import { NextResponse } from 'next/server'
import bcrypt from 'bcryptjs'
import { prisma } from '@/lib/db'

export const dynamic = 'force-dynamic'

// Public signup creates standard (non-admin) users only. Admin access is role-gated.
export async function POST(req: Request) {
  try {
    const body = await req.json().catch(() => ({}))
    const email = String(body?.email ?? '').trim().toLowerCase()
    const password = String(body?.password ?? '')
    const name = body?.name ? String(body.name) : null
    if (!email || !/^\S+@\S+\.\S+$/.test(email)) return NextResponse.json({ error: 'Valid email required' }, { status: 400 })
    if (password.length < 6) return NextResponse.json({ error: 'Password must be at least 6 characters' }, { status: 400 })
    const existing = await prisma.user.findUnique({ where: { email } })
    if (existing) return NextResponse.json({ error: 'Account already exists' }, { status: 409 })
    const user = await prisma.user.create({
      data: { email, name, password: await bcrypt.hash(password, 10), role: 'user' },
    })
    return NextResponse.json({ id: user.id, email: user.email }, { status: 201 })
  } catch (e) {
    console.error('signup failed', e)
    return NextResponse.json({ error: 'Signup failed' }, { status: 500 })
  }
}

'use client'

import { ReactNode, useEffect, useState } from 'react'

/** True only after the component has mounted on the client. Use to gate browser-only values. */
export function useMounted(): boolean {
  const [mounted, setMounted] = useState(false)
  useEffect(() => setMounted(true), [])
  return mounted
}

/**
 * Renders children only after client mount, so SSR output stays deterministic.
 * Use for anything that differs between server and client (window/localStorage reads,
 * user timezone/locale values, random ids, live clocks, third-party widgets).
 * Pass a `fallback` matching the final size to avoid layout shift.
 */
export function ClientOnly({ children, fallback = null }: { children: ReactNode; fallback?: ReactNode }) {
  const mounted = useMounted()
  return <>{mounted ? children : fallback}</>
}

import { NextResponse } from 'next/server'
import { prisma } from '@/lib/db'
import { requireAdmin } from '@/auth'
import { resolveImage } from '@/lib/content'

export const dynamic = 'force-dynamic'

export async function GET() {
  if (!(await requireAdmin())) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  const rows = await prisma.game.findMany({ orderBy: { order: 'asc' } })
  const games = await Promise.all(
    rows.map(async (g) => ({ ...g, imageUrl: await resolveImage(g.imagePath, g.imageIsPublic) }))
  )
  return NextResponse.json({ games })
}

export async function POST(req: Request) {
  if (!(await requireAdmin())) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  const body = await req.json().catch(() => ({}))
  const last = await prisma.game.findFirst({ orderBy: { order: 'desc' } })

  // Duplicate an existing unit (copy lands hidden at the end of the list)
  if (typeof body?.duplicateOf === 'string') {
    const src = await prisma.game.findUnique({ where: { id: body.duplicateOf } })
    if (!src) return NextResponse.json({ error: 'Unit not found' }, { status: 404 })
    const game = await prisma.game.create({
      data: {
        slug: `${src.slug}-copy-${Date.now().toString(36)}`,
        title: `${src.title} (COPY)`,
        subtitle: src.subtitle,
        description: src.description,
        deepDive: src.deepDive,
        format: src.format,
        launchLink: src.launchLink,
        linkTarget: src.linkTarget,
        status: src.status,
        featured: false,
        visible: false,
        locked: src.locked,
        imagePath: src.imagePath,
        imageIsPublic: src.imageIsPublic,
        order: (last?.order ?? 0) + 1,
      },
    })
    return NextResponse.json({ game }, { status: 201 })
  }

  const title = String(body?.title ?? 'NEW MACHINE').trim() || 'NEW MACHINE'
  const game = await prisma.game.create({
    data: {
      slug: `game-${Date.now().toString(36)}`,
      title,
      subtitle: String(body?.subtitle ?? ''),
      format: body?.format === 'app' ? 'app' : 'game',
      launchLink: '#',
      status: 'coming_soon',
      featured: false,
      visible: false,
      locked: true, // new units ship behind the paywall; owner frees them in admin
      order: (last?.order ?? 0) + 1,
    },
  })
  return NextResponse.json({ game }, { status: 201 })
}

import { heroKey, isOn, type HeroPage, type SiteContentMap } from './site-defaults'

export type HeroBg = 'banner' | 'gradient' | 'image' | 'solid' | 'none'
export type HeroAlign = 'left' | 'center' | 'right'
export type HeroHeight = 'auto' | 'compact' | 'medium' | 'tall' | 'full'

export type HeroConfig = {
  page: HeroPage
  show: boolean
  title: string
  subtitle: string
  bg: HeroBg
  /** resolved image URL for bg 'image' (null = falls back to the banner gradient) */
  imageUrl: string | null
  /** CSS background for gradient / solid / none */
  background: string
  titleColor: string
  textColor: string
  accentColor: string
  align: HeroAlign
  height: HeroHeight
  cta: { label: string; href: string; external: boolean } | null
  animate: boolean
  /** home only: the first full stop in the title is the control-room trigger */
  adminTrigger: boolean
}

const HEX = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i
export const cleanColor = (v: string | undefined) => (v && HEX.test(v.trim()) ? v.trim() : '')

const pick = <T extends string>(v: string, allowed: readonly T[], fallback: T): T =>
  (allowed as readonly string[]).includes(v) ? (v as T) : fallback

export const HERO_HEIGHTS: Record<HeroHeight, string | undefined> = {
  auto: undefined,
  compact: 'clamp(220px, 32svh, 360px)',
  medium: 'clamp(320px, 48svh, 540px)',
  tall: 'clamp(420px, 70svh, 780px)',
  full: 'calc(100svh - 56px - env(safe-area-inset-top))',
}

export const HERO_GRADIENTS: Record<string, { label: string; css: (from: string, to: string) => string }> = {
  banner: { label: 'Banner — lit pocket to black', css: () => 'var(--bv-gradient-banner)' },
  panel: { label: 'Panel — steel slab', css: () => 'var(--bv-gradient-panel)' },
  ember: {
    label: 'Ember — gold glow over banner',
    css: () => 'radial-gradient(90% 120% at 15% 0%, rgb(var(--bv-primary-rgb) / 0.22), transparent 60%), var(--bv-gradient-banner)',
  },
  custom: {
    label: 'Custom — two colours',
    css: (from, to) => `linear-gradient(135deg, ${from || 'var(--bv-surface-3)'} 0%, ${to || 'var(--bv-bg)'} 100%)`,
  },
}

function safeHref(v: string) {
  const s = v.trim()
  if (s.startsWith('/') && !s.startsWith('//')) return { href: s, external: false }
  if (/^https?:\/\//i.test(s) || /^mailto:/i.test(s)) return { href: s, external: true }
  return null
}

/** Pure resolver (safe on client and server). imageUrl is resolved by the caller. */
export function resolveHero(content: SiteContentMap, page: HeroPage, imageUrl: string | null): HeroConfig {
  const get = (p: Parameters<typeof heroKey>[1]) => (content[heroKey(page, p)] ?? '').toString()
  const bg = pick<HeroBg>(get('bg'), ['banner', 'gradient', 'image', 'solid', 'none'], 'gradient')
  const gradKey = HERO_GRADIENTS[get('gradient')] ? get('gradient') : 'banner'
  const from = cleanColor(get('gradFrom'))
  const to = cleanColor(get('gradTo'))
  let background = HERO_GRADIENTS[gradKey].css(from, to)
  if (bg === 'solid') background = cleanColor(get('solid')) || 'var(--bv-surface)'
  if (bg === 'none') background = 'transparent'

  let title = get('title').trim()
  // The home trigger must always exist: off-banner home titles need a full stop.
  if (page === 'home' && bg !== 'banner' && !title.includes('.')) title = 'GREY.FILTER'

  const href = safeHref(get('ctaHref'))
  const label = get('ctaLabel').trim()

  return {
    page,
    show: page === 'home' ? true : isOn(get('show')),
    title,
    subtitle: get('subtitle').trim(),
    bg,
    imageUrl: bg === 'image' ? imageUrl : null,
    background,
    titleColor: cleanColor(get('titleColor')),
    textColor: cleanColor(get('textColor')),
    accentColor: cleanColor(get('accentColor')),
    align: pick<HeroAlign>(get('align'), ['left', 'center', 'right'], 'left'),
    height: pick<HeroHeight>(get('height'), ['auto', 'compact', 'medium', 'tall', 'full'], 'compact'),
    cta: label && href ? { label, ...href } : null,
    animate: isOn(get('animate')),
    adminTrigger: page === 'home',
  }
}

HANDOVER PROMPT №2 — THE 3K OVERLAY LOCK + VIP SHELL ("PHASE: MANAGED DECLINE")
Project: BMF:3K — "Manage Decline" web app (managedecline.abacusai.app)
SEQUENCING: build this AFTER the Pitch Deck update handover is complete. Do not
run both changes simultaneously or restyle the deck to match the lock — the lock
joins the app's established language, not the other way round.

WHAT YOU'RE BUILDING
A full-screen, in-world lock that gates the app's VIP tab. It is styled as the
Manager's own instrument panel — stepping into the lock feels like standing
inside the 3K Overlay. The user types the password BASELINE (case-insensitive);
on success the panel runs an unlock dismantle sequence and reveals the VIP page
beneath: the "PHASE: MANAGED DECLINE" production-planning shell.

SOURCE MATERIAL — THE ATTACHED VISUAL REFERENCE
The member has attached an HTML/CSS/JS visual reference: an instrument-panel
chassis with a Green Band gauge and a key phrase verification meter, and a
placeholder page behind it. Treat it as the visual BASE — keep its chassis
layout, proportions and instrument feel — but it is a reference, not final
code. Rework it per the spec below. Where reference and spec conflict, SPEC WINS.

REWORK LIST (required changes to the reference)
1. PALETTE. Bring every surface, readout, lamp and line into lime #B8F026 /
   magenta #E040B0 on near-black. The reference's amber/yellow tones are
   removed everywhere. Flat colour only — no gradients.
2. DECORATIVE READOUTS. The reference's 42% gauge, "LEDGER SYNC" and
   "FILTER STATE" panels currently do nothing. For each one: give it a real
   job in the lock interaction, or remove it. The only jobs allowed:
   - KEY PHRASE VERIFICATION meter — advances 0–100% with each keystroke.
     This is the core instrument; it stays.
   - GREEN BAND gauge — idles steady inside the green band; pins to full
     lime on unlock; snaps out of band on rejection.
   - Status lamp — standby, flips magenta on rejection, lime on unlock.
   Nothing else survives. No invented instruments, no fake percentages.
3. MOBILE. The instruments are not decoration to be hidden on small screens.
   Reflow the panel so the verification meter, Green Band gauge and status
   lamp all remain on screen at phone width. Scale and stack — never delete.
4. BEHIND THE LOCK. Replace the reference's generic placeholder with the
   VIP shell specified below.

THE VIP SHELL — "PHASE: MANAGED DECLINE"
Behind the lock, build the VIP page as a titled shell:
- Header: "PHASE: MANAGED DECLINE"
- Sub-label: "Production planning — for the filmmaking team"
- Three clearly commented, labelled content slots, rendered as empty
  Overlay-styled frames ready to receive content: BUDGET / NEXT STEPS TO
  SUCCESS / DEPENDENCY ECONOMY.
The real content arrives in a later handover. Do not write, invent or
lorem-ipsum any of it. An empty, beautifully framed shell is the deliverable.

LOCK STATES
1. LOCKED (default): VIP tab opens the lock, never the page. Centre: a chunky
   mechanical input styled as an instrument readout — blinking block cursor,
   fixed-width type. Each keystroke advances the verification meter. Idle
   instrumentation is powered on but subtle (Green Band steady, scanline
   drift, standby lamp). No looping distraction.
2. REJECTED (wrong password): meter snaps to zero, lamp flips magenta,
   readout prints "MISMATCH — RE-ENTER KEY PHRASE". Input clears, focus
   retained. No browser alerts, no cartoon shake.
3. UNLOCKING (correct): meter holds 100%, lamp goes lime, readout prints
   "GREEN BAND CONFIRMED — ACCESS". Then the dismantle sequence plays once:
   scanline wipe top-to-bottom, meters pin to zero, chassis panels slide and
   rotate away like a mechanism opening — 1.5–2.5s, one-shot. The VIP shell
   is already rendered beneath; the overlay lifts to reveal it (never a
   blank flash).

TECHNICAL
- Password lives in ONE clearly-commented constant: VIP_PASSWORD = 'BASELINE'.
  Comparison is case-insensitive and trimmed. Changing it touches one line.
- On unlock, persist in sessionStorage — navigating the app does not re-lock.
  Nothing beyond the session.
- Keyboard: autofocus the input, Enter submits, Escape clears. Visible
  :focus-visible states throughout.
- prefers-reduced-motion: skip the dismantle, simple crossfade instead.
- Mobile-first: the lock stays fully usable and dramatic at phone width.
- Honesty note in your handover summary (not in UI copy): this is a
  presentational gate — a client-side check hides the page from casual
  visitors only; true confidentiality requires server-side access control.
  Never describe the lock as "secure" in any user-facing copy.
- A shared 3K Overlay sprite-sheet asset kit arrives in a later handover:
  build with CSS/SVG in the app's current visual language and leave clearly
  commented asset slots so the sheets can drop in without rework.

DO NOT
- No amber/yellow/orange anywhere in the lock UI. Orange belongs to in-story
  fire imagery only, and the damage sprite sheet is NOT part of this handover.
- No window.prompt/alert/confirm or any default browser dialog.
- No invented lore, readout names, or decorative fake data.
- No lorem ipsum in the VIP shell.
- No changes to the public pages: four-pane layout, pitch deck, music
  rotation, and the Hero placeholder stay exactly as they are.  <!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>BMF:3K — 3K Overlay Lock</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <!-- Monospace readout face + chunky display face -->
  <link href="https://fonts.googleapis.com/css2?family=Share+Tech+Mono&family=Orbitron:wght@700;900&display=swap" rel="stylesheet" />
  <link rel="stylesheet" href="overlay-lock.css" />
</head>
<body>
  <!-- ============================================================
       3K OVERLAY LOCK
       Presentational gate only. Client-side check hides the VIP
       page from casual visitors. True confidentiality requires
       server-side access control. Do not describe this as "secure"
       in any user-facing copy.
       ============================================================ -->

  <div id="app">
    <!-- VIP content lives behind the overlay. Always in the DOM so
         the unlock sequence can lift the overlay without a flash. -->
    <main id="vip-page" class="vip-page" aria-hidden="true">
      <div class="vip-placeholder">
        <div class="vip-stamp">VIP — PRODUCTION PLANNING</div>
        <p class="vip-note">(content pending handover)</p>
        <p class="vip-hint">Budget · Schedule · Next steps to production</p>
      </div>
    </main>

    <!-- The lock itself — full-screen instrument panel -->
    <div id="overlay-lock" class="overlay-lock" role="dialog" aria-modal="true" aria-labelledby="lock-title">
      <!-- Scanline layer (subtle idle drift) -->
      <div class="scanlines" aria-hidden="true"></div>

      <!-- Outer bezel / chassis -->
      <div class="chassis">
        <!-- Top status bar -->
        <header class="status-bar">
          <span class="stamp">3K OVERLAY</span>
          <span class="stamp status-lamp" id="status-lamp" data-state="standby">STANDBY</span>
          <span class="stamp">FILING CABINET // ACTIVE</span>
        </header>

        <!-- Title block -->
        <h1 id="lock-title" class="lock-title">KEY PHRASE VERIFICATION</h1>

        <!-- Main instrument cluster -->
        <div class="instrument-cluster">
          <!-- Left: Green Band gauge -->
          <div class="gauge-panel">
            <div class="gauge-label">GREEN BAND</div>
            <div class="gauge-body">
              <div class="gauge-track">
                <div class="gauge-fill" id="green-band-fill"></div>
                <div class="gauge-marker"></div>
              </div>
              <div class="gauge-readout" id="green-band-readout">42%</div>
            </div>
            <div class="caliper-marks" aria-hidden="true"></div>
          </div>

          <!-- Centre: Input + verification meter -->
          <div class="input-panel">
            <label for="key-phrase" class="input-label">ENTER KEY PHRASE</label>
            <div class="readout-frame">
              <input
                type="text"
                id="key-phrase"
                class="key-phrase-input"
                autocomplete="off"
                autocorrect="off"
                autocapitalize="off"
                spellcheck="false"
                maxlength="32"
                aria-describedby="readout-message"
              />
              <span class="block-cursor" aria-hidden="true"></span>
            </div>

            <!-- KEY PHRASE VERIFICATION meter -->
            <div class="verify-meter">
              <div class="verify-label">KEY PHRASE VERIFICATION</div>
              <div class="verify-track">
                <div class="verify-fill" id="verify-fill"></div>
              </div>
              <div class="verify-pct" id="verify-pct">0%</div>
            </div>

            <!-- Message readout -->
            <div class="message-readout" id="readout-message" aria-live="polite">
              AWAITING INPUT
            </div>
          </div>

          <!-- Right: secondary instruments -->
          <div class="side-panel">
            <div class="meter-block">
              <div class="meter-label">LEDGER SYNC</div>
              <div class="meter-bar"><div class="meter-bar-fill idle"></div></div>
            </div>
            <div class="meter-block">
              <div class="meter-label">FILTER STATE</div>
              <div class="meter-bar"><div class="meter-bar-fill idle" style="width:78%"></div></div>
            </div>
            <div class="file-tab">TAB // VIP ACCESS</div>
            <div class="file-tab muted">TAB // PUBLIC</div>
          </div>
        </div>

        <!-- Bottom bezel labels -->
        <footer class="bezel-footer">
          <span class="stamp">ANALOGUE FILTER v3K</span>
          <span class="stamp">MANAGER INSTRUMENT PANEL</span>
          <span class="stamp">NO ORANGE // NO GLOW</span>
        </footer>
      </div>
    </div>
  </div>

  <script src="overlay-lock.js"></script>
</body>
</html>  /* ============================================================
   3K OVERLAY LOCK — Visual Spec
   Palette: lime #B8F026 (primary), magenta #E040B0 (status)
   Ground: near-black. Flat colour only. No gradients.
   No amber / yellow / orange anywhere in the lock UI.
   Idiom: 1950s X-ray instrument × 1969–73 retro-futurist TV prop.
   ============================================================ */

:root {
  --lime: #B8F026;
  --magenta: #E040B0;
  --ground: #0a0a0a;
  --panel: #111111;
  --bevel-light: #1e1e1e;
  --bevel-dark: #050505;
  --muted: #3a3a3a;
  --readout-bg: #0d0d0d;
  --font-mono: "Share Tech Mono", "Courier New", monospace;
  --font-display: "Orbitron", "Arial Black", sans-serif;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html, body {
  height: 100%;
  background: var(--ground);
  color: var(--lime);
  font-family: var(--font-mono);
  overflow: hidden;
}

/* ---------- App shell ---------- */
#app {
  position: relative;
  width: 100%;
  height: 100%;
  min-height: 100dvh;
}

/* ---------- VIP page (always rendered beneath) ---------- */
.vip-page {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--ground);
  z-index: 1;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s ease;
}

.vip-page.revealed {
  opacity: 1;
  pointer-events: auto;
}

.vip-placeholder {
  border: 3px solid var(--lime);
  padding: 2.5rem 3rem;
  text-align: center;
  max-width: 90vw;
}

.vip-stamp {
  font-family: var(--font-display);
  font-weight: 900;
  font-size: clamp(1.1rem, 4vw, 1.6rem);
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--lime);
  margin-bottom: 1rem;
}

.vip-note {
  font-size: 0.95rem;
  letter-spacing: 0.12em;
  color: var(--magenta);
  margin-bottom: 0.75rem;
}

.vip-hint {
  font-size: 0.8rem;
  letter-spacing: 0.1em;
  color: var(--muted);
  text-transform: uppercase;
}

/* ---------- Overlay Lock ---------- */
.overlay-lock {
  position: absolute;
  inset: 0;
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--ground);
  transition: opacity 0.5s ease, transform 0.5s ease;
}

.overlay-lock.unlocking {
  pointer-events: none;
}

.overlay-lock.dismantled {
  opacity: 0;
  transform: scale(1.02);
  visibility: hidden;
}

/* Subtle scanline drift */
.scanlines {
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    to bottom,
    transparent 0,
    transparent 3px,
    rgba(184, 240, 38, 0.015) 3px,
    rgba(184, 240, 38, 0.015) 4px
  );
  pointer-events: none;
  animation: scan-drift 12s linear infinite;
  z-index: 20;
}

@keyframes scan-drift {
  0%   { background-position: 0 0; }
  100% { background-position: 0 40px; }
}

@media (prefers-reduced-motion: reduce) {
  .scanlines {
    animation: none;
  }
}

/* Chassis — the physical instrument body */
.chassis {
  position: relative;
  width: min(920px, 96vw);
  border: 4px solid var(--lime);
  background: var(--panel);
  padding: 1.25rem 1.5rem 1rem;
  box-shadow:
    inset 0 0 0 2px var(--bevel-dark),
    0 0 0 1px var(--bevel-light);
  z-index: 5;
}

/* Bevel corners via pseudo */
.chassis::before,
.chassis::after {
  content: "";
  position: absolute;
  width: 18px;
  height: 18px;
  border: 2px solid var(--lime);
  pointer-events: none;
}
.chassis::before {
  top: 6px;
  left: 6px;
  border-right: none;
  border-bottom: none;
}
.chassis::after {
  bottom: 6px;
  right: 6px;
  border-left: none;
  border-top: none;
}

/* Status bar */
.status-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 0.75rem;
  margin-bottom: 1.25rem;
  padding-bottom: 0.6rem;
  border-bottom: 2px solid var(--muted);
  flex-wrap: wrap;
}

.stamp {
  font-size: 0.7rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--lime);
  white-space: nowrap;
}

.status-lamp {
  padding: 0.2rem 0.55rem;
  border: 1px solid var(--lime);
  background: var(--readout-bg);
  transition: color 0.15s, border-color 0.15s, background 0.15s;
}

.status-lamp[data-state="standby"] {
  color: var(--lime);
  border-color: var(--lime);
}

.status-lamp[data-state="reject"] {
  color: var(--magenta);
  border-color: var(--magenta);
  background: #1a0a14;
}

.status-lamp[data-state="confirm"] {
  color: var(--lime);
  border-color: var(--lime);
  background: #0f1a05;
  box-shadow: 0 0 0 1px var(--lime);
}

/* Title */
.lock-title {
  font-family: var(--font-display);
  font-weight: 900;
  font-size: clamp(1rem, 3.5vw, 1.45rem);
  letter-spacing: 0.22em;
  text-transform: uppercase;
  text-align: center;
  margin-bottom: 1.5rem;
  color: var(--lime);
}

/* Instrument cluster — three columns */
.instrument-cluster {
  display: grid;
  grid-template-columns: 1fr 1.6fr 1fr;
  gap: 1.25rem;
  align-items: start;
}

@media (max-width: 720px) {
  .instrument-cluster {
    grid-template-columns: 1fr;
    gap: 1rem;
  }
  .side-panel {
    display: none; /* collapse secondary instruments on phone */
  }
}

/* ---- Left: Green Band gauge ---- */
.gauge-panel {
  border: 2px solid var(--muted);
  padding: 0.75rem;
  background: var(--readout-bg);
}

.gauge-label {
  font-size: 0.65rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  margin-bottom: 0.5rem;
  color: var(--lime);
}

.gauge-body {
  display: flex;
  align-items: center;
  gap: 0.6rem;
}

.gauge-track {
  flex: 1;
  height: 14px;
  border: 1px solid var(--lime);
  position: relative;
  background: var(--ground);
}

.gauge-fill {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 42%;
  background: var(--lime);
  transition: width 0.4s ease;
}

.gauge-marker {
  position: absolute;
  left: 50%;
  top: -3px;
  bottom: -3px;
  width: 2px;
  background: var(--magenta);
  transform: translateX(-50%);
}

.gauge-readout {
  font-size: 0.85rem;
  letter-spacing: 0.08em;
  min-width: 2.5rem;
  text-align: right;
}

.caliper-marks {
  height: 8px;
  margin-top: 0.35rem;
  background: repeating-linear-gradient(
    to right,
    var(--muted) 0,
    var(--muted) 1px,
    transparent 1px,
    transparent 8px
  );
}

/* ---- Centre: Input panel ---- */
.input-panel {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
}

.input-label {
  font-size: 0.7rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--lime);
}

.readout-frame {
  position: relative;
  border: 3px solid var(--lime);
  background: var(--readout-bg);
  padding: 0.7rem 0.9rem;
  min-height: 3rem;
  display: flex;
  align-items: center;
}

.key-phrase-input {
  flex: 1;
  background: transparent;
  border: none;
  outline: none;
  color: var(--lime);
  font-family: var(--font-mono);
  font-size: 1.15rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  caret-color: transparent; /* we use the block cursor */
  width: 100%;
}

.key-phrase-input:focus-visible {
  outline: 2px solid var(--magenta);
  outline-offset: 2px;
}

/* Blinking block cursor */
.block-cursor {
  display: inline-block;
  width: 0.65em;
  height: 1.15em;
  background: var(--lime);
  margin-left: 2px;
  animation: blink 1.05s steps(1) infinite;
  flex-shrink: 0;
}

@keyframes blink {
  0%, 50% { opacity: 1; }
  51%, 100% { opacity: 0; }
}

@media (prefers-reduced-motion: reduce) {
  .block-cursor {
    animation: none;
    opacity: 1;
  }
}

/* Verification meter */
.verify-meter {
  display: grid;
  grid-template-columns: 1fr auto;
  grid-template-rows: auto auto;
  gap: 0.3rem 0.6rem;
  align-items: center;
}

.verify-label {
  grid-column: 1 / -1;
  font-size: 0.6rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--muted);
}

.verify-track {
  height: 10px;
  border: 1px solid var(--lime);
  background: var(--ground);
  position: relative;
}

.verify-fill {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 0%;
  background: var(--lime);
  transition: width 0.08s linear;
}

.verify-fill.reject {
  background: var(--magenta);
  transition: width 0.2s ease;
}

.verify-pct {
  font-size: 0.8rem;
  letter-spacing: 0.08em;
  min-width: 2.8rem;
  text-align: right;
}

/* Message readout */
.message-readout {
  border: 1px solid var(--muted);
  background: var(--readout-bg);
  padding: 0.55rem 0.75rem;
  font-size: 0.8rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  min-height: 2.4rem;
  display: flex;
  align-items: center;
  color: var(--lime);
  transition: color 0.15s, border-color 0.15s;
}

.message-readout.reject {
  color: var(--magenta);
  border-color: var(--magenta);
}

.message-readout.confirm {
  color: var(--lime);
  border-color: var(--lime);
}

/* ---- Right: side instruments ---- */
.side-panel {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.meter-block {
  border: 1px solid var(--muted);
  padding: 0.5rem 0.6rem;
  background: var(--readout-bg);
}

.meter-label {
  font-size: 0.6rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  margin-bottom: 0.35rem;
  color: var(--muted);
}

.meter-bar {
  height: 8px;
  border: 1px solid var(--lime);
  background: var(--ground);
  position: relative;
}

.meter-bar-fill {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  background: var(--lime);
}

.meter-bar-fill.idle {
  width: 62%;
  animation: idle-pulse 4s ease-in-out infinite;
}

@keyframes idle-pulse {
  0%, 100% { opacity: 0.7; }
  50% { opacity: 1; }
}

@media (prefers-reduced-motion: reduce) {
  .meter-bar-fill.idle {
    animation: none;
  }
}

.file-tab {
  border: 2px solid var(--lime);
  border-bottom-width: 4px;
  padding: 0.45rem 0.6rem;
  font-size: 0.65rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  text-align: center;
  background: var(--panel);
}

.file-tab.muted {
  border-color: var(--muted);
  color: var(--muted);
}

/* Footer */
.bezel-footer {
  display: flex;
  justify-content: space-between;
  gap: 0.75rem;
  margin-top: 1.25rem;
  padding-top: 0.6rem;
  border-top: 2px solid var(--muted);
  flex-wrap: wrap;
}

.bezel-footer .stamp {
  font-size: 0.6rem;
  color: var(--muted);
}

/* ---------- Unlock sequence panels ---------- */
.overlay-lock.unlocking .chassis {
  animation: chassis-open 1.8s cubic-bezier(0.4, 0, 0.2, 1) forwards;
}

@keyframes chassis-open {
  0% {
    opacity: 1;
    transform: scale(1) rotate(0deg);
  }
  40% {
    opacity: 1;
    transform: scale(1.01) rotate(0.3deg);
  }
  100% {
    opacity: 0;
    transform: scale(0.96) rotate(-1deg) translateY(-8%);
  }
}

/* Scanline wipe during unlock */
.overlay-lock.unlocking .scanlines {
  animation: wipe-down 1.6s ease-in forwards;
}

@keyframes wipe-down {
  0% {
    clip-path: inset(0 0 0 0);
    opacity: 1;
  }
  100% {
    clip-path: inset(100% 0 0 0);
    opacity: 0;
  }
}

/* Reduced-motion: simple crossfade */
@media (prefers-reduced-motion: reduce) {
  .overlay-lock.unlocking .chassis {
    animation: none;
    transition: opacity 0.45s ease;
    opacity: 0;
  }
  .overlay-lock.unlocking .scanlines {
    animation: none;
    opacity: 0;
  }
}

/* Focus-visible for keyboard users */
.key-phrase-input:focus-visible,
button:focus-visible {
  outline: 2px solid var(--magenta);
  outline-offset: 3px;
}  /**
