 * Change VIP_PASSWORD and nothing else.
 */

// ============================================================
// CONFIG — touch only this line to change the password
const VIP_PASSWORD = 'BASELINE';
// ============================================================

const STORAGE_KEY = 'bmf3k_vip_unlocked';

(function init() {
  const overlay   = document.getElementById('overlay-lock');
  const vipPage   = document.getElementById('vip-page');
  const input     = document.getElementById('key-phrase');
  const verifyFill = document.getElementById('verify-fill');
  const verifyPct  = document.getElementById('verify-pct');
  const message    = document.getElementById('readout-message');
  const statusLamp = document.getElementById('status-lamp');
  const greenFill  = document.getElementById('green-band-fill');
  const greenRead  = document.getElementById('green-band-readout');

  // Persist across navigation within the session
  if (sessionStorage.getItem(STORAGE_KEY) === '1') {
    revealVip(true);
    return;
  }

  // Autofocus
  input.focus();

  // Idle green-band pulse (subtle, not looping distraction)
  let greenVal = 42;
  let greenDir = 1;
  const greenInterval = setInterval(() => {
    if (overlay.classList.contains('unlocking') || overlay.classList.contains('dismantled')) {
      clearInterval(greenInterval);
      return;
    }
    greenVal += greenDir * 0.4;
    if (greenVal >= 48) greenDir = -1;
    if (greenVal <= 38) greenDir = 1;
    greenFill.style.width = greenVal + '%';
    greenRead.textContent = Math.round(greenVal) + '%';
  }, 180);

  // Keystroke advances verification meter
  input.addEventListener('input', () => {
    const len = input.value.length;
    // Rough progress toward the expected length (BASELINE = 8)
    const target = VIP_PASSWORD.length;
    const pct = Math.min(100, Math.round((len / target) * 100));
    setMeter(pct);
    // Keep status in standby while typing
    if (statusLamp.dataset.state !== 'standby') {
      setStatus('standby', 'STANDBY');
      message.textContent = 'AWAITING INPUT';
      message.classList.remove('reject', 'confirm');
    }
  });

  // Enter submits
  input.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      attemptUnlock();
    }
    if (e.key === 'Escape') {
      e.preventDefault();
      clearInput();
    }
  });

  function attemptUnlock() {
    const entered = input.value.trim().toUpperCase();
    const expected = VIP_PASSWORD.trim().toUpperCase();

    if (entered === expected) {
      // SUCCESS
      setMeter(100);
      setStatus('confirm', 'GREEN BAND');
      message.textContent = 'GREEN BAND CONFIRMED — ACCESS';
      message.classList.remove('reject');
      message.classList.add('confirm');
      verifyFill.classList.remove('reject');

      // Pin green band
      greenFill.style.width = '50%';
      greenRead.textContent = '50%';

      // Run unlock sequence
      startUnlockSequence();
    } else {
      // REJECT
      setMeter(0);
      setStatus('reject', 'MISMATCH');
      message.textContent = 'MISMATCH — RE-ENTER KEY PHRASE';
      message.classList.remove('confirm');
      message.classList.add('reject');
      verifyFill.classList.add('reject');

      // Clear input, retain focus
      input.value = '';
      input.focus();

      // Brief visual hold then return to standby
      setTimeout(() => {
        if (statusLamp.dataset.state === 'reject') {
          setStatus('standby', 'STANDBY');
          message.textContent = 'AWAITING INPUT';
          message.classList.remove('reject');
          verifyFill.classList.remove('reject');
        }
      }, 1600);
    }
  }

  function startUnlockSequence() {
    const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    overlay.classList.add('unlocking');

    // Meters pin to zero during dismantle
    setTimeout(() => {
      setMeter(0);
      greenFill.style.width = '0%';
      greenRead.textContent = '0%';
    }, prefersReduced ? 0 : 400);

    const duration = prefersReduced ? 450 : 1900;

    setTimeout(() => {
      sessionStorage.setItem(STORAGE_KEY, '1');
      revealVip(false);
      overlay.classList.add('dismantled');
      // Clean up after transition
      setTimeout(() => {
        overlay.style.display = 'none';
      }, 500);
    }, duration);
  }

  function revealVip(instant) {
    vipPage.classList.add('revealed');
    vipPage.setAttribute('aria-hidden', 'false');
    if (instant) {
      overlay.style.display = 'none';
      overlay.classList.add('dismantled');
    }
  }

  function setMeter(pct) {
    verifyFill.style.width = pct + '%';
    verifyPct.textContent = pct + '%';
  }

  function setStatus(state, label) {
    statusLamp.dataset.state = state;
    statusLamp.textContent = label;
  }

  function clearInput() {
    input.value = '';
    setMeter(0);
    setStatus('standby', 'STANDBY');
    message.textContent = 'AWAITING INPUT';
    message.classList.remove('reject', 'confirm');
    verifyFill.classList.remove('reject');
    input.focus();
  }
})();

