  const philosophy = game?.philosophy || 'shepherd';
  const ending = ENDINGS[philosophy] ?? ENDINGS.shepherd;

  // Phase transitions
  useEffect(() => {
    playThud();
    const t1 = setTimeout(() => setPhase('inversion'), 4000);
    return () => clearTimeout(t1);
  }, []);

  const advanceDirective = useCallback(() => {
    audioManager.playSFX('nav');
    const next = directiveIdx + 1;
    if (next >= DIRECTIVES.length) {
      // All directives complete — transition to ending
      audioManager.playSFX('confirm');
      setHudStripped(100);
      setTimeout(() => setPhase('comic'), 1500);
    } else {
      setDirectiveIdx(next);
      setHudStripped(Math.round(((next + 1) / DIRECTIVES.length) * 100));
    }
  }, [directiveIdx]);

  // Comic viewer complete → transition to ending text
  const handleComicComplete = useCallback(() => {
    setPhase('ending');
    setTimeout(() => setPhase('credits'), 10000);
    setTimeout(() => setShowRestart(true), 16000);
  }, []);

  // How much HUD opacity remains (inverted strip)
  const hudOpacity = Math.max(0, 1 - hudStripped / 100);
  const plainOpacity = Math.min(1, hudStripped / 80);

  return (
    <div className="w-full h-full overflow-hidden relative" style={{ background: '#080807' }}>
      {/* CRT overlay that fades as HUD strips */}
      <div
        className="absolute inset-0 pointer-events-none z-50 transition-opacity duration-1000"
        style={{
          backgroundImage: 'repeating-linear-gradient(0deg, transparent 0px, transparent 2px, rgba(0,255,0,0.02) 2px, rgba(0,255,0,0.02) 4px)',
          mixBlendMode: 'screen',
          opacity: hudOpacity * 0.6,
        }}
      />

      {/* Scanline sweep */}
      {hudOpacity > 0.1 && (
        <motion.div
          className="absolute left-0 right-0 h-[2px] pointer-events-none z-50"
          style={{ background: `rgba(127,255,0,${0.08 * hudOpacity})` }}
          animate={{ top: ['-2%', '102%'] }}
          transition={{ duration: 6, repeat: Infinity, ease: 'linear' }}
        />
      )}

      {/* Status strip that dissolves */}
      <div
        className="absolute top-0 left-0 right-0 flex items-center justify-between px-4 py-2 z-40 transition-opacity duration-700"
        style={{ opacity: hudOpacity, borderBottom: '1px solid rgba(127,255,0,0.08)' }}
      >
        <span className="font-terminal text-[9px] text-[#9cff76]/40 tracking-[0.3em]">RECRUITMENT SYSTEM INVERTED</span>
        <div className="flex gap-3">
          <span className="text-[9px] font-terminal px-2 py-0.5 border border-[#9cff76]/20 text-[#9cff76]/40">
            HUD {Math.round(100 - hudStripped)}%
          </span>
          <span className="text-[9px] font-terminal px-2 py-0.5 border border-[#b87a96]/20 text-[#b87a96]/40">
            PRESSURE {((game?.heat ?? 0) * 10).toFixed(0)}
          </span>
        </div>
      </div>

      {/* PHASE: INTRO — reality flash */}
      <AnimatePresence>
        {phase === 'intro' && (
          <motion.div
            key="intro"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="absolute inset-0 z-30 flex items-center justify-center"
          >
            <motion.div
              animate={{ opacity: [0.2, 0.7, 0.2] }}
              transition={{ duration: 3, repeat: Infinity }}
              className="text-center"
            >
              <p className="font-terminal text-xs text-[#E8E8E8]/20 tracking-[0.4em] mb-3">SUBJECT: MANAGER</p>
              <p className="font-terminal text-sm text-[#9cff76]/30 tracking-[0.2em]">THE RECRUITMENT SYSTEM HAS INVERTED</p>
            </motion.div>
            {/* Brief reality flash */}
            <motion.div
              className="absolute inset-0 pointer-events-none"
              animate={{ opacity: [0, 0.15, 0, 0.25, 0] }}
              transition={{ duration: 3.5 }}
              style={{
                background: 'linear-gradient(180deg, #c8dc96 0%, #d4d0c8 50%, #c9c4b5 100%)',
                filter: 'saturate(0.5) brightness(0.9)',
              }}
            />
          </motion.div>
        )}
      </AnimatePresence>

      {/* PHASE: INVERSION — the interactive directive stack */}
      {phase === 'inversion' && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          className="absolute inset-0 z-20 flex flex-col md:flex-row"
        >
          {/* Left: Shutdown readout (Template: .finale-target + .shutdown-readout) */}
          <div className="w-full md:w-[340px] bg-[#1a1710] border-r border-[#7FFF00]/5 flex flex-col p-4 sm:p-6">
            <div className="flex-1 flex flex-col justify-center">
              <p className="font-terminal text-[9px] text-[#E8E8E8]/25 tracking-[0.3em] mb-2">SUBJECT: MANAGER</p>
              <h3 className="font-terminal text-xl mb-4" style={{ color: ending.color }}>
                Recruitment system inverted
              </h3>

              {/* Dissolution meter */}
              <div className="mb-4">
                <div className="flex justify-between text-[9px] font-terminal text-[#4a4a3a] mb-1">
                  <span>HUD DISSOLUTION</span>
                  <span>{hudStripped}%</span>
                </div>
                <div className="h-2 bg-[#1a1a1a] relative" style={{ borderRadius: '2px' }}>
                  <motion.div
                    className="absolute inset-y-0 left-0 transition-all duration-500"
                    style={{
                      width: `${hudStripped}%`,
                      backgroundColor: ending.color,
                      borderRadius: '2px',
                      opacity: 0.7,
                    }}
                  />
                </div>
              </div>

              <p className="text-[10px] font-typewriter leading-relaxed" style={{ color: `rgba(243,232,207,${0.2 + plainOpacity * 0.4})` }}>
                HUD elements strip away as directives become ordinary childhood instructions.
                {hudStripped > 50 && ' The labels are dissolving. What\'s underneath is just a bedroom.'}
                {hudStripped > 80 && ' There\'s no interface anymore. Just the carpet and the nightlight.'}
              </p>
            </div>

            {/* Stats that fade */}
            <div className="space-y-1 transition-opacity duration-500" style={{ opacity: hudOpacity }}>
              <div className="flex justify-between text-[9px] font-terminal">
                <span className="text-[#E8E8E8]/20">DAYS MANAGED</span>
                <span className="text-[#9cff76]/30">{game?.day ?? 1}</span>
              </div>
              <div className="flex justify-between text-[9px] font-terminal">
                <span className="text-[#E8E8E8]/20">CREW</span>
                <span className="text-[#9cff76]/30">{(game?.npcs ?? []).filter((n: any) => n?.recruited).length}/4</span>
              </div>
              <div className="flex justify-between text-[9px] font-terminal">
                <span className="text-[#E8E8E8]/20">HEAT</span>
                <span className="text-[#b87a96]/30">{(game?.heat ?? 0).toFixed(1)}</span>
              </div>
            </div>
          </div>

          {/* Right: Directive stack (Template: .directive-stack) */}
          <div className="flex-1 overflow-y-auto p-4 sm:p-6 flex flex-col justify-center">
            <div className="max-w-lg mx-auto w-full space-y-2">
              {DIRECTIVES.map((dir, idx) => {
                const isComplete = idx < directiveIdx + 1;
                const isCurrent = idx === directiveIdx + 1;
                const isFuture = idx > directiveIdx + 1;
                const isFinal = idx === DIRECTIVES.length - 1;
                // As HUD strips, show plain text instead of HUD text
                const showPlain = hudStripped > (idx / DIRECTIVES.length) * 100 + 15;

                return (
                  <motion.button
                    key={idx}
                    initial={{ opacity: 0, x: 20 }}
                    animate={{
                      opacity: isComplete ? 0.35 : isCurrent ? 1 : isFuture ? 0.15 : 0.5,
                      x: 0,
                    }}
                    transition={{ duration: 0.3, delay: idx * 0.08 }}
                    onClick={isCurrent ? advanceDirective : undefined}
                    disabled={!isCurrent}
                    className="w-full text-left px-4 py-3 transition-all"
                    style={{
                      border: `1px solid ${
                        isCurrent
                          ? (isFinal ? `${ending.color}60` : 'rgba(156,255,118,0.25)')
                          : isComplete
                          ? 'rgba(127,255,0,0.05)'
                          : 'rgba(127,255,0,0.03)'
                      }`,
                      borderRadius: '4px',
                      background: isCurrent
                        ? (isFinal ? `${ending.color}08` : 'rgba(156,255,118,0.04)')
                        : 'transparent',
                      cursor: isCurrent ? 'pointer' : 'default',
                    }}
                  >
                    {/* HUD label dissolves, plain label appears */}
                    <span
                      className="font-terminal text-xs tracking-wider block transition-opacity duration-500"
                      style={{
                        opacity: showPlain ? 0 : 1,
                        height: showPlain ? 0 : 'auto',
                        overflow: 'hidden',
                        color: isComplete ? '#4a4a3a' : isCurrent ? (isFinal ? ending.color : '#9cff76') : '#2a2a2a',
                        textDecoration: isComplete ? 'line-through' : 'none',
                      }}
                    >
                      {dir.hud}
                    </span>
                    <span
                      className="font-typewriter text-sm block transition-opacity duration-700"
                      style={{
                        opacity: showPlain ? 1 : 0,
                        height: showPlain ? 'auto' : 0,
                        overflow: 'hidden',
                        color: isComplete ? '#4a4a3a80' : isCurrent ? '#f3e8cf' : '#2a2a2a',
                      }}
                    >
                      {dir.plain}
                    </span>
                    {isComplete && (
                      <span className="text-[8px] text-[#4a4a3a] font-terminal">✓ COMPLETED</span>
                    )}
                  </motion.button>
                );
              })}

              {directiveIdx === -1 && (
                <motion.p
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  transition={{ delay: 0.5 }}
                  className="text-center text-[10px] text-[#9cff76]/30 font-terminal tracking-wider mt-4"
                >
                  CLICK THE FIRST DIRECTIVE TO BEGIN
                </motion.p>
              )}
            </div>
          </div>
        </motion.div>
      )}

      {/* PHASE: COMIC — ascension visual sequence */}
      {phase === 'comic' && (
        <ComicViewer
          panels={ASCENSION_PANELS}
          onComplete={handleComicComplete}
          sequenceLabel="THE LIGHTS GO OUT"
        />
      )}

      {/* PHASE: ENDING + CREDITS */}
      <AnimatePresence>
        {(phase === 'ending' || phase === 'credits') && (
          <motion.div
            key="ending"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            className="absolute inset-0 z-30 flex items-center justify-center p-6"
          >
            <div className="max-w-lg w-full text-center space-y-6">
              <motion.h1
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                className="font-creepy text-3xl sm:text-4xl"
                style={{ color: ending.color, textShadow: `0 0 20px ${ending.color}30` }}
              >
                {ending.title}
              </motion.h1>

              {phase === 'ending' && (
                <motion.p
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  transition={{ delay: 0.5 }}
                  className="font-typewriter text-sm text-[#E8E8E8]/45 leading-relaxed text-left"
                >
                  {ending.body}
                </motion.p>
              )}

              {phase === 'credits' && (
                <motion.div
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  className="space-y-6"
                >
                  <p className="font-typewriter text-xs text-[#E8E8E8]/25 italic">&ldquo;{ending.coda}&rdquo;</p>

                  <div className="border-t border-[#E8E8E8]/5 pt-5 space-y-1">
                    <p className="font-terminal text-xs text-[#4a4a3a]">DAYS MANAGED: {game?.day ?? 1}</p>
                    <p className="font-terminal text-xs text-[#4a4a3a]">CREW RECRUITED: {(game?.npcs ?? []).filter((n: any) => n?.recruited).length}/4</p>
                    <p className="font-terminal text-xs text-[#4a4a3a]">MISSIONS: {(game?.missions ?? []).filter((m: any) => m?.status === 'COMPLETED').length}</p>
                    <p className="font-terminal text-xs text-[#4a4a3a]">FINAL HEAT: {(game?.heat ?? 0).toFixed(1)}</p>
                  </div>

                  <div className="border-t border-[#E8E8E8]/5 pt-5 space-y-1">
                    <p className="font-terminal text-[10px] text-[#4a4a3a]/50">BUM A FAG - 3000</p>
                    <p className="font-terminal text-[10px] text-[#4a4a3a]/50">CREATIVE DIRECTION: WESLEY</p>
                    <p className="font-terminal text-[10px] text-[#4a4a3a]/50">LEAD DESIGN: THE AGENT</p>
                    <p className="font-typewriter text-[8px] text-[#4a4a3a]/30 mt-2 italic">&ldquo;It never slept. It never stopped. It understood the assignment.&rdquo;</p>
                    <p className="font-terminal text-[10px] text-[#4a4a3a]/50 mt-1">&copy; 3000 BAF3K HOLDINGS PTY LTD</p>
                  </div>
                </motion.div>
              )}

              {showRestart && (
                <motion.button
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  onClick={onRestart}
                  className="mt-4 font-terminal text-sm px-8 py-2 border border-[#7FFF00]/15 text-[#7FFF00]/30 hover:bg-[#7FFF00] hover:text-[#080808] transition-all active:scale-95 cursor-pointer"
                >
                  RETURN TO MENU
                </motion.button>
              )}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

/**
 * AudioManager v2.1 — Centralized audio control.
 *
 * Hub music rotation (menu-theme + after-hours), stash jingle,
 * room ambience, clipboard UI sounds, safety valve cue,
 * shrine audio, expedition event audio, pressure scaffold.
 *
 * Uses HTMLAudioElement for music + room ambience layers.
 * Delegates synth SFX to existing sound-effects.ts functions.
 *
 * Grey/Filter Dev Framework v2
 */

import {
  playClick,
  playChunkyPress,
  playLullabyChime,
  playSuccess,
  playError,
  playHover as sfxHover,
  isMuted,
} from '@/lib/sound-effects';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

type SfxName =
  | 'nav'
  | 'confirm'
  | 'error'
  | 'hover'
  | 'paper'
  | 'safety_valve'
  | 'lullaby'
  | 'click';

type RoomName = 'ops_centre_1' | 'ops_centre_2' | 'bedroom';
type MusicLayer = 'hub' | 'stash' | 'bedroom';

// Hub music rotation tracks
const HUB_TRACKS = [
  '/audio/menu-theme.mp3',
  '/audio/after-hours.mp3',
];

// Expedition event audio (rare, triggerable)
const EXPEDITION_AUDIO = [
  '/audio/voice-its-medical-v2.wav',
  '/audio/voice-stoners-v2.wav',
];

// ---------------------------------------------------------------------------
// Singleton
// ---------------------------------------------------------------------------

class AudioManager {
  private ctx: AudioContext | null = null;
  private master: GainNode | null = null;

  private music: Record<MusicLayer, HTMLAudioElement | null> = {
    hub: null,
    stash: null,
    bedroom: null,
  };

  private roomAmbience: Record<RoomName, HTMLAudioElement | null> = {
    ops_centre_1: null,
    ops_centre_2: null,
    bedroom: null,
  };

  private currentMusic: MusicLayer | null = null;
  private currentRoom: RoomName | null = null;

  // Hub track rotation index
  private hubTrackIndex = 0;

  // Shrine audio — plays once per click
  private shrineAudio: HTMLAudioElement | null = null;
  private shrinePlaying = false;

  // Expedition event audio — rare trigger guard
  private lastExpeditionAudioTime = 0;
  private expeditionCooldownMs = 45000; // 45s between expedition audio events

  // Jingle (short identifiable cue)
  private jingleAudio: HTMLAudioElement | null = null;

  pressure = 0.0;
  clarity = 1.0;

  // ------ Init ------

  init(): void {
    if (typeof window === 'undefined') return;
    if (this.ctx) return;

    try {
      this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
      this.master = this.ctx.createGain();
      this.master.gain.value = 1;
      this.master.connect(this.ctx.destination);
    } catch {
      // AudioContext unavailable
    }

    // MUSIC — hub does NOT loop natively; rotation handled via ended event
    this.music.hub = this.makeLoop(HUB_TRACKS[0], 0.65);
    if (this.music.hub) {
      this.music.hub.loop = false; // Override — rotation needs ended event
      this.music.hub.addEventListener('ended', () => this._rotateHubTrack());
    }
    this.music.stash = this.makeLoop('/audio/jingle.mp3', 0.0);
    this.music.bedroom = this.makeLoop(HUB_TRACKS[0], 0.0); // reuse until dedicated bedroom loop

    // ROOM AMBIENCE
    this.roomAmbience.ops_centre_1 = this.makeLoop('/audio/ops1-ambience.mp3', 0.0);
    this.roomAmbience.ops_centre_2 = this.makeLoop('/audio/ops2-ambience.mp3', 0.0);
    this.roomAmbience.bedroom = this.makeLoop('/audio/bedroom-ambience.mp3', 0.0);

    // SHRINE AUDIO
    try {
      this.shrineAudio = new Audio('/audio/voice-mummy-said-v2.wav');
      this.shrineAudio.preload = 'auto';
      this.shrineAudio.addEventListener('ended', () => { this.shrinePlaying = false; });
    } catch {}

    // JINGLE
    try {
      this.jingleAudio = new Audio('/audio/jingle.mp3');
      this.jingleAudio.preload = 'auto';
    } catch {}
  }

  private makeLoop(src: string, volume: number): HTMLAudioElement | null {
    if (typeof window === 'undefined') return null;
    try {
      const audio = new Audio(src);
      audio.loop = true;
      audio.preload = 'auto';
      audio.volume = volume;
      return audio;
    } catch {
      return null;
    }
  }

  // ------ Hub track rotation ------

  private _rotateHubTrack(): void {
    this.hubTrackIndex = (this.hubTrackIndex + 1) % HUB_TRACKS.length;
    const nextSrc = HUB_TRACKS[this.hubTrackIndex];
    if (this.music.hub) {
      this.music.hub.src = nextSrc;
      // Keep loop = false — ended event handles rotation
      if (this.currentMusic === 'hub') {
        this.music.hub.volume = 0.65;
        this.music.hub.play().catch(() => {});
      }
    }
  }

  // ------ Autoplay unlock ------

  async unlock(): Promise<void> {
    if (!this.ctx) this.init();
    if (this.ctx?.state === 'suspended') {
      try { await this.ctx.resume(); } catch {}
    }

    const all = [
      ...Object.values(this.music),
      ...Object.values(this.roomAmbience),
    ].filter(Boolean) as HTMLAudioElement[];

    await Promise.all(
      all.map(async (a) => {
        try {
          await a.play();
          a.pause();
          a.currentTime = 0;
        } catch {}
      })
    );
  }

  // ------ Fade utility ------

  private fade(audio: HTMLAudioElement | null, target: number, ms = 800): void {
    if (!audio) return;
    const start = audio.volume;
    const delta = target - start;
    const steps = 20;
    const stepMs = ms / steps;
    let i = 0;

    const tick = () => {
      i += 1;
      audio.volume = Math.max(0, Math.min(1, start + (delta * i) / steps));
      if (i < steps) {
        window.setTimeout(tick, stepMs);
      } else if (target === 0) {
        try { audio.pause(); } catch {}
      }
    };

    if (target > 0 && audio.paused) {
      audio.play().catch(() => {});
    }

    tick();
  }

  // ------ Pressure scaffold ------

  setPressure(value: number): void {
    this.pressure = Math.max(0, Math.min(1, value));
    this.clarity = 1 - this.pressure;
  }

  // ------ Room ambience ------

  setRoom(room: RoomName): void {
    if (this.currentRoom === room) return;
    this.currentRoom = room;

    const targets: Record<RoomName, number> = {
      ops_centre_1: 0.18,
      ops_centre_2: 0.16,
      bedroom: 0.14,
    };

    (Object.keys(this.roomAmbience) as RoomName[]).forEach((key) => {
      this.fade(this.roomAmbience[key], key === room ? targets[key] : 0, 800);
    });
  }

  // ------ Music routing ------
  // v3.0 — Hub music (theme) is handled EXCLUSIVELY by sound-effects.ts
  // playMenuMusic() + enableRadioMode(). AudioManager only manages the
  // stash jingle and bedroom layers to avoid duplicate instances.

  playHubMusic(): void {
    // Theme is driven by sound-effects.ts (with radio-mode filter at hub).
    // We only need to silence the non-hub layers and set tracking state.
    this.currentMusic = 'hub';
    this.fade(this.music.hub, 0, 400);   // ensure AM's own hub layer is silent
    this.fade(this.music.stash, 0, 800);
    this.fade(this.music.bedroom, 0, 800);
  }

  playStashMusic(): void {
    // v5.0 — Stash music removed per UX pass. Stash now uses room music.
    this.restoreRoomMusic();
  }

  playBedroomMusic(): void {
    // v3.1 — Bedroom is silence. No music layer. Only room ambience plays.
    // The absence of music IS the atmosphere — grief doesn't have a soundtrack.
    this.currentMusic = 'bedroom';
    this.fade(this.music.hub, 0, 600);
    this.fade(this.music.stash, 0, 600);
    this.fade(this.music.bedroom, 0, 600); // explicitly silent
  }

  restoreRoomMusic(): void {
    if (this.currentRoom === 'bedroom') {
      this.playBedroomMusic();
      return;
    }
    this.playHubMusic();
  }

  // ------ SFX routing (dedup: one instance per event) ------

  private _sfxLastTime: Record<string, number> = {};

  playSfx(name: SfxName): void {
    if (typeof window === 'undefined') return;
    if (isMuted()) return;

    // Prevent overlapping identical SFX within 80ms
    const now = Date.now();
    if (now - (this._sfxLastTime[name] ?? 0) < 80) return;
    this._sfxLastTime[name] = now;

    switch (name) {
      case 'nav':
        playChunkyPress();
        return;
      case 'click':
        playClick();
        return;
      case 'lullaby':
        playLullabyChime();
        return;
      case 'hover':
        sfxHover();
        return;
      case 'confirm':
        playSuccess();
        return;
      case 'error':
        playError();
        return;
      case 'paper':
        playSuccess();
        return;
      case 'safety_valve':
        this._playSafetyValveSynth();
        return;
    }
  }

  /** Alias for backward compat — 32 files use playSFX (uppercase) */
  playSFX(name: string): void {
    this.playSfx(name as SfxName);
  }

  // ------ Clipboard interaction triggers ------

  triggerClipboardHover(): void {
    this.playSfx('hover');
  }

  triggerClipboardSelect(): void {
    this.playSfx('paper');
    window.setTimeout(() => this.playSfx('confirm'), 40);
  }

  // ------ Jingle ------

  playJingle(): void {
    if (typeof window === 'undefined' || isMuted()) return;
    if (!this.jingleAudio) return;
    try {
      this.jingleAudio.currentTime = 0;
      this.jingleAudio.volume = 0.45;
      this.jingleAudio.play().catch(() => {});
    } catch {}
  }

  // ------ Shrine audio (once per click) ------

  playShrineAudio(): void {
    if (typeof window === 'undefined' || isMuted()) return;
    if (this.shrinePlaying) return; // Already playing — don't overlap
    if (!this.shrineAudio) return;
    try {
      this.shrineAudio.currentTime = 0;
      this.shrineAudio.volume = 0.55;
      this.shrinePlaying = true;
      this.shrineAudio.play().catch(() => { this.shrinePlaying = false; });
    } catch { this.shrinePlaying = false; }
  }

  // ------ Expedition event audio (rare + cooldown-guarded) ------

  /**
   * Attempt to play a random expedition audio event.
   * Returns true if played, false if on cooldown or suppressed.
   * ~20% chance per call, minimum 45s between plays.
   */
  tryExpeditionAudio(): boolean {
    if (typeof window === 'undefined' || isMuted()) return false;
    const now = Date.now();
    if (now - this.lastExpeditionAudioTime < this.expeditionCooldownMs) return false;
    // ~20% chance
    if (Math.random() > 0.20) return false;

    const src = EXPEDITION_AUDIO[Math.floor(Math.random() * EXPEDITION_AUDIO.length)];
    try {
      const audio = new Audio(src);
      audio.volume = 0.4;
      audio.play().catch(() => {});
      this.lastExpeditionAudioTime = now;
      return true;
    } catch {
      return false;
    }
  }

  // ------ Safety valve ------

  triggerSafetyValve(): void {
    this.setPressure(Math.min(1, this.pressure + 0.2));
    this.playSfx('safety_valve');
  }

  /** Safety valve SFX: low buzz + pitch drop */
  private _playSafetyValveSynth(): void {
    const ctx = this.ctx;
    if (!ctx) return;
    try {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(80, ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(40, ctx.currentTime + 0.6);
      gain.gain.setValueAtTime(0.25, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.8);
      osc.connect(gain);
      gain.connect(this.master || ctx.destination);
      osc.start(ctx.currentTime);
      osc.stop(ctx.currentTime + 0.85);

      // Sub-bass throb layer
      const osc2 = ctx.createOscillator();
      const gain2 = ctx.createGain();
      osc2.type = 'sine';
      osc2.frequency.setValueAtTime(55, ctx.currentTime);
      osc2.frequency.exponentialRampToValueAtTime(30, ctx.currentTime + 0.7);
      gain2.gain.setValueAtTime(0.15, ctx.currentTime);
      gain2.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.9);
      osc2.connect(gain2);
      gain2.connect(this.master || ctx.destination);
      osc2.start(ctx.currentTime);
      osc2.stop(ctx.currentTime + 0.95);
    } catch {
      // Degrade silently
    }
  }

  // ------ Stop all ------

  stopAll(): void {
    [...Object.values(this.music), ...Object.values(this.roomAmbience)].forEach((a) => {
      if (!a) return;
      try {
        a.pause();
        a.currentTime = 0;
        a.volume = 0;
      } catch {}
    });
    this.currentMusic = null;
    this.currentRoom = null;
  }
}

