'use client'

// One haptic vocabulary: press, activate, complete, error, toggle.
// Short, distinct pulses — each one is paired with a visual change at the call site.
const HAPTIC_PATTERNS: Record<string, number[]> = {
  press: [14], // crisp tick
  toggle: [8, 40, 8], // double click, like a switch throw
  activate: [24, 40, 24, 40, 90], // engine turning over, then catch
  complete: [18, 60, 120], // tap → heavy thunk
  error: [60, 45, 60, 45, 60], // triple buzz: denied / locked
}

// Operator hub intensity: scales pulse lengths (gaps stay as authored)
const LEVEL_SCALE: Record<string, number> = { low: 0.5, normal: 1, high: 1.6 }

let lastAt = 0
let lastPattern = ''

export function haptic(pattern: string): void {
  if (typeof window === 'undefined') return
  if (typeof navigator === 'undefined') return
  try {
    const enabled = localStorage?.getItem?.('haptics-enabled')
    if (enabled === 'false') return
    if (!navigator?.vibrate) return
    // swallow double-fires (click + key, nested handlers) of the same pattern
    const now = Date.now()
    if (pattern === lastPattern && now - lastAt < 80) return
    lastAt = now
    lastPattern = pattern
    const base = HAPTIC_PATTERNS?.[pattern] ?? HAPTIC_PATTERNS.press
    const scale = LEVEL_SCALE[localStorage?.getItem?.('bv-haptic-level') || 'normal'] ?? 1
    navigator.vibrate(scale === 1 ? base : base.map((v, i) => (i % 2 === 0 ? Math.max(4, Math.round(v * scale)) : v)))
  } catch {
    // silent fallback
  }
}

