import { NextResponse } from 'next/server'
import type Stripe from 'stripe'
import { getStripe, fulfilCheckout } from '@/lib/stripe'

export const dynamic = 'force-dynamic'

export async function POST(req: Request) {
  const stripe = getStripe()
  const secret = process.env.STRIPE_WEBHOOK_SECRET
  if (!stripe || !secret) return NextResponse.json({ error: 'not configured' }, { status: 503 })

  const sig = req.headers.get('stripe-signature')
  if (!sig) return NextResponse.json({ error: 'missing signature' }, { status: 400 })

  const raw = await req.text()
  let event: Stripe.Event
  try {
    event = stripe.webhooks.constructEvent(raw, sig, secret)
  } catch (e) {
    console.error('stripe webhook signature failed', e)
    return NextResponse.json({ error: 'bad signature' }, { status: 400 })
  }

  if (event.type === 'checkout.session.completed' || event.type === 'checkout.session.async_payment_succeeded') {
    const session = event.data.object as Stripe.Checkout.Session
    try {
      const res = await fulfilCheckout(session)
      if (!res.ok) console.warn('stripe webhook: not fulfilled', session.id, res.reason)
      else console.log('stripe webhook: unlock code issued for session', session.id)
    } catch (e) {
      console.error('stripe webhook fulfil failed', e)
      return NextResponse.json({ error: 'fulfil failed' }, { status: 500 })
    }
  }
  return NextResponse.json({ received: true })
}

import { resolveImage } from './content'
