export async function resolveHeroImage(path: string) {
  const p = path.trim()
  if (!p) return null
  if (/^https:\/\//i.test(p)) return p
  return resolveImage(p, true)
}

/** Server: per-page hero settings with the background image URL resolved. */
export async function getHeroConfig(content: SiteContentMap, page: HeroPage): Promise<HeroConfig> {
  const url = content[heroKey(page, 'bg')] === 'image' ? await resolveHeroImage(content[heroKey(page, 'bgImage')] ?? '') : null
  return resolveHero(content, page, url)
}

