// Operator hub state — client-side only (localStorage). Nothing here grants access;
// the unlock lives on the profile (User.member) and is set by the seal ritual.

export const TELEMETRY_KEY = 'bv-telemetry'
export const STASH_KEY = 'bv-stash'
export const HANDLE_KEY = 'bv-handle'
export const PREFS_KEY = 'bv-prefs'

export type Telemetry = { plays: Record<string, number>; last: Record<string, number>; jackIns: number; seconds: number }
export type HapticLevel = 'off' | 'low' | 'normal' | 'high'
export type Prefs = { haptics: HapticLevel; scanlines: boolean; hauntSfxMute: boolean; reduceMotion: boolean; flair: boolean }

export const DEFAULT_PREFS: Prefs = { haptics: 'normal', scanlines: true, hauntSfxMute: false, reduceMotion: false, flair: false }

function read<T>(key: string, fallback: T): T {
  try {
    const raw = localStorage.getItem(key)
    return raw ? { ...fallback, ...JSON.parse(raw) } : fallback
  } catch {
    return fallback
  }
}

function write(key: string, value: unknown) {
  try { localStorage.setItem(key, JSON.stringify(value)) } catch {}
}

/** Units are keyed by title (upper-cased) so every launch surface can record without knowing the slug. */
export const unitKey = (title: string) => title.trim().toUpperCase()

export function readTelemetry(): Telemetry {
  const t = read<Telemetry>(TELEMETRY_KEY, { plays: {}, last: {}, jackIns: 0, seconds: 0 })
  return { plays: t.plays || {}, last: t.last || {}, jackIns: t.jackIns || 0, seconds: t.seconds || 0 }
}

export function recordLaunch(title: string) {
  if (typeof window === 'undefined') return
  const t = readTelemetry()
  const k = unitKey(title)
  t.plays[k] = (t.plays[k] || 0) + 1
  t.last[k] = Date.now()
  t.jackIns += 1
  write(TELEMETRY_KEY, t)
}

export function addSeconds(n: number) {
  const t = readTelemetry()
  t.seconds += n
  write(TELEMETRY_KEY, t)
}

export function resetTelemetry() {
  write(TELEMETRY_KEY, { plays: {}, last: {}, jackIns: 0, seconds: 0 })
}

export function readStash(): string[] {
  try {
    const v = JSON.parse(localStorage.getItem(STASH_KEY) || '[]')
    return Array.isArray(v) ? v.filter((s) => typeof s === 'string') : []
  } catch {
    return []
  }
}

export function writeStash(slugs: string[]) {
  write(STASH_KEY, slugs)
}

export function readPrefs(): Prefs {
  return read<Prefs>(PREFS_KEY, DEFAULT_PREFS)
}

/** Applies prefs to the document. Haptic level is mirrored into the keys lib/haptics reads. */
export function applyPrefs(p: Prefs) {
  try {
    const root = document.documentElement
    root.classList.toggle('bv-no-scan', !p.scanlines)
    root.classList.toggle('bv-reduce', p.reduceMotion)
    localStorage.setItem('haptics-enabled', p.haptics === 'off' ? 'false' : 'true')
    localStorage.setItem('bv-haptic-level', p.haptics)
    localStorage.setItem('bv-haunt-sfx-mute', p.hauntSfxMute ? '1' : '0')
  } catch {}
}

export function writePrefs(p: Prefs) {
  write(PREFS_KEY, p)
  applyPrefs(p)
}

export function formatDuration(sec: number) {
  const h = Math.floor(sec / 3600)
  const m = Math.floor((sec % 3600) / 60)
  const s = sec % 60
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`
}

