            className="absolute inset-0 pointer-events-none"
            initial={{ opacity: 0 }}
            animate={{ opacity: [0, 0.14, 0.08, 0.18, 0.12, 0.06, 0] }}
            transition={{ duration: reduced ? 3 : 3.6, ease: 'easeInOut', times: [0, 0.18, 0.35, 0.52, 0.7, 0.85, 1] }}
          >
            {/* The face — screen-blended so only highlights (eye, latex sheen) glow through */}
            <div
              className="absolute"
              style={{
                top: '8%', left: '25%', width: '50%', height: '72%',
                backgroundImage: `url(${MANAGER_FACE})`,
                backgroundSize: 'cover',
                backgroundPosition: 'center 15%',
                mixBlendMode: 'screen',
                filter: 'blur(2.5px) contrast(1.25) brightness(1.3) saturate(0.6)',
                maskImage: 'radial-gradient(ellipse 70% 65% at 50% 40%, white 30%, transparent 80%)',
                WebkitMaskImage: 'radial-gradient(ellipse 70% 65% at 50% 40%, white 30%, transparent 80%)',
              }}
            />
            {/* Faint green phosphor tint over the reflection */}
            <div
              className="absolute"
              style={{
                top: '8%', left: '25%', width: '50%', height: '72%',
                background: 'radial-gradient(ellipse at 50% 38%, rgba(138,173,122,0.12), transparent 70%)',
                mixBlendMode: 'screen',
              }}
            />
          </motion.div>
          {/* Scanline wash over the reflection */}
          <motion.div
            className="absolute inset-0 pointer-events-none"
            initial={{ opacity: 0 }}
            animate={{ opacity: [0, 0.06, 0.03, 0] }}
            transition={{ duration: reduced ? 3 : 3.6, ease: 'easeInOut' }}
