export const WIPE_HINT_KEY = 'bv-wipe-hint'
export const NAV_ORDER_KEY = 'bv-nav-order'
export const LAST_PATH_KEY = 'bv-last-path'

/** Pages outside the nav (unlock, profile…) sit to the right of every nav page, matching the bar layout. */
function rank(order: string[], path: string): number {
  const i = order.indexOf(path)
  return i < 0 ? order.length : i
}

/**
 * Decide the laser direction for this page change and record the current path.
 * A swipe hint wins (beam follows the finger); otherwise moving back in nav order sweeps right-to-left.
 */
export function consumeWipeDirection(path: string): 'forward' | 'reverse' {
  try {
    const hint = sessionStorage.getItem(WIPE_HINT_KEY)
    const last = sessionStorage.getItem(LAST_PATH_KEY)
    const order: string[] = JSON.parse(sessionStorage.getItem(NAV_ORDER_KEY) || '[]')
    sessionStorage.removeItem(WIPE_HINT_KEY)
    sessionStorage.setItem(LAST_PATH_KEY, path)
    if (hint === 'reverse' || hint === 'forward') return hint
    if (!last || last === path || order.length === 0) return 'forward'
    return rank(order, path) < rank(order, last) ? 'reverse' : 'forward'
  } catch {
    return 'forward'
  }
}

