// Only very short viewports need scaling; ordinary layouts preserve reading size.
function FitSlide({ children }: { children: ReactNode }) {
  const box = useRef<HTMLDivElement>(null)
  const content = useRef<HTMLDivElement>(null)
  const [scale, setScale] = useState(1)
  useEffect(() => {
    let frame = 0
    const measure = () => {
      cancelAnimationFrame(frame)
      frame = requestAnimationFrame(() => {
        if (!box.current || !content.current) return
        const height = box.current.clientHeight
        const needed = content.current.scrollHeight
        setScale(height > 0 && needed > height ? height / needed : 1)
      })
    }
    const observer = new ResizeObserver(measure)
    if (box.current) observer.observe(box.current)
    if (content.current) {
      observer.observe(content.current)
      for (const child of Array.from(content.current.children)) observer.observe(child)
    }
    const mutations = new MutationObserver(measure)
    if (content.current) mutations.observe(content.current, { subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: ['data-overlay-view', 'data-opening-view'] })
    measure()
    document.fonts.addEventListener('loadingdone', measure)
    return () => { observer.disconnect(); mutations.disconnect(); cancelAnimationFrame(frame); document.fonts.removeEventListener('loadingdone', measure) }
  }, [])
  return <div className={styles.fitBox} ref={box}><div className={styles.fitContent} ref={content} style={{ transform: scale < 1 ? `scale(${scale})` : undefined }}>{children}</div></div>
}

function FiveActs() {
  const hud = useHud()
  const reduced = useReducedMotion()
  const [[active, direction], setAct] = useState([0, 1])
  const touch = useRef<number | null>(null)
  const show = (next: number) => {
    if (next < 0 || next >= DECK_ACTS.length || next === active) return
    setAct([next, next > active ? 1 : -1]); hud.pulse('press'); hud.note(`ACT ${DECK_ACTS[next].numeral} / ${DECK_ACTS[next].title.toUpperCase()}`)
  }
  const act = DECK_ACTS[active]
  return <div className={styles.acts} data-deck-control onPointerDown={(e) => e.stopPropagation()} onKeyDown={(e) => {
    if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') { e.preventDefault(); e.stopPropagation(); show(active + (e.key === 'ArrowRight' ? 1 : -1)) }
  }}>
    <div className={styles.actControls} aria-label="Five act selector">
      <button disabled={active === 0} onClick={() => show(active - 1)} aria-label="Previous act"><ArrowLeft size={16} /></button>
      {DECK_ACTS.map((item, i) => <button key={item.numeral} onClick={() => show(i)} aria-label={`Act ${item.numeral}: ${item.title}`} aria-pressed={active === i}>{item.numeral}</button>)}
      <button disabled={active === DECK_ACTS.length - 1} onClick={() => show(active + 1)} aria-label="Next act"><ArrowRight size={16} /></button>
    </div>
    <div className={styles.actStrip}>
      {DECK_ACTS.map((item, i) => <button key={item.numeral} onClick={() => show(i)} className={styles.actCard} aria-pressed={active === i}>
        <span className={styles.actNumber}>ACT {item.numeral}</span><h3>{item.title}</h3><p>{item.copy}</p>
      </button>)}
    </div>
    <div className={styles.actStepper} onTouchStart={(e) => { touch.current = e.touches[0].clientX }} onTouchEnd={(e) => {
      if (touch.current !== null) { const dx = e.changedTouches[0].clientX - touch.current; if (Math.abs(dx) > 45) show(active + (dx < 0 ? 1 : -1)) }; touch.current = null
    }}>
      <AnimatePresence initial={false} mode="wait" custom={direction}>
        <motion.section key={active} className={styles.actCard} custom={direction}
          variants={{ enter: (d: number) => ({ opacity: 0, x: reduced ? 0 : d * 24 }), center: { opacity: 1, x: 0 }, exit: (d: number) => ({ opacity: 0, x: reduced ? 0 : d * -24 }) }}
          initial="enter" animate="center" exit="exit" transition={{ duration: 0.16 }}>
          <span className={styles.actNumber}>ACT {act.numeral}</span><h3>{act.title}</h3><p>{act.copy}</p>
        </motion.section>
      </AnimatePresence>
    </div>
    <div className={styles.actReadout}><span>{pad(active + 1)} / 05</span><span>{act.title}</span><i style={{ '--act-progress': `${(active + 1) * 20}%` } as CSSProperties} /></div>
  </div>
}

