function SlideBody({ slide, restart }: { slide: DeckSlide; restart: () => void }) {
  if (slide.kind === 'logline') return <Opening slide={slide} />
  if (slide.kind === 'epilogue') return <div className={styles.epilogue}><span className={styles.year} aria-hidden="true">1996</span><p>{slide.copy}</p><div className={styles.epilogueEnd}><span>END OF PUBLIC DECK</span><button onClick={restart} data-deck-control><ArrowLeft size={14} /> RETURN TO THE BEGINNING</button></div></div>
  if (slide.kind === 'acts') return <FiveActs />
  if (slide.kind === 'overlay') return <OverlaySlide slide={slide} />
  return <div className={`${styles.imageBody} ${slide.kind === 'world' ? styles.worldBody : ''}`}>
    {slide.image && <DeckImagePanel image={slide.image} manager={slide.kind === 'manager'} tremor={slide.id === 'dave-mikey'} />}
    <div className={styles.copyPanel}>
      {slide.kind === 'world' && <div className={styles.worldYear}><span>SUBURBAN MELBOURNE</span><strong>1995</strong></div>}
      {slide.people ? slide.people.map((person, i) => <section className={styles.person} key={person.name}><span className={styles.personCode}>HOUSEHOLD / {pad(i + 1)}</span><h3>{person.name}</h3><p>{person.copy}</p></section>) : <p className={styles.copy}>{slide.copy}</p>}
      {slide.kind === 'manager' && <div className={styles.managerTags}><span>THE LEDGER</span><span>GREEN BAND</span><span>3K OVERLAY</span></div>}
    </div>
  </div>
}

export function PitchDeck({ goTo }: { goTo: (id: TabId) => void }) {
  const hud = useHud()
  const reduced = useReducedMotion()
  const dragControls = useDragControls()
  const [[index, dir], setState] = useState<[number, number]>([0, 0])
  const [indexOpen, setIndexOpen] = useState(false)
  const [focus, setFocus] = useState(false)
  const [manualScan, setManualScan] = useState(0)
  const stageRef = useRef<HTMLDivElement>(null)
  const reducedTouch = useRef<{ x: number; y: number } | null>(null)
  const total = DECK_SLIDES.length
  const slide = DECK_SLIDES[index]
  useEffect(() => { stageRef.current?.focus({ preventScroll: true }) }, [])
  useEffect(() => {
    const scan = () => setManualScan((n) => n + 1)
    window.addEventListener('bmf3k:manual-scan', scan)
    return () => window.removeEventListener('bmf3k:manual-scan', scan)
  }, [])

  const show = useCallback((next: number) => {
    if (next < 0 || next >= total) return
    setIndexOpen(false)
    if (next !== index) {
      setState([next, next > index ? 1 : -1]); hud.pulse('press')
      hud.note(`DECK / ${pad(next + 1)} ${DECK_SLIDES[next].title.toUpperCase()}`)
    }
  }, [index, total, hud])
  const onDragEnd = (_: unknown, info: PanInfo) => {
    if (info.offset.x < -60 || info.velocity.x < -400) show(index + 1)
    else if (info.offset.x > 60 || info.velocity.x > 400) show(index - 1)
  }
  const ignoreGesture = (target: EventTarget) => (target as HTMLElement).closest('button, [role="slider"], [data-deck-control], input, [role="dialog"]')

  return <div className={styles.root} data-slide={index + 1} data-focus={focus} data-field={hud.power} data-mode={hud.mode} data-hud-control
    style={{ '--field-gain': 0.2 + hud.gain * 0.65, '--field-color': `color-mix(in srgb, #B8F026 ${Math.round((1 - hud.hue) * 100)}%, #E040B0)` } as CSSProperties}
    onKeyDown={(e) => {
      if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); if (indexOpen) setIndexOpen(false); else if (focus) setFocus(false); else goTo('hero'); return }
      if ((e.target as HTMLElement).closest('[role="slider"], input, [data-deck-control]')) return
      if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') { e.preventDefault(); e.stopPropagation(); show(index + (e.key === 'ArrowRight' ? 1 : -1)) }
      if (e.key === 'Home' || e.key === 'End') { e.preventDefault(); e.stopPropagation(); show(e.key === 'Home' ? 0 : total - 1) }
    }}>
    <header className={styles.header}>
      <button className={styles.backButton} onClick={() => goTo('hero')} aria-label="Return to Home"><ArrowLeft size={14} /><span>HOME</span></button>
      <div className={styles.deckIdentity}><strong>BMF:3K</strong><span>Pitch deck</span></div>
      <div className={styles.headerTools}>
        <button aria-label={indexOpen ? 'Close slide index' : 'Open slide index'} aria-expanded={indexOpen} aria-controls="public-deck-index" onClick={() => { setIndexOpen(!indexOpen); hud.pulse('press') }}>{indexOpen ? <X size={15} /> : <Grid2X2 size={15} />}<span>INDEX</span></button>
        <button aria-label={focus ? 'Exit presentation focus' : 'Enter presentation focus'} aria-pressed={focus} onClick={() => { setFocus(!focus); hud.pulse('lock') }}>{focus ? <Minimize2 size={15} /> : <Maximize2 size={15} />}<span>{focus ? 'EXIT FOCUS' : 'FOCUS'}</span></button>
      </div>
    </header>
    <div ref={stageRef} tabIndex={0} className={styles.stage} role="region" aria-roledescription="carousel" aria-label="Public pitch deck. Arrow keys change slides; Escape closes focus or returns to Home.">
      {manualScan > 0 && <div key={manualScan} className={styles.manualScan} aria-hidden="true" />}
      <AnimatePresence initial={false} custom={dir} mode="sync">
        {!indexOpen && <motion.article key={slide.id} custom={dir} className={styles.slide} role="group" aria-roledescription="slide" aria-label={`${index + 1} of ${total}: ${slide.title}`}
          variants={{ enter: (d: number) => ({ x: reduced ? 0 : d >= 0 ? '100%' : '-100%', opacity: 0 }), center: { x: 0, opacity: 1 }, exit: (d: number) => ({ x: reduced ? 0 : d >= 0 ? '-100%' : '100%', opacity: 0 }) }}
          initial="enter" animate="center" exit="exit" transition={{ duration: reduced ? 0.12 : 0.32, ease: [0.22, 1, 0.36, 1] }}
          drag={reduced ? false : 'x'} dragControls={dragControls} dragListener={false} dragConstraints={{ left: 0, right: 0 }} dragElastic={0.07} onDragEnd={onDragEnd}
          onPointerDown={(e) => { if (!reduced && !ignoreGesture(e.target)) dragControls.start(e) }}
          onTouchStart={(e) => { if (!reduced || ignoreGesture(e.target)) { reducedTouch.current = null; return }; const t = e.touches[0]; reducedTouch.current = { x: t.clientX, y: t.clientY } }}
          onTouchEnd={(e) => { const start = reducedTouch.current; reducedTouch.current = null; if (!reduced || !start) return; const t = e.changedTouches[0], dx = t.clientX - start.x, dy = t.clientY - start.y; if (Math.abs(dx) > 60 && Math.abs(dx) > Math.abs(dy)) show(index + (dx < 0 ? 1 : -1)) }}>
          <FitSlide><div className={styles.slideHeading}><span>{pad(index + 1)}</span><h2 className={styles.title}>{slide.title}</h2></div><SlideBody slide={slide} restart={() => show(0)} /></FitSlide>
        </motion.article>}
      </AnimatePresence>
      {indexOpen && <div id="public-deck-index" className={styles.indexPanel}>
        <div className={styles.indexHeading}><span>PUBLIC DECK / CONTENTS</span><span>SELECT A PLATE</span></div>
        <div className={styles.indexGrid}>{DECK_SLIDES.map((item, i) => <button key={item.id} onClick={() => { show(i); stageRef.current?.focus() }} aria-current={index === i ? 'step' : undefined}><span>{pad(i + 1)}</span><strong>{SHORT_TITLES[i]}</strong><small>{item.kind === 'characters' || item.kind === 'manager' ? 'HOUSEHOLD' : item.kind === 'overlay' ? 'INTERACTIVE DEMO' : 'NARRATIVE'}</small><ArrowRight size={16} /></button>)}</div>
      </div>}
    </div>
    <nav className={styles.transport} aria-label="Pitch deck slides">
      <button className={styles.chevron} onClick={() => show(index - 1)} disabled={index === 0} aria-label="Previous slide"><ArrowLeft size={18} /></button>
      <div className={styles.dots}>{DECK_SLIDES.map((item, i) => <button key={item.id} onClick={() => show(i)} aria-label={`Slide ${i + 1}: ${item.title}`} aria-current={index === i ? 'step' : undefined} title={item.title}><span>{pad(i + 1)}</span><i /></button>)}</div>
      <button className={styles.nextButton} onClick={() => show(index + 1)} disabled={index === total - 1} aria-label="Next slide"><span><small>NEXT</small>{SHORT_TITLES[index + 1] || 'END OF DECK'}</span><ArrowRight size={18} /></button>
    </nav>
    <div className={styles.deckHint}><span>Swipe or use the arrows</span><span aria-live="polite">{pad(index + 1)} / {pad(total)} · {SHORT_TITLES[index].toUpperCase()}</span></div>
  </div>
}

