// ============================================================
// DUMPSTER-DIVING — CREW ROSTER PANEL  (v2.0)
// ============================================================
// Step 2 of the planning wizard. Shows:
//   - The selected location's skill requirements (left)
//   - The eligible crew roster (right) with toggle chips
//   - Live skill totals + crew size counter at the top
//   - Zone indicators per crew member (RED/GREEN/YELLOW)
//   - Performance impact preview based on zone state
// Skill matching logic lives in lib/dumpster-planning.ts.
// ============================================================

'use client';

import { motion, AnimatePresence } from 'framer-motion';
import { Users, AlertTriangle, Brain, Hand, Shuffle, Activity } from 'lucide-react';

import type { DumpsterLocation } from '@/lib/dumpster-locations';
import { audioManager } from '@/app/_lib/audio-manager';
import {
  computeSkillTotals,
  validateCrewSize,
  validateSkills,
  type CrewMember,
} from '@/lib/dumpster-planning';
import type { CrewZone } from '@/lib/ui-model';
import { ZONE_HEX } from '@/lib/ui-model';

interface Props {
  location: DumpsterLocation;
  eligibleCrew: CrewMember[];
  assignedCrewIds: string[];
  onToggleCrew: (npcId: string) => void;
  /** Zone state per NPC id */
  crewZones?: Record<string, CrewZone>;
}

const SKILL_META = {
  muscle: { label: 'MUSCLE', color: '#FF8C3A', Icon: Hand, hint: 'lifting, fighting off rivals' },
  brains: { label: 'BRAINS', color: '#c8dc96', Icon: Brain, hint: 'reading scenes, lock work' },
  unpredictability: { label: 'UNPRED', color: '#a8687e', Icon: Shuffle, hint: 'distraction, slipping past staff' },
} as const;

const ZONE_PERFORMANCE: Record<CrewZone, { label: string; desc: string; color: string }> = {
  GREEN:  { label: 'OPERATIONAL', desc: 'Standard performance', color: ZONE_HEX.GREEN },
  YELLOW: { label: 'UNRELIABLE', desc: 'May go absent mid-run', color: ZONE_HEX.YELLOW },
  RED:    { label: 'LIABILITY',   desc: 'Poor output, adds pressure', color: ZONE_HEX.RED },
};

export default function CrewRosterPanel({
  location,
  eligibleCrew,
  assignedCrewIds,
  onToggleCrew,
  crewZones,
}: Props) {
  const assignedSet = new Set(assignedCrewIds);
  const assignedCrew = eligibleCrew.filter((m) => assignedSet.has(m.id));
  const totals = computeSkillTotals(assignedCrew);
  const sizeCheck = validateCrewSize(assignedCrew, location);
  const skillCheck = validateSkills(assignedCrew, location);

  // Count zones in assigned crew
  const zoneCount = { GREEN: 0, YELLOW: 0, RED: 0 };
  for (const m of assignedCrew) {
    const z = crewZones?.[m.id] ?? 'GREEN';
    zoneCount[z]++;
  }
  const hasZoneRisk = zoneCount.RED > 0 || zoneCount.YELLOW > 0;

  if (eligibleCrew.length === 0) {
    return (
      <div
        className="border-l-[3px] border-l-[#CCAA00] p-4 rounded-[1px] text-center"
        style={{ background: 'rgba(10,10,9,0.78)' }}
      >
        <AlertTriangle size={28} className="mx-auto mb-2 text-[#CCAA00]" />
        <p className="font-terminal text-sm text-[#CCAA00]">NO CREW ON THE BOOKS</p>
        <p className="font-typewriter text-xs text-[#8a8578] italic mt-1">
          Recruit at the Clipboard before you try to dispatch anyone.
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-3">
      {/* Crew size counter + skill totals header */}
      <div
        className="border-l-[3px] border-l-[#B87333] p-3 rounded-[1px]"
        style={{ background: 'rgba(10,10,9,0.78)' }}
      >
        <div className="flex items-center justify-between mb-2">
          <p className="font-terminal text-[10px] tracking-[0.18em] text-[#B87333] flex items-center gap-1.5">
            <Users size={12} /> CREW MANIFEST
          </p>
          <div
            className="font-terminal text-xs px-2 py-0.5 rounded-[1px]"
            style={{
              color: sizeCheck.ok ? '#c8dc96' : '#a8687e',
              border: `1px solid ${sizeCheck.ok ? '#c8dc96' : '#a8687e'}66`,
              background: sizeCheck.ok ? 'rgba(200,220,150,0.06)' : 'rgba(255,20,147,0.04)',
            }}
          >
            {assignedCrew.length}/{location.maxCrew} (min {location.minCrew})
          </div>
        </div>

        {/* Skill totals row */}
        <div className="grid grid-cols-3 gap-2">
          {(['muscle', 'brains', 'unpredictability'] as const).map((k) => {
            const meta = SKILL_META[k];
            const need = location.skillRequirements?.[k] ?? 0;
            const have = totals[k];
            const met = need === 0 || have >= need;
            const Icon = meta.Icon;
            return (
              <div
                key={k}
                className="px-2 py-1.5 rounded-[1px]"
                style={{
                  borderLeft: `2px solid ${met ? meta.color : '#3a3a30'}`,
                  background: 'rgba(15,12,8,0.6)',
                }}
              >
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-1">
                    <Icon size={10} color={met ? meta.color : '#7a7060'} />
                    <p
                      className="font-terminal text-[9px] tracking-[0.15em]"
                      style={{ color: met ? meta.color : '#7a7060' }}
                    >
                      {meta.label}
                    </p>
                  </div>
                  {need > 0 && (
                    <p
                      className="font-terminal text-[10px]"
                      style={{ color: met ? '#c8dc96' : '#a8687e' }}
                    >
                      {met ? '\u2713' : '\u2717'}
                    </p>
                  )}
                </div>
                <p
                  className="font-terminal text-base mt-0.5"
                  style={{ color: met ? '#e8e4d4' : '#a8687e' }}
                >
                  {have}
                  {need > 0 && (
                    <span className="text-[#7a7060] text-xs"> / {need}</span>
                  )}
                </p>
              </div>
            );
          })}
        </div>

        {/* Skill shortfall message */}
        <AnimatePresence initial={false}>
          {!skillCheck.ok && assignedCrew.length > 0 && (
            <motion.p
              key="skill-warn"
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: 'auto' }}
              exit={{ opacity: 0, height: 0 }}
              className="font-typewriter text-[11px] text-[#a8687e] italic mt-2"
            >
              Crew is short on the right kind of hands. Pick someone with the missing stat.
            </motion.p>
          )}
        </AnimatePresence>
      </div>

      {/* Zone performance summary (shows when crew assigned) */}
      <AnimatePresence initial={false}>
        {assignedCrew.length > 0 && crewZones && (
          <motion.div
            key="zone-summary"
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            className="overflow-hidden"
          >
            <div
              className="border-l-[3px] p-3 rounded-[1px]"
              style={{
                borderLeftColor: hasZoneRisk ? ZONE_HEX.YELLOW : ZONE_HEX.GREEN,
                background: 'rgba(10,10,9,0.78)',
              }}
            >
              <p className="font-terminal text-[10px] tracking-[0.18em] flex items-center gap-1.5 mb-2" style={{ color: hasZoneRisk ? ZONE_HEX.YELLOW : ZONE_HEX.GREEN }}>
                <Activity size={11} /> CREW READINESS
              </p>
              <div className="flex items-center gap-3">
                {(['GREEN', 'YELLOW', 'RED'] as CrewZone[]).map((z) => {
                  const count = zoneCount[z];
                  if (count === 0) return null;
                  return (
                    <div key={z} className="flex items-center gap-1.5">
                      <span
                        className="w-2.5 h-2.5 rounded-full"
                        style={{
                          backgroundColor: ZONE_HEX[z],
                          boxShadow: `0 0 6px ${ZONE_HEX[z]}50`,
                        }}
                      />
                      <span className="font-terminal text-[10px]" style={{ color: ZONE_HEX[z] }}>
                        {count} {ZONE_PERFORMANCE[z].label}
                      </span>
                    </div>
                  );
                })}
              </div>
              {hasZoneRisk && (
                <p className="font-typewriter text-[10px] mt-2 italic" style={{ color: '#a99775' }}>
                  {zoneCount.RED > 0 ? 'RED crew adds pressure and reduces loot yield.' : ''}
                  {zoneCount.YELLOW > 0 ? ' YELLOW crew may go absent mid-run.' : ''}
                </p>
              )}
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Roster grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
        {eligibleCrew.map((npc) => {
          const selected = assignedSet.has(npc.id);
          const overCap = !selected && assignedCrew.length >= location.maxCrew;
          const zone = crewZones?.[npc.id] ?? 'GREEN';
          const zonePerf = ZONE_PERFORMANCE[zone];
          return (
            <button
              key={npc.id}
              type="button"
              disabled={overCap}
              onClick={() => {
                audioManager.playSFX('nav');
                onToggleCrew(npc.id);
              }}
              className="text-left p-3 rounded-[1px] transition-all disabled:opacity-30 disabled:cursor-not-allowed"
              style={{
                borderLeft: `3px solid ${selected ? '#c8dc96' : '#3a3a30'}`,
                background: selected ? 'rgba(200,220,150,0.06)' : 'rgba(10,10,9,0.78)',
                boxShadow: selected ? '0 0 18px rgba(200,220,150,0.18)' : 'none',
              }}
              aria-pressed={selected}
              aria-label={`${selected ? 'Remove' : 'Assign'} ${npc.name}`}
            >
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <p
                    className="font-terminal text-sm"
                    style={{ color: selected ? '#c8dc96' : '#e8e4d4' }}
                  >
                    {selected ? '\u2713 ' : ''}
                    {npc.name}
                  </p>
                  {/* Zone dot */}
                  <span
                    className="w-2 h-2 rounded-full flex-shrink-0"
                    style={{
                      backgroundColor: ZONE_HEX[zone],
                      boxShadow: `0 0 4px ${ZONE_HEX[zone]}40`,
                    }}
                    title={`${zone}: ${zonePerf.desc}`}
                  />
                </div>
                <div className="flex items-center gap-2">
                  {/* Zone label */}
                  <span
                    className="font-terminal text-[8px] px-1.5 py-0.5 tracking-wider"
                    style={{
                      color: zonePerf.color,
                      border: `1px solid ${zonePerf.color}30`,
                      borderRadius: '2px',
                      background: `${zonePerf.color}08`,
                    }}
                  >
                    {zone}
                  </span>
                  {npc.heatLevel >= 5 && (
                    <span
                      className="font-terminal text-[9px] px-1.5 py-0.5"
                      style={{
                        color: '#a8687e',
                        border: '1px solid rgba(255,20,147,0.4)',
                        background: 'rgba(255,20,147,0.05)',
                      }}
                      title="This crew member is hot. Adds personal heat penalty."
                    >
                      HOT {npc.heatLevel}
                    </span>
                  )}
                </div>
              </div>
              {npc.skill && (
                <p className="font-typewriter text-[11px] text-[#8a8578] italic mt-0.5 line-clamp-1">
                  {npc.skill}
                </p>
              )}
              <div className="flex items-center gap-3 mt-1.5 font-terminal text-[10px]">
                <span style={{ color: '#FF8C3A' }}>MUS {npc.muscle}</span>
                <span style={{ color: '#c8dc96' }}>BRN {npc.brains}</span>
                <span style={{ color: '#a8687e' }}>UNP {npc.unpredictability}</span>
                {/* Zone performance hint when selected */}
                {selected && zone !== 'GREEN' && (
                  <span className="ml-auto text-[9px]" style={{ color: zonePerf.color }}>
                    {zonePerf.desc}
                  </span>
                )}
              </div>
            </button>
          );
        })}
      </div>
    </div>
  );
}

// ============================================================
// DUMPSTER DIVING — PURE PLANNING LOGIC (v0.5.4)
// ============================================================
// All planning logic is pure functions on plain data so we can:
//   - run the same validators on the client (live UI feedback)
//   - re-run them on the server (authoritative dispatch validation)
// No DOM, no fetch, no React imports here.
// ============================================================

import type { ResourceKey } from './game-data';
import type { DumpsterLocation, DumpsterCost } from './dumpster-locations';

// ----- Types ------------------------------------------------

export interface CrewMember {
  id: string;
  name: string;
  recruited: boolean;
  status: string;            // 'AVAILABLE' | 'BUSY' | 'INJURED' | ...
  muscle: number;
  brains: number;
  unpredictability: number;
  heatLevel: number;         // their personal heat — adds to mission risk
  skill?: string;            // flavour text label
}

export interface ResourceLine {
  type: ResourceKey | string;
  quantity: number;
}

export interface SkillTotals {
  muscle: number;
  brains: number;
  unpredictability: number;
}

export interface ResourceCheck {
  resource: ResourceKey;
  required: number;
  have: number;
  ok: boolean;
}

export interface CrewSizeCheck {
  ok: boolean;
  size: number;
  min: number;
  max: number;
  reason?: string;
}

export interface SkillCheck {
  ok: boolean;
  totals: SkillTotals;
  required: { muscle: number; brains: number; unpredictability: number };
  shortfall: SkillTotals;
}

export interface PlanningValidation {
  // overall gate — true means dispatch is allowed
  ok: boolean;
  // breakdown
  crewSize: CrewSizeCheck;
  skills: SkillCheck;
  resources: ResourceCheck[];   // one row per resource the location costs
  // human-readable blocking reasons (in display order)
  blockingReasons: string[];
}

export interface SuccessEstimate {
  // 0..100 — marketing number shown in UI; do not use for server logic.
  chancePct: number;
  // descriptive label that maps onto the chance.
  label: 'LIKELY' | 'COIN-FLIP' | 'RISKY' | 'STUPID';
  // raw factors so UI can explain itself.
  factors: {
    base: number;
    skillBonus: number;
    sizeBonus: number;
    mobilityBonus: number;
    heatPenalty: number;
    crewHeatPenalty: number;
  };
}

// ----- Helpers ----------------------------------------------

const RESOURCE_KEYS: ResourceKey[] = ['cigarettes', 'alcohol', 'weed', 'crystals'];

function toMap(resources: ResourceLine[] | null | undefined): Record<string, number> {
  const map: Record<string, number> = {};
  for (const r of resources ?? []) {
    if (!r?.type) continue;
    map[r.type] = (map[r.type] ?? 0) + (r?.quantity ?? 0);
  }
  return map;
}

// ----- 1. Crew skill totals --------------------------------

export function computeSkillTotals(crew: CrewMember[] | null | undefined): SkillTotals {
  const out: SkillTotals = { muscle: 0, brains: 0, unpredictability: 0 };
  for (const m of crew ?? []) {
    if (!m) continue;
    out.muscle += m?.muscle ?? 0;
    out.brains += m?.brains ?? 0;
    out.unpredictability += m?.unpredictability ?? 0;
  }
  return out;
}

// ----- 2. Crew availability filter --------------------------
// What NPCs are eligible to be on a crew right now.
export function getEligibleCrew(
  npcs: CrewMember[] | null | undefined,
): CrewMember[] {
  return (npcs ?? [])
    .filter((n) => !!n)
    .filter((n) => n?.recruited === true)
    .filter((n) => {
      const status = (n?.status ?? '').toUpperCase();
      // BUSY / INJURED / DEAD are excluded; everything else is eligible.
      return status !== 'BUSY' && status !== 'INJURED' && status !== 'DEAD';
    });
}

// ----- 3. Resource validation -------------------------------

export function validateResources(
  cost: DumpsterCost,
  resources: ResourceLine[] | null | undefined,
): ResourceCheck[] {
  const have = toMap(resources);
  const out: ResourceCheck[] = [];
  for (const key of RESOURCE_KEYS) {
    const required = cost?.[key] ?? 0;
    if (required <= 0) continue;
    const haveQty = have?.[key] ?? 0;
    out.push({
      resource: key,
      required,
      have: haveQty,
      ok: haveQty >= required,
    });
  }
  return out;
}

// ----- 4. Crew size check -----------------------------------

export function validateCrewSize(
  crew: CrewMember[],
  location: DumpsterLocation,
): CrewSizeCheck {
  const size = crew?.length ?? 0;
  if (size < (location?.minCrew ?? 0)) {
    return {
      ok: false,
      size,
      min: location?.minCrew ?? 0,
      max: location?.maxCrew ?? 0,
      reason: `Need at least ${location.minCrew} crew. You\u2019ve picked ${size}.`,
    };
  }
  if (size > (location?.maxCrew ?? 99)) {
    return {
      ok: false,
      size,
      min: location?.minCrew ?? 0,
      max: location?.maxCrew ?? 0,
      reason: `Crew is overloaded. Cap is ${location.maxCrew}; you\u2019ve assigned ${size}.`,
    };
  }
  return {
    ok: true,
    size,
    min: location?.minCrew ?? 0,
    max: location?.maxCrew ?? 0,
  };
}

// ----- 5. Skill check ---------------------------------------

export function validateSkills(
  crew: CrewMember[],
  location: DumpsterLocation,
): SkillCheck {
  const totals = computeSkillTotals(crew);
  const required = {
    muscle: location?.skillRequirements?.muscle ?? 0,
    brains: location?.skillRequirements?.brains ?? 0,
    unpredictability: location?.skillRequirements?.unpredictability ?? 0,
  };
  const shortfall: SkillTotals = {
    muscle: Math.max(0, required.muscle - totals.muscle),
    brains: Math.max(0, required.brains - totals.brains),
    unpredictability: Math.max(0, required.unpredictability - totals.unpredictability),
  };
  const ok = shortfall.muscle === 0 && shortfall.brains === 0 && shortfall.unpredictability === 0;
  return { ok, totals, required, shortfall };
}

// ----- 6. Top-level validation -------------------------------

export function validatePlanning(
  location: DumpsterLocation,
  crew: CrewMember[],
  resources: ResourceLine[] | null | undefined,
): PlanningValidation {
  const crewSize = validateCrewSize(crew, location);
  const skills = validateSkills(crew, location);
  const resourceChecks = validateResources(location?.cost ?? {}, resources);
  const blockingReasons: string[] = [];

  if (!crewSize.ok && crewSize.reason) blockingReasons.push(crewSize.reason);
  if (!skills.ok) {
    const parts: string[] = [];
    if (skills.shortfall.muscle > 0) parts.push(`MUSCLE -${skills.shortfall.muscle}`);
    if (skills.shortfall.brains > 0) parts.push(`BRAINS -${skills.shortfall.brains}`);
    if (skills.shortfall.unpredictability > 0) parts.push(`UNPRED -${skills.shortfall.unpredictability}`);
    if (parts.length) blockingReasons.push(`Crew is short on: ${parts.join(', ')}.`);
  }
  for (const r of resourceChecks) {
    if (!r.ok) {
      blockingReasons.push(`Need ${r.required} ${r.resource}; you have ${r.have}.`);
    }
  }

  const ok = crewSize.ok && skills.ok && resourceChecks.every((r) => r.ok);

  return { ok, crewSize, skills, resources: resourceChecks, blockingReasons };
}

// ----- 7. Success estimate (UI-only) -------------------------
// NOTE: This is a marketing/feedback number. Server doesn't use it.
//
//   base = 60 - (difficulty - 1) * 8
//          (1 = 60, 2 = 52, 3 = 44, 4 = 36, 5 = 28)
//   skillBonus  = +5 per skill category that's met (max +15)
//                + min(15, surplus*2) per category bonus stat
//   sizeBonus   = +5 per crew over min, capped at +15
//   mobilityBonus  = +2 per mobility point above default (2)
//   heatPenalty    = floor(sessionHeat / 2) (max -25)
//   crewHeatPenalty = sum(crew.heatLevel) (max -15)
//
export function estimateSuccess(
  location: DumpsterLocation,
  crew: CrewMember[],
  ctx: { sessionHeat: number; mobilityStat: number },
): SuccessEstimate {
  const base = 60 - ((location?.difficulty ?? 1) - 1) * 8;

  // Skill bonus
  const totals = computeSkillTotals(crew);
  const reqs = location?.skillRequirements ?? {};
  let skillBonus = 0;
  let metCount = 0;
  for (const k of ['muscle', 'brains', 'unpredictability'] as const) {
    const need = reqs?.[k] ?? 0;
    if (need <= 0) continue;
    if (totals[k] >= need) {
      metCount += 1;
      const surplus = totals[k] - need;
      skillBonus += Math.min(15, surplus * 2);
    }
  }
  skillBonus += metCount * 5;

  // Size bonus
  const size = crew?.length ?? 0;
  const sizeBonus = Math.min(15, Math.max(0, size - (location?.minCrew ?? 0)) * 5);

  // Mobility
  const mobilityBonus = Math.max(0, (ctx?.mobilityStat ?? 2) - 2) * 2;

  // Heat penalty
  const heatPenalty = Math.min(25, Math.floor((ctx?.sessionHeat ?? 0) / 2));
  const crewHeatPenalty = Math.min(15, (crew ?? []).reduce((acc, n) => acc + (n?.heatLevel ?? 0), 0));

  const raw = base + skillBonus + sizeBonus + mobilityBonus - heatPenalty - crewHeatPenalty;
  const chancePct = Math.max(5, Math.min(95, Math.round(raw)));

  let label: SuccessEstimate['label'];
  if (chancePct >= 70) label = 'LIKELY';
  else if (chancePct >= 50) label = 'COIN-FLIP';
  else if (chancePct >= 30) label = 'RISKY';
  else label = 'STUPID';

  return {
    chancePct,
    label,
    factors: {
      base,
      skillBonus,
      sizeBonus,
      mobilityBonus,
      heatPenalty,
      crewHeatPenalty,
    },
  };
}

// ----- 8. Wizard reducer types ------------------------------
// Pure state shape used by the clipboard wizard. Lives here so the
// reducer can be unit-tested without React.

export type WizardStep = 'site' | 'crew' | 'review';

export interface WizardState {
  step: WizardStep;
  selectedLocationKey: string | null;
  /** Travel map node the player selected as destination */
  selectedNodeKey: string | null;
  assignedCrewIds: string[];
  // when dispatch starts, locks the wizard
  dispatching: boolean;
  // any server-side error from the last dispatch attempt
  dispatchError: string | null;
}

export const INITIAL_WIZARD_STATE: WizardState = {
  step: 'site',
  selectedLocationKey: null,
  selectedNodeKey: null,
  assignedCrewIds: [],
  dispatching: false,
  dispatchError: null,
};

export type WizardAction =
  | { type: 'select_location'; key: string }
  | { type: 'select_node'; nodeKey: string; locationKey: string }
  | { type: 'goto_step'; step: WizardStep }
  | { type: 'toggle_crew'; npcId: string; minCrew: number; maxCrew: number }
  | { type: 'clear_crew' }
  | { type: 'reset' }
  | { type: 'dispatch_start' }
  | { type: 'dispatch_error'; message: string }
  | { type: 'dispatch_done' };

export function wizardReducer(state: WizardState, action: WizardAction): WizardState {
  switch (action?.type) {
    case 'select_location':
      // changing location resets the crew (skill reqs are different)
      if (state.selectedLocationKey === action.key) return state;
      return {
        ...state,
        selectedLocationKey: action.key,
        assignedCrewIds: [],
        dispatchError: null,
      };
    case 'select_node':
      if (state.selectedNodeKey === action.nodeKey) return state;
      return {
        ...state,
        selectedNodeKey: action.nodeKey,
        selectedLocationKey: action.locationKey,
        assignedCrewIds: [],
        dispatchError: null,
      };
    case 'goto_step':
      return { ...state, step: action.step, dispatchError: null };
    case 'toggle_crew': {
      const has = state.assignedCrewIds.includes(action.npcId);
      if (has) {
        return {
          ...state,
          assignedCrewIds: state.assignedCrewIds.filter((id) => id !== action.npcId),
          dispatchError: null,
        };
      }
      // soft cap at maxCrew — reject extras silently (UI also disables)
      if (state.assignedCrewIds.length >= action.maxCrew) return state;
      return {
        ...state,
        assignedCrewIds: [...state.assignedCrewIds, action.npcId],
        dispatchError: null,
      };
    }
    case 'clear_crew':
      return { ...state, assignedCrewIds: [], dispatchError: null };
    case 'reset':
      return INITIAL_WIZARD_STATE;
    case 'dispatch_start':
      return { ...state, dispatching: true, dispatchError: null };
    case 'dispatch_error':
      return { ...state, dispatching: false, dispatchError: action.message };
    case 'dispatch_done':
      return { ...state, dispatching: false, dispatchError: null };
    default:
      return state;
  }
}

