// ============================================================
// DUMPSTER DIVING — LOCATION CATALOG (v0.5.4)
// ============================================================
// Phase 1 of the Dumpster Diving Planning Operation.
//
// Each location is a self-contained "job" the player can dispatch a
// crew to. Locations are placed on a paper-map (`mapPos`) inside the
// clipboard planning UI. Locations gate themselves via:
//   1. Resource cost (cigarettes/alcohol/etc to dispatch)
//   2. Crew size band (min..max)
//   3. Skill requirements (sum of crew stats >= threshold)
//   4. Optional prereq mission key (story progression)
//
// THIS FILE IS PURE DATA + TYPES. No game logic lives here.
// Logic lives in `lib/dumpster-planning.ts`.
// ============================================================

import type { ResourceKey } from './game-data';

// Resource cost block (re-using the same shape as MissionCost).
export type DumpsterCost = Partial<Record<ResourceKey, number>>;

// Skill requirement: sum of crew's stat across these dimensions.
// All fields optional; missing fields = no requirement on that stat.
export interface DumpsterSkillReq {
  muscle?: number;            // brute force, lifting, fighting off rivals
  brains?: number;            // recognising what's worth grabbing, lock picking
  unpredictability?: number;  // distraction, chaos, slipping past staff
}

// Loot ranges — randomised at extraction. [min, max] inclusive.
export interface DumpsterLootProfile {
  cigarettes: [number, number];
  alcohol:    [number, number];
  weed:       [number, number];
  crystals:   [number, number];
}

export type DumpsterDifficulty = 1 | 2 | 3 | 4 | 5;

export interface DumpsterLocation {
  key: string;

  // Naming
  name: string;          // delusion-flavoured name shown big
  realityName: string;   // truthful subtitle ("actually it's the…")
  district: string;      // map cluster / region label

  // Flavour copy
  flavor: string;        // 1-line briefing for cards
  realityText: string;   // gritty truth shown in flicker / detail

  // Difficulty + map
  difficulty: DumpsterDifficulty;
  mapPos: { x: number; y: number };  // 0..100 % within the map viewport

  // Gating
  cost: DumpsterCost;
  minCrew: number;       // inclusive
  maxCrew: number;       // inclusive
  skillRequirements: DumpsterSkillReq;

  // Outcome
  lootProfile: DumpsterLootProfile;
  baseHeat: number;       // baseline heat added on extraction

  // Story gate (mission key from MISSION_DEFINITIONS) or null = always available
  prereq: string | null;
}

// ============================================================
// THE 8 LOCATIONS
// ============================================================
// Layout intent on the map (xy normalised 0..100):
//   - Bottom-right: easy intro skips behind the player's own servo
//   - Centre belt: medium-risk strip-mall haul
//   - Top edges: high-risk industrial / commercial dumps
// ============================================================

export const DUMPSTER_LOCATIONS: DumpsterLocation[] = [
  {
    key: 'servo_rear_skip',
    name: 'BACK-OF-HOUSE BIN',
    realityName: 'Servo rear skip behind your own pumps',
    district: 'OUR PERIMETER',
