export function getDumpsterByKey(key: string | null | undefined): DumpsterLocation | null {
  if (!key) return null;
  return DUMPSTER_LOCATIONS.find((d) => d?.key === key) ?? null;
}

// Helper: a location is locked when its prereq mission isn't COMPLETED yet.
export function isDumpsterUnlocked(
  location: DumpsterLocation,
  completedMissionKeys: Set<string>,
): boolean {
  if (!location?.prereq) return true;
  return completedMissionKeys?.has?.(location.prereq) ?? false;
}

