// ============================================================
// DUMPSTER-DIVING — CLIPBOARD PLANNING WIZARD  (v0.5.4)
// ============================================================
// Replaces the legacy MapTableStation. Drives a 3-step planning flow:
//   1. SITE  — player picks a dumpster on the district map
//   2. CREW  — player assigns recruited NPCs (skill-matched)
//   3. GO    — player reviews cost + success estimate, hits DISPATCH
// State is held in a useReducer (see lib/dumpster-planning.ts).
// Server-side validation is the source of truth: see
// /api/game/expedition action='dispatch'.
// ============================================================

'use client';

import { useEffect, useMemo, useReducer, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ArrowLeft, ArrowRight, Route, Users, ClipboardCheck, Send } from 'lucide-react';
import { playThud } from '@/lib/sound-effects';
import type { EscalationState } from '@/lib/escalation';
import type { GameState } from '../game-client';
import {
  DUMPSTER_LOCATIONS,
  getDumpsterByKey,
  isDumpsterUnlocked,
  type DumpsterLocation,
} from '@/lib/dumpster-locations';
import { TRAVEL_NODES, getNodeByKey } from '@/lib/travel-map';
import {
  getEligibleCrew,
  validatePlanning,
  wizardReducer,
  INITIAL_WIZARD_STATE,
  type CrewMember,
  type ResourceLine,
  type WizardStep,
} from '@/lib/dumpster-planning';
import TravelMapPanel from './travel-map-panel';
import CrewRosterPanel from './crew-roster-panel';
import MissionBriefPanel from './mission-brief-panel';
import { audioManager } from '@/app/_lib/audio-manager';
import { computeActorState } from '@/lib/encounter';
import { getZoneFromActor, type CrewZone } from '@/lib/ui-model';
import { DIRECTIVE_CARDS, getDirectiveStatus } from '@/lib/directives';

interface Props {
  game: GameState;
  escalation: EscalationState;
  onBack: () => void;
  onLaunchExpedition: (expeditionId: string, directiveNpcKey?: string) => void;
  onRefresh: () => Promise<void>;
  showNotification: (msg: string) => void;
}

const STEPS: { key: WizardStep; label: string; n: number }[] = [
  { key: 'site',   label: 'TRAVEL', n: 1 },
  { key: 'crew',   label: 'CREW',   n: 2 },
  { key: 'review', label: 'GO',     n: 3 },
];

export default function DumpsterPlanningClipboard({
  game,
  escalation,
  onBack,
  onLaunchExpedition,
  onRefresh,
  showNotification,
}: Props) {
  const [state, dispatch] = useReducer(wizardReducer, INITIAL_WIZARD_STATE);
  const [activatedDirectiveKey, setActivatedDirectiveKey] = useState<string | null>(null);

  // Find eligible directive for assigned crew
  const eligibleDirective = useMemo(() => {
    for (const crewId of state.assignedCrewIds) {
      const npc = (game?.npcs ?? []).find((n) => n?.id === crewId);
      if (!npc) continue;
      const npcKey = npc.archetype?.toLowerCase();
      const card = DIRECTIVE_CARDS[npcKey];
      if (!card) continue;
      const mission = (game?.missions ?? []).find((m: any) => m?.missionKey === `directive_${npcKey}`);
      const dirStatus = getDirectiveStatus(npcKey, !!npc.recruited, !!npc.directiveDone, mission?.status);
      if (dirStatus === 'UNLOCKED' || dirStatus === 'FAILED') {
        return { npcKey, card, status: dirStatus, npcName: npc.name };
      }
    }
    return null;
  }, [state.assignedCrewIds, game?.npcs, game?.missions]);

  // Eligible crew (recruited + AVAILABLE), normalised to CrewMember
  const eligibleCrew: CrewMember[] = useMemo(() => {
    const npcs = (game?.npcs ?? []).map((n: any): CrewMember => ({
      id: n?.id,
      name: n?.name ?? 'NPC',
      recruited: !!n?.recruited,
      status: n?.status ?? 'AVAILABLE',
      muscle: n?.muscle ?? 0,
      brains: n?.brains ?? 0,
      unpredictability: n?.unpredictability ?? 0,
      heatLevel: n?.heatLevel ?? 0,
      skill: n?.skill,
    }));
    return getEligibleCrew(npcs);
  }, [game?.npcs]);

  // Compute zone state per NPC for roster/brief display
  const crewZones: Record<string, CrewZone> = useMemo(() => {
    const map: Record<string, CrewZone> = {};
    for (const npc of game?.npcs ?? []) {
      if (!npc?.recruited) continue;
      try {
        const actor = computeActorState(npc as any);
        map[npc.id] = getZoneFromActor(actor);
      } catch { map[npc.id] = 'GREEN'; }
    }
    return map;
  }, [game?.npcs]);

  // Set of completed mission keys (for unlocking gated locations)
  const completedMissionKeys = useMemo(() => {
    const set = new Set<string>();
    for (const m of (game?.missions ?? []) as any[]) {
      if (m?.status === 'COMPLETED' && m?.missionKey) set.add(m.missionKey);
    }
    return set;
  }, [game?.missions]);

  const selectedLocation: DumpsterLocation | null = getDumpsterByKey(state.selectedLocationKey);

  // Resource lines (used by all validators)
  const resourceLines: ResourceLine[] = useMemo(() => {
    return (game?.resources ?? []).map((r: any) => ({
      type: r?.type ?? '',
      quantity: r?.quantity ?? 0,
    }));
  }, [game?.resources]);

  const assignedCrew: CrewMember[] = useMemo(() => {
    const set = new Set(state.assignedCrewIds);
    return eligibleCrew.filter((m) => set.has(m.id));
  }, [eligibleCrew, state.assignedCrewIds]);

  // Live validation — only run when a location is selected
  const validation = useMemo(() => {
    if (!selectedLocation) return null;
    return validatePlanning(selectedLocation, assignedCrew, resourceLines);
  }, [selectedLocation, assignedCrew, resourceLines]);

  // Step gating — can the player advance to the next step?
  const canAdvance = useMemo(() => {
    if (state.step === 'site') return !!state.selectedNodeKey && !!selectedLocation;
    if (state.step === 'crew') {
      // need at least minCrew assigned to even peek at review
      if (!selectedLocation) return false;
      return assignedCrew.length >= selectedLocation.minCrew;
    }
    if (state.step === 'review') return validation?.ok === true;
    return false;
  }, [state.step, selectedLocation, assignedCrew, validation]);

  // Keyboard shortcuts — ESC to back out, Enter to advance
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e?.key === 'Escape') {
        if (state.step === 'site') onBack();
        else if (state.step === 'crew') dispatch({ type: 'goto_step', step: 'site' });
        else if (state.step === 'review') dispatch({ type: 'goto_step', step: 'crew' });
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [state.step, onBack]);

  // ----- Dispatch ------------------------------------------
  const handleDispatch = async () => {
    if (!selectedLocation) return;
    if (!validation?.ok) {
      audioManager.playSFX('error');
      showNotification('Planning is invalid. Check the brief.');
      return;
    }
    if (!game?.sessionId) {
      showNotification('No session.');
      return;
    }

    dispatch({ type: 'dispatch_start' });
    playThud();
    try {
      const res = await fetch('/api/game/expedition', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          sessionId: game.sessionId,
          action: 'dispatch',
          data: {
            locationKey: selectedLocation.key,
            crewIds: state.assignedCrewIds,
          },
        }),
      });
      if (!res.ok) {
        let msg = 'Dispatch refused.';
        try {
          const err = await res.json();
          msg = err?.error ?? msg;
          if (Array.isArray(err?.validation?.blockingReasons) && err.validation.blockingReasons.length) {
            msg += ' ' + err.validation.blockingReasons.join(' ');
          }
        } catch {}
        dispatch({ type: 'dispatch_error', message: msg });
        audioManager.playSFX('error');
        showNotification(msg);
        return;
      }
      const payload = await res.json();
      dispatch({ type: 'dispatch_done' });
      // Activate directive if toggled
      if (activatedDirectiveKey) {
        await fetch('/api/game/directive', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ sessionId: game.sessionId, action: 'activate', npcKey: activatedDirectiveKey }),
        }).catch(() => {});
      }
      await onRefresh();
      onLaunchExpedition(payload?.expedition?.id, activatedDirectiveKey ?? undefined);
    } catch (e: any) {
      const msg = e?.message ?? 'Dispatch failed.';
      dispatch({ type: 'dispatch_error', message: msg });
      audioManager.playSFX('error');
      showNotification(msg);
    }
  };

  // ----- Render --------------------------------------------
  const stepIdx = STEPS.findIndex((s) => s.key === state.step);

  return (
    <div className="w-full h-full flex flex-col bg-[#080808] grimy-panel">
      {/* Header */}
      <div className="flex items-center gap-3 px-3 py-3 bg-[#0a0a08]/95 border-b border-[#B87333]/25 backdrop-blur-[2px]">
        <button
          onClick={() => {
            audioManager.playSFX('nav');
            onBack();
          }}
          aria-label="Go back to hub"
          className="text-[#B87333] hover:text-[#CCAA00] active:scale-90 transition focus:outline-none focus-visible:ring-1 focus-visible:ring-[#B87333]/60 min-w-[44px] min-h-[44px] flex items-center justify-center"
        >
          <ArrowLeft size={20} />
        </button>
        <div className="flex-1 min-w-0">
          <h2 className="font-terminal text-base sm:text-lg text-[#CCAA00] tracking-[0.1em] truncate">
            CLIPBOARD — TRAVEL DISPATCH
          </h2>
          <p className="font-typewriter text-[10px] sm:text-[11px] text-[#8a8578] italic">
            Day {game?.day ?? 1} · Heat {Math.round(game?.heat ?? 0)} · Crew on books: {eligibleCrew.length}
          </p>
        </div>
        {/* Brass paperclip — fake decorative */}
        <div
          className="hidden sm:block"
          aria-hidden="true"
          style={{
            width: 28,
            height: 32,
            border: '2px solid #B87333',
            borderRadius: '6px 6px 2px 2px',
            borderBottomColor: 'transparent',
            opacity: 0.5,
            transform: 'rotate(8deg) translateY(-3px)',
            boxShadow: '1px 2px 0 rgba(0,0,0,0.6)',
          }}
        />
      </div>

      {/* Step indicator */}
      <div
        className="px-3 py-2 border-b border-[#B87333]/15 bg-[#0a0a08]/80"
        role="progressbar"
        aria-valuemin={1}
        aria-valuemax={STEPS.length}
        aria-valuenow={stepIdx + 1}
      >
        <div className="flex items-center justify-between gap-2 max-w-2xl mx-auto">
          {STEPS.map((s, i) => {
            const isActive = s.key === state.step;
            const isPast = i < stepIdx;
            const Icon = s.key === 'site' ? Route : s.key === 'crew' ? Users : ClipboardCheck;
            return (
              <div key={s.key} className="flex items-center gap-2 flex-1 min-w-0">
                <button
                  type="button"
                  onClick={() => {
                    // Allow stepping back, not forward (forward must satisfy gates)
                    if (i <= stepIdx) {
                      audioManager.playSFX('nav');
                      dispatch({ type: 'goto_step', step: s.key });
                    }
                  }}
                  disabled={i > stepIdx}
                  className="flex items-center gap-1.5 disabled:cursor-default"
                >
                  <span
                    className="flex items-center justify-center rounded-full font-terminal text-[10px] transition"
                    style={{
                      width: 22,
                      height: 22,
                      border: `1.5px solid ${isActive ? '#CCAA00' : isPast ? '#B87333' : '#3a3a30'}`,
                      color: isActive ? '#CCAA00' : isPast ? '#B87333' : '#7a7060',
                      background: isActive ? 'rgba(204,170,0,0.08)' : 'transparent',
                    }}
                  >
                    {isPast ? '✓' : s.n}
                  </span>
                  <span
                    className="font-terminal text-[11px] sm:text-xs tracking-[0.15em] flex items-center gap-1"
                    style={{ color: isActive ? '#CCAA00' : isPast ? '#B87333' : '#5a5345' }}
                  >
                    <Icon size={11} />
                    <span className="hidden sm:inline">{s.label}</span>
                  </span>
                </button>
                {i < STEPS.length - 1 && (
                  <div
                    className="flex-1 h-[1px]"
                    style={{
                      background:
                        i < stepIdx
                          ? '#B87333'
                          : 'repeating-linear-gradient(90deg,#3a3a30 0 4px,transparent 4px 7px)',
                      opacity: 0.6,
                    }}
                  />
                )}
              </div>
            );
          })}
        </div>
      </div>

      {/* Step content */}
      <div
        className="flex-1 overflow-auto p-3 sm:p-4"
        style={{
          background:
            'radial-gradient(ellipse at 50% 0%, #1a1611 0%, #0a0a08 60%, #060604 100%)',
        }}
      >
        <div className="max-w-3xl mx-auto">
          <AnimatePresence mode="wait">
            {state.step === 'site' && (
              <motion.div
                key="site"
                initial={{ opacity: 0, x: -8 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: 8 }}
                transition={{ duration: 0.2 }}
              >
                <TravelMapPanel
                  selectedKey={state.selectedNodeKey}
                  completedMissionKeys={completedMissionKeys}
                  onSelect={(nodeKey) => {
                    const node = getNodeByKey(nodeKey);
                    if (!node) return;
                    // Auto-pick first unlocked location at this node
                    const loc = node.locationKeys
                      .map((k) => getDumpsterByKey(k))
                      .filter((l): l is DumpsterLocation =>
                        !!l && isDumpsterUnlocked(l, completedMissionKeys),
                      )[0];
                    if (loc) {
                      dispatch({ type: 'select_node', nodeKey, locationKey: loc.key });
                    }
                  }}
                />
              </motion.div>
            )}
            {state.step === 'crew' && selectedLocation && (
              <motion.div
                key="crew"
                initial={{ opacity: 0, x: -8 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: 8 }}
                transition={{ duration: 0.2 }}
              >
                <CrewRosterPanel
                  location={selectedLocation}
                  eligibleCrew={eligibleCrew}
                  assignedCrewIds={state.assignedCrewIds}
                  crewZones={crewZones}
                  onToggleCrew={(npcId) =>
                    dispatch({
                      type: 'toggle_crew',
                      npcId,
                      minCrew: selectedLocation.minCrew,
                      maxCrew: selectedLocation.maxCrew,
                    })
                  }
                />
              </motion.div>
            )}
            {state.step === 'review' && selectedLocation && validation && (
              <motion.div
                key="review"
                initial={{ opacity: 0, x: -8 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: 8 }}
                transition={{ duration: 0.2 }}
              >
                <MissionBriefPanel
                  location={selectedLocation}
                  crew={assignedCrew}
                  validation={validation}
                  sessionHeat={game?.heat ?? 0}
                  mobilityStat={(game as any)?.mobility ?? 2}
                  crewZones={crewZones}
                />
                {/* Directive activation toggle */}
                {eligibleDirective && (
                  <div
                    className="mt-3 p-3 rounded-[1px]"
                    style={{
                      background: activatedDirectiveKey ? 'rgba(204,170,0,0.08)' : 'rgba(10,10,9,0.6)',
                      border: `1px solid ${activatedDirectiveKey ? '#CCAA0060' : '#3a383020'}`,
                    }}
                  >
                    <button
                      type="button"
                      onClick={() => {
                        audioManager.playSFX('nav');
                        setActivatedDirectiveKey(
                          activatedDirectiveKey === eligibleDirective.npcKey ? null : eligibleDirective.npcKey,
                        );
                      }}
                      className="w-full flex items-center gap-3 text-left"
                    >
                      <span
                        className="w-4 h-4 rounded-[2px] flex-shrink-0 flex items-center justify-center text-[10px]"
                        style={{
                          border: `1.5px solid ${activatedDirectiveKey ? '#CCAA00' : '#5a5850'}`,
                          background: activatedDirectiveKey ? '#CCAA0025' : 'transparent',
                          color: activatedDirectiveKey ? '#CCAA00' : 'transparent',
                        }}
                      >
                        ✓
                      </span>
                      <div className="flex-1 min-w-0">
                        <p className="font-terminal text-[10px] tracking-[0.15em]" style={{ color: activatedDirectiveKey ? '#CCAA00' : '#8a8578' }}>
                          ACTIVATE DIRECTIVE: {eligibleDirective.card.title}
                        </p>
                        <p className="font-typewriter text-[9px] text-[#6a6558] mt-0.5">
                          {eligibleDirective.npcName}'s story. Extended run with authored sequence.
                        </p>
                      </div>
                    </button>
                  </div>
                )}
                {state.dispatchError && (
                  <p className="font-typewriter text-[11px] text-[#a8687e] italic mt-2 text-center">
                    {state.dispatchError}
                  </p>
                )}
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </div>

      {/* Footer nav */}
      <div className="flex items-center gap-2 px-3 py-3 border-t border-[#B87333]/25 bg-[#0a0a08]/95 backdrop-blur-[2px]">
        <button
          type="button"
          onClick={() => {
            audioManager.playSFX('nav');
            if (stepIdx <= 0) onBack();
            else dispatch({ type: 'goto_step', step: STEPS[stepIdx - 1].key });
          }}
          className="font-terminal text-xs tracking-[0.15em] text-[#8a8578] hover:text-[#CCAA00] transition-colors flex items-center gap-1.5 px-3 py-2 min-h-[44px] focus:outline-none"
        >
          <ArrowLeft size={14} /> {stepIdx === 0 ? 'EXIT' : 'BACK'}
        </button>
        <div className="flex-1" />
        {state.step !== 'review' ? (
          <motion.button
            type="button"
            whileTap={{ scale: 0.97 }}
            disabled={!canAdvance}
            onClick={() => {
              audioManager.playSFX('nav');
              dispatch({ type: 'goto_step', step: STEPS[stepIdx + 1].key });
            }}
            className="font-terminal text-sm tracking-[0.15em] flex items-center gap-2 px-4 py-2.5 min-h-[44px] disabled:opacity-30 disabled:cursor-not-allowed transition"
            style={{
              color: canAdvance ? '#CCAA00' : '#5a5345',
              border: `1px solid ${canAdvance ? '#CCAA00' : '#3a3a30'}`,
              background: canAdvance ? 'rgba(204,170,0,0.06)' : 'transparent',
              boxShadow: canAdvance ? '0 0 14px rgba(204,170,0,0.18)' : 'none',
            }}
          >
            NEXT <ArrowRight size={14} />
          </motion.button>
        ) : (
          <motion.button
            type="button"
            whileTap={{ scale: 0.97 }}
            disabled={!validation?.ok || state.dispatching}
            onClick={handleDispatch}
            className="font-terminal text-sm tracking-[0.18em] flex items-center gap-2 px-4 py-2.5 min-h-[44px] disabled:opacity-30 disabled:cursor-not-allowed transition"
            style={{
              color: validation?.ok ? '#c8dc96' : '#5a5345',
              border: `1px solid ${validation?.ok ? '#c8dc96' : '#3a3a30'}`,
              background: validation?.ok ? 'rgba(200,220,150,0.08)' : 'transparent',
              boxShadow: validation?.ok ? '0 0 18px rgba(200,220,150,0.22)' : 'none',
            }}
          >
            <Send size={14} /> {state.dispatching ? 'DISPATCHING…' : 'DISPATCH CREW'}
          </motion.button>
        )}
      </div>
    </div>
  );
}

