  gap: var(--space-3);
  align-items: center;
  justify-content: flex-start;
  padding: var(--space-3);
  color: var(--color-text-muted);
  font-family: var(--font-mono);
  font-size: var(--text-sm);
  text-align: left;
}

.nav-item span {
  color: var(--color-text-faint);
}

.nav-item:hover,
.nav-item.is-active {
  border-color: rgba(255, 75, 193, 0.55);
  background: var(--color-primary-soft);
  color: var(--color-text);
}

.sidebar-card {
  margin-top: auto;
  padding: var(--space-4);
  border: 1px dashed var(--color-border);
  border-radius: var(--radius-lg);
  background: rgba(0, 0, 0, 0.16);
  color: var(--color-text-muted);
  font-size: var(--text-sm);
}

.mode-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-3) var(--space-4);
  color: var(--color-text-muted);
  font-family: var(--font-mono);
  font-size: var(--text-sm);
}

.toggle-dot {
  width: 1rem;
  height: 1rem;
  border-radius: 50%;
  background: var(--color-secondary);
  box-shadow: 0 0 1rem var(--color-secondary);
}

.stage {
  min-width: 0;
  padding: var(--space-6);
}

.topbar {
  display: flex;
  gap: var(--space-4);
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--space-6);
}

.status-strip {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  justify-content: flex-end;
}

.status-pill {
  display: inline-flex;
  min-height: 2rem;
  align-items: center;
  border: 1px solid var(--color-border);
  border-radius: 999px;
  padding: 0 var(--space-3);
  background: rgba(0, 0, 0, 0.18);
  color: var(--color-text-muted);
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  font-weight: 700;
}

.status-pill.good {
  color: var(--color-secondary);
}

.status-pill.warn {
  color: var(--color-warning);
}

.status-pill.bad {
  color: var(--color-danger);
}

.screen {
  display: none;
  min-height: calc(100dvh - 9rem);
}

.screen.is-visible {
  display: block;
  animation: screenIn 220ms cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes screenIn {
  from {
    opacity: 0;
    transform: translateY(0.5rem);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.title-layout,
.hud-grid,
.recruit-layout,
.encounter-layout,
.travel-layout,
.codex-layout,
.sleep-layout,
.finale-layout,
.kit-layout {
  display: grid;
  gap: var(--space-6);
}

.title-layout,
.hud-grid,
.recruit-layout,
.encounter-layout,
.travel-layout,
.sleep-layout,
.finale-layout {
  grid-template-columns: minmax(0, 1.55fr) minmax(18rem, 0.75fr);
}

.hero-panel,
.scene-window,
.portrait-card,
.actor-sheet,
.dose-console,
.map-panel,
.document-panel,
.ritual-image,
.ritual-panel,
.finale-target,
.kit-card,
.stack-panel > *,
.route-card,
.hud-panel {
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  background: var(--color-surface);
  box-shadow: var(--shadow-panel);
  overflow: hidden;
}

.hero-panel,
.portrait-card,
.ritual-image,
.finale-target {
  position: relative;
  min-height: 34rem;
}

.hero-panel img,
.portrait-card img,
.ritual-image img,
.finale-target img {
  width: 100%;
  height: 100%;
  min-height: inherit;
  object-fit: cover;
  filter: saturate(0.9) contrast(1.08);
}

.hero-overlay,
.portrait-tag,
.ritual-progress,
.shutdown-readout {
  position: absolute;
  border: 1px solid var(--color-border);
  background: rgba(8, 8, 7, 0.74);
  backdrop-filter: blur(10px);
}

[data-theme='light'] .hero-overlay,
[data-theme='light'] .portrait-tag,
[data-theme='light'] .ritual-progress,
[data-theme='light'] .shutdown-readout {
  background: rgba(246, 232, 200, 0.84);
}

.hero-overlay {
  left: var(--space-6);
  bottom: var(--space-6);
  max-width: 36rem;
  padding: var(--space-6);
  border-radius: var(--radius-xl);
}

.hero-overlay p {
  max-width: 54ch;
  color: var(--color-text-muted);
}

.hero-overlay h3 {
  margin: var(--space-2) 0 var(--space-3);
  font-size: clamp(2.2rem, 5vw, 4.75rem);
  text-shadow:
    0.05em 0 var(--color-primary),
    -0.035em 0 var(--color-secondary);
}

.button-row {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-3);
  margin-top: var(--space-6);
}

.button-row.vertical {
  display: grid;
}

.primary-action,
.ghost-action {
  padding: var(--space-3) var(--space-5);
  font-weight: 700;
}

.primary-action {
  background: var(--color-primary);
  color: #160912;
  border-color: transparent;
}

.primary-action:hover {
  transform: translateY(-1px);
  box-shadow: 0 0 2rem var(--color-primary-soft);
}

.ghost-action:hover {
  border-color: var(--color-secondary);
  background: var(--color-secondary-soft);
}

.stack-panel {
  display: grid;
  gap: var(--space-4);
  align-content: start;
}

.template-note,
.save-card,
.hud-panel,
.actor-sheet,
.dose-console,
.route-card,
.document-panel,
.ritual-panel,
.kit-card {
  padding: var(--space-5);
}

.template-note p,
.save-card span,
.pressure-block p,
.helper-text,
.route-card dd,
.document-panel p,
.ritual-panel p,
.rule-list {
  color: var(--color-text-muted);
}

.save-card {
  display: grid;
  grid-template-columns: 4.5rem 1fr;
  gap: var(--space-4);
  align-items: center;
}

.save-card strong,
.save-card span {
  display: block;
}

.mini-cassette {
  height: 3rem;
  border: 2px solid currentColor;
  color: var(--color-paper);
  border-radius: var(--radius-sm);
  background:
    radial-gradient(circle at 32% 68%, transparent 0 0.36rem, currentColor 0.39rem 0.43rem, transparent 0.46rem),
    radial-gradient(circle at 68% 68%, transparent 0 0.36rem, currentColor 0.39rem 0.43rem, transparent 0.46rem);
}

.scene-window {
  position: relative;
  min-height: 38rem;
  background:
    linear-gradient(rgba(0, 0, 0, 0.15), rgba(0, 0, 0, 0.55)),
    linear-gradient(135deg, #201915 0 20%, #4a3b2b 20% 42%, #1d1b18 42% 60%, #554827 60% 100%);
}

.supermarket::before {
  content: 'SUPERMARKET';
  position: absolute;
  top: 12%;
  left: 7%;
  color: rgba(216, 199, 163, 0.16);
  font-family: var(--font-mono);
  font-size: clamp(2.5rem, 8vw, 8rem);
  font-weight: 700;
  letter-spacing: 0.08em;
}

.scene-label {
  position: absolute;
  z-index: 1;
  padding: var(--space-2) var(--space-3);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  background: rgba(0, 0, 0, 0.52);
  color: var(--color-secondary);
  font-family: var(--font-mono);
  font-size: var(--text-xs);
}

.top-left {
  top: var(--space-4);
  left: var(--space-4);
}

.top-right {
  top: var(--space-4);
  right: var(--space-4);
  color: var(--color-warning);
}

.bin-row {
  position: absolute;
  right: var(--space-8);
  bottom: var(--space-16);
  left: var(--space-8);
  display: grid;
  grid-template-columns: 1.4fr 1fr 0.8fr;
  gap: var(--space-4);
  align-items: end;
}

.dumpster {
  display: grid;
  min-height: 7rem;
  place-items: center;
  border: 1px solid rgba(216, 199, 163, 0.32);
  border-radius: var(--radius-md);
  background:
    linear-gradient(180deg, rgba(156, 255, 118, 0.12), transparent),
    #273029;
  color: var(--color-paper);
  font-family: var(--font-mono);
  font-weight: 700;
}

.dumpster.active {
  box-shadow: 0 0 0 2px var(--color-primary), 0 0 2rem var(--color-primary-soft);
}

.dumpster.locked {
  opacity: 0.42;
}

.crew-chips {
  position: absolute;
  left: var(--space-4);
  bottom: var(--space-4);
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
}

.crew-chips span {
  padding: var(--space-2) var(--space-3);
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.54);
  color: var(--color-paper);
  font-family: var(--font-mono);
  font-size: var(--text-xs);
}

.hud-panel {
  display: grid;
  gap: var(--space-5);
  align-content: start;
}

.meter-header {
  display: flex;
  justify-content: space-between;
  gap: var(--space-4);
  margin-bottom: var(--space-2);
  font-family: var(--font-mono);
}

.meter {
  height: 0.75rem;
  overflow: hidden;
  border: 1px solid var(--color-border);
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.22);
}

.meter span {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, var(--color-secondary), var(--color-warning), var(--color-danger));
}

.resource-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-3);
}

.resource-card {
  padding: var(--space-4);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  background: rgba(255, 255, 255, 0.04);
}

.resource-card span {
  display: block;
  color: var(--color-text-muted);
  font-size: var(--text-xs);
}

.resource-card strong {
  font-family: var(--font-mono);
  font-size: var(--text-xl);
}

.resource-card.danger strong {
  color: var(--color-danger);
}

.verb-bar {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-2);
}

.verb-bar button {
  padding: var(--space-2);
  color: var(--color-text-muted);
  font-family: var(--font-mono);
  font-size: var(--text-sm);
}

.verb-bar button:hover {
  border-color: var(--color-secondary);
  color: var(--color-text);
}

.recruit-layout {
  align-items: start;
}

.portrait-card {
  background: #28231f;
}

.portrait-card img {
  object-fit: contain;
  padding: var(--space-6);
}

.portrait-tag {
  right: var(--space-4);
  bottom: var(--space-4);
  left: var(--space-4);
  padding: var(--space-3);
  border-radius: var(--radius-md);
  color: var(--color-secondary);
  font-family: var(--font-mono);
  font-size: var(--text-sm);
}

.recruit-column {
  display: grid;
  gap: var(--space-4);
}

.step-tabs {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--space-2);
}

.step-tabs button,
.tag-cloud button,
.brain-grid button,
.dialogue-builder button {
  padding: var(--space-3);
  color: var(--color-text-muted);
  font-size: var(--text-sm);
}

.step-tabs button.is-active,
.step-tabs button:hover,
.tag-cloud button:hover,
.brain-grid button:hover,
.dialogue-builder button:hover {
  border-color: var(--color-primary);
  background: var(--color-primary-soft);
  color: var(--color-text);
}

.recruit-step {
  display: none;
  min-height: 28rem;
  padding: var(--space-5);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  background: var(--color-surface);
  box-shadow: var(--shadow-panel);
}

.recruit-step.is-visible {
  display: block;
}

.recruit-step h3 {
  margin-bottom: var(--space-5);
}

.tag-cloud,
.dialogue-builder {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-3);
  margin-bottom: var(--space-5);
}

.brain-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--space-3);
}

.brain-grid button {
  min-height: 6.5rem;
  font-family: var(--font-mono);
}

.brain-grid .core {
  border-color: var(--color-secondary);
  background: var(--color-secondary-soft);
  color: var(--color-secondary);
}

.line-preview {
  padding: var(--space-4);
  border-radius: var(--radius-lg);
  background: rgba(0, 0, 0, 0.22);
  color: var(--color-paper);
}

.encounter-layout {
  align-items: stretch;
}

.actor-head {
  display: flex;
  justify-content: space-between;
  gap: var(--space-4);
  margin-bottom: var(--space-6);
}

.stat-list {
  display: grid;
  gap: var(--space-4);
}

.stat-list label {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: var(--space-2);
  color: var(--color-text);
}

.stat-list label span {
  color: var(--color-text-muted);
  font-family: var(--font-mono);
  font-size: var(--text-xs);
}

meter {
  grid-column: 1 / -1;
  width: 100%;
  height: 0.75rem;
  accent-color: var(--color-primary);
}

.dose-console {
  display: grid;
  align-content: start;
  gap: var(--space-5);
}

.dose-track {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--space-3);
}

.dose {
  min-height: 8rem;
  padding: var(--space-3);
  font-family: var(--font-mono);
  font-weight: 700;
}

.dose.is-selected {
  border-color: var(--color-secondary);
  background: var(--color-secondary-soft);
  color: var(--color-secondary);
}

.dose-result {
  padding: var(--space-4);
  border-radius: var(--radius-lg);
  background: rgba(0, 0, 0, 0.2);
  color: var(--color-text-muted);
}

.dose-result strong {
  display: block;
  color: var(--color-text);
}

.substance-row {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-3);
}

.substance-row button {
  padding: var(--space-3);
  background: rgba(255, 255, 255, 0.045);
}

.substance-row .danger {
  border-color: rgba(255, 94, 87, 0.45);
  color: var(--color-danger);
}

.travel-layout {
  align-items: start;
}

.map-panel {
  position: relative;
  min-height: 38rem;
  background:
    linear-gradient(rgba(0, 0, 0, 0.28), rgba(0, 0, 0, 0.42)),
    repeating-linear-gradient(45deg, rgba(216, 199, 163, 0.055) 0 0.1rem, transparent 0.1rem 2.2rem),
    #171511;
}

[data-theme='light'] .map-panel {
  background:
    repeating-linear-gradient(45deg, rgba(55, 45, 36, 0.08) 0 0.1rem, transparent 0.1rem 2.2rem),
    #dfcda9;
}

.route-lines {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.route-lines path {
  fill: none;
  stroke: var(--color-paper-dim);
  stroke-width: 3;
  stroke-dasharray: 9 10;
}

.node {
  position: absolute;
  z-index: 1;
  display: grid;
  min-width: 7.5rem;
  min-height: 3rem;
  place-items: center;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  background: var(--color-surface-solid);
  color: var(--color-paper);
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  font-weight: 700;
  text-transform: uppercase;
}

.node.active {
  border-color: var(--color-primary);
  color: var(--color-primary);
  box-shadow: 0 0 2rem var(--color-primary-soft);
}

.node.locked {
  opacity: 0.42;
}

.node-house {
  left: 8%;
  top: 15%;
}

.node-store {
  left: 43%;
  top: 46%;
}

.node-bus {
  right: 11%;
  top: 17%;
}

.node-alley {
  right: 8%;
  bottom: 21%;
}

.node-payphone {
  left: 9%;
  bottom: 19%;
}

.node-overpass {
  right: 27%;
  top: 46%;
}

.travel-head {
  position: absolute;
  z-index: 2;
  left: 45%;
  top: 38%;
  color: var(--color-secondary);
  font-size: 3rem;
  filter: drop-shadow(0 0 1rem var(--color-secondary));
}

.route-card dl {
  display: grid;
  gap: var(--space-3);
  margin: var(--space-5) 0;
}

.route-card div {
  display: grid;
  grid-template-columns: 6rem 1fr;
  gap: var(--space-4);
}

.route-card dt {
  color: var(--color-text);
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  text-transform: uppercase;
}

.codex-layout {
  grid-template-columns: minmax(13rem, 0.42fr) minmax(0, 1fr);
  min-height: calc(100dvh - 9rem);
}

.codex-index {
  display: grid;
  gap: var(--space-2);
  align-content: start;
}

.codex-index button {
  justify-content: flex-start;
  padding: var(--space-3);
  text-align: left;
}

.codex-index .is-active {
  border-color: var(--color-warning);
  background: var(--color-warning-soft);
}

.document-panel {
  position: relative;
  max-width: 56rem;
  background:
    linear-gradient(90deg, rgba(0, 0, 0, 0.08), transparent 5rem),
    var(--color-surface);
}

.document-panel h3 {
  margin: var(--space-3) 0 var(--space-6);
}

.document-panel p + p {
  margin-top: var(--space-4);
}

.stamp {
  display: inline-flex;
  margin-top: var(--space-8);
  transform: rotate(-2deg);
  border: 2px solid var(--color-danger);
  padding: var(--space-2) var(--space-4);
  color: var(--color-danger);
  font-family: var(--font-mono);
  font-weight: 700;
}

.sleep-layout {
  align-items: stretch;
}

.ritual-progress {
  right: var(--space-4);
  bottom: var(--space-4);
  left: var(--space-4);
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: var(--space-2);
  padding: var(--space-3);
  border-radius: var(--radius-md);
}

.ritual-progress span {
  display: grid;
  min-height: 2.5rem;
  place-items: center;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  color: var(--color-text-faint);
  font-family: var(--font-mono);
  font-size: var(--text-xs);
}

.ritual-progress .complete {
  border-color: var(--color-secondary);
  color: var(--color-secondary);
}

.finale-layout {
  align-items: start;
}

.finale-target {
  background: #24201d;
}

.finale-target img {
  object-fit: contain;
  padding: var(--space-4);
}

.shutdown-readout {
  right: var(--space-4);
  bottom: var(--space-4);
  left: var(--space-4);
  display: grid;
  gap: var(--space-3);
  padding: var(--space-5);
  border-radius: var(--radius-lg);
}

.directive-stack {
  display: grid;
  gap: var(--space-3);
}

.directive-stack button {
  justify-content: flex-start;
  padding: var(--space-4);
  text-align: left;
}

.directive-stack .final {
  border-color: var(--color-secondary);
  background: var(--color-secondary-soft);
  color: var(--color-secondary);
}

.kit-layout {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.kit-card.wide {
  grid-column: 1 / -1;
}

.swatches {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: var(--space-3);
  margin-top: var(--space-4);
}

.swatches span {
  display: grid;
  min-height: 7rem;
  align-items: end;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-3);
  background: var(--swatch);
  color: #f4ecd8;
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  text-shadow: 0 1px 4px rgba(0, 0, 0, 0.7);
}

.rule-list {
  margin-top: var(--space-4);
  padding-left: var(--space-5);
}

.rule-list li + li {
  margin-top: var(--space-2);
}

.state-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--space-3);
  margin-top: var(--space-4);
}

.empty-state,
.error-state,
.loading-state {
  display: grid;
  gap: var(--space-2);
  min-height: 9rem;
  align-content: start;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: var(--space-4);
  background: rgba(0, 0, 0, 0.14);
}

.error-state {
  border-color: rgba(255, 94, 87, 0.35);
  background: var(--color-danger-soft);
}

.empty-state span,
.error-state span,
.loading-state span {
  color: var(--color-text-muted);
  font-size: var(--text-sm);
}

.skeleton-line {
  display: block;
  height: 0.85rem;
  border-radius: 999px;
  background: linear-gradient(90deg, rgba(216, 199, 163, 0.08), rgba(216, 199, 163, 0.24), rgba(216, 199, 163, 0.08));
  background-size: 200% 100%;
