'use client';

import { useState, useEffect, useCallback, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ArrowLeft, Radio, Scan, Target, FileText } from 'lucide-react';
import Image from 'next/image';

import { NPC_DATA, type NPCKey } from '@/lib/game-data';
import type { GameNPC, GameResource } from '@/lib/types';
import { getToleranceStatus } from '@/lib/game-engine';
import ObservationStage from './observation-stage';
import ParsingStage from './parsing-stage';
import TransactionStage from './transaction-stage';
import GiftOfferPanel from './gift-offer-panel';
import VHSDegradation from './vhs-degradation';
import { CigaretteIcon, AlcoholIcon, WeedIcon, CrystalIcon } from '@/app/_components/icons/resource-icons';
import Breadcrumb from '../ui/breadcrumb';
import { audioManager } from '@/app/_lib/audio-manager';
import { playIntakeAmbient, stopIntakeAudio } from './intake-audio';
import dynamic from 'next/dynamic';

const ComicViewer = dynamic(() => import('@/app/_components/directives/comic-viewer'), { ssr: false });

const ADMITTED_CUTSCENES: Record<string, { image: string; alt: string }[]> = {
  dave:   [{ image: '/images/cutscenes/admitted-dave.jpg',   alt: 'Dave sits on the floor, looking at his hands. He stopped resisting.' }],
  tamara: [{ image: '/images/cutscenes/admitted-tamara.jpg', alt: 'Tamara at the kitchen table. She was already there.' }],
  sid:    [{ image: '/images/cutscenes/admitted-sid.jpg',    alt: 'Sid in the doorway. His fists are open.' }],
  mikey:  [{ image: '/images/cutscenes/admitted-mikey.jpg',  alt: 'Mikey on his milk crate, mid-sermon. A cat at his feet.' }],
};

interface Props {
  npcId: string;
  npcs: GameNPC[];
  sessionId: string;
  resources: GameResource[];
  onBack: () => void;
  onComplete: () => void;
  showNotification: (msg: string) => void;
  refreshResources: () => void;
  escalationLevel?: number;
}

type RecruitStage = 'casefile' | 'transaction' | 'result';
type CaseFileTab = 'surveillance' | 'dissection';

const getNpcColor = (name: string): string => {
  const colors: Record<string, string> = { Dave: '#8aad7a', Sid: '#a8687e', Tamara: '#7ab8b8', Mikey: '#b0926a' };
  return colors[name] ?? '#8aad7a';
};

// Compliance descriptors replace raw affinity %
function getComplianceLabel(affinity: number): { text: string; color: string } {
  if (affinity >= 80) return { text: 'FULLY COMPLIANT', color: '#9cff76' };
  if (affinity >= 60) return { text: 'THEY\'RE YOURS', color: '#9cff76' };
  if (affinity >= 45) return { text: 'THEY NEED THIS', color: '#FFFF00' };
  if (affinity >= 30) return { text: 'THEY\'RE LISTENING', color: '#FFB000' };
  if (affinity >= 15) return { text: 'GUARDED', color: '#b87a96' };
  return { text: 'HOSTILE', color: '#a8687e' };
}

// Stage config — 2 main stages: CASE FILE (surveillance+dissection merged) → THE PITCH
const STAGE_CONFIG = {
  casefile:    { label: 'CASE FILE',  icon: FileText, color: '#8aad7a', idx: 0, audio: 'surveillance' as const },
  transaction: { label: 'THE PITCH',  icon: Target,   color: '#b87a96', idx: 1, audio: 'pitch' as const },
} as const;

// Sub-tab config within Case File
const CASEFILE_TABS = [
  { key: 'surveillance' as const, label: 'SURVEILLANCE', icon: Radio, color: '#8aad7a' },
  { key: 'dissection' as const,   label: 'DISSECTION',   icon: Scan,  color: '#7ab8b8' },
] as const;

// VHS intensity mapping: stage → corruption level
function getVHSIntensity(stage: RecruitStage, affinity: number): number {
  const base = stage === 'casefile' ? 0 : stage === 'transaction' ? 2 : 2;
  if (affinity >= 55 && stage === 'transaction') return 3;
  return base;
}

// Portrait filter for micro-reactions
function getPortraitFilter(hoveredOptionAffinity: number | null, stage: RecruitStage): string {
  const base = 'saturate(0.75) contrast(1.1) brightness(0.9)';
  if (stage !== 'transaction' || hoveredOptionAffinity === null) return base;
  if (hoveredOptionAffinity > 0) {
    // Empathetic hover — slight warm shift, subject leans in
    return 'saturate(0.85) contrast(1.05) brightness(0.95) hue-rotate(-5deg)';
  }
  if (hoveredOptionAffinity < 0) {
    // Exploitative hover — cold, desaturated, pulling away
    return 'saturate(0.5) contrast(1.2) brightness(0.75) hue-rotate(10deg)';
  }
  return base;
}

export default function RecruitmentFlow({ npcId, npcs, sessionId, resources, onBack, onComplete, showNotification, refreshResources, escalationLevel = 0 }: Props) {
  const [stage, setStage] = useState<RecruitStage>('casefile');
  const [casefileTab, setCasefileTab] = useState<CaseFileTab>('surveillance');
  const [affinity, setAffinity] = useState(0);
  const [parsingComplete, setParsingComplete] = useState(0);
  const [recruitResult, setRecruitResult] = useState<'success' | 'failure' | null>(null);
  // Pass 2: portrait micro-reaction state
  const [hoveredAffinity, setHoveredAffinity] = useState<number | null>(null);
  // Pass 2: zoom pulse trigger for surveillance feed
  const [zoomPulse, setZoomPulse] = useState(0);

  const npc = npcs?.find?.((n) => n?.id === npcId);
  const npcName = (npc?.name ?? '').toLowerCase() as NPCKey;
  const npcData = NPC_DATA?.[npcName];

  const hasFullData = (npcData?.transaction?.length ?? 0) > 0;

  // Phase-specific ambient audio
  useEffect(() => {
    if (stage === 'casefile') {
      // Switch audio within case file sub-tabs
      playIntakeAmbient(casefileTab === 'dissection' ? 'dissection' : 'surveillance');
    } else {
      const cfg = STAGE_CONFIG[stage as keyof typeof STAGE_CONFIG];
      if (cfg?.audio) {
        playIntakeAmbient(cfg.audio);
      } else {
        stopIntakeAudio();
      }
    }
  }, [stage, casefileTab]);

  // Cleanup audio on unmount
  useEffect(() => {
    return () => { stopIntakeAudio(); };
  }, []);

  const advanceStage = useCallback(async (newStage: RecruitStage) => {
    try {
      await fetch('/api/game/recruit', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ npcId, action: 'advance_stage' }),
      });
    } catch (err: unknown) {
      console.error('Advance stage error:', err);
    }
    setStage(newStage);
  }, [npcId]);

  const updateAffinity = useCallback(async (delta: number) => {
    const newAffinity = Math.max(0, Math.min(100, affinity + delta));
    setAffinity(newAffinity);
    try {
      await fetch('/api/game/recruit', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ npcId, action: 'add_affinity', value: delta }),
      });
    } catch (err: unknown) {
      console.error('Update affinity error:', err);
    }
  }, [npcId, affinity]);

  const [showAdmittedCutscene, setShowAdmittedCutscene] = useState(false);

  const completeRecruitment = useCallback(async (success: boolean) => {
    setRecruitResult(success ? 'success' : 'failure');
    stopIntakeAudio();
    if (success && npcName && ADMITTED_CUTSCENES[npcName.toLowerCase()]) {
      setShowAdmittedCutscene(true);
    } else {
      setStage('result');
    }
    if (success) {
      try {
        await fetch('/api/game/recruit', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ npcId, action: 'recruit' }),
        });
      } catch (err: unknown) {
        console.error('Complete recruit error:', err);
      }
    }
  }, [npcId, npcName]);

  // Cutscene complete → show result
  const handleCutsceneComplete = useCallback(() => {
    setShowAdmittedCutscene(false);
    setStage('result');
  }, []);

  // Pass 2: Gift callback — triggers zoom pulse
  const handleGiftGiven = useCallback((result: { newAffinity: number; affinityDelta: number }) => {
    setAffinity(result.newAffinity);
    refreshResources();
    // Trigger zoom pulse on surveillance feed
    setZoomPulse((p) => p + 1);
    if (result.affinityDelta > 0) {
      showNotification(`Compliance rising. +${result.affinityDelta}`);
    } else if (result.affinityDelta < 0) {
      showNotification(`Wrong substance. Compliance ${result.affinityDelta}`);
    } else {
      showNotification(`They took it. No visible reaction.`);
    }
  }, [refreshResources, showNotification]);

  if (!npc || !npcData) {
    return (
      <div className="w-full h-full flex items-center justify-center bg-[#080808]">
        <p className="text-[#a8687e] font-terminal">NPC data not found. Something broke.</p>
        <button onClick={() => { stopIntakeAudio(); onBack(); }} className="ml-4 text-[#8aad7a] underline text-sm">Go back</button>
      </div>
    );
  }

  const color = getNpcColor(npc?.name ?? '');
  const compliance = getComplianceLabel(affinity);
  const currentStageConfig = STAGE_CONFIG[stage as keyof typeof STAGE_CONFIG];
  const currentIdx = currentStageConfig?.idx ?? 0;
  const vhsIntensity = getVHSIntensity(stage, affinity);
  const portraitFilter = getPortraitFilter(hoveredAffinity, stage);

  return (
    <div className="w-full h-full flex flex-col bg-[#060606] relative">
      {/* ── VHS DEGRADATION OVERLAY — covers entire recruitment screen ── */}
      <VHSDegradation intensity={vhsIntensity} hue={currentStageConfig?.color ?? '#b87a96'} />

      {/* ── HEADER: INTAKE BANNER ── */}
      <div className="flex items-center justify-between px-4 py-2 bg-[#0a0a08] relative z-40" style={{ borderBottom: '1px solid rgba(255,75,193,0.15)' }}>
        <div className="flex items-center gap-3">
          <button onClick={() => { audioManager.playSFX('nav'); stopIntakeAudio(); onBack(); }} aria-label="Abort intake" className="text-[#b87a96] hover:text-[#b87a96]/80 cursor-pointer active:scale-90 transition focus:outline-none min-w-[44px] min-h-[44px] flex items-center justify-center">
            <ArrowLeft size={20} />
          </button>
          <div className="flex flex-col">
            <Breadcrumb
              items={[
                { label: 'HUB', onClick: () => { audioManager.playSFX('nav'); stopIntakeAudio(); onBack(); } },
                { label: 'CREW BOARD', onClick: () => { audioManager.playSFX('nav'); stopIntakeAudio(); onBack(); } },
                { label: 'INTAKE' },
              ]}
            />
            <h2 className="font-terminal text-base sm:text-lg tracking-wider mt-0.5" style={{ color }}>
              SUBJECT: {npc?.name?.toUpperCase?.() ?? 'UNKNOWN'}
            </h2>
          </div>
        </div>
        {/* Compliance readout */}
        <div className="flex flex-col items-end gap-0.5">
          <span className="font-terminal text-[9px] tracking-widest text-[#8a8578]">COMPLIANCE</span>
          <motion.span
            key={compliance.text}
            initial={{ opacity: 0, x: 8 }}
            animate={{ opacity: 1, x: 0 }}
            className="font-terminal text-xs tracking-wider"
            style={{ color: compliance.color }}
          >
            {compliance.text}
          </motion.span>
        </div>
      </div>

      {/* ── STAGE TABS ── */}
      <div className="grid grid-cols-2 bg-[#080807] relative z-40" style={{ borderBottom: '1px solid rgba(255,75,193,0.08)' }} role="navigation" aria-label="Intake progress">
        {(['casefile', 'transaction'] as const).map((s) => {
          const cfg = STAGE_CONFIG[s];
          const isActive = stage === s;
          const isPast = currentIdx > cfg.idx;
          const Icon = cfg.icon;
          return (
            <button
              key={s}
              className="py-2.5 font-terminal text-[10px] sm:text-xs tracking-wider transition-all flex items-center justify-center gap-1.5"
              style={{
                borderBottom: `2px solid ${isActive ? cfg.color : isPast ? `${cfg.color}33` : 'transparent'}`,
                color: isActive ? cfg.color : isPast ? `${cfg.color}88` : '#5a5a4a',
                background: isActive ? `${cfg.color}08` : 'transparent',
              }}
              aria-current={isActive ? 'step' : undefined}
              disabled
            >
              <Icon size={11} />
              {cfg.label}
            </button>
          );
        })}
      </div>

      {/* ── CASE FILE SUB-TABS ── */}
      {stage === 'casefile' && (
        <div className="flex bg-[#070706] relative z-40" style={{ borderBottom: '1px solid rgba(156,255,118,0.06)' }}>
          {CASEFILE_TABS.map((tab) => {
            const isActive = casefileTab === tab.key;
            const TabIcon = tab.icon;
            return (
              <button
                key={tab.key}
                onClick={() => { audioManager.playSFX('nav'); setCasefileTab(tab.key); }}
                className="flex-1 py-1.5 font-terminal text-[9px] tracking-widest transition-all flex items-center justify-center gap-1"
                style={{
                  borderBottom: `1px solid ${isActive ? tab.color : 'transparent'}`,
                  color: isActive ? tab.color : '#4a4a3a',
                  background: isActive ? `${tab.color}06` : 'transparent',
                }}
              >
                <TabIcon size={9} />
                {tab.label}
              </button>
            );
          })}
        </div>
      )}

      {/* ── COMPLIANCE VITAL SIGN ── */}
      <div className="h-2 bg-[#0a0a08] relative overflow-hidden z-40" role="meter" aria-valuenow={affinity} aria-valuemin={0} aria-valuemax={100} aria-label="Subject compliance level">
        <svg className="absolute inset-0 w-full h-full" preserveAspectRatio="none" viewBox="0 0 400 20">
          <motion.polyline
            points="0,10 40,10 50,10 55,3 60,17 65,10 80,10 120,10 130,10 135,3 140,17 145,10 160,10 200,10 210,10 215,3 220,17 225,10 240,10 280,10 290,10 295,3 300,17 305,10 320,10 360,10 370,10 375,3 380,17 385,10 400,10"
            fill="none"
            stroke={compliance.color}
            strokeWidth="1.5"
            strokeOpacity={0.15}
            animate={{ x: [-20, 0] }}
            transition={{ duration: 2, repeat: Infinity, ease: 'linear' }}
          />
        </svg>
        <motion.div
          className="absolute inset-y-0 left-0"
          animate={{ width: `${affinity}%` }}
          transition={{ duration: 0.6, ease: 'easeOut' }}
          style={{
            background: `linear-gradient(90deg, ${compliance.color}22, ${compliance.color}55)`,
            boxShadow: `0 0 12px ${compliance.color}33`,
          }}
        />
        <div className="absolute top-0 bottom-0 w-px" style={{ left: '60%', background: `${compliance.color}15` }} />
      </div>

      {/* ── TWO-COLUMN LAYOUT ── */}
      <div className="flex-1 overflow-auto relative z-40">
        <AnimatePresence mode="wait">
          {stage === 'result' ? (
            <motion.div
              key="result"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              className="flex flex-col items-center justify-center h-full p-8"
            >
              {recruitResult === 'success' ? (
                <>
                  <motion.div
                    initial={{ scale: 0, rotate: -10 }}
                    animate={{ scale: 1, rotate: 0 }}
                    transition={{ type: 'spring', damping: 12 }}
                    className="text-5xl mb-4 p-4 font-terminal"
                    style={{ border: '2px solid #9cff76', color: '#9cff76' }}
                  >
                    ADMITTED
                  </motion.div>
                  <p className="text-[#E8E8E8]/60 text-sm text-center max-w-md mt-2 font-typewriter">
                    {npc?.name ?? 'They'} has been processed. Another intake for the roster.
                    {npc?.name === 'Dave' ? ' He looks almost proud. Almost.' : ''}
                  </p>
                  <p className="text-[9px] font-terminal mt-2" style={{ color: compliance.color }}>
                    FINAL STATUS: {compliance.text}
                  </p>
                  <button
                    onClick={onComplete}
                    aria-label="Return to hub after intake"
                    className="mt-6 font-terminal px-8 py-3 border text-sm hover:bg-[#9cff76] hover:text-[#080808] transition min-h-[48px] cursor-pointer active:scale-95"
                    style={{ borderColor: '#9cff76', color: '#9cff76' }}
                  >
                    RETURN TO OPS
                  </button>
                </>
              ) : (
                <>
                  <motion.div
                    initial={{ scale: 0 }}
                    animate={{ scale: 1 }}
                    className="text-5xl mb-4 p-4 font-terminal"
                    style={{ border: '2px solid #a8687e', color: '#a8687e' }}
                  >
                    REJECTED
                  </motion.div>
                  <p className="text-[#E8E8E8]/60 text-sm text-center max-w-md font-typewriter">
                    Intake failed. {npc?.name ?? 'They'} saw through the pitch. Try a different angle.
                  </p>
                  <button
                    onClick={() => { stopIntakeAudio(); onBack(); }}
                    aria-label="Back to crew board after failed intake"
                    className="mt-6 font-terminal px-8 py-3 border border-[#a8687e] text-[#a8687e] hover:bg-[#a8687e] hover:text-[#080808] transition min-h-[48px] cursor-pointer active:scale-95"
                  >
                    BACK TO CREW BOARD
                  </button>
                </>
              )}
            </motion.div>
          ) : (
            <div key="recruit-layout" className="grid grid-cols-1 md:grid-cols-[260px_1fr] gap-0 h-full">
              {/* LEFT: SUBJECT FILE */}
              <aside className="bg-[#0c0b08] p-3 hidden md:flex flex-col gap-3 overflow-y-auto" style={{ borderRight: '1px solid rgba(255,75,193,0.08)' }}>
                {/* Portrait — with micro-reaction filter */}
                <div className="relative w-full aspect-[3/4] bg-[#060606] overflow-hidden" style={{ border: '1px solid rgba(255,75,193,0.12)' }}>
                  <motion.div
                    className="absolute inset-0"
                    animate={{
                      scale: hoveredAffinity !== null ? (hoveredAffinity > 0 ? 1.02 : 0.98) : 1,
                    }}
                    transition={{ duration: 0.4, ease: 'easeOut' }}
                  >
                    <Image
                      src={npc?.portraitUrl || npcData?.portraitUrl || '/images/dave-portrait-v2-crop.png'}
                      alt={`Intake subject: ${npc?.name ?? 'NPC'}`}
                      fill
                      sizes="260px"
                      className="object-cover transition-all duration-500"
                      style={{ filter: portraitFilter }}
                    />
                  </motion.div>
                  {/* Scanline overlay */}
                  <div className="absolute inset-0 pointer-events-none" style={{
                    backgroundImage: 'repeating-linear-gradient(0deg, rgba(0,0,0,0) 0px, rgba(0,0,0,0) 2px, rgba(0,0,0,0.2) 3px)',
                    mixBlendMode: 'multiply',
                  }} />
                  <div className="absolute inset-0 bg-gradient-to-t from-[#0c0b08] via-transparent to-transparent" />
                  {/* REC indicator */}
                  <div className="absolute top-2 left-2 flex items-center gap-1.5">
                    <motion.div
                      animate={{ opacity: [1, 0.2, 1] }}
                      transition={{ duration: 1.5, repeat: Infinity }}
                      className="w-1.5 h-1.5 rounded-full bg-red-500"
                    />
                    <span className="font-terminal text-[8px] text-red-400/80 tracking-wider">REC</span>
                  </div>
                  <div className="absolute bottom-2 right-2 font-terminal text-[8px] text-[#b9aa8a]/60">
                    CAM-04 · INTAKE
                  </div>
                  {/* Pass 2: Micro-reaction overlay flash */}
                  <AnimatePresence>
                    {hoveredAffinity !== null && hoveredAffinity < 0 && (
                      <motion.div
                        key="recoil"
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 0.08 }}
                        exit={{ opacity: 0 }}
                        className="absolute inset-0"
                        style={{ background: '#a8687e', mixBlendMode: 'color' }}
                      />
                    )}
                    {hoveredAffinity !== null && hoveredAffinity > 0 && (
                      <motion.div
                        key="lean-in"
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 0.06 }}
                        exit={{ opacity: 0 }}
                        className="absolute inset-0"
                        style={{ background: '#9cff76', mixBlendMode: 'soft-light' }}
                      />
                    )}
                  </AnimatePresence>
                </div>

                {/* Subject tag */}
                <div className="font-bmf-mono text-[10px] px-2.5 py-1.5 bg-[#060606]" style={{ border: `1px solid ${color}35`, color }}>
                  <span className="text-[#8a8578]">SUBJ:</span> {(npc?.name ?? 'UNKNOWN').toUpperCase()} · {(npc?.role ?? npc?.archetype ?? '').toUpperCase()}
                </div>

                {/* Quick stats */}
                <div className="space-y-1.5 text-[9px] font-terminal">
                  <div className="text-[8px] text-[#b87a96]/70 tracking-widest mb-1">CAPABILITY PROFILE</div>
                  {[
                    { label: 'HEAT', value: npc?.heatLevel ?? 0 },
                    { label: 'MUSCLE', value: npc?.muscle ?? 0 },
                    { label: 'BRAINS', value: npc?.brains ?? 0 },
                    { label: 'UNPREDICT.', value: npc?.unpredictability ?? 0 },
                  ].map((s) => (
                    <div key={s.label} className="flex items-center gap-2">
                      <span className="text-[#c8c4b8]/60 w-16">{s.label}</span>
                      <div className="flex-1 h-1.5 bg-[#1a1a0a] relative rounded-sm">
                        <div className="absolute inset-y-0 left-0 rounded-sm" style={{ width: `${(s.value / 10) * 100}%`, backgroundColor: color, opacity: 0.8 }} />
                      </div>
                      <span style={{ color }} className="w-4 text-right font-bold">{s.value}</span>
                    </div>
                  ))}
                </div>

                {/* Tolerance profile */}
                <div className="space-y-1.5 pt-2" style={{ borderTop: '1px solid rgba(255,75,193,0.12)' }}>
                  <div className="text-[8px] text-[#b87a96]/70 tracking-widest font-terminal">SUBSTANCE TOLERANCE</div>
                  {[
                    { label: 'CIGS', value: npc?.toleranceCigs ?? 0, icon: <CigaretteIcon size={10} color="#c8dc96" /> },
                    { label: 'ALC', value: npc?.toleranceAlc ?? 0, icon: <AlcoholIcon size={10} color="#c79a5a" /> },
                    { label: 'WEED', value: npc?.toleranceWeed ?? 0, icon: <WeedIcon size={10} color="#8aad7a" /> },
                    { label: 'CRYST', value: npc?.toleranceCryst ?? 0, icon: <CrystalIcon size={10} color="#7ab8b8" /> },
                  ].map((t) => {
                    const status = getToleranceStatus(t.value);
                    return (
                      <div key={t.label} className="flex items-center gap-1.5">
                        <span className="inline-flex">{t.icon}</span>
                        <span className="text-[8px] text-[#c8c4b8]/60 w-8 font-terminal">{t.label}</span>
                        <div className="flex-1 h-1.5 bg-[#1a1a0a] relative rounded-sm">
                          <div className="absolute inset-y-0 left-0 rounded-sm" style={{ width: `${(t.value / 10) * 100}%`, backgroundColor: status?.color ?? '#8aad7a', opacity: 0.8 }} />
                        </div>
                      </div>
                    );
                  })}
                </div>
              </aside>

              {/* RIGHT: STAGE CONTENT */}
              <div className="flex-1 overflow-auto">
                <AnimatePresence mode="wait">
                  {stage === 'casefile' && casefileTab === 'surveillance' && (
                    <ObservationStage
                      key="obs"
                      npcData={npcData}
                      npc={npc}
                      affinity={affinity}
                      escalationLevel={escalationLevel}
                      zoomPulse={zoomPulse}
                      onAdvance={() => {
                        audioManager.playSFX('nav');
                        setCasefileTab('dissection');
                      }}
                    />
                  )}
                  {stage === 'casefile' && casefileTab === 'dissection' && (
                    <ParsingStage
                      key="parse"
                      npcData={npcData}
                      progress={parsingComplete}
                      onProgress={(n: number) => setParsingComplete(n)}
                      onAdvance={() => {
                        if (hasFullData) {
                          advanceStage('transaction');
                        } else {
                          showNotification(`${npc?.name}'s full intake coming in Phase 2. Auto-admitting...`);
                          completeRecruitment(true);
                        }
                      }}
                    />
                  )}
                  {stage === 'transaction' && (
                    <TransactionStage
                      key="trans"
                      npcData={npcData}
                      affinity={affinity}
                      onAffinityChange={updateAffinity}
                      onComplete={completeRecruitment}
                      onHoverOption={setHoveredAffinity}
                    />
                  )}
                </AnimatePresence>
              </div>
            </div>
          )}
        </AnimatePresence>
      </div>

      {/* ── VICE OFFERING PANEL ── */}
      {stage !== 'result' && npcData?.vice && (
        <GiftOfferPanel
          npcName={npc?.name ?? ''}
          npcKey={npcName}
          npcId={npcId}
          vice={npcData.vice}
          sessionId={sessionId}
          resources={resources}
          hasObservedCravings={stage !== 'casefile' || casefileTab === 'dissection'}
          escalationLevel={escalationLevel}
          onGiftGiven={handleGiftGiven}
        />
      )}

      {/* Admitted cutscene — plays once before result screen */}
      {showAdmittedCutscene && npcName && ADMITTED_CUTSCENES[npcName.toLowerCase()] && (
        <ComicViewer
          panels={ADMITTED_CUTSCENES[npcName.toLowerCase()]}
          onComplete={handleCutsceneComplete}
          sequenceLabel={`${npc?.name?.toUpperCase() ?? 'SUBJECT'} — ADMITTED`}
        />
      )}
    </div>
  );
}

