'use client'

import { memo } from 'react'
import { motion } from 'framer-motion'
import { CrucifixGlyph } from './overlay-lock'

// Four public panes: Trilogy overview → Gallery → Hero → Pitch Deck, then the
// VIP station (+2) behind the 3K Overlay lock (./vip-lock).
const STATIONS = [
  { id: 'trilogy', label: 'TRILOGY', short: 'TRILOGY', pos: '-2' },
  { id: 'tone', label: 'GALLERY', short: 'GALLERY', pos: '-1' },
  { id: 'hero', label: 'HOME', short: 'HOME', pos: '0' },
  { id: 'documents', label: 'PITCH DECK', short: 'DECK', pos: '+1' },
  { id: 'vip', label: 'VIP', short: 'VIP', pos: '+2' },
] as const

export type TabId = (typeof STATIONS)[number]['id']

interface TabNavigatorProps {
  activeStation: TabId
  onStationChange: (id: TabId) => void
}

function TabNavigatorInner({ activeStation, onStationChange }: TabNavigatorProps) {
  return (
    <nav
      className="station-nav relative z-40 w-full"
      role="tablist"
      aria-label="Main navigation"
    >
      {/* Top border line */}
      <div className="hairline-x" />

      <div className="flex items-stretch overflow-x-auto scrollbar-hide">
        {/* Route mark — the burning crucifix-lock */}
        <div
          className="hidden sm:flex items-center justify-center px-4 shrink-0"
          title="3K OVERLAY / LOCK"
        >
          <CrucifixGlyph size={28} animate={false} />
        </div>

        {STATIONS.map((station) => {
          const isActive = activeStation === station.id
          const isCentre = station.id === 'hero'
          const accent = isCentre ? '#D4FF3D' : '#B8F026'
          return (
            <button
              key={station.id}
              role="tab"
              aria-selected={isActive}
              aria-label={station.label}
              onClick={() => onStationChange?.(station.id)}
              className={`
                station-tab relative flex-1 min-w-0 flex items-center justify-center gap-1.5
                px-2 md:px-4 py-2.5 md:py-3
                text-[10px] md:text-[11px] uppercase tracking-label
                transition-all duration-200 active:translate-y-[0.5px]
                border-r border-[#B8F02608]
                focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-[#B8F026]
                ${isActive
                  ? 'bg-[#B8F02612]'
                  : 'opacity-75 hover:opacity-100 hover:bg-[#B8F02608]'
                }
              `}
              style={{ color: isActive ? accent : '#E8E4D9' }}
            >
              <span className="station-label">{station.label}</span>
              {/* Active indicator bar — slides between stations */}
              {isActive && (
                <motion.div
                  layoutId="tab-active-bar"
                  className="absolute bottom-0 left-2 right-2 h-[2px]"
                  style={{ background: accent }}
                  transition={{ type: 'spring', stiffness: 400, damping: 32 }}
                />
              )}
            </button>
          )
        })}
      </div>

      {/* Bottom border line */}
      <div className="hairline-x opacity-60" />
    </nav>
  )
}

const TabNavigator = memo(TabNavigatorInner)
export default TabNavigator
export { STATIONS }

