// scripts/backfill-npc-stats.ts — v0.5.7
//
// One-off backfill for the combat stat triad (muscle / brains / unpredictability).
//
// WHO NEEDS THIS:
//   Players who started a session before stats were authored — their NPC rows
//   have muscle=0, brains=0, unpredictability=0, which would make every combat
//   roll a guaranteed loss. This script copies the canonical values from
//   NPC_DATA into any NPC row where ALL three stat fields are 0.
//
// SAFETY:
//   - upsert-style: only touches rows where (muscle+brains+unpredictability) === 0
//   - never lowers a value
//   - never deletes anything (forbidden by safe-seed.ts anyway)
//   - matches by NPC.name, falls back to skipping unknown names
//
// HOW TO RUN:
//   cd nextjs_space
//   yarn tsx --require dotenv/config scripts/backfill-npc-stats.ts
//
// IDEMPOTENT: safe to run multiple times. After first run, all rows already
// have non-zero stats and the script will report "0 rows updated."

import { PrismaClient } from '@prisma/client';
import { NPC_DATA } from '../lib/game-data';

const prisma = new PrismaClient();

async function main(): Promise<void> {
  const candidates = await prisma.nPC.findMany({
    select: {
      id: true,
      name: true,
      muscle: true,
      brains: true,
      unpredictability: true,
    },
  });

  let updated = 0;
  let skippedKnownGood = 0;
  let skippedUnknown = 0;

  for (const npc of candidates) {
    // Already has stats? Leave alone.
    if ((npc.muscle ?? 0) + (npc.brains ?? 0) + (npc.unpredictability ?? 0) > 0) {
      skippedKnownGood++;
      continue;
    }

    // Look up the canonical seed by name. NPC_DATA keys are lowercase ids; the
    // name on the row is the human-readable name (e.g. 'Sid'). Match by name.
    const canonical = Object.values(NPC_DATA).find(
      (n: any) => n.name === npc.name,
    ) as any;

    if (!canonical) {
      console.warn(`  skip   ${npc.name.padEnd(12)} (no canonical entry in NPC_DATA)`);
      skippedUnknown++;
      continue;
    }

    await prisma.nPC.update({
      where: { id: npc.id },
      data: {
        muscle: canonical.muscle ?? 0,
        brains: canonical.brains ?? 0,
        unpredictability: canonical.unpredictability ?? 0,
      },
    });
    console.log(
      `  patch  ${npc.name.padEnd(12)} → ` +
      `M:${canonical.muscle} B:${canonical.brains} U:${canonical.unpredictability}`,
    );
    updated++;
  }

  console.log('');
  console.log(`Done. updated=${updated}  alreadyOK=${skippedKnownGood}  unknown=${skippedUnknown}`);
}

main()
  .catch((err) => {
    console.error('Backfill failed:', err);
    process.exitCode = 1;
  })
  .finally(async () => {
    await prisma.$disconnect();
  });

