function getQuote(level: number): string {
  const bracket = level >= 8 ? 8 : level >= 6 ? 6 : level >= 4 ? 4 : level >= 2 ? 2 : 0;
  const quotes = QUOTES[bracket] ?? QUOTES[0];
  return quotes[level % quotes.length] ?? quotes[0];
}

