function getCrewComment(npcs: GameState['npcs'], escalationLevel: number, day: number): { name: string; comment: string } | null {
  const recruited = (npcs ?? []).filter((n) => n?.recruited && n?.name);
  if (recruited.length === 0) return null;
  // Pick deterministic NPC based on day
  const npc = recruited[Math.abs(day) % recruited.length];
  const name = npc.name ?? '';
  const pool = CREW_COMMENTS[name];
  if (!pool) return null;
  const bracket = escalationLevel >= 6 ? 6 : escalationLevel >= 3 ? 3 : 0;
  const lines = pool[bracket] ?? pool[0];
  const comment = lines[Math.abs(day) % lines.length];
  return { name, comment };
}

export default function DayEndScreen({ game, escalation, onContinue, consumption }: Props) {
  const [printProgress, setPrintProgress] = useState(0);
  const [showButton, setShowButton] = useState(false);

  const resources = game?.resources ?? [];
  const getRes = (type: string) => resources.find((r) => r?.type === type)?.quantity ?? 0;
  const recruitedCount = (game?.npcs ?? []).filter((n) => n?.recruited).length;
  const totalTolerance = (game?.npcs ?? []).reduce((sum: number, n) => {
    return sum + (n?.toleranceCigs ?? 0) + (n?.toleranceAlc ?? 0) + (n?.toleranceWeed ?? 0) + (n?.toleranceCryst ?? 0);
  }, 0);
  const expeditionCount = game?.expeditions?.length ?? 0;

  // Crew consumption display — the "crackhead tax" applied during the night cycle.
  const hasConsumption = !!consumption && (consumption.consumed ?? []).some((c) => c.actual > 0);
  const totalConsumed = (consumption?.consumed ?? []).reduce((s, c) => s + c.actual, 0);

  // Receipt content is now dynamic depending on whether consumption applied.
  const crewNote = getCrewComment(game?.npcs ?? [], escalation.level, game?.day ?? 1);

  const receiptLines: Array<{ text: string; style: string; render?: 'resources' | 'consumption' | 'crew_note' }> = [
    { text: '================================', style: 'divider' },
    { text: `  BAF3K DAY SUMMARY REPORT`, style: 'header' },
    { text: `  DAY ${game?.day ?? 1} — POST-SHIFT AUDIT`, style: 'subheader' },
    { text: '================================', style: 'divider' },
    { text: `  CREW ACTIVE:      ${recruitedCount}/4`, style: 'stat' },
    { text: `  HEAT LEVEL:       ${(game?.heat ?? 0).toFixed(1)}`, style: (game?.heat ?? 0) > 5 ? 'danger' : 'stat' },
    { text: `  EXPEDITIONS:      ${expeditionCount}`, style: 'stat' },
    { text: `  TOTAL TOLERANCE:  ${totalTolerance.toFixed(1)}`, style: totalTolerance > 10 ? 'warning' : 'stat' },
    { text: '--------------------------------', style: 'divider' },
    { text: '  OVERNIGHT CONSUMPTION', style: 'section' },
    { text: '', style: 'consumption', render: 'consumption' },
    { text: '--------------------------------', style: 'divider' },
    { text: '  RESOURCES REMAINING', style: 'section' },
    { text: '', style: 'resources', render: 'resources' },
    { text: '--------------------------------', style: 'divider' },
    { text: `  STATUS: ${escalation.titleEscalation}`, style: 'title' },
    { text: `  NEXT SHIFT: DAY ${(game?.day ?? 1) + 1}`, style: 'stat' },
    { text: '================================', style: 'divider' },
    { text: `  "${getQuote(escalation.level)}"`, style: 'quote' },
    // Crew commentary — one recruited NPC speaks at the bottom of the receipt
    ...(crewNote ? [
      { text: '--------------------------------', style: 'divider' },
      { text: '', style: 'crew_note', render: 'crew_note' as const },
    ] : []),
  ];
  const totalLines = receiptLines.length;

  // Simulate receipt printing — line by line reveal
  useEffect(() => {
    const interval = setInterval(() => {
      setPrintProgress(prev => {
        if (prev >= totalLines) {
          clearInterval(interval);
          return prev;
        }
        return prev + 1;
      });
    }, 200);
    return () => clearInterval(interval);
  }, [totalLines]);

  useEffect(() => {
    if (printProgress >= totalLines) {
      setTimeout(() => setShowButton(true), 700);
    }
  }, [printProgress, totalLines]);

  return (
    <div className="w-full h-full bg-[#080808] texture-receipt-bg flex items-center justify-center overflow-auto p-4" role="region" aria-label="Day end report">
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="max-w-md sm:max-w-lg w-full"
      >
        {/* Receipt paper */}
        <div
          className="mx-auto relative"
          style={{
            background: '#e8e0c8',
            padding: '20px 16px',
            fontFamily: 'monospace',
            boxShadow: '0 4px 20px rgba(0,0,0,0.5)',
            // Torn top edge
            clipPath: 'polygon(0 2%, 3% 0, 6% 1.5%, 9% 0.5%, 12% 2%, 15% 0, 18% 1%, 21% 2%, 24% 0, 27% 1.5%, 30% 0.5%, 33% 2%, 36% 0, 39% 1.5%, 42% 0, 45% 2%, 48% 0.5%, 51% 1.5%, 54% 0, 57% 2%, 60% 0.5%, 63% 1%, 66% 2%, 69% 0, 72% 1.5%, 75% 0.5%, 78% 2%, 81% 0, 84% 1%, 87% 2%, 90% 0, 93% 1.5%, 96% 0.5%, 100% 2%, 100% 98%, 97% 100%, 94% 98.5%, 91% 100%, 88% 99%, 85% 100%, 82% 98%, 79% 100%, 76% 99%, 73% 100%, 70% 98.5%, 67% 100%, 64% 99%, 61% 100%, 58% 98%, 55% 100%, 52% 99.5%, 49% 100%, 46% 98%, 43% 100%, 40% 99%, 37% 100%, 34% 98.5%, 31% 100%, 28% 99%, 25% 100%, 22% 98%, 19% 100%, 16% 99%, 13% 100%, 10% 98.5%, 7% 100%, 4% 99%, 1% 100%, 0 98%)',
          }}
        >
          {/* Print head noise */}
          {printProgress < totalLines && (
            <motion.div
              animate={{ opacity: [0.3, 0.8, 0.3] }}
              transition={{ duration: 0.3, repeat: Infinity }}
              className="absolute left-0 right-0 h-[2px] bg-[#333]/20"
              style={{ top: `${(printProgress / totalLines) * 100}%` }}
            />
          )}

          <div className="space-y-0.5">
            {receiptLines.map((line, i) => {
              if (i >= printProgress) return <div key={i} className="h-4" />;

              // Consumption — the crackhead tax.  Shows deductions with minus signs.
              if (line.render === 'consumption') {
                if (!hasConsumption) {
                  return (
                    <motion.div
                      key={i}
                      initial={{ opacity: 0 }}
                      animate={{ opacity: 1 }}
                      transition={{ duration: 0.1 }}
                      className="font-terminal px-2 py-0.5 italic"
                      style={{ color: '#666', fontSize: '12px', lineHeight: '1.4' }}
                    >
                      {consumption && consumption.crewSize === 0
                        ? '  (no crew — no consumption)'
                        : '  (crew held back tonight)'}
                    </motion.div>
                  );
                }
                const rows = consumption!.consumed.filter((c) => c.actual > 0);
                return (
                  <motion.div
                    key={i}
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    transition={{ duration: 0.1 }}
                    className="font-terminal flex flex-wrap items-center gap-x-4 gap-y-1 px-2 py-0.5"
                    style={{ color: '#8B0000', fontSize: '13px', lineHeight: '1.4' }}
                  >
                    {rows.map((row) => {
                      const Icon =
                        row.type === 'cigarettes'
                          ? CigaretteIcon
                          : row.type === 'alcohol'
                          ? AlcoholIcon
                          : row.type === 'weed'
                          ? WeedIcon
                          : CrystalIcon;
                      return (
                        <span key={row.type} className="inline-flex items-center gap-1">
                          <Icon size={13} color="#8B0000" />
                          <span>−{row.actual}</span>
                        </span>
                      );
                    })}
                    {consumption && consumption.mitigationPct > 0 && (
                      <span className="text-[11px] text-[#5a5a3a] italic ml-2">
                        (CON saved {consumption.mitigationPct}%)
                      </span>
                    )}
                  </motion.div>
                );
              }

              // Crew commentary — a recruited NPC mutters something at the end
              if (line.render === 'crew_note' && crewNote) {
                return (
                  <motion.div
                    key={i}
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    transition={{ duration: 0.3 }}
                    className="font-caveat px-2 py-1"
                    style={{ color: '#5a4a2a', fontSize: '14px', lineHeight: '1.5' }}
                  >
                    <span className="font-terminal text-[10px] text-[#8a8a6a] uppercase tracking-wider block mb-0.5">
                      — {crewNote.name} scrawled on the back:
                    </span>
                    <span className="italic">&quot;{crewNote.comment}&quot;</span>
                  </motion.div>
                );
              }

              // Resources line rendered as JSX with icons (no emoji)
              if (line.render === 'resources') {
                return (
                  <motion.div
                    key={i}
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    transition={{ duration: 0.1 }}
                    className="font-terminal flex items-center gap-4 px-2 py-0.5"
                    style={{ color: '#333', fontSize: '13px', lineHeight: '1.4' }}
                  >
                    <span className="inline-flex items-center gap-1"><CigaretteIcon size={13} color="#333" />{getRes('cigarettes')}</span>
                    <span className="inline-flex items-center gap-1"><AlcoholIcon size={13} color="#333" />{getRes('alcohol')}</span>
                    <span className="inline-flex items-center gap-1"><WeedIcon size={13} color="#333" />{getRes('weed')}</span>
                    <span className="inline-flex items-center gap-1"><CrystalIcon size={13} color="#333" />{getRes('crystals')}</span>
                  </motion.div>
                );
              }

              let textColor = '#333';
              let fontSize = '13px';
              let fontWeight = 'normal';

              if (line.style === 'header') { fontWeight = 'bold'; fontSize = '15px'; }
              if (line.style === 'subheader') { textColor = '#555'; fontSize = '12px'; }
              if (line.style === 'divider') { textColor = '#999'; fontSize = '12px'; }
              if (line.style === 'section') { textColor = '#2a2a10'; fontWeight = 'bold'; fontSize = '11px'; }
              if (line.style === 'danger') { textColor = '#8B0000'; }
              if (line.style === 'warning') { textColor = '#8B6914'; }
              if (line.style === 'title') { textColor = '#2a2a10'; fontWeight = 'bold'; }
              if (line.style === 'quote') { textColor = '#5a5a3a'; fontSize = '12px'; }

              return (
                <motion.div
                  key={i}
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  transition={{ duration: 0.1 }}
                  style={{ color: textColor, fontSize, fontWeight, lineHeight: '1.4' }}
                  className="font-terminal whitespace-pre"
                >
                  {line.text}
                </motion.div>
              );
            })}
          </div>

          {/* Coffee ring stain */}
          <div className="absolute top-8 right-4 w-12 h-12 rounded-full border-2 border-[#8B4513]/10 opacity-40" />
        </div>

        {/* Day advance — appears after receipt prints */}
        {showButton && (
          <motion.button
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            onClick={() => { audioManager.playSFX('nav'); playDayAdvance(); onContinue(); }}
            className="bmf-btn w-full mt-6 py-3 font-bmf-mono text-sm active:scale-95 cursor-pointer focus:outline-none focus-visible:ring-1 focus-visible:ring-[#8aad7a]/60"
            style={{
              borderColor: 'var(--bmf-amber)',
              color: 'var(--bmf-amber)',
              boxShadow: '0 0 12px rgba(255,178,95,0.12)',
            }}
          >
            BEGIN DAY {(game?.day ?? 1) + 1} {'>'}
          </motion.button>
        )}
      </motion.div>
    </div>
  );
}

'use client'

import { useCallback, useEffect, useMemo, useState } from 'react'
import { signOut } from 'next-auth/react'
import { toast } from 'sonner'
import { haptic } from '@/lib/haptics'
import { SITE_FIELDS, type SiteContentMap, type SiteField, type SiteKey } from '@/lib/site-defaults'
import { GameEditor, type AdminGame } from './game-editor'
import { HeroEditor, Toggle } from './hero-editor'
