type Tab = 'units' | 'gallery' | 'heroes' | 'text' | 'look' | 'access'
const TABS: { id: Tab; label: string; blurb: string }[] = [
  { id: 'units', label: 'UNITS', blurb: 'Games & apps: art, links, order, locks. Unit edits save per unit.' },
  { id: 'gallery', label: 'GALLERY', blurb: 'Art behind the cog: upload, order and remove hero gallery images. Saves instantly, live without a redeploy.' },
  { id: 'heroes', label: 'PAGE HEROES', blurb: 'The top band of each page: copy, background, colours, layout, button, motion.' },
  { id: 'text', label: 'SITE TEXT', blurb: 'Every visitor-facing label outside the heroes.' },
  { id: 'look', label: 'LOOK & LAYOUT', blurb: 'Layout and atmosphere switches.' },
  { id: 'access', label: 'ACCESS', blurb: 'Unit locks. Locked units open through the seal on /profile.' },
]

const TEXT_SECTIONS: { title: string; match: (k: string) => boolean }[] = [
  { title: 'HOME FEATURE', match: (k) => /^(overline|titleLine|tagline|ctaLabel)/.test(k) },
  { title: 'GAMES & APPS', match: (k) => k.startsWith('archive') },
  { title: 'CONTACT', match: (k) => k.startsWith('contact') },
  { title: 'NAVIGATION', match: (k) => k.startsWith('nav') },
  { title: 'FOOTER', match: (k) => k.startsWith('footer') },
  { title: 'UNIT BUTTONS', match: () => true },
]

export function AdminConsole({ email }: { email: string }) {
  const [tab, setTab] = useState<Tab>('units')
  const [games, setGames] = useState<AdminGame[] | null>(null)
  const [content, setContent] = useState<SiteContentMap | null>(null)
  const [saved, setSaved] = useState<SiteContentMap | null>(null)
  const [busy, setBusy] = useState(false)

  const loadGames = useCallback(async () => {
    const res = await fetch('/api/admin/games', { cache: 'no-store' })
    if (!res.ok) return toast.error('Could not load units')
    const json = await res.json()
    setGames(json.games ?? [])
  }, [])

  const loadContent = useCallback(async () => {
    const res = await fetch('/api/admin/site', { cache: 'no-store' })
    if (!res.ok) return toast.error('Could not load site settings')
    const json = await res.json()
    setContent(json.content)
    setSaved(json.content)
  }, [])

  useEffect(() => {
    loadGames()
    loadContent()
  }, [loadGames, loadContent])

  const addGame = async () => {
    setBusy(true)
    const res = await fetch('/api/admin/games', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ title: 'NEW MACHINE', format: 'game' }),
    })
    setBusy(false)
    if (res.ok) {
      haptic('complete')
      toast.success('Unit added (hidden until you flip it visible)')
      loadGames()
    } else {
      haptic('error')
      toast.error('Could not add unit')
    }
  }

  const move = async (index: number, dir: -1 | 1) => {
    if (!games) return
    const next = [...games]
    const j = index + dir
    if (j < 0 || j >= next.length) return
    ;[next[index], next[j]] = [next[j], next[index]]
    setGames(next)
    haptic('press')
    const res = await fetch('/api/admin/games/reorder', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ ids: next.map((g) => g.id) }),
    })
    if (!res.ok) {
      haptic('error')
      toast.error('Reorder failed')
    }
    loadGames()
  }

  const dirtyCount = useMemo(() => {
    if (!content || !saved) return 0
    return (Object.keys(content) as SiteKey[]).filter((key) => content[key] !== saved[key]).length
  }, [content, saved])

  const publish = async () => {
    if (!content) return
    setBusy(true)
    const res = await fetch('/api/admin/site', {
      method: 'PUT',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ content }),
    })
    setBusy(false)
    if (res.ok) {
      haptic('complete')
      toast.success('Changes published')
      setSaved(content)
    } else {
      haptic('error')
      toast.error('Publish failed')
    }
  }

  const setMany = (patch: Partial<SiteContentMap>) => setContent((c) => (c ? { ...c, ...patch } : c))
  const setField = (key: SiteKey, value: string) => setMany({ [key]: value } as Partial<SiteContentMap>)
  const current = TABS.find((t) => t.id === tab)!
  const pick = (id: Tab) => {
    haptic('toggle')
    setTab(id)
  }

  return (
    <main className="admin-shell min-h-screen">
      <header className="admin-header sticky top-0 z-40">
        <div className="max-w-[1320px] mx-auto px-4 md:px-8 h-14 flex items-center gap-4">
          <span className="font-anton text-xl uppercase" style={{ color: 'var(--bv-text-strong)' }}>CONTROL ROOM</span>
          <span className="hidden md:inline font-ibm text-[10px] uppercase tracking-[0.25em]" style={{ color: 'var(--bv-text-muted)' }}>GREY.FILTER // {email}</span>
          <div className="ml-auto flex gap-2">
            <a href="/" target="_blank" rel="noopener noreferrer" className="admin-btn">VIEW SITE ↗</a>
            <button className="admin-btn" onClick={() => { haptic('press'); signOut({ redirectTo: '/' }) }}>SIGN OUT</button>
          </div>
        </div>
        <div className="gold-hairline" aria-hidden="true" />
      </header>

      <div className="max-w-[1320px] mx-auto px-4 md:px-8 py-8 md:py-10 md:grid md:grid-cols-[220px_1fr] md:gap-10">
        <nav aria-label="Admin sections" className="admin-nav">
          <div className="flex md:flex-col gap-1 overflow-x-auto -mx-4 px-4 md:mx-0 md:px-0 pb-2 md:pb-0" role="tablist">
            {TABS.map((t) => (
              <button key={t.id} role="tab" aria-selected={tab === t.id} onClick={() => pick(t.id)} className={`admin-tab ${tab === t.id ? 'is-active' : ''}`}>
                {t.label}
              </button>
            ))}
          </div>
        </nav>

        <section className="min-w-0 pt-6 md:pt-0">
          <div className="mb-6">
            <h1 className="font-anton text-3xl md:text-4xl uppercase" style={{ color: 'var(--bv-text-strong)' }}>{current.label}</h1>
            <p className="font-ibm text-xs mt-1" style={{ color: 'var(--bv-text-muted)' }}>{current.blurb}</p>
          </div>

          {tab === 'units' ? (
            <div className="space-y-6">
              <div className="flex flex-wrap items-center gap-4">
                <p className="font-ibm text-xs flex-1 min-w-[240px]" style={{ color: 'var(--bv-text)' }}>
                  Order here = order on the site. The first unit marked IN HERO fronts the home page; every visible unit appears in Games & Apps.
                </p>
                <button className="admin-btn admin-btn-primary" disabled={busy} onClick={addGame}>+ ADD UNIT</button>
              </div>
              {games === null ? (
                <p className="admin-label">◈ LOADING UNITS…</p>
              ) : games.length === 0 ? (
                <p className="admin-label">◈ NO UNITS — ADD ONE</p>
              ) : (
                games.map((g, i) => (
                  <GameEditor
                    key={`${g.id}-${g.order}-${g.title}-${g.imagePath ?? ''}`}
                    game={g}
                    index={i}
                    total={games.length}
                    onSaved={loadGames}
                    onMove={(dir) => move(i, dir)}
                  />
                ))
              )}
            </div>
          ) : tab === 'gallery' ? (
            <GalleryEditor />
          ) : content === null ? (
            <p className="admin-label">◈ LOADING…</p>
          ) : (
            <div className="admin-card">
              {tab === 'heroes' && <HeroEditor content={content} setMany={setMany} />}
              {tab === 'text' && <TextTab content={content} setField={setField} />}
              {tab === 'look' && <FieldGrid fields={SITE_FIELDS.filter((f) => f.group === 'look')} content={content} setField={setField} />}
              {tab === 'access' && <AccessTab content={content} setField={setField} />}
            </div>
          )}
        </section>
      </div>

      {tab !== 'units' && tab !== 'gallery' && content && (
        <div className="admin-publish fixed inset-x-0 bottom-0 z-40 safe-bottom">
          <div className="max-w-[1320px] mx-auto px-4 md:px-8 py-3 flex flex-wrap items-center gap-3">
            <span className="font-ibm text-[11px] uppercase tracking-[0.2em]" style={{ color: dirtyCount ? 'var(--bv-accent)' : 'var(--bv-text-muted)' }}>
              {dirtyCount ? `◈ ${dirtyCount} UNPUBLISHED EDIT${dirtyCount === 1 ? '' : 'S'} (ALL TABS)` : '◈ LIVE SITE MATCHES'}
            </span>
            <div className="ml-auto flex gap-2">
              {dirtyCount > 0 && <button className="admin-btn" onClick={() => { haptic('toggle'); setContent(saved) }}>REVERT</button>}
              <button className="admin-btn admin-btn-primary" disabled={!dirtyCount || busy} onClick={publish}>
                {busy ? 'PUBLISHING…' : dirtyCount ? 'PUBLISH' : 'PUBLISHED'}
              </button>
            </div>
          </div>
        </div>
      )}
    </main>
  )
}

type FieldProps = { content: SiteContentMap; setField: (key: SiteKey, value: string) => void }

function TextTab({ content, setField }: FieldProps) {
  const fields = SITE_FIELDS.filter((f) => f.group === 'text')
  const used = new Set<string>()
  return (
    <div className="space-y-8">
      {TEXT_SECTIONS.map((s) => {
        const list = fields.filter((f) => !used.has(f.key) && s.match(f.key))
        list.forEach((f) => used.add(f.key))
        if (!list.length) return null
        return (
          <div key={s.title}>
            <p className="font-oswald text-xs uppercase tracking-[0.3em] mb-4" style={{ color: 'var(--bv-primary)' }}>{s.title}</p>
            <FieldGrid fields={list} content={content} setField={setField} />
          </div>
        )
      })}
    </div>
  )
}

function AccessTab({ content, setField }: FieldProps) {
  const lockField = SITE_FIELDS.find((f) => f.key === 'paywallEnabled')!
  const retired = SITE_FIELDS.filter((f) => f.group === 'paywall' && f.key !== 'paywallEnabled')
  return (
    <div className="space-y-6">
      <FieldGrid fields={[{ ...lockField, label: 'Unit locks on', hint: 'On: units marked LOCKED (Units tab) send visitors to /profile, where turning the seal opens them. Off: every unit plays free.' }]} content={content} setField={setField} />
      <a href="/profile" target="_blank" rel="noopener noreferrer" className="admin-btn">PREVIEW SEAL ↗</a>
      <details className="pt-4" style={{ borderTop: '1px solid var(--bv-border)' }}>
        <summary className="admin-label cursor-pointer min-h-[44px] flex items-center">RETIRED PURCHASE FIELDS (NOT SHOWN TO VISITORS)</summary>
        <div className="pt-4"><FieldGrid fields={retired} content={content} setField={setField} /></div>
      </details>
    </div>
  )
}

function FieldGrid({ fields, content, setField }: FieldProps & { fields: SiteField[] }) {
  return (
    <div className="grid md:grid-cols-2 gap-5">
      {fields.map((f) => (
        <div key={f.key} className={f.type === 'multiline' ? 'md:col-span-2' : ''}>
          <label htmlFor={`site-${f.key}`} className="admin-label block mb-1.5">{f.label}</label>
          {f.type === 'multiline' ? (
            <textarea id={`site-${f.key}`} rows={f.key === 'paywallPerks' ? 5 : 2} className="admin-input" value={content[f.key]} onChange={(e) => setField(f.key, e.target.value)} />
          ) : f.type === 'toggle' ? (
            <Toggle value={content[f.key]} onChange={(v) => setField(f.key, v)} />
          ) : f.type === 'select' ? (
            <select id={`site-${f.key}`} className="admin-input" value={content[f.key]} onChange={(e) => { haptic('toggle'); setField(f.key, e.target.value) }}>
              {f.options?.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}
            </select>
          ) : (
            <input id={`site-${f.key}`} className="admin-input" value={content[f.key]} onChange={(e) => setField(f.key, e.target.value)} />
          )}
          {f.hint && <p className="admin-hint">{f.hint}</p>}
        </div>
      ))}
    </div>
  )
}

