// ---- Helpers ----------------------------------------------

export function getNodeByKey(key: string): TravelNode | null {
  return TRAVEL_NODES.find((n) => n.key === key) ?? null;
}

export function getHomeNode(): TravelNode {
  return TRAVEL_NODES.find((n) => n.isHome) ?? TRAVEL_NODES[0];
}

/** Get the route between two specific nodes (undirected) */
export function getRouteBetween(a: string, b: string): TravelRoute | null {
  return TRAVEL_ROUTES.find(
    (r) => (r.from === a && r.to === b) || (r.from === b && r.to === a),
  ) ?? null;
}

/** Get node keys adjacent to a given node */
export function getAdjacentNodeKeys(nodeKey: string): string[] {
  return TRAVEL_ROUTES
    .filter((r) => r.from === nodeKey || r.to === nodeKey)
    .map((r) => (r.from === nodeKey ? r.to : r.from));
}

/** Check if a node is unlocked (prereq mission completed) */
export function isNodeUnlocked(
  node: TravelNode,
  completedMissionKeys: Set<string>,
): boolean {
  if (!node.prereq) return true;
  return completedMissionKeys.has(node.prereq);
}

/** BFS shortest path. Returns node keys in order (inclusive). */
export function findPath(fromKey: string, toKey: string): string[] {
  if (fromKey === toKey) return [fromKey];
  const vis = new Set([fromKey]);
  const q: string[][] = [[fromKey]];
  while (q.length) {
    const p = q.shift()!;
    const c = p[p.length - 1];
    for (const a of getAdjacentNodeKeys(c)) {
      if (a === toKey) return [...p, a];
      if (!vis.has(a)) { vis.add(a); q.push([...p, a]); }
    }
  }
  return [];
}

/** Sum route costs along a path */
export function pathTotalCost(path: string[]): TravelCost {
  const t: TravelCost = {};
  for (let i = 0; i < path.length - 1; i++) {
    const r = getRouteBetween(path[i], path[i + 1]);
    if (r) for (const [k, v] of Object.entries(r.cost)) t[k as ResourceKey] = (t[k as ResourceKey] ?? 0) + (v ?? 0);
  }
  return t;
}

/** Sum route steps along a path */
export function pathTotalSteps(path: string[]): number {
  let s = 0;
  for (let i = 0; i < path.length - 1; i++) { const r = getRouteBetween(path[i], path[i + 1]); if (r) s += r.steps; }
  return s;
}

