/** Reads a banner token from the live stylesheet as #rrggbb (colour pickers need hex). */
function tokenHex(name: string) {
  const raw = getComputedStyle(document.documentElement).getPropertyValue(`--bv-${name}-rgb`).trim()
  const parts = raw.split(/\s+/).map(Number)
  if (parts.length < 3 || parts.some(Number.isNaN)) return ''
  return '#' + parts.slice(0, 3).map((n) => n.toString(16).padStart(2, '0')).join('')
}

