  const k = (p: HeroProp) => heroKey(page, p)
  const v = (p: HeroProp) => content[k(p)] ?? ''
  const set = (p: HeroProp, value: string) => setMany({ [k(p)]: value } as Partial<SiteContentMap>)

  useEffect(() => {
    setTokens({
      title: tokenHex('text-strong'),
      text: tokenHex('text'),
      accent: tokenHex('accent'),
      surface: tokenHex('surface'),
      from: tokenHex('surface-3'),
      to: tokenHex('bg'),
    })
  }, [])

  const bgImage = v('bgImage')
  useEffect(() => {
    if (!bgImage.trim()) return setImageUrl(null)
    let live = true
    const t = setTimeout(async () => {
      const res = await fetch('/api/admin/hero-image', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ path: bgImage }) })
      const json = await res.json().catch(() => ({}))
      if (live) setImageUrl(json?.url ?? null)
    }, 350)
    return () => {
      live = false
      clearTimeout(t)
    }
  }, [bgImage])

  const upload = async (file: File) => {
    if (!file.type.startsWith('image/')) return toast.error('Pick an image file')
    if (file.size > 100 * 1024 * 1024) return toast.error('Image must be under 100MB')
    setUploading(true)
    try {
      const pres = await fetch('/api/admin/upload', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ fileName: file.name, contentType: file.type }) })
      const { uploadUrl, cloud_storage_path, error } = await pres.json()
      if (!pres.ok) throw new Error(error ?? 'Upload URL failed')
      const put = await fetch(uploadUrl, { method: 'PUT', headers: { 'Content-Type': file.type }, body: file })
      if (!put.ok) throw new Error(`Upload failed (${put.status})`)
      setMany({ [k('bgImage')]: cloud_storage_path, [k('bg')]: 'image' } as Partial<SiteContentMap>)
      haptic('complete')
      toast.success('Image uploaded — publish to put it live')
    } catch (e: any) {
      haptic('error')
      toast.error(e?.message ?? 'Upload failed')
    } finally {
      setUploading(false)
    }
  }

  const resetPage = () => {
    haptic('toggle')
    setMany(Object.fromEntries(HERO_PROPS.map((p) => [k(p), HERO_DEFAULTS[k(p)]])) as Partial<SiteContentMap>)
  }

  const hero = resolveHero(content, page, imageUrl)
  const bg = v('bg')

  return (
    <div className="space-y-8">
      <div className="flex flex-wrap items-center gap-2" role="group" aria-label="Page">
        {HERO_PAGES.map((p) => (
          <button key={p} type="button" aria-pressed={page === p} className={`admin-btn ${page === p ? 'admin-btn-on' : ''}`} onClick={() => { haptic('toggle'); setPage(p) }}>
            {PAGE_LABEL[p].label}
          </button>
        ))}
        <a href={PAGE_LABEL[page].href} target="_blank" rel="noopener noreferrer" className="admin-btn ml-auto">VIEW PAGE ↗</a>
      </div>

      <div>
        <p className="admin-label mb-2">LIVE PREVIEW {page !== 'home' && v('show') === 'off' ? '— HIDDEN ON SITE' : ''}</p>
        <div className="admin-preview" style={{ opacity: page !== 'home' && v('show') === 'off' ? 0.45 : 1 }}>
          <PageHero key={`${page}-${v('animate')}`} hero={{ ...hero, show: true }} preview />
        </div>
      </div>

      <div className="grid md:grid-cols-2 gap-x-6 gap-y-5">
        <Group title="VISIBILITY & COPY" />
        {page === 'home' ? (
          <Note>The home hero always shows. With the banner background the art carries the GREY.FILTER title; text typed below appears under the banner. Any other background shows the title as type — keep a full stop in it (blank = GREY.FILTER).</Note>
        ) : (
          <Field label="Show on page"><Toggle value={v('show')} onChange={(x) => set('show', x)} /></Field>
        )}
        <Field label="Title"><input className="admin-input" value={v('title')} onChange={(e) => set('title', e.target.value)} /></Field>
        <Field label="Subtitle" wide><textarea rows={2} className="admin-input" value={v('subtitle')} onChange={(e) => set('subtitle', e.target.value)} /></Field>

        <Group title="BACKGROUND" />
        <Field label="Background type">
          <select className="admin-input" value={bg} onChange={(e) => { haptic('toggle'); set('bg', e.target.value) }}>
            {BG_OPTIONS.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}
          </select>
        </Field>
        <Field label="Height">
          <select className="admin-input" value={v('height')} onChange={(e) => { haptic('toggle'); set('height', e.target.value) }}>
            {HEIGHT_OPTIONS.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}
          </select>
        </Field>
        {bg === 'gradient' && (
          <>
            <Field label="Gradient">
              <select className="admin-input" value={v('gradient')} onChange={(e) => { haptic('toggle'); set('gradient', e.target.value) }}>
                {Object.entries(HERO_GRADIENTS).map(([key, g]) => <option key={key} value={key}>{g.label}</option>)}
              </select>
            </Field>
            {v('gradient') === 'custom' && (
              <Field label="Gradient colours">
                <div className="grid grid-cols-2 gap-2">
                  <ColorInput value={v('gradFrom')} fallback={tokens.from} onChange={(x) => set('gradFrom', x)} />
                  <ColorInput value={v('gradTo')} fallback={tokens.to} onChange={(x) => set('gradTo', x)} />
                </div>
              </Field>
            )}
          </>
        )}
        {bg === 'image' && (
          <Field label="Image" wide>
            <div className="flex flex-wrap gap-2">
              <label className="admin-btn cursor-pointer">
                {uploading ? 'UPLOADING…' : 'UPLOAD IMAGE'}
                <input type="file" accept="image/*" className="sr-only" disabled={uploading} onChange={(e) => { const f = e.target.files?.[0]; if (f) upload(f); e.target.value = '' }} />
              </label>
              <input className="admin-input flex-1 min-w-[200px]" placeholder="or paste an https:// image URL" value={bgImage} onChange={(e) => set('bgImage', e.target.value)} />
              {bgImage && <button type="button" className="admin-btn" onClick={() => set('bgImage', '')}>CLEAR</button>}
            </div>
            {!imageUrl && <p className="admin-hint">No image yet — the banner gradient shows until one is set. A dark scrim always sits under the text.</p>}
          </Field>
        )}
        {bg === 'solid' && (
          <Field label="Solid colour"><ColorInput value={v('solid')} fallback={tokens.surface} onChange={(x) => set('solid', x)} /></Field>
        )}

        <Group title="COLOUR OVERRIDES" hint="Blank = banner token. Overrides apply to this page only." />
        <Field label="Title colour"><ColorInput value={v('titleColor')} fallback={tokens.title} onChange={(x) => set('titleColor', x)} /></Field>
        <Field label="Text colour"><ColorInput value={v('textColor')} fallback={tokens.text} onChange={(x) => set('textColor', x)} /></Field>
        <Field label="Accent (button) colour"><ColorInput value={v('accentColor')} fallback={tokens.accent} onChange={(x) => set('accentColor', x)} /></Field>

        <Group title="LAYOUT & MOTION" />
        <Field label="Text alignment">
          <div className="flex gap-2" role="group" aria-label="Text alignment">
            {(['left', 'center', 'right'] as const).map((a) => (
              <button key={a} type="button" aria-pressed={v('align') === a} className={`admin-btn ${v('align') === a ? 'admin-btn-on' : ''}`} onClick={() => { haptic('toggle'); set('align', a) }}>
                {a.toUpperCase()}
              </button>
            ))}
          </div>
        </Field>
        <Field label="Animation"><Toggle value={v('animate')} onChange={(x) => set('animate', x)} /></Field>

        <Group title="BUTTON" hint="Both fields needed. Link: a site path (/games) or a full https:// address." />
        <Field label="Button label"><input className="admin-input" value={v('ctaLabel')} onChange={(e) => set('ctaLabel', e.target.value)} /></Field>
        <Field label="Button link"><input className="admin-input" placeholder="/games" value={v('ctaHref')} onChange={(e) => set('ctaHref', e.target.value)} /></Field>
      </div>

      <button type="button" className="admin-btn" onClick={resetPage}>RESET {PAGE_LABEL[page].label} HERO TO DEFAULTS</button>
    </div>
  )
}

function Group({ title, hint }: { title: string; hint?: string }) {
  return (
    <div className="md:col-span-2 pt-4 first:pt-0" style={{ borderTop: '1px solid var(--bv-border)' }}>
      <p className="font-oswald text-xs uppercase tracking-[0.3em] pt-4" style={{ color: 'var(--bv-primary)' }}>{title}</p>
      {hint && <p className="admin-hint">{hint}</p>}
    </div>
  )
}

function Note({ children }: { children: React.ReactNode }) {
  return <p className="md:col-span-2 font-ibm text-xs" style={{ color: 'var(--bv-text-muted)' }}>{children}</p>
}

function Field({ label, wide, children }: { label: string; wide?: boolean; children: React.ReactNode }) {
  return (
    <div className={wide ? 'md:col-span-2' : ''}>
      <p className="admin-label mb-1.5">{label}</p>
      {children}
    </div>
  )
}

export function Toggle({ value, onChange }: { value: string; onChange: (v: 'on' | 'off') => void }) {
  const cur = value === 'off' ? 'off' : 'on'
  return (
    <div className="flex gap-2" role="group">
      {(['on', 'off'] as const).map((x) => (
        <button key={x} type="button" aria-pressed={cur === x} className={`admin-btn ${cur === x ? 'admin-btn-on' : ''}`} onClick={() => { haptic('toggle'); onChange(x) }}>
          {x.toUpperCase()}
        </button>
      ))}
    </div>
  )
}

function ColorInput({ value, fallback, onChange }: { value: string; fallback?: string; onChange: (v: string) => void }) {
  const valid = cleanColor(value)
  return (
    <div className="flex gap-2 items-stretch">
      <input
        type="color"
        aria-label="Pick colour"
        className="admin-swatch"
        value={valid.length === 7 ? valid : fallback || '#000000'}
        onChange={(e) => onChange(e.target.value)}
      />
      <input className="admin-input flex-1 min-w-0" placeholder="TOKEN" value={value} onChange={(e) => onChange(e.target.value)} />
      {value && <button type="button" className="admin-btn" onClick={() => onChange('')} title="Back to the banner token">TOKEN</button>}
    </div>
  )
}

