'use client'

import { useState, useEffect, useCallback, useRef } from 'react'
import { motion, useReducedMotion } from 'framer-motion'

const TOTAL_BLOCKS = 6

interface BootSequenceProps {
  onComplete: () => void
}

export default function BootSequence({ onComplete }: BootSequenceProps) {
  const [phase, setPhase] = useState(0)
  const [interactive, setInteractive] = useState(false)
  const [locked, setLocked] = useState(false)
  const [blocks, setBlocks] = useState(0)
  const timerRef = useRef<NodeJS.Timeout | null>(null)
  const enteredRef = useRef(false)
  const audioRef = useRef<AudioContext | null>(null)
  const prefersReduced = useReducedMotion()

  const handleEnter = useCallback(() => {
    if (enteredRef.current) return
    if (!interactive) return
    enteredRef.current = true
    onComplete?.()
  }, [interactive, onComplete])

  // Procedural "clunk" — a short low thud as each frame piece locks in.
  const playClunk = useCallback((pitch = 150) => {
    if (prefersReduced) return
    try {
      const Ctx = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext
      if (!Ctx) return
      const ctx = audioRef.current || new Ctx()
      audioRef.current = ctx
      const now = ctx.currentTime
      const osc = ctx.createOscillator()
      const gain = ctx.createGain()
      const filter = ctx.createBiquadFilter()
      osc.type = 'square'
      osc.frequency.setValueAtTime(pitch, now)
      osc.frequency.exponentialRampToValueAtTime(pitch * 0.4, now + 0.11)
      filter.type = 'lowpass'
      filter.frequency.value = 850
      gain.gain.setValueAtTime(0.0001, now)
      gain.gain.exponentialRampToValueAtTime(0.08, now + 0.008)
      gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.14)
      osc.connect(filter).connect(gain).connect(ctx.destination)
      osc.start(now)
      osc.stop(now + 0.16)
    } catch {
      /* audio is progressive enhancement only */
    }
  }, [prefersReduced])

  useEffect(() => {
    const timers: NodeJS.Timeout[] = []
    // 0.0s: black void (phase 0)
    timers.push(setTimeout(() => setPhase(1), 800))    // 0.8s: frame pieces fly in + grid
    timers.push(setTimeout(() => setLocked(true), 1550)) // frame locks (corners snap)
    timers.push(setTimeout(() => setPhase(2), 2500))   // 2.5s: magenta scan
    timers.push(setTimeout(() => setPhase(3), 3300))   // 3.3s: monitor sweep
    timers.push(setTimeout(() => setPhase(4), 5500))   // 5.5s: status text
    timers.push(setTimeout(() => setPhase(5), 6500))   // 6.5s: MANAGE DECLINE prompt
    timers.push(setTimeout(() => setInteractive(true), 6000)) // 6s: interactive floor

    // Staggered clunks as the four edges settle (skipped under reduced motion)
    if (!prefersReduced) {
      timers.push(setTimeout(() => playClunk(150), 1180))
      timers.push(setTimeout(() => playClunk(130), 1300))
      timers.push(setTimeout(() => playClunk(170), 1420))
      timers.push(setTimeout(() => playClunk(90), 1560)) // heavier final lock
    }

    // Field generation — segment blocks fill in one by one, each with a clunk.
    for (let b = 1; b <= TOTAL_BLOCKS; b++) {
      const at = 1650 + (b - 1) * 130
      timers.push(setTimeout(() => {
        setBlocks(b)
        if (!prefersReduced) playClunk(200 + b * 16)
      }, at))
    }

    // Auto-enter at 9s
    timerRef.current = setTimeout(() => {
      if (!enteredRef.current) {
        enteredRef.current = true
        onComplete?.()
      }
    }, 9000)
    timers.push(timerRef.current)

    return () => {
      timers.forEach((t) => clearTimeout(t))
    }
  }, [onComplete, playClunk, prefersReduced])

  useEffect(() => {
    const handleKey = (e: KeyboardEvent) => {
      if (e.key === 'Enter') handleEnter()
    }
    window?.addEventListener?.('keydown', handleKey)
    return () => window?.removeEventListener?.('keydown', handleKey)
  }, [handleEnter])

  useEffect(() => {
    return () => {
      try { audioRef.current?.close?.() } catch { /* ignore */ }
    }
  }, [])

  // Spring that overshoots then settles — the "clunk into place" feel.
  const clunkSpring = prefersReduced
    ? { duration: 0.01 }
    : { type: 'spring' as const, stiffness: 320, damping: 15, mass: 0.9 }

  const hLines = Array.from({ length: 10 }, (_, i) => i)
  const vLines = Array.from({ length: 7 }, (_, i) => i)

  // Frame inset (matches the persistent OverlayFrame geometry)
  const inset = 20

  return (
    <motion.div
      className="fixed inset-0 bg-[#0A0A08] flex items-center justify-center cursor-pointer select-none"
      onClick={handleEnter}
      exit={{ opacity: 0 }}
      transition={{ duration: 0.4 }}
    >
      {/* Interior grid field — draws in behind the assembled frame */}
      {phase >= 1 && (
        <div className="absolute inset-0 pointer-events-none">
          {hLines.map((i) => (
            <motion.div
              key={`h-${i}`}
              className="absolute left-0 right-0 h-px bg-[#B8F026]"
              style={{ top: `${((i + 1) / 11) * 100}%` }}
              initial={{ scaleX: 0, opacity: 0 }}
              animate={{ scaleX: 1, opacity: 0.08 }}
              transition={{ duration: 0.7, delay: 1.5 + i * 0.04, ease: 'easeOut' }}
            />
          ))}
          {vLines.map((i) => (
            <motion.div
              key={`v-${i}`}
              className="absolute top-0 bottom-0 w-px bg-[#B8F026]"
              style={{ left: `${((i + 1) / 8) * 100}%` }}
              initial={{ scaleY: 0, opacity: 0 }}
              animate={{ scaleY: 1, opacity: 0.08 }}
              transition={{ duration: 0.6, delay: 1.7 + i * 0.04, ease: 'easeOut' }}
            />
          ))}
        </div>
      )}

      {/* FRAME ASSEMBLY — thick edge blocks slide in, overshoot, and clunk into place */}
      {phase >= 1 && (
        <div className="absolute inset-0 pointer-events-none">
          {/* Top edge */}
          <motion.div
            className="absolute bg-[#B8F026]"
            style={{ top: inset, left: inset, right: inset, height: 8, boxShadow: '0 0 22px 2px #B8F02688' }}
            initial={{ y: -70, opacity: 0 }}
