import { NextResponse } from 'next/server'
import { prisma } from '@/lib/db'
import { requireAdmin } from '@/auth'
import { SITE_DEFAULTS } from '@/lib/site-defaults'
import { getSiteContent } from '@/lib/content'

export const dynamic = 'force-dynamic'

export async function GET() {
  if (!(await requireAdmin())) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  return NextResponse.json({ content: await getSiteContent() })
}

export async function PUT(req: Request) {
  if (!(await requireAdmin())) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  const body = await req.json().catch(() => ({}))
  const entries = Object.entries(body?.content ?? {}).filter(
    ([k, v]) => k in SITE_DEFAULTS && typeof v === 'string'
  ) as [string, string][]
  await prisma.$transaction(
    entries.map(([key, value]) =>
      prisma.siteContent.upsert({ where: { key }, update: { value }, create: { key, value } })
    )
  )
  return NextResponse.json({ ok: true, saved: entries.length })
}

/**
 * UI Data Model — derived display state between game engine and React components.
 *
 * This module provides:
 *   - Zone system (RED / YELLOW / GREEN traffic-light for crew status)
 *   - CrewCardUI (composite display data for each NPC)
 *   - WinTrackerState (progress toward finale / ascension)
 *   - DosePreview (non-destructive prediction of dose outcomes)
 *
 * IMPORTANT: encounter.ts is LOCKED. We import its exports but never modify it.
 */

import {
  type ActorState,
  type ActorMood,
  type DoseResult,
  getActorMood,
  resolveDose,
  computeActorState,
} from './encounter';
import { NPC_DATA, MISSION_DEFINITIONS } from './game-data';

// ─── Zone System ──────────────────────────────────────────────────────────────

export type CrewZone = 'GREEN' | 'YELLOW' | 'RED';

/** CSS-ready color tokens per zone. */
export const ZONE_COLORS: Record<CrewZone, { bg: string; text: string; border: string; glow: string }> = {
  GREEN:  { bg: 'bg-emerald-900/40', text: 'text-emerald-400', border: 'border-emerald-500/50', glow: 'shadow-emerald-500/20' },
  YELLOW: { bg: 'bg-amber-900/40',   text: 'text-amber-400',   border: 'border-amber-500/50',   glow: 'shadow-amber-500/20' },
  RED:    { bg: 'bg-red-900/40',     text: 'text-red-400',     border: 'border-red-500/50',     glow: 'shadow-red-500/20' },
};

/** Zone hex colors for canvas/inline-style contexts. */
export const ZONE_HEX: Record<CrewZone, string> = {
  GREEN:  '#34d399',
  YELLOW: '#fbbf24',
  RED:    '#f87171',
};

/** Map the 7-mood system to a 3-zone traffic light. */
export function getCrewZone(mood: ActorMood): CrewZone {
  switch (mood) {
    case 'STABLE':     return 'GREEN';
    case 'RESTLESS':   return 'YELLOW';
    case 'DESPERATE':  return 'YELLOW';
    case 'WITHDRAWN':  return 'YELLOW';
    case 'VOLATILE':   return 'RED';
    case 'CRASHING':   return 'RED';
    case 'GONE':       return 'RED';
    default:           return 'YELLOW';
  }
}

/** Derive zone directly from ActorState (convenience). */
export function getZoneFromActor(actor: ActorState): CrewZone {
  return getCrewZone(getActorMood(actor));
}

/** Zone sort priority: RED=0 (urgent first), YELLOW=1, GREEN=2. */
export function zonePriority(zone: CrewZone): number {
  return zone === 'RED' ? 0 : zone === 'YELLOW' ? 1 : 2;
}

// ─── Crew Card UI ─────────────────────────────────────────────────────────────

export interface CrewCardUI {
  npcKey: string;
  name: string;
  archetype: string;
  role: string;
  specialty: string;
  skill: string;
  portraitUrl: string;
  recruited: boolean;
  affinity: number;
  zone: CrewZone;
  mood: ActorMood;
  /** Human-readable status line derived from mood. */
  statusLine: string;
}

/** NPC DB row shape — matches the Prisma NPC model fields we need. */
export interface NpcRow {
  name: string;
  archetype: string;
  role: string;
  specialty: string;
  skill: string;
  recruited: boolean;
  affinity: number;
  status: string;
  heatLevel: number;
  muscle: number;
  brains: number;
  unpredictability: number;
  toleranceCigs: number;
  toleranceAlc: number;
  toleranceWeed: number;
  toleranceCryst: number;
  usageCigs: number;
  usageAlc: number;
  usageWeed: number;
  usageCryst: number;
  decayDay: number;
}

const STATUS_LINES: Record<ActorMood, string> = {
  STABLE:     'Functional',
  RESTLESS:   'Getting antsy',
  DESPERATE:  'Needs a fix',
  VOLATILE:   'On the edge',
  WITHDRAWN:  'Pulling away',
  CRASHING:   'Falling apart',
  GONE:       'Gone',
};

/** Build a CrewCardUI from a DB row + static NPC_DATA. */
export function buildCrewCard(npcKey: string, row: NpcRow): CrewCardUI {
  const staticData = NPC_DATA[npcKey as keyof typeof NPC_DATA];
  const actor = computeActorState(row);
  const mood = getActorMood(actor);
  const zone = getCrewZone(mood);

  return {
    npcKey,
    name: staticData?.name ?? row.name,
    archetype: staticData?.archetype ?? row.archetype,
    role: staticData?.role ?? row.role,
    specialty: staticData?.specialty ?? row.specialty,
    skill: staticData?.skill ?? row.skill,
    portraitUrl: staticData?.portraitUrl ?? '/images/dave-portrait-v2-crop.png',
    recruited: row.recruited,
    affinity: row.affinity,
    zone,
    mood,
    statusLine: STATUS_LINES[mood],
  };
}

/** Build cards for all NPCs in a session. Returns sorted by zone priority (RED first). */
export function buildCrewRoster(npcs: Array<{ key: string } & NpcRow>): CrewCardUI[] {
  return npcs
    .map(npc => buildCrewCard(npc.key, npc))
    .sort((a, b) => zonePriority(a.zone) - zonePriority(b.zone));
}

// ─── Win Tracker ──────────────────────────────────────────────────────────────

const MAIN_MISSION_KEYS = ['initiation', 'territory_war', 'syndicate_handshake', 'ascension'] as const;

export interface CrewWinStatus {
  npcKey: string;
  name: string;
  recruited: boolean;
  zone: CrewZone;
  /** Is this crew member in a stable enough zone to contribute to win? */
  winEligible: boolean;
}

export interface WinTrackerState {
  /** Per-crew status toward finale. */
  crew: CrewWinStatus[];
  /** How many main missions completed (0-4). */
  mainMissionsCompleted: number;
  /** Total main missions (always 4). */
  mainMissionsTotal: number;
  /** Ordered list of main mission keys with completion status. */
  missionProgress: Array<{ key: string; title: string; completed: boolean }>;
  /** Number of crew in GREEN zone. */
  greenCount: number;
  /** Number of crew recruited. */
  recruitedCount: number;
  /** All prerequisites met for Ascension? */
  finaleReady: boolean;
  /** Overall progress percentage (0-100). */
  progressPercent: number;
}

/** Mission DB row — minimal shape we need. */
export interface MissionRow {
  missionKey: string;
  type: string;
  status: string;
}

/**
 * Compute the win tracker state from current session data.
 * @param npcs - All NPC rows with their keys
 * @param missions - All mission rows for the session
 */
export function computeWinTracker(
  npcs: Array<{ key: string } & NpcRow>,
  missions: MissionRow[],
): WinTrackerState {
  // Build crew status
  const crew: CrewWinStatus[] = npcs.map(npc => {
    const actor = computeActorState(npc);
    const zone = getZoneFromActor(actor);
    return {
      npcKey: npc.key,
      name: NPC_DATA[npc.key as keyof typeof NPC_DATA]?.name ?? npc.name,
      recruited: npc.recruited,
      zone,
      winEligible: npc.recruited && zone === 'GREEN' && !!(npc as any).directiveDone,
    };
  });

  // Mission progress
  const completedMissions = new Set(
    missions
      .filter(m => m.status === 'COMPLETED')
      .map(m => m.missionKey)
  );

  const missionProgress = MAIN_MISSION_KEYS.map(key => ({
    key,
    title: MISSION_DEFINITIONS[key]?.title ?? key,
    completed: completedMissions.has(key),
  }));

  const mainMissionsCompleted = missionProgress.filter(m => m.completed).length;
  const greenCount = crew.filter(c => c.zone === 'GREEN').length;
  const recruitedCount = crew.filter(c => c.recruited).length;

  // Ascension requires: syndicate_handshake completed + 4 crew recruited
  const ascensionDef = MISSION_DEFINITIONS.ascension;
  const prereqsMet = ascensionDef?.prereqs
    ? ascensionDef.prereqs.every(p => completedMissions.has(p))
    : false;
  const crewReqMet = recruitedCount >= (ascensionDef?.crewRequired ?? 4);
  const finaleReady = prereqsMet && crewReqMet;

  // Progress: weight missions at 60%, crew recruitment at 25%, green zones at 15%
  const missionScore = (mainMissionsCompleted / 4) * 60;
  const recruitScore = (recruitedCount / 4) * 25;
  const zoneScore = (greenCount / Math.max(recruitedCount, 1)) * 15;
  const progressPercent = Math.round(Math.min(100, missionScore + recruitScore + zoneScore));

  return {
    crew,
    mainMissionsCompleted,
    mainMissionsTotal: 4,
    missionProgress,
    greenCount,
    recruitedCount,
    finaleReady,
    progressPercent,
  };
}

// ─── Dose Preview ─────────────────────────────────────────────────────────────

export interface DosePreview {
  /** Predicted reaction type. */
  predictedReaction: DoseResult['reaction'];
  /** Predicted narrative text. */
  predictedNarrative: string;
  /** What zone the NPC would move to after dosing. */
  projectedZone: CrewZone;
  /** Current zone for comparison. */
  currentZone: CrewZone;
  /** Whether the dose would improve, worsen, or maintain zone. */
  zoneShift: 'IMPROVE' | 'WORSEN' | 'STABLE';
}

/**
 * Preview what would happen if you dose an NPC — without mutating anything.
 * Uses the same resolveDose() logic from encounter.ts but applies deltas
 * to a cloned ActorState to project the outcome.
 */
export function previewDose(
  npcRow: NpcRow,
  substancePreference: number,
  isCraving: boolean,
): DosePreview {
  const actor = computeActorState(npcRow);
  const currentZone = getZoneFromActor(actor);

  // Run the dose resolution on a snapshot (resolveDose is pure — returns deltas, doesn't mutate)
  const result = resolveDose(actor, substancePreference, isCraving);

  // Apply deltas to a clone to see the projected state
  const projected: ActorState = { ...actor };
  for (const [key, delta] of Object.entries(result.deltas)) {
    const k = key as keyof ActorState;
    projected[k] = Math.min(10, Math.max(0, projected[k] + (delta as number)));
  }

  const projectedZone = getZoneFromActor(projected);

  let zoneShift: DosePreview['zoneShift'] = 'STABLE';
  if (zonePriority(projectedZone) < zonePriority(currentZone)) {
    zoneShift = 'WORSEN'; // lower priority number = more urgent = worse
  } else if (zonePriority(projectedZone) > zonePriority(currentZone)) {
    zoneShift = 'IMPROVE';
  }

  return {
    predictedReaction: result.reaction,
    predictedNarrative: result.narrative,
    projectedZone,
    currentZone,
    zoneShift,
  };
}

// ─── Zone Summary (for HUD) ──────────────────────────────────────────────────

export interface ZoneSummary {
  green: number;
  yellow: number;
  red: number;
  total: number;
}

/** Quick zone count across all recruited crew. */
export function getZoneSummary(npcs: Array<{ key: string } & NpcRow>): ZoneSummary {
  const recruited = npcs.filter(n => n.recruited);
  let green = 0, yellow = 0, red = 0;
  for (const npc of recruited) {
    const zone = getZoneFromActor(computeActorState(npc));
    if (zone === 'GREEN') green++;
    else if (zone === 'YELLOW') yellow++;
    else red++;
  }
  return { green, yellow, red, total: recruited.length };
}

