'use client'

import { useEffect, useRef, useState, type FormEvent } from 'react'
import { createPortal } from 'react-dom'
import { signIn } from 'next-auth/react'
import { haptic } from '@/lib/haptics'

/**
 * The control-room trigger. 'hotspot' = invisible hit area over the full stop in the
 * banner art's GREY.FILTER; 'dot' = the literal "." in a text title, styled exactly as
 * the surrounding letters. Either opens the passcode prompt. Nothing changes visually.
 */
export function AdminGate({ variant }: { variant: 'hotspot' | 'dot' }) {
  const [open, setOpen] = useState(false)
  const openPrompt = () => {
    haptic('press')
    setOpen(true)
  }
  return (
    <>
      {variant === 'hotspot' ? (
        <button
          type="button"
          tabIndex={-1}
          aria-label="Control room"
          onClick={openPrompt}
          className="absolute z-[5] p-0 m-0 border-0 bg-transparent outline-none"
          style={{
            left: '35.2%',
            top: '53%',
            width: 'max(3%, 28px)',
            height: 'max(5%, 28px)',
            transform: 'translate(-50%, -50%)',
            cursor: 'default',
            WebkitTapHighlightColor: 'transparent',
          }}
        />
      ) : (
        <button
          type="button"
          tabIndex={-1}
          aria-label="Control room"
          onClick={openPrompt}
          className="inline p-0 m-0 border-0 bg-transparent outline-none"
          style={{ font: 'inherit', color: 'inherit', letterSpacing: 'inherit', lineHeight: 'inherit', cursor: 'inherit', WebkitTapHighlightColor: 'transparent' }}
        >
          .
        </button>
      )}
      {open && <PasscodePrompt onClose={() => setOpen(false)} />}
    </>
  )
}

function PasscodePrompt({ onClose }: { onClose: () => void }) {
  const [code, setCode] = useState('')
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const inputRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    inputRef.current?.focus()
    const onKey = (e: KeyboardEvent) => e.key === 'Escape' && onClose()
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [onClose])

  const submit = async (e: FormEvent) => {
    e.preventDefault()
    if (!code || busy) return
    setBusy(true)
    setError(null)
    try {
      const res = await fetch('/api/admin/login', {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ passcode: code }),
      })
      const json = await res.json().catch(() => ({}))
      if (!res.ok || !json?.ticket) {
        haptic('error')
        setCode('')
        setError(
          res.status === 429
            ? `LOCKED OUT — TRY AGAIN IN ${Math.ceil(Number(json?.retryAfter ?? 900) / 60)} MIN`
            : json?.error ?? 'ACCESS DENIED'
        )
        return
      }
      const result = await signIn('admin-ticket', { ticket: json.ticket, redirect: false })
      if (result?.error) {
        haptic('error')
        setError('ACCESS DENIED')
        return
      }
      haptic('complete')
      window.location.href = '/admin'
    } catch (err) {
      console.error('control room sign-in failed', err)
      haptic('error')
      setError('LINE DEAD — RETRY')
    } finally {
      setBusy(false)
    }
  }

  return createPortal(
    <div
      className="fixed inset-0 z-[200] flex items-center justify-center px-4"
      style={{ backgroundColor: 'rgb(var(--bv-bg-rgb) / 0.88)', backdropFilter: 'blur(6px)' }}
      onMouseDown={(e) => e.target === e.currentTarget && onClose()}
      data-no-swipe
    >
      <form
        role="dialog"
        aria-modal="true"
        aria-labelledby="cr-title"
        onSubmit={submit}
        className="w-full max-w-[400px] p-6 md:p-8"
        style={{ background: 'var(--bv-gradient-panel)', border: '1px solid var(--bv-border)', boxShadow: '0 30px 80px rgb(var(--bv-shadow-rgb) / 0.6)' }}
      >
        <p className="font-ibm text-[10px] uppercase tracking-[0.3em] mb-2" style={{ color: 'var(--bv-text-muted)' }}>RESTRICTED // GREY.FILTER</p>
        <h2 id="cr-title" className="font-anton text-3xl uppercase mb-6" style={{ color: 'var(--bv-text-strong)' }}>CONTROL ROOM</h2>
        <label htmlFor="cr-code" className="block font-oswald text-[11px] uppercase tracking-widest mb-1.5" style={{ color: 'var(--bv-text)' }}>Passcode</label>
        <input
          ref={inputRef}
          id="cr-code"
          type="password"
          autoComplete="off"
          spellCheck={false}
          className="admin-input"
          value={code}
          onChange={(e) => setCode(e.target.value)}
          disabled={busy}
        />
        <p role="alert" className="font-ibm text-[11px] uppercase min-h-[20px] mt-2" style={{ color: 'var(--bv-accent)' }}>{error ?? ''}</p>
        <div className="flex gap-2 mt-4">
          <button type="submit" className="admin-btn admin-btn-primary flex-1 justify-center" disabled={busy || !code}>
            {busy ? 'CHECKING…' : 'ENTER'}
          </button>
          <button type="button" className="admin-btn" onClick={onClose}>CLOSE</button>
        </div>
      </form>
    </div>,
    document.body
  )
}

