/** Resource type → icon component mapping. */
export const RESOURCE_ICON_MAP = {
  cigarettes: CigaretteIcon,
  alcohol: AlcoholIcon,
  weed: WeedIcon,
  crystals: CrystalIcon,
} as const;

export type ResourceKey = keyof typeof RESOURCE_ICON_MAP;

/** Compact resource display: icon + quantity, for HUDs and cost chips. */
export function ResourceChip({
  type,
  quantity,
  color = 'currentColor',
  size = 13,
  className = '',
}: {
  type: string;
  quantity: number;
  color?: string;
  size?: number;
  className?: string;
}) {
  const Icon = RESOURCE_ICON_MAP[type as ResourceKey];
  if (!Icon) return <span className={className}>{quantity}</span>;
  return (
    <span className={`inline-flex items-center gap-1 ${className}`} style={{ color }}>
      <Icon size={size} color={color} />
      <span className="tabular-nums">{quantity}</span>
    </span>
  );
}

'use client'

import { useEffect, useState } from 'react'
import Image from 'next/image'
import Link from 'next/link'
import { haptic } from '@/lib/haptics'
import type { SiteContentMap } from '@/lib/site-defaults'
import { RedeemToken } from '../components/redeem-token'

export async function startCheckout(): Promise<string> {
  const res = await fetch('/api/checkout', { method: 'POST' })
  const data = await res.json().catch(() => ({}))
  if (!res.ok || !data?.url) throw new Error(data?.error || 'CHECKOUT FAILED — TRY AGAIN')
  return data.url as string
}

type Props = {
  content: SiteContentMap
  lockedTitles?: string[]
  stripeReady?: boolean
  signedIn?: boolean
  unlocked?: boolean
  paused?: boolean
  cancelled?: boolean
}

const CTA_CLASS =
  'press-fx group mt-8 w-full inline-flex items-center justify-center gap-4 font-oswald uppercase tracking-[0.25em] text-base px-6 min-h-[56px] hover:bg-[var(--col-yellow-hot)] disabled:opacity-60'
const CTA_STYLE = { backgroundColor: 'var(--col-yellow)', color: 'var(--col-black)' }
const Arrow = () => (
  <svg width="22" height="14" viewBox="0 0 20 14" fill="none" aria-hidden="true" className="transition-transform group-hover:translate-x-1">
    <path d="M13 1L19 7M19 7L13 13M19 7H1" stroke="currentColor" strokeWidth="2.5" />
  </svg>
)

export function UnlockPanel({ content, lockedTitles = [], stripeReady = false, signedIn = false, unlocked = false, paused = false, cancelled = false }: Props) {
  const perks = content.paywallPerks.split('\n').map((p) => p.trim()).filter(Boolean)
  const [busy, setBusy] = useState(false)
  const [err, setErr] = useState<string | null>(null)

  // Back button from Stripe restores this page from bfcache — release the busy lock
  useEffect(() => {
    const reset = (e: PageTransitionEvent) => { if (e.persisted) setBusy(false) }
    window.addEventListener('pageshow', reset)
    return () => window.removeEventListener('pageshow', reset)
  }, [])

  const buy = async () => {
    if (busy) return
    haptic('activate')
    setBusy(true)
    setErr(null)
    try {
      window.location.assign(await startCheckout())
