'use client'

import { useCallback, useEffect, useRef, useState, type DragEvent } from 'react'
import { toast } from 'sonner'
import { haptic } from '@/lib/haptics'

type Item = { id: string; url: string; width: number; height: number }

const ACCEPT = ['image/jpeg', 'image/png', 'image/webp']
/** Raw file ceiling before compression. */
const MAX_INPUT_MB = 30
/** Decoded pixel ceiling (guards the browser against giant canvases). */
const MAX_INPUT_PIXELS = 80_000_000
/** Longest edge after resize. */
const MAX_WIDTH = 2400
const QUALITY = 0.86
/** Compressed output ceiling. */
const MAX_OUTPUT_MB = 8

async function loadBitmap(file: File) {
  if ('createImageBitmap' in window) {
    try {
      return await createImageBitmap(file)
    } catch {
      /* fall through to <img> decode */
    }
  }
  const url = URL.createObjectURL(file)
  try {
    const img = new window.Image()
    img.src = url
    await img.decode()
    return img
  } finally {
    URL.revokeObjectURL(url)
  }
}

/** Resize to MAX_WIDTH wide and re-encode (WebP, JPEG where WebP encoding is unsupported). */
async function compress(file: File) {
  const src = await loadBitmap(file)
  const w0 = src.width
  const h0 = src.height
  if (!w0 || !h0) throw new Error('could not be read as an image')
  if (w0 * h0 > MAX_INPUT_PIXELS) throw new Error(`is too large (${w0}×${h0}px, max 80 megapixels)`)
  const scale = Math.min(1, MAX_WIDTH / w0)
  const width = Math.round(w0 * scale)
  const height = Math.round(h0 * scale)
  const canvas = document.createElement('canvas')
  canvas.width = width
  canvas.height = height
  const ctx = canvas.getContext('2d')
  if (!ctx) throw new Error('could not be processed')
  ctx.imageSmoothingQuality = 'high'
  ctx.drawImage(src, 0, 0, width, height)
  if ('close' in src) src.close()
  const encode = (type: string) => new Promise<Blob | null>((res) => canvas.toBlob(res, type, QUALITY))
  let blob = await encode('image/webp')
  if (!blob || blob.type !== 'image/webp') {
    // JPEG has no alpha: paint transparent areas black first
    ctx.globalCompositeOperation = 'destination-over'
    ctx.fillStyle = 'black'
    ctx.fillRect(0, 0, width, height)
    blob = await encode('image/jpeg')
  }
  if (!blob) throw new Error('could not be compressed')
  if (blob.size > MAX_OUTPUT_MB * 1024 * 1024) throw new Error(`is still over ${MAX_OUTPUT_MB}MB after compression`)
  const ext = blob.type === 'image/webp' ? 'webp' : 'jpg'
  const name = `${file.name.replace(/\.[^.]+$/, '').slice(0, 60) || 'art'}.${ext}`
  return { blob, width, height, name }
}

export function GalleryEditor() {
  const [items, setItems] = useState<Item[] | null>(null)
  const [queue, setQueue] = useState<{ done: number; total: number } | null>(null)
  const [busy, setBusy] = useState(false)
  const [over, setOver] = useState(false)
  const inputRef = useRef<HTMLInputElement>(null)

  const load = useCallback(async () => {
    const res = await fetch('/api/admin/gallery', { cache: 'no-store' })
    if (!res.ok) return toast.error('Could not load the gallery')
    const json = await res.json()
    setItems(json.images ?? [])
  }, [])

  useEffect(() => {
    load()
  }, [load])

  const uploadOne = async (file: File) => {
    const { blob, width, height, name } = await compress(file)
    const pres = await fetch('/api/admin/gallery', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ action: 'presign', fileName: name, contentType: blob.type }),
    })
    const pj = await pres.json().catch(() => ({}))
    if (!pres.ok) throw new Error(pj?.error ?? 'upload URL failed')
    const put = await fetch(pj.uploadUrl, { method: 'PUT', headers: { 'Content-Type': blob.type }, body: blob })
    if (!put.ok) throw new Error(`upload failed (${put.status})`)
    const add = await fetch('/api/admin/gallery', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ action: 'add', cloud_storage_path: pj.cloud_storage_path, width, height }),
    })
    if (!add.ok) throw new Error('could not be saved to the gallery')
  }

  const handleFiles = async (list: FileList | File[]) => {
    const files = Array.from(list)
    if (!files.length || queue) return
    const ok: File[] = []
    for (const f of files) {
      if (!ACCEPT.includes(f.type)) toast.error(`${f.name}: rejected — JPG, PNG or WebP only`)
      else if (f.size > MAX_INPUT_MB * 1024 * 1024) toast.error(`${f.name}: rejected — over ${MAX_INPUT_MB}MB`)
      else ok.push(f)
    }
    if (!ok.length) return haptic('error')
    haptic('press')
    setQueue({ done: 0, total: ok.length })
    let good = 0
    for (let i = 0; i < ok.length; i++) {
      try {
        await uploadOne(ok[i])
        good++
      } catch (e: any) {
        toast.error(`${ok[i].name} ${e?.message ?? 'failed'}`)
      }
      setQueue({ done: i + 1, total: ok.length })
    }
    setQueue(null)
    await load()
    if (good) {
      haptic('complete')
      toast.success(`${good} image${good === 1 ? '' : 's'} hung in the gallery — live now`)
    } else haptic('error')
  }

  const move = async (index: number, dir: -1 | 1) => {
    if (!items) return
    const j = index + dir
    if (j < 0 || j >= items.length) return
    const next = [...items]
    ;[next[index], next[j]] = [next[j], next[index]]
    setItems(next)
    haptic('press')
    setBusy(true)
    const res = await fetch('/api/admin/gallery/reorder', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ ids: next.map((x) => x.id) }),
    })
    setBusy(false)
    if (!res.ok) {
      haptic('error')
      toast.error('Reorder failed')
      load()
    }
  }

  const remove = async (item: Item, index: number) => {
    if (!window.confirm(`Delete image ${String(index + 1).padStart(2, '0')} from the gallery permanently?`)) return
    setBusy(true)
    const res = await fetch(`/api/admin/gallery/${item.id}`, { method: 'DELETE' })
    setBusy(false)
    if (res.ok) {
      haptic('complete')
      toast.success('Image removed')
      setItems((xs) => (xs ? xs.filter((x) => x.id !== item.id) : xs))
    } else {
      haptic('error')
      toast.error('Delete failed')
    }
  }

  const onDrop = (e: DragEvent) => {
    e.preventDefault()
    setOver(false)
    if (e.dataTransfer.files?.length) handleFiles(e.dataTransfer.files)
  }

  return (
    <div className="space-y-6">
      <div className="admin-card">
        <div
          className={`admin-drop ${over ? 'is-over' : ''}`}
          onDragOver={(e) => { e.preventDefault(); setOver(true) }}
          onDragLeave={() => setOver(false)}
          onDrop={onDrop}
        >
          <p className="font-anton text-2xl uppercase" style={{ color: 'var(--bv-text-strong)' }}>
            {queue ? `UPLOADING ${queue.done}/${queue.total}…` : 'DROP ART HERE'}
          </p>
          <p className="admin-hint">JPG, PNG or WebP · up to {MAX_INPUT_MB}MB each · resized to {MAX_WIDTH}px wide and compressed before upload</p>
          <button type="button" className="admin-btn admin-btn-primary mt-4" disabled={!!queue} onClick={() => inputRef.current?.click()}>
            {queue ? 'WORKING…' : 'CHOOSE FILES'}
          </button>
          <input
            ref={inputRef}
            type="file"
            accept={ACCEPT.join(',')}
            multiple
            className="sr-only"
            tabIndex={-1}
            onChange={(e) => { if (e.target.files) handleFiles(e.target.files); e.target.value = '' }}
          />
        </div>
      </div>

      <div className="admin-card">
        <div className="flex flex-wrap items-center gap-3 mb-4">
          <p className="font-oswald text-xs uppercase tracking-[0.3em]" style={{ color: 'var(--bv-primary)' }}>HANGING ORDER</p>
          <p className="admin-hint !mt-0 ml-auto">Order here = swipe order in the hero gallery. Saves instantly.</p>
        </div>
        {items === null ? (
          <p className="admin-label">◈ LOADING GALLERY…</p>
        ) : items.length === 0 ? (
          <p className="admin-label">◈ NO ART HUNG YET — VISITORS SEE THE EMPTY-WALL PLACEHOLDER</p>
        ) : (
          <ol className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-4">
            {items.map((it, i) => (
              <li key={it.id} className="admin-thumb">
                <div className="relative aspect-video overflow-hidden" style={{ background: 'var(--bv-bg)' }}>
                  {/* eslint-disable-next-line @next/next/no-img-element */}
                  <img src={it.url} alt={`Gallery image ${i + 1}`} loading="lazy" className="absolute inset-0 w-full h-full object-contain" />
                  <span className="absolute top-1.5 left-1.5 font-ibm text-[10px] px-1.5 py-0.5" style={{ background: 'rgb(var(--bv-bg-rgb) / 0.85)', color: 'var(--bv-text-strong)' }}>
                    {String(i + 1).padStart(2, '0')}
                  </span>
                </div>
                <div className="flex gap-1.5 p-2">
                  <button className="admin-btn flex-1 justify-center" disabled={i === 0 || busy} onClick={() => move(i, -1)} aria-label={`Move image ${i + 1} earlier`}>←</button>
                  <button className="admin-btn flex-1 justify-center" disabled={i === items.length - 1 || busy} onClick={() => move(i, 1)} aria-label={`Move image ${i + 1} later`}>→</button>
                  <button className="admin-btn admin-btn-danger flex-1 justify-center" disabled={busy} onClick={() => remove(it, i)} aria-label={`Delete image ${i + 1}`}>✕</button>
                </div>
              </li>
            ))}
          </ol>
        )}
      </div>
    </div>
  )
}

export const dynamic = 'force-dynamic';

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { validateResourceType, isValidId, safeNumber } from '@/lib/api-guards';

export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const { sessionId } = body ?? {};
    if (!isValidId(sessionId)) {
      return NextResponse.json({ error: 'Missing sessionId' }, { status: 400 });
    }
    const type = validateResourceType(body?.type);
    if (!type) {
      return NextResponse.json({ error: 'Invalid resource type' }, { status: 400 });
    }
    const MAX_RESOURCE = 30;
    const requestedChange = safeNumber(body?.change, 0);

    // Get current quantity first for cap enforcement
    const existing = await prisma.resource.findUnique({
      where: { sessionId_type: { sessionId, type } },
    });
    const currentQty = existing?.quantity ?? 0;

    // If adding, cap at MAX_RESOURCE. If removing, floor at 0.
    let newQty = currentQty + requestedChange;
    if (newQty > MAX_RESOURCE) newQty = MAX_RESOURCE;
    if (newQty < 0) newQty = 0;

    const resource = await prisma.resource.upsert({
      where: { sessionId_type: { sessionId, type } },
      update: { quantity: newQty },
      create: { sessionId, type, quantity: Math.max(0, Math.min(MAX_RESOURCE, requestedChange)) },
    });
    return NextResponse.json({ ...resource, maxResource: MAX_RESOURCE });
  } catch (err: unknown) {
    console.error('Resource error:', err);
    return NextResponse.json({ error: 'Failed' }, { status: 500 });
  }
}

/* abacus-stage — story runtime for DeepAgent (scenes on a canvas, a camera, live abacus-viz tiles inside scenes).
   AbacusStage.mount(root, manifest, data, scenes, opts) → { go, next, prev, overview, viz, state, current, dispose }
   manifest: the dashboard.json of a `format: "story"` bundle — `scenes[]` ({id, title, html, frame:{x,y,w,h,scale,rotate}}),
   optional `path[]` (scene order), plus the usual `tiles[]` / `filters[]` / `sources[]` the viz kit renders.
   scenes: {id: innerHTML} — the authored markup of every scene (fetched by index.html, inlined by the share page). */
(function (global) {
  'use strict';

  const DEFAULT_W = 1600, DEFAULT_H = 900;
  const MARGIN = 0.035; // viewport share kept clear around a focused scene
  const STACK_W = 640; // logical scene width in stack mode (narrow portrait viewports)
  const el = (tag, cls, html) => { const e = document.createElement(tag); if (cls) e.className = cls; if (html != null) e.innerHTML = html; return e; };
  const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
  const reduced = () => global.matchMedia && global.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const isInteractive = (node) => !!node.closest('a, button, input, select, textarea, label, [data-goto], [data-tab], figure, .av-tile, .av-tabs, [data-ab="compare"], [data-ab="embed"], .as-scroll');

  function frameOf(s) {
    const f = s.frame || {};
    const w = +f.w || DEFAULT_W, h = +f.h || DEFAULT_H;
    return { x: +f.x || 0, y: +f.y || 0, w, h, scale: +f.scale || 1, rotate: +f.rotate || 0 };
  }

  function mount(root, manifest, data, scenes, opts = {}) {
    const embedded = !!opts.embedded;
    const sceneSpecs = (manifest.scenes || []).filter((s) => s && s.id);
    const path = (Array.isArray(manifest.path) && manifest.path.length ? manifest.path : sceneSpecs.map((s) => s.id)).filter((id) => sceneSpecs.some((s) => s.id === id));
    const byId = Object.fromEntries(sceneSpecs.map((s) => [s.id, s]));

    // ---------- theme (same contract as abacus-viz: html standalone, root embedded, ?theme= wins standalone) ----------
    const themeHost = embedded ? root : document.documentElement;
    const themeOf = (t) => (t === 'light' || t === 'editorial' ? '' : t === 'auto' ? (document.documentElement.classList.contains('dark') ? 'midnight' : '') : t);
    const urlTheme = !embedded && new URLSearchParams(global.location.search).get('theme');
    if (urlTheme) themeHost.dataset.theme = themeOf(urlTheme);
    else if (manifest.theme) themeHost.dataset.theme = themeOf(manifest.theme);

    // ---------- dom ----------
    root.classList.add('as-root', 'av-root');
    if (embedded) root.classList.add('as-embedded');
    root.innerHTML = '';
    const viewport = el('div', 'as-viewport');
    viewport.tabIndex = 0;
    const canvas = el('div', 'as-canvas');
    viewport.appendChild(canvas);
    root.appendChild(viewport);

    // one keypress per step value: every element with the same data-step appears (and hides) together
    function stepGroups(scene) {
      const byStep = new Map();
      scene.querySelectorAll('[data-step]').forEach((s) => { const k = +s.dataset.step || 0; if (!byStep.has(k)) byStep.set(k, []); byStep.get(k).push(s); });
      return [...byStep.entries()].sort((a, b) => a[0] - b[0]).map(([, els]) => els);
    }
    const setShown = (group, shown) => group.forEach((s) => s.classList.toggle('is-shown', shown));
    const isShown = (group) => group[0].classList.contains('is-shown');
    const nodes = {};
    sceneSpecs.forEach((s) => {
      const f = frameOf(s);
      const slot = el('div', 'as-slot');
      slot.style.cssText = `left:${f.x}px;top:${f.y}px;width:${f.w}px;height:${f.h}px;transform:rotate(${f.rotate}deg) scale(${f.scale})`;
      const scene = el('section', 'as-scene' + (s.class ? ' ' + s.class : ''), scenes[s.id] || '');
      scene.id = 'scene-' + s.id;
      scene.dataset.scene = s.id;
      scene.dataset.title = s.title || s.id;
      slot.appendChild(scene);
      canvas.appendChild(slot);
      nodes[s.id] = { spec: s, frame: f, slot, scene, entered: false, steps: stepGroups(scene) };
    });

    // hud
    const hud = el('div', 'as-hud');
    const title = el('div', 'as-hud-title');
    if (manifest.eyebrow) title.appendChild(el('span', 'as-hud-eyebrow', manifest.eyebrow));
    title.appendChild(el('span', 'as-hud-name', manifest.title || ''));
    const count = el('span', 'as-count');
    const prevBtn = el('button', 'as-btn', '←'); prevBtn.title = 'Previous (←)'; prevBtn.onclick = () => prev();
    const nextBtn = el('button', 'as-btn', '→'); nextBtn.title = 'Next (→ / space)'; nextBtn.onclick = () => next();
    const ovBtn = el('button', 'as-btn as-ov', 'Overview'); ovBtn.title = 'Overview (esc)'; ovBtn.onclick = () => (state.current === null ? go(path[0]) : overview());
    hud.append(title, count, prevBtn, nextBtn, ovBtn);
    if (!embedded && document.fullscreenEnabled) {
      const fsBtn = el('button', 'as-btn', 'Present'); fsBtn.title = 'Fullscreen (f)';
      fsBtn.onclick = () => (document.fullscreenElement ? document.exitFullscreen() : root.requestFullscreen());
      hud.appendChild(fsBtn);
    }
    root.appendChild(hud);
    const progress = el('div', 'as-progress', '<i></i>');
    root.appendChild(progress);
    const dots = el('div', 'as-dots');
    path.forEach((id) => { const b = el('button'); b.title = byId[id].title || id; b.onclick = () => go(id); dots.appendChild(b); });
