'use client'

import { useEffect, useRef, useState, type CSSProperties } from 'react'
import { usePathname } from 'next/navigation'

/**
 * The Manager — unannounced haunt. Four encounters per browser session (E4 locks every non-current tab), each rolled once inside its
 * dwell window of active time on site (visible tab, launch seal cleared). Plan lives in sessionStorage,
 * so route changes and reloads never restart it and fired encounters never repeat.
 * Never touches the soundtrack <audio>. Optional SFX use their own AudioContext (admin toggle, off by default).
 */

const PUBLIC = new Set(['/', '/games', '/contact'])
const KEY = 'bv-haunt'
const SPEED_KEY = 'bv-haunt-speed'
const WINDOWS: [number, number][] = [[18, 32], [50, 80], [95, 130], [150, 190]]
const FRONT = '/assets/manager-front.jpg'
const PROFILE = '/assets/manager-profile.jpg'
const GLYPHS = '#%&/<>=+*01X$@'

type Plan = { at: number[]; elapsed: number; done: number[]; tabs: string[] }
type Mode = 'idle' | 'signal' | 'lock' | 'hold' | 'blink' | 'out'
type Band = { top: number; h: number; d: number }
type Block = { x: number; y: number; w: number; h: number; k: number }
type Burst = { key: number; blocks: Block[]; slices: Band[]; jolt: boolean } | null

const rand = (a: number, b: number) => a + Math.random() * (b - a)
const scramble = (s: string) => s.replace(/[^\s]/g, () => GLYPHS[Math.floor(Math.random() * GLYPHS.length)])

function loadPlan(): Plan {
  try {
    const raw = sessionStorage.getItem(KEY)
    if (raw) {
      const p = JSON.parse(raw) as Plan
      if (Array.isArray(p.at) && p.at.length === WINDOWS.length && Array.isArray(p.done)) return { ...p, tabs: Array.isArray(p.tabs) ? p.tabs : [] }
    }
  } catch {}
  const plan: Plan = { at: WINDOWS.map(([a, b]) => Math.round(rand(a, b) * 1000)), elapsed: 0, done: [], tabs: [] }
  savePlan(plan)
  return plan
}
function savePlan(p: Plan) {
  try { sessionStorage.setItem(KEY, JSON.stringify(p)) } catch {}
}

/* ---------- SFX: separate layer, faint fuzzy bursts ---------- */
let sfxCtx: AudioContext | null = null
function fuzz(ms: number, peak = 0.03) {
  try {
    const AC = window.AudioContext || (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext
    if (!AC) return
    if (!sfxCtx) sfxCtx = new AC()
    const ctx = sfxCtx
    if (ctx.state === 'suspended') void ctx.resume().catch(() => {})
    const len = Math.max(1, Math.floor((ctx.sampleRate * ms) / 1000))
    const buf = ctx.createBuffer(1, len, ctx.sampleRate)
    const data = buf.getChannelData(0)
    const hold = 6 + Math.floor(Math.random() * 10) // sample-and-hold = digital fuzz
    let v = 0
    for (let i = 0; i < len; i++) {
      if (i % hold === 0) v = Math.random() * 2 - 1
      data[i] = v * (Math.random() < 0.08 ? 0.2 : 1)
    }
    const src = ctx.createBufferSource()
    src.buffer = buf
    const bp = ctx.createBiquadFilter()
    bp.type = 'bandpass'
    bp.frequency.value = rand(1400, 3200)
    bp.Q.value = 0.9
    const g = ctx.createGain()
    const t = ctx.currentTime
    g.gain.setValueAtTime(0, t)
    g.gain.linearRampToValueAtTime(peak, t + 0.008)
    g.gain.exponentialRampToValueAtTime(0.0001, t + ms / 1000)
    src.connect(bp).connect(g).connect(ctx.destination)
    src.start(t)
    src.stop(t + ms / 1000 + 0.02)
  } catch {}
}

export function ManagerHaunt({ enabled, sfx = false }: { enabled: boolean; sfx?: boolean }) {
  const pathname = usePathname()
  const pathRef = useRef(pathname)
  const busy = useRef(false)
  const timers = useRef<number[]>([])
  const restorers = useRef<(() => void)[]>([])
  const decodeTimer = useRef<number | null>(null)
  const [mode, setMode] = useState<Mode>('idle')
  const [face, setFace] = useState<string | null>(null)
  const [text, setText] = useState('')
  const [reduced, setReduced] = useState(false)
  const [geo, setGeo] = useState<{ x: number; lock: number; bands: Band[]; key: number }>({ x: 0, lock: 600, bands: [], key: 0 })
  const [burst, setBurst] = useState<Burst>(null)
  const burstKey = useRef(0)

  const later = (fn: () => void, ms: number) => {
    const id = window.setTimeout(fn, ms)
    timers.current.push(id)
  }
  const sound = (ms: number, peak?: number) => {
    // operator hub pref mutes haunt SFX only — the soundtrack is never touched
    let muted = false
    try { muted = localStorage.getItem('bv-haunt-sfx-mute') === '1' } catch {}
    if (sfx && !muted) fuzz(ms, peak)
  }

  const abort = () => {
    timers.current.forEach((id) => window.clearTimeout(id))
    timers.current = []
    if (decodeTimer.current) window.clearInterval(decodeTimer.current)
    decodeTimer.current = null
    restorers.current.splice(0).forEach((r) => r())
    busy.current = false
    setBurst(null)
    setMode('idle')
    setFace(null)
    setText('')
  }

  // Exempt routes (admin, login, profile, unlock, checkout) end any encounter instantly
  useEffect(() => {
    pathRef.current = pathname
    if (!PUBLIC.has(pathname ?? '') && busy.current) abort()
  }, [pathname])

  useEffect(() => {
    if (!enabled) return
    if (process.env.NODE_ENV !== 'production') {
      // QA hooks (dev preview only): ?haunt=reset clears the plan, ?haunt=fast runs the windows 6× faster
      const q = new URLSearchParams(window.location.search).get('haunt') ?? ''
      try {
        if (q.includes('reset')) { sessionStorage.removeItem(KEY); sessionStorage.removeItem(SPEED_KEY) }
        if (q.includes('fast')) sessionStorage.setItem(SPEED_KEY, '6')
      } catch {}
    }
    let speed = 1
    try { speed = Number(sessionStorage.getItem(SPEED_KEY)) || 1 } catch {}
    if (process.env.NODE_ENV === 'production') speed = 1

    const plan = loadPlan()
    let preloaded = false
    let last = performance.now()
    let lastSave = 0

    /* ---- page signal misbehaves: luminous tear bands + scrambled non-current labels ---- */
    const scrambleLabels = (ms: number, rm: boolean) => {
      if (rm) return
      document.querySelectorAll<HTMLElement>('[data-haunt-tab]').forEach((el) => {
        if (el.dataset.hauntTab === pathRef.current || el.dataset.corrupt) return
        const node = el.querySelector('[data-haunt-label]')?.firstChild
        if (!node || node.nodeType !== Node.TEXT_NODE) return
        const orig = node.nodeValue ?? ''
        const w = el.getBoundingClientRect().width
        el.style.width = `${w}px`
        el.style.overflow = 'hidden'
        let n = 0
        const iv = window.setInterval(() => {
          node.nodeValue = n++ % 3 === 2 ? orig : scramble(orig)
        }, 70)
        const restore = () => {
          window.clearInterval(iv)
          node.nodeValue = orig
          el.style.width = ''
          el.style.overflow = ''
        }
        restorers.current.push(restore)
        later(() => {
          restore()
          restorers.current = restorers.current.filter((r) => r !== restore)
        }, ms)
      })
    }

    /* ---- glitch burst: displaced face slices, inverted data blocks, one-frame contrast jolt ---- */
    const glitch = (rm: boolean, ms = Math.round(rand(140, 240))) => {
      if (rm) return
      const key = ++burstKey.current
      setBurst({
        key,
        jolt: Math.random() < 0.55,
        blocks: Array.from({ length: 4 + Math.floor(Math.random() * 6) }, () => ({
          x: rand(0, 92), y: rand(0, 94), w: rand(2, 18), h: rand(0.6, 4.5), k: Math.floor(Math.random() * 3),
        })),
        slices: Array.from({ length: 2 + Math.floor(Math.random() * 3) }, () => ({ top: rand(4, 86), h: rand(3, 14), d: rand(-34, 34) })),
      })
      later(() => setBurst((b) => (b && b.key === key ? null : b)), ms)
    }
    const stutters = (from: number, to: number, rm: boolean) => {
      if (rm) return
      let t = from + rand(250, 700)
      while (t < to - 200) {
        later(() => { glitch(rm); sound(90, 0.018) }, t)
        t += rand(480, 1250)
      }
    }

    const signal = (ms: number, rm: boolean) => {
      glitch(rm, Math.min(ms, 260))
      const bands: Band[] = Array.from({ length: 2 + Math.floor(Math.random() * 2) }, () => ({
        top: rand(8, 88), h: rand(5, 26), d: rand(-24, 24),
      }))
      setGeo((g) => ({ ...g, bands, x: rand(-10, 10), key: g.key + 1 }))
      setMode('signal')
      scrambleLabels(ms, rm)
      sound(Math.min(ms, 260), 0.025)
    }

    const decode = (target: string, ms: number) => {
      const start = performance.now()
      if (decodeTimer.current) window.clearInterval(decodeTimer.current)
      decodeTimer.current = window.setInterval(() => {
        const p = (performance.now() - start) / ms
        if (p >= 1) {
          setText(target)
          if (decodeTimer.current) window.clearInterval(decodeTimer.current)
          decodeTimer.current = null
          return
        }
        setText(
          target.split('').map((c, i) => (c === ' ' || p > (i + 1) / target.length + rand(-0.06, 0.06) ? c : GLYPHS[Math.floor(Math.random() * GLYPHS.length)])).join('')
        )
      }, 45)
    }

    /* ---- non-current nav tabs go dark for 5–8s, then come back untouched (E2/E3: one each, E4: all) ---- */
    const corruptTab = (img: 'front' | 'profile', rm: boolean, onDone: () => void, all = false) => {
      const els = Array.from(document.querySelectorAll<HTMLElement>('[data-haunt-tab]')).filter((el) => {
        const href = el.dataset.hauntTab ?? ''
        if (href === pathRef.current || el.dataset.corrupt || el.getClientRects().length === 0) return false
        return all || (!plan.tabs.includes(href) && document.activeElement !== el)
      })
      const picked = all ? els : els.slice(Math.floor(Math.random() * els.length)).slice(0, 1)
      if (!picked.length) { onDone(); return }
      if (!all) { plan.tabs.push(picked[0].dataset.hauntTab ?? ''); savePlan(plan) }
      const restores = picked.map((el) => lockTab(el, img, rm))
      sound(all ? 320 : 180, 0.02)
      later(() => {
        restores.forEach((r) => r())
        onDone()
      }, Math.round(rand(5000, 8000)))
    }

    const lockTab = (el: HTMLElement, img: 'front' | 'profile', rm: boolean) => {
      const node = el.querySelector('[data-haunt-label]')?.firstChild
      const orig = node?.nodeValue ?? ''
      const hadTabIndex = el.getAttribute('tabindex')
      const block = (e: Event) => { e.preventDefault(); e.stopPropagation() }
      el.style.width = `${el.getBoundingClientRect().width}px`
      el.style.overflow = 'hidden'
      el.dataset.corrupt = img
      el.setAttribute('aria-disabled', 'true')
      el.tabIndex = -1
      el.addEventListener('click', block, true)
      let iv: number | null = null
      if (node) {
        if (rm) node.nodeValue = orig.replace(/[^\s]/g, '/')
        else iv = window.setInterval(() => { node.nodeValue = Math.random() < 0.18 ? orig : scramble(orig) }, 110)
      }
      let restored = false
      const restore = () => {
        if (restored) return
        restored = true
        if (iv) window.clearInterval(iv)
        if (node) node.nodeValue = orig
        el.style.width = ''
        el.style.overflow = ''
        delete el.dataset.corrupt
        el.removeAttribute('aria-disabled')
        if (hadTabIndex === null) el.removeAttribute('tabindex')
        else el.setAttribute('tabindex', hadTabIndex)
        el.removeEventListener('click', block, true)
        window.clearInterval(watch)
        restorers.current = restorers.current.filter((r) => r !== restore)
      }
      restorers.current.push(restore)
      // Tab dies with its nav (route change swaps the nav), so a stale lock can never outlive the page
      const watch = window.setInterval(() => {
        if (!el.isConnected || el.dataset.hauntTab === pathRef.current) restore()
      }, 250)
      return restore
    }

    const finish = () => {
      setMode('idle')
      setFace(null)
      setText('')
    }

    const encounter1 = (rm: boolean) => {
      if (rm) {
        setFace(FRONT); setMode('hold')
        later(() => { finish(); busy.current = false }, 1400)
        return
      }
      setFace(FRONT)
      signal(rand(240, 360), rm)
      let t = rand(240, 360)
      const flashes = 2 + Math.floor(Math.random() * 2)
      for (let i = 0; i < flashes; i++) {
        const on = Math.round(rand(240, 520))
        later(() => { setGeo((g) => ({ ...g, lock: on, x: rand(-12, 12), key: g.key + 1 })); setMode('lock'); glitch(rm); sound(on * 0.6, 0.022) }, t)
        later(() => glitch(rm, 120), t + on * 0.6)
        t += on
        if (i < flashes - 1) {
          later(() => setMode('blink'), t)
          t += Math.round(rand(380, 1000))
        }
      }
      later(() => { setMode('out'); glitch(rm, 200); sound(220, 0.02) }, t)
      later(() => { finish(); busy.current = false }, t + 420)
    }

    const encounterWithText = (img: string, copy: string, tabImg: 'front' | 'profile', rm: boolean, allTabs = false) => {
      let pending = 2 // face exit + tab restore
      const settle = () => { if (--pending <= 0) busy.current = false }
      setFace(img)
      if (rm) {
        setMode('hold')
        setText(copy)
        later(() => corruptTab(tabImg, rm, settle, allTabs), 900)
        later(() => { finish(); settle() }, 3400)
        return
      }
      const sig = rand(280, 420)
      signal(sig, rm)
      const lock = Math.round(rand(420, 600))
      later(() => { setGeo((g) => ({ ...g, lock, key: g.key + 1 })); setMode('lock'); glitch(rm); sound(260, 0.025) }, sig)
      later(() => { setMode('hold'); glitch(rm, 160); if (copy) decode(copy, 1000) }, sig + lock)
      const stare = Math.round(rand(3200, 4200))
      stutters(sig + lock, sig + lock + stare, rm)
      later(() => { glitch(rm, 260); corruptTab(tabImg, rm, settle, allTabs) }, sig + lock + Math.round(allTabs ? rand(700, 1100) : rand(1300, 1900)))
      later(() => { setMode('out'); glitch(rm, 200); sound(240, 0.022) }, sig + lock + stare)
      later(() => { finish(); settle() }, sig + lock + stare + 420)
    }

    const fire = (i: number) => {
      busy.current = true
      plan.done.push(i)
      savePlan(plan)
      const rm = window.matchMedia('(prefers-reduced-motion: reduce)').matches || document.documentElement.classList.contains('bv-reduce')
      setReduced(rm)
      if (i === 0) encounter1(rm)
      else if (i === 1) encounterWithText(FRONT, 'MEET YOUR MANAGER', 'front', rm)
      else if (i === 2) encounterWithText(PROFILE, 'BMF:3K', 'profile', rm)
      else encounterWithText(FRONT, '', 'front', rm, true) // E4: lockdown — every tab except the current one
    }

    const tick = window.setInterval(() => {
      const now = performance.now()
      const dt = Math.min(1000, now - last)
      last = now
      if (plan.done.length >= WINDOWS.length) return
      if (document.hidden || document.getElementById('launch-gate')) return
      plan.elapsed += dt
      if (!preloaded) {
        preloaded = true
        ;[FRONT, PROFILE].forEach((src) => { const im = new Image(); im.src = src })
      }
      if (now - lastSave > 2000) { savePlan(plan); lastSave = now }
      const next = WINDOWS.map((_, i) => i).find((i) => !plan.done.includes(i))
      if (next === undefined || busy.current) return
      if (plan.elapsed * speed < plan.at[next]) return
      if (!PUBLIC.has(pathRef.current ?? '')) return
      if (document.querySelector('.laser-wipe, [aria-modal="true"]')) return
      fire(next)
    }, 250)

    const onHide = () => savePlan(plan)
    window.addEventListener('pagehide', onHide)
    return () => {
      window.clearInterval(tick)
      window.removeEventListener('pagehide', onHide)
      savePlan(plan)
      abort()
    }
  }, [enabled, sfx])

  if (!enabled || mode === 'idle') return null

  const faceStyle = { '--hf-img': `url(${face})`, '--hf-x': `${geo.x}vw`, '--lock-ms': `${geo.lock}ms` } as CSSProperties
  return (
    <div className={`haunt${reduced ? ' haunt-rm' : ''}`} data-mode={mode} aria-hidden="true">
      {!reduced && (
        <div className="haunt-signal" key={`s${geo.key}`}>
          {geo.bands.map((b, i) => (
            <i key={i} style={{ top: `${b.top}%`, height: b.h, '--tear': `${b.d}px` } as CSSProperties} />
          ))}
        </div>
      )}
      {burst && (
        <div className={`haunt-burst${burst.jolt ? ' is-jolt' : ''}`} key={`b${burst.key}`}>
          {burst.blocks.map((b, i) => (
            <i key={i} data-k={b.k} style={{ left: `${b.x}%`, top: `${b.y}%`, width: `${b.w}%`, height: `${b.h}%` }} />
          ))}
        </div>
      )}
      {face && mode !== 'signal' && (
        <div className="haunt-face" style={faceStyle} key={`f${geo.key}`}>
          <div className="hf-shade" />
          <div className="hf-stack">
            <div className="hf-ghost hf-c" />
            <div className="hf-ghost hf-m" />
            <div className="hf-core" />
            {burst?.slices.map((s, i) => (
              <div key={`${burst.key}-${i}`} className="hf-slice" style={{ clipPath: `inset(${s.top}% 0 ${Math.max(0, 100 - s.top - s.h)}% 0)`, transform: `translateX(${s.d}px)` }} />
            ))}
            <div className="hf-scan" />
            <div className="hf-roll" />
          </div>
        </div>
      )}
      {text && <div className="haunt-term font-ibm">{text}<span className="haunt-cursor" /></div>}
    </div>
  )
}

'use client';

// v0.6.0 — Reality bleed cinematic overlay system
// Subscribes to escalation level and randomly fires one of 3 reality-bleed flashes:
//   level 4-5 → collapse_chaos (rare flash, ~0.4s)
//   level 6-7 → escape_breach   (more frequent, ~1.2s)
//   level 8-10 → perspective_shift_ui (sustained 3-5s)
// Reduced-motion aware.

import { useEffect, useState, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import Image from 'next/image';
import type { EscalationState } from '@/lib/escalation';

type BleedKind = 'collapse_chaos' | 'escape_breach' | 'perspective_shift';

interface BleedConfig {
  kind: BleedKind;
  src: string;
  caption: string;
  durationMs: number;
}

const CONFIGS: Record<BleedKind, BleedConfig> = {
  collapse_chaos: {
    kind: 'collapse_chaos',
    src: '/images/bleed-collapse-chaos.jpg',
    caption: 'IT’S ALL COLLAPSING',
    durationMs: 480,
  },
  escape_breach: {
    kind: 'escape_breach',
    src: '/images/bleed-escape-breach.jpg',
    caption: 'THEY’RE GETTING OUT',
    durationMs: 1300,
  },
  perspective_shift: {
    kind: 'perspective_shift',
    src: '/images/bleed-perspective-shift.jpg',
    caption: 'THIS ISN’T YOUR ROOM',
    durationMs: 3800,
  },
};

// Returns a deterministic-feeling pseudo-random tick interval (ms) for the given level
function nextIntervalMs(level: number): number {
  // Higher level = more frequent. Floor 25s, scales down with level.
  const base = Math.max(18000, 60000 - level * 4500);
  const jitter = Math.floor(Math.random() * 12000);
  return base + jitter;
}

function pickKind(level: number): BleedKind | null {
  if (level < 4) return null;
  if (level >= 8) {
    // Highest tier: 50% perspective_shift, 30% escape_breach, 20% collapse_chaos
    const r = Math.random();
    if (r < 0.5) return 'perspective_shift';
    if (r < 0.8) return 'escape_breach';
    return 'collapse_chaos';
  }
  if (level >= 6) {
    // Bleeding tier: 60% escape_breach, 30% collapse_chaos, 10% perspective_shift
    const r = Math.random();
    if (r < 0.6) return 'escape_breach';
    if (r < 0.9) return 'collapse_chaos';
    return 'perspective_shift';
  }
  // level 4-5 sweating: only collapse_chaos, rare
  return 'collapse_chaos';
}

export default function RealityBleedOverlay({ escalation }: { escalation: EscalationState }) {
  const [active, setActive] = useState<BleedConfig | null>(null);
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const fireRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const reducedMotionRef = useRef(false);

  // Detect reduced motion once on mount
  useEffect(() => {
    if (typeof window === 'undefined') return;
    const mql = window.matchMedia('(prefers-reduced-motion: reduce)');
    reducedMotionRef.current = mql.matches;
    const onChange = (e: MediaQueryListEvent) => {
      reducedMotionRef.current = e.matches;
    };
    mql.addEventListener?.('change', onChange);
    return () => mql.removeEventListener?.('change', onChange);
  }, []);

  useEffect(() => {
    // Cleanup any pending timers on level change / unmount
    const clearAll = () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
      if (fireRef.current) clearTimeout(fireRef.current);
      timeoutRef.current = null;
      fireRef.current = null;
    };

    if (escalation.level < 4 || reducedMotionRef.current) {
      clearAll();
      setActive(null);
      return clearAll;
    }

    let cancelled = false;

    const scheduleNext = () => {
      if (cancelled) return;
      const wait = nextIntervalMs(escalation.level);
      timeoutRef.current = setTimeout(() => {
        if (cancelled) return;
        const kind = pickKind(escalation.level);
        if (!kind) {
          scheduleNext();
          return;
        }
        const cfg = CONFIGS[kind];
        setActive(cfg);
        fireRef.current = setTimeout(() => {
          if (cancelled) return;
          setActive(null);
          // Re-arm next tick after the flash ends
          scheduleNext();
        }, cfg.durationMs);
      }, wait);
    };

    scheduleNext();
    return () => {
      cancelled = true;
      clearAll();
    };
  }, [escalation.level]);

  return (
    <AnimatePresence>
      {active && (
        <motion.div
          key={`${active.kind}-${Date.now()}`}
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          transition={{ duration: active.kind === 'perspective_shift' ? 0.45 : 0.18 }}
          className="fixed inset-0 z-[120] pointer-events-none"
          aria-hidden="true"
        >
          <Image
            src={active.src}
            alt="Reality bleed visual distortion"
            fill
            sizes="100vw"
            priority={false}
            className="object-cover"
            style={{
              filter:
                active.kind === 'collapse_chaos'
                  ? 'contrast(1.3) saturate(1.15) brightness(1.05)'
                  : active.kind === 'escape_breach'
                  ? 'contrast(1.18) saturate(0.95) brightness(0.92)'
                  : 'contrast(1.05) saturate(0.85) brightness(0.85) hue-rotate(-8deg)',
            }}
          />
          {/* Vignette to push focus inward */}
          <div
            className="absolute inset-0"
            style={{
              background:
                'radial-gradient(ellipse at center, rgba(0,0,0,0) 35%, rgba(0,0,0,0.55) 100%)',
            }}
          />
          {/* Scan / interlace */}
          <div
            className="absolute inset-0 mix-blend-multiply opacity-40"
            style={{
              backgroundImage:
                'repeating-linear-gradient(0deg, rgba(0,0,0,0.6) 0px, rgba(0,0,0,0.6) 1px, transparent 1px, transparent 3px)',
            }}
          />
          {/* Caption — typewriter, lower-third */}
          {active.kind !== 'collapse_chaos' && (
            <motion.div
              initial={{ opacity: 0, y: 8 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.12, duration: 0.35 }}
              className="absolute bottom-12 left-1/2 -translate-x-1/2 px-4 py-2 bg-black/65 border-l-[2px] border-[#b89a2a]/70"
            >
              <div className="font-typewriter text-[12px] sm:text-[14px] tracking-[0.18em] text-[#d8d0b8]">
                {active.caption}
              </div>
            </motion.div>
          )}
          {/* Corner system stamp — only on perspective_shift */}
          {active.kind === 'perspective_shift' && (
            <div className="absolute top-4 right-4 font-terminal text-[9px] tracking-widest text-[#b89a2a]/80">
              ROOM · NOT FOUND
            </div>
          )}
        </motion.div>
      )}
    </AnimatePresence>
  );
}

'use client'

interface MachineReadoutsProps {
  activeState: string
}

const PROCESS_MAP: Record<string, string> = {
  idle: 'IDLE',
  ready: 'READY',
  activating: 'ACTIVE',
  active: 'ACTIVE',
}

export function MachineReadouts({ activeState }: MachineReadoutsProps) {
  const process = PROCESS_MAP?.[activeState] ?? 'IDLE'

  return (
    <div className="hidden md:flex flex-col gap-2" aria-hidden="true">
      <div className="flex items-center gap-2">
        <span
          className="w-1.5 h-1.5 inline-block"
          style={{
            backgroundColor: activeState === 'idle' ? 'var(--col-steel)' : 'var(--col-yellow-hot)',
            borderRadius: '50%',
          }}
        />
        <span className="font-ibm text-[10px] uppercase" style={{ color: 'var(--col-bone)' }}>
          ONLINE
        </span>
      </div>
      <div className="font-ibm text-[10px] uppercase" style={{ color: 'var(--col-bone)', opacity: 0.5 }}>
        PROCESS: {process}
      </div>
