'use client'

import { useEffect, useState } from 'react'
import Link from 'next/link'
import { haptic } from '@/lib/haptics'
import { redeemToProfile, PENDING_CODE_KEY } from '../../components/redeem-token'

export type SuccessState = { kind: 'paid'; code: string; used: boolean } | { kind: 'pending' } | { kind: 'error' }

const btn = 'press-fx inline-flex items-center justify-center gap-3 font-oswald uppercase tracking-[0.25em] px-6 min-h-[52px] disabled:opacity-60'
const gold = { backgroundColor: 'var(--col-yellow)', color: 'var(--col-black)' }
const ghost = { border: '1px solid var(--col-steel)', color: 'var(--col-ivory)' }

export function SuccessPanel({ state, signedIn, unlocked }: { state: SuccessState; signedIn: boolean; unlocked: boolean }) {
  const [copied, setCopied] = useState(false)
  const [redeem, setRedeem] = useState<'idle' | 'busy' | 'ok' | 'error'>('idle')
  const [msg, setMsg] = useState('')

  useEffect(() => {
    if (state.kind !== 'paid') return
    haptic('complete')
    // Carry the fresh code through sign-in for this tab session only
    if (!state.used) try { sessionStorage.setItem(PENDING_CODE_KEY, state.code) } catch {}
  }, [state])

  const copy = async () => {
    if (state.kind !== 'paid') return
    haptic('press')
    try {
      await navigator.clipboard.writeText(state.code)
      setCopied(true)
      setTimeout(() => setCopied(false), 1600)
    } catch {
      haptic('error')
      setMsg('COPY BLOCKED — SELECT THE CODE MANUALLY')
    }
  }

  const redeemNow = async () => {
    if (state.kind !== 'paid') return
    haptic('activate')
    setRedeem('busy')
    try {
      await redeemToProfile(state.code)
      haptic('complete')
      setRedeem('ok')
      setMsg('PASS BOUND TO YOUR PROFILE // OPENING THE GAMES')
      setTimeout(() => window.location.assign('/games'), 900)
    } catch (e) {
      haptic('error')
      setRedeem('error')
      setMsg(e instanceof Error ? e.message : 'REDEEM FAILED')
    }
  }

  const done = redeem === 'ok' || (unlocked && state.kind === 'paid' && state.used)

  return (
    <section className="bv-field relative min-h-[100svh] flex items-center" style={{ paddingTop: 'calc(56px + env(safe-area-inset-top))', backgroundColor: 'var(--col-black)' }}>
      <div className="relative max-w-[720px] mx-auto w-full px-4 md:px-8 py-12">
        <p className="font-oswald text-[11px] md:text-xs uppercase tracking-[0.35em] mb-4" style={{ color: 'var(--col-yellow)' }}>
          {state.kind === 'paid' ? 'PAYMENT VERIFIED' : state.kind === 'pending' ? 'PAYMENT IN TRANSIT' : 'SESSION NOT FOUND'}
        </p>
        <h1 className="font-anton uppercase tracking-tight" style={{ color: 'var(--col-ivory)', lineHeight: 0.92, fontSize: 'clamp(44px, 8vw, 104px)' }}>
          {state.kind === 'paid' ? 'YOU\'RE IN.' : state.kind === 'pending' ? 'HOLD TIGHT.' : 'NO PASS HERE.'}
        </h1>

        <div className="mt-10 p-6 md:p-8" style={{ backgroundColor: 'var(--col-gunmetal)', borderTop: '2px solid var(--col-yellow)', boxShadow: '0 24px 50px rgb(var(--bv-shadow-rgb) / 0.6)' }}>
          {state.kind === 'paid' ? (
            <>
              <p className="font-oswald text-[11px] uppercase tracking-[0.3em]" style={{ color: 'var(--col-bone)' }}>YOUR UNLOCK CODE // SINGLE USE</p>
              <p
                className="font-ibm select-all break-all mt-3 py-4 px-4"
                style={{ color: 'var(--col-yellow-hot)', backgroundColor: 'var(--col-black)', fontSize: 'clamp(22px, 5vw, 38px)', letterSpacing: '0.12em' }}
                aria-label="Unlock code"
              >
                {state.code}
              </p>
              <p className="font-ibm text-[11px] uppercase mt-3 leading-relaxed" style={{ color: 'var(--col-bone)' }}>
                Save it now. Redeem it once to your profile — then sign in on any device to keep access.
              </p>
              <div className="flex flex-col sm:flex-row gap-3 mt-6">
                <button type="button" onClick={copy} className={`${btn} text-sm`} style={ghost}>
                  {copied ? 'COPIED ✓' : 'COPY CODE'}
                </button>
                {done ? (
                  <Link href="/games" onClick={() => haptic('complete')} className={`${btn} text-base flex-1 hover:bg-[var(--col-yellow-hot)]`} style={gold}>
                    PLAY EVERYTHING →
                  </Link>
                ) : state.used ? (
                  <p className="font-oswald text-sm uppercase tracking-[0.2em] self-center" style={{ color: 'var(--col-bone)' }}>CODE ALREADY REDEEMED</p>
                ) : signedIn ? (
                  <button type="button" onClick={redeemNow} disabled={redeem === 'busy'} className={`${btn} text-base flex-1 hover:bg-[var(--col-yellow-hot)]`} style={gold}>
                    {redeem === 'busy' ? 'BINDING…' : 'REDEEM TO MY PROFILE'}
                  </button>
                ) : (
                  <Link href="/profile?next=redeem" onClick={() => haptic('press')} className={`${btn} text-sm flex-1 hover:bg-[var(--col-yellow-hot)]`} style={gold}>
                    SIGN IN OR CREATE PROFILE TO REDEEM
                  </Link>
                )}
              </div>
            </>
          ) : state.kind === 'pending' ? (
            <>
              <p className="font-ibm text-sm uppercase leading-relaxed" style={{ color: 'var(--col-bone)' }}>
                Stripe hasn&apos;t confirmed the payment yet. Your code appears here the moment it lands.
              </p>
              <button type="button" onClick={() => { haptic('press'); window.location.reload() }} className={`${btn} text-sm mt-6`} style={ghost}>
                REFRESH STATUS
              </button>
            </>
          ) : (
            <>
              <p className="font-ibm text-sm uppercase leading-relaxed" style={{ color: 'var(--col-bone)' }}>
                This checkout link doesn&apos;t match a payment. No charge was confirmed for it.
              </p>
              <Link href="/unlock" onClick={() => haptic('press')} className={`${btn} text-sm mt-6`} style={ghost}>
                ← BACK TO THE PASS
              </Link>
            </>
          )}
          <p role="status" aria-live="polite" className="font-ibm text-[11px] uppercase mt-4 min-h-[16px]" style={{ color: redeem === 'error' ? 'var(--col-yellow-hot)' : 'var(--col-bone)' }}>
            {msg}
          </p>
        </div>
      </div>
    </section>
  )
}

