export type LaunchPhase = 'grow' | 'hold' | 'collapse'

interface LaunchOverlayProps {
  rect: { top: number; left: number; width: number; height: number }
  phase: LaunchPhase
  title: string
  imageUrl: string | null
  outcome: 'launch' | 'pending' | 'offline'
}

const OUTCOME_TEXT = {
  launch: { kicker: 'SYSTEM ACTIVE', line: 'LAUNCHING' },
  pending: { kicker: 'LINK PENDING', line: 'STANDBY — ROUTE NOT WIRED' },
  offline: { kicker: 'SIGNAL OFFLINE', line: 'COMING ONLINE SOON' },
} as const

// The window's panel expands from its own footprint to the full viewport — the button IS the transition.
export function LaunchOverlay({ rect, phase, title, imageUrl, outcome }: LaunchOverlayProps) {
  const [vw, setVw] = useState(0)
  const [vh, setVh] = useState(0)
  const [expanded, setExpanded] = useState(false)

  useEffect(() => {
    setVw(window.innerWidth)
    setVh(window.innerHeight)
    const id = requestAnimationFrame(() => requestAnimationFrame(() => setExpanded(true)))
    return () => cancelAnimationFrame(id)
  }, [])

  const open = expanded && phase !== 'collapse'
  const inset = `inset(${rect.top}px ${Math.max(0, vw - rect.left - rect.width)}px ${Math.max(0, vh - rect.top - rect.height)}px ${rect.left}px)`
  const txt = OUTCOME_TEXT[outcome]
  const accent = outcome === 'launch' ? 'var(--col-yellow-hot)' : 'var(--col-yellow)'

  return (
    <div
      className="fixed inset-0 z-[100] pointer-events-none"
      aria-live="assertive"
      style={{
        clipPath: open ? 'inset(0px 0px 0px 0px)' : inset,
        transition: 'clip-path 620ms cubic-bezier(0.77, 0, 0.18, 1)',
        backgroundColor: 'var(--col-black)',
      }}
    >
      {imageUrl ? (
        <img src={imageUrl} alt="" className="absolute inset-0 w-full h-full object-cover" style={{ opacity: 0.55 }} />
      ) : null}
      <div
        className="absolute inset-0"
        style={{ background: 'radial-gradient(ellipse at center, rgb(var(--bv-surface-2-rgb) / 0.45) 0%, rgb(var(--bv-bg-rgb) / 0.94) 70%)' }}
      />

      <div
        className="absolute inset-0 flex flex-col items-center justify-center px-6 text-center"
        style={{ opacity: open ? 1 : 0, transition: 'opacity 260ms ease 260ms' }}
      >
        <MachineGauge state={outcome === 'launch' ? 'active' : 'activating'} size={96} />
        <p className="font-oswald uppercase tracking-[0.45em] text-xs md:text-sm mt-8" style={{ color: accent }}>
          {txt.kicker}
        </p>
        <h2
          className="font-anton uppercase leading-[0.88] mt-4"
          style={{ color: 'var(--col-ivory)', fontSize: 'clamp(44px, 9vw, 150px)' }}
