import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { isValidId } from '@/lib/api-guards';

// POST: Execute a raid — confiscate resources, reduce heat
export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const { sessionId } = body ?? {};
    if (!isValidId(sessionId)) {
      return NextResponse.json({ error: 'Missing sessionId' }, { status: 400 });
    }

    const session = await prisma.gameSession.findUnique({
      where: { id: sessionId },
      include: { resources: true },
    });
    if (!session) {
      return NextResponse.json({ error: 'Session not found' }, { status: 404 });
    }

    // Confiscate 30-60% of each resource
    const resourcesLost: { type: string; lost: number }[] = [];
    for (const resource of session.resources ?? []) {
      if ((resource?.quantity ?? 0) > 0) {
        const confiscateRate = 0.3 + ((session?.day ?? 1) % 3) * 0.15; // 30-60% based on day
        const lost = Math.ceil((resource?.quantity ?? 0) * confiscateRate);
        if (lost > 0) {
          await prisma.resource.update({
            where: { id: resource.id },
            data: { quantity: Math.max(0, (resource?.quantity ?? 0) - lost) },
          });
          resourcesLost.push({ type: resource.type, lost });
        }
      }
    }

    // Reduce heat significantly after raid (justice served)
    const heatAfter = Math.max(0, (session?.heat ?? 0) * 0.4); // Drop to 40%
    await prisma.gameSession.update({
      where: { id: sessionId },
      data: { heat: heatAfter },
    });

    // Survived if heat was below 9 (second raid at 9+ = game over)
    const survived = (session?.heat ?? 0) < 9;

    return NextResponse.json({
      resourcesLost,
      heatAfter,
      survived,
    });
  } catch (err: unknown) {
    console.error('Raid error:', err);
    return NextResponse.json({ error: 'Failed' }, { status: 500 });
  }
}

