    const t2 = setTimeout(() => { audioManager.playSFX('error'); setPhase('result'); }, 6000);
    const t3 = setTimeout(() => setShowBtn(true), 8000);
    return () => { clearTimeout(t1); clearTimeout(t2); clearTimeout(t3); };
  }, []);

  const flavour = RAID_FLAVOUR[Math.abs((game?.day ?? 0) % RAID_FLAVOUR.length)];
  const recruited = (game?.npcs ?? []).filter((n) => n?.recruited && n?.name);

  return (
    <div className="w-full h-full bg-[#050505] flex items-center justify-center p-4 overflow-auto" role="alert" aria-label="Raid event">
      <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="max-w-lg sm:max-w-xl w-full text-center">
        {/* Phase: Intro — CCTV surveillance frame */}
        {phase === 'intro' && (
          <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="relative">
            {/* CCTV frame overlay */}
            <div className="absolute inset-0 pointer-events-none border-2 border-[#a8687e]/20 rounded-sm">
              <div className="absolute top-2 left-3 font-terminal text-[9px] text-[#a8687e]/40 tracking-widest">
                CAM-03 ● REC
              </div>
              <div className="absolute top-2 right-3 font-terminal text-[9px] text-[#a8687e]/30">
                {String(game?.day ?? 1).padStart(3, '0')}.{String(Math.abs((game?.day ?? 0) * 7 + 23) % 24).padStart(2, '0')}:{String(Math.abs((game?.day ?? 0) * 13 + 47) % 60).padStart(2, '0')}
              </div>
              {/* Corner brackets */}
              <div className="absolute top-0 left-0 w-4 h-4 border-t-2 border-l-2 border-[#a8687e]/30" />
              <div className="absolute top-0 right-0 w-4 h-4 border-t-2 border-r-2 border-[#a8687e]/30" />
              <div className="absolute bottom-0 left-0 w-4 h-4 border-b-2 border-l-2 border-[#a8687e]/30" />
              <div className="absolute bottom-0 right-0 w-4 h-4 border-b-2 border-r-2 border-[#a8687e]/30" />
              {/* Scanline effect */}
              <motion.div
                animate={{ y: ['0%', '100%'] }}
                transition={{ duration: 2, repeat: Infinity, ease: 'linear' }}
                className="absolute left-0 right-0 h-[1px] bg-[#a8687e]/10"
              />
            </div>

            <div className="py-8">
              <motion.div
                animate={{ opacity: [0.4, 1, 0.4] }}
                transition={{ duration: 0.6, repeat: Infinity }}
                className="flex justify-center mb-6"
              >
                <AlertIcon size={72} color="#a8687e" />
              </motion.div>
              <h2 className="font-creepy text-3xl text-[#a8687e] mb-4 animate-pulse-neon">RAID</h2>
              <p className="font-typewriter text-sm text-[#E8E8E8]/50 italic">&quot;{flavour}&quot;</p>
            </div>
          </motion.div>
        )}

        {/* Phase: Damage report + crew reactions */}
        {phase === 'damage' && (
          <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="space-y-3">
            <h3 className="font-terminal text-lg text-[#a8687e]">CONFISCATION REPORT</h3>
            <div className="border border-[#a8687e]/20 p-4 bg-[#0a0a0a] space-y-2">
              {raidResult.resourcesLost.map((r, i) => (
                <div key={i} className="flex justify-between font-terminal text-sm">
                  <span className="text-[#E8E8E8]/40 uppercase">{r.type}</span>
                  <span className="text-[#a8687e]">-{r.lost}</span>
                </div>
              ))}
              {raidResult.resourcesLost.length === 0 && (
                <p className="text-[#4a4a3a] text-xs font-typewriter">Nothing to confiscate. They looked disappointed.</p>
              )}
            </div>

            {/* Crew reactions during the raid */}
            {recruited.length > 0 && (
              <motion.div
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ delay: 0.8, duration: 0.6 }}
                className="space-y-1.5 pt-2"
              >
                {recruited.map((npc, idx) => {
                  const reaction = CREW_RAID_REACTIONS[npc.name ?? ''];
                  if (!reaction) return null;
                  const line = raidResult.survived ? reaction.survived : reaction.failed;
                  return (
                    <motion.p
                      key={npc.name}
                      initial={{ opacity: 0, x: -10 }}
                      animate={{ opacity: 1, x: 0 }}
                      transition={{ delay: 0.8 + idx * 0.4 }}
                      className="font-caveat text-xs text-[#E8E8E8]/30 italic text-left pl-4"
                    >
                      {line}
                    </motion.p>
                  );
                })}
              </motion.div>
            )}
          </motion.div>
        )}

        {/* Phase: Result */}
        {phase === 'result' && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="space-y-4">
            <h3 className="font-terminal text-lg" style={{ color: raidResult.survived ? '#CCAA00' : '#a8687e' }}>
              {raidResult.survived ? 'YOU SURVIVED THE RAID' : 'OPERATION COMPROMISED'}
            </h3>
            <p className="font-typewriter text-xs text-[#E8E8E8]/40">
              {raidResult.survived
                ? 'They took what they could carry. Heat has been reduced. Keep your head down.'
                : 'The walls are closing in. One more like this and it\'s over.'}
            </p>
            <p className="font-terminal text-xs text-[#4a4a3a]">HEAT AFTER RAID: {raidResult.heatAfter.toFixed(1)}</p>
          </motion.div>
        )}

        {/* Continue */}
        {showBtn && (
          <motion.button
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            onClick={onContinue}
            className="mt-8 font-terminal text-sm px-8 py-2 border border-[#CCAA00]/40 text-[#CCAA00] hover:bg-[#CCAA00] hover:text-[#080808] transition-all active:scale-95 cursor-pointer"
          >
            {raidResult.survived ? 'PICK UP THE PIECES' : 'FACE THE MUSIC'}
          </motion.button>
        )}
      </motion.div>
    </div>
  );
}

