'use client'

import { useCallback, useEffect, useRef, useState } from 'react'
import { usePathname } from 'next/navigation'
import { haptic } from '@/lib/haptics'

// The launch seal: GREY.FILTER emblem as the app's front door. Pressing it splits the seal
// on a gold seam, tears a light bar open and reveals the page. The same press starts the
// soundtrack (loops, no visitor controls). Lives in the root layout so the music survives
// client-side navigation.
const GATED = new Set(['/', '/games', '/contact'])
const TRACK = '/audio/teeth-of-the-great-press.mp3'
const SEAL = '/assets/gate-seal.png'
const MAX_PARTICLES = 180

type Phase = 'locked' | 'running' | 'reveal' | 'done'

interface Particle { x: number; y: number; vx: number; vy: number; life: number; max: number; r: number; wob: number; wsf: number }

export function LaunchGate({ enabled, label }: { enabled: boolean; label: string }) {
  const pathname = usePathname()
  const [phase, setPhase] = useState<Phase>(() => (enabled && GATED.has(pathname ?? '') ? 'locked' : 'done'))
  const audioRef = useRef<HTMLAudioElement>(null)
  const rootRef = useRef<HTMLDivElement>(null)
  const sealRef = useRef<HTMLButtonElement>(null)
  const stackRef = useRef<HTMLDivElement>(null)
  const halfL = useRef<HTMLDivElement>(null)
  const halfR = useRef<HTMLDivElement>(null)
  const seamRef = useRef<HTMLDivElement>(null)
  const barRef = useRef<HTMLDivElement>(null)
  const flashRef = useRef<HTMLDivElement>(null)
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const timers = useRef<number[]>([])
  const started = useRef(false)
  const pathRef = useRef(pathname)
  useEffect(() => {
    pathRef.current = pathname
  }, [pathname])

  const startMusic = useCallback(() => {
    const a = audioRef.current
    if (!a || started.current) return
    a.volume = 1
    const p = a.play()
    started.current = true
    // blocked by the browser: retry on the next interaction
    p?.catch?.((err: unknown) => {
      started.current = false
      console.error('Soundtrack blocked until next interaction', err)
    })
  }, [])

  // Fallback: no seal on this load (gate off, or entered via another page) — the first
  // tap/key on a public page starts the track; also retries if the browser blocked play().
  useEffect(() => {
    const onFirst = () => {
      if (phase === 'locked' || phase === 'running') return
      if (!GATED.has(pathRef.current ?? '')) return
      startMusic()
    }
    window.addEventListener('pointerdown', onFirst)
    window.addEventListener('keydown', onFirst)
    return () => {
      window.removeEventListener('pointerdown', onFirst)
      window.removeEventListener('keydown', onFirst)
    }
  }, [phase, startMusic])

  // While locked: page behind is inert and does not scroll; the seal holds focus.
  useEffect(() => {
    if (phase !== 'locked' && phase !== 'running') return
    const root = rootRef.current
    const siblings = Array.from(document.body.children).filter((el) => el !== root && !el.contains(root)) as HTMLElement[]
    siblings.forEach((el) => el.setAttribute('inert', ''))
    const html = document.documentElement
    const prevOverflow = html.style.overflow
    html.style.overflow = 'hidden'
    if (phase === 'locked') sealRef.current?.focus({ preventScroll: true })
    return () => {
      siblings.forEach((el) => el.removeAttribute('inert'))
      html.style.overflow = prevOverflow
    }
  }, [phase])

  useEffect(() => () => timers.current.forEach((t) => window.clearTimeout(t)), [])

  const later = (fn: () => void, ms: number) => {
    timers.current.push(window.setTimeout(fn, ms))
  }

  // Steam: one burst system, hard-capped, runs only during the release (~2s)
  const runSteam = (seconds: number) => {
    const canvas = canvasRef.current
    const seal = sealRef.current
    const ctx = canvas?.getContext('2d')
    if (!canvas || !seal || !ctx) return { spawn: () => {} }
    const dpr = Math.min(window.devicePixelRatio || 1, 2)
    canvas.width = Math.floor(canvas.clientWidth * dpr)
    canvas.height = Math.floor(canvas.clientHeight * dpr)
    const parts: Particle[] = []
    const r = seal.getBoundingClientRect()
    const cx = (r.left + r.width / 2) * dpr
    const cy = (r.top + r.height / 2) * dpr
    const rad = (r.width / 2) * dpr
    const spawn = (n: number, burst: boolean) => {
      for (let i = 0; i < n && parts.length < MAX_PARTICLES; i++) {
        const sp = burst ? (3 + Math.random() * 8) * dpr : (0.6 + Math.random() * 1.8) * dpr
        parts.push({
          x: cx + (Math.random() - 0.5) * 10 * dpr,
          y: cy + (Math.random() * 2 - 1) * rad * 0.85,
          vx: (Math.random() - 0.5) * (burst ? 8 : 1.5) * dpr,
          vy: -Math.abs(Math.sin(-Math.PI / 2 + (Math.random() - 0.5) * 1.2)) * sp,
          life: 0,
          max: 0.9 + Math.random() * 1.2,
          r: (6 + Math.random() * 20) * dpr,
          wob: Math.random() * Math.PI * 2,
          wsf: 1.5 + Math.random() * 2.5,
        })
      }
    }
    // Canvas cannot read CSS vars directly: pull the banner token once
    const steamRgb = (getComputedStyle(document.documentElement).getPropertyValue('--bv-text-strong-rgb').trim() || '241 231 213').split(/\s+/).join(',')
    const end = performance.now() + seconds * 1000
    let last = performance.now()
    const tick = (t: number) => {
      const dt = Math.min((t - last) / 16.67, 3) || 0.6
      last = t
      ctx.clearRect(0, 0, canvas.width, canvas.height)
      if (t > end || !canvas.isConnected) return
      if (!document.hidden) {
        ctx.globalCompositeOperation = 'lighter'
        for (let i = parts.length - 1; i >= 0; i--) {
          const p = parts[i]
          p.life += 0.016 * dt
          if (p.life > p.max) { parts.splice(i, 1); continue }
          p.wob += 0.05 * p.wsf * dt
          p.x += (p.vx + Math.sin(p.wob) * 0.4 * dpr) * dt
          p.y += p.vy * dt
          p.vy -= 0.012 * dpr * dt
          const k = p.life / p.max
          const alpha = (k < 0.15 ? k / 0.15 : 1 - (k - 0.15) / 0.85) * 0.18
          const g = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, p.r)
          g.addColorStop(0, `rgba(${steamRgb},${alpha})`)
          g.addColorStop(1, `rgba(${steamRgb},0)`)
          ctx.fillStyle = g
          ctx.beginPath()
          ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2)
          ctx.fill()
        }
      }
      requestAnimationFrame(tick)
    }
    requestAnimationFrame(tick)
    return { spawn }
  }

  const release = () => {
    if (phase !== 'locked') return
    startMusic() // inside the press gesture, so autoplay rules allow it
    haptic('press')
    const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches
    if (reduced) {
      // single gold reveal, no rotation/split/steam
      setPhase('reveal')
      haptic('complete')
      return
    }
    setPhase('running')
    const steam = runSteam(2.4)

    // 1 — dial: compress, over-rotate, counter-rotate, settle
    stackRef.current?.animate(
      [
        { transform: 'rotate(0deg) scale(1)' },
        { transform: 'rotate(0deg) scale(0.975)', offset: 0.12 },
        { transform: 'rotate(11deg) scale(0.99)', offset: 0.42 },
        { transform: 'rotate(-5deg)', offset: 0.74 },
        { transform: 'rotate(0deg)' },
      ],
      { duration: 680, easing: 'cubic-bezier(0.2, 0.9, 0.25, 1.1)' },
    )

    // 2 — seam ignites, the stage jolts
    later(() => {
      haptic('activate')
      seamRef.current?.animate([{ transform: 'translateX(-50%) scaleY(0)', opacity: 1 }, { transform: 'translateX(-50%) scaleY(1)', opacity: 1 }], {
        duration: 150,
        easing: 'ease-out',
        fill: 'forwards',
      })
      rootRef.current?.querySelector('.gate-stage')?.animate(
        [
          { transform: 'translate(0,0)' },
          { transform: 'translate(-4px,2px)' },
          { transform: 'translate(4px,-3px)' },
          { transform: 'translate(-3px,-1px)' },
          { transform: 'translate(2px,2px)' },
          { transform: 'translate(0,0)' },
        ],
        { duration: 320, easing: 'linear' },
      )
      steam.spawn(50, false)
    }, 640)

    // 3 — split: halves shear apart like blast doors, light tears open
    later(() => {
      steam.spawn(130, true)
      const off = Math.max(window.innerWidth * 0.16, 90)
      const shear = (el: HTMLDivElement | null, dir: 1 | -1) =>
        el?.animate(
          [
            { transform: 'translateX(0) rotate(0deg)', opacity: 1 },
            { transform: `translateX(${dir * off * 0.3}px) rotate(${dir * 2}deg)`, opacity: 1, offset: 0.45 },
            { transform: `translateX(${dir * off}px) rotate(${dir * 8}deg)`, opacity: 0 },
          ],
          { duration: 760, easing: 'cubic-bezier(0.5, 0, 0.2, 1)', fill: 'forwards' },
        )
      shear(halfL.current, -1)
      shear(halfR.current, 1)
      barRef.current?.animate(
        [
          { transform: 'translateX(-50%) scaleX(0.004)', opacity: 1 },
          { transform: 'translateX(-50%) scaleX(1)', opacity: 1 },
        ],
        { duration: 700, delay: 100, easing: 'cubic-bezier(0.7, 0, 0.9, 0.4)', fill: 'forwards' },
      )
      rootRef.current?.querySelectorAll('.gate-aura, .gate-ring').forEach((el) =>
        el.animate([{ opacity: 1 }, { opacity: 0 }], { duration: 300, fill: 'forwards' }),
      )
    }, 980)

    // 4 — flash in, gate out, page revealed
    later(() => {
      flashRef.current?.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 150, easing: 'ease-in', fill: 'forwards' })
    }, 1500)
    later(() => {
      setPhase('reveal')
      haptic('complete')
    }, 1660)
  }

  const onRevealEnd = () => setPhase('done')

  return (
    <>
      <audio ref={audioRef} src={TRACK} loop preload="auto" aria-hidden="true" className="hidden" />
      {(phase === 'locked' || phase === 'running') && (
        <div
          ref={rootRef}
          id="launch-gate"
          role="dialog"
          aria-modal="true"
          aria-label="Launch seal — press to enter Baseline Velocity"
          className={`launch-gate ${phase === 'running' ? 'is-armed' : ''}`}
        >
          <div className="gate-ticks" aria-hidden="true"><i className="t" /><i className="b" /><i className="l" /><i className="r" /></div>
          <canvas ref={canvasRef} className="gate-steam" aria-hidden="true" />
          <div className="gate-stage">
            <div ref={barRef} className="gate-bar" aria-hidden="true" />
            <button ref={sealRef} type="button" className="gate-seal" onClick={release} aria-label="Press the seal to enter">
              <span className="gate-aura" aria-hidden="true" />
              <svg className="gate-ring" viewBox="0 0 100 100" aria-hidden="true">
                <circle cx="50" cy="50" r="49" fill="none" style={{ stroke: 'rgb(var(--bv-primary-rgb) / 0.35)' }} strokeWidth="0.25" />
                <path d="M50 0v3M50 97v3M0 50h3M97 50h3" style={{ stroke: 'var(--bv-primary)' }} strokeWidth="0.5" />
              </svg>
              <svg className="gate-focus" viewBox="0 0 100 100" aria-hidden="true">
                <circle cx="50" cy="50" r="49.2" fill="none" style={{ stroke: 'var(--bv-accent)' }} strokeWidth="0.8" />
              </svg>
              <div ref={stackRef} className="gate-stack">
                <div ref={halfL} className="gate-half l" style={{ backgroundImage: `url(${SEAL})` }} />
                <div ref={halfR} className="gate-half r" style={{ backgroundImage: `url(${SEAL})` }} />
                <div ref={seamRef} className="gate-seam" aria-hidden="true" />
              </div>
            </button>
          </div>
          <p className="gate-prompt font-oswald" aria-hidden="true">{label || 'PRESS THE SEAL'}</p>
          <div ref={flashRef} className="gate-flash" aria-hidden="true" />
        </div>
      )}
      {phase === 'reveal' && <div className="gate-flash is-out" aria-hidden="true" onAnimationEnd={onRevealEnd} />}
    </>
  )
}

