};

// ── NPC colour assignments ──
const getNpcColor = (name: string): string => {
  const colors: Record<string, string> = { Dave: '#8aad7a', Sid: '#a8687e', Tamara: '#7ab8b8', Mikey: '#b0926a' };
  return colors[name] ?? '#8aad7a';
};

// ── Win #11: Qualitative stat band labels ──
const getStatBand = (value: number): { label: string; color: string } => {
  if (value <= 2) return { label: 'LOW', color: '#4a4a3a' };
  if (value <= 4) return { label: 'MODERATE', color: '#8aad7a' };
  if (value <= 6) return { label: 'ELEVATED', color: '#FFFF00' };
  if (value <= 8) return { label: 'HIGH', color: '#FF8C00' };
  return { label: 'EXTREME', color: '#a8687e' };
};

// ── Win #10: Affinity thematic labels ──
const getAffinityLabel = (affinity: number): string => {
  if (affinity >= 80) return 'IN YOUR ORBIT';
  if (affinity >= 60) return 'LOYAL ENOUGH';
  if (affinity >= 40) return 'WARMING UP';
  if (affinity >= 20) return 'WARY';
  return "DOESN'T TRUST YOU";
};

// ── Win #5: Vice preference icon ──
const getPrefIcon = (pref: number): { icon: string; color: string } => {
  if (pref >= 2) return { icon: '▲▲', color: '#8aad7a' };
  if (pref === 1) return { icon: '▲', color: '#8aad7a' };
  if (pref === 0) return { icon: '─', color: '#4a4a3a' };
  if (pref === -1) return { icon: '▼', color: '#b87a96' };
  return { icon: '▼▼', color: '#a8687e' };
};

// ── Win #9: Status badge styling ──
const getStatusStyle = (status: string): { bg: string; text: string; border: string } => {
  switch (status?.toUpperCase()) {
    case 'ON_MISSION': return { bg: 'rgba(255,75,193,0.06)', text: '#b87a96', border: 'rgba(255,75,193,0.3)' };
    case 'RECOVERING': return { bg: 'rgba(255,140,0,0.06)', text: '#FF8C00', border: 'rgba(255,140,0,0.3)' };
    case 'ABSENT': return { bg: 'rgba(255,0,0,0.06)', text: '#ff5e57', border: 'rgba(255,94,87,0.3)' };
    default: return { bg: 'rgba(138,173,122,0.04)', text: '#8aad7a', border: 'rgba(138,173,122,0.2)' };
  }
};

