export const dynamic = 'force-dynamic';

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { NPC_DATA, MISSION_DEFINITIONS } from '@/lib/game-data';
import { isValidId, validateResourceType } from '@/lib/api-guards';

// PATCH: Update player stats after character creation (Clinical History assessment)
export async function PATCH(req: NextRequest) {
  try {
    const body = await req.json();
    const { sessionId, playerName, nerve, insight, presence, mobility, philosophy, startingResources } = body ?? {};
    if (!isValidId(sessionId)) return NextResponse.json({ error: 'Missing sessionId' }, { status: 400 });

    // Clinical History: base 2 per stat, +2 from injury page, +2 from trauma page → valid range 2-6
    const clamp = (v: number) => Math.max(0, Math.min(10, v ?? 2));

    // Sanitise playerName: strip HTML, clamp length
    const safeName = typeof playerName === 'string'
      ? playerName.replace(/<[^>]*>/g, '').trim().slice(0, 40) || 'Manager'
      : 'Manager';

    const session = await prisma.gameSession.update({
      where: { id: sessionId },
      data: {
        playerName: safeName,
        nerve: clamp(nerve),
        insight: clamp(insight),
        presence: clamp(presence),
        mobility: clamp(mobility),
        philosophy: ['SHEPHERD', 'ENTREPRENEUR', 'PROPHET'].includes(philosophy) ? philosophy : 'SHEPHERD',
      },
      include: { npcs: true, resources: true },
    });

    // Apply inheritance resource overrides if provided — allowlist types
    if (startingResources && typeof startingResources === 'object') {
      for (const [rawType, quantity] of Object.entries(startingResources)) {
        const validType = validateResourceType(rawType);
        if (validType && typeof quantity === 'number') {
          await prisma.resource.updateMany({
            where: { sessionId, type: validType },
            data: { quantity: Math.max(0, Math.min(30, quantity)) },
          });
        }
      }
    }

    // Re-fetch with updated resources
    const updated = await prisma.gameSession.findUnique({
      where: { id: sessionId },
      include: { npcs: true, resources: true },
    });
    return NextResponse.json(updated);
  } catch (err: unknown) {
    console.error('Update stats error:', err);
    return NextResponse.json({ error: 'Failed' }, { status: 500 });
  }
}

// POST: Create new game session
export async function POST() {
  try {
    const session = await prisma.gameSession.create({
      data: {
        phase: 'HUB',
        day: 1,
        heat: 0,
        resources: {
          create: [
            { type: 'cigarettes', quantity: 8 },
            { type: 'alcohol', quantity: 3 },
            { type: 'weed', quantity: 1 },
            { type: 'crystals', quantity: 0 },
          ],
        },
        npcs: {
          create: Object.entries(NPC_DATA).map(([key, npc]) => ({
            name: npc?.name ?? key,
            archetype: npc?.archetype ?? '',
            role: npc?.role ?? '',
            specialty: npc?.specialty ?? '',
            skill: npc?.skill ?? '',
            recruited: false,
            affinity: 0,
            status: 'AVAILABLE',
            heatLevel: npc?.heatLevel ?? 0,
            muscle: npc?.muscle ?? 0,
            brains: npc?.brains ?? 0,
            unpredictability: npc?.unpredictability ?? 0,
            portraitUrl: npc?.portraitUrl ?? '',
            recruitStage: 0,
            parsingProgress: 0,
          })),
        },
      },
      include: { npcs: true, resources: true, missions: true },
    });

    // Seed initial missions from definitions
    const missionCreates = Object.entries(MISSION_DEFINITIONS).map(([key, def]) => ({
      sessionId: session.id,
      missionKey: key,
      type: def.type,
      tier: def.tier,
      status: def.initialStatus ?? 'LOCKED',
    }));
    if (missionCreates.length > 0) {
      await prisma.mission.createMany({ data: missionCreates });
    }

    // Re-fetch with missions included
    const fullSession = await prisma.gameSession.findUnique({
      where: { id: session.id },
      include: { npcs: true, resources: true, missions: true, expeditions: true },
    });
    return NextResponse.json(fullSession);
  } catch (err: unknown) {
    console.error('Create game error:', err);
    return NextResponse.json({ error: 'Failed to create game' }, { status: 500 });
  }
}

// GET: Load game session
export async function GET(req: NextRequest) {
  try {
    const sessionId = req.nextUrl.searchParams.get('id');
    if (!sessionId || !isValidId(sessionId)) {
      // Get most recent session (or no valid id provided)
      const session = await prisma.gameSession.findFirst({
        orderBy: { updatedAt: 'desc' },
        include: { npcs: true, resources: true, expeditions: true, missions: true },
      });
      if (!session) return NextResponse.json({ error: 'No game found' }, { status: 404 });
      return NextResponse.json(session);
    }
    const session = await prisma.gameSession.findUnique({
      where: { id: sessionId },
      include: { npcs: true, resources: true, expeditions: true, missions: true },
    });
    if (!session) return NextResponse.json({ error: 'Session not found' }, { status: 404 });
    return NextResponse.json(session);
  } catch (err: unknown) {
    console.error('Load game error:', err);
    return NextResponse.json({ error: 'Failed to load game' }, { status: 500 });
  }
}

