import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { safeNumber, clampHeat, isValidId } from '@/lib/api-guards';

// v0.6.0 — Increment / decrement session heat (e.g., expedition extract).
// Body: { sessionId: string, change: number }   change is delta (±).
export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const sessionId = body?.sessionId;
    if (!isValidId(sessionId)) {
      return NextResponse.json({ error: 'Missing sessionId' }, { status: 400 });
    }
    const change = safeNumber(body?.change, 0);
    if (change === 0) {
      return NextResponse.json({ error: 'Missing or zero change' }, { status: 400 });
    }
    // Clamp delta to ±10 to prevent abuse
    const clampedChange = Math.max(-10, Math.min(10, change));

    const session = await prisma.gameSession.findUnique({ where: { id: sessionId }, select: { heat: true } });
    if (!session) {
      return NextResponse.json({ error: 'Session not found' }, { status: 404 });
    }
    const newHeat = clampHeat((session.heat ?? 0) + clampedChange);

    const updated = await prisma.gameSession.update({
      where: { id: sessionId },
      data: { heat: newHeat },
      select: { id: true, heat: true },
    });
    return NextResponse.json(updated);
  } catch (err: unknown) {
    console.error('Heat update error:', err);
    return NextResponse.json({ error: 'Failed' }, { status: 500 });
  }
}

