import { useEffect, useRef, useState } from 'react'
import Image from 'next/image'
import * as Dialog from '@radix-ui/react-dialog'
import { motion, useReducedMotion } from 'framer-motion'
import { Maximize2, Minus, Plus, RotateCcw, X } from 'lucide-react'
import { useHud } from './hud-context'
import styles from './artwork-viewer.module.css'

interface ArtworkViewerProps {
  src: string
  alt: string
  title: string
  caption?: string
  open: boolean
  onOpenChange: (open: boolean) => void
}

/** Shared, focus-trapped artwork inspection. Originals are never cropped or altered. */
export function ArtworkViewer({ src, alt, title, caption, open, onOpenChange }: ArtworkViewerProps) {
  const hud = useHud()
  const reduced = useReducedMotion()
  const [zoom, setZoom] = useState(1)
  const [failed, setFailed] = useState(false)
  const [bounds, setBounds] = useState({ width: 0, height: 0 })
  const [resetKey, setResetKey] = useState(0)
  const viewport = useRef<HTMLDivElement>(null)
  useEffect(() => { setZoom(1); setFailed(false); setResetKey((n) => n + 1) }, [open, src])
  useEffect(() => {
    if (!open) return
    const frame = requestAnimationFrame(() => {
      const node = viewport.current
      if (node) setBounds({ width: node.clientWidth, height: node.clientHeight })
    })
    const observer = new ResizeObserver((entries) => {
      const rect = entries[0]?.contentRect
      if (rect) setBounds({ width: rect.width, height: rect.height })
    })
    // Dialog portals attach after the opening render.
    const timer = window.setTimeout(() => { if (viewport.current) observer.observe(viewport.current) }, 0)
    return () => { cancelAnimationFrame(frame); clearTimeout(timer); observer.disconnect() }
  }, [open])
  const changeZoom = (next: number) => {
    setZoom(Math.max(1, Math.min(3, next)))
    setResetKey((n) => n + 1)
    hud.pulse('tick')
  }
  return <Dialog.Root open={open} onOpenChange={(value) => { onOpenChange(value); hud.pulse('press') }}>
    <Dialog.Portal>
      <Dialog.Overlay className={styles.backdrop} />
      <Dialog.Content className={styles.viewer} data-hud-control onKeyDown={(e) => e.stopPropagation()} onEscapeKeyDown={(e) => e.stopPropagation()}>
        <header className={styles.header}>
          <div><span className={styles.eyebrow}><Maximize2 size={12} /> ARTWORK / INSPECTION</span><Dialog.Title>{title}</Dialog.Title></div>
          <Dialog.Close className={styles.button} aria-label="Close artwork inspector"><X size={19} /></Dialog.Close>
        </header>
        <div ref={viewport} className={styles.viewport}>
          {failed ? <p className={styles.error}>Artwork unavailable. Close and reopen to retry.</p> : <motion.div key={`${src}-${resetKey}`} className={styles.imagePlane}
            drag={zoom > 1} dragConstraints={{ left: -bounds.width * (zoom - 1) / 2, right: bounds.width * (zoom - 1) / 2, top: -bounds.height * (zoom - 1) / 2, bottom: bounds.height * (zoom - 1) / 2 }} dragElastic={0} dragMomentum={false}
            style={{ cursor: zoom > 1 ? 'grab' : 'default' }} animate={{ scale: zoom }} transition={{ duration: reduced ? 0 : 0.16 }}>
            <Image src={src} alt={alt} fill sizes="95vw" className={styles.image} draggable={false} onError={() => { console.error(`Artwork inspector could not load: ${src}`); setFailed(true) }} />
          </motion.div>}
        </div>
        <footer className={styles.footer}>
          <Dialog.Description>{caption || 'Supplied artwork · original composition'}<span>{zoom > 1 ? 'Drag to inspect the artwork' : 'Zoom to inspect details'}</span></Dialog.Description>
          <div className={styles.tools}>
            <button className={styles.button} disabled={zoom <= 1} onClick={() => changeZoom(zoom - 0.5)} aria-label="Zoom out"><Minus size={16} /></button>
            <output aria-live="polite">{zoom.toFixed(1)}×</output>
            <button className={styles.button} disabled={zoom >= 3} onClick={() => changeZoom(zoom + 0.5)} aria-label="Zoom in"><Plus size={16} /></button>
            <button className={styles.button} onClick={() => changeZoom(1)} aria-label="Reset artwork view"><RotateCcw size={15} /></button>
          </div>
        </footer>
      </Dialog.Content>
    </Dialog.Portal>
  </Dialog.Root>
}

