 */
export default function Template({ children }: { children: React.ReactNode }) {
  const [wiping, setWiping] = useState(true)
  const [reverse, setReverse] = useState(false)
  const pathname = usePathname()

  // Before paint on client navigations: pick the sweep direction so the beam never starts the wrong way
  useLayoutEffect(() => {
    if (!booted) {
      booted = true
      try { sessionStorage.setItem(LAST_PATH_KEY, pathname) } catch {}
      return
    }
    setReverse(consumeWipeDirection(pathname) === 'reverse')
  }, [pathname])

  useEffect(() => {
    // Only after a real tap/click (navigation) — a cold page load has no user activation for vibrate
    const activated = (navigator as Navigator & { userActivation?: { hasBeenActive: boolean } }).userActivation?.hasBeenActive
    if (activated && !window.matchMedia('(prefers-reduced-motion: reduce)').matches) haptic('toggle')
    const t = window.setTimeout(() => setWiping(false), 760)
    return () => window.clearTimeout(t)
  }, [])

  return (
    <>
      <div className={reverse ? 'page-reveal is-reverse' : 'page-reveal'}>{children}</div>
      {wiping && (
        <div className={reverse ? 'laser-wipe is-reverse' : 'laser-wipe'} aria-hidden="true">
          <span className="laser-veil" />
          <span className="laser-flash" />
          <span className="laser-carriage">
            <span className="laser-scorch" />
            <span className="laser-bloom" />
            <span className="laser-beam" />
            {SPARKS.map(([top, delay, dx, dy, a], i) => (
              <span
                key={i}
                className="laser-spark"
                style={{ top: `${top}%`, animationDelay: `${delay}ms`, ['--dx' as string]: `${dx}px`, ['--dy' as string]: `${dy}px`, ['--a' as string]: `${a}deg` } as React.CSSProperties}
              />
            ))}
          </span>
        </div>
      )}
    </>
  )
}

