import { isOn, type SiteContentMap } from './site-defaults'

export type NavSection = { id: 'works' | 'games' | 'contact'; label: string; href: string }

/** Page list for the nav, in the owner's order. Hidden pages drop out. */
export function navSections(content: SiteContentMap): NavSection[] {
  const archive: NavSection | null = isOn(content.showArchive) ? { id: 'games', label: content.navGamesLabel || 'GAMES', href: '/games' } : null
  const contact: NavSection | null = isOn(content.showContact) ? { id: 'contact', label: content.navContactLabel || 'CONTACT', href: '/contact' } : null
  const ordered = content.sectionOrder === 'contact-first' ? [contact, archive] : [archive, contact]
  return [{ id: 'works', label: content.navWorksLabel || 'WORKS', href: '/' }, ...ordered.filter((s): s is NavSection => s !== null)]
}

