'use client';

// ═══════════════════════════════════════════════════════════════════════
// ViceHandover v6 — THE DRAG
// Single atmospheric drag interaction. No hybrid mechanics.
// Drag the substance from your hand to theirs. That's it.
// The resistance, speed, atmosphere, and feedback tell the story.
// ═══════════════════════════════════════════════════════════════════════

import { useState, useRef, useCallback, useEffect, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { playThud, playWetSmack } from '@/lib/sound-effects';
import { audioManager } from '@/app/_lib/audio-manager';

type Substance = 'cigarettes' | 'alcohol' | 'weed' | 'crystals';
type HandoverState = 'READY' | 'DRAGGING' | 'AFTERMATH' | 'RESOLVED';
type Territory = 'DESPERATE' | 'NEUTRAL' | 'POWER_PLAY';
type Outcome = 'SUCCESS' | 'REFUSED';

interface Props {
  substance: Substance;
  recipientName: string;
  onComplete: () => void;
  onCancel: () => void;
  visible: boolean;
  mode?: 'recruitment' | 'maintenance';
  preference?: number;       // -2 (hated) to +2 (craving)
  escalationLevel?: number;  // 0-10
}

// ── Substance configuration ──────────────────────────────────────────

const SUBSTANCE_META: Record<Substance, {
  color: string; glow: string; label: string;
  weight: number; // 0-1, heavier = atmosphere builds faster
}> = {
  cigarettes: { color: '#CCAA00', glow: 'rgba(204,170,0,0.3)', label: 'FAG', weight: 0.3 },
  alcohol:    { color: '#B87333', glow: 'rgba(184,115,51,0.3)', label: 'BOOZE', weight: 0.5 },
  weed:       { color: '#c8dc96', glow: 'rgba(200,220,150,0.3)', label: 'GREEN', weight: 0.6 },
  crystals:   { color: '#a4e2ff', glow: 'rgba(164,226,255,0.3)', label: 'GLASS', weight: 0.9 },
};

// ── Territory logic ──────────────────────────────────────────────────

function getTerritory(progress: number): Territory {
  if (progress >= 65) return 'DESPERATE';   // top — you went to them
  if (progress >= 35) return 'NEUTRAL';     // middle
  return 'POWER_PLAY';                      // bottom — they came to you
}

const TERRITORY_META: Record<Territory, { label: string; affinityBonus: number; prefix: string }> = {
  DESPERATE:  { label: 'DESPERATE OFFERING', affinityBonus: -15, prefix: 'You pushed it into their space.' },
  NEUTRAL:    { label: 'NEUTRAL GROUND',     affinityBonus: 5,   prefix: '' },
  POWER_PLAY: { label: 'POWER PLAY',         affinityBonus: 25,  prefix: 'They had to reach for it.' },
};

// ── Aftermath reaction text ──────────────────────────────────────────

const REACTIONS: Record<Substance, Record<string, string>> = {
  cigarettes: {
    craving:  'Gone before you blinked. Already lit.',
    wants:    'Tapped the pack. Chose one carefully.',
    neutral:  'Took it. Said nothing.',
    dislikes: 'Held it like it was someone else\'s problem.',
    hates:    'Barely touched it. Their fingers didn\'t close.',
  },
  alcohol: {
    craving:  'Cap off before it left your hand. Long pull.',
    wants:    'Took the neck. Didn\'t look at the label.',
    neutral:  'Held it. Weighed the decision.',
    dislikes: 'Took it the way you take medicine.',
    hates:    'Held it at arm\'s length.',
  },
  weed: {
    craving:  'Brought it to their nose first. Smiled.',
    wants:    'Pocketed it. For later, they said.',
    neutral:  'Turned it over in their fingers.',
    dislikes: 'Looked at you like you\'d handed them a dead thing.',
    hates:    'Took it. You could feel the contempt.',
  },
  crystals: {
    craving:  'Their pupils did the talking.',
    wants:    'Palmed it. Didn\'t look around first \u2014 that\'s trust.',
    neutral:  'Held it to what light there was.',
    dislikes: 'Took it at arm\'s length. You felt the distance.',
    hates:    'Stared at it. Then at you. Then pocketed it anyway.',
  },
};

function getReaction(substance: Substance, preference: number): string {
  const pool = REACTIONS[substance];
  if (preference >= 2) return pool.craving;
  if (preference >= 1) return pool.wants;
  if (preference <= -2) return pool.hates;
  if (preference <= -1) return pool.dislikes;
  return pool.neutral;
}

function getPrefLabel(pref: number): string {
  if (pref >= 2) return 'CRAVING';
  if (pref >= 1) return 'WANTS IT';
  if (pref <= -2) return 'HATES THIS';
  if (pref <= -1) return 'NOT INTO IT';
  return 'NEUTRAL';
}

// ── Whisper pools (surface during drag) ──────────────────────────────

const WHISPERS = [
  'They didn\'t ask for this.',
  'You\'re making a choice for them.',
  'Their need is your leverage.',
  'Every second you hold it, the weight grows.',
  'You can\'t take this back.',
  'Is your hand steady?',
  'They\'ll remember this.',
  'This is who you are now.',
];

// ── Web Audio atmosphere engine ──────────────────────────────────────

let _ctx: AudioContext | null = null;
let _droneNode: OscillatorNode | null = null;
let _droneGain: GainNode | null = null;
let _heartbeatTimer: ReturnType<typeof setInterval> | null = null;

function getCtx(): AudioContext | null {
  try {
    if (!_ctx) {
      const AC = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
      _ctx = new AC();
    }
    if (_ctx.state === 'suspended') _ctx.resume();
    return _ctx;
  } catch { return null; }
}

function startDrone() {
  const ctx = getCtx();
  if (!ctx || _droneNode) return;
  try {
    _droneNode = ctx.createOscillator();
    _droneGain = ctx.createGain();
    const filter = ctx.createBiquadFilter();
    _droneNode.type = 'sawtooth';
    _droneNode.frequency.setValueAtTime(42, ctx.currentTime);
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(80, ctx.currentTime);
    _droneGain.gain.setValueAtTime(0, ctx.currentTime);
    _droneNode.connect(filter);
    filter.connect(_droneGain);
    _droneGain.connect(ctx.destination);
    _droneNode.start();
  } catch { /* no-op */ }
}

function setDroneLevel(level: number) {
  if (_droneGain) {
    try { _droneGain.gain.setTargetAtTime(Math.min(level, 0.04), (_ctx?.currentTime ?? 0), 0.1); } catch { /* */ }
  }
}

function stopDrone() {
  try { _droneNode?.stop(); _droneNode?.disconnect(); } catch { /* */ }
  _droneNode = null;
  _droneGain = null;
}

function thump(freq: number, vol: number) {
  const ctx = getCtx();
  if (!ctx) return;
  try {
    const t = ctx.currentTime;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(freq, t);
    osc.frequency.exponentialRampToValueAtTime(10, t + 0.12);
    gain.gain.setValueAtTime(vol, t);
    gain.gain.exponentialRampToValueAtTime(0.001, t + 0.12);
    osc.connect(gain); gain.connect(ctx.destination);
    osc.start(t); osc.stop(t + 0.15);
  } catch { /* */ }
}

function startHeartbeat(bpm: number) {
  stopHeartbeat();
  const ms = (60 / bpm) * 1000;
  _heartbeatTimer = setInterval(() => {
    thump(55, 0.08);
    setTimeout(() => thump(45, 0.06), 140);
  }, ms);
}

function stopHeartbeat() {
  if (_heartbeatTimer) { clearInterval(_heartbeatTimer); _heartbeatTimer = null; }
}

function playRustle() {
  const ctx = getCtx();
  if (!ctx) return;
  try {
    const t = ctx.currentTime;
    const bufferSize = ctx.sampleRate * 0.08;
    const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) data[i] = (Math.random() * 2 - 1) * 0.15;
    const source = ctx.createBufferSource();
    source.buffer = buffer;
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.06, t);
    gain.gain.exponentialRampToValueAtTime(0.001, t + 0.08);
    const filter = ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.setValueAtTime(2000, t);
    source.connect(filter); filter.connect(gain); gain.connect(ctx.destination);
    source.start(t);
  } catch { /* */ }
}

function playOutcomeSFX(success: boolean) {
  const ctx = getCtx();
  if (!ctx) return;
  const t = ctx.currentTime;
  try {
    if (success) {
      const o = ctx.createOscillator(); const g = ctx.createGain();
      o.frequency.setValueAtTime(220, t); o.frequency.exponentialRampToValueAtTime(440, t + 0.25);
      g.gain.setValueAtTime(0.04, t); g.gain.exponentialRampToValueAtTime(0.001, t + 0.3);
      o.connect(g); g.connect(ctx.destination); o.start(); o.stop(t + 0.3);
    } else {
      const o = ctx.createOscillator(); const g = ctx.createGain();
      o.type = 'sawtooth';
      o.frequency.setValueAtTime(100, t); o.frequency.linearRampToValueAtTime(50, t + 0.35);
      g.gain.setValueAtTime(0.06, t); g.gain.exponentialRampToValueAtTime(0.001, t + 0.35);
      o.connect(g); g.connect(ctx.destination); o.start(); o.stop(t + 0.35);
    }
  } catch { /* */ }
}

function cleanupAudio() {
  stopHeartbeat();
  stopDrone();
}

