                <span className="flex items-center justify-center gap-2">
                  <Search size={14} />
                  SCAVENGE {selectedLoc.name}
                </span>
              </button>
            </motion.div>
          )}

          {/* ─── SEARCHING ─── */}
          {phase === 'searching' && (
            <motion.div key="searching" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="flex flex-col items-center gap-6 text-center py-6">
              <motion.div animate={{ opacity: [0.3, 1, 0.3] }} transition={{ duration: 1.5, repeat: Infinity }} style={{ color: ACCENT }}>
                <Search size={32} />
              </motion.div>
              <div className="font-typewriter text-sm leading-relaxed italic" style={{ color: '#c8dc96' }}>{flavour}</div>
              <div className="font-bmf-mono text-xs tracking-[0.3em] uppercase" style={{ color: FAINT }}>SCAVENGING...</div>
