          {/* ─── RESULTS ─── */}
          {phase === 'results' && (
            <motion.div key="results" initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} className="flex flex-col items-center gap-5">
              <div className="font-typewriter text-sm italic text-center leading-relaxed" style={{ color: '#c8dc96' }}>{flavour}</div>
              <div className="w-full p-4 rounded" style={panel({ borderColor: BORDER_STRONG })}>
