          )}

          {/* ─── ALREADY DONE ─── */}
          {phase === 'already_done' && (
            <motion.div key="already_done" initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} className="flex flex-col items-center gap-5 text-center py-6">
