// Escalation system — calculates how much "reality" bleeds through
// Based on exploitation level: how many NPCs recruited, substances administered, expeditions run

export interface EscalationState {
  level: number; // 0-10 scale
  phase: 'clean' | 'cracking' | 'sweating' | 'bleeding' | 'broken';
  flickerIntensity: number; // 0-1
  realityBleedChance: number; // 0-1 probability of reality portrait showing
  shrineSize: number; // 0-5 shrine growth stages  
  titleEscalation: string; // Player's delusional title
}

export function calculateEscalation(gameState: {
  npcs?: Array<{ recruited?: boolean; toleranceCigs?: number; toleranceAlc?: number; toleranceWeed?: number; toleranceCryst?: number }>;
  resources?: Array<{ type?: string; quantity?: number }>;
  expeditions?: Array<{ id?: string }>;
  heat?: number;
  day?: number;
}): EscalationState {
  const npcs = gameState?.npcs ?? [];
  const recruited = npcs?.filter?.((n) => n?.recruited)?.length ?? 0;
  const totalTolerance = npcs?.reduce?.((sum: number, n) => {
    return sum + (n?.toleranceCigs ?? 0) + (n?.toleranceAlc ?? 0) + (n?.toleranceWeed ?? 0) + (n?.toleranceCryst ?? 0);
  }, 0) ?? 0;
  const expeditionCount = gameState?.expeditions?.length ?? 0;
  const heat = gameState?.heat ?? 0;
  const day = gameState?.day ?? 1;

  // Calculate raw escalation score (0-100)
  const rawScore = Math.min(100,
    (recruited * 8) +
    (totalTolerance * 2) +
    (expeditionCount * 5) +
    (heat * 3) +
    (day * 1)
  );

  // Normalize to 0-10
  const level = Math.min(10, Math.floor(rawScore / 10));

  // Determine phase
  let phase: EscalationState['phase'] = 'clean';
  if (level >= 8) phase = 'broken';
  else if (level >= 6) phase = 'bleeding';
  else if (level >= 4) phase = 'sweating';
  else if (level >= 2) phase = 'cracking';

  // Flicker gets worse
  const flickerIntensity = Math.min(1, level / 10);

  // Reality bleed chance increases
  const realityBleedChance = Math.min(0.8, level * 0.08);

  // Shrine grows
  const shrineSize = Math.min(5, Math.floor(level / 2));

  // Delusional title escalates
  const titles = [
    'Shift Manager',
    'Operations Manager', 
    'Director of Operations',
    'Regional Director',
    'Vice President of Commerce',
    'Supreme Architect',
    'The Shepherd',
    'The Messiah of Commerce',
    'God-Emperor of the Court',
    'THE ETERNAL ONE',
    'HE WHO WAS ALWAYS HERE',
  ];
  const titleEscalation = titles[Math.min(level, titles.length - 1)] ?? 'Manager';

  return { level, phase, flickerIntensity, realityBleedChance, shrineSize, titleEscalation };
}

// Get CSS class names based on escalation
export function getEscalationClasses(escalation: EscalationState): string {
  const classes: string[] = [];
  if (escalation.level >= 1) classes.push('sweat-layer');
  if (escalation.level >= 3) classes.push('fluorescent-light');
  if (escalation.level >= 5) classes.push('sweat-heavy');
  if (escalation.level >= 7) classes.push('animate-reality-bleed');
  return classes.join(' ');
}

// Get dynamic opacity for reality portraits
export function getRealityBleedOpacity(escalation: EscalationState): number {
  if (escalation.level < 3) return 0;
  return Math.min(0.6, (escalation.level - 3) * 0.08);
}

