import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { isValidId } from '@/lib/api-guards';

/** Valid NPC keys for directives. */
const VALID_NPC_KEYS = ['dave', 'tamara', 'sid', 'mikey'] as const;
const VALID_ACTIONS = ['activate', 'complete', 'fail'] as const;

/**
 * POST /api/game/directive
 * Actions:
 *   - activate: Start a directive mission for an NPC
 *   - complete: Mark directive as done (pressure check passed)
 *   - fail: Mark directive as failed (pressure too high)
 */
export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const { sessionId, action, npcKey } = body;

    if (!isValidId(sessionId)) {
      return NextResponse.json({ error: 'Missing sessionId' }, { status: 400 });
    }
    if (!VALID_NPC_KEYS.includes(npcKey)) {
      return NextResponse.json({ error: 'Invalid npcKey' }, { status: 400 });
    }
    if (!VALID_ACTIONS.includes(action)) {
      return NextResponse.json({ error: 'Unknown action' }, { status: 400 });
    }

    const missionKey = `directive_${npcKey}`;

    if (action === 'activate') {
      // Upsert a DIRECTIVE mission for this NPC
      await prisma.mission.upsert({
        where: { sessionId_missionKey: { sessionId, missionKey } },
        create: {
          sessionId,
          missionKey,
          type: 'DIRECTIVE',
          directiveNpcKey: npcKey,
          tier: 5,
          status: 'ACTIVE',
          startedAt: new Date(),
        },
        update: {
          status: 'ACTIVE',
          startedAt: new Date(),
          completedAt: null,
        },
      });

      return NextResponse.json({ ok: true, status: 'ACTIVE' });
    }

    if (action === 'complete') {
      // Mark mission as COMPLETED
      await prisma.mission.update({
        where: { sessionId_missionKey: { sessionId, missionKey } },
        data: {
          status: 'COMPLETED',
          completedAt: new Date(),
        },
      });

      // Mark NPC directiveDone
      const npc = await prisma.nPC.findFirst({
        where: { sessionId, archetype: npcKey },
      });
      if (npc) {
        await prisma.nPC.update({
          where: { id: npc.id },
          data: { directiveDone: true },
        });
      }

      return NextResponse.json({ ok: true, status: 'COMPLETED' });
    }

    if (action === 'fail') {
      // Mark mission as FAILED (can retry)
      await prisma.mission.update({
        where: { sessionId_missionKey: { sessionId, missionKey } },
        data: {
          status: 'FAILED',
          completedAt: null,
        },
      });

      return NextResponse.json({ ok: true, status: 'FAILED' });
    }

    return NextResponse.json({ error: 'Unknown action' }, { status: 400 });
  } catch (err: unknown) {
    console.error('[directive] Error:', err);
    return NextResponse.json({ error: 'Directive failed' }, { status: 500 });
  }
}

