                        {section.title}
                      </h4>
                    </div>
                    <div className="space-y-2.5">
                      {section.content.map((para, i) => {
                        // Section headers (lines starting with block char)
                        const isHeader = para.startsWith('\u2592');
                        if (isHeader) {
                          return (
                            <div key={i} className="mt-4 mb-1">
                              <h5 className="font-terminal text-xs tracking-[0.15em]" style={{ color: section.color, opacity: 0.7 }}>
                                {para}
                              </h5>
