              <p className="font-typewriter text-[9px] text-[#3a3a30] text-center tracking-wider">
                FIELD MANUAL \u2014 BAF3K OPERATIONAL GUIDE v1.0.1 \u2014 CONTENTS SUBJECT TO REVISION
              </p>
            </div>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

