  { pos: 5, label: 'NEED CENTRE',      region: 'Hypothalamus',    x: 38, y: 38, w: 26, h: 26 },  // center = core
  { pos: 6, label: 'COMPLIANCE GATE',  region: 'Basal Ganglia',   x: 65, y: 38, w: 24, h: 22 },
  { pos: 7, label: 'MEMORY VAULT',     region: 'Hippocampus',     x: 10, y: 68, w: 26, h: 22 },
  { pos: 8, label: 'TRUST RECEPTOR',   region: 'Insula',          x: 70, y: 62, w: 22, h: 22 },
  { pos: 9, label: 'DENIAL BARRIER',   region: 'Cingulate',       x: 48, y: 8,  w: 24, h: 18 },
