export default function ParsingStage({ npcData, progress, onProgress, onAdvance }: Props) {
  const grid = npcData?.parsingGrid ?? [];
  const [revealed, setRevealed] = useState<Set<number>>(new Set());
  const [selectedNode, setSelectedNode] = useState<number | null>(null);
  const [flinchNode, setFlinchNode] = useState<number | null>(null);
  const [latestRevealed, setLatestRevealed] = useState<number | null>(null);

  const revealCount = revealed?.size ?? 0;
  const threshold = Math.ceil((grid?.length ?? 9) * 0.7);
  const canAdvance = revealCount >= threshold;

  const clickNode = useCallback((pos: number) => {
    if (revealed?.has?.(pos) || selectedNode !== null) return;
    audioManager.playSFX('nav');
    setSelectedNode(pos);

    const node = grid?.find?.((n: any) => n?.pos === pos);
    setTimeout(() => {
      if (node) {
        audioManager.playSFX('confirm');
        setLatestRevealed(pos);
      } else {
        audioManager.playSFX('error');
        // Flinch reaction — the subject felt the probe
        setFlinchNode(pos);
        setTimeout(() => setFlinchNode(null), 600);
      }
      setRevealed((prev: Set<number>) => new Set([...(Array.from(prev ?? []) ?? []), pos]));
      onProgress(revealCount + 1);
      setSelectedNode(null);
    }, 700);
  }, [revealed, grid, onProgress, revealCount, selectedNode]);

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="p-4 sm:p-5"
    >
      {/* Header */}
      <div className="flex items-center gap-2 mb-1">
        <Scan size={13} className="text-[#7ab8b8]/60" />
        <h3 className="font-terminal text-xs text-[#7ab8b8]/60 tracking-widest">PSYCHOLOGICAL DISSECTION</h3>
      </div>

      <p className="text-[10px] text-[#E8E8E8]/40 mb-4 font-typewriter">
        Map {npcData?.name ?? 'the subject'}&apos;s neural architecture. Probe regions to expose what drives them.
        Need {threshold} of {grid?.length ?? 9} sectors.
      </p>

      {/* Progress — biological fill */}
      <div className="mb-5">
        <div className="flex justify-between text-[8px] text-[#7ab8b8]/40 mb-1 font-terminal tracking-wider">
          <span>SECTORS MAPPED: {revealCount}/{grid?.length ?? 9}</span>
          <span>{canAdvance ? 'THRESHOLD MET \u2713' : `NEED ${Math.max(0, threshold - revealCount)} MORE`}</span>
        </div>
        <div className="h-2 bg-[#0a0a0a] relative overflow-hidden" style={{ border: '1px solid rgba(0,255,255,0.1)' }}>
          <motion.div
            className="absolute inset-y-0 left-0 transition-all duration-500"
            animate={{ width: `${((revealCount / (grid?.length ?? 9)) * 100)}%` }}
            style={{
              background: canAdvance
                ? 'linear-gradient(90deg, rgba(156,255,118,0.3), rgba(156,255,118,0.6))'
                : 'linear-gradient(90deg, rgba(0,255,255,0.2), rgba(0,255,255,0.5))',
            }}
          />
          {/* Threshold line */}
          <div
            className="absolute top-0 bottom-0 w-px"
            style={{ left: `${(threshold / (grid?.length ?? 9)) * 100}%`, background: '#FFFF0055' }}
          />
        </div>
      </div>

      {/* ── BRAIN CROSS-SECTION ── */}
      <div className="relative w-full mb-5" style={{ aspectRatio: '1 / 1', maxWidth: '380px', margin: '0 auto' }}>
        {/* Head silhouette SVG */}
        <svg viewBox="0 0 100 100" className="absolute inset-0 w-full h-full" style={{ opacity: 0.12 }}>
          <ellipse cx="50" cy="48" rx="38" ry="44" fill="none" stroke="#7ab8b8" strokeWidth="0.4" strokeDasharray="2 2" />
          {/* Brain lobes outline */}
          <path d="M 22 35 Q 30 15 50 12 Q 70 15 78 35 Q 82 50 75 65 Q 65 82 50 85 Q 35 82 25 65 Q 18 50 22 35 Z" fill="none" stroke="#7ab8b8" strokeWidth="0.3" opacity="0.5" />
          {/* Central fissure */}
          <line x1="50" y1="12" x2="50" y2="85" stroke="#7ab8b8" strokeWidth="0.15" opacity="0.3" />
          {/* Lateral fissure */}
          <path d="M 25 45 Q 40 42 55 50 Q 65 55 75 48" fill="none" stroke="#7ab8b8" strokeWidth="0.15" opacity="0.3" />
        </svg>

        {/* Flinch flash — subject felt the probe */}
        <AnimatePresence>
          {flinchNode !== null && (
            <motion.div
              key="flinch"
              initial={{ opacity: 0.7 }}
              animate={{ opacity: 0 }}
              exit={{ opacity: 0 }}
              transition={{ duration: 0.5 }}
              className="absolute inset-0 z-20 pointer-events-none"
              style={{ background: 'radial-gradient(circle, rgba(255,30,30,0.15) 0%, transparent 60%)' }}
            />
          )}
        </AnimatePresence>

        {/* Brain region nodes */}
        {BRAIN_REGIONS.map((region) => {
          const node = grid?.find?.((n: any) => n?.pos === region.pos);
          const isRevealed = revealed?.has?.(region.pos);
          const isSelected = selectedNode === region.pos;
          const isCore = region.pos === 5;
          const isFlinching = flinchNode === region.pos;
          const isLatest = latestRevealed === region.pos;

          return (
            <motion.button
              key={region.pos}
              onClick={() => clickNode(region.pos)}
              disabled={isRevealed || selectedNode !== null}
              className="absolute flex flex-col items-center justify-center text-center transition-all overflow-hidden"
              style={{
                left: `${region.x}%`,
                top: `${region.y}%`,
                width: `${region.w}%`,
                height: `${region.h}%`,
                border: `1px solid ${
                  isRevealed
                    ? (node ? (isCore ? 'rgba(156,255,118,0.35)' : 'rgba(0,255,255,0.2)') : 'rgba(255,30,30,0.15)')
                    : isSelected ? 'rgba(255,255,0,0.4)' : 'rgba(0,255,255,0.06)'
                }`,
                borderRadius: '8px',
                background: isRevealed
                  ? (node
                    ? (isCore ? 'rgba(156,255,118,0.06)' : 'rgba(0,255,255,0.04)')
                    : 'rgba(255,30,30,0.03)')
                  : isSelected ? 'rgba(255,255,0,0.03)' : 'rgba(0,0,0,0.2)',
                cursor: isRevealed || selectedNode !== null ? 'default' : 'pointer',
                zIndex: isSelected || isLatest ? 10 : 1,
              }}
              animate={{
                scale: isFlinching ? [1, 1.08, 0.95, 1] : isLatest ? [1, 1.05, 1] : 1,
                x: isFlinching ? [0, -3, 3, -1, 0] : 0,
              }}
              transition={{ duration: isFlinching ? 0.4 : 0.3 }}
              whileTap={!isRevealed && selectedNode === null ? { scale: 0.95 } : {}}
            >
              {isRevealed && node ? (
                <motion.div
                  initial={{ opacity: 0, scale: 0.7, rotateX: 90 }}
                  animate={{ opacity: 1, scale: 1, rotateX: 0 }}
                  transition={{ duration: 0.5, ease: 'easeOut' }}
                  className="text-center px-1"
                >
                  <Unlock size={10} className={`mx-auto mb-0.5 ${isCore ? 'text-[#9cff76]' : 'text-[#7ab8b8]'}`} />
                  <p className={`text-[8px] sm:text-[9px] font-terminal ${isCore ? 'text-[#9cff76]' : 'text-[#7ab8b8]'}`}>{node?.label ?? region.label}</p>
                  <p className="text-[7px] text-[#E8E8E8]/30 mt-0.5 leading-tight line-clamp-2">{(node?.desc ?? '').slice(0, 40)}</p>
                </motion.div>
              ) : isRevealed ? (
                <motion.div
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  className="text-center"
                >
                  <span className="text-[8px] text-red-400/40 italic font-terminal">EMPTY</span>
                  <p className="text-[7px] text-[#4a4a3a]">{region.label}</p>
                </motion.div>
              ) : (
                <>
                  <Lock size={10} className="text-[#7ab8b8]/12 mb-0.5" />
                  <span className="text-[7px] sm:text-[8px] text-[#7ab8b8]/15 font-terminal leading-tight">{region.label}</span>
                  {isSelected && (
                    <motion.div
                      animate={{ opacity: [0.2, 0.8, 0.2] }}
                      transition={{ duration: 0.4, repeat: Infinity }}
                      className="absolute inset-0 rounded-lg"
                      style={{ border: '1px solid rgba(255,255,0,0.4)' }}
                    />
                  )}
                </>  
              )}
            </motion.button>
          );
        })}
      </div>

      {/* Scanning indicator */}
      <AnimatePresence>
        {selectedNode && !revealed?.has?.(selectedNode) && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            className="p-2.5 mb-4 text-center" style={{
              border: '1px solid rgba(255,255,0,0.12)',
              background: 'rgba(255,255,0,0.02)',
            }}
          >
            <span className="text-[10px] text-[#FFFF00]/70 animate-pulse font-terminal tracking-wider">
              PROBING {BRAIN_REGIONS.find((r) => r.pos === selectedNode)?.label ?? `SECTOR ${selectedNode}`}...
            </span>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Flinch feedback */}
      <AnimatePresence>
        {flinchNode !== null && (
          <motion.div
            initial={{ opacity: 0, y: -5 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: 5 }}
            className="p-2 mb-3 text-center"
            style={{ border: '1px solid rgba(255,30,30,0.15)', background: 'rgba(255,30,30,0.03)' }}
          >
            <span className="text-[10px] text-red-400/60 font-terminal">SUBJECT FLINCHED. EMPTY SECTOR. THEY FELT THAT.</span>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Advance */}
      {canAdvance && (
        <motion.button
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          onClick={() => { audioManager.playSFX('nav'); onAdvance(); }}
          className="w-full font-terminal py-3 text-sm tracking-wider transition-all cursor-pointer active:scale-[0.98]"
          style={{
            border: '1px solid #7ab8b8',
            color: '#7ab8b8',
            background: 'rgba(0,255,255,0.04)',
          }}
        >
          PROCEED TO THE PITCH <ChevronRight size={13} className="inline ml-1" />
        </motion.button>
      )}
    </motion.div>
  );
}

