export const dynamic = 'force-dynamic';

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { MISSION_DEFINITIONS } from '@/lib/game-data';
import { isValidId } from '@/lib/api-guards';

// POST: Mission actions (start, advance, complete, fail)
export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const { sessionId, missionKey, action } = body ?? {};
    if (!isValidId(sessionId) || !missionKey || !action) {
      return NextResponse.json({ error: 'Missing sessionId, missionKey, or action' }, { status: 400 });
    }

    // Validate missionKey against known definitions (prevents arbitrary DB writes)
    const def = MISSION_DEFINITIONS[missionKey];
    if (!def) {
      return NextResponse.json({ error: 'Unknown mission' }, { status: 400 });
    }

    const session = await prisma.gameSession.findUnique({
      where: { id: sessionId },
      include: { resources: true, npcs: true, missions: true },
    });
    if (!session) {
      return NextResponse.json({ error: 'Session not found' }, { status: 404 });
    }

    const mission = session.missions.find((m: any) => m.missionKey === missionKey);

    switch (action) {
      case 'start': {
        // Check if mission exists, create if not (for older sessions)
        if (!mission) {
          // Create the mission record for legacy sessions
          const created = await prisma.mission.create({
            data: {
              sessionId,
              missionKey,
              type: def.type,
              tier: def.tier,
              status: def.initialStatus,
            },
          });
          if (created.status !== 'AVAILABLE') {
            return NextResponse.json({ error: 'Mission is locked' }, { status: 400 });
          }
        } else if (mission.status !== 'AVAILABLE') {
          return NextResponse.json({ error: `Mission status is ${mission.status}, cannot start` }, { status: 400 });
        }

        // Check crew requirement
        const recruitedCount = session.npcs.filter((n: any) => n.recruited).length;
        if (recruitedCount < def.crewRequired) {
          return NextResponse.json({
            error: `Need ${def.crewRequired} recruited crew members. You have ${recruitedCount}.`,
          }, { status: 400 });
        }

        // Check resource costs
        const costEntries = Object.entries(def.cost) as [string, number][];
        for (const [resType, amount] of costEntries) {
          const res = session.resources.find((r: any) => r.type === resType);
          if (!res || res.quantity < amount) {
            return NextResponse.json({
              error: `Insufficient ${resType}: need ${amount}, have ${res?.quantity ?? 0}`,
            }, { status: 400 });
          }
        }

        // Deduct resources
        for (const [resType, amount] of costEntries) {
          await prisma.resource.updateMany({
            where: { sessionId, type: resType },
            data: { quantity: { decrement: amount } },
          });
        }

        // Start the mission
        const missionId = mission?.id;
        if (missionId) {
          await prisma.mission.update({
            where: { id: missionId },
            data: { status: 'ACTIVE', narrativePhase: 1, startedAt: new Date() },
          });
        } else {
          await prisma.mission.updateMany({
            where: { sessionId, missionKey },
            data: { status: 'ACTIVE', narrativePhase: 1, startedAt: new Date() },
          });
        }

        break;
      }

      case 'advance': {
        if (!mission || mission.status !== 'ACTIVE') {
          return NextResponse.json({ error: 'Mission is not active' }, { status: 400 });
        }
        const nextPhase = mission.narrativePhase + 1;
        if (nextPhase > def.narrativePhases) {
          return NextResponse.json({ error: 'Already at final phase, use complete action' }, { status: 400 });
        }
        await prisma.mission.update({
          where: { id: mission.id },
          data: { narrativePhase: nextPhase },
        });
        break;
      }

      case 'complete': {
        if (!mission || mission.status !== 'ACTIVE') {
          return NextResponse.json({ error: 'Mission is not active' }, { status: 400 });
        }

        // Mark completed
        await prisma.mission.update({
          where: { id: mission.id },
          data: {
            status: 'COMPLETED',
            completedAt: new Date(),
            rewardsClaimed: true,
            narrativePhase: def.narrativePhases,
          },
        });

        // Apply rewards
        const rewards = def.rewards;

        // Stat boost
        if (rewards.statBoost) {
          const updateData: Record<string, any> = {};
          updateData[rewards.statBoost.stat] = {
            increment: rewards.statBoost.amount,
          };
          await prisma.gameSession.update({
            where: { id: sessionId },
            data: updateData,
          });
        }

        // Heat reduction
        if (rewards.heatReduction) {
          await prisma.gameSession.update({
            where: { id: sessionId },
            data: { heat: { decrement: rewards.heatReduction } },
          });
        }

        // Unlock dependent missions
        if (rewards.unlocks && rewards.unlocks.length > 0) {
          for (const unlockKey of rewards.unlocks) {
            // Try to update existing locked mission
            const updated = await prisma.mission.updateMany({
              where: { sessionId, missionKey: unlockKey, status: 'LOCKED' },
              data: { status: 'AVAILABLE' },
            });
            // If no record exists yet, create it as AVAILABLE
            if (updated.count === 0) {
              const unlockDef = MISSION_DEFINITIONS[unlockKey];
              if (unlockDef) {
                await prisma.mission.upsert({
                  where: { sessionId_missionKey: { sessionId, missionKey: unlockKey } },
                  create: {
                    sessionId,
                    missionKey: unlockKey,
                    type: unlockDef.type,
                    tier: unlockDef.tier,
                    status: 'AVAILABLE',
                  },
                  update: { status: 'AVAILABLE' },
                });
              }
            }
          }
        }

        break;
      }

      case 'fail': {
        if (!mission || mission.status !== 'ACTIVE') {
          return NextResponse.json({ error: 'Mission is not active' }, { status: 400 });
        }
        // For expeditions, reset to AVAILABLE. For main missions, mark FAILED.
        const newStatus = def.type === 'EXPEDITION' ? 'AVAILABLE' : 'FAILED';
        await prisma.mission.update({
          where: { id: mission.id },
          data: {
            status: newStatus,
            narrativePhase: 0,
            startedAt: null,
          },
        });
        break;
      }

      default:
        return NextResponse.json({ error: `Unknown action: ${action}` }, { status: 400 });
    }

    // Return updated session
    const updated = await prisma.gameSession.findUnique({
      where: { id: sessionId },
      include: { npcs: true, resources: true, expeditions: true, missions: true },
    });
    return NextResponse.json(updated);
  } catch (err: unknown) {
    console.error('Mission action error:', err);
    return NextResponse.json({ error: 'Mission action failed' }, { status: 500 });
  }
}

'use client'

import { useCallback, useEffect, useMemo, useState } from 'react'
