import {
  DEFAULT_PREFS, HANDLE_KEY, formatDuration, readPrefs, readStash, readTelemetry, resetTelemetry,
  recordLaunch, unitKey, writePrefs, writeStash, type HapticLevel, type Prefs, type Telemetry,
} from '@/lib/operator'
import { SealDial } from './seal-dial'

type ProfileUser = { name: string | null; email: string; role: string; member: boolean; memberSince: string | null }
type Props = { user: ProfileUser | null; games: PublicGame[] }

const label = 'block font-oswald text-[11px] uppercase tracking-[0.3em] mb-2'
const kicker = 'font-oswald text-[11px] uppercase tracking-[0.35em]'
const slab = { backgroundColor: 'var(--col-gunmetal)', border: '1px solid var(--col-steel)', boxShadow: '0 24px 50px rgb(var(--bv-shadow-rgb) / 0.6)' }
const goldBtn = 'press-fx w-full inline-flex items-center justify-center gap-3 font-oswald uppercase tracking-[0.25em] text-base px-6 min-h-[56px] hover:bg-[var(--col-yellow-hot)] disabled:opacity-60'
const goldStyle = { backgroundColor: 'var(--col-yellow)', color: 'var(--col-black)' }
const ghostBtn = 'press-fx font-oswald text-xs uppercase tracking-[0.25em] px-4 min-h-[44px] inline-flex items-center justify-center'
const ghostStyle = { border: '1px solid var(--col-steel)', color: 'var(--col-bone)' }

function AuthForm() {
  const [mode, setMode] = useState<'create' | 'signin'>('create')
  const [name, setName] = useState('')
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const submit = async (e: React.FormEvent) => {
    e.preventDefault()
    haptic('press')
    setBusy(true)
    setError(null)
    try {
      if (mode === 'create') {
        const res = await fetch('/api/signup', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ name: name.trim() || null, email, password }),
        })
        if (!res.ok) {
          const d = await res.json().catch(() => ({}))
          throw new Error(res.status === 409 ? 'PROFILE EXISTS — SIGN IN INSTEAD' : String(d?.error || 'COULD NOT CREATE PROFILE').toUpperCase())
        }
        if (name.trim()) try { localStorage.setItem(HANDLE_KEY, name.trim().toUpperCase()) } catch {}
      }
      const r = await signIn('credentials', { email, password, redirect: false })
      if (r?.error) throw new Error('WRONG EMAIL OR PASSWORD')
      haptic('complete')
      window.location.assign('/profile')
    } catch (err) {
      haptic('error')
      setError(err instanceof Error ? err.message : 'SOMETHING JAMMED')
      setBusy(false)
    }
  }

  return (
    <form onSubmit={submit} className="relative p-6 md:p-8" style={slab}>
      <div className="grid grid-cols-2 mb-7" role="tablist" aria-label="Profile access">
        {(['create', 'signin'] as const).map((m) => (
          <button
            key={m}
            type="button"
            role="tab"
            aria-selected={mode === m}
            onClick={() => { haptic('toggle'); setMode(m); setError(null) }}
            className="font-oswald text-xs uppercase tracking-[0.25em] min-h-[44px]"
            style={{
              color: mode === m ? 'var(--col-ivory)' : 'var(--col-bone)',
              opacity: mode === m ? 1 : 0.7,
              borderBottom: mode === m ? '2px solid var(--col-yellow)' : '1px solid var(--col-steel)',
            }}
          >
            {m === 'create' ? 'CREATE PROFILE' : 'SIGN IN'}
          </button>
        ))}
      </div>
      {mode === 'create' && (
        <>
          <label className={label} style={{ color: 'var(--col-bone)' }} htmlFor="p-name">Call sign (optional)</label>
          <input id="p-name" value={name} onChange={(e) => setName(e.target.value)} autoComplete="nickname" maxLength={40} className="admin-input mb-5" />
        </>
      )}
      <label className={label} style={{ color: 'var(--col-bone)' }} htmlFor="p-email">Email</label>
      <input id="p-email" type="email" required value={email} onChange={(e) => setEmail(e.target.value)} autoComplete="email" className="admin-input mb-5" />
      <label className={label} style={{ color: 'var(--col-bone)' }} htmlFor="p-pass">Password{mode === 'create' ? ' (6+ characters)' : ''}</label>
      <input id="p-pass" type="password" required minLength={mode === 'create' ? 6 : undefined} value={password} onChange={(e) => setPassword(e.target.value)} autoComplete={mode === 'create' ? 'new-password' : 'current-password'} className="admin-input mb-6" />
      {error ? <p role="alert" className="font-ibm text-xs uppercase mb-4" style={{ color: 'var(--col-yellow-hot)' }}>{error}</p> : null}
      <button type="submit" disabled={busy} className={goldBtn} style={goldStyle}>
        {busy ? 'PATCHING IN…' : mode === 'create' ? 'CREATE PROFILE' : 'SIGN IN'}
      </button>
      <p className="font-ibm text-[10px] uppercase mt-4 leading-relaxed" style={{ color: 'var(--col-bone)', opacity: 0.6 }}>
        Free. Your profile holds the turned seal — sign in on any device and everything stays open.
      </p>
    </form>
  )
}

function Toggle({ on, onChange, children }: { on: boolean; onChange: (v: boolean) => void; children: React.ReactNode }) {
  return (
    <button
      type="button"
      role="switch"
      aria-checked={on}
      onClick={() => { haptic('toggle'); onChange(!on) }}
      className="press-fx w-full flex items-center justify-between gap-4 px-4 min-h-[48px] font-oswald text-xs uppercase tracking-[0.22em] text-left"
      style={{ border: '1px solid var(--col-steel)', color: 'var(--col-bone)', backgroundColor: on ? 'rgb(var(--bv-primary-rgb) / 0.08)' : 'transparent' }}
    >
      <span>{children}</span>
      <span className="font-ibm text-[10px] tracking-[0.2em] px-2 py-1" style={{ border: `1px solid ${on ? 'var(--col-yellow)' : 'var(--col-steel)'}`, color: on ? 'var(--col-yellow)' : 'var(--col-bone)' }}>
        {on ? 'ON' : 'OFF'}
      </span>
    </button>
  )
}

function LaunchLink({ game, children, className, style }: { game: PublicGame; children: React.ReactNode; className: string; style?: React.CSSProperties }) {
  const live = game.status === 'active' && game.launchLink && game.launchLink !== '#' && !game.locked
  if (!live) return <span className={className} style={{ ...style, opacity: 0.55 }}>{game.locked ? 'SEALED' : 'STANDBY'}</span>
  const newTab = game.linkTarget === 'new_tab'
  return (
    <a href={game.launchLink} target={newTab ? '_blank' : undefined} rel={newTab ? 'noopener noreferrer' : undefined} onClick={() => { haptic('complete'); recordLaunch(game.title) }} className={className} style={style}>
      {children}
    </a>
  )
}

export function ProfilePanel({ user, games }: Props) {
  const router = useRouter()
  const [handle, setHandle] = useState('')
  const [stash, setStash] = useState<string[]>([])
  const [tele, setTele] = useState<Telemetry | null>(null)
  const [prefs, setPrefs] = useState<Prefs>(DEFAULT_PREFS)
  const [unsealed, setUnsealed] = useState(Boolean(user?.member || user?.role === 'admin'))

  useEffect(() => {
    let h = ''
    try { h = localStorage.getItem(HANDLE_KEY) || '' } catch {}
    setHandle(h || (user?.name || '').toUpperCase())
    setStash(readStash())
    setTele(readTelemetry())
    setPrefs(readPrefs())
    const t = window.setInterval(() => setTele(readTelemetry()), 5000)
    return () => window.clearInterval(t)
  }, [user?.name])

  const saveHandle = (v: string) => {
    const clean = v.toUpperCase().replace(/[^A-Z0-9 ._\-:]/g, '').slice(0, 24)
    setHandle(clean)
    try { localStorage.setItem(HANDLE_KEY, clean) } catch {}
  }
  const pin = (slug: string) => {
    haptic('toggle')
    const next = stash.includes(slug) ? stash.filter((s) => s !== slug) : [...stash, slug]
    setStash(next)
    writeStash(next)
  }
  const setPref = <K extends keyof Prefs>(k: K, v: Prefs[K]) => {
    const next = { ...prefs, [k]: v }
    setPrefs(next)
    writePrefs(next)
  }
  const onUnsealed = useCallback(() => { setUnsealed(true); router.refresh() }, [router])

  const pinned = useMemo(() => stash.map((s) => games.find((g) => g.slug === s)).filter(Boolean) as PublicGame[], [stash, games])
  const topUnit = useMemo(() => {
    if (!tele) return null
    const best = Object.entries(tele.plays).sort((a, b) => b[1] - a[1])[0]
    return best ? games.find((g) => unitKey(g.title) === best[0])?.title || best[0] : null
  }, [tele, games])
  const lockedCount = games.filter((g) => g.locked).length
  const isAdmin = user?.role === 'admin'
  const status = !user ? 'UNREGISTERED' : isAdmin ? 'OWNER // ALL ACCESS' : unsealed ? 'UNSEALED // FULL ACCESS' : `SEALED // ${lockedCount} UNITS LOCKED`

  return (
    <section className="bv-field relative min-h-[100svh] overflow-hidden" style={{ paddingTop: 'calc(56px + env(safe-area-inset-top))', backgroundColor: 'var(--col-black)' }}>
      <div className="relative z-10 max-w-[1180px] mx-auto w-full px-4 md:px-8 py-10 md:py-16 safe-bottom">
        <div className="grid md:grid-cols-12 gap-10 md:gap-14 items-start">
          {/* Identity */}
          <div className="md:col-span-7 min-w-0">
            <p className={kicker} style={{ color: 'var(--col-yellow)' }}>OPERATOR TERMINAL</p>
            <h1 className="font-anton uppercase tracking-tight break-words mt-4" style={{ color: 'var(--col-ivory)', lineHeight: 0.92, fontSize: 'clamp(48px, 8vw, 112px)' }}>
              {user ? handle || 'OPERATOR' : 'JACK IN'}
            </h1>
            <div className="w-24 gold-rule mt-5" aria-hidden="true" />

            {user ? (
              <div className="relative mt-8 p-5 md:p-6 frame-corners" style={slab}>
                <div className="flex flex-wrap items-center gap-3">
                  <span className="font-ibm text-[10px] uppercase tracking-[0.2em] px-2 py-1" style={{ border: `1px solid ${unsealed ? 'var(--col-yellow)' : 'var(--col-steel)'}`, color: unsealed ? 'var(--col-yellow)' : 'var(--col-bone)' }}>
                    ◈ {status}
                  </span>
                  {prefs.flair ? (
                    <span className="op-flair font-oswald text-[10px] uppercase tracking-[0.25em] px-2 py-1">BASELINE VELOCITY — DAY ZERO OPERATOR</span>
                  ) : null}
                </div>
                <label className={`${label} mt-6`} style={{ color: 'var(--col-bone)' }} htmlFor="op-handle">Operator handle // call sign</label>
                <input id="op-handle" value={handle} onChange={(e) => saveHandle(e.target.value)} maxLength={24} placeholder="SET A CALL SIGN" className="admin-input font-ibm uppercase" />
                <p className="font-ibm text-[10px] uppercase mt-2" style={{ color: 'var(--col-bone)', opacity: 0.6 }}>Stored on this device. {user.email}</p>
              </div>
            ) : (
              <p className="font-ibm text-sm md:text-base mt-6 max-w-[480px] leading-relaxed" style={{ color: 'var(--col-bone)' }}>
                Make a free profile. Then turn the seal upside down — every locked game and app opens for your profile.
              </p>
            )}

            <div className="mt-6 flex flex-wrap gap-3">
              <Link href="/games" onClick={() => haptic('press')} className={ghostBtn} style={ghostStyle}>← BACK TO THE GAMES</Link>
              {user && (
                <button type="button" onClick={() => { haptic('press'); signOut({ redirectTo: '/profile' }) }} className={ghostBtn} style={ghostStyle}>SIGN OUT</button>
              )}
            </div>

            {!user ? <div className="mt-10 max-w-[520px]"><AuthForm /></div> : null}
          </div>

          {/* The seal */}
          <div className="md:col-span-5">
            <div className="relative p-6 md:p-8 frame-corners" style={{ ...slab, borderTop: `2px solid ${unsealed ? 'var(--col-yellow)' : 'var(--col-steel)'}` }}>
              <p className={kicker} style={{ color: 'var(--col-bone)' }}>THE SEAL</p>
              <div className="mt-6">
                <SealDial signedIn={Boolean(user)} unsealed={unsealed} onUnsealed={onUnsealed} />
              </div>
              {unsealed && user ? (
                <Link href="/games" onClick={() => haptic('complete')} className={`${goldBtn} mt-8`} style={goldStyle}>PLAY EVERYTHING →</Link>
              ) : null}
            </div>
          </div>
        </div>

        {user ? (
          <div className="grid md:grid-cols-12 gap-10 md:gap-14 mt-14 md:mt-20">
            {/* Stash + roster */}
            <div className="md:col-span-7 min-w-0">
              <p className={kicker} style={{ color: 'var(--col-yellow)' }}>THE STASH</p>
              {pinned.length ? (
                <div className="grid sm:grid-cols-2 gap-3 mt-5">
                  {pinned.map((g) => (
                    <LaunchLink key={g.id} game={g} className="press-fx bv-card flex items-center justify-between gap-3 px-4 min-h-[64px] font-anton uppercase text-xl tracking-tight" style={{ color: 'var(--col-ivory)' }}>
                      <span className="truncate">{g.title}</span>
                      <span className="font-oswald text-[10px] tracking-[0.25em] shrink-0" style={{ color: 'var(--col-yellow)' }}>{g.kind === 'app' ? 'VISIT' : 'PLAY'} →</span>
                    </LaunchLink>
                  ))}
                </div>
              ) : (
                <p className="font-ibm text-xs uppercase mt-4" style={{ color: 'var(--col-bone)', opacity: 0.7 }}>Nothing pinned. Pin units below for one-click launch.</p>
              )}

              <p className={`${kicker} mt-12`} style={{ color: 'var(--col-bone)' }}>ROSTER</p>
              <ul className="mt-4" style={{ borderTop: '1px solid var(--col-steel)' }}>
                {games.map((g) => {
                  const on = stash.includes(g.slug)
                  const plays = tele?.plays[unitKey(g.title)] || 0
                  return (
                    <li key={g.id} className="flex items-center gap-3 py-3" style={{ borderBottom: '1px solid var(--col-steel)' }}>
                      <button type="button" onClick={() => pin(g.slug)} aria-pressed={on} aria-label={on ? `Unpin ${g.title}` : `Pin ${g.title} to the stash`} className="press-fx shrink-0 w-11 h-11 inline-flex items-center justify-center font-ibm text-sm" style={{ border: `1px solid ${on ? 'var(--col-yellow)' : 'var(--col-steel)'}`, color: on ? 'var(--col-yellow)' : 'var(--col-bone)' }}>
                        {on ? '◆' : '◇'}
                      </button>
                      <span className="flex-1 min-w-0">
                        <span className="block font-oswald uppercase tracking-[0.12em] text-sm truncate" style={{ color: 'var(--col-ivory)' }}>{g.title}</span>
                        <span className="block font-ibm text-[10px] uppercase" style={{ color: 'var(--col-bone)', opacity: 0.7 }}>{plays} LAUNCH{plays === 1 ? '' : 'ES'}</span>
                      </span>
                      <LaunchLink game={g} className="press-fx shrink-0 font-oswald text-[11px] uppercase tracking-[0.22em] px-3 min-h-[44px] inline-flex items-center" style={ghostStyle}>
                        {g.kind === 'app' ? 'VISIT' : 'PLAY'}
                      </LaunchLink>
                    </li>
                  )
                })}
              </ul>
            </div>

            {/* Telemetry + prefs */}
            <div className="md:col-span-5 space-y-10">
              <div>
                <p className={kicker} style={{ color: 'var(--col-yellow)' }}>SESSION TELEMETRY</p>
                <dl className="grid grid-cols-2 gap-px mt-5" style={{ backgroundColor: 'var(--col-steel)' }}>
                  {[
                    ['JACK-INS', tele ? String(tele.jackIns).padStart(3, '0') : '---'],
                    ['TIME IN MACHINE', tele ? formatDuration(tele.seconds) : '--:--:--'],
                    ['MOST FIRED', topUnit || '—'],
                    ['UNITS TOUCHED', tele ? String(Object.keys(tele.plays).length) : '-'],
                  ].map(([k, v]) => (
                    <div key={k} className="p-4" style={{ backgroundColor: 'var(--col-gunmetal)' }}>
                      <dt className="font-oswald text-[10px] uppercase tracking-[0.25em]" style={{ color: 'var(--col-bone)', opacity: 0.75 }}>{k}</dt>
                      <dd className="font-anton uppercase text-2xl mt-2 truncate" style={{ color: 'var(--col-ivory)' }}>{v}</dd>
                    </div>
                  ))}
                </dl>
                <button type="button" onClick={() => { haptic('error'); resetTelemetry(); setTele(readTelemetry()) }} className={`${ghostBtn} mt-3`} style={ghostStyle}>WIPE TELEMETRY</button>
                <p className="font-ibm text-[10px] uppercase mt-2" style={{ color: 'var(--col-bone)', opacity: 0.6 }}>Counted on this device only.</p>
              </div>

              <div>
                <p className={kicker} style={{ color: 'var(--col-yellow)' }}>TERMINAL PREFERENCES</p>
                <p className={`${label} mt-5`} style={{ color: 'var(--col-bone)' }}>Haptic intensity</p>
                <div className="grid grid-cols-4 gap-px" role="radiogroup" aria-label="Haptic intensity" style={{ backgroundColor: 'var(--col-steel)' }}>
                  {(['off', 'low', 'normal', 'high'] as HapticLevel[]).map((l) => (
                    <button key={l} type="button" role="radio" aria-checked={prefs.haptics === l} onClick={() => { setPref('haptics', l); haptic('toggle') }} className="min-h-[44px] font-oswald text-[11px] uppercase tracking-[0.2em]" style={{ backgroundColor: prefs.haptics === l ? 'var(--col-yellow)' : 'var(--col-gunmetal)', color: prefs.haptics === l ? 'var(--col-black)' : 'var(--col-bone)' }}>
                      {l}
                    </button>
                  ))}
                </div>
                <div className="space-y-2 mt-4">
                  <Toggle on={prefs.scanlines} onChange={(v) => setPref('scanlines', v)}>Gold scanlines &amp; grain</Toggle>
                  <Toggle on={prefs.hauntSfxMute} onChange={(v) => setPref('hauntSfxMute', v)}>Mute effect sounds</Toggle>
                  <Toggle on={prefs.reduceMotion} onChange={(v) => setPref('reduceMotion', v)}>Reduced motion</Toggle>
                  <Toggle on={prefs.flair} onChange={(v) => setPref('flair', v)}>Day Zero Operator badge</Toggle>
                </div>
                <p className="font-ibm text-[10px] uppercase mt-3 leading-relaxed" style={{ color: 'var(--col-bone)', opacity: 0.6 }}>
                  Effect sounds only. The soundtrack keeps running.
                </p>
              </div>
            </div>
          </div>
        ) : null}
      </div>
    </section>
  )
}

import Image from 'next/image'
import type { CSSProperties } from 'react'
import { HERO_HEIGHTS, type HeroConfig } from '@/lib/hero-config'
import { AdminGate } from './admin-gate'
import { HeroCta } from './hero-cta'
import { HeroGate } from './hero-gate'

export const BANNER = { src: '/assets/gf-banner-cold.jpg', w: 2880, h: 1621 }

const ALIGN = {
  left: 'items-start text-left',
  center: 'items-center text-center',
  right: 'items-end text-right',
} as const

/**
 * Reusable page hero. Every default colour is a banner token; per-page overrides come
 * from the admin (hero_<page>_* keys). `preview` disables the control-room trigger.
 */
export function PageHero({ hero, preview = false, gate = false }: { hero: HeroConfig; preview?: boolean; /** Stage 1 cog gate (home hero only) */ gate?: boolean }) {
  const vars = {
    '--hero-title': hero.titleColor || 'var(--bv-text-strong)',
    '--hero-text': hero.textColor || 'var(--bv-text)',
    '--hero-accent': hero.accentColor || 'var(--bv-accent)',
  } as CSSProperties
  const minHeight = HERO_HEIGHTS[hero.height]
  const trigger = hero.adminTrigger && !preview
  const anim = hero.animate ? 'bv-hero-anim' : ''
  const hasText = !!(hero.title || hero.subtitle || hero.cta)

  if (hero.bg === 'banner') {
    return (
      <>
        <section
          data-hero={hero.page}
          className={`relative w-full flex flex-col justify-center ${anim}`}
          style={{ ...vars, minHeight, background: 'var(--bv-gradient-banner)' }}
        >
          {/* Full banner: entire artwork visible at its natural ratio, nothing laid over it */}
          {gate && !preview ? (
            <div className="relative w-full bv-hero-art">
              <HeroGate
                src={BANNER.src}
                w={BANNER.w}
                h={BANNER.h}
                alt="Grey.Filter — The New Baseline banner"
                overlay={trigger ? <AdminGate variant="hotspot" /> : undefined}
              />
            </div>
          ) : (
          <div className="relative w-full bv-hero-art">
            <Image
              src={BANNER.src}
              alt="Grey.Filter — The New Baseline banner"
              width={BANNER.w}
              height={BANNER.h}
              priority
              sizes="100vw"
              className="block w-full h-auto"
            />
            {trigger && <AdminGate variant="hotspot" />}
          </div>
          )}
          {hasText && <HeroText hero={hero} trigger={false} className="py-8 md:py-10" />}
        </section>
        <div className="gold-hairline" aria-hidden="true" />
      </>
    )
  }

  const image = hero.bg === 'image' && hero.imageUrl
  return (
    <>
      <section
        data-hero={hero.page}
        className={`relative w-full overflow-hidden flex flex-col justify-center ${anim}`}
        style={{ ...vars, minHeight, background: hero.background }}
      >
        {image && (
          <>
            <div className="absolute inset-0 bv-hero-bg" aria-hidden="true">
              <Image src={image} alt="" fill sizes="100vw" className="object-cover" priority />
            </div>
            <div
              className="absolute inset-0"
              aria-hidden="true"
              style={{ background: 'linear-gradient(0deg, rgb(var(--bv-bg-rgb) / 0.85) 0%, rgb(var(--bv-bg-rgb) / 0.55) 55%, rgb(var(--bv-bg-rgb) / 0.4) 100%)' }}
            />
          </>
        )}
        <HeroText hero={hero} trigger={trigger} className="py-12 md:py-16" />
      </section>
      <div className="gold-hairline" aria-hidden="true" />
    </>
  )
}

function HeroText({ hero, trigger, className }: { hero: HeroConfig; trigger: boolean; className: string }) {
  const dot = trigger ? hero.title.indexOf('.') : -1
  return (
    <div className={`relative max-w-[1280px] mx-auto w-full px-4 md:px-8 flex flex-col gap-4 ${ALIGN[hero.align]} ${className}`}>
      {hero.title && (
        <h2
          className="bv-hero-rise font-anton uppercase leading-[0.92] break-words max-w-full"
          style={{ color: 'var(--hero-title)', fontSize: 'clamp(2.4rem, 7vw, 6rem)' }}
        >
          {dot >= 0 ? (
            <>
              {hero.title.slice(0, dot)}
              <AdminGate variant="dot" />
              {hero.title.slice(dot + 1)}
            </>
          ) : (
            hero.title
          )}
        </h2>
      )}
      {hero.subtitle && (
        <p className="bv-hero-rise font-ibm text-sm md:text-base max-w-[60ch] whitespace-pre-line" style={{ color: 'var(--hero-text)' }}>
          {hero.subtitle}
        </p>
      )}
      {hero.cta && (
        <div className="bv-hero-rise pt-2">
          <HeroCta {...hero.cta} />
        </div>
      )}
    </div>
  )
}

import * as React from 'react';
import { cva, type VariantProps } from 'class-variance-authority';

import { cn } from '@/lib/utils';

const badgeVariants = cva(
  'inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-semibold transition-colors focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2',
  {
    variants: {
      variant: {
        default:
          'border-transparent bg-primary text-primary-foreground hover:bg-primary/80',
        secondary:
          'border-transparent bg-secondary text-secondary-foreground hover:bg-secondary/80',
        destructive:
          'border-transparent bg-destructive text-destructive-foreground hover:bg-destructive/80',
        outline: 'text-foreground',
      },
    },
    defaultVariants: {
      variant: 'default',
    },
  }
);

export interface BadgeProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof badgeVariants> {}

function Badge({ className, variant, ...props }: BadgeProps) {
  return (
    <div className={cn(badgeVariants({ variant }), className)} {...props} />
  );
}

export { Badge, badgeVariants };

'use client';

import Image from 'next/image';
import { motion } from 'framer-motion';
import { PinIcon } from '../icons/resource-icons';

/**
 * PosterPinup — decorative cartoon propaganda poster pinned to a wall.
 * All 8 posters live at /public/images/poster-01.jpg through poster-08.jpg.
 * Pass `seed` (e.g. day number) for deterministic selection across renders,
 * or `index` (1-8) to force a specific poster.
 *
 * Styled as an aged, slightly-tilted, pinned flyer. Defaults to low opacity
 * and sepia wash so it reads as atmospheric wall art, not focal UI.
 */
export default function PosterPinup({
  seed,
  index,
  className = '',
  style = {},
  opacity = 0.48,
  rotate = -3,
  showPin = true,
  sepia = 0.35,
  widthClass = 'w-24 sm:w-32',
}: {
  seed?: number;
  index?: number;
  className?: string;
  style?: React.CSSProperties;
  opacity?: number;
  rotate?: number;
  showPin?: boolean;
  sepia?: number;
  widthClass?: string;
}) {
  // Pick poster index (1-8)
  let n: number;
  if (typeof index === 'number') {
    n = ((index - 1) % 8 + 8) % 8 + 1;
  } else {
    const s = typeof seed === 'number' ? Math.abs(seed) : 0;
    n = (s % 8) + 1;
  }
  const src = `/images/poster-0${n}.jpg`;

  return (
    <motion.div
      initial={{ opacity: 0, rotate: 0, y: -4 }}
      animate={{ opacity, rotate, y: 0 }}
      transition={{ duration: 0.8, ease: 'easeOut' }}
      className={`pointer-events-none select-none ${widthClass} ${className}`}
      style={style}
      aria-hidden="true"
    >
      <div
        className="relative aspect-[3/4] bg-[#1a1608]"
        style={{
          filter: `sepia(${sepia}) contrast(0.95) brightness(0.82)`,
          boxShadow: '0 4px 12px rgba(0,0,0,0.55), inset 0 0 24px rgba(0,0,0,0.3)',
        }}
      >
        <Image
          src={src}
          alt={`Propaganda poster ${n}`}
          fill
          className="object-cover"
          sizes="(max-width: 640px) 96px, 128px"
        />
        {/* Age/grime overlay */}
        <div
          className="absolute inset-0 mix-blend-multiply"
          style={{
            background:
              'radial-gradient(ellipse at 30% 20%, transparent 40%, rgba(20,15,5,0.4) 100%)',
          }}
        />
