// IMPORTANT: Do not remove this component.
// It handles a known Next.js dev server race condition where dynamic chunks
// imported by next/dynamic haven't been compiled yet and cause webpack to throw
// a ChunkLoadError

import { useEffect } from 'react'

export function ChunkLoadErrorHandler() {
  useEffect(() => {
    const handler = (event: ErrorEvent) => {
      if (
        event.error?.name === 'ChunkLoadError' ||
        event.error?.message?.includes('Loading chunk')
      ) {
        event.preventDefault()
        window.location.reload()
      }
    }
    window.addEventListener('error', handler)
    return () => window.removeEventListener('error', handler)
  }, [])

  return null
}

'use client';

// ═══════════════════════════════════════════════════════════
// FullscreenEnforcer — Requests exclusive fullscreen on first
// user interaction. Browsers require a user gesture to enter
// fullscreen, so we attach a one-shot listener to the first
// click/tap/keydown. Falls back gracefully if the API is
// unavailable (e.g. iframe embeds).
// ═══════════════════════════════════════════════════════════

import { useEffect } from 'react';

export default function FullscreenEnforcer() {
  useEffect(() => {
    // Skip if already fullscreen or API unavailable
    const el = document.documentElement;
    if (!el.requestFullscreen && !(el as any).webkitRequestFullscreen) return;

    function tryFullscreen() {
      try {
        if (document.fullscreenElement || (document as any).webkitFullscreenElement) return;
        if (el.requestFullscreen) {
          el.requestFullscreen({ navigationUI: 'hide' }).catch(() => {});
        } else if ((el as any).webkitRequestFullscreen) {
          (el as any).webkitRequestFullscreen();
        }
      } catch {}
      // One-shot — remove after first attempt
      cleanup();
    }

    function cleanup() {
      document.removeEventListener('click', tryFullscreen, true);
      document.removeEventListener('keydown', tryFullscreen, true);
      document.removeEventListener('touchstart', tryFullscreen, true);
    }

    document.addEventListener('click', tryFullscreen, true);
    document.addEventListener('keydown', tryFullscreen, true);
    document.addEventListener('touchstart', tryFullscreen, true);

    // Re-enter fullscreen if user exits (e.g. Esc) — listen for change
    function onFsChange() {
      if (!document.fullscreenElement && !(document as any).webkitFullscreenElement) {
        // Re-arm the one-shot listeners for next interaction
        document.addEventListener('click', tryFullscreen, true);
        document.addEventListener('keydown', tryFullscreen, true);
        document.addEventListener('touchstart', tryFullscreen, true);
      }
    }
    document.addEventListener('fullscreenchange', onFsChange);
    document.addEventListener('webkitfullscreenchange', onFsChange);

    return () => {
      cleanup();
      document.removeEventListener('fullscreenchange', onFsChange);
      document.removeEventListener('webkitfullscreenchange', onFsChange);
    };
  }, []);

  return null;
}

