import { useState, useCallback, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Target } from 'lucide-react';
import { playItsMedical } from '@/lib/sound-effects';
import { audioManager } from '@/app/_lib/audio-manager';

const VOICE_CLIP_PLAYERS: Record<string, () => void> = {
  'tamara-its-medical': () => { playItsMedical(); },
};

// Qualitative compliance labels — player never sees the raw number
function getComplianceRead(affinity: number): { text: string; color: string } {
  if (affinity >= 80) return { text: 'FULLY COMPLIANT', color: '#9cff76' };
  if (affinity >= 60) return { text: 'THEY\'RE YOURS', color: '#9cff76' };
  if (affinity >= 45) return { text: 'THEY NEED THIS', color: '#FFFF00' };
  if (affinity >= 30) return { text: 'THEY\'RE LISTENING', color: '#FFB000' };
  if (affinity >= 15) return { text: 'RESISTANT', color: '#b87a96' };
  return { text: 'HOSTILE', color: '#a8687e' };
}

// ── TYPEWRITER HOOK — letter-by-letter reveal with blinking cursor ──
function useTypewriter(text: string | null, speed: number = 28) {
  const [displayed, setDisplayed] = useState('');
  const [done, setDone] = useState(false);
  const indexRef = useRef(0);

  useEffect(() => {
    if (!text) {
      setDisplayed('');
      setDone(false);
      indexRef.current = 0;
      return;
    }
    setDisplayed('');
    setDone(false);
    indexRef.current = 0;

    const interval = setInterval(() => {
      indexRef.current++;
      if (indexRef.current >= text.length) {
        setDisplayed(text);
        setDone(true);
        clearInterval(interval);
      } else {
        setDisplayed(text.slice(0, indexRef.current));
      }
    }, speed);
    return () => clearInterval(interval);
  }, [text, speed]);

  return { displayed, done };
}

interface TransactionOption { id?: string; text: string; response: string; affinity?: number; affinityDelta?: number; voiceClip?: string; correct?: boolean }
interface TransactionRound { round: number; prompt: string; options: TransactionOption[] }

interface Props {
  npcData: { name: string; transaction?: TransactionRound[] };
  affinity: number;
  onAffinityChange: (delta: number) => void;
  onComplete: (success: boolean) => void;
  onHoverOption?: (affinity: number | null) => void;
}

export default function TransactionStage({ npcData, affinity, onAffinityChange, onComplete, onHoverOption }: Props) {
  const [currentRound, setCurrentRound] = useState(0);
  const [selectedOption, setSelectedOption] = useState<string | null>(null);
  const [response, setResponse] = useState<string | null>(null);
  const [roundComplete, setRoundComplete] = useState(false);
  const [localAffinity, setLocalAffinity] = useState(affinity);

  const rounds = npcData?.transaction ?? [];
  const round = rounds?.[currentRound];
  const isLastRound = currentRound >= (rounds?.length ?? 0) - 1;
  const compliance = getComplianceRead(localAffinity);

  // Pass 2: typewriter reveal on NPC response
  const { displayed: typedResponse, done: typingDone } = useTypewriter(response);

  // Clear hover state when moving between rounds or unmounting
  useEffect(() => {
    return () => { onHoverOption?.(null); };
  }, [currentRound, onHoverOption]);

  const selectOption = useCallback((option: TransactionOption) => {
    if (roundComplete) return;
    audioManager.playSFX('nav');
    setSelectedOption(option?.id ?? option?.text ?? null);
    setResponse(option?.response ?? 'No response.');
    setRoundComplete(true);
    // Clear hover on selection
    onHoverOption?.(null);

    const delta = option?.affinity ?? option?.affinityDelta ?? 0;
    const newAff = Math.max(0, Math.min(100, localAffinity + delta));
    setLocalAffinity(newAff);
    onAffinityChange(delta);

    if (delta > 0) audioManager.playSFX('confirm');
    else if (delta < 0) audioManager.playSFX('error');

    const voiceClip = option?.voiceClip;
    if (voiceClip && VOICE_CLIP_PLAYERS[voiceClip]) {
      setTimeout(() => {
        try { VOICE_CLIP_PLAYERS[voiceClip]?.(); } catch { /* ignore */ }
      }, 450);
    }
  }, [roundComplete, localAffinity, onAffinityChange, onHoverOption]);

  const nextRound = useCallback(() => {
    if (isLastRound) {
      const success = localAffinity >= 60;
      onComplete(success);
    } else {
      setCurrentRound((prev: number) => (prev ?? 0) + 1);
      setSelectedOption(null);
      setResponse(null);
      setRoundComplete(false);
    }
  }, [isLastRound, localAffinity, onComplete]);

  if (!round) {
    return (
      <div className="p-6 text-center">
        <p className="text-[#a8687e] font-terminal">No pitch data available.</p>
      </div>
    );
  }

  // Sort options by affinity delta — subtle/empathetic at top, aggressive at bottom
  const sortedOptions = [...(round?.options ?? [])].sort((a, b) => ((b?.affinity ?? b?.affinityDelta ?? 0) - (a?.affinity ?? a?.affinityDelta ?? 0)));

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="p-4 sm:p-5"
    >
      {/* Header */}
      <div className="flex items-center gap-2 mb-1">
        <Target size={13} className="text-[#b87a96]/60" />
        <h3 className="font-terminal text-xs text-[#b87a96]/60 tracking-widest">THE PITCH</h3>
        <span className="ml-auto text-[8px] text-[#4a4a3a] font-terminal">ROUND {currentRound + 1}/{rounds?.length ?? 0}</span>
      </div>

      {/* Compliance — qualitative only, no numbers */}
      <div className="mb-5">
        <div className="flex justify-between items-center mb-1">
          <span className="text-[8px] text-[#b87a96]/40 font-terminal tracking-widest">SUBJECT READ</span>
          <motion.span
            key={compliance.text}
            initial={{ opacity: 0, x: 8 }}
            animate={{ opacity: 1, x: 0 }}
            className="text-[10px] font-terminal tracking-wider"
            style={{ color: compliance.color }}
          >
            {compliance.text}
          </motion.span>
        </div>
        {/* Ambient compliance bar — no numbers, no threshold markers visible */}
        <div className="h-1.5 bg-[#0a0a0a] relative overflow-hidden" style={{ border: '1px solid rgba(255,75,193,0.08)' }}>
          <motion.div
            className="absolute inset-y-0 left-0"
            animate={{ width: `${localAffinity}%` }}
            transition={{ duration: 0.6 }}
            style={{
              background: `linear-gradient(90deg, ${compliance.color}33, ${compliance.color}66)`,
              boxShadow: `0 0 8px ${compliance.color}22`,
            }}
          />
        </div>
      </div>

      {/* Prompt — what the NPC says/does */}
      <div className="p-4 mb-4" style={{
        border: '1px solid rgba(255,75,193,0.1)',
        borderLeft: '3px solid rgba(255,75,193,0.3)',
        background: 'rgba(0,0,0,0.2)',
      }}>
        <p className="font-typewriter text-sm text-[#E8E8E8]/75 italic leading-relaxed">
          {round?.prompt ?? 'The subject waits.'}
        </p>
      </div>

      {/* ── MANIPULATION SPECTRUM — options arranged top=subtle, bottom=aggressive ── */}
      <div className="mb-1">
        <div className="flex justify-between text-[7px] font-terminal tracking-widest mb-1.5">
          <span className="text-[#9cff76]/30">▲ EMPATHETIC</span>
          <span className="text-[#b87a96]/30">EXPLOITATIVE ▼</span>
        </div>
        <div className="space-y-1.5">
          {sortedOptions.map((option: TransactionOption, i: number) => {
            const isSelected = selectedOption === (option?.id ?? option?.text);
            const showResult = roundComplete && isSelected;
            const optAffinity = option?.affinity ?? option?.affinityDelta ?? 0;
            const isPositive = optAffinity > 0;
            const isNeutral = optAffinity === 0;

            // Spectrum gradient — empathetic (top) to exploitative (bottom)
            const spectrumPos = i / Math.max(1, sortedOptions.length - 1);
            const spectrumColor = spectrumPos < 0.3 ? '#9cff76' : spectrumPos > 0.7 ? '#b87a96' : '#FFB000';

            return (
              <motion.button
                key={option?.id ?? i}
                whileTap={!roundComplete ? { scale: 0.98 } : {}}
                onClick={() => selectOption(option)}
                onMouseEnter={() => { if (!roundComplete) onHoverOption?.(optAffinity); }}
                onMouseLeave={() => { if (!roundComplete) onHoverOption?.(null); }}
                disabled={roundComplete}
                className="w-full text-left px-3 py-2.5 transition-all font-terminal text-[11px] flex items-start gap-2"
                style={{
                  borderLeft: `3px solid ${
                    showResult
                      ? (isPositive ? '#9cff76' : isNeutral ? '#FFB000' : '#b87a96')
                      : `${spectrumColor}20`
                  }`,
                  border: showResult
                    ? `1px solid ${isPositive ? '#9cff7644' : '#b87a9644'}`
                    : `1px solid rgba(255,75,193,0.06)`,
                  borderLeftWidth: '3px',
                  borderLeftColor: showResult
                    ? (isPositive ? '#9cff76' : isNeutral ? '#FFB000' : '#b87a96')
                    : `${spectrumColor}25`,
                  background: showResult
                    ? (isPositive ? 'rgba(156,255,118,0.05)' : 'rgba(255,75,193,0.05)')
                    : 'rgba(0,0,0,0.15)',
                  opacity: roundComplete && !isSelected ? 0.15 : 1,
                  cursor: roundComplete ? 'default' : 'pointer',
                  color: showResult
                    ? (isPositive ? '#9cff76' : '#b87a96')
                    : '#E8E8E8cc',
                }}
              >
                <span className="flex-1">&ldquo;{option?.text ?? ''}&rdquo;</span>
                {showResult && (
                  <motion.span
                    initial={{ opacity: 0, x: 8 }}
                    animate={{ opacity: 1, x: 0 }}
                    className="flex-shrink-0 text-[9px] mt-0.5"
                    style={{ color: isPositive ? '#9cff76' : isNeutral ? '#FFB000' : '#b87a96' }}
                  >
                    {isPositive ? 'COMPLIANCE \u25b2' : isNeutral ? 'NO EFFECT' : 'COMPLIANCE \u25bc'}
                  </motion.span>
                )}
              </motion.button>
            );
          })}
        </div>
      </div>

      {/* Response — NPC reacts with typewriter reveal */}
      <AnimatePresence>
        {response && (
          <motion.div
            initial={{ opacity: 0, y: 8 }}
            animate={{ opacity: 1, y: 0 }}
            className="p-3 my-4"
            style={{
              background: 'rgba(0,0,0,0.2)',
              borderLeft: '2px solid rgba(243,232,207,0.15)',
              color: '#f3e8cf',
            }}
          >
            <p className="font-typewriter text-sm italic leading-relaxed">
              {typedResponse}
              {!typingDone && (
                <motion.span
                  animate={{ opacity: [1, 0] }}
                  transition={{ duration: 0.5, repeat: Infinity }}
                  className="inline-block w-[2px] h-[14px] bg-[#f3e8cf]/60 ml-0.5 align-middle"
                />
              )}
            </p>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Next round / Complete */}
      {roundComplete && typingDone && (
        <motion.button
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          onClick={() => { audioManager.playSFX('nav'); nextRound(); }}
          className="w-full font-terminal py-3 text-sm transition-all tracking-wider cursor-pointer active:scale-[0.98]"
          style={{
            border: `1px solid ${compliance.color}`,
            color: compliance.color,
            background: `${compliance.color}08`,
          }}
        >
          {isLastRound
            ? (localAffinity >= 60 ? 'COMPLETE INTAKE \u2713' : 'CONCLUDE PITCH')
            : 'NEXT ROUND >'}
        </motion.button>
      )}
    </motion.div>
  );
}

