  activeStationRef.current = activeStation
  const activeDocumentRef = useRef(activeDocument)
  activeDocumentRef.current = activeDocument
  const touchRef = useRef<{ x: number; y: number } | null>(null)

  const goTo = useCallback((id: TabId) => {
    const from = STATION_ORDER.indexOf(activeStationRef.current)
    const to = STATION_ORDER.indexOf(id)
    const dir = to - from
    setDirection(dir)
    setActiveStation(id)
    setActiveDocument(null)
    setOverlayTight(true)
    setTimeout(() => setOverlayTight(false), 200)
    if (dir !== 0) setSweep((s) => ({ key: s.key + 1, dir }))
    const meta = STATIONS.find((s) => s.id === id)
    hudRef.current.triggerScan()
    hudRef.current.pulse('press')
    if (dir !== 0) hudRef.current.transition(dir)
    hudRef.current.note(`STATION ${meta?.pos ?? '0'} / ${meta?.label ?? ''}`)
  }, [])

  const step = useCallback((delta: number) => {
    const idx = STATION_ORDER.indexOf(activeStationRef.current)
    const nextIdx = Math.min(Math.max(idx + delta, 0), STATION_ORDER.length - 1)
    if (nextIdx !== idx) goTo(STATION_ORDER[nextIdx])
  }, [goTo])

  const openDocument = useCallback((id: string) => {
    setActiveDocument(id)
    setSweep((s) => ({ key: s.key + 1, dir: 1 }))
    hudRef.current.triggerScan()
    hudRef.current.pulse('press')
    hudRef.current.transition(1)
    hudRef.current.note(`OPEN / ${id.replace(/-/g, ' ').toUpperCase()}`)
  }, [])

  const closeDocument = useCallback(() => {
    setActiveDocument(null)
    setSweep((s) => ({ key: s.key + 1, dir: -1 }))
    hudRef.current.pulse('tick')
    hudRef.current.transition(-1)
    hudRef.current.note('DOCUMENTS / INDEX')
  }, [])

  // Keyboard nav: Left/Right walk the route; Escape steps back to centre.
  // Up/Down are left free so vertical reading scroll is never hijacked.
  useEffect(() => {
    const handleKey = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement | null
      if (target?.closest?.('[data-hud-control]')) return
      const tag = target?.tagName
      if (tag === 'INPUT' || tag === 'TEXTAREA' || target?.isContentEditable) return

      if (e.key === 'ArrowRight') {
        e.preventDefault()
        step(1)
      } else if (e.key === 'ArrowLeft') {
        e.preventDefault()
        step(-1)
      } else if (e.key === 'Escape') {
        if (activeDocumentRef.current) {
          closeDocument()
        } else if (activeStationRef.current !== 'hero') {
          goTo('hero')
        }
      }
    }
    window?.addEventListener?.('keydown', handleKey)
    return () => window?.removeEventListener?.('keydown', handleKey)
  }, [step, goTo, closeDocument])

  // Grand entrance — a single specular sweep as the app resolves in, so the
  // win sweep reads as an app-wide signature and not only a per-station tic.
  useEffect(() => {
    setSweep((s) => ({ key: s.key + 1, dir: 1 }))
  }, [])

  const onTouchStart = useCallback((e: React.TouchEvent) => {
    const target = e.target as HTMLElement | null
    if (target?.closest?.('[data-hud-control]')) {
      touchRef.current = null
      return
    }
    const t = e.touches[0]
    touchRef.current = { x: t.clientX, y: t.clientY }
  }, [])

  const onTouchEnd = useCallback((e: React.TouchEvent) => {
    const start = touchRef.current
    touchRef.current = null
    if (!start) return
    const t = e.changedTouches[0]
    const dx = t.clientX - start.x
    const dy = t.clientY - start.y
    if (Math.abs(dx) > 60 && Math.abs(dx) > Math.abs(dy) * 1.4) {
      step(dx < 0 ? 1 : -1)
    }
  }, [step])

  // The source reader stays offstage; do not bundle private dossier copy here.
  const isBlueMode = false
  const isPublicDeck = activeStation === 'documents'

  const ctx: StationCtx = { activeDocument, openDocument, closeDocument, goTo }
  const content = getStationContent(activeStation, ctx)

  return (
    <motion.div
      className="fixed inset-0 bg-[#0A0A08] flex flex-col"
      data-public-deck={isPublicDeck ? '' : undefined}
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 0.5 }}
    >
      {/* Reading-first by default. The original instrument field remains opt-in. */}
      {instrumentsOpen && !isPublicDeck && <EdgeBloom tabId={activeStation} blueMode={isBlueMode} />}
      {instrumentsOpen && !isPublicDeck && <ScanSystem blueMode={isBlueMode} />}

      <AnimatePresence>
        {instrumentsOpen && overlayTight && !isPublicDeck && (
          <motion.div
            className="absolute inset-0 pointer-events-none z-50"
            initial={{ opacity: 0 }}
            animate={{ opacity: [0, 1, 0.25, 0.9] }}
            exit={{ opacity: 0 }}
            transition={{ duration: 0.2, times: [0, 0.35, 0.6, 1] }}
          >
            <div className="absolute inset-4 md:inset-6 border border-[#B8F02622]" />
          </motion.div>
        )}
      </AnimatePresence>

      {/* Window sweep — specular band passing across the viewport on transition */}
      {instrumentsOpen && sweep.key > 0 && !isPublicDeck && (
        <div
          key={sweep.key}
          className="absolute inset-0 z-40 pointer-events-none overflow-hidden"
          aria-hidden="true"
        >
          <div
            className={`win-sweep-band absolute inset-y-0 left-0 w-[40%] ${sweep.dir < 0 ? 'rev' : ''}`}
            style={{
              background:
                'linear-gradient(100deg, transparent 0%, rgba(184,240,38,0.06) 30%, rgba(224,64,176,0.05) 43%, rgba(232,228,217,0.26) 50%, rgba(184,240,38,0.06) 57%, transparent 100%)',
            }}
          />
        </div>
      )}

      <div className="relative z-30 shrink-0" data-shell="navigation">
        <TabNavigator activeStation={activeStation} onStationChange={goTo} />
      </div>

      {/* Instrument gutters flank the reading area — they never sit on top of it. */}
      <div className="flex-1 flex min-h-0">
        {instrumentsOpen && <HudLeftGutter />}

        <div
          className="flex-1 min-w-0 relative"
          onTouchStart={onTouchStart}
          onTouchEnd={onTouchEnd}
        >
          {instrumentsOpen && !isPublicDeck && <OverlayFrame tabId={activeStation} blueMode={isBlueMode} />}

          <AnimatePresence mode="wait" custom={direction}>
            <motion.div
              key={`${activeStation}:${activeDocument ?? 'base'}`}
              className={`absolute inset-0 scrollbar-hide z-10 ${isPublicDeck ? 'overflow-hidden' : 'overflow-y-auto'}`}
              custom={direction}
              variants={reducedMotion ? { enter: { opacity: 0 }, center: { opacity: 1 }, exit: { opacity: 0 } } : slideVariants}
              initial="enter"
              animate="center"
              exit="exit"
              transition={{ duration: 0.32, ease: 'easeOut' }}
            >
              {content}
            </motion.div>
          </AnimatePresence>

          {/* Main navigation above replaces duplicate floating page arrows. */}
        </div>

        {instrumentsOpen && <HudRightGutter />}
      </div>

      {/* Mobile hardware rail */}
      {instrumentsOpen && <HudMobileRail />}

      {/* Bottom status bar — always shows position on the route. */}
      <div className="app-status-bar relative z-30 shrink-0 flex items-center justify-between px-3 md:px-5" data-shell="status">
        <div className="hairline-x absolute top-0 left-0 opacity-70" aria-hidden="true" />
        <button type="button" data-hud-control className="display-controls-toggle focus-ring" aria-expanded={instrumentsOpen} onClick={() => setInstrumentsOpen((open) => !open)}>
          Display controls <span aria-hidden="true">{instrumentsOpen ? '−' : '+'}</span>
        </button>
        <div className="flex items-center gap-3">
          {/* Global score volume — present on every station */}
          <div
            data-hud-control
            className="flex items-center gap-1.5"
            title="Score volume"
          >
            <span
              aria-hidden="true"
              className="text-[8px] uppercase tracking-label text-[#E040B0] opacity-90"
            >
              {hud.musicVolume === 0 ? 'MUTED' : 'MUSIC'}
            </span>
            <input
              type="range"
              min={0}
              max={1}
              step={0.01}
              value={hud.musicVolume}
              onChange={(e) => hud.setMusicVolume(parseFloat(e.target.value))}
              aria-label="Score volume"
              className="score-fader w-14 md:w-24 h-8 cursor-pointer"
            />
          </div>
          <button
            data-hud-control
            onClick={() => {
              hud.toggleSound()
              hud.pulse('tick')
            }}
            aria-label={hud.soundOn ? 'Mute transition sound' : 'Unmute transition sound'}
            aria-pressed={hud.soundOn}
            className="focus-ring tap flex items-center gap-1 min-h-9 px-1 text-[8px] uppercase tracking-label transition-colors"
            style={{ color: hud.soundOn ? '#B8F026' : '#E8E4D9', opacity: hud.soundOn ? 0.95 : 0.7 }}
          >
            <span className="w-1 h-1" style={{ background: 'currentColor' }} />
            SFX {hud.soundOn ? 'ON' : 'OFF'}
          </button>
        </div>
      </div>

      {instrumentsOpen && <div className="prestige-vignette" aria-hidden="true" />}
      {instrumentsOpen && <div className="prestige-grain" aria-hidden="true" />}
    </motion.div>
  )
}

