'use client';

import * as React from 'react';
import useEmblaCarousel, {
  type UseEmblaCarouselType,
} from 'embla-carousel-react';
import { ArrowLeft, ArrowRight } from 'lucide-react';

import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';

type CarouselApi = UseEmblaCarouselType[1];
type UseCarouselParameters = Parameters<typeof useEmblaCarousel>;
type CarouselOptions = UseCarouselParameters[0];
type CarouselPlugin = UseCarouselParameters[1];

type CarouselProps = {
  opts?: CarouselOptions;
  plugins?: CarouselPlugin;
  orientation?: 'horizontal' | 'vertical';
  setApi?: (api: CarouselApi) => void;
};

type CarouselContextProps = {
  carouselRef: ReturnType<typeof useEmblaCarousel>[0];
  api: ReturnType<typeof useEmblaCarousel>[1];
  scrollPrev: () => void;
  scrollNext: () => void;
  canScrollPrev: boolean;
  canScrollNext: boolean;
} & CarouselProps;

const CarouselContext = React.createContext<CarouselContextProps | null>(null);

function useCarousel() {
  const context = React.useContext(CarouselContext);

  if (!context) {
    throw new Error('useCarousel must be used within a <Carousel />');
  }

  return context;
}

const Carousel = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement> & CarouselProps
>(
  (
    {
      orientation = 'horizontal',
      opts,
      setApi,
      plugins,
      className,
      children,
      ...props
    },
    ref
  ) => {
    const [carouselRef, api] = useEmblaCarousel(
      {
        ...opts,
        axis: orientation === 'horizontal' ? 'x' : 'y',
      },
      plugins
    );
    const [canScrollPrev, setCanScrollPrev] = React.useState(false);
    const [canScrollNext, setCanScrollNext] = React.useState(false);

    const onSelect = React.useCallback((api: CarouselApi) => {
      if (!api) {
        return;
      }

      setCanScrollPrev(api.canScrollPrev());
      setCanScrollNext(api.canScrollNext());
    }, []);

    const scrollPrev = React.useCallback(() => {
      api?.scrollPrev();
    }, [api]);

    const scrollNext = React.useCallback(() => {
      api?.scrollNext();
    }, [api]);

    const handleKeyDown = React.useCallback(
      (event: React.KeyboardEvent<HTMLDivElement>) => {
        if (event.key === 'ArrowLeft') {
          event.preventDefault();
          scrollPrev();
        } else if (event.key === 'ArrowRight') {
          event.preventDefault();
          scrollNext();
        }
      },
      [scrollPrev, scrollNext]
    );

    React.useEffect(() => {
      if (!api || !setApi) {
        return;
      }

      setApi(api);
    }, [api, setApi]);

    React.useEffect(() => {
      if (!api) {
        return;
      }

      onSelect(api);
      api.on('reInit', onSelect);
      api.on('select', onSelect);

      return () => {
        api?.off('select', onSelect);
      };
    }, [api, onSelect]);

    return (
      <CarouselContext.Provider
        value={{
          carouselRef,
          api: api,
          opts,
          orientation:
            orientation || (opts?.axis === 'y' ? 'vertical' : 'horizontal'),
          scrollPrev,
          scrollNext,
          canScrollPrev,
          canScrollNext,
        }}
      >
        <div
          ref={ref}
          onKeyDownCapture={handleKeyDown}
          className={cn('relative', className)}
          role="region"
          aria-roledescription="carousel"
          {...props}
        >
          {children}
        </div>
      </CarouselContext.Provider>
    );
  }
);
Carousel.displayName = 'Carousel';

const CarouselContent = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement>
>(({ className, ...props }, ref) => {
  const { carouselRef, orientation } = useCarousel();

  return (
    <div ref={carouselRef} className="overflow-hidden">
      <div
        ref={ref}
        className={cn(
          'flex',
          orientation === 'horizontal' ? '-ml-4' : '-mt-4 flex-col',
          className
        )}
        {...props}
      />
    </div>
  );
});
CarouselContent.displayName = 'CarouselContent';

const CarouselItem = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement>
>(({ className, ...props }, ref) => {
  const { orientation } = useCarousel();

  return (
    <div
      ref={ref}
      role="group"
      aria-roledescription="slide"
      className={cn(
        'min-w-0 shrink-0 grow-0 basis-full',
        orientation === 'horizontal' ? 'pl-4' : 'pt-4',
        className
      )}
      {...props}
    />
  );
});
CarouselItem.displayName = 'CarouselItem';

const CarouselPrevious = React.forwardRef<
  HTMLButtonElement,
  React.ComponentProps<typeof Button>
>(({ className, variant = 'outline', size = 'icon', ...props }, ref) => {
  const { orientation, scrollPrev, canScrollPrev } = useCarousel();

  return (
    <Button
      ref={ref}
      variant={variant}
      size={size}
      className={cn(
        'absolute  h-8 w-8 rounded-full',
        orientation === 'horizontal'
          ? '-left-12 top-1/2 -translate-y-1/2'
          : '-top-12 left-1/2 -translate-x-1/2 rotate-90',
        className
      )}
      disabled={!canScrollPrev}
      onClick={scrollPrev}
      {...props}
    >
      <ArrowLeft className="h-4 w-4" />
      <span className="sr-only">Previous slide</span>
    </Button>
  );
});
CarouselPrevious.displayName = 'CarouselPrevious';

const CarouselNext = React.forwardRef<
  HTMLButtonElement,
  React.ComponentProps<typeof Button>
>(({ className, variant = 'outline', size = 'icon', ...props }, ref) => {
  const { orientation, scrollNext, canScrollNext } = useCarousel();

  return (
    <Button
      ref={ref}
      variant={variant}
      size={size}
      className={cn(
        'absolute h-8 w-8 rounded-full',
        orientation === 'horizontal'
          ? '-right-12 top-1/2 -translate-y-1/2'
          : '-bottom-12 left-1/2 -translate-x-1/2 rotate-90',
        className
      )}
      disabled={!canScrollNext}
      onClick={scrollNext}
      {...props}
    >
      <ArrowRight className="h-4 w-4" />
      <span className="sr-only">Next slide</span>
    </Button>
  );
});
CarouselNext.displayName = 'CarouselNext';

export {
  type CarouselApi,
  Carousel,
  CarouselContent,
  CarouselItem,
  CarouselPrevious,
  CarouselNext,
};

'use client'

import { motion } from 'framer-motion'

const viewportConfig = { once: true, margin: '-60px' as `${number}px` }

export function FadeIn({
  children, delay = 0, duration = 0.4, className,
}: {
  children: React.ReactNode; delay?: number; duration?: number; className?: string
}) {
  return (
    <motion.div
      initial={{ opacity: 0, y: 8 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={viewportConfig}
      transition={{ duration, delay, ease: 'easeOut' }}
      className={className}
    >
      {children}
    </motion.div>
  )
}

export function ScaleIn({
  children, delay = 0, className,
}: {
  children: React.ReactNode; delay?: number; className?: string
}) {
  return (
    <motion.div
      initial={{ opacity: 0, scale: 0.95 }}
      whileInView={{ opacity: 1, scale: 1 }}
      viewport={viewportConfig}
      transition={{ duration: 0.3, delay, ease: 'easeOut' }}
      className={className}
    >
      {children}
    </motion.div>
  )
}

const slideDirections = {
  bottom: { y: 20, x: 0 },
  top:    { y: -20, x: 0 },
  left:   { x: -20, y: 0 },
  right:  { x: 20, y: 0 },
}

export function SlideIn({
  children, from = 'bottom', delay = 0, className,
}: {
  children: React.ReactNode; from?: keyof typeof slideDirections; delay?: number; className?: string
}) {
  return (
    <motion.div
      initial={{ opacity: 0, ...slideDirections[from] }}
      whileInView={{ opacity: 1, x: 0, y: 0 }}
      viewport={viewportConfig}
      transition={{ duration: 0.4, delay, ease: 'easeOut' }}
      className={className}
    >
      {children}
    </motion.div>
  )
}

export function Stagger({
  children, staggerDelay = 0.08, className,
}: {
  children: React.ReactNode; staggerDelay?: number; className?: string
}) {
  return (
    <motion.div
      variants={{ show: { transition: { staggerChildren: staggerDelay } } }}
      initial="hidden"
      whileInView="show"
      viewport={viewportConfig}
      className={className}
    >
      {children}
    </motion.div>
  )
}

export function StaggerItem({
  children, className,
}: {
  children: React.ReactNode; className?: string
}) {
  return (
    <motion.div
      variants={{
        hidden: { opacity: 0, y: 16 },
        show: { opacity: 1, y: 0, transition: { duration: 0.4, ease: 'easeOut' } },
      }}
      className={className}
    >
      {children}
    </motion.div>
  )
}

export function HoverLift({
  children, className,
}: {
  children: React.ReactNode; className?: string
}) {
  return (
    <motion.div
      whileHover={{ y: -2, boxShadow: 'var(--shadow-lg)' }}
      transition={{ duration: 0.15, ease: 'easeOut' }}
      className={className}
    >
      {children}
    </motion.div>
  )
}

export function PressScale({
  children, className,
}: {
  children: React.ReactNode; className?: string
}) {
  return (
    <motion.div
      whileTap={{ scale: 0.98 }}
      transition={{ duration: 0.1, ease: 'easeOut' }}
      className={className}
    >
      {children}
    </motion.div>
  )
}

export function SkeletonPulse({ className }: { className?: string }) {
  return (
    <motion.div
      animate={{ opacity: [0.4, 1, 0.4] }}
      transition={{ duration: 1.5, repeat: Infinity, ease: 'easeInOut' }}
      className={`rounded-md bg-muted ${className ?? ''}`}
    />
  )
}

@import url('https://fonts.googleapis.com/css2?family=Anton&family=Oswald:wght@700&family=IBM+Plex+Mono:wght@400&display=swap');

@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    /* ================================================================
       BANNER TOKENS — single source of truth for every colour on the site.
       Sampled from the GREY.FILTER banner (public/assets/gf-banner-cold.jpg).
       Change a value here and the whole site (pages, hero, admin) follows.
       Channels are stored as "R G B" so any alpha can be derived:
       rgb(var(--bv-primary-rgb) / 0.2)
       ================================================================ */
    --bv-bg-rgb: 4 4 3;              /* background — deepest banner shadow */
    --bv-surface-rgb: 22 21 21;      /* surface — banner dark ground */
    --bv-surface-2-rgb: 34 31 30;    /* surface 2 — charcoal grunge */
    --bv-surface-3-rgb: 42 39 36;    /* surface 3 — lit grunge, top-left of banner */
    --bv-secondary-rgb: 66 62 58;    /* secondary — steel / frame shadow, borders */
    --bv-text-rgb: 211 208 205;      /* text — bone */
    --bv-text-muted-rgb: 154 149 144;/* text muted — bone into steel */
    --bv-text-strong-rgb: 241 231 213; /* text strong — banner lettering ivory */
    --bv-primary-rgb: 215 156 30;    /* primary — banner frame gold */
    --bv-accent-rgb: 241 179 1;      /* accent — hazard-stripe gold, bright */
    --bv-highlight-rgb: 255 250 240; /* hot highlight (laser core, gloss) */
    --bv-shadow-rgb: 0 0 0;          /* shadow ink */
    /* Haunt-only glitch channels (owner-approved exception, used nowhere else) */
    --bv-haunt-cyan-rgb: 0 255 240;
    --bv-haunt-magenta-rgb: 255 0 200;

    --bv-bg: rgb(var(--bv-bg-rgb));
    --bv-surface: rgb(var(--bv-surface-rgb));
    --bv-surface-2: rgb(var(--bv-surface-2-rgb));
    --bv-surface-3: rgb(var(--bv-surface-3-rgb));
    --bv-secondary: rgb(var(--bv-secondary-rgb));
    --bv-text: rgb(var(--bv-text-rgb));
    --bv-text-muted: rgb(var(--bv-text-muted-rgb));
    --bv-text-strong: rgb(var(--bv-text-strong-rgb));
    --bv-primary: rgb(var(--bv-primary-rgb));
    --bv-accent: rgb(var(--bv-accent-rgb));
    --bv-highlight: rgb(var(--bv-highlight-rgb));
    --bv-border: var(--bv-secondary);

    /* Banner gradients: the lit grunge pocket upper-right falling to black at the edges */
    --bv-gradient-banner: radial-gradient(120% 95% at 68% 22%, rgb(var(--bv-secondary-rgb)) 0%, var(--bv-surface-3) 30%, var(--bv-surface-2) 55%, var(--bv-surface) 78%, var(--bv-bg) 100%);
    --bv-gradient-panel: linear-gradient(160deg, var(--bv-surface-3) 0%, var(--bv-surface) 35%, var(--bv-bg) 78%);
    --bv-gradient-gold: linear-gradient(90deg, transparent, var(--bv-primary) 20%, var(--bv-accent) 50%, var(--bv-primary) 80%, transparent);

    /* Legacy aliases — every older class/inline style resolves to the banner tokens */
    --col-black: var(--bv-bg);
    --col-gunmetal: var(--bv-surface);
    --col-charcoal: var(--bv-surface-2);
    --col-steel: var(--bv-secondary);
    --col-bone: var(--bv-text);
    --col-ivory: var(--bv-text-strong);
    --col-yellow: var(--bv-primary);
    --col-yellow-hot: var(--bv-accent);
    --col-smoke: rgb(var(--bv-text-rgb) / 0.06);
    --radius: 0rem;

    /* Spacing */
    --spacing-xs: 4px;
    --spacing-sm: 8px;
    --spacing-md: 16px;
    --spacing-lg: 24px;
    --spacing-xl: 32px;
    --spacing-2xl: 48px;
    --spacing-3xl: 64px;

    /* Shadows */
    --shadow-sm: 0 1px 3px rgb(var(--bv-shadow-rgb) / 0.4);
    --shadow-md: 0 4px 12px rgb(var(--bv-shadow-rgb) / 0.5);
    --shadow-lg: 0 8px 30px rgb(var(--bv-shadow-rgb) / 0.6);

    /* Durations */
    --duration-fast: 150ms;
    --duration-normal: 250ms;
    --duration-slow: 350ms;
  }
}

* {
  border-radius: 0 !important;
}

html {
  scroll-behavior: smooth;
}

body {
  background-color: var(--col-black);
  color: var(--col-bone);
  font-family: 'IBM Plex Mono', monospace;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

/* Font utilities */
.font-anton {
  font-family: 'Anton', Impact, sans-serif;
}

.font-oswald {
  font-family: 'Oswald', sans-serif;
  font-weight: 700;
}

.font-ibm {
  font-family: 'IBM Plex Mono', monospace;
  font-weight: 400;
}

/* Grain overlay */
.grain::after {
  content: '';
  position: fixed;
  inset: 0;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)' opacity='0.5'/%3E%3C/svg%3E");
  opacity: 0.06;
  pointer-events: none;
  z-index: 9999;
  mix-blend-mode: overlay;
}

/* Focus style */
*:focus-visible {
  outline: 2px solid var(--col-yellow) !important;
  outline-offset: 2px;
}

/* Gauge animations */
@keyframes gauge-sweep {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(270deg); }
}

@keyframes gauge-fast-spin {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

@keyframes steam-rise {
  0% {
    opacity: 0;
    transform: translateY(0) scale(0.8);
  }
  20% {
    opacity: 0.12;
  }
  100% {
    opacity: 0;
    transform: translateY(-70px) scale(1.2);
  }
}

@keyframes flash-brightness {
  0% { filter: brightness(1); }
  50% { filter: brightness(1.3); }
  100% { filter: brightness(1); }
}

@keyframes readout-blink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
  .steam-particle {
    display: none !important;
  }
}

/* Scrollbar */
::-webkit-scrollbar {
  width: 6px;
}
::-webkit-scrollbar-track {
  background: var(--col-black);
}
::-webkit-scrollbar-thumb {
  background: var(--col-steel);
}

/* ── Attitude layer: print-texture utilities (static unless noted) ── */
.scanlines {
  background-image: repeating-linear-gradient(0deg, rgb(var(--bv-shadow-rgb) / 0.22) 0px, rgb(var(--bv-shadow-rgb) / 0.22) 1px, transparent 1px, transparent 3px);
  pointer-events: none;
}
.hazard-stripes {
  background-image: repeating-linear-gradient(-45deg, rgb(var(--bv-primary-rgb) / 0.08) 0 14px, transparent 14px 28px);
  pointer-events: none;
}
/* Gold hairline rule (replaces the old red rule) */
.gold-rule { height: 2px; background: var(--col-yellow); }
/* Visual twin of every haptic: buttons physically depress */
.press-fx {
  transition: transform 90ms ease, box-shadow 90ms ease, background-color 150ms, filter 150ms;
  /* gloss: lit top edge, falling sheen, darker foot */
  background-image: linear-gradient(180deg, rgb(var(--bv-highlight-rgb) / 0.16) 0%, rgb(var(--bv-highlight-rgb) / 0.04) 46%, rgb(var(--bv-shadow-rgb) / 0) 50%, rgb(var(--bv-shadow-rgb) / 0.18) 100%);
  box-shadow: inset 0 1px 0 rgb(var(--bv-highlight-rgb) / 0.14), inset 0 -1px 0 rgb(var(--bv-shadow-rgb) / 0.35), 0 6px 16px rgb(var(--bv-shadow-rgb) / 0.45);
}
.press-fx:hover { filter: brightness(1.08); }
.press-fx:active { transform: translate(3px, 3px); box-shadow: none !important; }

/* Page field: localized gradients + hatch/scan texture over the black base (layered above inline background-color) */
.bv-field {
  background-image:
    radial-gradient(110% 55% at 50% -8%, rgb(var(--bv-primary-rgb) / 0.11), transparent 62%),
    radial-gradient(70% 55% at 100% 100%, rgb(var(--bv-secondary-rgb) / 0.38), transparent 70%),
    radial-gradient(60% 45% at 0% 55%, rgb(var(--bv-surface-2-rgb) / 0.7), transparent 72%),
    repeating-linear-gradient(135deg, rgb(var(--bv-text-strong-rgb) / 0.022) 0 1px, transparent 1px 7px),
    repeating-linear-gradient(0deg, rgb(var(--bv-shadow-rgb) / 0.28) 0 1px, transparent 1px 3px);
}
/* Glossy nav bar: steel-lit glass strip with a gold underglow */
.bv-glass {
  background-image: linear-gradient(180deg, rgb(var(--bv-secondary-rgb) / 0.55) 0%, rgb(var(--bv-surface-rgb) / 0.25) 55%, rgb(var(--bv-bg-rgb) / 0) 100%);
  box-shadow: inset 0 1px 0 rgb(var(--bv-text-strong-rgb) / 0.07), 0 1px 0 rgb(var(--bv-primary-rgb) / 0.18), 0 10px 24px rgb(var(--bv-shadow-rgb) / 0.5);
}

.bv-card {
  transition: transform 260ms cubic-bezier(0.2,0.8,0.2,1), box-shadow 260ms ease;
  background-image:
    linear-gradient(180deg, rgb(var(--bv-text-strong-rgb) / 0.07) 0%, rgb(var(--bv-text-strong-rgb) / 0) 22%),
    linear-gradient(155deg, var(--bv-surface-3) 0%, var(--col-gunmetal) 45%, var(--bv-bg) 100%);
}
/* Defined edge: 1px steel frame + lit top line + gold hairline on top; never blocks clicks */
.bv-card::after {
  content: ''; position: absolute; inset: 0; pointer-events: none; z-index: 4;
  border: 1px solid rgb(var(--bv-secondary-rgb) / 0.95);
  box-shadow: inset 0 1px 0 rgb(var(--bv-text-strong-rgb) / 0.1), inset 0 0 0 1px rgb(var(--bv-shadow-rgb) / 0.6);
  background: linear-gradient(90deg, transparent, rgb(var(--bv-primary-rgb) / 0.55) 20%, rgb(var(--bv-primary-rgb) / 0.55) 80%, transparent) top / 100% 1px no-repeat;
  transition: border-color 200ms ease;
}
.bv-card:hover::after, .bv-card:focus-within::after { border-color: var(--col-yellow); }
.bv-card:hover, .bv-card:focus-within {
  transform: translateY(-2px);
  box-shadow: 0 0 0 1px var(--col-yellow), 0 18px 40px rgb(var(--bv-shadow-rgb) / 0.55) !important;
}
.bv-card:active { transform: translate(1px, 1px); }
/* Dossier window: short clip-path unfold, no transform on the backdrop */
.dossier-backdrop { animation: dossier-fade 180ms ease-out backwards; }
.dossier-panel { animation: dossier-open 280ms cubic-bezier(0.2,0.8,0.2,1) backwards; }
@keyframes dossier-fade { from { opacity: 0; } to { opacity: 1; } }
@keyframes dossier-open {
  from { clip-path: inset(48% 0 48% 0); }
  to { clip-path: inset(-20px -20px -20px -20px); }
}
@media (prefers-reduced-motion: reduce) {
  .dossier-backdrop, .dossier-panel { animation: none; }
}
.sweep-line {
  background: linear-gradient(90deg, transparent 0%, rgb(var(--bv-accent-rgb) / 0.28) 48%, rgb(var(--bv-text-strong-rgb) / 0.5) 50%, rgb(var(--bv-accent-rgb) / 0.28) 52%, transparent 100%);
  animation: sweep-across 700ms cubic-bezier(0.6,0,0.4,1) forwards;
  pointer-events: none;
}
@keyframes sweep-across {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(100%); }
}
.launch-bar {
  width: 0%;
  animation: launch-fill 900ms cubic-bezier(0.7,0,0.2,1) 200ms forwards;
}
@keyframes launch-fill {
  0% { width: 0%; }
  100% { width: 100%; }
}
@media (prefers-reduced-motion: reduce) {
  .sweep-line { display: none; }
  .launch-bar { width: 100%; }
}

/* ── Control room (admin) ── */
.admin-card {
  background: var(--col-gunmetal);
  border-top: 2px solid var(--col-yellow);
  box-shadow: 0 20px 44px rgb(var(--bv-shadow-rgb) / 0.5);
  padding: 1.5rem;
}
.admin-input {
  width: 100%;
  background: var(--col-black);
  color: var(--col-ivory);
  border: 1px solid var(--col-steel);
  padding: 0.6rem 0.75rem;
  font-family: 'IBM Plex Mono', monospace;
  font-size: 0.85rem;
  min-height: 44px;
}
.admin-input:focus { outline: 2px solid var(--col-yellow); outline-offset: -1px; }
select.admin-input { min-height: 44px; cursor: pointer; }
select.admin-input option { background: var(--col-black); color: var(--col-ivory); }

/* ── Owner switches + phone polish ── */
body:has(.grain-off)::after { display: none; }
.safe-top { padding-top: env(safe-area-inset-top); }
.safe-bottom { padding-bottom: max(12px, env(safe-area-inset-bottom)); }
.mobile-bar {
  transform: translateY(110%);
  transition: transform 320ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.mobile-bar[data-show='true'] { transform: translateY(0); }
.nav-link { position: relative; }
.nav-link::after {
  content: '';
  position: absolute;
  left: 0; right: 0; bottom: 8px;
  height: 2px;
  background: var(--col-yellow);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 220ms ease;
}
.nav-link[aria-current='true']::after { transform: scaleX(1); }

/* Page transition: signal-gold laser wipe. A beam cuts left→right; the page is revealed (clip-path only)
   exactly behind it. Beam, veil and reveal share duration/delay/easing so the cut edge never drifts.
   Perf: overlay moves by transform/opacity only (veil slides instead of clip-path), no blend modes,
   no animated filters, layer isolated with contain. */
:root { --laser-dur: 600ms; --laser-delay: 60ms; --laser-ease: cubic-bezier(0.7, 0, 0.22, 1); }
.page-reveal { animation: laser-reveal var(--laser-dur) var(--laser-ease) var(--laser-delay) backwards; }
@keyframes laser-reveal {
  from { clip-path: inset(0 100% 0 0); }
  to { clip-path: inset(0 0 0 0); }
}
.laser-wipe { position: fixed; inset: 0; z-index: 90; pointer-events: none; overflow: hidden; contain: strict; }
/* Unrevealed side: flat dark veil that slides off with the beam */
.laser-veil {
  position: absolute; inset: 0;
  background: linear-gradient(90deg, var(--col-gunmetal), var(--col-black));
  will-change: transform;
  animation: laser-veil var(--laser-dur) var(--laser-ease) var(--laser-delay) both;
}
@keyframes laser-veil {
  from { transform: translateX(0); }
  to { transform: translateX(100%); }
}
/* Carriage: everything that rides the beam */
.laser-carriage {
  position: absolute; top: 0; bottom: 0; left: 0; width: 0;
  will-change: transform;
  animation: laser-travel var(--laser-dur) var(--laser-ease) var(--laser-delay) both;
}
@keyframes laser-travel {
  from { transform: translateX(0); }
  to { transform: translateX(100vw); }
}
/* Scorch: warm gold trail on the freshly cut side */
.laser-scorch {
  position: absolute; top: 0; bottom: 0; right: 0; width: 140px;
  background: linear-gradient(90deg, transparent 0%, rgb(var(--bv-primary-rgb) / 0.10) 55%, rgb(var(--bv-accent-rgb) / 0.32) 96%, transparent 100%);
  animation: laser-fade var(--laser-dur) linear var(--laser-delay) both;
}
/* Bloom: soft gold glow around the cut (static gradient, opacity-only animation) */
.laser-bloom {
  position: absolute; top: 0; bottom: 0; left: -90px; width: 180px;
  background: radial-gradient(ellipse 50% 60% at 50% 50%, rgb(var(--bv-accent-rgb) / 0.32) 0%, rgb(var(--bv-primary-rgb) / 0.12) 45%, transparent 75%);
  animation: laser-fade var(--laser-dur) linear var(--laser-delay) both;
}
/* Beam: ivory core → signal-gold sheath */
.laser-beam {
  position: absolute; top: 0; bottom: 0; left: -2px; width: 3px;
  background: linear-gradient(180deg, transparent 0%, var(--col-ivory) 6%, var(--bv-highlight) 50%, var(--col-ivory) 94%, transparent 100%);
  box-shadow: 0 0 0 1px rgb(var(--bv-accent-rgb) / 0.95), 0 0 10px 3px rgb(var(--bv-accent-rgb) / 0.75), 0 0 36px 10px rgb(var(--bv-primary-rgb) / 0.4);
  transform-origin: 50% 50%;
  animation: laser-ignite var(--laser-dur) linear var(--laser-delay) both;
}
@keyframes laser-ignite {
  0% { transform: scaleY(0.02) scaleX(3); opacity: 0; }
  7% { transform: scaleY(1) scaleX(2); opacity: 1; }
  14% { transform: scaleY(1) scaleX(1); }
  88% { transform: scaleY(1) scaleX(1); opacity: 1; }
  100% { transform: scaleY(1) scaleX(0.3); opacity: 0; }
}
@keyframes laser-fade {
  0% { opacity: 0; } 10%, 82% { opacity: 1; } 100% { opacity: 0; }
}
/* Sparks: hard-edged gold streaks thrown back off the cut */
.laser-spark {
  position: absolute; left: 0; width: 8px; height: 2px;
  background: linear-gradient(90deg, transparent, var(--col-yellow-hot) 40%, var(--col-ivory));
  opacity: 0;
  animation: laser-spark 340ms cubic-bezier(0.2, 0.6, 0.4, 1) both;
}
@keyframes laser-spark {
  0% { opacity: 1; transform: translate(0, 0) rotate(var(--a)); }
  100% { opacity: 0; transform: translate(var(--dx), var(--dy)) rotate(var(--a)) scaleX(0.4); }
}
/* Ignition flash at the entry edge */
.laser-flash {
  position: absolute; top: 0; bottom: 0; left: 0; width: 40%;
  background: radial-gradient(ellipse 60% 70% at 0% 50%, rgb(var(--bv-text-strong-rgb) / 0.22), rgb(var(--bv-accent-rgb) / 0.12) 45%, transparent 75%);
  animation: laser-flash 240ms ease-out var(--laser-delay) both;
}
@keyframes laser-flash { 0% { opacity: 0; } 25% { opacity: 1; } 100% { opacity: 0; } }
/* Reverse sweep (back in nav order, or swipe finger-left): mirror the whole overlay; reveal cuts from the right */
.laser-wipe.is-reverse { transform: scaleX(-1); }
.page-reveal.is-reverse { animation-name: laser-reveal-rev; }
@keyframes laser-reveal-rev {
  from { clip-path: inset(0 0 0 100%); }
  to { clip-path: inset(0 0 0 0); }
}
@media (prefers-reduced-motion: reduce) {
  .page-reveal, .page-reveal.is-reverse { animation: none; }
  .laser-wipe { display: none; }
}
.section-seam {
  height: 1px;
  background: linear-gradient(90deg, var(--col-yellow) 0 8%, var(--col-steel) 8% 100%);
}
.admin-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  font-family: 'Oswald', sans-serif;
  font-weight: 700;
  font-size: 0.72rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  padding: 0.55rem 0.9rem;
  min-height: 40px;
  color: var(--col-bone);
  background: var(--col-charcoal);
  border: 1px solid var(--col-steel);
  transition: background 150ms, color 150ms;
}
.admin-btn:hover:not(:disabled) { background: var(--col-steel); color: var(--col-ivory); }
.admin-btn:disabled { opacity: 0.4; cursor: not-allowed; }
.admin-btn-on { color: var(--col-yellow); border-color: var(--col-yellow); }
.admin-btn-primary { background: var(--col-yellow); color: var(--col-black); border-color: var(--col-yellow); }
.admin-btn-primary:hover:not(:disabled) { background: var(--col-yellow-hot); color: var(--col-black); }
.admin-btn-danger { color: var(--col-ivory); border-color: var(--col-bone); }
.admin-btn-danger:hover:not(:disabled) { background: var(--col-ivory); color: var(--col-black); }
.admin-btn:active:not(:disabled) { transform: translate(1px, 1px); }

/* Code-built placeholder art for units without owner art */
.dead-signal {
  background:
    linear-gradient(115deg, transparent 0 38%, rgb(var(--bv-primary-rgb) / 0.35) 38% 39%, transparent 39% 100%),
    linear-gradient(115deg, transparent 0 62%, rgb(var(--bv-secondary-rgb) / 0.6) 62% 63%, transparent 63% 100%),
    var(--col-charcoal);
}

/* ===== LAUNCH SEAL (boot gate) ===== */
.launch-gate {
  position: fixed; inset: 0; z-index: 200;
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2.75rem;
  background: radial-gradient(ellipse at 50% 46%, var(--bv-surface) 0%, var(--col-black) 58%, var(--bv-bg) 100%);
  cursor: crosshair; overflow: hidden;
  padding: env(safe-area-inset-top) env(safe-area-inset-right) env(safe-area-inset-bottom) env(safe-area-inset-left);
}
.launch-gate::after {
  content: ''; position: absolute; inset: 0; pointer-events: none; z-index: 3;
  background: radial-gradient(ellipse at center, transparent 55%, rgb(var(--bv-shadow-rgb) / 0.6) 100%);
}
.gate-ticks i { position: absolute; background: var(--col-yellow); opacity: 0.7; z-index: 3; }
.gate-ticks .t, .gate-ticks .b { left: 50%; width: 1px; height: 18px; transform: translateX(-50%); }
.gate-ticks .t { top: calc(18px + env(safe-area-inset-top)); }
.gate-ticks .b { bottom: calc(18px + env(safe-area-inset-bottom)); }
.gate-ticks .l, .gate-ticks .r { top: 50%; height: 1px; width: 18px; transform: translateY(-50%); }
.gate-ticks .l { left: 18px; }
.gate-ticks .r { right: 18px; }
.gate-steam { position: absolute; inset: 0; width: 100%; height: 100%; z-index: 4; pointer-events: none; }
.gate-stage { position: relative; display: grid; place-items: center; z-index: 2; }
.gate-seal {
  position: relative; width: min(64vw, 340px); aspect-ratio: 1;
  background: none; border: 0; padding: 0; cursor: pointer;
  touch-action: manipulation; outline: none; -webkit-tap-highlight-color: transparent; z-index: 2;
}
.gate-seal:active .gate-stack { filter: brightness(1.2); }
.gate-aura {
  position: absolute; inset: -14%; pointer-events: none;
  background: radial-gradient(circle, rgb(var(--bv-primary-rgb) / 0.16) 0%, rgb(var(--bv-primary-rgb) / 0.05) 42%, transparent 68%);
  animation: gate-breathe 4.2s ease-in-out infinite;
}
.gate-ring { position: absolute; inset: -9%; width: 118%; height: 118%; pointer-events: none; animation: gate-orbit 60s linear infinite; }
.gate-focus { position: absolute; inset: -5%; width: 110%; height: 110%; pointer-events: none; opacity: 0; transition: opacity 150ms; }
.gate-seal:focus-visible { outline: none !important; }
.gate-seal:focus-visible .gate-focus { opacity: 1; }
.gate-stack, .gate-half { position: absolute; inset: 0; will-change: transform; }
.gate-half { background: center / contain no-repeat; user-select: none; }
.gate-half.l { clip-path: inset(-4% 50% -4% -4%); }
.gate-half.r { clip-path: inset(-4% -4% -4% 50%); }
.gate-seam {
  position: absolute; top: -6%; bottom: -6%; left: 50%; width: 2px; opacity: 0;
  transform: translateX(-50%) scaleY(0);
  background: linear-gradient(180deg, transparent, var(--col-ivory) 20%, var(--col-yellow-hot) 50%, var(--col-ivory) 80%, transparent);
  box-shadow: 0 0 12px rgb(var(--bv-accent-rgb) / 0.8), 0 0 28px rgb(var(--bv-primary-rgb) / 0.5);
}
.gate-bar {
  position: absolute; top: -40vh; bottom: -40vh; left: 50%; width: 60vw; opacity: 0; z-index: 1;
  transform: translateX(-50%) scaleX(0.004);
  background: linear-gradient(90deg, transparent, rgb(var(--bv-primary-rgb) / 0.5) 30%, rgb(var(--bv-highlight-rgb) / 0.95) 50%, rgb(var(--bv-primary-rgb) / 0.5) 70%, transparent);
  filter: blur(2px); pointer-events: none;
}
.gate-prompt {
  position: relative; z-index: 2; font-size: 0.75rem; letter-spacing: 0.42em; text-transform: uppercase;
  color: var(--col-bone); transition: opacity 200ms;
}
.gate-prompt::after { content: '_'; color: var(--col-yellow); margin-left: 0.15em; animation: gate-blink 1s steps(1) infinite; }
.launch-gate.is-armed .gate-prompt { opacity: 0; }
.gate-flash {
  position: fixed; inset: 0; z-index: 210; opacity: 0; pointer-events: none;
  background: radial-gradient(circle at 50% 50%, var(--bv-highlight) 0%, var(--col-ivory) 45%, var(--bv-text) 100%);
}
.gate-flash.is-out { opacity: 1; animation: gate-flash-out 520ms ease-out forwards; }
@keyframes gate-breathe { 0%,100% { opacity: 0.55; transform: scale(0.97); } 50% { opacity: 1; transform: scale(1.03); } }
@keyframes gate-orbit { to { transform: rotate(360deg); } }
@keyframes gate-blink { 50% { opacity: 0; } }
@keyframes gate-flash-out { from { opacity: 1; } to { opacity: 0; } }
@media (prefers-reduced-motion: reduce) {
  .gate-aura, .gate-ring, .gate-prompt::after { animation: none; }
  .gate-flash.is-out {
    background: radial-gradient(circle, rgb(var(--bv-primary-rgb) / 0.35) 0%, var(--col-black) 70%);
    animation-duration: 400ms;
  }
}

/* Hero framing helpers: gold corner brackets + hairline */
.frame-corners > span { position: absolute; width: var(--fc-size, 18px); height: var(--fc-size, 18px); pointer-events: none; border-color: var(--col-yellow); border-style: solid; border-width: 0; z-index: 3; }
.frame-corners > span.tl { top: -1px; left: -1px; border-top-width: 2px; border-left-width: 2px; }
.frame-corners > span.tr { top: -1px; right: -1px; border-top-width: 2px; border-right-width: 2px; }
.frame-corners > span.bl { bottom: -1px; left: -1px; border-bottom-width: 2px; border-left-width: 2px; }
.frame-corners > span.br { bottom: -1px; right: -1px; border-bottom-width: 2px; border-right-width: 2px; }
.gold-hairline { height: 1px; opacity: 0.6; background: linear-gradient(90deg, transparent, var(--col-yellow) 18%, var(--col-yellow) 82%, transparent); }

/* ===== The Manager haunt — cyan/magenta live ONLY inside these rules ===== */
.haunt {
  position: fixed; left: 0; right: 0; bottom: 0; top: calc(56px + env(safe-area-inset-top, 0px));
  z-index: 120; pointer-events: none; overflow: hidden; contain: strict;
}
.haunt-signal { position: absolute; inset: 0; display: none; }
.haunt[data-mode='signal'] .haunt-signal { display: block; animation: hs-bright 420ms steps(1, end) both; }
.haunt[data-mode='lock'] .haunt-signal { display: block; animation: hs-out 260ms steps(1, end) forwards; }
.haunt-signal i {
  position: absolute; left: -4%; right: -4%; display: block;
  background: linear-gradient(90deg, transparent 0%, rgb(var(--bv-haunt-cyan-rgb) / 0.14) 22%, rgb(var(--bv-text-strong-rgb) / 0.22) 50%, rgb(var(--bv-haunt-magenta-rgb) / 0.14) 78%, transparent 100%);
  backdrop-filter: brightness(1.9) contrast(1.3) saturate(0);
  -webkit-backdrop-filter: brightness(1.9) contrast(1.3) saturate(0);
  animation: hs-tear 140ms steps(1, end) infinite;
}
@keyframes hs-tear { 0% { transform: translateX(var(--tear)); } 50% { transform: translateX(calc(var(--tear) * -0.6)) scaleY(0.6); } }
@keyframes hs-bright {
  0% { backdrop-filter: brightness(1.22) contrast(1.12); -webkit-backdrop-filter: brightness(1.22) contrast(1.12); }
  30% { backdrop-filter: brightness(0.86); -webkit-backdrop-filter: brightness(0.86); }
  55% { backdrop-filter: brightness(1.3) contrast(1.2); -webkit-backdrop-filter: brightness(1.3) contrast(1.2); }
  80% { backdrop-filter: none; -webkit-backdrop-filter: none; }
}
@keyframes hs-out { 0% { opacity: 1; } 50% { opacity: 0.4; } 100% { opacity: 0; } }

.haunt-face {
  position: absolute; left: 50%; top: 46%;
  width: min(74vmin, 600px); aspect-ratio: 1;
  transform: translate(calc(-50% + var(--hf-x, 0vw)), -50%);
}
.hf-shade { position: absolute; inset: -18%; background: radial-gradient(closest-side, rgb(var(--bv-bg-rgb) / 0.82) 0%, rgb(var(--bv-bg-rgb) / 0.55) 55%, transparent 100%); }
.hf-stack {
  position: absolute; inset: 0;
  -webkit-mask-image: radial-gradient(closest-side, rgb(var(--bv-shadow-rgb)) 48%, rgb(var(--bv-shadow-rgb) / 0.55) 72%, transparent 100%);
  mask-image: radial-gradient(closest-side, rgb(var(--bv-shadow-rgb)) 48%, rgb(var(--bv-shadow-rgb) / 0.55) 72%, transparent 100%);
}
.hf-core, .hf-ghost { position: absolute; inset: 0; background-image: var(--hf-img); background-size: cover; background-position: center; }
.hf-core { mix-blend-mode: screen; filter: contrast(1.08) brightness(1.04); }
.hf-ghost { mix-blend-mode: screen; opacity: 0; background-blend-mode: multiply; }
.hf-c { background-color: rgb(var(--bv-haunt-cyan-rgb)); transform: translateX(-7px); }
.hf-m { background-color: rgb(var(--bv-haunt-magenta-rgb)); transform: translateX(7px); }
.hf-scan { position: absolute; inset: 0; background: repeating-linear-gradient(0deg, rgb(var(--bv-shadow-rgb) / 0.42) 0 1px, transparent 1px 3px); }
.hf-roll { position: absolute; left: 0; right: 0; height: 18%; top: -20%; background: linear-gradient(180deg, transparent, rgb(var(--bv-text-strong-rgb) / 0.08), transparent); }

.haunt[data-mode='lock'] .haunt-face { animation: hf-lock var(--lock-ms, 600ms) steps(1, end) both; }
.haunt[data-mode='lock'] .hf-ghost { opacity: 0.55; animation: hf-ghost-lock var(--lock-ms, 600ms) steps(1, end) both; }
.haunt[data-mode='hold'] .hf-core { animation: hf-breathe 2.3s steps(1, end) infinite; }
.haunt[data-mode='hold'] .hf-ghost { animation: hf-twitch 1.7s steps(1, end) infinite; }
.haunt[data-mode='hold'] .hf-roll { animation: hf-roll 2.1s linear infinite; }
.haunt[data-mode='blink'] .haunt-face { animation: hf-blink 150ms steps(1, end) forwards; }
.haunt[data-mode='out'] .haunt-face, .haunt[data-mode='out'] .haunt-term { animation: hf-collapse 400ms cubic-bezier(0.7, 0, 0.84, 0) forwards; }

@keyframes hf-lock {
  0%   { opacity: 0;    clip-path: inset(47% 0 48% 0); transform: translate(calc(-50% + var(--hf-x) - 16px), -50%) scaleY(1.05); }
  12%  { opacity: 0.9;  clip-path: inset(28% 0 54% 0); transform: translate(calc(-50% + var(--hf-x) + 12px), -50%); }
  24%  { opacity: 0.3;  clip-path: inset(8% 0 72% 0);  transform: translate(calc(-50% + var(--hf-x) - 6px), -50%); }
  38%  { opacity: 1;    clip-path: inset(0 0 38% 0);   transform: translate(calc(-50% + var(--hf-x) + 18px), -50%) skewX(-5deg); }
  52%  { opacity: 0.55; clip-path: inset(18% 0 6% 0);  transform: translate(calc(-50% + var(--hf-x) - 4px), -50%); }
  66%  { opacity: 1;    clip-path: inset(0);           transform: translate(calc(-50% + var(--hf-x) + 6px), -50%); }
  82%  { opacity: 0.85; clip-path: inset(0);           transform: translate(calc(-50% + var(--hf-x) - 2px), -50%); }
  100% { opacity: 1;    clip-path: inset(0);           transform: translate(calc(-50% + var(--hf-x)), -50%); }
}
@keyframes hf-ghost-lock { 0% { opacity: 0.7; } 40% { opacity: 0.45; } 70% { opacity: 0.25; } 100% { opacity: 0; } }
@keyframes hf-breathe { 0% { opacity: 1; } 22% { opacity: 0.86; } 30% { opacity: 0.97; } 61% { opacity: 0.82; } 66% { opacity: 1; } }
@keyframes hf-twitch { 0%, 100% { opacity: 0; } 46% { opacity: 0.5; } 49% { opacity: 0; } 83% { opacity: 0.32; } 85% { opacity: 0; } }
@keyframes hf-roll { from { top: -20%; } to { top: 104%; } }
@keyframes hf-blink {
  0%   { opacity: 0.7; transform: translate(calc(-50% + var(--hf-x) + 12px), -50%); clip-path: inset(0); }
  50%  { opacity: 0.35; transform: translate(calc(-50% + var(--hf-x) - 9px), -50%); clip-path: inset(38% 0 30% 0); }
  100% { opacity: 0; clip-path: inset(50% 0 50% 0); }
}
@keyframes hf-collapse {
  0%   { opacity: 1; filter: none; }
  45%  { opacity: 1; filter: brightness(2.6); transform: translate(calc(-50% + var(--hf-x)), -50%) scale(1.03, 0.012); }
  100% { opacity: 0; filter: brightness(4); transform: translate(calc(-50% + var(--hf-x)), -50%) scale(0, 0.006); }
}

.haunt-term {
  position: absolute; left: 50%; bottom: max(14%, 72px); transform: translateX(-50%);
  white-space: nowrap; color: var(--col-ivory);
  font-size: clamp(1.05rem, 3.4vw, 2.1rem); letter-spacing: 0.24em; text-transform: uppercase;
  text-shadow: -2px 0 rgb(var(--bv-haunt-cyan-rgb) / 0.7), 2px 0 rgb(var(--bv-haunt-magenta-rgb) / 0.7), 0 0 14px rgb(var(--bv-text-strong-rgb) / 0.35);
}
.haunt[data-mode='out'] .haunt-term { animation-name: hf-collapse-term; }
@keyframes hf-collapse-term {
  45%  { opacity: 1; filter: brightness(2.4); transform: translateX(-50%) scale(1.04, 0.05); }
  100% { opacity: 0; transform: translateX(-50%) scale(0, 0.02); }
}
.haunt-cursor { display: inline-block; width: 0.6em; height: 1em; margin-left: 0.2em; vertical-align: -0.12em; background: var(--col-ivory); animation: hf-cursor 0.9s steps(1, end) infinite; }
@keyframes hf-cursor { 50% { opacity: 0; } }

/* Corrupted nav tab: visually scrambled, unclickable, out of tab order — restored by the haunt in 5–8s */
.nav-link[data-corrupt] {
  pointer-events: none; color: var(--col-bone) !important; opacity: 0.95 !important;
  text-shadow: -1.5px 0 rgb(var(--bv-haunt-cyan-rgb) / 0.8), 1.5px 0 rgb(var(--bv-haunt-magenta-rgb) / 0.8);
  animation: hf-tab-jit 0.8s steps(1, end) infinite;
}
.nav-link[data-corrupt]::before {
  content: ''; position: absolute; inset: 4px 0; pointer-events: none; opacity: 0;
  background: var(--hf-tab) center 32% / cover no-repeat; mix-blend-mode: screen;
  animation: hf-tab-face 5s steps(1, end) forwards;
}
.nav-link[data-corrupt='front'] { --hf-tab: url(/assets/manager-front.jpg); }
.nav-link[data-corrupt='profile'] { --hf-tab: url(/assets/manager-profile.jpg); }
@keyframes hf-tab-jit { 0% { transform: none; } 30% { transform: translateX(1.5px); } 36% { transform: translateX(-1px) skewX(-6deg); } 70% { transform: none; } 92% { transform: translateX(-2px); } }
@keyframes hf-tab-face { 0% { opacity: 0; } 12% { opacity: 0.75; } 16% { opacity: 0.2; } 20% { opacity: 0.85; } 34% { opacity: 0; } 71% { opacity: 0.5; } 74% { opacity: 0; } }

/* Glitch bursts: inverted data blocks + displaced face slices + one-frame contrast jolt */
.haunt-burst { position: absolute; inset: 0; z-index: 2; animation: hb-flick 90ms steps(1, end) infinite; }
.haunt-burst i { position: absolute; display: block; mix-blend-mode: difference; background: rgb(var(--bv-text-strong-rgb) / 0.85); }
.haunt-burst i[data-k='1'] { background: rgb(var(--bv-haunt-cyan-rgb) / 0.55); mix-blend-mode: screen; }
.haunt-burst i[data-k='2'] { background: rgb(var(--bv-haunt-magenta-rgb) / 0.5); mix-blend-mode: screen; }
.haunt-burst.is-jolt { backdrop-filter: contrast(1.6) brightness(1.15) hue-rotate(8deg); -webkit-backdrop-filter: contrast(1.6) brightness(1.15) hue-rotate(8deg); }
@keyframes hb-flick { 0% { transform: none; opacity: 1; } 40% { transform: translateX(-6px); opacity: 0.7; } 70% { transform: translateX(4px); opacity: 1; } }
.hf-slice { position: absolute; inset: 0; background-image: var(--hf-img); background-size: cover; background-position: center; mix-blend-mode: screen; filter: brightness(1.3) saturate(1.4); }

/* Reduced motion: one quiet static appearance, no tear, no flicker, no stepping */
.haunt-rm .haunt-face, .haunt-rm .hf-core, .haunt-rm .hf-ghost, .haunt-rm .hf-roll, .haunt-rm .haunt-term { animation: none !important; }
.haunt-rm .hf-core { opacity: 0.6; }
.haunt-rm .hf-ghost, .haunt-rm .hf-roll, .haunt-rm .haunt-cursor, .haunt-rm .haunt-burst, .haunt-rm .hf-slice { display: none; }
@media (prefers-reduced-motion: reduce) {
  .nav-link[data-corrupt] { animation: none; }
  .nav-link[data-corrupt]::before { display: none; }
}

/* ── Operator hub: turnable seal ── */
.seal-disc { width: min(78vw, 340px); aspect-ratio: 1; cursor: grab; filter: drop-shadow(0 18px 30px rgb(var(--bv-shadow-rgb) / 0.6)); transition: filter 400ms ease; }
.seal-disc.is-dragging { cursor: grabbing; }
.seal-face { position: absolute; inset: 0; background: url(/assets/seal-all-seeing-eye.webp) center / contain no-repeat; transition: transform 500ms cubic-bezier(0.2,0.8,0.2,1); will-change: transform; }
.seal-disc.is-dragging .seal-face { transition: none; }
.seal-disc.is-dormant { cursor: not-allowed; filter: grayscale(1) brightness(0.45) drop-shadow(0 18px 30px rgb(var(--bv-shadow-rgb) / 0.6)); }
.seal-disc.is-unsealed { filter: drop-shadow(0 0 22px rgb(var(--bv-primary-rgb) / 0.45)) drop-shadow(0 18px 30px rgb(var(--bv-shadow-rgb) / 0.6)); }
.seal-notch { position: absolute; top: -14px; left: 50%; width: 2px; height: 12px; transform: translateX(-50%); background: var(--col-yellow); box-shadow: 0 0 8px rgb(var(--bv-primary-rgb) / 0.6); }

/* Screen-tear fault message */
.seal-tear { position: fixed; inset: 0; z-index: 10000; display: flex; align-items: center; justify-content: center; cursor: pointer; overflow: hidden; }
.seal-tear__veil { position: absolute; inset: 0; background: rgb(var(--bv-shadow-rgb) / 0.92); animation: tear-veil 4.2s ease forwards; }
.seal-tear__band { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; animation: tear-shift 900ms steps(9, end) both; }
.tear-panel { text-align: center; padding: 24px; max-width: 92vw; }
.seal-tear__scan { position: absolute; inset: 0; pointer-events: none; background: repeating-linear-gradient(0deg, rgb(var(--bv-text-strong-rgb) / 0.05) 0 1px, transparent 1px 3px); animation: tear-scan 1.2s linear infinite; }
.seal-tear__hint { position: absolute; bottom: max(24px, env(safe-area-inset-bottom)); left: 0; right: 0; text-align: center; color: var(--col-bone); opacity: 0.7; }
@keyframes tear-shift {
  0% { transform: translateX(calc(var(--dx) * 3)); opacity: 0; filter: brightness(2); }
  20% { transform: translateX(calc(var(--dx) * -1.6)); opacity: 1; }
  45% { transform: translateX(var(--dx)); }
  70% { transform: translateX(calc(var(--dx) * -0.4)); filter: brightness(1.2); }
  100% { transform: translateX(0); opacity: 1; filter: none; }
}
@keyframes tear-veil { 0% { background: rgb(var(--bv-text-strong-rgb) / 0.85); } 6% { background: rgb(var(--bv-shadow-rgb) / 0.92); } 100% { background: rgb(var(--bv-shadow-rgb) / 0.92); } }
@keyframes tear-scan { from { background-position: 0 0; } to { background-position: 0 30px; } }

/* Day Zero flair badge */
.op-flair { display: inline-flex; align-items: center; gap: 8px; padding: 6px 10px; border: 1px solid var(--col-yellow); background: linear-gradient(90deg, rgb(var(--bv-primary-rgb) / 0.16), rgb(var(--bv-primary-rgb) / 0.02)); color: var(--col-yellow); box-shadow: 0 0 14px rgb(var(--bv-primary-rgb) / 0.18); }

/* Terminal preferences */
html.bv-no-scan .grain::after, html.bv-no-scan body::after { display: none !important; }
html.bv-no-scan .bv-field { background-image: none !important; }
html.bv-reduce *, html.bv-reduce *::before, html.bv-reduce *::after { animation-duration: 0.001ms !important; animation-iteration-count: 1 !important; transition-duration: 0.001ms !important; }
html.bv-reduce .seal-tear__band, html.bv-reduce .seal-tear__scan, html.bv-reduce .seal-tear__veil { animation: none !important; }
@media (prefers-reduced-motion: reduce) {
  .seal-tear__band, .seal-tear__scan, .seal-tear__veil { animation: none; }
  .seal-face { transition: none; }
}

/* ── Admin console (banner tokens only) ── */
.admin-shell { min-height: 100vh; background: var(--bv-gradient-banner); background-attachment: fixed; color: var(--bv-text); padding-bottom: 96px; }
.admin-header { position: sticky; top: 0; z-index: 40; background: rgb(var(--bv-surface-rgb) / 0.96); border-bottom: 1px solid var(--bv-border); backdrop-filter: blur(8px); -webkit-backdrop-filter: blur(8px); }
.admin-nav { display: flex; flex-direction: column; gap: 2px; }
.admin-tab { min-height: 44px; width: 100%; padding: 10px 14px; text-align: left; font-family: 'Oswald', sans-serif; font-weight: 700; font-size: 12px; letter-spacing: 0.2em; text-transform: uppercase; color: var(--bv-text-muted); background: transparent; border: 0; border-left: 2px solid transparent; cursor: pointer; transition: background 160ms ease, color 160ms ease, border-color 160ms ease; }
.admin-tab:hover, .admin-tab:focus-visible { background: var(--bv-surface-2); color: var(--bv-text-strong); }
.admin-tab.is-active { background: var(--bv-surface-2); color: var(--bv-text-strong); border-left-color: var(--bv-primary); }
.admin-label { display: block; margin-bottom: 6px; font-family: 'Oswald', sans-serif; font-weight: 700; font-size: 11px; letter-spacing: 0.22em; text-transform: uppercase; color: var(--bv-text); }
.admin-hint { margin-top: 6px; font-family: 'IBM Plex Mono', monospace; font-size: 10px; line-height: 1.5; color: var(--bv-text-muted); }
.admin-preview { position: relative; border: 1px solid var(--bv-border); overflow: hidden; background: var(--bv-bg); }
.admin-swatch { width: 44px; height: 44px; padding: 2px; border: 1px solid var(--bv-border); background: transparent; cursor: pointer; flex-shrink: 0; }
.admin-publish { position: fixed; left: 0; right: 0; bottom: 0; z-index: 45; background: rgb(var(--bv-surface-rgb) / 0.97); border-top: 1px solid var(--bv-border); backdrop-filter: blur(8px); -webkit-backdrop-filter: blur(8px); padding-bottom: env(safe-area-inset-bottom); }
@media (max-width: 767px) { .admin-nav { flex-direction: row; overflow-x: auto; } .admin-tab { width: auto; white-space: nowrap; border-left: 0; border-bottom: 2px solid transparent; } .admin-tab.is-active { border-bottom-color: var(--bv-primary); } }

/* ── Page hero animation ── */
@keyframes bv-hero-rise { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: none; } }
@keyframes bv-hero-fade { from { opacity: 0; } to { opacity: 1; } }
@keyframes bv-hero-settle { from { transform: scale(1.06); } to { transform: scale(1); } }
.bv-hero-anim .bv-hero-rise { animation: bv-hero-rise 700ms cubic-bezier(0.2, 0.7, 0.2, 1) both; }
.bv-hero-anim .bv-hero-rise:nth-child(2) { animation-delay: 120ms; }
.bv-hero-anim .bv-hero-rise:nth-child(3) { animation-delay: 240ms; }
.bv-hero-anim .bv-hero-art { animation: bv-hero-fade 900ms ease-out both; }
.bv-hero-anim .bv-hero-bg { animation: bv-hero-settle 2.4s cubic-bezier(0.2, 0.7, 0.2, 1) both; }
html.bv-reduce .bv-hero-anim .bv-hero-rise, html.bv-reduce .bv-hero-anim .bv-hero-art, html.bv-reduce .bv-hero-anim .bv-hero-bg { animation: none !important; }
@media (prefers-reduced-motion: reduce) {
  .bv-hero-anim .bv-hero-rise, .bv-hero-anim .bv-hero-art, .bv-hero-anim .bv-hero-bg { animation: none; }
  .admin-tab { transition: none; }
}

/* ── Stage 1 hero gate: jammed cog → gold beam split → draggable halves (app/components/hero-gate.tsx) ──
   Gold is reserved for the beam and its glow; the cog, sparks and steam stay steel/bone. */
.bv-gate { position: relative; width: 100%; overflow: hidden; }
.bv-gate-behind {
  position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
  background: var(--bv-gradient-panel);
}
.bv-gate-gallery {
  min-height: 44px; min-width: 44px; padding: 0.4em 0.8em;
  font-size: clamp(2rem, 7vw, 5.5rem); letter-spacing: 0.06em; line-height: 1;
  color: var(--bv-text-muted); opacity: 0.35; background: transparent; border: 0; cursor: pointer;
  transition: opacity 400ms ease, color 200ms ease, letter-spacing 300ms ease;
}
.bv-gate-behind.is-revealed .bv-gate-gallery { opacity: 1; color: var(--bv-text-strong); }
.bv-gate-gallery:hover, .bv-gate-gallery:focus-visible { letter-spacing: 0.1em; }
.bv-gate-gallery:focus-visible { outline: 2px solid var(--bv-text); outline-offset: 4px; }

.bv-gate-half {
  position: absolute; inset: 0; touch-action: pan-y; user-select: none; -webkit-user-select: none;
  transition: transform 560ms cubic-bezier(0.34, 1.45, 0.5, 1);
  will-change: transform;
}
.bv-gate-half--left { clip-path: inset(0 50% 0 0); }
.bv-gate-half--right { clip-path: inset(0 0 0 50%); }
.bv-gate.is-split .bv-gate-half:not(.is-open) { cursor: grab; }
.bv-gate-half.is-dragging { transition: none; cursor: grabbing; }
.bv-gate-half.is-open { transition: transform 620ms cubic-bezier(0.2, 0.7, 0.2, 1); pointer-events: none; }
.bv-gate-half:focus-visible { outline: none; }
.bv-gate-half:focus-visible .bv-gate-edge { opacity: 1; width: 6px; }
.bv-gate-edge {
  position: absolute; top: 0; bottom: 0; width: 3px; opacity: 0; pointer-events: none;
  background: linear-gradient(180deg, transparent, rgb(var(--bv-accent-rgb) / 0.7) 20%, rgb(var(--bv-highlight-rgb) / 0.8) 50%, rgb(var(--bv-accent-rgb) / 0.7) 80%, transparent);
  box-shadow: 0 0 14px rgb(var(--bv-accent-rgb) / 0.55);
  transition: opacity 500ms ease 200ms, width 200ms ease;
}
.bv-gate-half--left .bv-gate-edge { left: calc(50% - 3px); }
.bv-gate-half--right .bv-gate-edge { left: 50%; }
.bv-gate.is-split .bv-gate-edge { opacity: 0.6; }

.bv-gate-beam {
  position: absolute; top: 0; bottom: 0; left: 50%; width: 4px; transform: translateX(-50%);
  pointer-events: none; z-index: 3;
  background: linear-gradient(180deg, var(--bv-highlight), var(--bv-accent) 45%, var(--bv-primary) 100%);
  box-shadow: 0 0 10px rgb(var(--bv-accent-rgb) / 0.9), 0 0 34px rgb(var(--bv-accent-rgb) / 0.55), 0 0 90px rgb(var(--bv-primary-rgb) / 0.35);
  clip-path: inset(0 -120px 100% -120px);
  animation: bv-beam-crack var(--beam-ms, 900ms) cubic-bezier(0.7, 0, 0.3, 1) forwards;
}
.bv-gate.is-split .bv-gate-beam { animation: bv-beam-fade 1400ms ease-out forwards; }
@keyframes bv-beam-crack {
  0% { clip-path: inset(0 -120px 100% -120px); filter: brightness(1.6); }
  18% { clip-path: inset(0 -120px 78% -120px); }
  26% { clip-path: inset(0 -120px 74% -120px); }
  48% { clip-path: inset(0 -120px 38% -120px); }
  56% { clip-path: inset(0 -120px 33% -120px); }
  80% { clip-path: inset(0 -120px 0 -120px); filter: brightness(1.9); }
  100% { clip-path: inset(0 -120px 0 -120px); filter: brightness(1.2); }
}
@keyframes bv-beam-fade {
  0% { clip-path: inset(0 -120px 0 -120px); opacity: 1; }
  100% { clip-path: inset(0 -120px 0 -120px); opacity: 0; }
}

/* Jammed cog — sits just left of the banner's "GREY." lettering */
.bv-cog {
  position: absolute; left: 4.4%; top: 47%; z-index: 4;
  width: clamp(26px, 3.6vw, 64px); aspect-ratio: 1; transform: translate(-50%, -50%);
  padding: 0; border: 0; background: transparent; cursor: pointer; -webkit-tap-highlight-color: transparent;
  transition: opacity 500ms ease 600ms;
}
.bv-cog::before { content: ''; position: absolute; left: 50%; top: 50%; width: max(100%, 44px); height: max(100%, 44px); transform: translate(-50%, -50%); }
.bv-cog:focus-visible { outline: 2px solid var(--bv-text); outline-offset: 4px; border-radius: 50%; }
.bv-cog.is-freed { opacity: 0; pointer-events: none; cursor: default; }
.bv-cog-turn { position: absolute; inset: 0; display: block; transition: transform 200ms cubic-bezier(0.3, 1.8, 0.5, 1); }
.bv-cog-body { position: absolute; inset: 0; display: block; animation: bv-cog-jam 2.8s steps(1, end) infinite; }
.bv-cog-body.is-kicked { animation: bv-cog-shudder 420ms linear, bv-cog-jam 2.8s steps(1, end) 420ms infinite; }
.bv-cog-body svg { width: 100%; height: 100%; display: block; filter: drop-shadow(0 2px 3px rgb(var(--bv-shadow-rgb) / 0.8)); }
.bv-cog-metal { fill: var(--bv-secondary); stroke: var(--bv-text-muted); stroke-width: 2.5; }
.bv-cog-ring { fill: none; stroke: var(--bv-surface-3); stroke-width: 4; }
.bv-cog-scratch { stroke: rgb(var(--bv-text-strong-rgb) / 0.55); stroke-width: 2; stroke-linecap: round; }
.bv-cog:hover .bv-cog-metal { stroke: var(--bv-text); }
@keyframes bv-cog-jam {
  0%, 68% { transform: rotate(0deg); }
  70% { transform: rotate(2.2deg) translateX(0.5px); }
  72% { transform: rotate(-1.4deg); }
  74% { transform: rotate(1deg); }
  76%, 100% { transform: rotate(0deg); }
}
@keyframes bv-cog-shudder {
  0% { transform: rotate(0) translate(0, 0); }
  15% { transform: rotate(-4deg) translate(-1px, 1px); }
  30% { transform: rotate(3deg) translate(1px, -1px); }
  45% { transform: rotate(-2deg) translate(-1px, 0); }
  60% { transform: rotate(1.5deg) translate(1px, 1px); }
  80% { transform: rotate(-0.6deg); }
  100% { transform: rotate(0) translate(0, 0); }
}
.bv-cog-fx { position: absolute; inset: 0; pointer-events: none; }
.bv-cog-spark {
  position: absolute; left: 62%; top: 30%; width: 2px; height: 2px; border-radius: 50%; opacity: 0;
  background: var(--bv-highlight); box-shadow: 0 0 4px rgb(var(--bv-text-strong-rgb) / 0.9);
  animation: bv-cog-spark 3s ease-out infinite;
}
@keyframes bv-cog-spark {
  0%, 64% { opacity: 0; transform: translate(0, 0) scale(1); }
  66% { opacity: min(1, var(--cog-fx)); }
  78% { opacity: 0; transform: translate(var(--sx), var(--sy)) scale(0.4); }
  100% { opacity: 0; transform: translate(var(--sx), var(--sy)) scale(0.4); }
}
.bv-cog-steam {
  position: absolute; left: 30%; top: 10%; width: 60%; height: 60%; border-radius: 50%; opacity: 0;
  background: radial-gradient(circle, rgb(var(--bv-text-rgb) / 0.55), transparent 70%);
  filter: blur(4px); animation: bv-cog-steam 5.5s ease-out infinite;
}
.bv-cog-steam--2 { left: 10%; animation-delay: 2.7s; animation-duration: 6.4s; }
@keyframes bv-cog-steam {
  0% { opacity: 0; transform: translate(0, 0) scale(0.5); }
  15% { opacity: calc(0.28 * var(--cog-fx)); }
  100% { opacity: 0; transform: translate(6px, -130%) scale(1.8); }
}
@media (prefers-reduced-motion: reduce) {
  .bv-cog-body, .bv-cog-body.is-kicked, .bv-cog-spark, .bv-cog-steam { animation: none; }
  .bv-cog-turn { transition: none; }
  .bv-gate-beam { animation: none; clip-path: none; opacity: 0.8; }
  .bv-gate.is-split .bv-gate-beam { animation: none; opacity: 0; }
  .bv-gate-half, .bv-gate-half.is-open { transition-duration: 1ms; }
}

/* ── Stage 2: hero art gallery (app/components/hero-gallery.tsx) + EXIT slam ── */
.bv-gal { position: absolute; inset: 0; overflow: hidden; background: var(--bv-gradient-panel); }
.bv-gal-viewport { position: absolute; inset: 0; overflow: hidden; touch-action: pan-y; cursor: grab; user-select: none; -webkit-user-select: none; }
.bv-gal-viewport.is-dragging { cursor: grabbing; }
.bv-gal-track { position: absolute; inset: 0; display: flex; transition: transform 420ms cubic-bezier(0.2, 0.7, 0.2, 1); will-change: transform; }
.bv-gal-viewport.is-dragging .bv-gal-track { transition: none; }
.bv-gal-slide { position: relative; flex: none; width: 100%; height: 100%; overflow: hidden; }
.bv-gal-backdrop { object-fit: cover; filter: blur(24px) brightness(0.35) saturate(0.8); transform: scale(1.1); pointer-events: none; }
.bv-gal-img { object-fit: contain; pointer-events: none; }
.bv-gal-arrow {
  position: absolute; top: 50%; z-index: 2; transform: translateY(-50%);
  width: 44px; height: 44px; display: flex; align-items: center; justify-content: center;
  font-family: 'Oswald', sans-serif; font-size: 1.1rem; color: var(--bv-text-strong);
  background: rgb(var(--bv-shadow-rgb) / 0.55); border: 1px solid rgb(var(--bv-text-rgb) / 0.25);
  cursor: pointer; transition: background 150ms, border-color 150ms, opacity 150ms;
}
.bv-gal-arrow--prev { left: clamp(8px, 2vw, 24px); }
.bv-gal-arrow--next { right: clamp(8px, 2vw, 24px); }
.bv-gal-arrow:hover:not(:disabled) { background: rgb(var(--bv-shadow-rgb) / 0.8); border-color: var(--bv-text); }
.bv-gal-arrow:disabled { opacity: 0.25; cursor: default; }
.bv-gal-arrow:focus-visible, .bv-gal-exit:focus-visible { outline: 2px solid var(--bv-text); outline-offset: 2px; }
.bv-gal-hud { position: absolute; inset: 0; z-index: 3; pointer-events: none; }
.bv-gal-pos {
  position: absolute; left: 50%; bottom: clamp(8px, 2vw, 20px); transform: translateX(-50%);
  display: flex; align-items: center; gap: 0.6rem; padding: 0.3rem 0.6rem;
  font-size: 0.68rem; letter-spacing: 0.16em; color: var(--bv-text-strong);
  background: rgb(var(--bv-shadow-rgb) / 0.55);
}
.bv-gal-bar { position: relative; display: block; width: clamp(40px, 8vw, 96px); height: 2px; background: rgb(var(--bv-text-rgb) / 0.25); }
.bv-gal-bar i { position: absolute; left: 0; top: 0; bottom: 0; background: var(--bv-text-strong); transition: width 300ms ease; }
.bv-gal-exit {
  position: absolute; top: clamp(8px, 2vw, 20px); right: clamp(8px, 2vw, 20px); pointer-events: auto;
  min-height: 44px; min-width: 44px; padding: 0.5rem 0.9rem;
  font-weight: 700; font-size: 0.72rem; letter-spacing: 0.18em; text-transform: uppercase;
  color: var(--bv-text-strong); background: rgb(var(--bv-shadow-rgb) / 0.7);
  border: 1px solid rgb(var(--bv-text-rgb) / 0.4); cursor: pointer; transition: background 150ms, color 150ms;
}
.bv-gal-exit:hover:not(:disabled) { background: var(--bv-text-strong); color: var(--bv-bg); }
.bv-gal-exit:active:not(:disabled) { transform: translate(1px, 1px); }
.bv-gal-empty { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 0.5rem; padding: 1rem; text-align: center; }
.bv-gal-kicker { font-size: 0.68rem; letter-spacing: 0.22em; color: var(--bv-text-muted); }
.bv-gal-title { font-size: clamp(1.6rem, 5vw, 4rem); line-height: 1; letter-spacing: 0.04em; color: var(--bv-text-strong); }
.bv-gal-sub { font-size: 0.78rem; color: var(--bv-text); }

/* Slam: halves accelerate in (ease-in), then the frame shakes and the seam throws a gold flash + sparks */
.bv-gate.is-slamming .bv-gate-half { transition-timing-function: cubic-bezier(0.55, 0, 0.9, 0.35); pointer-events: none; }
.bv-gate.is-impact .bv-gate-half { animation: bv-gate-shake 420ms linear; }
@keyframes bv-gate-shake {
  0% { translate: 0 0; } 12% { translate: -5px 2px; } 26% { translate: 4px -2px; } 40% { translate: -3px 1px; }
  56% { translate: 2px -1px; } 72% { translate: -1px 0; } 100% { translate: 0 0; }
}
.bv-gate-slam { position: absolute; top: 0; bottom: 0; left: 50%; width: 0; z-index: 3; pointer-events: none; }
.bv-gate-slam::before {
  content: ''; position: absolute; top: 0; bottom: 0; left: -3px; width: 6px;
  background: linear-gradient(180deg, transparent, var(--bv-highlight) 30%, var(--bv-accent) 70%, transparent);
  box-shadow: 0 0 18px rgb(var(--bv-accent-rgb) / 0.95), 0 0 60px rgb(var(--bv-accent-rgb) / 0.5);
  animation: bv-slam-flash var(--slam-ms, 420ms) ease-out forwards;
}
.bv-gate-slam i {
  position: absolute; left: -2px; width: 4px; height: 2px; border-radius: 1px;
  background: var(--bv-highlight); box-shadow: 0 0 6px rgb(var(--bv-text-strong-rgb) / 0.9);
  animation: bv-slam-spark var(--slam-ms, 420ms) ease-out forwards;
}
@keyframes bv-slam-flash { 0% { opacity: 1; transform: scaleX(2.4); } 100% { opacity: 0; transform: scaleX(1); } }
@keyframes bv-slam-spark {
  0% { opacity: 1; transform: translate(0, 0) scale(1.2); }
  100% { opacity: 0; transform: translate(calc(var(--sx) * 2.4), calc(var(--sy) * 2.4)) scale(0.3); }
}
@media (prefers-reduced-motion: reduce) {
  .bv-gal-track, .bv-gal-bar i { transition: none; }
  .bv-gate.is-impact .bv-gate-half, .bv-gate-slam::before, .bv-gate-slam i { animation: none; }
  .bv-gate-slam { display: none; }
}

/* Admin GALLERY tab (app/admin/gallery-editor.tsx) */
.admin-drop {
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 0.5rem;
  min-height: 180px; padding: 1.5rem; text-align: center; cursor: pointer;
  background: var(--col-black); border: 1px dashed var(--col-steel); color: var(--col-bone);
  transition: border-color 150ms, background 150ms;
}
.admin-drop.is-over { border-color: var(--col-yellow); background: var(--col-charcoal); }
.admin-thumb { position: relative; background: var(--col-black); border: 1px solid var(--col-steel); }

'use client'

import { memo } from 'react'
import { useHud } from './hud-context'
import { signatureFor, paletteFor } from './overlay-signatures'

interface EdgeBloomProps {
  tabId: string
  blueMode?: boolean
}

// Viewport-level colour. This is the housing of the optic — it wraps the whole
// screen, gutters included, and is the first thing the eye reads on every page.
//
// Two layers, deliberately separated:
//   FIELD  (z-2)  — soft colour bleeding inward. Sits BEHIND all content so it
//                   never muddies the nav or the reading copy.
//   EDGES  (z-46) — hot filaments, corner plates, studs. Sits ABOVE everything
//                   so the colour stays crisp on the glass.
function EdgeBloomInner({ tabId, blueMode = false }: EdgeBloomProps) {
  const hud = useHud()
  const power = hud.power
  const gain = hud.gain
  const hue = hud.hue
  const mode = hud.mode

  const sig = signatureFor(tabId)
  const palette = paletteFor(blueMode)

  const topC = palette[sig.top]
  const bottomC = palette[sig.bottom]
  const leftC = palette[sig.left]
  const rightC = palette[sig.right]

  const bloom = power ? 0.66 + gain * 0.34 : 0.14
  const hueShift = Math.round((hue - 0.5) * 44)
  const filter = hueShift !== 0 ? `hue-rotate(${hueShift}deg)` : undefined

  const depth = sig.depth
  const sideDepth = Math.round(depth * 0.7)
  const arm = sig.bracket

  // Clamp against the viewport so a deep signature does not swallow a phone screen.
  const capH = `min(${depth}px, 20vh)`
  const sideW = `min(${sideDepth}px, 15vw)`

  // MODE stays live out here: DECAY breaks the hot edge into dashes,
  // PARTITION drops registration studs at mid-span.
  const dash = mode === 'decay'
  const edgeH = (c: string) =>
    dash ? `repeating-linear-gradient(to right, ${c} 0 18px, transparent 18px 32px)` : c
  const edgeV = (c: string) =>
    dash ? `repeating-linear-gradient(to bottom, ${c} 0 18px, transparent 18px 32px)` : c

  return (
    <>
      {/* ---------- FIELD: colour bleeding in from every edge, behind content ---------- */}
      <div
        className="absolute inset-0 pointer-events-none z-[2] overflow-hidden"
        style={filter ? { filter } : undefined}
        aria-hidden="true"
      >
        <div
          className="absolute top-0 left-0 right-0"
          style={{ height: capH, background: `linear-gradient(to bottom, ${topC}A0, ${topC}30 34%, transparent)`, opacity: bloom }}
        />
        <div
          className="absolute bottom-0 left-0 right-0"
          style={{ height: capH, background: `linear-gradient(to top, ${bottomC}A0, ${bottomC}30 34%, transparent)`, opacity: bloom }}
        />
        <div
          className="absolute top-0 bottom-0 left-0"
          style={{ width: sideW, background: `linear-gradient(to right, ${leftC}9A, ${leftC}2C 38%, transparent)`, opacity: bloom }}
        />
        <div
          className="absolute top-0 bottom-0 right-0"
          style={{ width: sideW, background: `linear-gradient(to left, ${rightC}9A, ${rightC}2C 38%, transparent)`, opacity: bloom }}
        />

        {/* corner pools — where two edge colours meet and mix */}
        <div
          className="absolute top-0 left-0"
          style={{ width: sideW, height: capH, background: `radial-gradient(ellipse at top left, ${leftC}55, transparent 72%)`, opacity: bloom }}
        />
        <div
          className="absolute top-0 right-0"
          style={{ width: sideW, height: capH, background: `radial-gradient(ellipse at top right, ${rightC}55, transparent 72%)`, opacity: bloom }}
        />
        <div
          className="absolute bottom-0 left-0"
          style={{ width: sideW, height: capH, background: `radial-gradient(ellipse at bottom left, ${leftC}4A, transparent 72%)`, opacity: bloom }}
        />
        <div
          className="absolute bottom-0 right-0"
          style={{ width: sideW, height: capH, background: `radial-gradient(ellipse at bottom right, ${rightC}4A, transparent 72%)`, opacity: bloom }}
        />
      </div>

      {/* ---------- EDGES: hot filament on the glass, above everything ---------- */}
      <div
        className="absolute inset-0 pointer-events-none z-[46] overflow-hidden"
        style={filter ? { filter } : undefined}
        aria-hidden="true"
      >
        <div className="absolute top-0 left-0 right-0" style={{ height: 4, background: edgeH(topC), opacity: bloom, boxShadow: `0 0 28px 3px ${topC}` }} />
        <div className="absolute bottom-0 left-0 right-0" style={{ height: 4, background: edgeH(bottomC), opacity: bloom, boxShadow: `0 0 28px 3px ${bottomC}` }} />
        <div className="absolute top-0 bottom-0 left-0" style={{ width: 4, background: edgeV(leftC), opacity: bloom * 0.94, boxShadow: `0 0 28px 3px ${leftC}` }} />
        <div className="absolute top-0 bottom-0 right-0" style={{ width: 4, background: edgeV(rightC), opacity: bloom * 0.94, boxShadow: `0 0 28px 3px ${rightC}` }} />

        {/* secondary rail — a hairline running parallel, inset. Reads as housing depth. */}
        <div className="absolute left-0 right-0" style={{ top: 10, height: 1, background: topC, opacity: bloom * 0.45 }} />
        <div className="absolute left-0 right-0" style={{ bottom: 10, height: 1, background: bottomC, opacity: bloom * 0.45 }} />
        <div className="absolute top-0 bottom-0" style={{ left: 10, width: 1, background: leftC, opacity: bloom * 0.38 }} />
        <div className="absolute top-0 bottom-0" style={{ right: 10, width: 1, background: rightC, opacity: bloom * 0.38 }} />

        {/* corner plates — arm length varies per screen */}
        <div className="absolute top-0 left-0" style={{ opacity: bloom }}>
          <div style={{ width: arm * 4, height: 6, background: topC, boxShadow: `0 0 14px ${topC}` }} />
          <div style={{ width: 6, height: arm * 4, background: leftC, boxShadow: `0 0 14px ${leftC}` }} />
        </div>
        <div className="absolute top-0 right-0 flex flex-col items-end" style={{ opacity: bloom }}>
          <div style={{ width: arm * 4, height: 6, background: topC, boxShadow: `0 0 14px ${topC}` }} />
          <div style={{ width: 6, height: arm * 4, background: rightC, boxShadow: `0 0 14px ${rightC}` }} />
        </div>
        <div className="absolute bottom-0 left-0 flex flex-col justify-end" style={{ opacity: bloom }}>
          <div style={{ width: 6, height: arm * 4, background: leftC, boxShadow: `0 0 14px ${leftC}` }} />
          <div style={{ width: arm * 4, height: 6, background: bottomC, boxShadow: `0 0 14px ${bottomC}` }} />
        </div>
        <div className="absolute bottom-0 right-0 flex flex-col items-end justify-end" style={{ opacity: bloom }}>
          <div style={{ width: 6, height: arm * 4, background: rightC, boxShadow: `0 0 14px ${rightC}` }} />
          <div style={{ width: arm * 4, height: 6, background: bottomC, boxShadow: `0 0 14px ${bottomC}` }} />
        </div>

        {/* mid-span studs — only in PARTITION */}
        {mode === 'partition' && (
          <>
            <div className="absolute top-0 left-1/2 -translate-x-1/2" style={{ width: 46, height: 6, background: topC, opacity: bloom, boxShadow: `0 0 14px ${topC}` }} />
            <div className="absolute bottom-0 left-1/2 -translate-x-1/2" style={{ width: 46, height: 6, background: bottomC, opacity: bloom, boxShadow: `0 0 14px ${bottomC}` }} />
