import { ChevronRight } from 'lucide-react';
import { audioManager } from '@/app/_lib/audio-manager';

export interface BreadcrumbItem {
  label: string;
  onClick?: () => void;
}

interface Props {
  items: BreadcrumbItem[];
  className?: string;
}

/**
 * Breadcrumb strip — HUB / CLIPBOARD / DAVE  style navigation.
 * Each non-terminal segment with an onClick is a functional back-link.
 */
export default function Breadcrumb({ items, className = '' }: Props) {
  return (
    <nav
      aria-label="Breadcrumb"
      className={`flex items-center gap-1.5 font-terminal text-[10px] tracking-[0.2em] ${className}`}
    >
      {items.map((item, i) => {
        const isLast = i === items.length - 1;
        const clickable = !isLast && !!item.onClick;
        return (
          <span key={i} className="flex items-center gap-1.5">
            {clickable ? (
              <button
                onClick={() => { try { audioManager.playSFX('nav'); } catch {} item.onClick?.(); }}
                className="text-[#CCAA00] hover:text-[#FFD84A] transition-colors focus:outline-none focus-visible:underline"
              >
                {item.label}
              </button>
            ) : (
              <span className={isLast ? 'text-[#c8dc96]' : 'text-[#8a8578]'}>
                {item.label}
              </span>
            )}
            {!isLast && <ChevronRight size={10} className="text-[#5a4830]" />}
          </span>
        );
      })}
    </nav>
  );
}

