'use client';

/**
 * CrtFx — Bucket A overlay FX for the OPS desk rooms.
 *
 * Renders purely on TOP of the existing flat background art (zero new art):
 *  - Per-monitor scanline + flicker glow on the screen clusters
 *  - Holographic overlay: slow pulse glow, wireframe drift
 *  - Whole-room CRT scanline veil whose intensity scales with escalation heat
 *  - Rolling CRT refresh sweep beam
 *  - Manager reflection: slow breathing presence in monitor glass
 *
 * Hydration-safe: all randomised timing runs only inside useEffect; the initial
 * render is fully deterministic (no Math.random / Date.now in markup). Honours
 * prefers-reduced-motion by disabling the loops.
 */

import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';

type OpsRoom = 'ops_centre_1' | 'ops_centre_2';

interface Zone {
  // position as % of frame
  top: string; left: string; width: string; height: string;
  // tint of the screen glow
  tint: string;
  // 'screen' = scanline + flicker glow, 'dead' = occasional single-frame flash
  kind: 'screen' | 'dead';
  // animation phase offset so monitors don't flicker in lockstep
  delay?: number;
}

interface HoloZone {
  top: string; left: string; width: string; height: string;
  tint: string;
}

interface ReflectZone {
  top: string; left: string; width: string; height: string;
  pos: string; // background-position so the face sits right in the glass
}

const ROOM_ZONES: Record<OpsRoom, { monitors: Zone[]; holo: HoloZone; reflect: ReflectZone }> = {
  ops_centre_1: {
    monitors: [
      // green-text terminal cluster (left desk)
      { top: '33%', left: '15%', width: '27%', height: '29%', tint: 'rgba(120,210,120,0.9)', kind: 'screen', delay: 0 },
      // bright cyan cluster (centre-right desk)
      { top: '28%', left: '55%', width: '23%', height: '30%', tint: 'rgba(130,200,225,0.9)', kind: 'screen', delay: 0.8 },
      // dead / powered-off bulky monitors (right foreground)
      { top: '34%', left: '67%', width: '25%', height: '34%', tint: 'rgba(190,200,205,0.8)', kind: 'dead', delay: 1.6 },
    ],
    holo: { top: '8%', left: '42%', width: '24%', height: '32%', tint: 'rgba(120,255,150,0.55)' },
    reflect: { top: '6%', left: '40%', width: '40%', height: '56%', pos: 'center 18%' },
  },
  ops_centre_2: {
    monitors: [
      // dim CRT cluster behind the holo (centre)
      { top: '13%', left: '38%', width: '22%', height: '21%', tint: 'rgba(130,200,225,0.85)', kind: 'screen', delay: 0.4 },
      // dead bank, left foreground
      { top: '12%', left: '0%', width: '20%', height: '34%', tint: 'rgba(190,200,205,0.8)', kind: 'dead', delay: 1.1 },
      // dead bank, right foreground
      { top: '13%', left: '80%', width: '20%', height: '38%', tint: 'rgba(190,200,205,0.8)', kind: 'dead', delay: 2.0 },
    ],
    holo: { top: '5%', left: '28%', width: '50%', height: '47%', tint: 'rgba(210,235,90,0.5)' },
    reflect: { top: '4%', left: '26%', width: '52%', height: '60%', pos: 'center 16%' },
  },
};

// The Manager's face caught in the monitor glass — a reflection, not a portrait.
// screen-blended so only the bright bits (the wet eye, the latex sheen) surface.
const MANAGER_FACE = '/images/manager-latex-closeup.jpg';

export default function CrtFx({ room, level }: { room: OpsRoom; level: number }) {
  const lvl = Math.max(0, Math.min(10, level ?? 0));
  const { monitors, holo, reflect } = ROOM_ZONES[room];

  // The reflection lives constantly but faintly; it surfaces harder with heat
  // and snaps sharper on glitch frames. Baseline is a barely-there smudge.
  const reflectBase = 0.03 + lvl * 0.017; // lvl0 ~0.03 .. lvl10 ~0.20

  // --- reduced motion detection (matches existing project pattern) ---
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    if (typeof window === 'undefined') return;
    const mql = window.matchMedia('(prefers-reduced-motion: reduce)');
    setReduced(mql.matches);
    const onChange = (e: MediaQueryListEvent) => setReduced(e.matches);
    mql.addEventListener?.('change', onChange);
    return () => mql.removeEventListener?.('change', onChange);
  }, []);

  // Heat-scaled scanline veil opacity (degradation grows with escalation)
  const veilOpacity = 0.05 + lvl * 0.016; // 0.05 .. 0.21
  const scanlineSize = 3; // px period

  return (
    <div className="absolute inset-0 pointer-events-none overflow-hidden" aria-hidden="true">
      {/* ============ Per-monitor screen glow + scanlines ============ */}
      {monitors.map((z, i) => (
        <div
          key={`mon-${room}-${i}`}
          className="absolute overflow-hidden"
          style={{ top: z.top, left: z.left, width: z.width, height: z.height, borderRadius: '4px' }}
        >
          {z.kind === 'screen' ? (
            <>
              {/* phosphor glow — gentle flicker */}
              <motion.div
                className="absolute inset-0"
                style={{
                  background: `radial-gradient(ellipse 80% 70% at 50% 45%, ${z.tint} 0%, transparent 72%)`,
                  mixBlendMode: 'screen',
                  filter: 'blur(5px)',
                }}
                animate={reduced ? undefined : { opacity: [0.16, 0.30, 0.12, 0.34, 0.18, 0.26] }}
                transition={{ duration: 2.4, repeat: Infinity, ease: 'linear', delay: z.delay }}
              />
              {/* fine scanlines clipped to the screen */}
              <div
                className="absolute inset-0"
                style={{
                  backgroundImage: `repeating-linear-gradient(0deg, rgba(0,0,0,0.55) 0px, rgba(0,0,0,0.55) 1px, transparent 1px, transparent ${scanlineSize}px)`,
                  mixBlendMode: 'multiply',
                  opacity: 0.4 + lvl * 0.03,
                }}
              />
              {/* slow vertical scroll band — suggests scrolling terminal text */}
              {!reduced && (
                <motion.div
                  className="absolute left-0 right-0"
                  style={{ height: '40%', background: `linear-gradient(180deg, transparent 0%, ${z.tint} 50%, transparent 100%)`, mixBlendMode: 'screen', opacity: 0.12, filter: 'blur(2px)' }}
                  animate={{ top: ['-40%', '100%'] }}
                  transition={{ duration: 5.5 + i, repeat: Infinity, ease: 'linear', delay: z.delay }}
                />
              )}
            </>
          ) : (
            // dead monitor — mostly dark, with a very slow residual phosphor glow
            <motion.div
              className="absolute inset-0"
              style={{ background: `radial-gradient(ellipse 70% 60% at 50% 45%, ${z.tint} 0%, transparent 70%)`, mixBlendMode: 'screen', filter: 'blur(4px)' }}
              animate={reduced ? undefined : { opacity: [0, 0.04, 0.08, 0.03, 0] }}
              transition={{ duration: 8, repeat: Infinity, ease: 'easeInOut', delay: z.delay }}
            />
          )}
        </div>
      ))}

      {/* ============ Holographic overlay — pulse + drift + corruption ============ */}
      <div
        className="absolute overflow-hidden"
        style={{ top: holo.top, left: holo.left, width: holo.width, height: holo.height }}
      >
        {/* pulse glow */}
        <motion.div
