          style={{ background: `radial-gradient(ellipse 70% 70% at 50% 45%, ${holo.tint} 0%, transparent 70%)`, mixBlendMode: 'screen', filter: 'blur(9px)' }}
          animate={reduced ? undefined : { opacity: [0.18, 0.42, 0.22, 0.38, 0.2] }}
          transition={{ duration: 4.2, repeat: Infinity, ease: 'easeInOut' }}
        />
        {/* slow wireframe drift — a faint scanning bar that wanders the holo */}
        {!reduced && (
          <motion.div
            className="absolute inset-0"
            style={{ backgroundImage: `repeating-linear-gradient(0deg, ${holo.tint} 0px, ${holo.tint} 1px, transparent 1px, transparent 6px)`, mixBlendMode: 'screen', opacity: 0.1 }}
            animate={{ y: [0, -4, 2, -3, 0], x: [0, 2, -1, 1, 0] }}
            transition={{ duration: 7, repeat: Infinity, ease: 'easeInOut' }}
          />
        )}

      </div>

      {/* ============ The Manager — caught in the glass ============ */}
      <div
        className="absolute overflow-hidden"
        style={{
          top: reflect.top, left: reflect.left, width: reflect.width, height: reflect.height,
          // feather the edges so it reads as a localised reflection, not a pasted image
          WebkitMaskImage: 'radial-gradient(ellipse 62% 70% at 50% 42%, #000 18%, transparent 74%)',
          maskImage: 'radial-gradient(ellipse 62% 70% at 50% 42%, #000 18%, transparent 74%)',
        }}
      >
        <motion.div
          className="absolute inset-0"
          style={{
            backgroundImage: `url(${MANAGER_FACE})`,
            backgroundSize: 'cover',
            backgroundPosition: reflect.pos,
            // screen blend = only highlights glow through, like light on dark glass
            mixBlendMode: 'screen',
            filter: `blur(${reduced ? 2.4 : 1.8}px) contrast(1.12) brightness(1.18) saturate(0.7)`,
          }}
          animate={reduced
            ? { opacity: reflectBase * 0.8 }
            : {
                // slow breathing presence + gentle drift, like the reflected light shifting
                opacity: [reflectBase * 0.55, reflectBase, reflectBase * 0.7, reflectBase * 1.05, reflectBase * 0.6],
                x: [0, 4, -3, 2, 0],
                y: [0, -2, 3, -1, 0],
                scale: [1, 1.015, 1, 1.01, 1],
              }}
          transition={{ duration: 11, repeat: Infinity, ease: 'easeInOut' }}
        />
      </div>

      {/* ============ Whole-room CRT scanline veil (heat degradation) ============ */}
      <div
        className="absolute inset-0"
        style={{
          backgroundImage: `repeating-linear-gradient(0deg, rgba(0,0,0,0.5) 0px, rgba(0,0,0,0.5) 1px, transparent 1px, transparent ${scanlineSize}px)`,
          mixBlendMode: 'multiply',
          opacity: veilOpacity,
        }}
      />
      {/* faint rolling scanline beam — the CRT refresh sweep */}
      {!reduced && (
        <motion.div
          className="absolute left-0 right-0"
          style={{ height: '18%', background: 'linear-gradient(180deg, transparent 0%, rgba(255,255,255,0.045) 50%, transparent 100%)', mixBlendMode: 'screen' }}
          animate={{ top: ['-18%', '100%'] }}
          transition={{ duration: 6.5, repeat: Infinity, ease: 'linear' }}
        />
      )}

    </div>
  );
}

