import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { MAX_ENERGY, ENERGY_COST } from '@/lib/game-data';
import { isValidId, safeNumber } from '@/lib/api-guards';

// POST: Update recruitment stage / affinity
export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const { npcId, action, value, sessionId } = body ?? {};
    if (!isValidId(npcId) || !action) {
      return NextResponse.json({ error: 'Missing npcId or action' }, { status: 400 });
    }
    const npc = await prisma.nPC.findUnique({ where: { id: npcId } });
    if (!npc) return NextResponse.json({ error: 'NPC not found' }, { status: 404 });

    // Ownership guard: if sessionId provided, verify NPC belongs to that session
    if (sessionId && npc.sessionId !== sessionId) {
      return NextResponse.json({ error: 'NPC does not belong to this session' }, { status: 403 });
    }

    const updateData: Record<string, number | boolean | string> = {};

    switch (action) {
      case 'advance_stage': {
        const session = await prisma.gameSession.findUnique({ where: { id: npc.sessionId } });
        if (session) {
          const energyUsed = session.energyUsed ?? 0;
          const energyLeft = MAX_ENERGY - energyUsed;
          if (energyLeft < ENERGY_COST.recruit_stage) {
            return NextResponse.json({
              error: 'no_energy',
              message: 'Too exhausted to continue the intake. Get some sleep.',
            }, { status: 409 });
          }
          await prisma.gameSession.update({
            where: { id: npc.sessionId },
            data: { energyUsed: { increment: ENERGY_COST.recruit_stage } },
          });
        }
        updateData.recruitStage = Math.min((npc.recruitStage ?? 0) + 1, 3);
        break;
      }
      case 'add_affinity': {
        // Clamp delta to ±30 per call to prevent single-request max-out
        const delta = Math.max(-30, Math.min(30, safeNumber(value, 0)));
        updateData.affinity = Math.max(0, Math.min(100, (npc.affinity ?? 0) + delta));
        break;
      }
      case 'parsing_progress':
        updateData.parsingProgress = Math.min(9, (npc.parsingProgress ?? 0) + 1);
        break;
      case 'recruit':
        updateData.recruited = true;
        updateData.recruitStage = 3;
        updateData.status = 'AVAILABLE';
        break;
      case 'reset':
        updateData.recruitStage = 0;
        updateData.affinity = 0;
        updateData.parsingProgress = 0;
        break;
      default:
        return NextResponse.json({ error: 'Unknown action' }, { status: 400 });
    }

    const updated = await prisma.nPC.update({ where: { id: npcId }, data: updateData });
    return NextResponse.json(updated);
  } catch (err: unknown) {
    console.error('Recruit error:', err);
    return NextResponse.json({ error: 'Failed' }, { status: 500 });
  }
}

