export function GamesArchive({ games, content }: GamesArchiveProps) {
  const list = games ?? []
  const ownerView: View = content.archiveView === 'list' ? 'list' : 'grid'
  const [view, setView] = useState<View>(ownerView)
  const [dossier, setDossier] = useState<number | null>(null)
  const showToggle = isOn(content.showViewToggle)
  const showNumbers = isOn(content.showUnitNumbers)
  const showDesc = isOn(content.showDescriptions)
  const backdrop = BACKDROPS[content.archiveBackdrop] !== undefined ? BACKDROPS[content.archiveBackdrop] : BACKDROPS.console
  // Square/poster art packs two cards per row on phones so the archive stays short
  const compact = content.archiveArt === 'square' || content.archiveArt === 'poster'
  const lockedCount = list.filter((g) => g.locked).length

  // Visitor's last choice wins, but only when the switch is offered
  useEffect(() => {
    if (!showToggle) return
    try {
      const stored = window.localStorage.getItem(VIEW_KEY)
      if (stored === 'grid' || stored === 'list') setView(stored)
    } catch {}
  }, [showToggle])

  const pickView = (next: View) => {
    if (next === view) return
    setView(next)
    haptic('toggle')
    try { window.localStorage.setItem(VIEW_KEY, next) } catch {}
  }

  const activeView = showToggle ? view : ownerView

  return (
    <section id="games" className="relative py-16 md:py-32">
      <div className="absolute inset-0 z-0 overflow-hidden">
        {backdrop && <Image src={backdrop} alt="" fill className="object-cover object-center" sizes="100vw" style={{ opacity: 0.18, filter: 'grayscale(1)' }} />}
        <div
          className="absolute inset-0"
          style={{ background: 'linear-gradient(180deg, var(--col-black) 0%, rgb(var(--bv-bg-rgb) / 0.82) 20%, rgb(var(--bv-bg-rgb) / 0.82) 80%, var(--col-black) 100%)' }}
        />
      </div>

      <div className="relative z-10 max-w-[1280px] mx-auto px-4 md:px-8">
        <div className="mb-10 md:mb-14 grid md:grid-cols-12 gap-6 items-end">
          <div className="md:col-span-8">
            <p className="font-oswald text-[11px] uppercase tracking-[0.35em] mb-3" style={{ color: 'var(--col-yellow)' }}>
