                      style={{
                        backgroundColor: on ? 'var(--col-steel)' : 'transparent',
                        color: on ? 'var(--col-ivory)' : 'var(--col-bone)',
                        border: '1px solid var(--col-steel)',
                      }}
                    >
                      {v === 'grid' ? (
                        <svg width="12" height="12" viewBox="0 0 12 12" aria-hidden="true"><rect x="0" y="0" width="5" height="5" fill="currentColor" /><rect x="7" y="0" width="5" height="5" fill="currentColor" /><rect x="0" y="7" width="5" height="5" fill="currentColor" /><rect x="7" y="7" width="5" height="5" fill="currentColor" /></svg>
                      ) : (
                        <svg width="12" height="12" viewBox="0 0 12 12" aria-hidden="true"><rect x="0" y="0" width="12" height="3" fill="currentColor" /><rect x="0" y="4.5" width="12" height="3" fill="currentColor" /><rect x="0" y="9" width="12" height="3" fill="currentColor" /></svg>
                      )}
                      {v}
