                    <div className="min-w-0 flex-1">
                      <div className="flex flex-wrap items-center gap-2 mb-1">
                        <h3 className="font-anton uppercase tracking-tight leading-none text-xl md:text-2xl" style={{ color: 'var(--col-ivory)' }}>
                          {game.title}
