                        <StatusBadge locked={game.locked} isActive={isActive} small />
                      </div>
                      {game.subtitle ? (
                        <p className="font-ibm text-[11px] uppercase tracking-wider" style={{ color: 'var(--col-bone)' }}>{game.subtitle}</p>
                      ) : null}
                      {showDesc && game.description ? (
                        <p className="hidden md:block font-ibm text-sm mt-1 leading-relaxed line-clamp-2" style={{ color: 'var(--col-bone)', opacity: 0.75 }}>{game.description}</p>
                      ) : null}
                    </div>
                  </div>
                  <div className="flex gap-2 w-full sm:w-auto">
                    <DossierButton game={game} onOpen={() => setDossier(index)} />
                    <UnitAction game={game} content={content} fill="flex-1 sm:flex-none sm:min-w-[200px]" />
                  </div>
                </li>
              )
            })}
          </ol>
        ) : (
          <div className={`grid ${compact ? 'grid-cols-2 gap-3 sm:gap-6' : 'grid-cols-1 gap-5 sm:gap-6'} sm:grid-cols-2 ${LG_COLS[content.archiveColumns] ?? LG_COLS['3']}`}>
            {list.map((game, index) => {
              const isActive = game.status === 'active'
              return (
                <article
                  key={game.id}
                  className="bv-card group relative flex flex-col"
                  style={{ backgroundColor: 'var(--col-gunmetal)', boxShadow: '0 18px 40px rgb(var(--bv-shadow-rgb) / 0.5)' }}
                >
                  <div className={`relative ${ART_ASPECT[content.archiveArt] ?? ART_ASPECT.wide} bg-[var(--col-charcoal)] overflow-hidden`}>
                    <UnitArt game={game} />
                    {showNumbers && (
                      <span className="absolute top-3 left-3 font-ibm text-[10px] uppercase px-2 py-1" style={{ backgroundColor: 'rgb(var(--bv-bg-rgb) / 0.88)', color: 'var(--col-bone)' }}>
                        UNIT-{String(index + 1).padStart(2, '0')}
                      </span>
                    )}
                    <StatusBadge locked={game.locked} isActive={isActive} className="absolute top-3 right-3" />
                  </div>

                  <div className={`flex-1 flex flex-col ${compact ? 'p-3 sm:p-5' : 'p-5 md:p-6'}`}>
                    <h3 className={`font-anton uppercase tracking-tight leading-none ${compact ? 'text-xl sm:text-2xl md:text-3xl' : 'text-2xl md:text-3xl'}`} style={{ color: 'var(--col-ivory)' }}>
                      {game.title}
                    </h3>
                    {game.subtitle ? (
                      <p className="font-ibm text-xs uppercase tracking-wider mt-2" style={{ color: 'var(--col-bone)' }}>{game.subtitle}</p>
                    ) : null}
                    {showDesc && game.description ? (
                      <p className={`font-ibm text-sm mt-3 leading-relaxed ${compact ? 'hidden sm:block' : ''}`} style={{ color: 'var(--col-bone)', opacity: 0.8 }}>{game.description}</p>
                    ) : null}
                    <div className="mt-auto pt-5 flex flex-wrap gap-2">
                      <UnitAction game={game} content={content} fill={compact ? 'w-full sm:w-auto px-3' : undefined} />
                      <DossierButton game={game} onOpen={() => setDossier(index)} fill={compact ? 'w-full sm:w-auto' : undefined} />
                    </div>
                  </div>
                </article>
              )
            })}
          </div>
        )}
      </div>
      {dossier !== null && list[dossier] ? (
        <DossierWindow game={list[dossier]} index={dossier} content={content} onClose={() => setDossier(null)} />
      ) : null}
    </section>
  )
}

'use client'

import { useRef, useCallback, useState, type CSSProperties, type PointerEvent as ReactPointerEvent, type KeyboardEvent as ReactKeyboardEvent } from 'react'

const DETENTS = 20

interface HudDialProps {
  label: string
  value: number
  onChange: (v: number) => void
  onDetent?: () => void
  onLock?: () => void
  color?: string
  size?: number
  detents?: number
  valueText?: string
  readout?: string
}

/** Rotary dial. Drag vertically or horizontally to spin. Sweep is -135deg to +135deg. */
export function HudDial({ label, value, onChange, onDetent, onLock, color = '#B8F026', size = 48, detents = DETENTS, valueText, readout }: HudDialProps) {
  const dragRef = useRef<{ y: number; x: number; start: number } | null>(null)
  const detentRef = useRef(Math.round(value * detents))
  const [active, setActive] = useState(false)

  const angle = -135 + value * 270

  const commit = useCallback((next: number) => {
    const clamped = Math.min(1, Math.max(0, next))
    const d = Math.round(clamped * detents)
    if (d !== detentRef.current) {
      detentRef.current = d
      onDetent?.()
    }
    onChange?.(clamped)
  }, [onChange, onDetent, detents])

  const handleDown = useCallback((e: ReactPointerEvent<HTMLDivElement>) => {
    if (e.button !== 0) return
    e.stopPropagation()
    e.currentTarget.focus({ preventScroll: true })
    e.currentTarget.setPointerCapture?.(e.pointerId)
    detentRef.current = Math.round(value * detents)
    dragRef.current = { y: e.clientY, x: e.clientX, start: value }
    setActive(true)
    onLock?.()
  }, [value, onLock, detents])

  const handleMove = useCallback((e: ReactPointerEvent<HTMLDivElement>) => {
    const d = dragRef.current
    if (!d) return
    e.preventDefault()
    const dy = d.y - e.clientY
    const dx = e.clientX - d.x
    const delta = (dy + dx) / 160
    commit(d.start + delta)
  }, [commit])

  const handleUp = useCallback((e: ReactPointerEvent<HTMLDivElement>) => {
    if (!dragRef.current) return
    dragRef.current = null
    setActive(false)
    e.currentTarget.releasePointerCapture?.(e.pointerId)
  }, [])

  const handleKey = useCallback((e: ReactKeyboardEvent<HTMLDivElement>) => {
    const step = e.shiftKey ? Math.min(1, 2 / detents) : 1 / detents
    if (e.key === 'ArrowUp' || e.key === 'ArrowRight') {
      e.preventDefault()
      e.stopPropagation()
      commit(value + step)
    } else if (e.key === 'ArrowDown' || e.key === 'ArrowLeft') {
      e.preventDefault()
      e.stopPropagation()
      commit(value - step)
    } else if (e.key === 'Home') {
      e.preventDefault()
      e.stopPropagation()
      commit(0)
    } else if (e.key === 'End') {
      e.preventDefault()
      e.stopPropagation()
      commit(1)
    }
  }, [commit, value, detents])

  return (
    <div className="hud-dial-group flex flex-col items-center gap-1 select-none" style={{ '--control-color': color } as CSSProperties}>
      <div
        data-hud-control="dial"
        role="slider"
        tabIndex={0}
        aria-label={label}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={Math.round(value * 100)}
        aria-valuetext={valueText || `${Math.round(value * 100)} percent`}
        title={`${label} · drag up/right to increase · arrow keys to fine-tune`}
        onPointerDown={handleDown}
        onPointerMove={handleMove}
        onPointerUp={handleUp}
        onPointerCancel={handleUp}
        onKeyDown={handleKey}
        className="hud-dial relative cursor-grab active:cursor-grabbing touch-none"
        data-active={active}
        style={{ width: Math.max(44, size), height: Math.max(44, size) }}
      >
        {/* Detent ring */}
        <svg width="100%" height="100%" viewBox="0 0 100 100" className="absolute inset-0" aria-hidden="true">
          {Array.from({ length: detents + 1 }).map((_, i) => {
            const a = (-135 + (i / detents) * 270) * (Math.PI / 180)
            const x1 = 50 + Math.sin(a) * 44
            const y1 = 50 - Math.cos(a) * 44
            const x2 = 50 + Math.sin(a) * 49
            const y2 = 50 - Math.cos(a) * 49
            const lit = i / detents <= value + 0.001
            return (
              <line
                key={i}
                x1={x1}
                y1={y1}
                x2={x2}
                y2={y2}
                stroke={lit ? color : '#E8E4D9'}
                strokeWidth={2}
                opacity={lit ? 0.85 : 0.18}
              />
            )
          })}
          <circle cx="50" cy="50" r="37" fill="#080907" stroke="#3e4535" strokeWidth={3} />
          <circle cx="50" cy="50" r="33" fill="#252a21" stroke={color} strokeWidth={1.2} opacity={active ? 1 : 0.85} />
          <circle cx="50" cy="50" r="29" fill="#141810" stroke="#707762" strokeWidth={4} strokeDasharray="1 3" />
          <circle cx="50" cy="50" r="23" fill="#1e2419" stroke="#373e2e" strokeWidth={1} />
          <path d="M30 46 A21 21 0 0 1 67 36" fill="none" stroke="#d5ddbd" strokeOpacity=".2" />
        </svg>
        {/* Pointer needle */}
        <div
          className="absolute inset-0 flex items-start justify-center"
          style={{ transform: `rotate(${angle}deg)`, transition: active ? 'none' : 'transform 120ms linear' }}
        >
          <div style={{ width: 2, height: size * 0.3, marginTop: size * 0.1, background: color, opacity: 0.95 }} />
        </div>
      </div>
      <span className="hud-control-label" style={{ color }}>{label}</span>
      <span className="hud-dial-readout" aria-hidden="true">{readout ?? String(Math.round(value * 100)).padStart(3, '0')}</span>
    </div>
  )
}

