interface HudFaderProps {
  label: string
  value: number
  onChange: (v: number) => void
  onDetent?: () => void
  color?: string
  orientation?: 'vertical' | 'horizontal'
  length?: number
}

/** Ticked fader. Drag the cap along the track. */
export function HudFader({ label, value, onChange, onDetent, color = '#B8F026', orientation = 'vertical', length = 76 }: HudFaderProps) {
  const trackRef = useRef<HTMLDivElement>(null)
  const detentRef = useRef(Math.round(value * DETENTS))
  const [active, setActive] = useState(false)
  const vertical = orientation === 'vertical'

  const commit = useCallback((next: number) => {
    const clamped = Math.min(1, Math.max(0, next))
    const d = Math.round(clamped * DETENTS)
    if (d !== detentRef.current) {
      detentRef.current = d
      onDetent?.()
    }
    onChange?.(clamped)
  }, [onChange, onDetent])

  const fromPointer = useCallback((clientX: number, clientY: number) => {
    const el = trackRef.current
    if (!el) return
    const r = el.getBoundingClientRect()
    const ratio = vertical
      ? 1 - (clientY - r.top) / Math.max(1, r.height)
      : (clientX - r.left) / Math.max(1, r.width)
    commit(ratio)
  }, [commit, vertical])

  const handleDown = useCallback((e: ReactPointerEvent<HTMLDivElement>) => {
    if (e.button !== 0) return
    e.stopPropagation()
    e.currentTarget.focus({ preventScroll: true })
    e.currentTarget.setPointerCapture?.(e.pointerId)
    setActive(true)
    fromPointer(e.clientX, e.clientY)
  }, [fromPointer])

  const handleMove = useCallback((e: ReactPointerEvent<HTMLDivElement>) => {
    if (!active) return
    e.preventDefault()
    fromPointer(e.clientX, e.clientY)
  }, [active, fromPointer])

  const handleUp = useCallback((e: ReactPointerEvent<HTMLDivElement>) => {
    setActive(false)
    e.currentTarget.releasePointerCapture?.(e.pointerId)
  }, [])

  const handleKey = useCallback((e: ReactKeyboardEvent<HTMLDivElement>) => {
    const step = 1 / DETENTS
    if (e.key === 'ArrowUp' || e.key === 'ArrowRight') {
      e.preventDefault()
      e.stopPropagation()
      commit(value + step)
    } else if (e.key === 'ArrowDown' || e.key === 'ArrowLeft') {
      e.preventDefault()
      e.stopPropagation()
      commit(value - step)
    }
  }, [commit, value])

  const capPos = `${value * 100}%`

  return (
    <div className={`flex ${vertical ? 'flex-col' : 'flex-row'} items-center gap-1.5 select-none`}>
      <div
        ref={trackRef}
        data-hud-control="fader"
        role="slider"
        tabIndex={0}
        aria-label={label}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={Math.round(value * 100)}
        aria-orientation={orientation}
        onPointerDown={handleDown}
        onPointerMove={handleMove}
        onPointerUp={handleUp}
        onPointerCancel={handleUp}
        onKeyDown={handleKey}
        className="hud-fader relative cursor-pointer touch-none"
        style={vertical ? { width: 44, height: length } : { width: length, height: 44 }}
      >
        {/* Track */}
        <div
          className="absolute"
          style={vertical
            ? { left: '50%', top: 0, bottom: 0, width: 1, marginLeft: -0.5, background: '#E8E4D9', opacity: 0.18 }
            : { top: '50%', left: 0, right: 0, height: 1, marginTop: -0.5, background: '#E8E4D9', opacity: 0.18 }}
        />
        {/* Filled portion */}
        <div
          className="absolute"
          style={vertical
            ? { left: '50%', bottom: 0, height: capPos, width: 1, marginLeft: -0.5, background: color, opacity: 0.7 }
            : { top: '50%', left: 0, width: capPos, height: 1, marginTop: -0.5, background: color, opacity: 0.7 }}
        />
        {/* Ticks */}
        {Array.from({ length: 5 }).map((_, i) => {
          const p = `${(i / 4) * 100}%`
          return (
            <div
              key={i}
              className="absolute"
              style={vertical
                ? { top: p, left: 3, width: 5, height: 1, background: '#E8E4D9', opacity: 0.22 }
                : { left: p, top: 3, height: 5, width: 1, background: '#E8E4D9', opacity: 0.22 }}
            />
          )
        })}
        {/* Cap */}
        <div
          className="absolute"
          style={vertical
            ? { bottom: capPos, left: 10, width: 24, height: 12, marginBottom: -6, background: active ? '#303827' : '#1c2116', border: `1px solid ${color}`, boxShadow: '0 2px 0 #000' }
            : { left: capPos, top: 10, height: 24, width: 12, marginLeft: -6, background: active ? '#303827' : '#1c2116', border: `1px solid ${color}`, boxShadow: '0 2px 0 #000' }}
        />
      </div>
      <span className="text-[8px] uppercase tracking-wide-label opacity-70" style={{ color }}>
        {label}
      </span>
    </div>
  )
}

