/**
 * LockedSilhouette — distinct redacted "surveillance subject" art for un-recruited
 * crew on the Crew Board. Instead of every locked recruit reading as the same
 * blurred mystery blob, each NPC gets a unique body silhouette + observable
 * descriptor (what a watcher would note without knowing the name). Intriguing,
 * never identifying.
 *
 * Pure SVG — zero new assets, negligible JS.
 */

export type SilhouetteKey = 'dave' | 'tamara' | 'sid' | 'mikey';

interface SubjectProfile {
  /** Distinct body shape drawn into the frame */
  shape: SilhouetteKey;
  /** Observable traits a watcher would jot — hints, never the name */
  descriptors: string[];
}

export const SUBJECT_PROFILES: Record<string, SubjectProfile> = {
  dave: {
    shape: 'dave',
    descriptors: ['MALE · 30s', 'HUGS THE WALLS', 'COUNTS UNDER BREATH'],
  },
  tamara: {
    shape: 'tamara',
    descriptors: ['FEMALE · RESTLESS', 'NEVER STOPS MOVING', 'WATCHES THE LIGHTS'],
  },
  sid: {
    shape: 'sid',
    descriptors: ['MALE · BROAD BUILD', 'CLENCHED FISTS', 'RUNS HOT'],
  },
  mikey: {
    shape: 'mikey',
    descriptors: ['ELDERLY · GREY', 'LONG COAT', 'TALKS TO NO ONE'],
  },
};

function SilhouetteShape({ shape, color }: { shape: SilhouetteKey; color: string }) {
  // Each path is a distinct head + shoulders profile so the four read apart
  // at a glance even when fully blacked out.
  const common = {
    fill: color,
    fillOpacity: 0.9,
  };
  switch (shape) {
    case 'dave':
      // Narrow, bowed head; thin sloped shoulders pressed inward
      return (
        <g {...common}>
          <ellipse cx="50" cy="33" rx="11" ry="13" />
          <path d="M30 100 C32 70 40 58 50 58 C60 58 68 70 70 100 Z" />
        </g>
      );
    case 'tamara':
      // Upright tense head with a tied-back bump; lean, alert shoulders
      return (
        <g {...common}>
          <circle cx="50" cy="31" r="12" />
          <path d="M58 24 q9 -3 8 7 q-1 6 -7 5 Z" />
          <path d="M28 100 C29 66 41 55 50 55 C59 55 71 66 72 100 Z" />
        </g>
      );
    case 'sid':
      // Heavy square jaw, very broad bulky shoulders
      return (
        <g {...common}>
          <rect x="37" y="18" width="26" height="28" rx="8" />
          <path d="M18 100 C20 62 36 52 50 52 C64 52 80 62 82 100 Z" />
        </g>
      );
    case 'mikey':
      // Brimmed hat + hunched, raised-collar long coat
      return (
        <g {...common}>
          <ellipse cx="50" cy="24" rx="20" ry="5" />
          <rect x="40" y="14" width="20" height="12" rx="4" />
          <circle cx="50" cy="36" r="10" />
          <path d="M26 100 C24 70 38 54 50 56 C62 54 76 70 74 100 Z" />
          <path d="M40 58 L36 78 M60 58 L64 78" stroke={color} strokeWidth="2" strokeOpacity="0.5" fill="none" />
        </g>
      );
    default:
      return null;
  }
}

/** Small roster-thumbnail variant: just the silhouette, no descriptors. */
export function LockedSilhouetteThumb({
  npcKey,
  color = '#b87a96',
}: {
  npcKey: string;
  color?: string;
}) {
  const profile = SUBJECT_PROFILES[npcKey?.toLowerCase()];
  if (!profile) {
    return (
      <span className="font-bmf-mono text-base" style={{ color: 'rgba(255,75,193,0.5)' }}>?</span>
    );
  }
  return (
    <svg viewBox="0 0 100 100" className="w-full h-full" aria-hidden="true" preserveAspectRatio="xMidYMax meet">
      <SilhouetteShape shape={profile.shape} color={color} />
    </svg>
  );
}

/** Large dossier-panel variant: framed silhouette + surveillance descriptors. */
export function LockedSilhouette({
  npcKey,
  color = '#b87a96',
}: {
  npcKey: string;
  color?: string;
}) {
  const profile = SUBJECT_PROFILES[npcKey?.toLowerCase()];
  return (
    <div className="absolute inset-0 flex flex-col items-center justify-end">
      {/* Silhouette fills the frame */}
      <svg
        viewBox="0 0 100 100"
        className="absolute inset-0 w-full h-full"
        aria-hidden="true"
        preserveAspectRatio="xMidYMax meet"
        style={{ filter: `drop-shadow(0 0 8px ${color}40)` }}
      >
        {profile ? (
          <SilhouetteShape shape={profile.shape} color="#0d0d0c" />
        ) : null}
      </svg>
      {/* Tinted edge so the black shape reads against the dark frame */}
      <div
        className="absolute inset-0 pointer-events-none"
        style={{ background: `radial-gradient(circle at 50% 38%, ${color}14, transparent 62%)` }}
      />
      {/* Observable descriptors stacked at the base */}
      {profile && (
        <div className="relative z-10 w-full px-2 pb-2 flex flex-col items-center gap-0.5">
          {profile.descriptors.map((d) => (
            <span
              key={d}
              className="font-bmf-mono text-[7px] tracking-[0.15em] px-1.5 py-0.5"
              style={{
                color: `${color}cc`,
                background: 'rgba(8,8,7,0.7)',
                border: `1px solid ${color}25`,
              }}
            >
              {d}
            </span>
          ))}
        </div>
      )}
    </div>
  );
}

// ============================================================
// DUMPSTER-DIVING — MISSION BRIEF PANEL  (v0.5.4)
// ============================================================
// Step 3 of the planning wizard — the "job sheet". Shows the final
// review screen the player confirms before dispatch:
//   - Location detail
//   - Crew manifest
//   - Resource cost vs. inventory (with shortfall flagged)
//   - Success estimate (UI-only marketing number)
//   - Heat warning if applicable
// All numbers come from pure functions in lib/dumpster-planning.ts.
// ============================================================

'use client';

import { motion } from 'framer-motion';
import { CheckCircle2, AlertTriangle, Flame, Users, Coins, PackageOpen } from 'lucide-react';
import type { DumpsterLocation } from '@/lib/dumpster-locations';
import type { ResourceKey } from '@/lib/game-data';
import {
  estimateSuccess,
  type CrewMember,
  type PlanningValidation,
  type ResourceCheck,
} from '@/lib/dumpster-planning';
import {
  CigaretteIcon,
  AlcoholIcon,
  WeedIcon,
  CrystalIcon,
} from '../icons/resource-icons';
import type { CrewZone } from '@/lib/ui-model';
import { ZONE_HEX } from '@/lib/ui-model';

interface Props {
  location: DumpsterLocation;
  crew: CrewMember[];
  validation: PlanningValidation;
  sessionHeat: number;
  mobilityStat: number;
  /** Zone state per NPC id */
  crewZones?: Record<string, CrewZone>;
}

const RESOURCE_COLOR: Record<ResourceKey, string> = {
  cigarettes: '#8aad7a',
  alcohol:    '#7ab8b8',
  weed:       '#9a86b5',
  crystals:   '#a8687e',
};

const RESOURCE_ICON: Record<ResourceKey, React.ComponentType<any>> = {
  cigarettes: CigaretteIcon,
  alcohol:    AlcoholIcon,
  weed:       WeedIcon,
  crystals:   CrystalIcon,
};

const ZONE_PERF_LABELS: Record<CrewZone, { label: string; effect: string }> = {
  GREEN:  { label: 'OPERATIONAL', effect: 'Standard loot, stable pressure' },
  YELLOW: { label: 'UNRELIABLE', effect: 'May go absent, +0.2 pressure' },
  RED:    { label: 'LIABILITY',   effect: 'Reduced loot, +0.3 pressure' },
};

export default function MissionBriefPanel({
  location,
  crew,
  validation,
  sessionHeat,
  mobilityStat,
  crewZones,
}: Props) {
  const success = estimateSuccess(location, crew, { sessionHeat, mobilityStat });
  const heatWarn = location.baseHeat >= 3 || sessionHeat >= 5;

  // Reward preview — pure read of the location's loot ranges. Server still
  // rolls the real numbers; this is the player-facing "what's in it for me".
  const haulEntries = (Object.keys(location.lootProfile) as ResourceKey[])
    .map((k) => ({ key: k, range: location.lootProfile[k] }))
    .filter((e) => e.range[1] > 0);
  const hasRedCrew = crew.some((m) => (crewZones?.[m.id] ?? 'GREEN') === 'RED');

  return (
    <div className="space-y-3">
      {/* Location */}
      <div
        className="border-l-[3px] border-l-[#B87333] p-3 rounded-[1px]"
        style={{ background: 'rgba(10,10,9,0.82)' }}
      >
        <p className="font-terminal text-[10px] tracking-[0.18em] text-[#B87333]">TARGET SITE</p>
        <h3 className="font-terminal text-base text-[#e8e4d4] mt-0.5">{location.name}</h3>
        <p className="font-typewriter text-[11px] text-[#8a8578] italic">{location.realityName}</p>
      </div>

      {/* Crew manifest */}
      <div
        className="border-l-[3px] border-l-[#c8dc96] p-3 rounded-[1px]"
        style={{ background: 'rgba(10,10,9,0.82)' }}
      >
        <p className="font-terminal text-[10px] tracking-[0.18em] text-[#c8dc96] flex items-center gap-1.5">
          <Users size={11} /> CREW MANIFEST ({crew.length})
        </p>
        {crew.length === 0 ? (
          <p className="font-typewriter text-xs text-[#a8687e] italic mt-1">
            No crew assigned. They’re not going.
          </p>
        ) : (
          <ul className="mt-1.5 space-y-0.5">
            {crew.map((m) => {
              const z = crewZones?.[m.id] ?? 'GREEN';
              return (
                <li
                  key={m.id}
                  className="font-terminal text-xs text-[#e8e4d4] flex items-center justify-between"
                >
                  <span className="flex items-center gap-1.5">
                    <span
                      className="inline-block w-2 h-2 rounded-full flex-shrink-0"
                      style={{ background: ZONE_HEX[z] }}
                    />
                    {m.name}
                  </span>
                  <span className="flex items-center gap-2">
                    {z !== 'GREEN' && (
                      <span
                        className="font-terminal text-[9px] uppercase px-1 rounded-sm"
                        style={{ color: ZONE_HEX[z], border: `1px solid ${ZONE_HEX[z]}44` }}
                      >
                        {ZONE_PERF_LABELS[z].label}
                      </span>
                    )}
                    <span className="font-terminal text-[10px] text-[#8a8578]">
                      M{m.muscle}/B{m.brains}/U{m.unpredictability}
                    </span>
                  </span>
                </li>
              );
            })}
          </ul>
        )}
      </div>

      {/* Resource cost */}
      <div
        className="border-l-[3px] border-l-[#CCAA00] p-3 rounded-[1px]"
        style={{ background: 'rgba(10,10,9,0.82)' }}
      >
        <p className="font-terminal text-[10px] tracking-[0.18em] text-[#CCAA00] flex items-center gap-1.5">
          <Coins size={11} /> DISPATCH COST
        </p>
        {validation.resources.length === 0 ? (
          <p className="font-typewriter text-xs text-[#8a8578] italic mt-1">
            No cost. (You’ll be lucky.)
          </p>
        ) : (
          <ul className="mt-1.5 space-y-1">
            {validation.resources.map((r: ResourceCheck) => {
              const Icon = RESOURCE_ICON[r.resource as ResourceKey];
              const color = RESOURCE_COLOR[r.resource as ResourceKey] ?? '#e8e4d4';
              return (
                <li key={r.resource} className="flex items-center justify-between">
                  <span className="flex items-center gap-1.5 font-terminal text-xs text-[#e8e4d4] uppercase">
                    {Icon && <Icon color={color} size={12} />}
                    {r.resource}
                  </span>
                  <span
                    className="font-terminal text-xs"
                    style={{ color: r.ok ? '#c8dc96' : '#a8687e' }}
                  >
                    {r.required} <span className="text-[#7a7060]">(have {r.have})</span>{' '}
                    {r.ok ? '✓' : '✗'}
                  </span>
                </li>
              );
            })}
          </ul>
        )}
      </div>

      {/* Success estimate */}
      <div
        className="border-l-[3px] p-3 rounded-[1px]"
        style={{
          borderLeftColor: success.label === 'STUPID'
            ? '#a8687e'
            : success.label === 'RISKY'
            ? '#FF8C3A'
            : success.label === 'COIN-FLIP'
            ? '#CCAA00'
            : '#c8dc96',
          background: 'rgba(10,10,9,0.82)',
        }}
      >
        <div className="flex items-end justify-between">
          <div>
            <p className="font-terminal text-[10px] tracking-[0.18em] text-[#B87333]">
              ESTIMATED SUCCESS
            </p>
            <p
              className="font-terminal mt-1"
              style={{
                fontSize: '32px',
                lineHeight: 1,
                color:
                  success.label === 'STUPID'
                    ? '#a8687e'
                    : success.label === 'RISKY'
                    ? '#FF8C3A'
                    : success.label === 'COIN-FLIP'
                    ? '#CCAA00'
                    : '#c8dc96',
              }}
            >
              {success.chancePct}%
            </p>
          </div>
          <div
            className="font-terminal text-xs px-2 py-0.5"
            style={{
              color:
                success.label === 'STUPID'
                  ? '#a8687e'
                  : success.label === 'RISKY'
                  ? '#FF8C3A'
                  : success.label === 'COIN-FLIP'
                  ? '#CCAA00'
                  : '#c8dc96',
              border: `1px solid currentColor`,
              background: 'rgba(0,0,0,0.4)',
            }}
          >
            {success.label}
          </div>
        </div>
        <div className="font-terminal text-[10px] text-[#7a7060] mt-2 grid grid-cols-2 gap-x-3 gap-y-0.5">
          <span>Base: {success.factors.base}</span>
          <span>+Skills: {success.factors.skillBonus}</span>
          <span>+Size: {success.factors.sizeBonus}</span>
          <span>+Mobility: {success.factors.mobilityBonus}</span>
          <span style={{ color: '#FF8C3A' }}>−Heat: {success.factors.heatPenalty}</span>
          <span style={{ color: '#FF8C3A' }}>−CrewHeat: {success.factors.crewHeatPenalty}</span>
        </div>
      </div>

      {/* Projected haul — the reward side of the risk/reward call */}
      <div
        className="border-l-[3px] border-l-[#B87333] p-3 rounded-[1px]"
        style={{ background: 'rgba(10,10,9,0.82)' }}
      >
        <div className="flex items-center justify-between">
          <p className="font-terminal text-[10px] tracking-[0.18em] text-[#B87333] flex items-center gap-1.5">
            <PackageOpen size={11} /> PROJECTED HAUL
          </p>
          <span className="font-terminal text-[9px] text-[#7a7060] uppercase tracking-[0.12em]">
            if extraction holds
          </span>
        </div>
        {haulEntries.length === 0 ? (
          <p className="font-typewriter text-xs text-[#8a8578] italic mt-1">
            Nothing worth the diesel. Scraps only.
          </p>
        ) : (
          <ul className="mt-1.5 grid grid-cols-2 gap-x-3 gap-y-1">
            {haulEntries.map((e) => {
              const Icon = RESOURCE_ICON[e.key];
              const color = RESOURCE_COLOR[e.key];
              const [min, max] = e.range;
              return (
                <li key={e.key} className="flex items-center justify-between">
                  <span className="flex items-center gap-1.5 font-terminal text-xs text-[#e8e4d4] uppercase">
                    {Icon && <Icon color={color} size={12} />}
                    {e.key}
                  </span>
                  <span className="font-terminal text-xs" style={{ color }}>
                    {min === max ? max : `${min}–${max}`}
                  </span>
                </li>
              );
            })}
          </ul>
        )}
        {hasRedCrew && haulEntries.length > 0 && (
          <p className="font-typewriter text-[10px] text-[#FF8C3A] italic mt-2 flex items-start gap-1.5">
            <AlertTriangle size={11} className="flex-shrink-0 mt-0.5" />
            LIABILITY crew on this run — expect the low end. They lose, spill, or pocket the good stuff.
          </p>
        )}
      </div>

      {/* Heat warning */}
      {heatWarn && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          className="border-l-[3px] border-l-[#a8687e] p-2.5 rounded-[1px] flex items-start gap-2"
          style={{ background: 'rgba(255,20,147,0.04)' }}
        >
          <Flame size={14} className="text-[#a8687e] flex-shrink-0 mt-0.5" />
          <p className="font-typewriter text-[11px] text-[#e8e4d4] italic">
            Heat exposure on this run: <span className="text-[#a8687e] font-terminal">+{location.baseHeat}</span>.
            {sessionHeat >= 5 ? ' You are already attracting attention. Consider laying low.' : ''}
          </p>
        </motion.div>
      )}

      {/* Final go/no-go */}
      <div
        className="p-3 rounded-[1px] flex items-center gap-2.5 border"
        style={{
          borderColor: validation.ok ? '#c8dc96' : '#a8687e',
          background: validation.ok
            ? 'rgba(200,220,150,0.06)'
            : 'rgba(255,20,147,0.04)',
        }}
      >
        {validation.ok ? (
          <CheckCircle2 size={18} className="text-[#c8dc96] flex-shrink-0" />
        ) : (
          <AlertTriangle size={18} className="text-[#a8687e] flex-shrink-0" />
        )}
        <div className="flex-1 min-w-0">
          {validation.ok ? (
            <p className="font-terminal text-sm text-[#c8dc96]">
              ALL CHECKS GREEN. READY FOR DISPATCH.
            </p>
          ) : (
            <ul className="space-y-0.5">
              {validation.blockingReasons.map((reason, i) => (
                <li
                  key={i}
                  className="font-typewriter text-[11px] text-[#a8687e]"
                >
                  • {reason}
                </li>
              ))}
            </ul>
          )}
        </div>
      </div>
    </div>
  );
}

