function pad(n: number) {
  return String(n).padStart(2, '0')
}

export function ToneGallery() {
  const hud = useHud()
  const hudRef = useRef(hud)
  hudRef.current = hud
  const [emblaRef, emblaApi] = useEmblaCarousel({ loop: true, align: 'start', dragFree: false })
  const [index, setIndex] = useState(0)
  const [zoom, setZoom] = useState(false)
  const [failed, setFailed] = useState<Record<string, boolean>>({})
  const reduce = useReducedMotion()
  useEffect(() => {
    if (!emblaApi) return
    const onSelect = () => {
      const next = emblaApi.selectedScrollSnap()
      setIndex(next)
      hudRef.current.pulse('tick')
      hudRef.current.note('PLATE / ' + pad(next + 1))
    }
    emblaApi.on('select', onSelect)
    return () => { emblaApi.off('select', onSelect) }
  }, [emblaApi])
  const prev = useCallback(() => { emblaApi?.scrollPrev(); hudRef.current.pulse('press') }, [emblaApi])
  const next = useCallback(() => { emblaApi?.scrollNext(); hudRef.current.pulse('press') }, [emblaApi])
  const active = PLATES[index] ?? PLATES[0]
  return <div className="gallery-console" data-hud-control tabIndex={0} aria-roledescription="carousel" aria-label="Concept art gallery" onKeyDown={(e) => {
    if ((e.target as HTMLElement).closest('[role="slider"], [role="dialog"]')) return
    if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') { e.preventDefault(); e.stopPropagation(); if (e.key === 'ArrowLeft') prev(); else next() }
  }}>

    <div className="gallery-bay">
      <motion.div className="gallery-frame" layout={!reduce} style={{ width: '100%', maxWidth: `calc(58dvh * ${active.ratio})`, aspectRatio: active.ratio }} transition={{ type: 'spring', stiffness: 240, damping: 30 }}>
        <div className="absolute inset-0 overflow-hidden cursor-grab active:cursor-grabbing" ref={emblaRef}>
          <div className="flex h-full">{PLATES.map((plate, i) => <div key={plate.src} className="relative flex-[0_0_100%] min-w-0 h-full">
            {failed[plate.src] ? <div className="absolute inset-0 grid place-items-center text-sm text-[#E8E4D9]">Artwork unavailable</div> : <Image src={plate.src} alt={plate.alt} fill draggable={false} priority={i === 0} className="object-contain select-none pointer-events-none" sizes="(max-width: 767px) 85vw, 45vw" onError={() => { console.error(`Gallery artwork unavailable: ${plate.src}`); setFailed((previous) => ({ ...previous, [plate.src]: true })) }} />}
          </div>)}</div>
        </div>
        <button className="gallery-inspect" onClick={() => { setZoom(true); hud.pulse('press'); hud.note('PLATE / INSPECT') }} aria-label="Inspect gallery artwork"><Expand size={15} /><span>INSPECT</span></button>
      </motion.div>
    </div>
    <div className="gallery-transport">
      <button className="gallery-arrow" onClick={prev} aria-label="Previous plate"><ArrowLeft size={18} /></button>
      <div className="gallery-caption"><strong>{active.title}</strong><span>{active.note}</span></div>
      <span className="gallery-count" aria-live="polite">{index + 1} / {PLATES.length}</span>
      <button className="gallery-arrow" onClick={next} aria-label="Next plate"><ArrowRight size={18} /></button>
    </div>
    <label className="gallery-picker">Choose artwork
      <select value={index} onChange={(e) => { emblaApi?.scrollTo(Number(e.target.value)); hud.pulse('press') }} onKeyDown={(e) => e.stopPropagation()}>
        {PLATES.map((plate, i) => <option key={plate.src} value={i}>{pad(i + 1)} · {plate.title}</option>)}
      </select>
    </label>
    <ArtworkViewer src={active.src} alt={active.alt} title={active.title} caption={active.note} open={zoom} onOpenChange={setZoom} />
  </div>
}

