// ========================
// SOUND EFFECTS - Web Audio API based + Real Audio Files
// ========================

// ========================
// MUTE SYSTEM (v0.5.0)
// Pipeline: UI calls setMuted(true) → getAudioContext gated to null
// (stops all WebAudio synth + ambient) + HTMLAudio elements volume→0.
// State persists to localStorage. Subscribers get notified of changes.
// ========================

const MUTE_STORAGE_KEY = 'bumafag_muted_v1';
const VOL_STORAGE_KEY = 'bumafag_volumes_v1';
let muted = false;
const muteSubscribers = new Set<(m: boolean) => void>();

// ========================
// VOLUME CATEGORY SYSTEM (v0.9.1)
// Three independent volume multipliers: master, music, sfx.
// All stored in localStorage. All default to 1.0.
// Every audio output multiplies by master * category.
// ========================
export type VolumeCategory = 'master' | 'music' | 'sfx';
const volumeLevels: Record<VolumeCategory, number> = { master: 1.0, music: 1.0, sfx: 1.0 };
const volumeSubscribers = new Set<(v: Record<VolumeCategory, number>) => void>();

export function loadVolumesFromStorage(): Record<VolumeCategory, number> {
  if (typeof window === 'undefined') return { ...volumeLevels };
  try {
    const raw = window.localStorage.getItem(VOL_STORAGE_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (parsed.master !== undefined) volumeLevels.master = Math.max(0, Math.min(1, parsed.master));
      if (parsed.music !== undefined) volumeLevels.music = Math.max(0, Math.min(1, parsed.music));
      if (parsed.sfx !== undefined) volumeLevels.sfx = Math.max(0, Math.min(1, parsed.sfx));
    }
  } catch { /* ignore */ }
  return { ...volumeLevels };
}

export function getVolume(cat: VolumeCategory): number { return volumeLevels[cat]; }
export function getEffectiveVolume(cat: 'music' | 'sfx'): number {
  return volumeLevels.master * volumeLevels[cat];
}

export function setVolume(cat: VolumeCategory, val: number) {
  volumeLevels[cat] = Math.max(0, Math.min(1, val));
  try {
    if (typeof window !== 'undefined') {
      window.localStorage.setItem(VOL_STORAGE_KEY, JSON.stringify(volumeLevels));
    }
  } catch { /* ignore */ }
  // Re-apply volumes to active audio elements
  applyVolumesToActiveAudio();
  volumeSubscribers.forEach(cb => { try { cb({ ...volumeLevels }); } catch {} });
}

export function subscribeVolumes(cb: (v: Record<VolumeCategory, number>) => void): () => void {
  volumeSubscribers.add(cb);
  return () => { volumeSubscribers.delete(cb); };
}

/** Re-apply volume multipliers to all currently playing HTML audio elements */
function applyVolumesToActiveAudio() {
  if (muted) return; // muted → all zero already
  const m = volumeLevels.master;
  const mus = m * volumeLevels.music;
  const sfx = m * volumeLevels.sfx;
  try { if (menuMusicAudio) menuMusicAudio.volume = (duckCount > 0 ? MUSIC_DUCKED_VOL : MUSIC_NORMAL_VOL) * mus; } catch {}
  try { if (nightAudio) nightAudio.volume = 0.3 * mus; } catch {}
  try { if (introDialogueAudio) introDialogueAudio.volume = 0.75 * sfx; } catch {}
  try { if (menuTransitionSpeechAudio) menuTransitionSpeechAudio.volume = 0.88 * sfx; } catch {}
  try { if (tamaraVoiceAudio) tamaraVoiceAudio.volume = sfx; } catch {}
}

export function loadMutedFromStorage(): boolean {
  if (typeof window === 'undefined') return false;
  try {
    const val = window.localStorage.getItem(MUTE_STORAGE_KEY);
    muted = val === '1';
  } catch { /* ignore */ }
  return muted;
}

export function isMuted(): boolean {
  return muted;
}

export function setMuted(value: boolean) {
  if (muted === value) return;
  muted = value;
  try {
    if (typeof window !== 'undefined') {
      window.localStorage.setItem(MUTE_STORAGE_KEY, value ? '1' : '0');
    }
  } catch { /* ignore */ }
  applyMuteToHTMLAudio();
  if (muted) {
    // Stop all synth loops immediately
    try { stopZippoBurnLoop(); } catch {}
    try { stopAmbientLoop(); } catch {}
    // v0.5.5 — kill the radio static when muting
    try {
      if (radioStaticGain) radioStaticGain.gain.value = 0;
    } catch {}
  } else {
    // Restoring sound — re-apply static fade-in if we're still in radio mode
    try {
      if (radioModeActive && menuAudioContext && radioStaticGain) {
        const now = menuAudioContext.currentTime;
        radioStaticGain.gain.cancelScheduledValues(now);
        radioStaticGain.gain.setValueAtTime(0, now);
        radioStaticGain.gain.linearRampToValueAtTime(0.014, now + 0.6);
      }
    } catch {}
  }
  muteSubscribers.forEach(cb => { try { cb(muted); } catch {} });
}

export function toggleMuted(): boolean {
  setMuted(!muted);
  return muted;
}

export function subscribeMuted(cb: (m: boolean) => void): () => void {
  muteSubscribers.add(cb);
  return () => { muteSubscribers.delete(cb); };
}

/** Apply current mute state to all 5 HTMLAudio tracks. Null-safe. */
function applyMuteToHTMLAudio() {
  if (muted) {
    try { if (menuMusicAudio) menuMusicAudio.volume = 0; } catch {}
    try { if (introDialogueAudio) introDialogueAudio.volume = 0; } catch {}
    try { if (menuTransitionSpeechAudio) menuTransitionSpeechAudio.volume = 0; } catch {}
    try { if (nightAudio) nightAudio.volume = 0; } catch {}
    try { if (tamaraVoiceAudio) tamaraVoiceAudio.volume = 0; } catch {}
  } else {
    // Restore sensible defaults — callers will re-apply ducking
    try { if (menuMusicAudio) menuMusicAudio.volume = duckCount > 0 ? MUSIC_DUCKED_VOL : MUSIC_NORMAL_VOL; } catch {}
    try { if (introDialogueAudio) introDialogueAudio.volume = 1; } catch {}
    try { if (menuTransitionSpeechAudio) menuTransitionSpeechAudio.volume = 1; } catch {}
    try { if (nightAudio) nightAudio.volume = 0.3; } catch {}
    try { if (tamaraVoiceAudio) tamaraVoiceAudio.volume = 1; } catch {}
  }
}

let audioCtx: AudioContext | null = null;

function getAudioContext(): AudioContext | null {
  if (typeof window === 'undefined') return null;
  if (muted) return null; // v0.5.0: gate all WebAudio output when muted
  if (!audioCtx) {
    try {
      audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
    } catch {
      return null;
    }
  }
  return audioCtx;
}

// ========================
// ZIPPO LIGHTER SFX (v0.3.6 — lighter cursor)
// Synthesized via WebAudio. Short, crisp, metallic.
// ========================

/**
 * Zippo SNAP — the characteristic metallic click when the lid flips open.
 * Built from: brief filtered-noise burst + tiny metallic resonance tone.
 * Duration ~60ms.
 */
export function playZippoSnap() {
  const ctx = getAudioContext();
  if (!ctx) return;
  const now = ctx.currentTime;

  // 1) Sharp noise burst for the metallic impact
  const bufferSize = Math.floor(ctx.sampleRate * 0.05); // 50ms
  const noiseBuffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
  const data = noiseBuffer.getChannelData(0);
  for (let i = 0; i < bufferSize; i++) {
    // White noise with quick exponential decay
    const decay = Math.exp(-i / (bufferSize * 0.18));
    data[i] = (Math.random() * 2 - 1) * decay;
  }
  const noise = ctx.createBufferSource();
  noise.buffer = noiseBuffer;
  const noiseFilter = ctx.createBiquadFilter();
  noiseFilter.type = 'bandpass';
  noiseFilter.frequency.value = 4200;
  noiseFilter.Q.value = 3.5;
  const noiseGain = ctx.createGain();
  noiseGain.gain.setValueAtTime(0.35, now);
  noiseGain.gain.exponentialRampToValueAtTime(0.001, now + 0.055);
  noise.connect(noiseFilter).connect(noiseGain).connect(ctx.destination);
  noise.start(now);
  noise.stop(now + 0.06);

  // 2) Metallic resonance — short pitched click
  const osc = ctx.createOscillator();
  osc.type = 'triangle';
  osc.frequency.setValueAtTime(1800, now);
  osc.frequency.exponentialRampToValueAtTime(900, now + 0.04);
  const oscGain = ctx.createGain();
  oscGain.gain.setValueAtTime(0.12, now);
  oscGain.gain.exponentialRampToValueAtTime(0.001, now + 0.045);
  osc.connect(oscGain).connect(ctx.destination);
  osc.start(now);
  osc.stop(now + 0.05);
}

/**
 * Zippo IGNITE — the flame whoosh. Short wind-rush.
 * Built from: low-pass filtered noise with quick swell + decay.
 * Duration ~200ms.
 */
export function playZippoIgnite() {
  const ctx = getAudioContext();
  if (!ctx) return;
  const now = ctx.currentTime;

  const bufferSize = Math.floor(ctx.sampleRate * 0.22);
  const noiseBuffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
  const data = noiseBuffer.getChannelData(0);
  for (let i = 0; i < bufferSize; i++) {
    data[i] = (Math.random() * 2 - 1) * 0.6;
  }
  const noise = ctx.createBufferSource();
  noise.buffer = noiseBuffer;
  // Low-pass filter with slight upward sweep to mimic air intake
  const filter = ctx.createBiquadFilter();
  filter.type = 'lowpass';
  filter.frequency.setValueAtTime(500, now);
  filter.frequency.exponentialRampToValueAtTime(1600, now + 0.06);
  filter.frequency.exponentialRampToValueAtTime(700, now + 0.2);
  filter.Q.value = 0.9;
  const gain = ctx.createGain();
  gain.gain.setValueAtTime(0.0001, now);
  gain.gain.exponentialRampToValueAtTime(0.16, now + 0.04);
  gain.gain.exponentialRampToValueAtTime(0.001, now + 0.2);
  noise.connect(filter).connect(gain).connect(ctx.destination);
  noise.start(now);
  noise.stop(now + 0.22);
}

/**
 * Zippo BURN LOOP — continuous flame/combustion hiss for while-held state.
 * Returns a stop() function. Designed to overlap cleanly with playZippoIgnite()
 * at the start. Low volume, subtle — the flame is breathing, not roaring.
 */
let burnLoopNodes: { osc?: OscillatorNode; noise?: AudioBufferSourceNode; gain?: GainNode; filter?: BiquadFilterNode; lfoGain?: GainNode; lfo?: OscillatorNode } | null = null;

export function startZippoBurnLoop() {
  const ctx = getAudioContext();
  if (!ctx) return;
  if (burnLoopNodes) return; // already running
  const now = ctx.currentTime;

  // Continuous filtered noise for the hiss
  const bufferSize = ctx.sampleRate * 2; // 2s buffer, looped
  const noiseBuffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
  const data = noiseBuffer.getChannelData(0);
  for (let i = 0; i < bufferSize; i++) {
    data[i] = (Math.random() * 2 - 1) * 0.45;
  }
  const noise = ctx.createBufferSource();
  noise.buffer = noiseBuffer;
  noise.loop = true;

  const filter = ctx.createBiquadFilter();
  filter.type = 'bandpass';
  filter.frequency.value = 1100;
  filter.Q.value = 0.7;

  const gain = ctx.createGain();
  gain.gain.setValueAtTime(0.0001, now);
  gain.gain.exponentialRampToValueAtTime(0.055, now + 0.12); // fade in from ignition

  // LFO for gentle flicker modulation on the volume (flame breathing)
  const lfo = ctx.createOscillator();
  lfo.type = 'sine';
  lfo.frequency.value = 8.5; // ~8-9Hz flicker
  const lfoGain = ctx.createGain();
  lfoGain.gain.value = 0.015;
  lfo.connect(lfoGain);
  lfoGain.connect(gain.gain);

  noise.connect(filter).connect(gain).connect(ctx.destination);
  noise.start(now);
  lfo.start(now);

  burnLoopNodes = { noise, filter, gain, lfo, lfoGain };
}

export function stopZippoBurnLoop() {
  const ctx = getAudioContext();
  if (!ctx || !burnLoopNodes) return;
  const now = ctx.currentTime;
  const { noise, gain, lfo } = burnLoopNodes;
  try {
    if (gain) {
      gain.gain.cancelScheduledValues(now);
      gain.gain.setValueAtTime(gain.gain.value, now);
      gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.18);
    }
    setTimeout(() => {
      try { noise?.stop(); } catch { /* ignore */ }
      try { lfo?.stop(); } catch { /* ignore */ }
    }, 220);
  } catch { /* ignore */ }
  burnLoopNodes = null;
}

// ========================
// REAL AUDIO FILE PLAYBACK
// ========================

let menuMusicAudio: HTMLAudioElement | null = null;
let introDialogueAudio: HTMLAudioElement | null = null;
let menuTransitionSpeechAudio: HTMLAudioElement | null = null;

// ========================
// v0.4.1 AUDIO DUCKING SYSTEM
// Dynamic music ducking for speech/priority SFX clarity.
// Any speech/dialogue call requests a "duck"; the menu music volume ramps
// down to a floor while the duck is active, then ramps back up on release.
// Ref-counted so overlapping speech lines don't unduck prematurely.
// ========================

const MUSIC_NORMAL_VOL = 0.42;
const MUSIC_DUCKED_VOL = 0.10;     // music dims to 10% when speech fires
const DUCK_ATTACK_MS = 220;        // fast attack — must not feel laggy
const DUCK_RELEASE_MS = 520;       // slower release — graceful return
const STOP_MUSIC_FADE_MS = 900;    // menu music hard-stop fade

let duckCount = 0;
let duckRafId: number | null = null;
let stopMusicRafId: number | null = null;
// Tracks which audio elements currently hold a duck reservation. Prevents
// double-decrement if both 'ended' event and explicit stopX() fire.
const duckingSources = new WeakSet<HTMLAudioElement>();

function rampMusicVolume(targetVol: number, durationMs: number, onDone?: () => void) {
  if (stopMusicRafId !== null) { cancelAnimationFrame(stopMusicRafId); stopMusicRafId = null; }
  if (duckRafId !== null) { cancelAnimationFrame(duckRafId); duckRafId = null; }
  const audio = menuMusicAudio;
  if (!audio) { onDone?.(); return; }
  const startVol = audio.volume;
  const startTime = performance.now();
  const step = (now: number) => {
    if (!menuMusicAudio || menuMusicAudio !== audio) {
      // Music was replaced or cleared — abort smoothly.
      duckRafId = null;
      onDone?.();
      return;
    }
    const t = Math.min(1, (now - startTime) / Math.max(1, durationMs));
    // Smooth ease-in-out for pleasant fade
    const eased = t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
    const vol = startVol + (targetVol - startVol) * eased;
    try { audio.volume = Math.max(0, Math.min(1, vol)); } catch { /* ignore */ }
    if (t < 1) {
      duckRafId = requestAnimationFrame(step);
    } else {
      duckRafId = null;
      onDone?.();
    }
  };
  duckRafId = requestAnimationFrame(step);
}

function applyDuckState() {
  // If no music is playing there's nothing to ramp. Still maintain the count
  // so if music starts mid-speech, ducking will be observed on next play.
  if (!menuMusicAudio) return;
  const target = duckCount > 0 ? MUSIC_DUCKED_VOL : MUSIC_NORMAL_VOL;
  const duration = duckCount > 0 ? DUCK_ATTACK_MS : DUCK_RELEASE_MS;
  rampMusicVolume(target, duration);
}

/** Request music ducking. Balance with releaseDuck(). Ref-counted. */
export function requestDuck() {
  duckCount++;
  if (duckCount === 1) applyDuckState();
}

/** Release a previously-requested duck. Idempotent at zero. */
export function releaseDuck() {
  duckCount = Math.max(0, duckCount - 1);
  if (duckCount === 0) applyDuckState();
}

/**
 * Attach a duck reservation to an audio element. The duck will auto-release
 * when the audio ends. Safe to call multiple times on the same element.
 */
function attachDuckToAudio(audio: HTMLAudioElement | null) {
  if (!audio || duckingSources.has(audio)) return;
  duckingSources.add(audio);
  requestDuck();
  const onEnded = () => {
    if (duckingSources.has(audio)) {
      duckingSources.delete(audio);
      releaseDuck();
    }
    audio.removeEventListener('ended', onEnded);
  };
  audio.addEventListener('ended', onEnded);
}

/** Force-release the duck for a specific audio element (used by stopX()). */
function forceReleaseDuckFor(audio: HTMLAudioElement | null) {
  if (!audio || !duckingSources.has(audio)) return;
  duckingSources.delete(audio);
  releaseDuck();
}

/**
 * Preload the menu music file so it's ready to play the instant
 * the user acknowledges the disclaimer. No-op after first call.
 * This warms the HTTP cache; playMenuMusic() will then load from cache.
 */
let menuMusicPreloaded = false;
export function preloadMenuMusic(): void {
  if (typeof window === 'undefined' || menuMusicPreloaded) return;
  try {
    const a = new Audio('/audio/menu-theme.mp3');
    a.preload = 'auto';
    a.volume = 0;
    a.load();
    menuMusicPreloaded = true;
  } catch { /* ignore */ }
}

/**
 * v0.5.5 — Music plays 25% faster than the source file. This is intentional —
 * Wesley wants the menu loop to feel slightly more frantic / off-kilter.
 * preservesPitch is left at the browser default (true on Chrome, varies
 * elsewhere) so the song stays in tune; the temp-shift alone is the effect.
 * If the user wants the chipmunk-pitch creep, set this to false.
 */
const MENU_MUSIC_PLAYBACK_RATE = 1.0;

function applyPlaybackRate(audio: HTMLAudioElement | null) {
  if (!audio) return;
  try {
    audio.playbackRate = MENU_MUSIC_PLAYBACK_RATE;
    // Modern browsers — keep pitch correct so it's just faster, not chipmunk
    // (Wesley can flip this later if he wants the pitch shift).
    if ('preservesPitch' in audio) {
      (audio as HTMLAudioElement & { preservesPitch?: boolean }).preservesPitch = true;
    }
  } catch { /* ignore */ }
}

/**
 * Play the main menu music (menu-theme.mp3).
 * Loops. This is designed to carry SEAMLESSLY from the menu through the
 * title slideshow → character_creator/welcome_back → bedroom hub —
 * callers should NOT call stopMenuMusic() when navigating between those
 * phases. Only stop it when entering actual gameplay (raid, expedition, etc).
 * In the bedroom hub, callers should activate radio-mode (see enableRadioMode)
 * to give the song a tinny, distant, "playing-in-another-room" treatment.
 * If already playing, returns without restarting.
 */
export function playMenuMusic() {
  if (typeof window === 'undefined') return;
  // If already playing, don't restart — lets it carry across phase transitions.
  if (menuMusicAudio && !menuMusicAudio.paused) {
    applyPlaybackRate(menuMusicAudio);
    return;
  }
  try {
    if (!menuMusicAudio) {
      menuMusicAudio = new Audio('/audio/menu-theme.mp3');
      menuMusicAudio.loop = false; // v3.0 — plays once; radio-mode filter at hub
      menuMusicAudio.volume = duckCount > 0 ? MUSIC_DUCKED_VOL : MUSIC_NORMAL_VOL;
    } else {
      // Re-apply current duck state in case of re-entry
      menuMusicAudio.volume = duckCount > 0 ? MUSIC_DUCKED_VOL : MUSIC_NORMAL_VOL;
    }
    applyPlaybackRate(menuMusicAudio);
    menuMusicAudio.play().catch(() => { /* user gesture required */ });
  } catch { /* ignore */ }
}

/** Fade out and stop menu music (call this when entering actual gameplay) */
export function stopMenuMusic() {
  if (!menuMusicAudio) return;
  // v0.5.5 — if radio mode was active, drop it cleanly so the static stops.
  if (radioModeActive) {
    radioModeActive = false;
    if (menuAudioContext) stopRadioStatic(menuAudioContext);
  }
  // Cancel any active duck ramp — we're stopping entirely.
  if (duckRafId !== null) { cancelAnimationFrame(duckRafId); duckRafId = null; }
  if (stopMusicRafId !== null) { cancelAnimationFrame(stopMusicRafId); stopMusicRafId = null; }
  const audio = menuMusicAudio;
  menuMusicAudio = null; // detach singleton immediately so new calls don't interfere
  const startVol = audio.volume;
  const startTime = performance.now();
  const step = (now: number) => {
    const t = Math.min(1, (now - startTime) / STOP_MUSIC_FADE_MS);
    const eased = t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
    const vol = startVol * (1 - eased);
    try { audio.volume = Math.max(0, vol); } catch { /* ignore */ }
    if (t < 1) {
      stopMusicRafId = requestAnimationFrame(step);
    } else {
      stopMusicRafId = null;
      try { audio.pause(); audio.currentTime = 0; } catch { /* ignore */ }
    }
  };
  stopMusicRafId = requestAnimationFrame(step);
}

// ========================
// v0.5.2 MENU MUSIC ANALYSER (psychedelic bloom beat-sync)
// Lazily wires an AnalyserNode into the menu music stream so visuals like
// the main-menu psychedelic bloom can pulse in time with the music.
// Once attached, the audio output continues through the audio graph
// (analyser → destination) so playback remains audible.
// ========================

let menuAudioContext: AudioContext | null = null;
let menuAnalyser: AnalyserNode | null = null;
let menuMusicSourceNode: MediaElementAudioSourceNode | null = null;
let menuMusicSourceAttachedTo: HTMLAudioElement | null = null;

// ------------------------------------------------------------------------
// v0.5.5 — RADIO MODE
// Two parallel output paths: a dry path (normal) and a wet path (filtered
// for the "old radio in another room" treatment). Gain crossfade between
// them when enableRadioMode/disableRadioMode is called. A separate static
// noise source rides on top with very low gain.
// ------------------------------------------------------------------------
let radioDryGain: GainNode | null = null;
let radioWetGain: GainNode | null = null;
let radioFilterLow: BiquadFilterNode | null = null;
let radioFilterPeak: BiquadFilterNode | null = null;
let radioStaticSource: AudioBufferSourceNode | null = null;
let radioStaticGain: GainNode | null = null;
let radioStaticFilter: BiquadFilterNode | null = null;
let radioModeActive = false;

/**
 * Get the underlying menu music HTMLAudioElement, or null if not playing.
 * Provided for components that need direct access (e.g., for beat-sync).
 */
export function getMenuMusicAudio(): HTMLAudioElement | null {
  return menuMusicAudio;
}

/**
 * Returns an AnalyserNode wired to the menu music. Lazily creates the
 * AudioContext + MediaElementSourceNode + AnalyserNode on first call.
 * Subsequent calls reuse the cached analyser.
 * Returns null if no music is playing or Web Audio API is unavailable.
 *
 * Note: once createMediaElementSource() captures the audio element,
 * subsequent attempts on the same element throw InvalidStateError, so we
 * track which element the source is attached to and only create one per element.
 */
export function getMenuMusicAnalyser(): AnalyserNode | null {
  if (typeof window === 'undefined') return null;
  const audio = menuMusicAudio;
  if (!audio) return null;

  // If audio element changed (e.g., music was stopped + restarted),
  // tear down the old graph nodes — a MediaElementSourceNode can't be
  // reattached to a different element.
  if (menuMusicSourceAttachedTo && menuMusicSourceAttachedTo !== audio) {
    try { menuMusicSourceNode?.disconnect(); } catch {}
    try { menuAnalyser?.disconnect(); } catch {}
    try { radioDryGain?.disconnect(); } catch {}
    try { radioWetGain?.disconnect(); } catch {}
    try { radioFilterLow?.disconnect(); } catch {}
    try { radioFilterPeak?.disconnect(); } catch {}
    menuMusicSourceNode = null;
    menuAnalyser = null;
    menuMusicSourceAttachedTo = null;
    radioDryGain = null;
    radioWetGain = null;
    radioFilterLow = null;
    radioFilterPeak = null;
  }

  try {
    const Ctx: typeof AudioContext | undefined = window.AudioContext || (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
    if (!Ctx) return null;
    if (!menuAudioContext) {
      menuAudioContext = new Ctx();
    }
    if (menuAudioContext.state === 'suspended') {
      menuAudioContext.resume().catch(() => { /* needs gesture */ });
    }
    if (!menuMusicSourceNode) {
      menuMusicSourceNode = menuAudioContext.createMediaElementSource(audio);
      menuMusicSourceAttachedTo = audio;
    }
    if (!menuAnalyser) {
      menuAnalyser = menuAudioContext.createAnalyser();
      menuAnalyser.fftSize = 256;            // 128 frequency bins
      menuAnalyser.smoothingTimeConstant = 0.82; // gentle smoothing
      menuMusicSourceNode.connect(menuAnalyser);
      // v0.5.5 — instead of analyser→destination, route through dry/wet split.
      buildRadioGraph(menuAudioContext, menuAnalyser);
    }
    return menuAnalyser;
  } catch {
    return null;
  }
}

/**
 * v0.5.5 — Build the dry/wet output graph that sits BETWEEN the analyser
 * and the audio destination. Once built, the dry-gain is at 1.0 and the
 * wet-gain is at 0, so it acts as an audible passthrough.  Toggling radio
 * mode crossfades between the two paths.
 *
 * Idempotent — safe to call multiple times; it builds nodes only once.
 */
function buildRadioGraph(ctx: AudioContext, analyser: AnalyserNode) {
  if (radioDryGain && radioWetGain) return; // already wired
  try {
    radioDryGain = ctx.createGain();
    radioDryGain.gain.value = 1.0;

    radioFilterLow = ctx.createBiquadFilter();
    radioFilterLow.type = 'lowpass';
    radioFilterLow.frequency.value = 1900;   // attenuate above ~1.9kHz — kills sparkle
    radioFilterLow.Q.value = 0.6;

    radioFilterPeak = ctx.createBiquadFilter();
    radioFilterPeak.type = 'peaking';
    radioFilterPeak.frequency.value = 1000;  // tinny presence boost in the speech band
    radioFilterPeak.Q.value = 1.4;
    radioFilterPeak.gain.value = 5.5;

    radioWetGain = ctx.createGain();
    radioWetGain.gain.value = 0.0;

    // Wire two parallel paths from analyser to destination.
    analyser.connect(radioDryGain);
    radioDryGain.connect(ctx.destination);

    analyser.connect(radioFilterLow);
    radioFilterLow.connect(radioFilterPeak);
    radioFilterPeak.connect(radioWetGain);
    radioWetGain.connect(ctx.destination);
  } catch { /* ignore */ }
}

/** Spin up the static-noise loop. Generates 2s of pink-ish noise on the fly. */
function startRadioStatic(ctx: AudioContext) {
  if (radioStaticSource) return;
  try {
    const sampleRate = ctx.sampleRate;
    const bufferSize = sampleRate * 2;
    const buffer = ctx.createBuffer(1, bufferSize, sampleRate);
    const data = buffer.getChannelData(0);
    // White noise with mild low-frequency rumble removed by the highpass below.
    for (let i = 0; i < bufferSize; i++) data[i] = (Math.random() * 2 - 1);

    radioStaticSource = ctx.createBufferSource();
    radioStaticSource.buffer = buffer;
    radioStaticSource.loop = true;

    radioStaticFilter = ctx.createBiquadFilter();
    radioStaticFilter.type = 'highpass';
    radioStaticFilter.frequency.value = 700;  // crisp crackle, not bass rumble
    radioStaticFilter.Q.value = 0.5;

    radioStaticGain = ctx.createGain();
    radioStaticGain.gain.value = 0;           // fade-in below

    radioStaticSource.connect(radioStaticFilter);
    radioStaticFilter.connect(radioStaticGain);
    radioStaticGain.connect(ctx.destination);
    radioStaticSource.start();

    // Fade-in to the target static level (very low — texture only)
    const now = ctx.currentTime;
    radioStaticGain.gain.cancelScheduledValues(now);
    radioStaticGain.gain.setValueAtTime(0, now);
    radioStaticGain.gain.linearRampToValueAtTime(0.014, now + 1.4);
  } catch { /* ignore */ }
}

/** Stop and tear down the static-noise loop. Idempotent. */
function stopRadioStatic(ctx: AudioContext) {
  if (!radioStaticSource && !radioStaticGain) return;
  try {
    if (radioStaticGain) {
      const now = ctx.currentTime;
      radioStaticGain.gain.cancelScheduledValues(now);
      radioStaticGain.gain.setValueAtTime(radioStaticGain.gain.value, now);
      radioStaticGain.gain.linearRampToValueAtTime(0, now + 0.8);
    }
    setTimeout(() => {
      try { radioStaticSource?.stop(); } catch {}
      try { radioStaticSource?.disconnect(); } catch {}
      try { radioStaticFilter?.disconnect(); } catch {}
      try { radioStaticGain?.disconnect(); } catch {}
      radioStaticSource = null;
      radioStaticFilter = null;
      radioStaticGain = null;
    }, 900);
  } catch { /* ignore */ }
}

/**
 * v0.5.5 — Apply the "playing on a radio in another room" treatment to
 * the menu music. Crossfades dry→wet over ~1.6s, drops music gain to a
 * floor (~0.18), and adds a low-volume static crackle.  Idempotent.
 *
 * Call this when the user enters the bedroom hub. Pair with disableRadioMode
 * when leaving the hub or when stopping the music entirely.
 */
export function enableRadioMode() {
  if (typeof window === 'undefined') return;
  if (radioModeActive) return;
  radioModeActive = true;

  // Bootstrap the analyser graph if it hasn't been built yet (e.g., the
  // user skipped the main-menu visualizer).
  const analyser = getMenuMusicAnalyser();
  const ctx = menuAudioContext;
  if (!ctx || !analyser || !radioDryGain || !radioWetGain) {
    // No web audio graph — fall back to gain-only ducking via existing ramp.
    rampMusicVolume(0.18, 1500);
    return;
  }

  // Crossfade the dry/wet gains.
  const now = ctx.currentTime;
  const fadeSec = 1.5;
  try {
    radioDryGain.gain.cancelScheduledValues(now);
    radioDryGain.gain.setValueAtTime(radioDryGain.gain.value, now);
    radioDryGain.gain.linearRampToValueAtTime(0.0, now + fadeSec);
    radioWetGain.gain.cancelScheduledValues(now);
    radioWetGain.gain.setValueAtTime(radioWetGain.gain.value, now);
    radioWetGain.gain.linearRampToValueAtTime(1.0, now + fadeSec);
  } catch { /* ignore */ }

  // Drop the master music gain to a "playing somewhere else" floor.
  rampMusicVolume(0.18, 1500);

  // Crackle.
  startRadioStatic(ctx);
}

/**
 * v0.5.5 — Reverse enableRadioMode. Crossfades wet→dry, restores music
 * volume, and fades out the static.  Idempotent.
 */
export function disableRadioMode() {
  if (typeof window === 'undefined') return;
  if (!radioModeActive) return;
  radioModeActive = false;

  const ctx = menuAudioContext;
  if (ctx && radioDryGain && radioWetGain) {
    const now = ctx.currentTime;
    const fadeSec = 1.5;
    try {
      radioDryGain.gain.cancelScheduledValues(now);
      radioDryGain.gain.setValueAtTime(radioDryGain.gain.value, now);
      radioDryGain.gain.linearRampToValueAtTime(1.0, now + fadeSec);
      radioWetGain.gain.cancelScheduledValues(now);
      radioWetGain.gain.setValueAtTime(radioWetGain.gain.value, now);
      radioWetGain.gain.linearRampToValueAtTime(0.0, now + fadeSec);
    } catch { /* ignore */ }
    stopRadioStatic(ctx);
  }

  // Restore master music volume to its standard duck-aware default.
  rampMusicVolume(duckCount > 0 ? MUSIC_DUCKED_VOL : MUSIC_NORMAL_VOL, 1500);
}

/** True when radio-mode treatment is currently active. */
export function isRadioModeActive(): boolean {
  return radioModeActive;
}


