// --- SFX dedup guard: prevents overlapping identical sounds ---
const _sfxLastPlay: Record<string, number> = {};
const SFX_DEDUP_MS = 80; // minimum ms between same SFX

function _sfxGuard(key: string): boolean {
  const now = Date.now();
  if (now - (_sfxLastPlay[key] ?? 0) < SFX_DEDUP_MS) return false;
  _sfxLastPlay[key] = now;
  return true;
}

function playNoise(duration: number, freq: number, type: OscillatorType = 'sawtooth', vol: number = 0.1) {
  const ctx = getAudioContext();
  if (!ctx) return;
  // Dedup: keyed by rounded freq + type
  const key = `${Math.round(freq)}_${type}`;
  if (!_sfxGuard(key)) return;

  // Muffled effect: lowpass filter to dampen high frequencies
  const filter = ctx.createBiquadFilter();
  filter.type = 'lowpass';
  filter.frequency.setValueAtTime(Math.min(freq * 1.5, 2000), ctx.currentTime);
  filter.Q.setValueAtTime(0.7, ctx.currentTime);

  const osc = ctx.createOscillator();
  const gain = ctx.createGain();
  osc.type = type;
  osc.frequency.setValueAtTime(freq, ctx.currentTime);
  // Muffled: reduce volume to 60% of original
  const muffledVol = vol * 0.6;
  gain.gain.setValueAtTime(muffledVol, ctx.currentTime);
  gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + duration);
  osc.connect(filter);
  filter.connect(gain);
  gain.connect(ctx.destination);
  osc.start();
  osc.stop(ctx.currentTime + duration);
}

