// ========================
// AMBIENT LOOPS — per-screen atmosphere
// ========================

let activeAmbientNodes: { oscs: OscillatorNode[]; gains: GainNode[]; stop: () => void } | null = null;

export function stopAmbientLoop() {
  if (activeAmbientNodes) {
    try { activeAmbientNodes.stop(); } catch {}
    activeAmbientNodes = null;
  }
}

function createAmbientLoop(setup: (ctx: AudioContext) => { oscs: OscillatorNode[]; gains: GainNode[] }) {
  stopAmbientLoop();
  const ctx = getAudioContext();
  if (!ctx) return;

  const { oscs, gains } = setup(ctx);

  activeAmbientNodes = {
    oscs,
    gains,
    stop: () => {
      gains.forEach(g => {
        try { g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.8); } catch {}
      });
      setTimeout(() => {
        oscs.forEach(o => { try { o.stop(); } catch {} });
      }, 1000);
    },
  };
}

// Hub: Low mains hum + distant creaking stairs ambience.
// The creaking simulates old wooden house settling — irregular filtered noise bursts.
// (Wesley asked to severely reduce the original humming static — kept it near-subliminal.)
export function playAmbientHub(escalationLevel: number = 0) {
  createAmbientLoop((ctx) => {
    const allOscs: OscillatorNode[] = [];
    const allGains: GainNode[] = [];

    // --- Mains hum (only at escalation >= 2) ---
    if (escalationLevel >= 2) {
      const baseVol = 0.0015 + (escalationLevel - 2) * 0.0008;
      const osc1 = ctx.createOscillator();
      const gain1 = ctx.createGain();
      osc1.type = 'sine';
      osc1.frequency.setValueAtTime(60, ctx.currentTime);
      gain1.gain.setValueAtTime(baseVol, ctx.currentTime);
      osc1.connect(gain1);
      gain1.connect(ctx.destination);
      osc1.start();
      allOscs.push(osc1);
      allGains.push(gain1);
    }

    // --- Distant creaking stairs ---
    // Uses filtered noise bursts at irregular intervals to simulate
    // old wood stress/settling sounds. Very low volume, subliminal.
    const creakVol = 0.003 + escalationLevel * 0.0008;
    // Create noise source via oscillator + waveshaper (cheap noise)
    const noiseOsc = ctx.createOscillator();
    const noiseGain = ctx.createGain();
    const noiseBand = ctx.createBiquadFilter();

    noiseOsc.type = 'sawtooth';
    noiseOsc.frequency.setValueAtTime(80 + Math.random() * 40, ctx.currentTime);

    // Bandpass filter to make it sound wooden/creaky (300-600Hz range)
    noiseBand.type = 'bandpass';
    noiseBand.frequency.setValueAtTime(420, ctx.currentTime);
    noiseBand.Q.setValueAtTime(8, ctx.currentTime);

    noiseGain.gain.setValueAtTime(0, ctx.currentTime);

    noiseOsc.connect(noiseBand);
    noiseBand.connect(noiseGain);
    noiseGain.connect(ctx.destination);
    noiseOsc.start();

    allOscs.push(noiseOsc);
    allGains.push(noiseGain);

    // Schedule irregular creak events — fades in and out over 0.1-0.3s
    let creakTimer: ReturnType<typeof setTimeout> | null = null;
    function scheduleCreak() {
      const delay = 4000 + Math.random() * 12000; // 4-16 seconds apart
      creakTimer = setTimeout(() => {
        try {
          const now = ctx.currentTime;
          const dur = 0.08 + Math.random() * 0.2;
          // Shift frequency slightly for variety
          noiseBand.frequency.setValueAtTime(350 + Math.random() * 200, now);
          noiseOsc.frequency.setValueAtTime(60 + Math.random() * 80, now);
          // Creak envelope: quick attack, slow release
          noiseGain.gain.cancelScheduledValues(now);
          noiseGain.gain.setValueAtTime(0, now);
          noiseGain.gain.linearRampToValueAtTime(creakVol, now + 0.02);
          noiseGain.gain.linearRampToValueAtTime(creakVol * 0.6, now + dur * 0.5);
          noiseGain.gain.linearRampToValueAtTime(0, now + dur);
        } catch {}
        scheduleCreak();
      }, delay);
    }
    scheduleCreak();

    // Patch cleanup to clear creak timer
    const cleanupCreak = () => { if (creakTimer) clearTimeout(creakTimer); };
    // Store cleanup reference on gain node for later
    (noiseGain as any)._cleanupCreak = cleanupCreak;

    return { oscs: allOscs, gains: allGains };
  });
}

