// Scrapbook: Near-silence. Clock tick (~1Hz sine pulse) + fridge hum (60Hz continuous).
// The ABSENCE of the game's chaotic audio is the statement. Very quiet.
export function playAmbientScrapbook() {
  createAmbientLoop((ctx) => {
    // Fridge hum — continuous low 60Hz drone, barely audible
    const fridgeOsc = ctx.createOscillator();
    const fridgeGain = ctx.createGain();
    fridgeOsc.type = 'sine';
    fridgeOsc.frequency.setValueAtTime(60, ctx.currentTime);
    fridgeGain.gain.setValueAtTime(0.006, ctx.currentTime);
    fridgeOsc.connect(fridgeGain);
    fridgeGain.connect(ctx.destination);
    fridgeOsc.start();

    // Fridge harmonic — 120Hz overtone, even quieter
    const fridgeOsc2 = ctx.createOscillator();
    const fridgeGain2 = ctx.createGain();
    fridgeOsc2.type = 'sine';
    fridgeOsc2.frequency.setValueAtTime(120, ctx.currentTime);
    fridgeGain2.gain.setValueAtTime(0.002, ctx.currentTime);
    fridgeOsc2.connect(fridgeGain2);
    fridgeGain2.connect(ctx.destination);
    fridgeOsc2.start();

    // Clock tick — metronome sine pulse ~1Hz, short attack/decay
    const tickOsc = ctx.createOscillator();
    const tickGain = ctx.createGain();
    const tickFilter = ctx.createBiquadFilter();
    tickOsc.type = 'sine';
    tickOsc.frequency.setValueAtTime(800, ctx.currentTime);
    tickFilter.type = 'bandpass';
    tickFilter.frequency.setValueAtTime(800, ctx.currentTime);
    tickFilter.Q.setValueAtTime(12, ctx.currentTime);
    tickGain.gain.setValueAtTime(0, ctx.currentTime);
    tickOsc.connect(tickFilter);
    tickFilter.connect(tickGain);
    tickGain.connect(ctx.destination);
    tickOsc.start();

    // Schedule ticks via gain envelope — 1 tick per second
    const scheduleTicks = () => {
      const now = ctx.currentTime;
      for (let i = 0; i < 120; i++) {
        const t = now + i;
        tickGain.gain.setValueAtTime(0, t);
        tickGain.gain.linearRampToValueAtTime(0.012, t + 0.003);
        tickGain.gain.exponentialRampToValueAtTime(0.0001, t + 0.06);
      }
      // Re-schedule before running out
      setTimeout(scheduleTicks, 110000);
    };
    scheduleTicks();

    return { oscs: [fridgeOsc, fridgeOsc2, tickOsc], gains: [fridgeGain, fridgeGain2, tickGain] };
  });
}

// Escalation drone — pitch increases with level
export function playEscalationDrone(level: number) {
  if (level < 3) return; // Only kicks in at level 3+
  createAmbientLoop((ctx) => {
    const baseFreq = 30 + level * 5;
    const vol = 0.005 + (level - 3) * 0.003;

    const osc1 = ctx.createOscillator();
    const gain1 = ctx.createGain();
    osc1.type = 'sine';
    osc1.frequency.setValueAtTime(baseFreq, ctx.currentTime);
    gain1.gain.setValueAtTime(vol, ctx.currentTime);

    // Distortion increases with level
    const waveshaper = ctx.createWaveShaper();
    const curve = new Float32Array(256);
    const distortion = level * 10;
    for (let i = 0; i < 256; i++) {
      const x = (i * 2) / 256 - 1;
      curve[i] = ((3 + distortion) * x * 20 * (Math.PI / 180)) / (Math.PI + distortion * Math.abs(x));
    }
    waveshaper.curve = curve;

    osc1.connect(waveshaper);
    waveshaper.connect(gain1);
    gain1.connect(ctx.destination);
    osc1.start();

    return { oscs: [osc1], gains: [gain1] };
  });
}

