/**
 * Paper crinkle — short, textured noise burst for memo fluttering in.
 * Used by <MemoReveal/>. ~320ms, quiet.
 */
export function playPaperCrinkle() {
  const ctx = getAudioContext();
  if (!ctx) return;
  const now = ctx.currentTime;
  const bufferSize = Math.floor(ctx.sampleRate * 0.32);
  const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
  const data = buffer.getChannelData(0);
  // Stochastic crackle: short bursts at random positions
  for (let i = 0; i < bufferSize; i++) {
    // Very sparse — only a few samples have noise
    const pos = i / bufferSize;
    const envelope = Math.sin(pos * Math.PI) * 0.8; // arc envelope
    const sparkle = Math.random() < 0.35 ? (Math.random() * 2 - 1) : 0;
    data[i] = sparkle * envelope;
  }
  const src = ctx.createBufferSource();
  src.buffer = buffer;
  const filter = ctx.createBiquadFilter();
  filter.type = 'highpass';
  filter.frequency.value = 2200;
  filter.Q.value = 0.7;
  const gain = ctx.createGain();
  gain.gain.setValueAtTime(0.15, now);
  gain.gain.exponentialRampToValueAtTime(0.001, now + 0.32);
  src.connect(filter);
  filter.connect(gain);
  gain.connect(ctx.destination);
  src.start(now);
  src.stop(now + 0.32);
}

/**
 * Match strike — quick rasp followed by a brief puff. ~180ms.
 * Used for recruitment gift / Zippo ignition accents.
 */
export function playMatchStrike() {
  const ctx = getAudioContext();
  if (!ctx) return;
  const now = ctx.currentTime;

  // 1) Rasp — ~60ms of filtered white noise with fast decay
  const raspSize = Math.floor(ctx.sampleRate * 0.06);
  const raspBuf = ctx.createBuffer(1, raspSize, ctx.sampleRate);
  const raspData = raspBuf.getChannelData(0);
  for (let i = 0; i < raspSize; i++) {
    const decay = Math.exp(-i / (raspSize * 0.4));
    raspData[i] = (Math.random() * 2 - 1) * decay;
  }
  const rasp = ctx.createBufferSource();
  rasp.buffer = raspBuf;
  const raspFilter = ctx.createBiquadFilter();
  raspFilter.type = 'bandpass';
  raspFilter.frequency.value = 3200;
  raspFilter.Q.value = 2.2;
  const raspGain = ctx.createGain();
  raspGain.gain.setValueAtTime(0.3, now);
  rasp.connect(raspFilter);
  raspFilter.connect(raspGain);
  raspGain.connect(ctx.destination);
  rasp.start(now);
  rasp.stop(now + 0.06);

  // 2) Puff — pink-ish noise, ~120ms, starts right after rasp
  const puffSize = Math.floor(ctx.sampleRate * 0.12);
  const puffBuf = ctx.createBuffer(1, puffSize, ctx.sampleRate);
  const puffData = puffBuf.getChannelData(0);
  let b0 = 0, b1 = 0;
  for (let i = 0; i < puffSize; i++) {
    const white = Math.random() * 2 - 1;
    b0 = 0.99 * b0 + white * 0.0555;
    b1 = 0.96 * b1 + white * 0.2965;
    puffData[i] = (b0 + b1) * 0.5;
  }
  const puff = ctx.createBufferSource();
  puff.buffer = puffBuf;
  const puffFilter = ctx.createBiquadFilter();
  puffFilter.type = 'lowpass';
  puffFilter.frequency.setValueAtTime(800, now + 0.06);
  puffFilter.frequency.exponentialRampToValueAtTime(300, now + 0.18);
  const puffGain = ctx.createGain();
  puffGain.gain.setValueAtTime(0.22, now + 0.06);
  puffGain.gain.exponentialRampToValueAtTime(0.001, now + 0.18);
  puff.connect(puffFilter);
  puffFilter.connect(puffGain);
  puffGain.connect(ctx.destination);
  puff.start(now + 0.06);
  puff.stop(now + 0.18);
}

