/**
 * Nightlight twinkle — soft 3-note ascending chime (C6 → E6 → G6) with a
 * gentle decay tail.  Plays when the player confirms "the animal light".
 * Total duration ≈ 1.2s.
 */
export function playNightlightTwinkle() {
  const ctx = getAudioContext();
  if (!ctx) return;
  const now = ctx.currentTime;
  // C6 ≈ 1046.5 Hz, E6 ≈ 1318.5 Hz, G6 ≈ 1567.98 Hz
  const notes = [1046.5, 1318.5, 1567.98];
  notes.forEach((freq, i) => {
    const start = now + i * 0.16;
    const dur = 0.7;

    // Sine for the tone body
    const osc = ctx.createOscillator();
    osc.type = 'sine';
    osc.frequency.value = freq;
    // Detuned partial for a glassy shimmer
    const partial = ctx.createOscillator();
    partial.type = 'sine';
    partial.frequency.value = freq * 2.005;

    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.0001, start);
    gain.gain.exponentialRampToValueAtTime(0.13, start + 0.01);
    gain.gain.exponentialRampToValueAtTime(0.0001, start + dur);

    const partialGain = ctx.createGain();
    partialGain.gain.setValueAtTime(0.0001, start);
    partialGain.gain.exponentialRampToValueAtTime(0.04, start + 0.012);
    partialGain.gain.exponentialRampToValueAtTime(0.0001, start + dur * 0.85);

    // Soft lowpass to round off the top
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 5200;
    filter.Q.value = 0.5;

    osc.connect(gain);
    partial.connect(partialGain);
    partialGain.connect(gain);
    gain.connect(filter);
    filter.connect(ctx.destination);

    osc.start(start);
    partial.start(start);
    osc.stop(start + dur);
    partial.stop(start + dur);
  });
}

/**
 * Light-switch click — articulated mechanical click with a brief hollow
