  const clickData = clickBuf.getChannelData(0);
  for (let i = 0; i < clickSize; i++) {
    const decay = Math.exp(-i / (clickSize * 0.18));
    clickData[i] = (Math.random() * 2 - 1) * decay;
  }
  const click = ctx.createBufferSource();
