/**
 * Pacifier slide — a soft wet "schlick" suggesting a thumb sliding into
 * a mouth.  Filtered noise + a low body tone.  ~280ms.  Disquieting and
 * intimate.  Used for ritual III confirm.
 */
export function playPacifierSlide() {
  const ctx = getAudioContext();
  if (!ctx) return;
  const now = ctx.currentTime;

  // 1) Wet noise body — pink-ish noise, lowpass that opens then closes
  const noiseSize = Math.floor(ctx.sampleRate * 0.28);
  const noiseBuf = ctx.createBuffer(1, noiseSize, ctx.sampleRate);
  const noiseData = noiseBuf.getChannelData(0);
  let b0 = 0, b1 = 0;
  for (let i = 0; i < noiseSize; i++) {
    const white = Math.random() * 2 - 1;
    b0 = 0.985 * b0 + white * 0.06;
    b1 = 0.94 * b1 + white * 0.28;
    const env = Math.sin((i / noiseSize) * Math.PI); // arch envelope
    noiseData[i] = (b0 + b1) * env * 0.55;
  }
  const noise = ctx.createBufferSource();
  noise.buffer = noiseBuf;
  const noiseFilter = ctx.createBiquadFilter();
  noiseFilter.type = 'lowpass';
  // Filter sweep: starts dim, opens to ~1.6kHz mid-slide, closes again
  noiseFilter.frequency.setValueAtTime(700, now);
  noiseFilter.frequency.linearRampToValueAtTime(1600, now + 0.13);
  noiseFilter.frequency.linearRampToValueAtTime(500, now + 0.28);
  noiseFilter.Q.value = 1.1;
  const noiseGain = ctx.createGain();
  noiseGain.gain.setValueAtTime(0.0001, now);
  noiseGain.gain.exponentialRampToValueAtTime(0.16, now + 0.06);
  noiseGain.gain.exponentialRampToValueAtTime(0.04, now + 0.20);
  noiseGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.28);
  noise.connect(noiseFilter);
  noiseFilter.connect(noiseGain);
  noiseGain.connect(ctx.destination);
  noise.start(now);
  noise.stop(now + 0.28);

  // 2) Low body tone — sine slides from 220 → 140 Hz
  const body = ctx.createOscillator();
  body.type = 'sine';
  body.frequency.setValueAtTime(220, now);
  body.frequency.exponentialRampToValueAtTime(140, now + 0.25);
  const bodyGain = ctx.createGain();
  bodyGain.gain.setValueAtTime(0.0001, now);
  bodyGain.gain.exponentialRampToValueAtTime(0.06, now + 0.05);
  bodyGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.26);
  body.connect(bodyGain);
  bodyGain.connect(ctx.destination);
  body.start(now);
  body.stop(now + 0.28);
}

/**
 * Bedtime whimper — a quiet, child-like whine.  Sine wave 380 → 260 Hz
 * with subtle vibrato.  Played as the final fade-to-black.  Total ≈ 1.4s.
 */
export function playBedtimeWhimper() {
  const ctx = getAudioContext();
  if (!ctx) return;
  const now = ctx.currentTime;
  const dur = 1.4;

  // Main whine
  const osc = ctx.createOscillator();
  osc.type = 'sine';
  osc.frequency.setValueAtTime(380, now);
  osc.frequency.exponentialRampToValueAtTime(260, now + dur);

  // Vibrato (LFO modulating osc detune)
  const lfo = ctx.createOscillator();
  lfo.type = 'sine';
  lfo.frequency.value = 5.5; // ~5.5 Hz vibrato
  const lfoGain = ctx.createGain();
  lfoGain.gain.value = 14; // cents range
  lfo.connect(lfoGain);
  lfoGain.connect(osc.detune);

  // Slight fundamental partial for breathiness
  const partial = ctx.createOscillator();
  partial.type = 'sine';
  partial.frequency.setValueAtTime(380 * 1.5, now);
  partial.frequency.exponentialRampToValueAtTime(260 * 1.5, now + dur);
  const partialGain = ctx.createGain();
  partialGain.gain.setValueAtTime(0.0001, now);
  partialGain.gain.exponentialRampToValueAtTime(0.018, now + 0.18);
  partialGain.gain.exponentialRampToValueAtTime(0.0001, now + dur);

  // Master envelope — soft attack, full body, fade out
  const gain = ctx.createGain();
  gain.gain.setValueAtTime(0.0001, now);
  gain.gain.exponentialRampToValueAtTime(0.07, now + 0.18);
  gain.gain.setValueAtTime(0.07, now + 0.55);
  gain.gain.exponentialRampToValueAtTime(0.025, now + 1.05);
  gain.gain.exponentialRampToValueAtTime(0.0001, now + dur);

  // Lowpass to keep it warm/round
  const filter = ctx.createBiquadFilter();
  filter.type = 'lowpass';
  filter.frequency.value = 1600;
  filter.Q.value = 0.4;

  osc.connect(gain);
  partial.connect(partialGain);
  partialGain.connect(gain);
  gain.connect(filter);
  filter.connect(ctx.destination);

  osc.start(now);
  partial.start(now);
  lfo.start(now);
  osc.stop(now + dur);
  partial.stop(now + dur);
  lfo.stop(now + dur);
}
