/**
 * CRT DEGAUSS — the classic "bwoooong" wobble heard when an old monitor
 * powers on / a screen is switched. A low sine that dips in pitch with a
 * fast amplitude tremolo (the magnetic shudder) decaying over ~650ms.
 * Synthesised — no audio asset. Used on hub room transitions.
 */
/**
 * playChunkyPress — "massive pixelated button pressed, abrupt, serious with a touch of silly."
 * Short burst (~180ms): low square wave with quick pitch drop (weight) + layered
 * white-noise pop (silliness) + a brief bit-crushed overtone.
 */
export function playChunkyPress() {
  const ctx = getAudioContext();
  if (!ctx) return;
  if (!_sfxGuard('chunkyPress')) return;
  const now = ctx.currentTime;
  const vol = 0.18 * getEffectiveVolume('sfx');
  if (vol <= 0) return;

  // --- Layer 1: heavy square wave with pitch drop (the "thonk") ---
  const osc = ctx.createOscillator();
  osc.type = 'square';
  osc.frequency.setValueAtTime(140, now);
  osc.frequency.exponentialRampToValueAtTime(55, now + 0.12);
  const oscGain = ctx.createGain();
  oscGain.gain.setValueAtTime(vol, now);
  oscGain.gain.exponentialRampToValueAtTime(0.001, now + 0.18);
  // low-pass to keep it chunky, not shrill
  const lp = ctx.createBiquadFilter();
  lp.type = 'lowpass';
  lp.frequency.setValueAtTime(600, now);
  lp.Q.setValueAtTime(1.2, now);
  osc.connect(lp).connect(oscGain).connect(ctx.destination);
  osc.start(now);
  osc.stop(now + 0.2);

  // --- Layer 2: noise pop (the comedic overtone) ---
  const bufLen = Math.floor(ctx.sampleRate * 0.06);
  const buf = ctx.createBuffer(1, bufLen, ctx.sampleRate);
  const data = buf.getChannelData(0);
  for (let i = 0; i < bufLen; i++) data[i] = (Math.random() * 2 - 1) * 0.5;
  const noise = ctx.createBufferSource();
  noise.buffer = buf;
  const noiseGain = ctx.createGain();
  noiseGain.gain.setValueAtTime(vol * 0.5, now);
  noiseGain.gain.exponentialRampToValueAtTime(0.001, now + 0.08);
  const noiseLp = ctx.createBiquadFilter();
  noiseLp.type = 'bandpass';
  noiseLp.frequency.setValueAtTime(1800, now);
  noiseLp.Q.setValueAtTime(0.8, now);
  noise.connect(noiseLp).connect(noiseGain).connect(ctx.destination);
  noise.start(now + 0.01);
  noise.stop(now + 0.09);

  // --- Layer 3: bit-crush overtone (brief sawtooth blip) ---
  const saw = ctx.createOscillator();
  saw.type = 'sawtooth';
  saw.frequency.setValueAtTime(280, now);
  saw.frequency.exponentialRampToValueAtTime(110, now + 0.06);
  const sawGain = ctx.createGain();
  sawGain.gain.setValueAtTime(vol * 0.25, now);
  sawGain.gain.exponentialRampToValueAtTime(0.001, now + 0.07);
  saw.connect(lp).connect(sawGain).connect(ctx.destination);
  saw.start(now);
  saw.stop(now + 0.08);
}

/**
 * playLullabyChime — soft music-box arpeggio for the lullaby ritual button.
 * Three gentle sine tones ascending (C5-E5-G5) with slight detune for warmth,
 * each note fading like a struck chime. ~600ms total.
 */
export function playLullabyChime() {
  const ctx = getAudioContext();
  if (!ctx) return;
  if (!_sfxGuard('lullabyChime')) return;
  const now = ctx.currentTime;
  const vol = 0.12 * getEffectiveVolume('sfx');
  if (vol <= 0) return;

  const notes = [523.25, 659.25, 783.99]; // C5, E5, G5
  const spacing = 0.14;

  notes.forEach((freq, i) => {
    const t = now + i * spacing;
    // main tone
    const osc = ctx.createOscillator();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(freq, t);
    // slight detune partner for music-box warmth
    const osc2 = ctx.createOscillator();
    osc2.type = 'sine';
    osc2.frequency.setValueAtTime(freq * 1.003, t);

    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.001, t);
    gain.gain.exponentialRampToValueAtTime(vol * (1 - i * 0.15), t + 0.02);
    gain.gain.exponentialRampToValueAtTime(0.001, t + 0.35);

    // gentle high-shelf rolloff
    const hp = ctx.createBiquadFilter();
    hp.type = 'highshelf';
    hp.frequency.value = 3000;
    hp.gain.value = -6;

    osc.connect(hp).connect(gain).connect(ctx.destination);
    osc2.connect(hp);
    osc.start(t);
    osc2.start(t);
    osc.stop(t + 0.4);
    osc2.stop(t + 0.4);
  });
}

export function playDegauss() {
  const ctx = getAudioContext();
  if (!ctx) return;
  const now = ctx.currentTime;
  const dur = 0.65;
  const vol = 0.16 * getEffectiveVolume('sfx');
  if (vol <= 0) return;

  // Main body — low sine sweeping down (the "bwooong" pitch dip)
  const osc = ctx.createOscillator();
  osc.type = 'sine';
  osc.frequency.setValueAtTime(150, now);
  osc.frequency.exponentialRampToValueAtTime(55, now + dur);

  // Tremolo LFO — the magnetic shudder modulating amplitude
  const lfo = ctx.createOscillator();
  lfo.type = 'sine';
  lfo.frequency.setValueAtTime(22, now);
  lfo.frequency.exponentialRampToValueAtTime(7, now + dur);
  const lfoGain = ctx.createGain();
  lfoGain.gain.setValueAtTime(vol * 0.55, now);

  const gain = ctx.createGain();
  gain.gain.setValueAtTime(0.0001, now);
  gain.gain.exponentialRampToValueAtTime(vol, now + 0.04);
  gain.gain.exponentialRampToValueAtTime(0.0001, now + dur);

  // Slight low-pass so it reads as "behind glass"
  const filter = ctx.createBiquadFilter();
  filter.type = 'lowpass';
  filter.frequency.value = 900;
  filter.Q.value = 0.6;

  lfo.connect(lfoGain).connect(gain.gain);
  osc.connect(filter).connect(gain).connect(ctx.destination);
  osc.start(now);
  lfo.start(now);
  osc.stop(now + dur + 0.05);
  lfo.stop(now + dur + 0.05);
}

