// ENCOUNTER BRIDGE — BMF:3K Bible §5.2
// Maps the 5 existing encounter templates to their dominant tone.
// encounter.ts is LOCKED — this file provides a read-only overlay.
// ═══════════════════════════════════════════════════════════════════════

import type { EncounterTone } from './anchor-dictionary';

/**
 * Encounter template keys — must match the `trigger` values in
 * encounter.ts ENCOUNTER_TEMPLATES (which we cannot import directly
 * because encounter.ts is locked and may have side-effects).
 */
export type EncounterTemplateKey =
  | 'RIVAL_CREW'
  | 'SECURITY_PATROL'
  | 'TWEAKER_AMBUSH'
  | 'STRAY_ANIMALS'
  | 'SHAKEDOWN';

export interface EncounterToneBridge {
  tone: EncounterTone;
  /** Short rationale for the tone assignment. */
  rationale: string;
}

/**
 * Tone assignments for each encounter template.
 * Derived from Bible §5.2 encounter-tone matrix.
 */
export const ENCOUNTER_TONE_MAP: Record<EncounterTemplateKey, EncounterToneBridge> = {
  RIVAL_CREW: {
    tone: 'HESITANT',
    rationale: 'Rival crews posture but hesitate — they share the same precarity.',
  },
  SECURITY_PATROL: {
    tone: 'RIGID',
    rationale: 'Security speaks in policy and ordinance — pure authority.',
  },
  TWEAKER_AMBUSH: {
    tone: 'CLINICAL',
    rationale: 'Tweakers frame aggression as calculated, expected behaviour.',
  },
  STRAY_ANIMALS: {
    tone: 'CLINICAL',
    rationale: 'Animal encounters are narrated with detached observation.',
  },
  SHAKEDOWN: {
    tone: 'RIGID',
    rationale: 'Shakedowns enforce hierarchy through threats of prohibition.',
  },
} as const;

/**
 * Look up the dominant tone for an encounter template.
 * Returns undefined if the key is not in the bridge (safety).
 */
export function getEncounterTone(key: string): EncounterToneBridge | undefined {
  return ENCOUNTER_TONE_MAP[key as EncounterTemplateKey];
}

import { NextResponse } from 'next/server'
import { prisma } from '@/lib/db'
import { UNLOCK_COOKIE, CODE_PATTERN, getSignedInUser, normaliseToken } from '@/lib/membership'
import { newUnlockToken } from '@/lib/stripe'

export const dynamic = 'force-dynamic'

/**
 * Redeems a single-use purchase code to the signed-in profile.
 * The entitlement (User.member) is stored server-side; no device cookie is issued.
 */
export async function POST(req: Request) {
  const user = await getSignedInUser()
  if (!user) return NextResponse.json({ error: 'SIGN IN TO REDEEM' }, { status: 401 })

  const body = await req.json().catch(() => ({}))
  const code = normaliseToken(body?.code)
  if (!CODE_PATTERN.test(code)) return NextResponse.json({ error: 'CODE NOT RECOGNISED' }, { status: 404 })

  const record = await prisma.unlockCode.findUnique({ where: { code } })
  if (!record) return NextResponse.json({ error: 'CODE NOT RECOGNISED' }, { status: 404 })

  if (record.usedAt) {
    if (record.userId === user.id) return NextResponse.json({ ok: true, already: true })
    return NextResponse.json({ error: 'CODE ALREADY USED' }, { status: 409 })
  }

  // Atomic claim: only one request can flip usedAt from null and bind the code to its profile
  const claimed = await prisma.unlockCode.updateMany({ where: { code, usedAt: null }, data: { usedAt: new Date(), userId: user.id } })
  if (claimed.count !== 1) {
    const now = await prisma.unlockCode.findUnique({ where: { code }, select: { userId: true } })
    if (now?.userId === user.id) return NextResponse.json({ ok: true, already: true })
    return NextResponse.json({ error: 'CODE ALREADY USED' }, { status: 409 })
  }

  await prisma.$transaction([
    prisma.purchase.upsert({
      where: { stripeSessionId: record.stripeSessionId },
      update: { userId: user.id },
      create: {
        userId: user.id,
        stripeSessionId: record.stripeSessionId,
        amountTotal: record.amountTotal,
        currency: record.currency,
        status: 'paid',
      },
    }),
    prisma.user.update({
      where: { id: user.id },
      data: {
        member: true,
        memberSince: user.memberSince ?? new Date(),
        unlockToken: user.unlockToken ?? newUnlockToken(),
      },
    }),
  ])
  return NextResponse.json({ ok: true, already: false })
}

/** Clears the retired device cookie from older builds. */
export async function DELETE() {
  const res = NextResponse.json({ ok: true })
  res.cookies.set(UNLOCK_COOKIE, '', { httpOnly: true, secure: true, sameSite: 'lax', path: '/', maxAge: 0 })
  return res
}

import NextAuth from 'next-auth'
import Credentials from 'next-auth/providers/credentials'
import { PrismaAdapter } from '@auth/prisma-adapter'
import bcrypt from 'bcryptjs'
import { prisma } from '@/lib/db'
import { ADMIN_PRINCIPAL_EMAIL, adminFingerprint, consumeTicket } from '@/lib/admin-auth'

export const { handlers, auth, signIn, signOut } = NextAuth({
  adapter: PrismaAdapter(prisma),
  trustHost: true,
  session: { strategy: 'jwt' },
  pages: { signIn: '/profile' },
  providers: [
    // Visitor profiles. Email sign-in never grants admin.
    Credentials({
      credentials: { email: {}, password: {} },
      async authorize(creds) {
        const email = String(creds?.email ?? '').trim().toLowerCase()
        const password = String(creds?.password ?? '')
        if (!email || !password) return null
        const user = await prisma.user.findUnique({ where: { email } })
        if (!user?.password || user.role === 'admin') return null
        const ok = await bcrypt.compare(password, user.password)
        if (!ok) return null
        return { id: user.id, email: user.email, name: user.name, role: 'user' } as any
      },
    }),
    // Control room: only a one-time ticket issued by /api/admin/login (after the hashed passcode
    // passed its rate-limited check) can mint an admin session.
    Credentials({
      id: 'admin-ticket',
      name: 'Control room',
      credentials: { ticket: {} },
      async authorize(creds) {
        const ticket = String(creds?.ticket ?? '')
        if (!/^[a-f0-9]{64}$/.test(ticket) || !consumeTicket(ticket)) return null
        const principal = await prisma.user.upsert({
          where: { email: ADMIN_PRINCIPAL_EMAIL },
          update: { role: 'admin', password: null },
          create: { email: ADMIN_PRINCIPAL_EMAIL, name: 'Control Room', role: 'admin' },
        })
        return { id: principal.id, email: principal.email, name: principal.name, role: 'admin' } as any
      },
    }),
  ],
  callbacks: {
    async jwt({ token, user }) {
      if (user) {
        token.id = (user as any).id
        token.role = (user as any).role ?? 'user'
        token.av = token.role === 'admin' ? adminFingerprint() : null
      }
      // An admin session minted under an older passcode loses admin rights immediately
      if (token.role === 'admin' && (!token.av || token.av !== adminFingerprint())) token.role = 'user'
      return token
    },
    async session({ session, token }) {
      if (session.user) {
        ;(session.user as any).id = token.id
        ;(session.user as any).role = token.role
      }
      return session
    },
  },
})

export async function requireAdmin() {
  const session = await auth()
  const role = (session?.user as any)?.role
  return role === 'admin' ? session : null
}

