import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { calculateTolerance, type ToleranceCurve } from '@/lib/game-engine';
import { isValidId, validateResourceType } from '@/lib/api-guards';

export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const { npcId, sessionId } = body ?? {};
    const substance = validateResourceType(body?.substance);
    if (!isValidId(npcId) || !substance) {
      return NextResponse.json({ error: 'Missing params' }, { status: 400 });
    }
    const npc = await prisma.nPC.findUnique({ where: { id: npcId } });
    if (!npc) return NextResponse.json({ error: 'NPC not found' }, { status: 404 });

    // Ownership guard
    if (sessionId && npc.sessionId !== sessionId) {
      return NextResponse.json({ error: 'NPC does not belong to this session' }, { status: 403 });
    }

    const substanceMap: Record<string, { usageField: keyof typeof npc; tolField: string; rate: number; curve: ToleranceCurve }> = {
      cigarettes: { usageField: 'usageCigs', tolField: 'toleranceCigs', rate: 0.1, curve: 'LINEAR' },
      alcohol: { usageField: 'usageAlc', tolField: 'toleranceAlc', rate: 0.3, curve: 'SLOW_FADE' },
      weed: { usageField: 'usageWeed', tolField: 'toleranceWeed', rate: 0.2, curve: 'LINEAR' },
      crystals: { usageField: 'usageCryst', tolField: 'toleranceCryst', rate: 5.0, curve: 'DOUBLE_DOWN' },
    };

    const s = substanceMap[substance];
    if (!s) return NextResponse.json({ error: 'Unknown substance' }, { status: 400 });

    const currentUsage = (npc[s.usageField] as number) ?? 0;
    const newUsage = currentUsage + 1;
    const newTol = calculateTolerance(0, newUsage, s.rate, 1.0, s.curve);

    // Crystal cross-contamination: meth is so systemically destructive it
    // spills stress into every other tolerance axis. Without this, the
    // encounter system's avgTolerance (sum/4) dilutes a single substance
    // into nothing. Spillover = 80% of crystal tolerance, floored by existing.
    const data: Record<string, number> = { [s.usageField]: newUsage, [s.tolField]: newTol };
    if (substance === 'crystals') {
      const spill = newTol * 0.8;
      if (spill > ((npc.toleranceCigs as number) ?? 0)) data.toleranceCigs = spill;
      if (spill > ((npc.toleranceAlc as number) ?? 0))  data.toleranceAlc = spill;
      if (spill > ((npc.toleranceWeed as number) ?? 0)) data.toleranceWeed = spill;
    }

    const updated = await prisma.nPC.update({
      where: { id: npcId },
      data,
    });

    return NextResponse.json(updated);
  } catch (err: unknown) {
    console.error('Tolerance error:', err);
    return NextResponse.json({ error: 'Failed' }, { status: 500 });
  }
}

'use client';

import { useEffect, useRef } from 'react';
import { motion } from 'framer-motion';

interface Props {
  /** 0-3: 0=surveillance start, 1=dissection, 2=pitch, 3=near-complete */
  intensity: number;
  /** Optional override for colour bleed hue */
  hue?: string;
}

/**
 * VHS DEGRADATION OVERLAY
 *
 * Simulates VHS tape artefacts that worsen as recruitment progresses.
 * The player is literally degrading the subject — the interface reflects
 * the violence of the process.
 *
 * Level 0: Faint scan lines only
 * Level 1: + tracking wobble, occasional horizontal tear
 * Level 2: + colour channel separation (chromatic aberration), noise grain
 * Level 3: + heavy static bursts, rolling bar, colour bleed
 *
 * Pure CSS/SVG animation — zero JS runtime, zero bundle impact.
 */
export default function VHSDegradation({ intensity, hue = '#b87a96' }: Props) {
  const level = Math.max(0, Math.min(3, Math.floor(intensity)));

  return (
    <div className="absolute inset-0 pointer-events-none overflow-hidden z-30" aria-hidden="true">
      {/* ─── SCAN LINES (always present) ─── */}
      <div
        className="absolute inset-0"
        style={{
          backgroundImage: 'repeating-linear-gradient(0deg, rgba(0,0,0,0) 0px, rgba(0,0,0,0) 1px, rgba(0,0,0,0.08) 2px, rgba(0,0,0,0) 3px)',
          opacity: 0.4 + level * 0.15,
        }}
      />

      {/* ─── TRACKING WOBBLE (level 1+) ─── */}
      {level >= 1 && (
        <motion.div
          className="absolute inset-0"
          animate={{ x: [0, -1, 2, -1, 0, 1, -2, 0] }}
          transition={{ duration: 4 + Math.random() * 2, repeat: Infinity, ease: 'linear' }}
          style={{ mixBlendMode: 'overlay' }}
        >
          {/* Horizontal tear — a bright line that jumps position */}
          <motion.div
            className="absolute left-0 right-0 h-[2px]"
            animate={{
              top: ['15%', '45%', '78%', '22%', '60%', '35%'],
              opacity: [0, 0.6, 0, 0, 0.4, 0],
            }}
            transition={{ duration: 8, repeat: Infinity, ease: 'linear' }}
            style={{ background: `linear-gradient(90deg, transparent, rgba(255,255,255,0.3), transparent)` }}
          />
        </motion.div>
      )}

      {/* ─── CHROMATIC ABERRATION (level 2+) ─── */}
      {level >= 2 && (
        <>
          {/* Red channel shift */}
          <motion.div
            className="absolute inset-0"
            animate={{ x: [0, 2, 0, -1, 0] }}
            transition={{ duration: 6, repeat: Infinity, ease: 'easeInOut' }}
            style={{
              background: 'transparent',
              boxShadow: `inset 2px 0 0 rgba(255,0,0,0.04), inset -2px 0 0 rgba(0,255,255,0.04)`,
              mixBlendMode: 'screen',
            }}
          />
          {/* Noise grain */}
          <div
            className="absolute inset-0"
            style={{
              backgroundImage: `url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='https://i.ytimg.com/vi/1bYAwpPPD6U/sddefault.jpg id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)' opacity='0.04'/%3E%3C/svg%3E")`,
              opacity: 0.5 + level * 0.1,
            }}
          />
        </>
      )}

      {/* ─── HEAVY CORRUPTION (level 3) ─── */}
      {level >= 3 && (
        <>
          {/* Rolling dark bar */}
          <motion.div
            className="absolute left-0 right-0 h-[30px]"
            animate={{
              top: ['-30px', '110%'],
              opacity: [0, 0.25, 0.25, 0],
            }}
            transition={{ duration: 5, repeat: Infinity, ease: 'linear', repeatDelay: 3 }}
            style={{
              background: 'linear-gradient(180deg, transparent, rgba(0,0,0,0.4), transparent)',
            }}
          />
          {/* Colour bleed flash */}
          <motion.div
            className="absolute inset-0"
            animate={{ opacity: [0, 0, 0.08, 0, 0, 0.06, 0] }}
            transition={{ duration: 4, repeat: Infinity, ease: 'linear' }}
            style={{ background: hue, mixBlendMode: 'color' }}
          />
          {/* Static burst band */}
          <motion.div
            className="absolute left-0 right-0 h-[6px]"
            animate={{
              top: ['20%', '70%', '40%', '85%', '10%'],
              opacity: [0, 0.5, 0, 0.3, 0],
              scaleY: [1, 1.5, 1, 2, 1],
            }}
            transition={{ duration: 3, repeat: Infinity, ease: 'linear', repeatDelay: 5 }}
            style={{
              backgroundImage: 'repeating-linear-gradient(90deg, transparent 0px, rgba(255,255,255,0.15) 1px, transparent 2px)',
            }}
          />
        </>
      )}
    </div>
  );
}

'use client'

import { createContext, useContext, useState, useCallback, useRef, useEffect, useMemo, type ReactNode } from 'react'

export type FieldMode = 'grid' | 'partition' | 'decay'
export type PulseKind = 'tick' | 'press' | 'lock' | 'sweep'

interface HudState {
  power: boolean
  gain: number
  hue: number
  mode: FieldMode
  scanKey: number
  lastEvent: string
  soundOn: boolean
  musicVolume: number
  togglePower: () => void
  setGain: (v: number) => void
  setHue: (v: number) => void
  cycleMode: () => void
  triggerScan: () => void
  pulse: (kind: PulseKind) => void
  transition: (dir: number) => void
  toggleSound: () => void
  setMusicVolume: (v: number) => void
  note: (label: string) => void
}

const MODES: FieldMode[] = ['grid', 'partition', 'decay']

const HudContext = createContext<HudState | null>(null)

export function useHud(): HudState {
  const ctx = useContext(HudContext)
  if (!ctx) {
    throw new Error('useHud must be used within HudProvider')
  }
  return ctx
}

export function HudProvider({ children }: { children: ReactNode }) {
  const [power, setPower] = useState(true)
  const [gain, setGainState] = useState(0.55)
  const [hue, setHueState] = useState(0)
  const [mode, setMode] = useState<FieldMode>('grid')
  const [scanKey, setScanKey] = useState(0)
  const [lastEvent, setLastEvent] = useState('SYSTEM NOMINAL')
  const [soundOn, setSoundOn] = useState(true)
  const [musicVolume, setMusicVolumeState] = useState(0.5)

  const audioRef = useRef<AudioContext | null>(null)
  const reducedRef = useRef(false)
  const soundRef = useRef(true)
  const musicRef = useRef<HTMLAudioElement | null>(null)
  const musicVolumeRef = useRef(0.5)

  useEffect(() => {
    if (typeof window === 'undefined') return
    reducedRef.current = window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches ?? false
    try {
      const saved = window.localStorage?.getItem('bmf3k.sound')
      if (saved === 'off') {
        soundRef.current = false
        setSoundOn(false)
      }
    } catch {
      // localStorage unavailable — keep default on
    }
  }, [])

  // Background score — starts once the app launches (this provider mounts only
  // after the boot click, so autoplay is allowed), loops forever, and its
  // volume is driven by the global slider that lives on every station.
  useEffect(() => {
    if (typeof window === 'undefined') return

    let vol = 0.5
    try {
      const saved = window.localStorage?.getItem('bmf3k.musicVolume')
      if (saved != null) {
        const n = parseFloat(saved)
        if (!Number.isNaN(n)) vol = Math.min(1, Math.max(0, n))
      }
    } catch {
      // localStorage unavailable — keep default
    }
    musicVolumeRef.current = vol
    setMusicVolumeState(vol)

    // Score rotation: the opening track, then the two follow-ups, then round again.
    const playlist = ['/audio/the-iron-grip.mp3', '/audio/blackout-at-noon.mp3', '/audio/iron-vise.mp3']
    let track = 0
    const audio = new Audio(playlist[track])
    audio.loop = false
    audio.preload = 'auto'
    audio.volume = vol
    musicRef.current = audio

    const tryPlay = () => {
      audio.play().catch(() => { /* blocked until a gesture — handled below */ })
    }
    const onEnded = () => {
      track = (track + 1) % playlist.length
      audio.src = playlist[track]
      tryPlay()
    }
    audio.addEventListener('ended', onEnded)
    tryPlay()

    // Fallback: if the browser blocked autoplay, kick it off on the first
    // pointer or key interaction anywhere in the app.
    const onGesture = () => {
      if (audio.paused) tryPlay()
      if (!audio.paused) {
        window.removeEventListener('pointerdown', onGesture)
        window.removeEventListener('keydown', onGesture)
      }
    }
    window.addEventListener('pointerdown', onGesture)
    window.addEventListener('keydown', onGesture)

    return () => {
      window.removeEventListener('pointerdown', onGesture)
      window.removeEventListener('keydown', onGesture)
      audio.removeEventListener('ended', onEnded)
      audio.pause()
      audio.src = ''
      musicRef.current = null
    }
  }, [])

  const setMusicVolume = useCallback((v: number) => {
    const clamped = Math.min(1, Math.max(0, v))
    musicVolumeRef.current = clamped
    setMusicVolumeState(clamped)
    const audio = musicRef.current
    if (audio) {
      audio.volume = clamped
      // raising from silence should resume playback if it was ever blocked
      if (clamped > 0 && audio.paused) audio.play().catch(() => {})
    }
    try {
      window.localStorage?.setItem('bmf3k.musicVolume', String(clamped))
    } catch {
      // ignore persistence failure
    }
  }, [])

  const toggleSound = useCallback(() => {
    setSoundOn((s) => {
      const next = !s
      soundRef.current = next
      try {
        window.localStorage?.setItem('bmf3k.sound', next ? 'on' : 'off')
      } catch {
        // ignore persistence failure
      }
      return next
    })
  }, [])

  const ensureCtx = useCallback((): AudioContext | null => {
    if (typeof window === 'undefined') return null
    try {
      const Ctor = window.AudioContext || (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext
      if (!Ctor) return null
      if (!audioRef.current) audioRef.current = new Ctor()
      const ac = audioRef.current
      if (ac.state === 'suspended') void ac.resume()
      return ac
    } catch {
      return null
    }
  }, [])

  const transition = useCallback((dir: number) => {
    if (typeof window === 'undefined') return
    if (!soundRef.current || reducedRef.current) return
    const ac = ensureCtx()
    if (!ac) return
    try {
      const now = ac.currentTime
      const fwd = dir >= 0
      const dur = 0.34

      // Bandpass-filtered white-noise whoosh.
      const frames = Math.floor(ac.sampleRate * dur)
      const buffer = ac.createBuffer(1, frames, ac.sampleRate)
      const data = buffer.getChannelData(0)
      for (let i = 0; i < frames; i++) data[i] = Math.random() * 2 - 1
      const noise = ac.createBufferSource()
      noise.buffer = buffer

      const band = ac.createBiquadFilter()
      band.type = 'bandpass'
      band.Q.value = 0.8
      band.frequency.setValueAtTime(fwd ? 380 : 1700, now)
      band.frequency.exponentialRampToValueAtTime(fwd ? 1700 : 380, now + dur)

      const nGain = ac.createGain()
      nGain.gain.setValueAtTime(0.0001, now)
      nGain.gain.exponentialRampToValueAtTime(0.05, now + 0.06)
      nGain.gain.exponentialRampToValueAtTime(0.0001, now + dur)

      noise.connect(band)
      band.connect(nGain)

      // Optional stereo sweep by direction.
      let tail: AudioNode = nGain
      if (typeof ac.createStereoPanner === 'function') {
        const pan = ac.createStereoPanner()
        pan.pan.setValueAtTime(fwd ? -0.5 : 0.5, now)
        pan.pan.linearRampToValueAtTime(fwd ? 0.5 : -0.5, now + dur)
        nGain.connect(pan)
        tail = pan
      }
      tail.connect(ac.destination)
      noise.start(now)
      noise.stop(now + dur)

      // Subtle sine thunk under the whoosh.
      const osc = ac.createOscillator()
      const oGain = ac.createGain()
      osc.type = 'sine'
      osc.frequency.setValueAtTime(fwd ? 160 : 120, now)
      osc.frequency.exponentialRampToValueAtTime(fwd ? 90 : 200, now + 0.22)
      oGain.gain.setValueAtTime(0.0001, now)
      oGain.gain.exponentialRampToValueAtTime(0.03, now + 0.03)
      oGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.26)
      osc.connect(oGain)
      oGain.connect(ac.destination)
      osc.start(now)
      osc.stop(now + 0.28)
    } catch {
      // audio unavailable — silent
    }
  }, [ensureCtx])

  const note = useCallback((label: string) => {
    setLastEvent(label)
  }, [])

  const pulse = useCallback((kind: PulseKind) => {
    if (typeof window === 'undefined') return

    // Haptics — supported on Android Chrome; iOS Safari ignores this silently.
    try {
      const nav = window.navigator as Navigator & { vibrate?: (p: number | number[]) => boolean }
      if (typeof nav.vibrate === 'function') {
        if (kind === 'tick') nav.vibrate(7)
        else if (kind === 'press') nav.vibrate(18)
        else if (kind === 'lock') nav.vibrate([10, 26, 16])
        else nav.vibrate([4, 30, 4])
      }
    } catch {
      // haptics unavailable — silent
    }

    // Detent ticks are haptic-only; no audio chatter.
    if (kind === 'tick') return
    if (reducedRef.current || !soundRef.current) return

    try {
      const ac = ensureCtx()
      if (!ac) return

      const now = ac.currentTime
      const osc = ac.createOscillator()
      const gainNode = ac.createGain()
      const filter = ac.createBiquadFilter()

      filter.type = 'lowpass'
      filter.frequency.value = kind === 'sweep' ? 900 : 1600

      osc.type = kind === 'sweep' ? 'sine' : 'square'
      const base = kind === 'press' ? 220 : kind === 'lock' ? 150 : 90
      osc.frequency.setValueAtTime(base, now)
      osc.frequency.exponentialRampToValueAtTime(base * 0.5, now + 0.07)

      const peak = kind === 'sweep' ? 0.018 : 0.032
      gainNode.gain.setValueAtTime(0.0001, now)
      gainNode.gain.exponentialRampToValueAtTime(peak, now + 0.004)
      gainNode.gain.exponentialRampToValueAtTime(0.0001, now + 0.11)

      osc.connect(filter)
      filter.connect(gainNode)
      gainNode.connect(ac.destination)
      osc.start(now)
      osc.stop(now + 0.13)
    } catch {
      // audio unavailable — silent
    }
  }, [ensureCtx])

  const togglePower = useCallback(() => {
    setPower((p) => {
      const next = !p
      setLastEvent(next ? 'FIELD RESTORED' : 'FIELD SUPPRESSED')
      return next
    })
    pulse('lock')
  }, [pulse])

  const setGain = useCallback((v: number) => {
    const clamped = Math.min(1, Math.max(0, v))
    setGainState(clamped)
  }, [])

  const setHue = useCallback((v: number) => {
    const clamped = Math.min(1, Math.max(0, v))
    setHueState(clamped)
  }, [])

  const cycleMode = useCallback(() => {
    setMode((m) => {
      const idx = MODES.indexOf(m)
      const next = MODES[(idx + 1) % MODES.length] ?? 'grid'
      setLastEvent(`MODE / ${next.toUpperCase()}`)
      return next
    })
    pulse('press')
  }, [pulse])

  const triggerScan = useCallback(() => {
    setScanKey((k) => k + 1)
  }, [])

  // App-wide automatic scan sweep every 10 seconds.
  // Paused while the tab is hidden so it never fires against a backgrounded page.
  useEffect(() => {
    if (typeof window === 'undefined') return
    let id: number | null = null
    const start = () => {
      if (id != null) return
      id = window.setInterval(() => setScanKey((k) => k + 1), 10000)
    }
    const stop = () => {
      if (id != null) {
        window.clearInterval(id)
        id = null
      }
    }
    const onVis = () => {
      if (document.visibilityState === 'hidden') stop()
      else start()
    }
    if (document.visibilityState !== 'hidden') start()
    document.addEventListener('visibilitychange', onVis)
    return () => {
      stop()
      document.removeEventListener('visibilitychange', onVis)
    }
  }, [])

  const value = useMemo<HudState>(() => ({
    power,
    gain,
    hue,
    mode,
    scanKey,
    lastEvent,
    soundOn,
    musicVolume,
    togglePower,
    setGain,
    setHue,
    cycleMode,
    triggerScan,
    pulse,
    transition,
    toggleSound,
    setMusicVolume,
    note,
  }), [power, gain, hue, mode, scanKey, lastEvent, soundOn, musicVolume, togglePower, setGain, setHue, cycleMode, triggerScan, pulse, transition, toggleSound, setMusicVolume, note])

  return <HudContext.Provider value={value}>{children}</HudContext.Provider>
}

