import { NextResponse } from 'next/server'
import { clientIp, issueTicket, lockRemaining, verifyPasscode } from '@/lib/admin-auth'

export const dynamic = 'force-dynamic'

export async function POST(req: Request) {
  const ip = clientIp(req)
  let passcode = ''
  try {
    const body = await req.json()
    passcode = typeof body?.passcode === 'string' ? body.passcode : ''
  } catch {
    passcode = ''
  }
  const result = await verifyPasscode(passcode, ip)
  if (result === 'ok') return NextResponse.json({ ticket: issueTicket() })
  if (result === 'locked') {
    const wait = lockRemaining(ip)
    return NextResponse.json(
      { error: 'LOCKED OUT', retryAfter: wait },
      { status: 429, headers: { 'Retry-After': String(wait) } },
    )
  }
  if (result === 'unconfigured') return NextResponse.json({ error: 'CONTROL ROOM OFFLINE' }, { status: 503 })
  return NextResponse.json({ error: 'ACCESS DENIED' }, { status: 401 })
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { MAX_LIFETIME_COFFEES } from '@/lib/game-data';
import { isValidId } from '@/lib/api-guards';

export const dynamic = 'force-dynamic';

// v1.3.0 — 4 coffee types, each buffs a different stat. 1 per day, MAX_LIFETIME_COFFEES total.
const COFFEE_TYPES: Record<string, { stat: 'nerve' | 'insight' | 'presence' | 'mobility'; label: string }> = {
  black:     { stat: 'nerve',    label: 'BLACK COFFEE' },
  mocha:     { stat: 'insight',  label: 'MOCHA' },
  espresso:  { stat: 'presence', label: 'ESPRESSO' },
  instant:   { stat: 'mobility', label: 'INSTANT' },
};

export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const sessionId = body?.sessionId;
    const coffeeType = body?.coffeeType;

    if (!isValidId(sessionId)) {
      return NextResponse.json({ error: 'Missing sessionId' }, { status: 400 });
    }

    const coffee = COFFEE_TYPES[coffeeType as string];
    if (!coffee) {
      return NextResponse.json({ error: 'Unknown coffee type' }, { status: 400 });
    }

    const session = await prisma.gameSession.findUnique({
      where: { id: sessionId },
      select: { day: true, lastCoffeeDay: true, totalCoffees: true, nerve: true, insight: true, presence: true, mobility: true },
    });

    if (!session) {
      return NextResponse.json({ error: 'Session not found' }, { status: 404 });
    }

    // 1 coffee per day
    if (session.lastCoffeeDay >= session.day) {
      return NextResponse.json({ error: 'already_used', message: 'One cup per shift. The machine knows.' }, { status: 409 });
    }

    // Lifetime cap — prevents infinite stat scaling
    const totalCoffees = session.totalCoffees ?? 0;
    if (totalCoffees >= MAX_LIFETIME_COFFEES) {
      // Mark as used (so they can't keep trying) but don't boost
      await prisma.gameSession.update({
        where: { id: sessionId },
        data: { lastCoffeeDay: session.day },
      });
      return NextResponse.json({
        stat: coffee.stat,
        value: session[coffee.stat],
        changed: false,
        label: coffee.label,
        message: 'The machine whirs but nothing comes out. You\'ve had too many. Body\'s stopped responding.',
        lifetimeCap: true,
      });
    }

    const currentVal = session[coffee.stat];
    if (currentVal >= 10) {
      await prisma.gameSession.update({
        where: { id: sessionId },
        data: { lastCoffeeDay: session.day, totalCoffees: { increment: 1 } },
      });
      return NextResponse.json({ stat: coffee.stat, value: currentVal, changed: false, label: coffee.label });
    }

    const updated = await prisma.gameSession.update({
      where: { id: sessionId },
      data: {
        [coffee.stat]: Math.min(10, currentVal + 1),
        lastCoffeeDay: session.day,
        totalCoffees: { increment: 1 },
      },
      select: { nerve: true, insight: true, presence: true, mobility: true },
    });

    return NextResponse.json({
      stat: coffee.stat,
      value: updated[coffee.stat],
      changed: true,
      label: coffee.label,
      coffeesRemaining: MAX_LIFETIME_COFFEES - totalCoffees - 1,
    });
  } catch (error) {
    console.error('Kitchen coffee API failed:', error);
    return NextResponse.json({ error: 'Kitchen coffee failed' }, { status: 500 });
  }
}

import { prisma } from './db'
import { SITE_DEFAULTS, type SiteContentMap } from './site-defaults'
import { getFileUrl } from './s3'

export type PublicGame = {
  id: string
  slug: string
  title: string
  subtitle: string
  description: string | null
  /** long-form dossier copy (shown in the dossier window) */
  deepDive: string | null
  /** stored in the legacy `format` column: 'app' units show VISIT, everything else PLAY NOW */
  kind: 'game' | 'app'
  launchLink: string
  linkTarget: 'new_tab' | 'same_tab'
  status: 'active' | 'coming_soon'
  featured: boolean
  order: number
  imageUrl: string | null
  /** behind the paywall: real link is never sent to the browser while locked */
  locked: boolean
}

export async function resolveImage(path: string | null, isPublic: boolean) {
  if (!path) return null
  if (path.startsWith('/')) return path // bundled site asset (e.g. /assets/tet-poster.jpg)
  try {
    return await getFileUrl(path, isPublic)
  } catch {
    return null
  }
}

/** `paywallOn` false = every unit plays free (locks are ignored while the paywall is switched off).
 *  `unlocked` true = supporter (profile or device token): locked units send their real links. */
export async function getPublicGames(paywallOn = true, unlocked = false): Promise<PublicGame[]> {
  try {
    const rows = await prisma.game.findMany({ where: { visible: true }, orderBy: { order: 'asc' } })
    return Promise.all(
      rows.map(async (g) => {
        const locked = paywallOn && g.locked && !unlocked
        return {
        id: g.id,
        slug: g.slug,
        title: g.title,
        subtitle: g.subtitle,
        description: g.description,
        deepDive: g.deepDive,
        kind: g.format === 'app' ? 'app' : 'game',
        launchLink: locked ? '/profile' : g.launchLink || '#',
        linkTarget: g.linkTarget === 'same_tab' ? 'same_tab' : 'new_tab',
        status: g.status === 'coming_soon' ? 'coming_soon' : 'active',
        featured: g.featured,
        order: g.order,
        imageUrl: await resolveImage(g.imagePath, g.imageIsPublic),
        locked,
        } satisfies PublicGame
      })
    )
  } catch (e) {
    console.error('getPublicGames failed', e)
    return []
  }
}

export async function getSiteContent(): Promise<SiteContentMap> {
  const map: SiteContentMap = { ...SITE_DEFAULTS }
  try {
    const rows = await prisma.siteContent.findMany()
    for (const r of rows) if (r.key in map) map[r.key as keyof SiteContentMap] = r.value
  } catch (e) {
    console.error('getSiteContent failed', e)
  }
  return map
}

'use client'

import { useState } from 'react'
import Image from 'next/image'
import { toast } from 'sonner'
import { haptic } from '@/lib/haptics'

export type AdminGame = {
  id: string
  slug: string
  title: string
  subtitle: string
  description: string | null
  deepDive: string | null
  format: string
  launchLink: string
  linkTarget: string
  status: string
  featured: boolean
  visible: boolean
  locked: boolean
  order: number
  imagePath: string | null
  imageUrl: string | null
}

interface Props {
  game: AdminGame
  index: number
  total: number
  onSaved: () => void
  onMove: (dir: -1 | 1) => void
}

const Label = ({ children, htmlFor }: { children: React.ReactNode; htmlFor?: string }) => (
  <label htmlFor={htmlFor} className="block font-oswald text-[11px] uppercase tracking-widest mb-1.5" style={{ color: 'var(--col-bone)' }}>
    {children}
  </label>
)

export function GameEditor({ game, index, total, onSaved, onMove }: Props) {
  const [draft, setDraft] = useState({
    title: game.title,
    subtitle: game.subtitle,
    description: game.description ?? '',
    deepDive: game.deepDive ?? '',
    launchLink: game.launchLink,
    linkTarget: game.linkTarget,
    status: game.status,
    format: game.format === 'app' ? 'app' : 'game',
  })
  const [busy, setBusy] = useState(false)
  const [uploading, setUploading] = useState(false)
  const dirty =
    draft.title !== game.title ||
    draft.subtitle !== game.subtitle ||
    draft.description !== (game.description ?? '') ||
    draft.deepDive !== (game.deepDive ?? '') ||
    draft.launchLink !== game.launchLink ||
    draft.linkTarget !== game.linkTarget ||
    draft.status !== game.status ||
    draft.format !== (game.format === 'app' ? 'app' : 'game')

  const patch = async (data: Record<string, unknown>, okMsg: string) => {
    setBusy(true)
    try {
      const res = await fetch(`/api/admin/games/${game.id}`, {
        method: 'PATCH',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify(data),
      })
      const json = await res.json().catch(() => ({}))
      if (!res.ok) throw new Error(json?.error ?? `HTTP ${res.status}`)
      haptic('complete')
      toast.success(okMsg)
      onSaved()
    } catch (e: any) {
      haptic('error')
      toast.error(e?.message ?? 'Save failed')
    } finally {
      setBusy(false)
    }
  }

  const upload = async (file: File) => {
    if (!file.type.startsWith('image/')) return toast.error('Pick an image file')
    if (file.size > 100 * 1024 * 1024) return toast.error('Image must be under 100MB')
    setUploading(true)
    try {
      const pres = await fetch('/api/admin/upload', {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ fileName: file.name, contentType: file.type }),
      })
      const { uploadUrl, cloud_storage_path, error } = await pres.json()
      if (!pres.ok) throw new Error(error ?? 'Upload URL failed')
      const put = await fetch(uploadUrl, { method: 'PUT', headers: { 'Content-Type': file.type }, body: file })
      if (!put.ok) throw new Error(`Upload failed (${put.status})`)
      await patch({ imagePath: cloud_storage_path }, 'Window art updated')
    } catch (e: any) {
      haptic('error')
      toast.error(e?.message ?? 'Upload failed')
    } finally {
      setUploading(false)
    }
  }

  const duplicate = async () => {
    setBusy(true)
    const res = await fetch('/api/admin/games', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ duplicateOf: game.id }),
    })
    setBusy(false)
    if (res.ok) {
      haptic('complete')
      toast.success('Copy added at the bottom (hidden)')
      onSaved()
    } else {
      haptic('error')
      toast.error('Duplicate failed')
    }
  }

  const remove = async () => {
    if (!window.confirm(`Delete "${game.title}" permanently?`)) return
    setBusy(true)
    const res = await fetch(`/api/admin/games/${game.id}`, { method: 'DELETE' })
    setBusy(false)
    if (res.ok) {
      haptic('complete')
      toast.success('Unit removed')
      onSaved()
    } else {
      haptic('error')
      toast.error('Delete failed')
    }
  }

  const set = (k: keyof typeof draft) => (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) =>
    setDraft((d) => ({ ...d, [k]: e.target.value }))
  const fid = (k: string) => `${game.id}-${k}`

  return (
    <article className="admin-card" style={{ opacity: game.visible ? 1 : 0.7 }}>
      <header className="flex flex-wrap items-center gap-3 mb-5">
        <span className="font-ibm text-[11px] uppercase" style={{ color: 'var(--col-yellow)' }}>UNIT-{String(index + 1).padStart(2, '0')}</span>
        <h3 className="font-anton text-2xl uppercase" style={{ color: 'var(--col-ivory)' }}>{game.title}</h3>
        <div className="ml-auto flex flex-wrap gap-2">
          <button className="admin-btn" disabled={index === 0 || busy} onClick={() => onMove(-1)} aria-label="Move up">↑</button>
          <button className="admin-btn" disabled={index === total - 1 || busy} onClick={() => onMove(1)} aria-label="Move down">↓</button>
          <button className={`admin-btn ${game.visible ? 'admin-btn-on' : ''}`} disabled={busy} onClick={() => patch({ visible: !game.visible }, game.visible ? 'Hidden from site' : 'Visible on site')}>
            {game.visible ? 'VISIBLE' : 'HIDDEN'}
          </button>
          <button className={`admin-btn ${game.featured ? 'admin-btn-on' : ''}`} disabled={busy} onClick={() => patch({ featured: !game.featured }, game.featured ? 'Removed from hero' : 'Featured in hero')}>
            {game.featured ? 'IN HERO' : 'NOT IN HERO'}
          </button>
          <button
            className={`admin-btn ${game.locked ? 'admin-btn-danger' : 'admin-btn-on'}`}
            disabled={busy}
            onClick={() => patch({ locked: !game.locked }, game.locked ? 'Unit is free to play' : 'Unit locked behind paywall')}
            title="Locked units send visitors to the unlock page"
          >
            {game.locked ? 'LOCKED' : 'FREE'}
          </button>
          <button className="admin-btn" disabled={busy} onClick={duplicate}>DUPLICATE</button>
          <button className="admin-btn admin-btn-danger" disabled={busy} onClick={remove}>DELETE</button>
        </div>
      </header>

      <div className="grid md:grid-cols-[260px_1fr] gap-6">
        <div>
          <div className="relative aspect-video bg-[var(--col-black)] overflow-hidden mb-3">
            <Image src={game.imageUrl || '/assets/window-interior-bg.png'} alt={`${game.title} window art`} fill unoptimized={!!game.imageUrl} className="object-cover" sizes="260px" />
            {!game.imageUrl && (
              <span className="absolute bottom-2 left-2 font-ibm text-[10px] uppercase px-1.5 py-0.5" style={{ backgroundColor: 'rgb(var(--bv-bg-rgb) / 0.8)', color: 'var(--col-bone)' }}>DEFAULT ART</span>
            )}
          </div>
          <label className="admin-btn w-full justify-center cursor-pointer">
            {uploading ? 'UPLOADING…' : 'UPLOAD WINDOW ART'}
            <input type="file" accept="image/*" className="sr-only" disabled={uploading} onChange={(e) => { const f = e.target.files?.[0]; if (f) upload(f); e.target.value = '' }} />
          </label>
          {game.imagePath && (
            <button className="admin-btn w-full justify-center mt-2" disabled={busy} onClick={() => patch({ imagePath: null }, 'Reverted to default art')}>USE DEFAULT ART</button>
          )}
        </div>

        <div className="grid sm:grid-cols-2 gap-4">
          <div><Label htmlFor={fid('title')}>Title</Label><input id={fid('title')} className="admin-input" value={draft.title} onChange={set('title')} /></div>
          <div><Label htmlFor={fid('subtitle')}>Subtitle</Label><input id={fid('subtitle')} className="admin-input" value={draft.subtitle} onChange={set('subtitle')} /></div>
          <div className="sm:col-span-2"><Label htmlFor={fid('desc')}>Description (archive card)</Label><textarea id={fid('desc')} rows={2} className="admin-input" value={draft.description} onChange={set('description')} /></div>
          <div className="sm:col-span-2"><Label htmlFor={fid('deep')}>Deep dive (dossier window)</Label><textarea id={fid('deep')} rows={4} className="admin-input" value={draft.deepDive} onChange={set('deepDive')} /></div>
          <div className="sm:col-span-2">
            <Label htmlFor={fid('link')}>Launch link (https://… or # for pending)</Label>
            <input id={fid('link')} className="admin-input" value={draft.launchLink} onChange={set('launchLink')} placeholder="https://" />
          </div>
          <div>
            <Label htmlFor={fid('target')}>Opens in</Label>
            <select id={fid('target')} className="admin-input" value={draft.linkTarget} onChange={set('linkTarget')}>
              <option value="new_tab">New tab</option>
              <option value="same_tab">Same tab</option>
            </select>
          </div>
          <div>
            <Label htmlFor={fid('status')}>Status</Label>
            <select id={fid('status')} className="admin-input" value={draft.status} onChange={set('status')}>
              <option value="active">Live</option>
              <option value="coming_soon">Coming soon</option>
            </select>
          </div>
          <div>
            <Label htmlFor={fid('kind')}>Type (card button)</Label>
            <select id={fid('kind')} className="admin-input" value={draft.format} onChange={set('format')}>
              <option value="game">Game — PLAY NOW</option>
              <option value="app">App — VISIT</option>
            </select>
          </div>
          <div className="flex items-end gap-2">
            <button className="admin-btn admin-btn-primary flex-1 justify-center" disabled={!dirty || busy} onClick={() => patch(draft, 'Unit saved')}>
              {busy ? 'SAVING…' : dirty ? 'SAVE CHANGES' : 'SAVED'}
            </button>
            {dirty && (
              <button className="admin-btn" disabled={busy} onClick={() => setDraft({ title: game.title, subtitle: game.subtitle, description: game.description ?? '', deepDive: game.deepDive ?? '', launchLink: game.launchLink, linkTarget: game.linkTarget, status: game.status, format: game.format === 'app' ? 'app' : 'game' })}>REVERT</button>
            )}
          </div>
        </div>
      </div>
    </article>
  )
}

'use client';

import { useState, useEffect, useCallback, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

interface Props {
  onComplete: () => void;
}

/**
 * v2.1.0 — Glitch Wipe + Pink/Green 3000-Style Wireframe Transition
 *
 * Triggered after the player selects New Game or Continue.
 * Phases:
 *   1. glitch_wipe   (0—1.2s)    — Screen tears apart with chromatic noise
 *   2. wireframe     (1.2—5.2s)  — Pink/green neon wireframe of the menu room
 *                                  with cracked glass, pulsing borders, scan lines
 *   3. fade_out      (5.2—6.2s)  — Wireframe dissolves to black, advance
 *
 * Total: ~6s, skippable.
 *
 * The wireframe visually replaces the old pipe loading screen.
 * Aesthetic: neon magenta (#b87a96) + neon green (#00FF00 / #7FFF00) + yellow
 * accents, CRT damage, cracked glass overlay.
 */

type Phase = 'glitch_wipe' | 'wireframe' | 'fade_out';

const GLITCH_MS = 1200;
const WIREFRAME_MS = 4000;
const FADE_MS = 1000;

export default function TitleSlideshowScreen({ onComplete }: Props) {
  const [phase, setPhase] = useState<Phase>('glitch_wipe');
  const [visible, setVisible] = useState(true);
  const completedRef = useRef(false);
  const timersRef = useRef<ReturnType<typeof setTimeout>[]>([]);

  const finish = useCallback(() => {
    if (completedRef.current) return;
    completedRef.current = true;
    setVisible(false);
    const t = setTimeout(() => onComplete(), 600);
    timersRef.current.push(t);
  }, [onComplete]);

  useEffect(() => {
    let elapsed = 0;
    const t1 = setTimeout(() => setPhase('wireframe'), elapsed += GLITCH_MS);
    const t2 = setTimeout(() => setPhase('fade_out'), elapsed += WIREFRAME_MS);
    const t3 = setTimeout(() => finish(), elapsed += FADE_MS);
    timersRef.current = [t1, t2, t3];
    return () => timersRef.current.forEach(clearTimeout);
  }, [finish]);

  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if (e.key === 'Escape' || e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        finish();
      }
    };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, [finish]);

  return (
    <AnimatePresence>
      {visible && (
        <motion.div
          initial={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          transition={{ duration: 0.5 }}
          className="fixed inset-0 z-[100] bg-black overflow-hidden"
          onClick={finish}
        >
          {/* ===== PHASE 1: GLITCH WIPE ===== */}
          <AnimatePresence>
            {phase === 'glitch_wipe' && (
              <motion.div
                key="glitch"
                initial={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                transition={{ duration: 0.12 }}
                className="absolute inset-0"
              >
                {/* Diagonal white wipe */}
                <motion.div
                  className="absolute inset-0"
                  initial={{ clipPath: 'polygon(0% 0%, 0% 0%, 0% 100%, 0% 100%)' }}
                  animate={{ clipPath: 'polygon(0% 0%, 120% 0%, 100% 100%, 0% 100%)' }}
                  transition={{ duration: 0.6, ease: 'easeInOut' }}
                  style={{ background: 'white' }}
                />

                {/* Horizontal glitch bars — alternating pink/green */}
                {Array.from({ length: 14 }).map((_, i) => (
                  <motion.div
                    key={i}
                    className="absolute left-0 right-0"
                    initial={{ opacity: 0, x: 0 }}
                    animate={{
                      opacity: [0, 0.85, 0.4, 0.9, 0],
                      x: [0, (i % 2 === 0 ? 1 : -1) * (12 + i * 2), 0],
                    }}
                    transition={{
                      duration: 0.5,
                      delay: 0.08 + i * 0.035,
                      ease: 'easeOut',
                    }}
                    style={{
                      top: `${4 + i * 6.5}%`,
                      height: `${2 + (i % 3)}px`,
                      background: i % 2 === 0
                        ? 'rgba(255,75,193,0.6)' // magenta
                        : 'rgba(0,255,0,0.5)',   // green
                      mixBlendMode: 'screen',
                    }}
                  />
                ))}

                {/* Chromatic aberration flash */}
                <motion.div
                  className="absolute inset-0"
                  initial={{ opacity: 0 }}
                  animate={{ opacity: [0, 0.4, 0] }}
                  transition={{ duration: 0.25, delay: 0.35 }}
                  style={{
                    background: 'linear-gradient(135deg, rgba(255,0,100,0.15), rgba(0,255,0,0.15), rgba(255,230,0,0.1))',
                    mixBlendMode: 'screen',
                  }}
                />
              </motion.div>
            )}
          </AnimatePresence>

          {/* ===== PHASE 2: WIREFRAME ROOM ===== */}
          <AnimatePresence>
            {(phase === 'wireframe' || phase === 'fade_out') && (
              <motion.div
                key="wireframe"
                initial={{ opacity: 0 }}
                animate={{ opacity: phase === 'fade_out' ? 0 : 1 }}
                exit={{ opacity: 0 }}
                transition={{ duration: phase === 'fade_out' ? 0.8 : 0.25 }}
                className="absolute inset-0"
                style={{ background: '#0a0010' }}
              >
                {/* === CRACKED GLASS OVERLAY === */}
                <svg className="absolute inset-0 w-full h-full z-[8] pointer-events-none" viewBox="0 0 1000 600" preserveAspectRatio="none">
                  {/* Impact point 1 — center-right */}
                  {[
                    'M 620,280 L 720,180', 'M 620,280 L 750,320', 'M 620,280 L 580,180',
                    'M 620,280 L 520,350', 'M 620,280 L 700,400', 'M 620,280 L 560,220',
                    'M 620,280 L 680,200', 'M 620,280 L 650,380',
                  ].map((d, i) => (
                    <path key={`c1-${i}`} d={d} fill="none" stroke="rgba(255,255,255,0.08)" strokeWidth="0.5" />
                  ))}
                  {/* Impact point 2 — bottom-left */}
                  {[
                    'M 200,420 L 100,350', 'M 200,420 L 300,500', 'M 200,420 L 150,520',
                    'M 200,420 L 280,380', 'M 200,420 L 120,480', 'M 200,420 L 250,350',
                  ].map((d, i) => (
                    <path key={`c2-${i}`} d={d} fill="none" stroke="rgba(255,255,255,0.06)" strokeWidth="0.5" />
                  ))}
                  {/* Impact point 3 — top-right */}
                  {[
                    'M 820,120 L 900,60', 'M 820,120 L 750,80', 'M 820,120 L 880,180',
                    'M 820,120 L 780,50', 'M 820,120 L 860,200',
