'use client'

import Image from 'next/image'
import { useCallback, useEffect, useRef, useState, type CSSProperties, type KeyboardEvent, type PointerEvent as RPointerEvent, type ReactNode } from 'react'
import { haptic } from '@/lib/haptics'
import { HeroGallery, type GalleryImage } from './hero-gallery'

// ───────────── Stage 1 config: gated gallery entry ─────────────
/** Total cog presses that break the jam and split the hero. */
export const GATE_PRESS_COUNT = 3
/** Fraction of the banner width a half must be dragged before it stays open (0–1). */
export const GATE_DRAG_THRESHOLD = 0.2
/** Effect intensity multiplier for sparks + steam (0 = off, 1 = default, 2 = heavy). */
export const GATE_EFFECT_INTENSITY = 1
/** Idle spark particles around the jammed cog. */
export const GATE_SPARK_COUNT = 5
/** Degrees each press nudges the cog. */
export const GATE_NUDGE_DEG = 9
/** Beam crack duration (ms) before the halves become draggable. */
export const GATE_BEAM_MS = 900
/** Halves slide-in duration on EXIT (ms) before they slam. */
export const GATE_SLAM_MS = 380
/** Impact shake + spark flash after the slam (ms) before the cog re-jams. */
export const GATE_IMPACT_MS = 420
/** Window event the gate listens for to open the gallery. */
export const OPEN_GALLERY_EVENT = 'bv:open-gallery'
// ────────────────────────────────────────────────────────────────

/** Opens the hero gallery: fires `bv:open-gallery` on window; HeroGate swaps the banner for the viewer. */
export function openGallery() {
  window.dispatchEvent(new CustomEvent(OPEN_GALLERY_EVENT))
}

type Phase = 'jammed' | 'cracking' | 'split' | 'gallery' | 'closing' | 'impact'

// Fixed burst table for the slam (SSR-safe): sparks thrown sideways off the seam
const SLAM_SPARKS = [
  { x: -38, y: -10, top: 22 },
  { x: 42, y: -14, top: 30 },
  { x: -30, y: 8, top: 48 },
  { x: 36, y: 12, top: 55 },
  { x: -44, y: -4, top: 70 },
  { x: 28, y: 6, top: 78 },
]
type Side = 'left' | 'right'

// Fixed spark table (SSR-safe, no random values in markup)
const SPARKS = [
  { x: 18, y: -14, d: 0, t: 2.6 },
  { x: -16, y: -10, d: 0.9, t: 3.1 },
  { x: 22, y: 6, d: 1.7, t: 2.9 },
  { x: -6, y: -20, d: 2.4, t: 3.4 },
  { x: 12, y: 16, d: 3.2, t: 2.7 },
  { x: -20, y: 10, d: 1.3, t: 3.6 },
  { x: 4, y: -24, d: 2.9, t: 3.0 },
  { x: 24, y: -4, d: 0.5, t: 3.3 },
]

function cogPath(teeth = 10, outer = 48, inner = 39, hole = 15) {
  const pts: string[] = []
  const step = (Math.PI * 2) / teeth
  for (let i = 0; i < teeth; i++) {
    const a = i * step
    const seq: [number, number][] = [
      [a - step * 0.28, inner],
      [a - step * 0.17, outer],
      [a + step * 0.17, outer],
      [a + step * 0.28, inner],
    ]
    for (const [ang, r] of seq) pts.push(`${(50 + r * Math.cos(ang)).toFixed(2)},${(50 + r * Math.sin(ang)).toFixed(2)}`)
  }
  return `M${pts.join('L')}Z M${50 + hole},50 A${hole},${hole} 0 1 0 ${50 - hole},50 A${hole},${hole} 0 1 0 ${50 + hole},50Z`
}
const COG_D = cogPath()

function JammedCog({ onPress, disabled }: { onPress: () => void; disabled: boolean }) {
  const [presses, setPresses] = useState(0)
  const [kick, setKick] = useState(0)
  const fx = Math.max(0, GATE_EFFECT_INTENSITY)

  const press = () => {
    if (disabled) return
    haptic('press')
    setPresses((p) => p + 1)
    setKick((k) => k + 1)
    onPress()
  }

  return (
    <button
      type="button"
      onClick={press}
      disabled={disabled}
      aria-label={disabled ? 'Cog freed' : `Jammed cog — press to force it (${presses}/${GATE_PRESS_COUNT})`}
      className={`bv-cog ${disabled ? 'is-freed' : ''}`}
      style={{ '--cog-fx': fx } as CSSProperties}
    >
      {!disabled && fx > 0 && (
        <span className="bv-cog-fx" aria-hidden="true">
          {SPARKS.slice(0, GATE_SPARK_COUNT).map((s, i) => (
            <i
              key={i}
              className="bv-cog-spark"
              style={{ '--sx': `${s.x * Math.min(fx, 2)}px`, '--sy': `${s.y * Math.min(fx, 2)}px`, animationDelay: `${s.d}s`, animationDuration: `${s.t}s` } as CSSProperties}
            />
          ))}
          <i className="bv-cog-steam" />
          <i className="bv-cog-steam bv-cog-steam--2" />
        </span>
      )}
      <span className="bv-cog-turn" style={{ transform: `rotate(${presses * GATE_NUDGE_DEG}deg)` }}>
        <span key={kick} className={`bv-cog-body ${kick ? 'is-kicked' : ''}`}>
          <svg viewBox="0 0 100 100" aria-hidden="true">
            <path d={COG_D} fillRule="evenodd" className="bv-cog-metal" />
            <circle cx="50" cy="50" r="24" className="bv-cog-ring" />
            <path d="M62 30 L70 44" className="bv-cog-scratch" />
          </svg>
        </span>
      </span>
    </button>
  )
}

interface DragState {
  side: Side
  id: number
  x0: number
  width: number
}

/**
 * Home hero banner with the gate: jammed cog → gold beam split → draggable halves → "Gallery" →
 * swipeable art viewer → EXIT slams the halves shut and re-jams the cog. Nothing persists between visits.
 * `overlay` (the control-room hotspot) rides on the left half so it stays aligned with the banner full stop.
 */
export function HeroGate({ src, w, h, alt, overlay }: { src: string; w: number; h: number; alt: string; overlay?: ReactNode }) {
  const [phase, setPhase] = useState<Phase>('jammed')
  const [offset, setOffset] = useState<Record<Side, number>>({ left: 0, right: 0 })
  const [open, setOpen] = useState<Record<Side, boolean>>({ left: false, right: false })
  const [dragging, setDragging] = useState<Side | null>(null)
  const [cycle, setCycle] = useState(0)
  const [images, setImages] = useState<GalleryImage[] | null>(null)
  const [failed, setFailed] = useState(false)
  const pressRef = useRef(0)
  const phaseRef = useRef<Phase>('jammed')
  const dragRef = useRef<DragState | null>(null)
  const boxRef = useRef<HTMLDivElement>(null)
  const timers = useRef<number[]>([])

  phaseRef.current = phase
  const later = (fn: () => void, ms: number) => {
    timers.current.push(window.setTimeout(fn, ms))
  }
  const reduced = () => window.matchMedia('(prefers-reduced-motion: reduce)').matches || document.documentElement.classList.contains('bv-reduce')

  useEffect(() => () => timers.current.forEach((t) => window.clearTimeout(t)), [])

  // Fresh gallery list every time the hero splits: admin edits show up without a reload, and images preload
  useEffect(() => {
    if (phase !== 'split') return
    let alive = true
    setFailed(false)
    fetch('/api/gallery', { cache: 'no-store' })
      .then((r) => (r.ok ? r.json() : Promise.reject(new Error(`HTTP ${r.status}`))))
      .then((json) => {
        if (!alive) return
        const list: GalleryImage[] = Array.isArray(json?.images) ? json.images : []
        list.forEach((img) => {
          const pre = new window.Image()
          pre.decoding = 'async'
          pre.src = img.url
        })
        setImages(list)
      })
      .catch((e) => {
        console.error('gallery fetch failed', e)
        if (alive) setFailed(true)
      })
    return () => {
      alive = false
    }
  }, [phase, cycle])

  // openGallery() is the single entry point: it fires the window event, the gate answers it
  useEffect(() => {
    const enter = () => {
      if (phaseRef.current !== 'split') return
      haptic('activate')
      setOpen({ left: true, right: true })
      setPhase('gallery')
    }
    window.addEventListener(OPEN_GALLERY_EVENT, enter)
    return () => window.removeEventListener(OPEN_GALLERY_EVENT, enter)
  }, [])

  const onCogPress = useCallback(() => {
    pressRef.current += 1
    if (pressRef.current < GATE_PRESS_COUNT) return
    haptic('activate')
    setPhase('cracking')
    later(() => {
      setPhase('split')
      haptic('complete')
    }, reduced() ? 0 : GATE_BEAM_MS)
  }, [])

  /** EXIT: halves slide back in and slam, impact, then the cog re-jams with its counter at zero. */
  const exitGallery = useCallback(() => {
    if (phaseRef.current !== 'gallery') return
    haptic('press')
    const calm = reduced()
    setOffset({ left: 0, right: 0 })
    setOpen({ left: false, right: false })
    setPhase('closing')
    later(() => {
      setPhase('impact')
      haptic('complete')
      later(() => {
        pressRef.current = 0
        setCycle((c) => c + 1)
        setPhase('jammed')
        later(() => boxRef.current?.querySelector<HTMLButtonElement>('.bv-cog')?.focus({ preventScroll: true }), 0)
      }, calm ? 0 : GATE_IMPACT_MS)
    }, calm ? 0 : GATE_SLAM_MS)
  }, [])

  const settle = (side: Side, dx: number, width: number) => {
    const past = Math.abs(dx) >= width * GATE_DRAG_THRESHOLD
    setOpen((o) => ({ ...o, [side]: past }))
    setOffset((o) => ({ ...o, [side]: 0 }))
    if (past) haptic('toggle')
  }

  const onDown = (side: Side) => (e: RPointerEvent<HTMLDivElement>) => {
    if (phase !== 'split' || open[side]) return
    if (e.pointerType === 'mouse' && e.button !== 0) return
    // Let the control-room hotspot (and any other control) keep its own click
    if ((e.target as HTMLElement).closest('button, a')) return
    const width = boxRef.current?.offsetWidth ?? 1
    dragRef.current = { side, id: e.pointerId, x0: e.clientX, width }
    e.currentTarget.setPointerCapture(e.pointerId)
    setDragging(side)
  }
  const onMove = (e: RPointerEvent<HTMLDivElement>) => {
    const d = dragRef.current
    if (!d || d.id !== e.pointerId) return
    const raw = e.clientX - d.x0
    // Each half only travels outward; inward pull gets a stiff 12px give
    const dx = d.side === 'left' ? (raw < 0 ? raw : Math.min(raw * 0.15, 12)) : raw > 0 ? raw : Math.max(raw * 0.15, -12)
    setOffset((o) => ({ ...o, [d.side]: dx }))
  }
  const onUp = (e: RPointerEvent<HTMLDivElement>) => {
    const d = dragRef.current
    if (!d || d.id !== e.pointerId) return
    dragRef.current = null
    setDragging(null)
    const raw = e.clientX - d.x0
    settle(d.side, d.side === 'left' ? Math.min(raw, 0) : Math.max(raw, 0), d.width)
  }
  const onKey = (side: Side) => (e: KeyboardEvent<HTMLDivElement>) => {
    if (phase !== 'split') return
    const outward = side === 'left' ? 'ArrowLeft' : 'ArrowRight'
    if (e.key === 'Enter' || e.key === ' ' || e.key === outward) {
      e.preventDefault()
      setOpen((o) => ({ ...o, [side]: true }))
      haptic('toggle')
    }
  }

  const slamming = phase === 'closing' || phase === 'impact'
  const halfStyle = (side: Side): CSSProperties => {
    // Closed halves sit a hairline apart so the beam seam reads as a crack; a slam shuts them flush
    const closed = slamming ? '0px' : side === 'left' ? '-2px' : '2px'
    const base = open[side] ? (side === 'left' ? '-102%' : '102%') : closed
    return { transform: `translate3d(calc(${base} + ${offset[side]}px), 0, 0)`, ...(slamming ? { transitionDuration: `${GATE_SLAM_MS}ms` } : null) }
  }

  const split = phase === 'split'
  const cracked = phase !== 'jammed'
  const inGallery = phase === 'gallery' || slamming
  const revealed = open.left || open.right

  return (
    <div
      ref={boxRef}
      className={`bv-gate ${cracked ? 'is-cracked' : ''} ${split ? 'is-split' : ''} ${slamming ? 'is-slamming' : ''} ${phase === 'impact' ? 'is-impact' : ''}`}
      data-no-swipe={cracked ? '' : undefined}
    >
      {/* Sizer: holds the banner's natural ratio; hidden once the halves take over */}
      <Image
        src={src}
        alt={alt}
        width={w}
        height={h}
        priority
        sizes="100vw"
        className="block w-full h-auto"
        style={{ visibility: cracked ? 'hidden' : 'visible' }}
      />

      {cracked && (
        <>
          <div className={`bv-gate-behind ${revealed ? 'is-revealed' : ''}`}>
            {inGallery ? (
              <HeroGallery images={images} failed={failed} live={phase === 'gallery'} onExit={exitGallery} />
            ) : (
              <button type="button" className="bv-gate-gallery font-anton uppercase" onClick={openGallery} tabIndex={revealed ? 0 : -1}>
                Gallery
              </button>
            )}
          </div>
          {(['left', 'right'] as Side[]).map((side) => (
            <div
              key={side}
              className={`bv-gate-half bv-gate-half--${side} ${dragging === side ? 'is-dragging' : ''} ${open[side] ? 'is-open' : ''}`}
              style={halfStyle(side)}
              onPointerDown={onDown(side)}
              onPointerMove={onMove}
              onPointerUp={onUp}
              onPointerCancel={onUp}
              onKeyDown={onKey(side)}
              role={split && !open[side] ? 'button' : undefined}
              tabIndex={split && !open[side] ? 0 : -1}
              aria-label={split && !open[side] ? `Drag the ${side} half of the banner ${side} to open` : undefined}
              aria-hidden={open[side] || undefined}
            >
              <Image src={src} alt="" fill sizes="100vw" className="object-cover pointer-events-none select-none" draggable={false} />
              <span className="bv-gate-edge" aria-hidden="true" />
              {side === 'left' && !inGallery && overlay}
            </div>
          ))}
          {(phase === 'cracking' || split) && (
            <span className="bv-gate-beam" aria-hidden="true" style={{ '--beam-ms': `${GATE_BEAM_MS}ms` } as CSSProperties} />
          )}
          {phase === 'impact' && (
            <span className="bv-gate-slam" aria-hidden="true" style={{ '--slam-ms': `${GATE_IMPACT_MS}ms` } as CSSProperties}>
              {SLAM_SPARKS.map((s, i) => (
                <i key={i} style={{ '--sx': `${s.x}px`, '--sy': `${s.y}px`, top: `${s.top}%` } as CSSProperties} />
              ))}
            </span>
          )}
        </>
      )}

      {!cracked && overlay}

      <JammedCog key={cycle} onPress={onCogPress} disabled={cracked} />
    </div>
  )
}

