interface HeroSectionProps {
  games: PublicGame[]
  content: SiteContentMap
  /** per-page hero (home): banner by default, editable in the admin PAGE HEROES tab */
  hero: HeroConfig
  showArchiveLink?: boolean
}

const FALLBACK_ART = '/assets/window-interior-bg.png'

function displayHost(link: string) {
  try {
    return new URL(link).host
  } catch {
    return link
  }
}

export function HeroSection({ games, content, hero: pageHero, showArchiveLink = true }: HeroSectionProps) {
  const list = games ?? []
  // The hero always fronts a free unit: locked units live in the archive behind the paywall
  const free = list.filter((g) => !g.locked)
  const hero = free.find((g) => g.featured) ?? free.find((g) => g.status === 'active') ?? null
  const others = list.filter((g) => g.id !== hero?.id).length

  const router = useRouter()
  const toArchive = () => {
    haptic('press')
    router.push('/games')
  }

  return (
    <section id="works" className="bv-field relative flex flex-col" style={{ paddingTop: 'calc(56px + env(safe-area-inset-top))', backgroundColor: 'var(--col-black)' }}>
      <h1 className="sr-only">
        {content.titleLine1} {content.titleLine2} {content.titleLine3}
      </h1>
      <PageHero hero={pageHero} gate />

      <div className="relative max-w-[1280px] mx-auto w-full px-4 md:px-8 py-10 md:py-16">
        {hero ? (
          <HeroFeature
            game={hero}
            others={others}
            onArchive={toArchive}
            ctaLabel={content.ctaLabel}
            steam={isOn(content.steam) && !isOn(content.haunt)}
            showReadouts={isOn(content.showReadouts)}
            showArchiveLink={showArchiveLink}
            mobileBar={isOn(content.mobileCtaBar)}
          />
        ) : showArchiveLink ? (
          <button onClick={toArchive} className="font-ibm text-sm uppercase min-h-[44px]" style={{ color: 'var(--col-bone)' }}>
            NO UNIT FEATURED — OPEN THE GAMES →
          </button>
        ) : (
          <p className="font-ibm text-sm uppercase" style={{ color: 'var(--col-bone)' }}>NO UNIT FEATURED</p>
        )}
      </div>
    </section>
  )
}

interface FeatureProps {
  game: PublicGame
  others: number
  onArchive: () => void
  ctaLabel: string
  steam: boolean
  showReadouts: boolean
  showArchiveLink: boolean
  mobileBar: boolean
}

function HeroFeature({ game, others, onArchive, ctaLabel, steam, showReadouts, showArchiveLink, mobileBar }: FeatureProps) {
  const slabRef = useRef<HTMLDivElement>(null)
  const ctaRowRef = useRef<HTMLDivElement>(null)
  const [readoutState, setReadoutState] = useState<LaunchState>('idle')
  const [showBar, setShowBar] = useState(false)
  const onStateChange = useCallback((s: LaunchState) => setReadoutState(s), [])
  const art = game.imageUrl || FALLBACK_ART

  const seq = useLaunchSequence({
    targetRef: slabRef,
    title: game.title,
    launchLink: game.launchLink,
    linkTarget: game.linkTarget,
    status: game.status,
    imageUrl: art,
    onStateChange,
  })
  useSteamSystem({ containerRef: slabRef, paused: !steam || seq.state === 'activating' })

  // Sticky phone bar appears only after the in-hero button has scrolled out of view
  useEffect(() => {
    if (!mobileBar) return
    const el = ctaRowRef.current
    if (!el || typeof IntersectionObserver === 'undefined') return
    const io = new IntersectionObserver(([e]) => setShowBar(!e.isIntersecting && e.boundingClientRect.top < 0), { threshold: 0 })
    io.observe(el)
    return () => io.disconnect()
  }, [mobileBar])

  const hot = seq.state === 'ready' || seq.state === 'activating'
  const words = game.title.split(/\s+/).filter(Boolean)
  const ctaText = seq.isComingSoon ? 'SIGNAL OFFLINE' : seq.hasLink ? 'TAKE A BITE' : 'LINK PENDING'

  const onKey = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault()
      seq.activate()
    }
  }

  return (
    <div
      className="frame-corners relative flex-1 grid grid-cols-1 md:grid-cols-12 gap-8 md:gap-12 items-center p-5 sm:p-7 md:p-10"
      style={{
        border: '1px solid var(--col-steel)',
        background: 'linear-gradient(180deg, rgb(var(--bv-text-strong-rgb) / 0.06) 0%, rgb(var(--bv-text-strong-rgb) / 0) 14%), radial-gradient(90% 70% at 18% 30%, rgb(var(--bv-primary-rgb) / 0.08), transparent 60%), linear-gradient(160deg, var(--bv-surface-3) 0%, var(--col-gunmetal) 35%, var(--col-black) 78%)',
        boxShadow: 'inset 0 1px 0 rgb(var(--bv-text-strong-rgb) / 0.1), 0 30px 70px rgb(var(--bv-shadow-rgb) / 0.6)',
