        <span className="font-oswald text-[11px] uppercase tracking-[0.35em]" style={{ color: 'var(--col-bone)' }}>FEATURED UNIT</span>
        <span className="font-ibm text-[11px] uppercase tracking-wider" style={{ color: 'var(--col-yellow)' }}>{seq.isComingSoon ? 'OFFLINE' : 'FREE TO PLAY'}</span>
      </div>
      {/* The window: owner art slab */}
      <div className="md:col-span-5 flex justify-center md:justify-start">
        <div className="frame-corners relative w-full max-w-[250px] sm:max-w-[320px] md:max-w-none md:w-auto md:h-[min(66vh,640px)]" style={{ aspectRatio: '2 / 3' }}>
