            onClick={seq.activate}
            onKeyDown={onKey}
            onMouseEnter={seq.arm}
            onMouseLeave={seq.disarm}
            onFocus={seq.arm}
            onBlur={seq.disarm}
            className="absolute inset-0 overflow-hidden cursor-pointer select-none outline-none focus-visible:ring-2 focus-visible:ring-[var(--col-yellow)]"
            style={{
              backgroundColor: 'var(--col-black)',
              border: hot ? '1px solid var(--col-yellow)' : '1px solid var(--col-steel)',
              filter: seq.flashing ? 'brightness(1.35)' : undefined,
              transform: seq.state === 'activating' ? 'scale(0.985)' : hot ? 'translate(-3px,-3px)' : undefined,
              transition: 'transform 260ms cubic-bezier(0.2,0.8,0.2,1)',
              boxShadow: '0 28px 60px rgb(var(--bv-shadow-rgb) / 0.6)',
            }}
          >
            <Image
              src={art}
              alt={`${game.title} key art`}
              fill
              priority
              unoptimized={art.startsWith('http')}
              className="object-cover"
              sizes="(max-width: 768px) 360px, 460px"
              style={{
                filter: seq.isComingSoon ? 'grayscale(1) brightness(0.4)' : hot ? 'saturate(1.15) brightness(1.05)' : 'saturate(0.95) brightness(0.92)',
