'use client'

import { useEffect } from 'react'
import { addSeconds, applyPrefs, readPrefs } from '@/lib/operator'

/** Applies operator prefs site-wide and counts visible-tab time in the machine (client-side only). */
export function OperatorClock() {
  useEffect(() => {
    applyPrefs(readPrefs())
    let pending = 0
    const tick = window.setInterval(() => {
      if (document.visibilityState !== 'visible') return
      pending += 1
      if (pending >= 5) { addSeconds(pending); pending = 0 }
    }, 1000)
    const flush = () => { if (pending) { addSeconds(pending); pending = 0 } }
    document.addEventListener('visibilitychange', flush)
    window.addEventListener('pagehide', flush)
    return () => {
      window.clearInterval(tick)
      flush()
      document.removeEventListener('visibilitychange', flush)
      window.removeEventListener('pagehide', flush)
    }
  }, [])
  return null
}

