'use client';

/**
 * ManagerVoice — his muttering in the margins of home (MANDATED FEATURE — do not remove).
 *
 * Distinct from ManagerVision (the full-screen perception takeover). This is the
 * quieter half of his presence: every so often a short hand-scrawled line fades
 * into a corner of the hub, like he left a note on the edge of your vision, then
 * it's gone. Domestic-creepy when you're calm; watchful then menacing as heat
 * climbs. Text-only — zero asset weight.
 *
 * Hydration-safe: lines are only ever chosen inside useEffect (no Math.random /
 * Date.now in render; first paint is deterministic null). Honours
 * prefers-reduced-motion (rarer, no drift).
 */

import { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

// Tiered by heat. No emojis, his register — soft and domestic low down,
// turning watchful then bladed as the room heats up.
const CALM_LINES = [
  'the place looks tidy today.',
  'you fed them. good.',
  'i like it when it stays this quiet.',
  'the kettle went cold again.',
  'leave the hall light on for me.',
  'home. say it back.',
  "you've been sitting there a while.",
  "nice. everyone's accounted for.",
];
const WATCH_LINES = [
  "someone's been counting.",
  "they're getting comfortable. interesting.",
  "don't get attached to them.",
  'i can hear the floorboards from here.',
  "you didn't lock the back room.",
  'still watching you watch them.',
  'i moved something. find it.',
];
const HOT_LINES = [
  'they know your face now.',
  'tick. tick.',
  "you're running out of room.",
  "i'm already at the door.",
  'smile. they can see you.',
  'this was always going to end here.',
  "don't make me come home.",
];

interface Note { seed: number; text: string; }

function pickLine(lvl: number, seed: number): string {
  const pool = lvl >= 7 ? HOT_LINES : lvl >= 4 ? WATCH_LINES : CALM_LINES;
  return pool[Math.floor(seed * pool.length)];
}

export default function ManagerVoice({ level }: { level: number }) {
  const lvl = Math.max(0, Math.min(10, level ?? 0));

  const [reduced, setReduced] = useState(false);
  const [note, setNote] = useState<Note | null>(null);
  const loopRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const endRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // reduced-motion detection (matches project pattern)
  useEffect(() => {
    if (typeof window === 'undefined') return;
    const mql = window.matchMedia('(prefers-reduced-motion: reduce)');
    setReduced(mql.matches);
    const onChange = (e: MediaQueryListEvent) => setReduced(e.matches);
    mql.addEventListener?.('change', onChange);
    return () => mql.removeEventListener?.('change', onChange);
  }, []);

  // scheduler — gentle and sparse when calm, insistent when hot
  useEffect(() => {
    let cancelled = false;

    const schedule = () => {
      if (cancelled) return;
      // calm (lvl0): ~50-90s.  hot (lvl10): ~14-26s.  reduced motion: much rarer.
      const base = Math.max(12000, 52000 - lvl * 4000);
      const jitter = base * 0.7;
      let wait = base + Math.random() * jitter;
      if (reduced) wait *= 2.4;
      loopRef.current = setTimeout(() => {
        if (cancelled) return;
        const seed = Math.random();
        setNote({ seed, text: pickLine(lvl, seed) });
        // the line lingers, then is gone
        const dur = reduced ? 4200 : 5200 + Math.random() * 1800;
        endRef.current = setTimeout(() => {
          if (cancelled) return;
          setNote(null);
          schedule();
        }, dur);
      }, wait);
    };

    schedule();
    return () => {
      cancelled = true;
      if (loopRef.current) clearTimeout(loopRef.current);
      if (endRef.current) clearTimeout(endRef.current);
    };
  }, [lvl, reduced]);

  // colour warms toward bone-white and tightens as heat climbs
  const ink = lvl >= 7 ? 'rgba(243,232,207,0.62)' : lvl >= 4 ? 'rgba(201,180,143,0.5)' : 'rgba(185,170,138,0.42)';
  const tilt = note ? (note.seed > 0.5 ? -1.4 : 1.2) : 0;

  return (
    <div className="pointer-events-none absolute inset-0 z-[38] overflow-hidden" aria-hidden="true">
      <AnimatePresence>
        {note && (
          <motion.div
            key={`${note.text}-${note.seed}`}
            className="absolute bottom-7 left-4 max-w-[62%] sm:max-w-[44%]"
            initial={{ opacity: 0, x: -10, filter: 'blur(2px)' }}
            animate={{
              opacity: 1,
              x: 0,
              filter: 'blur(0px)',
              ...(reduced ? {} : { y: [0, -1.5, 0] }),
            }}
            exit={{ opacity: 0, x: 6, filter: 'blur(2px)' }}
            transition={{
              opacity: { duration: 0.9, ease: 'easeOut' },
              x: { duration: 0.9, ease: 'easeOut' },
              filter: { duration: 0.9 },
              y: reduced ? undefined : { duration: 5, repeat: Infinity, ease: 'easeInOut' },
            }}
            style={{ transform: `rotate(${tilt}deg)` }}
          >
            <span
              className="block font-caveat leading-tight"
              style={{
                color: ink,
                fontSize: 'clamp(1.05rem, 3.2vw, 1.45rem)',
                textShadow: lvl >= 7 ? '0 0 10px rgba(168,104,126,0.25)' : '0 0 8px rgba(0,0,0,0.6)',
                mixBlendMode: 'screen',
              }}
            >
              {note.text}
            </span>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

