// ==================================================
// DAILY CREW CONSUMPTION ("CRACKHEAD TAX")
// --------------------------------------------------
// Runs ONCE at day-end, before the night cycle.
// Every recruited NPC drinks / smokes / chases the ghost — the player pays
// the bill.
//
// Per NPC per day:
//   - cigarettes : 1 base + (toleranceCigs   > 3 ? 1 : 0)
//   - alcohol    : 1 base + (toleranceAlc    > 3 ? 1 : 0)   (only if recruited has toleranceAlc > 0)
//   - weed       : 1       if toleranceWeed  > 0
//   - crystals   : 1       if toleranceCryst > 4 (only the hard users)
//
// PRESENCE mitigation (formerly CONSTITUTION):
//   The player's PRESENCE stat reduces total consumption by 6% per point,
//   capped at a 45% reduction (ceil'd, min 0).
//
// The server is authoritative — never deduct resources on the client.
// Returns the exact per-resource breakdown so the day_end ledger can display
// it down to the last cigarette.
// ==================================================
export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const { sessionId } = body ?? {};
    if (!isValidId(sessionId)) {
      return NextResponse.json({ error: 'Missing sessionId' }, { status: 400 });
    }

    const session = await prisma.gameSession.findUnique({
      where: { id: sessionId },
      include: { npcs: true, resources: true },
    });
    if (!session) {
      return NextResponse.json({ error: 'Session not found' }, { status: 404 });
    }

    const recruitedNpcs = (session.npcs ?? []).filter((n: any) => !!n?.recruited);

    // Tally raw consumption across the whole crew.
    const raw: Record<string, number> = { cigarettes: 0, alcohol: 0, weed: 0, crystals: 0 };
    for (const npc of recruitedNpcs) {
      raw.cigarettes += 1 + ((npc.toleranceCigs ?? 0) > 3 ? 1 : 0);
      if ((npc.toleranceAlc ?? 0) > 0) raw.alcohol += 1 + ((npc.toleranceAlc ?? 0) > 3 ? 1 : 0);
      if ((npc.toleranceWeed ?? 0) > 0) raw.weed += 1;
      if ((npc.toleranceCryst ?? 0) > 4) raw.crystals += 1;
    }

    // Apply PRESENCE mitigation (formerly constitution).
    const presence = Math.max(0, Math.min(10, session.presence ?? 2));
    const mitigation = Math.min(0.45, presence * 0.06);
    const afterMitigation: Record<string, number> = {};
    for (const [type, qty] of Object.entries(raw)) {
      afterMitigation[type] = Math.max(0, Math.floor(qty * (1 - mitigation)));
    }

    // Deduct from resource table, clamping to 0.
    const consumed: { type: string; requested: number; actual: number; remaining: number }[] = [];
    for (const [type, requested] of Object.entries(afterMitigation)) {
      if (requested <= 0) {
        const row = (session.resources ?? []).find((r: any) => r.type === type);
        consumed.push({
          type,
          requested: 0,
          actual: 0,
          remaining: row?.quantity ?? 0,
        });
        continue;
      }
      const row = (session.resources ?? []).find((r: any) => r.type === type);
      const have = row?.quantity ?? 0;
      const actual = Math.min(have, requested);
      if (row && actual > 0) {
        await prisma.resource.update({
          where: { id: row.id },
          data: { quantity: Math.max(0, have - actual) },
        });
      }
      consumed.push({
        type,
        requested,
        actual,
        remaining: Math.max(0, have - actual),
      });
    }

    return NextResponse.json({
      crewSize: recruitedNpcs.length,
      presence,
      mitigationPct: Math.round(mitigation * 100),
      consumed,
    });
  } catch (err: unknown) {
    console.error('Consume (crackhead tax) error:', err);
    return NextResponse.json({ error: 'Failed' }, { status: 500 });
  }
}

