export const dynamic = 'force-dynamic';

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { MAX_ENERGY, ENERGY_COST } from '@/lib/game-data';
import { isValidId } from '@/lib/api-guards';

// ==================================================
// SCROUNGE — Safety-valve resource action
// --------------------------------------------------
// Costs 1 energy. Once per day.
// INSIGHT stat influences yields: base 1-2 cigs + bonus items at higher insight.
// ==================================================

const MAX_RESOURCE = 30;

// ──────────────────────────────────────────────
// CREW SCAVENGING ASSIST — risk/reward modifiers
// Only 1 NPC can assist per scrounge session.
// ──────────────────────────────────────────────
const CREW_SCAVENGE_MODIFIERS: Record<string, {
  cigsBonus: number;       // extra cigs (added to base)
  alcChanceMod: number;    // additive % to alcohol chance
  weedChanceMod: number;   // additive % to weed chance
  crystalChance: number;   // flat % chance to find a crystal
  heatMod: number;         // additive heat (can be negative)
  label: string;
}> = {
  dave:   { cigsBonus: 0,  alcChanceMod: 0.05, weedChanceMod: 0.05, crystalChance: 0,    heatMod: -1, label: 'QUIET APPROACH — less heat, slight bonus finds' },
  tamara: { cigsBonus: 1,  alcChanceMod: 0.10, weedChanceMod: 0.00, crystalChance: 0,    heatMod: 0,  label: 'HYPERVIGILANT — extra cigs, better alcohol odds' },
  sid:    { cigsBonus: 1,  alcChanceMod: 0.05, weedChanceMod: 0.15, crystalChance: 0.08, heatMod: 2,  label: 'RECKLESS — high yield, high heat, crystal chance' },
  mikey:  { cigsBonus: 1,  alcChanceMod: 0.10, weedChanceMod: 0.10, crystalChance: 0.05, heatMod: 0,  label: 'VETERAN SCAVENGER — balanced bonus across the board' },
};

export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const { sessionId, assistantNpcId } = body ?? {};
    if (!isValidId(sessionId)) {
      return NextResponse.json({ error: 'Missing sessionId' }, { status: 400 });
    }

    const session = await prisma.gameSession.findUnique({
      where: { id: sessionId },
      include: { npcs: true },
    });
    if (!session) {
      return NextResponse.json({ error: 'Session not found' }, { status: 404 });
    }

    // Check daily limit
    if (session.scroungedToday) {
      return NextResponse.json({
        error: 'already_scrounged',
        message: 'You already picked over the alley today. Come back tomorrow.',
      }, { status: 409 });
    }

    // Check energy
    const energyUsed = session.energyUsed ?? 0;
    const energyLeft = MAX_ENERGY - energyUsed;
    if (energyLeft < ENERGY_COST.scrounge) {
      return NextResponse.json({
        error: 'no_energy',
        message: 'Too exhausted. Get some sleep.',
      }, { status: 409 });
    }

    // Validate assistant NPC (optional — only 1 per session)
    let assistant: typeof CREW_SCAVENGE_MODIFIERS[string] | null = null;
    let assistantName = '';
    if (assistantNpcId && typeof assistantNpcId === 'string') {
      const npc = (session.npcs ?? []).find((n: any) => n.id === assistantNpcId && n.recruited);
      if (npc) {
        const key = (npc.name ?? '').toLowerCase();
        assistant = CREW_SCAVENGE_MODIFIERS[key] ?? null;
        assistantName = npc.name;
      }
    }

    // INSIGHT stat influences scrounge yields:
    // Base: 1-2 cigs, 20% alcohol chance
    // Per insight point above 2: +5% alcohol chance, +10% weed chance (from 0)
    const insight = Math.max(0, Math.min(10, session.insight ?? 2));
    const insightBonus = Math.max(0, insight - 2); // 0-8 range

    // v1.5 — increased base yields slightly: 2-3 cigs (was 1-2), +5% base alcohol
    const cigsFound = Math.floor(Math.random() * 2) + 2 + (assistant?.cigsBonus ?? 0); // 2-3 base + crew bonus
    const alcChance = 0.25 + (insightBonus * 0.05) + (assistant?.alcChanceMod ?? 0); // 25-65% + crew mod
    const alcFound = Math.random() < Math.min(alcChance, 0.85) ? 1 : 0; // cap at 85%
    const weedChance = (insightBonus * 0.10) + (assistant?.weedChanceMod ?? 0); // 0-80% + crew mod
    const weedFound = Math.random() < Math.min(weedChance, 0.90) ? 1 : 0;
    // Crystal chance: only with crew assist (Sid/Mikey)
    const crystalChance = assistant?.crystalChance ?? 0;
    const crystalFound = crystalChance > 0 && Math.random() < crystalChance ? 1 : 0;
    const heatGain = Math.max(0, 1 + (assistant?.heatMod ?? 0));

    // Apply resources (capped at MAX_RESOURCE)
    const results: { type: string; gained: number; newTotal: number }[] = [];

    // Cigarettes
    const cigRow = await prisma.resource.upsert({
      where: { sessionId_type: { sessionId, type: 'cigarettes' } },
      update: { quantity: { increment: cigsFound } },
      create: { sessionId, type: 'cigarettes', quantity: cigsFound },
    });
    if (cigRow.quantity > MAX_RESOURCE) {
      await prisma.resource.update({
        where: { sessionId_type: { sessionId, type: 'cigarettes' } },
        data: { quantity: MAX_RESOURCE },
      });
      cigRow.quantity = MAX_RESOURCE;
    }
    results.push({ type: 'cigarettes', gained: cigsFound, newTotal: cigRow.quantity });

    // Alcohol
    if (alcFound > 0) {
      const alcRow = await prisma.resource.upsert({
        where: { sessionId_type: { sessionId, type: 'alcohol' } },
        update: { quantity: { increment: alcFound } },
        create: { sessionId, type: 'alcohol', quantity: alcFound },
      });
      if (alcRow.quantity > MAX_RESOURCE) {
        await prisma.resource.update({
          where: { sessionId_type: { sessionId, type: 'alcohol' } },
          data: { quantity: MAX_RESOURCE },
        });
        alcRow.quantity = MAX_RESOURCE;
      }
      results.push({ type: 'alcohol', gained: alcFound, newTotal: alcRow.quantity });
    }

    // Weed (insight bonus + crew mod)
    if (weedFound > 0) {
      const weedRow = await prisma.resource.upsert({
        where: { sessionId_type: { sessionId, type: 'weed' } },
        update: { quantity: { increment: weedFound } },
        create: { sessionId, type: 'weed', quantity: weedFound },
      });
      if (weedRow.quantity > MAX_RESOURCE) {
        await prisma.resource.update({
          where: { sessionId_type: { sessionId, type: 'weed' } },
          data: { quantity: MAX_RESOURCE },
        });
        weedRow.quantity = MAX_RESOURCE;
      }
      results.push({ type: 'weed', gained: weedFound, newTotal: weedRow.quantity });
    }

    // Crystals (crew assist only — Sid/Mikey)
    if (crystalFound > 0) {
      const crystRow = await prisma.resource.upsert({
        where: { sessionId_type: { sessionId, type: 'crystals' } },
        update: { quantity: { increment: crystalFound } },
        create: { sessionId, type: 'crystals', quantity: crystalFound },
      });
      if (crystRow.quantity > MAX_RESOURCE) {
        await prisma.resource.update({
          where: { sessionId_type: { sessionId, type: 'crystals' } },
          data: { quantity: MAX_RESOURCE },
        });
        crystRow.quantity = MAX_RESOURCE;
      }
      results.push({ type: 'crystals', gained: crystalFound, newTotal: crystRow.quantity });
    }

    // Apply heat + mark scrounged + spend energy
    await prisma.gameSession.update({
      where: { id: sessionId },
      data: {
        heat: { increment: heatGain },
        scroungedToday: true,
        energyUsed: { increment: ENERGY_COST.scrounge },
      },
    });

    return NextResponse.json({
      ok: true,
      loot: results,
      heatGain,
      newHeat: (session.heat ?? 0) + heatGain,
      energySpent: ENERGY_COST.scrounge,
      assistant: assistant ? { name: assistantName, label: assistant.label } : null,
    });
  } catch (err: unknown) {
    console.error('Scrounge error:', err);
    return NextResponse.json({ error: 'Scrounge failed' }, { status: 500 });
  }
}

