// Each tone produces "anchor words" the player must identify.

export type EncounterTone = 'RIGID' | 'HESITANT' | 'CLINICAL';

export interface ToneDefinition {
  label: string;
  description: string;
  /** The vice that counters this tone (§5.3). */
  counterVice: ResourceKey;
  /** Anchor words that signal this tone in encounter dialogue. */
  anchors: readonly string[];
}

export const TONE_DEFINITIONS: Record<EncounterTone, ToneDefinition> = {
  RIGID: {
    label: 'Rigid',
    description: 'Authoritarian, rule-bound speech. Structures the world as regulations.',
