    anchors: ['Protocol', 'Policy', 'Unauthorized', 'Ordinance', 'Prohibited', 'Scheduled'],
  },
  HESITANT: {
    label: 'Hesitant',
    description: 'Uncertain, stuttering speech. Wants to act but fears consequences.',
    counterVice: 'alcohol',
    anchors: ['Listen', 'Actually', 'Trying', 'S-sorry', 'Wait', 'Warning'],
  },
  CLINICAL: {
    label: 'Clinical',
    description: 'Detached, data-driven speech. Reduces everything to metrics.',
    counterVice: 'crystals',
    anchors: ['Calculated', 'Expected', 'Stable', 'Normal', 'Logic', 'Predicted'],
  },
} as const;

// ─── Counter-Approach Map ────────────────────────────────────────────────────
// Vice → approach label shown to the player when they use the right substance.

export const COUNTER_APPROACH: Record<ResourceKey, string> = {
  weed: 'Creative',
  alcohol: 'Confident',
  crystals: 'Erratic',
  cigarettes: 'Fog Lifter', // cigarettes counter The Fog, not a tone
} as const;

// ─── Tone → Counter lookup (convenience) ────────────────────────────────────

export function getCounterVice(tone: EncounterTone): ResourceKey {
  return TONE_DEFINITIONS[tone].counterVice;
}

export function getAnchors(tone: EncounterTone): readonly string[] {
  return TONE_DEFINITIONS[tone].anchors;
}

// ─── The Fog (§5.4) ─────────────────────────────────────────────────────────
// Cigarette-specific mechanic. In high-heat areas, text is blotted/redacted.
// Having cigarettes allocated to crew restores full visibility.

export interface FogRule {
  /** Heat threshold at which fog begins to redact text. */
  heatThreshold: number;
  /** Description of the mechanic for UI tooltips. */
  description: string;
  /** The resource that counters The Fog. */
  counterVice: 'cigarettes';
}

