/**
 * Tiny haptic helper.  Wrapped in try/catch because navigator.vibrate is
 * absent on iOS Safari and locked behind a user-gesture quota everywhere
 * else.  Failures are fine — silent fallback to "no haptics".
 */
function tinyVibrate(pattern: number | number[]) {
  if (typeof navigator === 'undefined') return;
  if (typeof (navigator as any).vibrate !== 'function') return;
  try { (navigator as any).vibrate(pattern); } catch { /* ignore */ }
}

interface Props {
  onComplete: () => void;
}

type RitualId = 'nightlight' | 'lullaby' | 'thumb';

interface Ritual {
  id: RitualId;
  numeral: string;
  glyph: string; // small inline SVG path d= (kept as fallback if image fails)
  image: string; // comic illustration (v0.6.0)
  title: string;
  directive: string;
  subtext: string;
  confirm: string;
}

// The three bedtime rituals.  All three must be confirmed before the screen
// will black out and the night audio will play.
const RITUALS: Ritual[] = [
  {
    id: 'nightlight',
    numeral: 'I.',
    glyph:
      'M 32 50 C 20 50 12 40 16 28 C 12 26 12 18 18 16 C 20 12 26 10 32 14 C 38 10 44 12 46 16 C 52 18 52 26 48 28 C 52 40 44 50 32 50 Z M 24 28 L 26 28 M 38 28 L 40 28',
