    directive: 'TURN ON THE NIGHT LIGHT SHAPED LIKE AN ANIMAL.',
    subtext: 'The bear. The elephant. Whichever one you still own.',
    confirm: 'THE LIGHT IS ON',
  },
  {
    id: 'lullaby',
    numeral: 'II.',
    glyph:
      'M 18 46 a 4 4 0 1 0 8 0 a 4 4 0 1 0 -8 0 M 26 46 L 26 18 L 46 14 L 46 42 M 38 42 a 4 4 0 1 0 8 0 a 4 4 0 1 0 -8 0',
    image: '/images/ritual-lullaby-tape.jpg',
