/**
 * NIGHT CYCLE SCREEN
 *
 * Between the hub (day-end) and the blackout, the player must perform three
 * regressive rituals.  All three prompts must be confirmed on the device
 * before the screen hands off to night_blackout.  Partial completion keeps
 * the screen active and cycles a nag overlay at the bottom.
 */
export default function NightCycleScreen({ onComplete }: Props) {
  const [confirmed, setConfirmed] = useState<Record<RitualId, boolean>>({
    nightlight: false,
    lullaby: false,
    thumb: false,
  });
  const [nagCount, setNagCount] = useState(0);
  const [advancing, setAdvancing] = useState(false);

  const allDone = confirmed.nightlight && confirmed.lullaby && confirmed.thumb;

  const handleConfirm = useCallback((id: RitualId) => {
    if (advancing) return;
    setConfirmed((prev) => {
      if (prev[id]) return prev;
      // Per-ritual SFX + haptic feedback.  Each ritual gets a tactile and
      // sonic signature to make the bedtime sequence feel intimate.
      switch (id) {
        case 'nightlight':
          // Domestic switch flip, then a glassy chime as the light comes on.
          playLightSwitchClick();
          tinyVibrate(40);
          setTimeout(() => playNightlightTwinkle(), 110);
          break;
        case 'lullaby':
          // Music-box chime — unique lullaby sound.
          audioManager.playSFX('lullaby');
          tinyVibrate([35, 50, 35]);
          break;
        case 'thumb':
          // The wet, intimate one.  Long single buzz to feel pressed-into.
          playPacifierSlide();
          tinyVibrate(180);
          break;
      }
      return { ...prev, [id]: true };
    });
  }, [advancing]);

  // Nag the user if they try to skip ahead without finishing.
  useEffect(() => {
    if (allDone) return;
    const handler = (e: KeyboardEvent) => {
      if (e.key === 'Enter' || e.key === ' ' || e.key === 'Escape') {
        e.preventDefault();
        setNagCount((n) => n + 1);
      }
    };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, [allDone]);

  const handleProceed = useCallback(() => {
    if (!allDone || advancing) return;
    setAdvancing(true);
    audioManager.playSFX('nav');
    // Tiny fade-to-black: a soft whimper + a long, fading buzz.
    setTimeout(() => {
      playBedtimeWhimper();
      tinyVibrate([220, 120, 200, 140, 180]);
    }, 80);
    // Give the whimper room to start before we hand off to the blackout.
    setTimeout(() => onComplete(), 1200);
  }, [allDone, advancing, onComplete]);

  return (
    <div
      className="w-full h-full relative overflow-hidden flex flex-col items-center justify-center px-4 sm:px-8 py-6"
      role="region"
      aria-label="Night cycle rituals"
      style={{
        background:
          'radial-gradient(ellipse at 50% 55%, #1a1826 0%, #0a0a14 55%, #030308 100%)',
      }}
    >
      {/* Mother's Shrine — the persistent visual anchor of the night */}
      <motion.div
        className="absolute inset-0 pointer-events-none"
        initial={{ opacity: 0 }}
        animate={{ opacity: allDone ? 0.55 : 0.32 }}
        transition={{ duration: 1.4, ease: 'easeOut' }}
      >
        <Image
          src="/images/ritual-mothers-shrine.jpg"
          alt="Night ritual imagery"
          fill
          priority
          className="object-cover"
          style={{ filter: 'saturate(0.78) brightness(0.62) contrast(1.08)' }}
        />
        <div className="absolute inset-0" style={{
          background: 'radial-gradient(ellipse at 50% 38%, rgba(0,0,0,0.0) 28%, rgba(8,6,12,0.72) 100%)',
        }} />
      </motion.div>

      {/* Starry / bedroom dust */}
      <div
        className="absolute inset-0 opacity-[0.06] pointer-events-none"
        style={{
          backgroundImage:
            'repeating-radial-gradient(circle at 18% 22%, rgba(200,210,255,0.22) 0px, transparent 1.5px, transparent 14px), repeating-radial-gradient(circle at 75% 68%, rgba(160,120,220,0.18) 0px, transparent 1.5px, transparent 17px)',
          backgroundSize: '180px 180px, 220px 220px',
        }}
      />

      {/* Breathing vignette */}
      <motion.div
        className="absolute inset-0 pointer-events-none"
        animate={{ opacity: [0.6, 1, 0.6] }}
        transition={{ duration: 5, repeat: Infinity, ease: 'easeInOut' }}
        style={{
          background: 'radial-gradient(ellipse at center, transparent 55%, rgba(0,0,0,0.9) 100%)',
        }}
      />

      <motion.div
        initial={{ opacity: 0, y: 18 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.9 }}
        className="relative z-10 w-full max-w-3xl"
      >
        {/* Header */}
        <div className="text-center mb-6 sm:mb-8">
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 0.55 }}
            transition={{ delay: 0.3, duration: 1.2 }}
            className="font-terminal text-[10px] tracking-[0.5em] text-[#c8dc96]/60 mb-3"
          >
            — NIGHT CYCLE —
          </motion.div>
          <motion.h1
            initial={{ opacity: 0, y: 8 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.5, duration: 0.9 }}
            className="font-typewriter text-3xl sm:text-4xl text-[#d8d0b8] tracking-wide"
          >
            Before You Sleep
          </motion.h1>
          <motion.p
            initial={{ opacity: 0 }}
            animate={{ opacity: 0.7 }}
            transition={{ delay: 1.0, duration: 1 }}
            className="font-typewriter text-[11px] sm:text-xs text-[#a8a090] mt-3 max-w-lg mx-auto leading-relaxed"
          >
            Three small things. Every night. The same order. It is the only way you ever learned.
          </motion.p>
        </div>

        {/* Ritual rows */}
        <div className="space-y-3 sm:space-y-4">
          {RITUALS.map((r, i) => {
            const isDone = !!confirmed[r.id];
            return (
              <motion.div
                key={r.id}
                initial={{ opacity: 0, x: -16 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: 0.8 + i * 0.2, duration: 0.6 }}
                className={`relative flex items-center gap-4 sm:gap-5 p-3 sm:p-4 border-l-[3px] transition-colors ${
                  isDone
                    ? 'border-l-[#c8dc96] bg-[rgba(200,220,150,0.05)]'
                    : 'border-l-[#6b4226] bg-[rgba(12,10,18,0.72)]'
                }`}
              >
                {/* Numeral + glyph */}
                <div className="flex flex-col items-center flex-shrink-0 w-16 sm:w-20">
                  <div
                    className={`font-typewriter text-[11px] tracking-widest mb-1 transition-colors ${
                      isDone ? 'text-[#c8dc96]' : 'text-[#8a7a6a]'
                    }`}
                  >
                    {r.numeral}
                  </div>
                  <div
                    className="relative w-14 h-14 sm:w-16 sm:h-16 grimy-border overflow-hidden"
                    aria-hidden="true"
                  >
                    <Image
                      src={r.image}
                      alt={r.title}
                      fill
                      sizes="64px"
                      className="object-cover transition-all duration-700"
                      style={{
                        filter: isDone
                          ? 'saturate(1.05) brightness(0.96) contrast(1.04)'
                          : 'saturate(0.45) brightness(0.62) contrast(1.05) sepia(0.18)',
                      }}
                    />
                    {/* faint scanline overlay */}
                    <div
                      className="absolute inset-0 pointer-events-none mix-blend-overlay opacity-30"
                      style={{
                        backgroundImage:
                          'repeating-linear-gradient(0deg, rgba(0,0,0,0.55) 0px, rgba(0,0,0,0.55) 1px, transparent 1px, transparent 3px)',
                      }}
                    />
                    {isDone && (
                      <div
                        className="absolute inset-0 ring-1 ring-[#c8dc96]/55"
                        style={{ boxShadow: 'inset 0 0 14px rgba(200,220,150,0.35)' }}
                      />
                    )}
                    <svg
                      width="20"
                      height="20"
                      viewBox="0 0 64 64"
                      fill="none"
                      stroke={isDone ? '#c8dc96' : '#8a7a6a'}
                      strokeWidth="2.4"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      className="absolute bottom-0.5 right-0.5 opacity-80 drop-shadow-[0_0_2px_rgba(0,0,0,0.85)]"
                      aria-hidden="true"
                    >
                      <path d={r.glyph} />
                    </svg>
                  </div>
                </div>

                {/* Copy */}
                <div className="flex-1 min-w-0">
                  <div
                    className={`font-terminal text-[10px] sm:text-[11px] tracking-[0.3em] mb-1 transition-colors ${
                      isDone ? 'text-[#c8dc96]' : 'text-[#b89a2a]/80'
                    }`}
                  >
                    {r.title}
                  </div>
                  <div className="font-typewriter text-sm sm:text-base text-[#d8d0b8] leading-snug">
                    {r.directive}
                  </div>
                  <div className="font-typewriter text-[10px] sm:text-[11px] text-[#8a8070] mt-1 italic leading-snug">
                    {r.subtext}
                  </div>
                </div>

                {/* Confirm button / checkmark */}
                <div className="flex-shrink-0">
                  {isDone ? (
                    <motion.div
                      initial={{ scale: 0.6, opacity: 0 }}
                      animate={{ scale: 1, opacity: 1 }}
                      transition={{ type: 'spring', stiffness: 280, damping: 16 }}
                      className="w-10 h-10 sm:w-11 sm:h-11 border border-[#c8dc96]/70 flex items-center justify-center text-[#c8dc96]"
                      aria-label={`${r.title} confirmed`}
                    >
                      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                        <path d="M5 12 L10 17 L19 7" />
                      </svg>
                    </motion.div>
                  ) : (
                    <button
                      onClick={() => handleConfirm(r.id)}
                      aria-label={r.confirm}
                      className="font-terminal text-[10px] sm:text-[11px] tracking-[0.22em] px-4 py-2 sm:py-2.5 border border-[#b89a2a]/40 text-[#b89a2a] hover:text-[#CCAA00] hover:border-[#CCAA00]/70 transition-all active:scale-95 min-h-[44px] min-w-[120px] focus:outline-none focus-visible:ring-1 focus-visible:ring-[#CCAA00]/60"
                    >
                      {r.confirm}
                    </button>
                  )}
                </div>
              </motion.div>
            );
          })}
        </div>

        {/* Proceed button — only active once all three confirmed */}
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 1.6 }}
          className="mt-8 flex flex-col items-center gap-3"
        >
          {!allDone ? (
            <>
              <div
                className="font-typewriter text-[11px] sm:text-xs text-[#8a8070] tracking-wide text-center"
                aria-live="polite"
              >
                {Object.values(confirmed).filter(Boolean).length} / 3 complete — you cannot sleep until all three are done.
              </div>
              <AnimatePresence>
                {nagCount > 0 && (
                  <motion.div
                    key={nagCount}
                    initial={{ opacity: 0, y: -4 }}
                    animate={{ opacity: 0.85, y: 0 }}
                    exit={{ opacity: 0 }}
                    className="font-typewriter text-[10px] text-[#b89a2a] italic"
                    role="alert"
                    aria-live="assertive"
                  >
