              disabled={advancing}
              aria-label="Close your eyes and sleep"
              className="font-terminal text-xs sm:text-sm tracking-[0.28em] px-8 py-3 border border-[#c8dc96]/70 text-[#c8dc96] hover:bg-[#c8dc96] hover:text-[#0a0a14] transition-all active:scale-95 min-h-[48px] disabled:opacity-40 focus:outline-none focus-visible:ring-1 focus-visible:ring-[#c8dc96]/60"
