// ── Haptic Feedback ────────────────────────────────────────────
function haptic(pattern: number | number[]) {
  try { if (typeof navigator !== 'undefined' && (navigator as any)?.vibrate) (navigator as any).vibrate(pattern); } catch {}
}

// ── Designation Calculator ─────────────────────────────────────
function getDesignation(stats: Record<StatKey, number>): string {
  const { nerve: n, insight: i, presence: p, mobility: m } = stats;
  const mx = Math.max(n, i, p, m);
  // Two-stat combos first
  if (n === mx && i === mx) return 'VANGUARD';
  if (n === mx && p === mx) return 'ENFORCER';
  if (n === mx && m === mx) return 'OPERATIVE';
  if (i === mx && p === mx) return 'ARBITRATOR';
  if (i === mx && m === mx) return 'INFILTRATOR';
  if (p === mx && m === mx) return 'ENVOY';
  // Single dominant
  if (n === mx) return 'ENFORCER';
  if (i === mx) return 'ANALYST';
  if (p === mx) return 'ARBITRATOR';
  if (m === mx) return 'SCAVENGER';
  return 'SPECIALIST';
}

