  // ── Render: Stat Chart ──
  const renderStatChart = () => {
    const stats = computeStats();
    return (
      <div className="mb-4 p-3" style={{ border: `1px solid ${A.border}`, background: 'rgba(255,174,25,0.02)' }}>
        <div className="font-bmf-mono text-[9px] tracking-[0.2em] mb-2.5" style={{ color: A.dark }}>STAT REFERENCE — WHAT YOU&apos;RE CHOOSING</div>
        <div className="grid grid-cols-2 gap-2">
          {(Object.keys(STAT_INFO) as StatKey[]).map(key => {
