      {/* ── Main Content Area ── */}
      <div className="flex-1 flex overflow-hidden relative z-40">

        {/* Left Column — Interaction Space */}
        <div className="flex-1 overflow-auto p-4 sm:p-6 lg:p-8 flex items-start justify-center">
          <AnimatePresence mode="wait">

            {/* ══════ FILED — Transmission Confirmed ══════ */}
            {filed && (
              <motion.div key="filed" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="max-w-lg w-full text-center py-20">
                <motion.div
                  initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }}
                  transition={{ delay: 0.3, duration: 0.5 }}
                >
                  <div className="font-bmf-mono text-[10px] tracking-[0.3em] mb-4" style={{ color: A.dark }}>TRANSMISSION CONFIRMED</div>
                  <div className="w-16 h-px mx-auto mb-6" style={{ background: A.borderHi }} />
                  <h2 className="font-bmf-mono text-2xl sm:text-3xl tracking-wider mb-2" style={{ color: A.bright }}>
                    DOSSIER FILED
                  </h2>
                  <div className="font-bmf-mono text-[10px] tracking-[0.2em] mb-8" style={{ color: A.mid }}>
                    RECORD: {recordIdRef.current}
                  </div>
                  <div className="inline-block p-4" style={{ border: `1px solid ${A.border}`, background: A.glow }}>
                    <div className="font-bmf-mono text-sm tracking-wider" style={{ color: A.bright }}>
                      {playerName.trim() || getDesignation(computeStats())}
                    </div>
                    <div className="font-bmf-mono text-[9px] mt-1" style={{ color: A.dark }}>
                      DESIGNATION: {getDesignation(computeStats())}
                    </div>
                  </div>
                  <motion.div
                    initial={{ opacity: 0 }} animate={{ opacity: 1 }}
                    transition={{ delay: 1.5 }}
                    className="mt-10 font-bmf-mono text-[10px] tracking-[0.15em]"
                    style={{ color: A.dim }}
                  >
                    COMMENCING INTAKE SEQUENCE...
                    <motion.span
                      animate={{ opacity: [1, 0] }}
                      transition={{ repeat: Infinity, duration: 0.8 }}
                    > _</motion.span>
                  </motion.div>
                </motion.div>
              </motion.div>
            )}

            {/* ══════ STEP 1: NAME ══════ */}
            {!filed && step === 'name' && (
              <motion.div key="name" initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -12 }} transition={{ duration: 0.3 }} className="max-w-2xl w-full">
                {sectionHead('CLINICAL HISTORY \u2014 SUBJECT IDENTIFICATION', 'Department of Child Welfare \u2014 Behavioural Assessment Division')}

                <div className="space-y-6">
                  <div className="font-bmf-mono text-[9px] flex items-center gap-2" style={{ color: A.dark }}>
                    <span className="tracking-wider">CLASSIFICATION:</span>
                    <span style={{ color: A.bright }}>RESTRICTED — WELFARE ACT §7.1</span>
                  </div>

                  <div className="pb-3 relative">
                    <div className="absolute bottom-0 left-0 right-0 h-px" style={{ background: A.border }} />
                    <span className="font-bmf-mono text-[10px] tracking-wider block mb-2" style={{ color: A.dark }}>SUBJECT DESIGNATION</span>
                    <input
                      type="text"
                      value={playerName}
                      onChange={(e) => setPlayerName(e.target.value)}
                      placeholder="Manager"
                      maxLength={20}
                      className="w-full bg-transparent font-bmf-mono text-xl py-2 px-0 focus:outline-none border-none"
                      style={{
                        color: A.bright,
                        caretColor: A.bright,
                        borderBottom: `1px solid ${A.border}`,
                      }}
                    />
                  </div>

                  <div className="p-3" style={{ border: `1px solid ${A.border}`, background: 'rgba(255,174,25,0.02)' }}>
                    <p className="font-bmf-mono text-[9px] leading-relaxed italic" style={{ color: A.dark }}>
                      &quot;The following assessment is compiled from extant welfare records, medical histories,
                      and caseworker observations. The subject&apos;s cooperation is noted but not required.
                      Proceed to Section A: Injury History.&quot;
                    </p>
                    <p className="font-bmf-mono text-[8px] mt-2 tracking-wider" style={{ color: A.dim }}>
                      — DR. K. HALLORAN, BEHAVIOURAL ASSESSMENT DIV.
                    </p>
                  </div>
                </div>

                {renderNav(undefined, 'BEGIN ASSESSMENT \u2192')}
              </motion.div>
            )}

            {/* ══════ STEP 2: INJURY HISTORY ══════ */}
            {!filed && step === 'injury' && (
              <motion.div key="injury" initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -12 }} transition={{ duration: 0.3 }} className="max-w-2xl w-full">
                {sectionHead('SECTION A: INJURY HISTORY', 'Select the most significant physical incident from the subject\'s medical record.')}
                {renderStatChart()}
                <div className="space-y-2">
                  {INJURY_OPTIONS.map(opt =>
                    renderCard(
                      { ...opt },
                      selectedInjury === opt.id,
                      () => setSelectedInjury(opt.id),
                      `+2 ${opt.statLabel}`,
                    )
                  )}
                </div>
                {renderNav('BACK', selectedInjury ? 'PROCEED TO SECTION B \u2192' : 'SELECT AN ENTRY')}
              </motion.div>
            )}

            {/* ══════ STEP 3: CHILDHOOD TRAUMA ══════ */}
            {!filed && step === 'trauma' && (
              <motion.div key="trauma" initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -12 }} transition={{ duration: 0.3 }} className="max-w-2xl w-full">
                {sectionHead('SECTION B: TRAUMA EVALUATION', 'Identify the primary developmental trauma from the subject\'s psychosocial record.')}
                {renderStatChart()}
                <div className="space-y-2">
                  {TRAUMA_OPTIONS.map(opt =>
                    renderCard(
                      { ...opt },
                      selectedTrauma === opt.id,
                      () => setSelectedTrauma(opt.id),
                      `+2 ${opt.statLabel}`,
                    )
                  )}
                </div>
                {renderNav('BACK', selectedTrauma ? 'PROCEED TO SECTION C \u2192' : 'SELECT AN ENTRY')}
              </motion.div>
            )}

            {/* ══════ STEP 4: INHERITANCE ══════ */}
            {!filed && step === 'inheritance' && (
              <motion.div key="inheritance" initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -12 }} transition={{ duration: 0.3 }} className="max-w-2xl w-full">
                {sectionHead('SECTION C: INHERITANCE', 'Personal effects released to subject upon reaching age of majority. Select item on file.')}
                <div className="space-y-2">
                  {INHERITANCE_OPTIONS.map(opt => {
                    const r = opt.resources;
                    const parts: string[] = [];
                    if (r.cigarettes > 0) parts.push(`${r.cigarettes}c`);
                    if (r.alcohol > 0) parts.push(`${r.alcohol}a`);
                    if (r.weed > 0) parts.push(`${r.weed}w`);
                    if (r.crystals > 0) parts.push(`${r.crystals}x`);
                    return renderCard(
                      { ...opt },
                      selectedInheritance === opt.id,
                      () => setSelectedInheritance(opt.id),
                      parts.join(' / '),
                    );
                  })}
                </div>
                {renderNav('BACK', selectedInheritance ? 'REVIEW DOSSIER \u2192' : 'SELECT AN ITEM')}
              </motion.div>
            )}

            {/* ══════ STEP 5: DOSSIER REVIEW ══════ */}
            {!filed && step === 'confirm' && (
              <motion.div key="confirm" initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -12 }} transition={{ duration: 0.3 }} className="max-w-2xl w-full">
                {sectionHead('DOSSIER REVIEW', 'Confirm subject profile. There is no revision after filing.')}

                <div className="relative p-4 sm:p-5" style={{ border: `1px solid ${A.border}`, background: 'rgba(255,174,25,0.02)' }}>

                  {/* Designation */}
                  <div className="flex items-baseline gap-3 mb-4 pb-3" style={{ borderBottom: `1px solid ${A.border}` }}>
                    <span className="font-bmf-mono text-[9px] tracking-wider" style={{ color: A.dark }}>DESIGNATION</span>
                    <span className="font-bmf-mono text-xl" style={{ color: A.bright }}>{playerName || getDesignation(computeStats())}</span>
                    <span className="font-bmf-mono text-[8px] ml-auto tracking-wider" style={{ color: A.dim }}>
                      [{getDesignation(computeStats())}]
                    </span>
                  </div>

                  {/* Clinical History */}
                  <div className="space-y-3 mb-4 pb-3" style={{ borderBottom: `1px solid ${A.border}` }}>
                    <div className="font-bmf-mono text-[9px] tracking-wider mb-2" style={{ color: A.dark }}>CLINICAL HISTORY</div>
                    {(() => {
                      const injury = INJURY_OPTIONS.find(o => o.id === selectedInjury);
                      const trauma = TRAUMA_OPTIONS.find(o => o.id === selectedTrauma);
                      const inh = INHERITANCE_OPTIONS.find(o => o.id === selectedInheritance);
                      return (
                        <>
                          {injury && (
                            <div className="flex items-baseline gap-2">
                              <span className="font-bmf-mono text-[8px] w-16 flex-shrink-0" style={{ color: A.dark }}>INJURY</span>
                              <span className="font-bmf-mono text-[10px]" style={{ color: A.mid }}>{injury.label}</span>
                              <span className="font-bmf-mono text-[8px] ml-auto" style={{ color: A.bright }}>+2 {injury.statLabel}</span>
                            </div>
                          )}
                          {trauma && (
                            <div className="flex items-baseline gap-2">
                              <span className="font-bmf-mono text-[8px] w-16 flex-shrink-0" style={{ color: A.dark }}>TRAUMA</span>
                              <span className="font-bmf-mono text-[10px]" style={{ color: A.mid }}>{trauma.label}</span>
                              <span className="font-bmf-mono text-[8px] ml-auto" style={{ color: A.bright }}>+2 {trauma.statLabel}</span>
                            </div>
                          )}
                          {inh && (
                            <div className="flex items-baseline gap-2">
                              <span className="font-bmf-mono text-[8px] w-16 flex-shrink-0" style={{ color: A.dark }}>INHERIT</span>
                              <span className="inline-flex items-center gap-1 font-bmf-mono text-[10px]" style={{ color: A.mid }}>{inh.icon} {inh.label}</span>
                            </div>
                          )}
                        </>
                      );
                    })()}
                  </div>

                  {/* Derived Attributes */}
                  <div className="space-y-2.5 mb-4 pb-3" style={{ borderBottom: `1px solid ${A.border}` }}>
                    <div className="font-bmf-mono text-[9px] tracking-wider mb-2" style={{ color: A.dark }}>DERIVED ATTRIBUTES</div>
                    {(() => {
                      const stats = computeStats();
                      return (Object.keys(STAT_INFO) as StatKey[]).map(key => {
                        const val = stats[key];
                        return (
                          <div key={key} className="flex items-center gap-3">
                            <span className="font-bmf-mono text-[10px] w-20 flex-shrink-0 tracking-wider" style={{ color: A.mid }}>
                              {STAT_INFO[key].label}
                            </span>
                            <div className="flex-1 flex items-center gap-[2px]">
                              {Array.from({ length: 6 }).map((_, i) => (
                                <div key={i} className="flex-1 h-2.5 transition-all" style={{
                                  background: i < val ? A.glow : 'transparent',
                                  border: `1px solid ${i < val ? A.borderHi : A.border}`,
                                  boxShadow: i < val ? `0 0 4px ${A.glow}` : 'none',
                                }} />
                              ))}
                            </div>
                            <span className="font-bmf-mono text-sm w-5 text-right flex-shrink-0" style={{ color: A.bright }}>{val}</span>
                          </div>
                        );
                      });
                    })()}
                  </div>

                  {/* Starting Provisions */}
                  {(() => {
                    const res = computeResources();
                    return (
                      <div className="mb-4 pb-3" style={{ borderBottom: `1px solid ${A.border}` }}>
                        <div className="font-bmf-mono text-[9px] tracking-wider mb-2" style={{ color: A.dark }}>STARTING PROVISIONS</div>
                        <div className="grid grid-cols-4 gap-3">
                          {res.cigarettes > 0 && (
                            <div className="flex flex-col items-center gap-1 p-2" style={{ border: `1px solid ${A.border}`, background: A.glow }}>
                              <CigaretteIcon size={16} color={A.bright} />
                              <span className="font-bmf-mono text-[10px]" style={{ color: A.bright }}>×{res.cigarettes}</span>
                            </div>
                          )}
                          {res.alcohol > 0 && (
                            <div className="flex flex-col items-center gap-1 p-2" style={{ border: `1px solid ${A.border}`, background: A.glow }}>
                              <AlcoholIcon size={16} color={A.bright} />
                              <span className="font-bmf-mono text-[10px]" style={{ color: A.bright }}>×{res.alcohol}</span>
                            </div>
                          )}
                          {res.weed > 0 && (
                            <div className="flex flex-col items-center gap-1 p-2" style={{ border: `1px solid ${A.border}`, background: A.glow }}>
                              <WeedIcon size={16} color={A.bright} />
                              <span className="font-bmf-mono text-[10px]" style={{ color: A.bright }}>×{res.weed}</span>
                            </div>
                          )}
                          {res.crystals > 0 && (
                            <div className="flex flex-col items-center gap-1 p-2" style={{ border: `1px solid ${A.border}`, background: A.glow }}>
                              <CrystalIcon size={16} color={A.bright} />
                              <span className="font-bmf-mono text-[10px]" style={{ color: A.bright }}>×{res.crystals}</span>
                            </div>
                          )}
                        </div>
                      </div>
                    );
                  })()}

                  {/* Signature */}
                  <SignatureCanvas onSign={setSigned} />

                  {/* Stamp */}
                  <div className="mt-4 pt-3" style={{ borderTop: `1px solid ${A.border}` }}>
                    <p className="font-bmf-mono text-[8px] tracking-wider" style={{ color: A.dim }}>CLASSIFIED // BAF3K-INTAKE-REV3 // DO NOT DISTRIBUTE</p>
                  </div>
                </div>

                {/* Submit buttons */}
                <div className="flex gap-3 mt-5">
                  <motion.button whileTap={{ scale: 0.97 }} onClick={goBack}
                    className="flex-1 py-3 font-bmf-mono text-[10px] tracking-wider transition-all min-h-[48px]"
                    style={{ border: `1px solid ${A.border}`, color: A.dark }}>
                    ← BACK
                  </motion.button>
                  <motion.button
                    whileTap={{ scale: 0.97 }}
                    disabled={submitting}
                    onClick={handleSubmit}
                    className="flex-1 py-3.5 font-bmf-mono text-xs tracking-[0.15em] transition-all disabled:opacity-50 min-h-[48px]"
                    style={{
                      border: `1px solid ${A.borderHi}`,
                      color: A.bright,
                      background: A.glow,
                      boxShadow: `0 0 16px ${A.glow}`,
                    }}
                  >
                    {submitting ? 'TRANSMITTING...' : 'FILE DOSSIER & BEGIN \u2192'}
                  </motion.button>
                </div>
              </motion.div>
            )}

          </AnimatePresence>
        </div>

        {/* Right Column — Rorschach Panel (desktop only) */}
        {!filed && (
          <div className="hidden lg:flex w-56 xl:w-64 flex-col items-center justify-center border-l p-4"
            style={{ borderColor: A.border, background: 'rgba(255,174,25,0.015)' }}>
            <div className="font-bmf-mono text-[8px] tracking-[0.2em] mb-4 text-center" style={{ color: A.dim }}>
              PSYCH EVAL // RORSCHACH
            </div>
            <div className="w-full max-w-[180px]">
              <ProceduralRorschach stepIdx={stepIdx} />
            </div>
            <div className="font-bmf-mono text-[7px] text-center mt-4 px-2 leading-relaxed" style={{ color: A.dark }}>
              {RORSCHACH_READINGS[stepIdx]}
            </div>
            <div className="mt-4 w-full h-px" style={{ background: A.border }} />
            <div className="font-bmf-mono text-[7px] mt-2 text-center" style={{ color: A.dim }}>
              CARD {stepIdx + 1} OF {STEP_ORDER.length}
            </div>
          </div>
        )}
      </div>

      {/* ── Bottom Toggle Bar ── */}
      {!filed && (
        <div className="flex-shrink-0 flex items-center justify-between px-4 sm:px-6 py-2 z-40"
          style={{ borderTop: `1px solid ${A.border}` }}>
          <div className="flex items-center gap-3">
            <button
              onClick={() => setCrtOn(!crtOn)}
              className="font-bmf-mono text-[8px] tracking-wider px-2 py-1 transition-all"
              style={{
                color: crtOn ? A.bright : A.dim,
                border: `1px solid ${crtOn ? A.borderHi : A.border}`,
                background: crtOn ? A.glow : 'transparent',
              }}
            >
              CRT {crtOn ? 'ON' : 'OFF'}
            </button>
            <button
              onClick={() => setHumOn(!humOn)}
              className="font-bmf-mono text-[8px] tracking-wider px-2 py-1 transition-all"
              style={{
                color: humOn ? A.bright : A.dim,
                border: `1px solid ${humOn ? A.borderHi : A.border}`,
                background: humOn ? A.glow : 'transparent',
              }}
            >
              HUM {humOn ? 'ON' : 'OFF'}
            </button>
          </div>
          <span className="font-bmf-mono text-[7px] tracking-[0.15em]" style={{ color: A.dim }}>
            BUM-3K INTAKE TERMINAL v3.1
          </span>
        </div>
      )}
    </div>
  );
}

// TRAVEL MAP PANEL (v1.1.0) — BMF3K Template Console aesthetic
'use client';

import { useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Lock, MapPin, Footprints, ArrowRight } from 'lucide-react';
import { playHover } from '@/lib/sound-effects';
import {
  TRAVEL_NODES,
  TRAVEL_ROUTES,
  getHomeNode,
  getRouteBetween,
  isNodeUnlocked,
  type TravelNode,
} from '@/lib/travel-map';
import type { ResourceKey } from '@/lib/game-data';
import { audioManager } from '@/app/_lib/audio-manager';

interface Props {
  selectedKey: string | null;
  completedMissionKeys: Set<string>;
  onSelect: (key: string) => void;
  currentNodeKey?: string;
}

const DIFFICULTY_COLORS: Record<number, string> = {
  1: 'var(--bmf-green)',
  2: 'var(--bmf-amber)',
  3: 'var(--bmf-paper-dim)',
  4: 'var(--bmf-magenta)',
  5: 'var(--bmf-danger)',
};

const RESOURCE_LABELS: Record<string, string> = {
  cigarettes: 'CIG',
  alcohol: 'ALC',
  weed: 'WED',
  crystals: 'CRY',
};

function CostDisplay({ cost }: { cost: Partial<Record<ResourceKey, number>> }) {
  const entries = Object.entries(cost).filter(([, v]) => v && v > 0);
  if (entries.length === 0) return <span style={{ color: 'var(--bmf-text-faint)' }}>FREE</span>;
  return (
    <span className="flex items-center gap-1.5 flex-wrap">
      {entries.map(([k, v]) => (
        <span key={k} style={{ color: 'var(--bmf-paper)' }}>
          {v} {RESOURCE_LABELS[k] ?? k.toUpperCase()}
        </span>
      ))}
    </span>
  );
}

/** Difficulty pips — filled squares up to level, dimmed for rest */
function DifficultyPips({ level }: { level: number }) {
  return (
    <span className="font-bmf-mono text-[10px] tracking-[0.06em]" aria-label={`Difficulty ${level} of 5`}>
      {Array.from({ length: 5 }, (_, i) => (
        <span key={i} style={{ color: i < level ? DIFFICULTY_COLORS[level] : 'var(--bmf-text-faint)', opacity: i < level ? 1 : 0.3 }}>
          ■
        </span>
      ))}
    </span>
  );
}

export default function TravelMapPanel({
  selectedKey,
  completedMissionKeys,
  onSelect,
  currentNodeKey,
}: Props) {
  const home = getHomeNode();
  const currentKey = currentNodeKey ?? home.key;

  const selectedNode: TravelNode | null =
    TRAVEL_NODES.find((n) => n.key === selectedKey) ?? null;

  const directRoute = useMemo(() => {
    if (!selectedKey || selectedKey === currentKey) return null;
    return getRouteBetween(currentKey, selectedKey);
  }, [currentKey, selectedKey]);

  return (
    <div className="flex flex-col gap-3">
      {/* Map viewport — hatched panel */}
      <div
        className="bmf-panel-hatched relative w-full overflow-hidden"
        style={{ aspectRatio: '16 / 9' }}
        role="img"
        aria-label="Travel map showing 6 district nodes with connecting routes"
      >
        {/* Deep background gradient */}
        <div
          className="absolute inset-0 pointer-events-none"
          style={{
            background:
              'radial-gradient(ellipse at 50% 80%, rgba(33,30,25,0.6) 0%, rgba(17,16,14,0.3) 50%, transparent 100%)',
          }}
        />

        {/* Route lines — SVG dashed */}
        <svg
          className="absolute inset-0 w-full h-full pointer-events-none"
          viewBox="0 0 100 100"
          preserveAspectRatio="none"
          aria-hidden="true"
        >
          {TRAVEL_ROUTES.map((route) => {
            const fn = TRAVEL_NODES.find((n) => n.key === route.from);
            const tn = TRAVEL_NODES.find((n) => n.key === route.to);
            if (!fn || !tn) return null;
            const isLit =
              directRoute?.id === route.id ||
              (selectedKey &&
                ((route.from === currentKey && route.to === selectedKey) ||
                  (route.to === currentKey && route.from === selectedKey)));
            return (
              <line
                key={route.id}
                x1={fn.mapPos.x}
                y1={fn.mapPos.y}
                x2={tn.mapPos.x}
                y2={tn.mapPos.y}
                stroke={isLit ? 'var(--bmf-magenta)' : 'var(--bmf-paper-faint)'}
                strokeWidth={isLit ? 0.6 : 0.35}
                strokeDasharray={isLit ? '1.8 1' : '1.2 1.5'}
                strokeOpacity={isLit ? 0.85 : 0.3}
                strokeLinecap="round"
                className={isLit ? 'bmf-route-line' : ''}
              />
            );
          })}
        </svg>

        {/* Node cards */}
        {TRAVEL_NODES.map((node) => {
          const unlocked = isNodeUnlocked(node, completedMissionKeys);
          const isSelected = selectedKey === node.key;
          const isCurrent = node.key === currentKey;

          return (
            <button
              key={node.key}
              type="button"
              disabled={!unlocked || isCurrent}
              onClick={() => {
                if (!unlocked) return;
                audioManager.playSFX('nav');
                onSelect(node.key);
              }}
              onMouseEnter={() => unlocked && playHover()}
              className="bmf-node group"
              style={{
                left: `${node.mapPos.x}%`,
                top: `${node.mapPos.y}%`,
                transform: 'translate(-50%, -50%)',
                cursor: unlocked && !isCurrent ? 'pointer' : isCurrent ? 'default' : 'not-allowed',
                ...(isSelected
                  ? {
                      borderColor: 'var(--bmf-magenta)',
                      boxShadow: 'var(--bmf-shadow-glow-magenta)',
                    }
                  : isCurrent
                    ? {
                        borderColor: 'var(--bmf-green)',
                        boxShadow: 'var(--bmf-shadow-glow-green)',
                      }
                    : {}),
                ...(!unlocked ? { opacity: 0.42, filter: 'saturate(0.4)' } : {}),
              }}
              data-active={isSelected ? 'true' : undefined}
              data-locked={!unlocked ? 'true' : undefined}
              aria-label={`${node.name} — ${node.district} — difficulty ${node.difficulty}${unlocked ? '' : ' (locked)'}${isSelected ? ' (selected)' : ''}${isCurrent ? ' (you are here)' : ''}`}
              aria-pressed={isSelected}
            >
              {/* Icon + label cluster */}
              <div className="flex items-center gap-1.5">
                <span style={{ color: isCurrent ? 'var(--bmf-green)' : isSelected ? 'var(--bmf-magenta)' : 'var(--bmf-paper-dim)', fontSize: 14 }}>
                  {isCurrent ? (
                    <Footprints size={14} />
                  ) : unlocked ? (
                    <MapPin size={13} />
