              <div className="text-right shrink-0">
                <p className="font-bmf-mono text-[10px] tracking-[0.12em] uppercase" style={{ color: 'var(--bmf-text-faint)' }}>DIFFICULTY</p>
                <div className="mt-0.5">
                  <DifficultyPips level={selectedNode.difficulty} />
                </div>
              </div>
            </div>
            {directRoute ? (
              <div className="flex items-center gap-2 mt-2 pt-2 font-bmf-mono text-[11px]" style={{ borderTop: '1px solid var(--bmf-border)' }}>
                <ArrowRight size={12} style={{ color: 'var(--bmf-magenta)' }} />
                <span style={{ color: 'var(--bmf-text-muted)' }}>
                  {directRoute.steps} steps ·{' '}
