            ) : selectedKey && selectedKey !== currentKey ? (
              <div className="mt-2 pt-2" style={{ borderTop: '1px solid var(--bmf-border)' }}>
                <p className="font-bmf-mono text-[10px] italic" style={{ color: 'var(--bmf-text-faint)' }}>
