            ) : null}
          </motion.div>
        ) : (
          <motion.div
            key="empty"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="bmf-panel p-3 text-center"
            style={{ borderStyle: 'dashed' }}
          >
            <p className="font-bmf-mono text-xs italic" style={{ color: 'var(--bmf-text-faint)' }}>
