import type { GameState } from '../game-client';
import { type EscalationState } from '@/lib/escalation';
import { audioManager } from '@/app/_lib/audio-manager';

interface Props {
  game: GameState;
  escalation: EscalationState;
  onBack: () => void;
  onRefresh: () => Promise<void>;
  showNotification: (msg: string) => void;
}

const COFFEES = [
  { key: 'black',    label: 'BLACK COFFEE', stat: 'nerve',    desc: 'Bitter. Keeps your hands steady.',      color: '#FF6B35', icon: Zap },
  { key: 'mocha',    label: 'MOCHA',        stat: 'insight',   desc: 'Sweet enough to think clearly.',       color: '#C49A6C', icon: Eye },
  { key: 'espresso', label: 'ESPRESSO',     stat: 'presence',  desc: 'Thick. Makes people notice you.',      color: '#8B4513', icon: Users },
  { key: 'instant',  label: 'INSTANT',      stat: 'MOBILITY',  desc: 'Tastes like dirt. Legs feel lighter.',  color: '#DAA520', icon: Wind },
] as const;

const STAT_LABELS: Record<string, string> = { nerve: 'NERVE', insight: 'INSIGHT', presence: 'PRESENCE', MOBILITY: 'MOBILITY' };

const BREW_LINES = [
  'Grinding something... might be beans.',
  'Water temperature: hot enough.',
  'Cup dispensed. Slightly cracked.',
  'Adding... substance.',
  'Machine shuddering. Normal.',
  'BREWMATIC 3000 — "BETTER THAN NOTHING"',
];

function CoffeeStation({ game, escalation, onBack, onRefresh, showNotification }: Props) {
  const [brewing, setBrewing] = useState(false);
  const [brewLine, setBrewLine] = useState('');
  const [result, setResult] = useState<{ stat: string; value: number; changed: boolean; label: string; message?: string; coffeesRemaining?: number; lifetimeCap?: boolean } | null>(null);
  const [usedToday, setUsedToday] = useState(false);

  // Check if already used today on mount
  useEffect(() => {
    try {
      const stored = localStorage.getItem(`coffee_day_${game?.sessionId}`);
      if (stored && Number(stored) >= (game?.day ?? 0)) setUsedToday(true);
    } catch {}
  }, [game?.sessionId, game?.day]);

  const lifetimeUsed = game?.totalCoffees ?? 0;
  const lifetimeLeft = Math.max(0, MAX_LIFETIME_COFFEES - lifetimeUsed);
  const maxedOut = lifetimeLeft <= 0;
  const disabled = usedToday || maxedOut || brewing;

  const handleBrew = useCallback(async (coffeeKey: string) => {
    if (disabled || !game?.sessionId) return;
    setBrewing(true);
    setResult(null);

    // Brewing animation — cycle through lines
    const lines = [...BREW_LINES].sort(() => Math.random() - 0.5);
    for (let i = 0; i < 3; i++) {
      setBrewLine(lines[i % lines.length]);
      await new Promise(r => setTimeout(r, 700));
    }

    try {
      audioManager.playSFX('nav');
      const res = await fetch('/api/game/kitchen/coffee', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ sessionId: game.sessionId, coffeeType: coffeeKey }),
      });

      if (res.status === 409) {
        setUsedToday(true);
        try { localStorage.setItem(`coffee_day_${game.sessionId}`, String(game.day)); } catch {}
        showNotification('One cup per shift. Come back tomorrow.');
        setBrewing(false);
        setBrewLine('');
        return;
      }

      const data = await res.json();
      if (!res.ok) {
        showNotification(data?.message || data?.error || 'Machine jammed.');
        setBrewing(false);
        setBrewLine('');
        return;
      }

      setResult(data);
      setUsedToday(true);
      try { localStorage.setItem(`coffee_day_${game.sessionId}`, String(game.day)); } catch {}
      await onRefresh();

      if (data.changed) {
        showNotification(`${data.label} consumed — ${(data.stat ?? '').toUpperCase()} → ${data.value}`);
