      </div>

      {/* Status banner */}
      <div className="relative z-10 mx-4 mb-3 px-3 py-2" style={{ background: 'rgba(var(--pop-rgb),0.06)', border: '1px solid rgba(var(--pop-rgb),0.15)' }}>
        <p className="font-terminal text-[10px] tracking-wider text-[#b0a890] text-center">
          {usedToday
            ? '[DISPENSED] — COME BACK NEXT SHIFT'
