'use client'

import { useEffect, useRef, useState } from 'react'
import { createPortal } from 'react-dom'
import { haptic } from '@/lib/haptics'

const TOLERANCE = 14 // degrees either side of upside down
const norm = (a: number) => ((a % 360) + 360) % 360
const isInverted = (a: number) => Math.abs(norm(a) - 180) <= TOLERANCE

type Props = {
  /** null = no profile yet (seal is shown but will not turn) */
  signedIn: boolean
  unsealed: boolean
  onUnsealed: () => void
}

export function SealDial({ signedIn, unsealed, onUnsealed }: Props) {
  const [angle, setAngle] = useState(unsealed ? 180 : 0)
  const [dragging, setDragging] = useState(false)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [tear, setTear] = useState(false)
  const discRef = useRef<HTMLDivElement>(null)
  const drag = useRef<{ prev: number; angle: number } | null>(null)
  const lastTick = useRef(0)
  const locked = !signedIn || unsealed || busy

  const pointerAngle = (x: number, y: number) => {
    const r = discRef.current!.getBoundingClientRect()
    return (Math.atan2(y - (r.top + r.height / 2), x - (r.left + r.width / 2)) * 180) / Math.PI
  }

  const turnTo = (a: number) => {
    const step = Math.floor(norm(a) / 30)
    if (step !== lastTick.current) { lastTick.current = step; haptic('press') }
    setAngle(a)
  }

  const commit = async (a: number) => {
    if (!isInverted(a) || locked) return
    setAngle(a - norm(a) + 180)
    setBusy(true)
    setError(null)
    try {
      const res = await fetch('/api/profile/seal', { method: 'POST' })
      const d = await res.json().catch(() => ({}))
      if (!res.ok) throw new Error(String(d?.error || 'THE SEAL JAMMED'))
      haptic('complete')
      setTear(true)
    } catch (e) {
      haptic('error')
      setError(e instanceof Error ? e.message : 'THE SEAL JAMMED')
      setAngle((v) => v - norm(v))
      setBusy(false)
    }
  }

  const onDown = (e: React.PointerEvent) => {
    if (locked) { if (!signedIn) haptic('error'); return }
    e.preventDefault()
    discRef.current?.setPointerCapture(e.pointerId)
    drag.current = { prev: pointerAngle(e.clientX, e.clientY), angle }
    setDragging(true)
    haptic('toggle')
  }
  const onMove = (e: React.PointerEvent) => {
    if (!drag.current) return
    const cur = pointerAngle(e.clientX, e.clientY)
    let d = cur - drag.current.prev
    if (d > 180) d -= 360
    if (d < -180) d += 360
    drag.current.prev = cur
    drag.current.angle += d
    turnTo(drag.current.angle)
  }
  const onUp = () => {
    if (!drag.current) return
    const a = drag.current.angle
    drag.current = null
    setDragging(false)
    void commit(a)
  }

  const onKey = (e: React.KeyboardEvent) => {
    if (locked) return
    if (e.key === 'ArrowRight' || e.key === 'ArrowUp') { e.preventDefault(); const a = angle + 15; turnTo(a); void commit(a) }
    if (e.key === 'ArrowLeft' || e.key === 'ArrowDown') { e.preventDefault(); const a = angle - 15; turnTo(a); void commit(a) }
  }

  const turnHalf = () => {
    if (locked) { if (!signedIn) haptic('error'); return }
    haptic('activate')
    const a = angle + (180 - norm(angle))
    setAngle(a)
    window.setTimeout(() => void commit(a), 650)
  }

  const dismiss = () => {
    setTear(false)
    setBusy(false)
    onUnsealed()
  }

  const deg = Math.round(norm(angle))

  return (
    <div className="flex flex-col items-center text-center">
      <div
        ref={discRef}
        role="slider"
        tabIndex={locked ? -1 : 0}
        aria-label="The seal. Turn it upside down to unlock every game and app"
        aria-valuemin={0}
        aria-valuemax={359}
        aria-valuenow={deg}
        aria-valuetext={`${deg} degrees${unsealed ? ', turned' : ''}`}
        aria-disabled={locked}
        onPointerDown={onDown}
        onPointerMove={onMove}
        onPointerUp={onUp}
        onPointerCancel={onUp}
        onKeyDown={onKey}
        className={`seal-disc relative select-none touch-none focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-8 focus-visible:outline-[var(--col-yellow)] ${dragging ? 'is-dragging' : ''} ${unsealed ? 'is-unsealed' : ''} ${!signedIn ? 'is-dormant' : ''}`}
        style={{ cursor: locked ? (signedIn ? 'default' : 'not-allowed') : dragging ? 'grabbing' : 'grab' }}
      >
        <div className="seal-face" style={{ transform: `rotate(${angle}deg)` }} aria-hidden="true" />
        <span className="seal-notch" aria-hidden="true" />
      </div>

      <p className="font-ibm text-[11px] uppercase tracking-[0.25em] mt-6" style={{ color: 'var(--col-bone)' }}>
        {unsealed ? 'SEAL INVERTED // 180°' : `BEARING ${String(deg).padStart(3, '0')}°`}
      </p>
      <p className="font-oswald text-xs uppercase tracking-[0.3em] mt-2" style={{ color: unsealed ? 'var(--col-yellow)' : 'var(--col-ivory)' }}>
        {!signedIn ? 'CREATE A PROFILE TO TURN THE SEAL' : unsealed ? 'EVERYTHING IS OPEN' : busy ? 'BREAKING THE SEAL…' : 'DRAG THE SEAL UPSIDE DOWN'}
      </p>
      {signedIn && !unsealed ? (
        <button
          type="button"
          onClick={turnHalf}
          disabled={busy}
          className="press-fx mt-5 font-oswald text-xs uppercase tracking-[0.25em] px-5 min-h-[44px] inline-flex items-center justify-center disabled:opacity-60"
          style={{ border: '1px solid var(--col-steel)', color: 'var(--col-bone)' }}
        >
          TURN IT FOR ME
        </button>
      ) : null}
      {error ? <p role="alert" className="font-ibm text-[11px] uppercase mt-3" style={{ color: 'var(--col-yellow-hot)' }}>{error}</p> : null}
      {tear ? <TearMessage onDone={dismiss} /> : null}
    </div>
  )
}

