}

function TearMessage({ onDone }: { onDone: () => void }) {
  const [mounted, setMounted] = useState(false)
  useEffect(() => {
    setMounted(true)
    const t = window.setTimeout(onDone, 4200)
    const key = (e: KeyboardEvent) => { if (e.key === 'Escape' || e.key === 'Enter') onDone() }
    window.addEventListener('keydown', key)
    return () => { window.clearTimeout(t); window.removeEventListener('keydown', key) }
  }, [onDone])
  if (!mounted) return null
  return createPortal(
    <div className="seal-tear" role="alertdialog" aria-live="assertive" aria-label="Keep it baseline. All games and apps unlocked" onClick={onDone}>
      <div className="seal-tear__veil" aria-hidden="true" />
      {BANDS.map(([top, bottom, dx], i) => (
        <div
          key={i}
          className="seal-tear__band"
          aria-hidden={i > 0}
          style={{ clipPath: `inset(${top}% 0 ${100 - bottom}% 0)`, ['--dx' as string]: `${dx}px`, animationDelay: `${i * 35}ms` }}
        >
          <TearPanel />
        </div>
      ))}
      <div className="seal-tear__scan" aria-hidden="true" />
      <p className="seal-tear__hint font-ibm text-[10px] uppercase tracking-[0.3em]">TAP TO CONTINUE</p>
    </div>,
    document.body
  )
}

