interface NavProps {
  sections?: NavSection[]
  unlockLabel?: string | null
  current?: 'unlock' | 'profile'
  /** null hides the PROFILE link (paywall off) */
  profile?: { member: boolean } | null
  /** Touch swipe between nav pages (SiteContent swipeNav) */
  swipe?: boolean
}

const DEFAULT_SECTIONS: NavSection[] = [
  { id: 'works', label: 'WORKS', href: '/' },
  { id: 'games', label: 'GAMES', href: '/games' },
  { id: 'contact', label: 'CONTACT', href: '/contact' },
]

export function Nav({ sections = DEFAULT_SECTIONS, current, profile, swipe = false }: NavProps) {
  const pathname = usePathname()
  const press = () => haptic('press')
  const hrefs = useMemo(() => sections.map((s) => s.href), [sections])

  // Runs before the page template's layout effect, so the laser knows the nav order when picking a direction
  useLayoutEffect(() => {
    try { sessionStorage.setItem(NAV_ORDER_KEY, JSON.stringify(hrefs)) } catch {}
  }, [hrefs])

  return (
    <nav
      className="bv-glass fixed top-0 left-0 right-0 z-50 safe-top"
