            const active = pathname === s.href
            return (
              <Link
                key={s.id}
                href={s.href}
                onClick={press}
                aria-current={active ? 'true' : undefined}
                data-haunt-tab={s.href}
                className="nav-link relative font-oswald text-[11px] sm:text-xs md:text-sm uppercase tracking-[0.18em] md:tracking-widest transition-opacity min-h-[44px] inline-flex items-center gap-1.5 hover:opacity-100"
