              style={{ color: current === 'profile' ? 'var(--col-ivory)' : 'var(--col-bone)', opacity: current === 'profile' ? 1 : 0.8 }}
            >
              {profile.member ? (
                <span className="px-2 py-1 text-[10px] tracking-[0.2em]" style={{ border: '1px solid var(--col-yellow)', color: 'var(--col-yellow)' }}>
                  UNSEALED
