              ) : (
                <>
                  <svg className="sm:hidden" width="20" height="20" viewBox="0 0 20 20" fill="none" aria-hidden="true">
                    <rect x="6.5" y="2.5" width="7" height="7" stroke="currentColor" strokeWidth="2" />
                    <path d="M3 18V14.5H17V18" stroke="currentColor" strokeWidth="2" />
                  </svg>
                  <span className="hidden sm:inline">PROFILE</span>
                </>
              )}
            </Link>
          ) : null}
        </div>
      </div>
      {swipe ? <SwipeNav hrefs={hrefs} /> : null}
    </nav>
  )
}

