'use client';

import React, { useEffect, useState } from 'react';
import { createPortal } from 'react-dom';
import { motion, AnimatePresence } from 'framer-motion';

export type DeltaKind = 'cigarettes' | 'alcohol' | 'weed' | 'crystals' | 'heat' | 'affinity' | string;

export interface FloaterEntry {
  id: number;
  kind: DeltaKind;
  amount: number;
  x: number;
  y: number;
}

// Module-level event bus — call showResourceDelta() from anywhere.
type Listener = (e: FloaterEntry) => void;
const listeners = new Set<Listener>();
let nextId = 1;

/**
 * Show a floating delta animation at a given screen position.
 * Call this from API-response handlers after any resource mutation.
 *
 * @example
 * showResourceDelta('cigarettes', -1, { x: e.clientX, y: e.clientY });
 */
export function showResourceDelta(kind: DeltaKind, amount: number, pos: { x: number; y: number }) {
  const entry: FloaterEntry = { id: nextId++, kind, amount, x: pos.x, y: pos.y };
  listeners.forEach((l) => { try { l(entry); } catch { /* ignore */ } });
}

/** Fire a delta anchored to a specific DOM element (uses its bounding rect). */
export function showResourceDeltaAt(kind: DeltaKind, amount: number, el: HTMLElement | null) {
  if (!el) return;
  const rect = el.getBoundingClientRect();
  showResourceDelta(kind, amount, { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 });
}

const KIND_LABEL: Record<string, string> = {
  cigarettes: 'CIG',
  alcohol: 'ALC',
  weed: 'WEED',
  crystals: 'CRYS',
  heat: 'HEAT',
  affinity: 'AFF',
};

export default function ResourceDeltaFloaters(): React.ReactElement | null {
  const [mounted, setMounted] = useState(false);
  const [items, setItems] = useState<FloaterEntry[]>([]);

  useEffect(() => {
    setMounted(true);
  }, []);

  useEffect(() => {
    const handler: Listener = (entry) => {
      setItems((prev) => [...prev, entry]);
      // Auto-remove after animation duration
      setTimeout(() => {
        setItems((prev) => prev.filter((e) => e.id !== entry.id));
      }, 1000);
    };
    listeners.add(handler);
    return () => { listeners.delete(handler); };
  }, []);

  if (!mounted || typeof document === 'undefined') return null;

  const content = (
    <div className="fixed inset-0 pointer-events-none z-[9997]" aria-hidden="true">
      <AnimatePresence>
        {items.map((it) => {
          const positive = it.amount > 0;
          const color = positive ? '#c8dc96' : '#a8687e';
          const label = KIND_LABEL[String(it.kind)] ?? String(it.kind).toUpperCase();
          const sign = positive ? '+' : '';
          return (
            <motion.div
              key={it.id}
              initial={{ opacity: 0, y: 0, scale: 0.85 }}
              animate={{ opacity: 1, y: -28, scale: 1 }}
              exit={{ opacity: 0, y: -44, scale: 0.8 }}
              transition={{ duration: 0.9, ease: 'easeOut' }}
              className="absolute font-terminal text-sm whitespace-nowrap select-none"
              style={{
                left: it.x,
                top: it.y,
                transform: 'translate(-50%, -50%)',
                color,
                textShadow: '0 0 3px rgba(0,0,0,0.95), 0 1px 1px rgba(0,0,0,0.9)',
              }}
            >
              {sign}{it.amount} {label}
            </motion.div>
          );
        })}
      </AnimatePresence>
    </div>
  );
  const portal = createPortal(content as any, document.body) as unknown as React.ReactElement;
  return portal;
}

import { prisma } from './db'
import { getFileUrl } from './s3'
import { getBucketConfig } from './aws-config'

export type GalleryItem = { id: string; url: string; width: number; height: number }

/** Ordered gallery, read live from the DB on every call (admin edits show without a redeploy). */
export async function getGallery(): Promise<GalleryItem[]> {
  const rows = await prisma.galleryImage.findMany({ orderBy: [{ order: 'asc' }, { createdAt: 'asc' }] })
  return Promise.all(
    rows.map(async (r) => ({ id: r.id, url: await getFileUrl(r.cloud_storage_path, r.isPublic), width: r.width, height: r.height }))
  )
}

/** Only paths minted by the gallery presign may be registered. */
export function isGalleryPath(p: string) {
  const { folderPrefix } = getBucketConfig()
  return p.startsWith(`${folderPrefix}public/gallery/`) && !p.includes('..')
