import Image from 'next/image'
import { useEffect, useRef, useState } from 'react'
import styles from './hero-xray.module.css'

const SRC = '/assets/bmf3k-hero-key-art-oct19.jpg'
const W = 2070
const H = 1673
const ALT =
  'Grey.Filter presents BMF:3K — dripping magenta and lime graffiti BMF over a hatched lime and magenta 3K, 1995 marked in yellow, and a sketched open Zippo lighter'

/**
 * Hero key art with an X-ray lens: on hover (desktop) or touch (mobile) a
 * circular scan follows the pointer and reveals a luminous monochrome "X-ray"
 * pass of the same artwork. The artwork itself is shown unaltered.
 */
export function HeroXray() {
  const ref = useRef<HTMLDivElement>(null)
  const [active, setActive] = useState(false)
  const [readout, setReadout] = useState('000 · 000')
  const hideTimer = useRef<number | null>(null)

  useEffect(() => () => { if (hideTimer.current) window.clearTimeout(hideTimer.current) }, [])

  const place = (clientX: number, clientY: number) => {
    const el = ref.current
    if (!el) return
    const r = el.getBoundingClientRect()
    const x = Math.min(100, Math.max(0, ((clientX - r.left) / r.width) * 100))
    const y = Math.min(100, Math.max(0, ((clientY - r.top) / r.height) * 100))
    el.style.setProperty('--x', `${x}%`)
    el.style.setProperty('--y', `${y}%`)
    setReadout(`${String(Math.round(x * 10)).padStart(3, '0')} · ${String(Math.round(y * 10)).padStart(3, '0')}`)
  }

  const onMove = (e: React.PointerEvent) => {
    place(e.clientX, e.clientY)
    if (!active) setActive(true)
  }

  const onDown = (e: React.PointerEvent) => {
    place(e.clientX, e.clientY)
    setActive(true)
    if (e.pointerType !== 'mouse') {
      if (hideTimer.current) window.clearTimeout(hideTimer.current)
      hideTimer.current = window.setTimeout(() => setActive(false), 1800)
    }
  }

  const onLeave = (e: React.PointerEvent) => {
    if (e.pointerType === 'mouse') setActive(false)
  }

  return (
    <div
      ref={ref}
      className={styles.stage}
      data-active={active ? 'true' : 'false'}
      style={{ aspectRatio: `${W} / ${H}` }}
      onPointerMove={onMove}
      onPointerDown={onDown}
      onPointerLeave={onLeave}
    >
      <Image src={SRC} alt={ALT} fill priority sizes="(max-width: 768px) 92vw, 620px" className={styles.art} draggable={false} />

      <div className={styles.xray} aria-hidden="true">
        <Image src={SRC} alt="" fill sizes="(max-width: 768px) 92vw, 620px" className={styles.xrayArt} draggable={false} />
        <div className={styles.tint} />
        <div className={styles.lines} />
        <div className={styles.bar} />
      </div>

      <div className={styles.lens} aria-hidden="true">
        <span className={styles.tick} data-side="t" />
        <span className={styles.tick} data-side="b" />
        <span className={styles.tick} data-side="l" />
        <span className={styles.tick} data-side="r" />
        <span className={styles.label}>XR·3K {readout}</span>
      </div>

      <span className={styles.hint} aria-hidden="true">
        <span className={styles.hintDesk}>Hover to X-ray</span>
        <span className={styles.hintTouch}>Touch to X-ray</span>
      </span>
    </div>
  )
}

/**
 * INTAKE AUDIO — Phase-specific ambient sound beds for recruitment
 *
 * SURVEILLANCE: Tape hiss + distant camera servo motors + muffled breathing
 * DISSECTION:   Clinical buzz + heartbeat monitor + wet electrical crackle
 * THE PITCH:    Muffled hold-music drone + telemarketing hum + tinnitus ring
 *
 * All synthesised via Web Audio API — zero audio files, zero bundle size.
 * Each phase crossfades when switching.
 */

type IntakePhase = 'surveillance' | 'dissection' | 'pitch' | null;

let ctx: AudioContext | null = null;
let currentPhase: IntakePhase = null;
let nodes: AudioNode[] = [];
let masterGain: GainNode | null = null;

function getCtx(): AudioContext | null {
  if (typeof window === 'undefined') return null;
  if (ctx && ctx.state !== 'closed') return ctx;
  try {
    ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
  } catch { return null; }
  return ctx;
}

function cleanup() {
  for (const n of nodes) {
    try { (n as any).stop?.(); } catch { /* ignore */ }
    try { n.disconnect(); } catch { /* ignore */ }
  }
  nodes = [];
  masterGain = null;
}

/** Fade out and stop all intake audio */
export function stopIntakeAudio() {
  if (masterGain && ctx) {
    const now = ctx.currentTime;
    masterGain.gain.setValueAtTime(masterGain.gain.value, now);
    masterGain.gain.linearRampToValueAtTime(0, now + 0.8);
    setTimeout(() => cleanup(), 900);
  } else {
    cleanup();
  }
  currentPhase = null;
}

/** Switch to a new phase ambient */
export function playIntakeAmbient(phase: IntakePhase) {
  if (phase === currentPhase) return;
  stopIntakeAudio();
  if (!phase) return;

  const c = getCtx();
  if (!c) return;

  // Resume if suspended (autoplay policy)
  if (c.state === 'suspended') {
    try { c.resume(); } catch { /* ignore */ }
  }

  currentPhase = phase;
  masterGain = c.createGain();
  masterGain.gain.setValueAtTime(0, c.currentTime);
  masterGain.gain.linearRampToValueAtTime(1, c.currentTime + 1.2);
  masterGain.connect(c.destination);
  nodes.push(masterGain);

  if (phase === 'surveillance') buildSurveillance(c, masterGain);
  else if (phase === 'dissection') buildDissection(c, masterGain);
  else if (phase === 'pitch') buildPitch(c, masterGain);
}

// ═══════════════════════════════════════════════════════════════
// SURVEILLANCE: Tape hiss + servo whir + breathing
// ═══════════════════════════════════════════════════════════════
function buildSurveillance(c: AudioContext, master: GainNode) {
  // Tape hiss — brown noise via buffer
  const bufLen = c.sampleRate * 2;
  const buf = c.createBuffer(1, bufLen, c.sampleRate);
  const data = buf.getChannelData(0);
  let last = 0;
  for (let i = 0; i < bufLen; i++) {
    const white = Math.random() * 2 - 1;
    last = (last + (0.02 * white)) / 1.02;
    data[i] = last * 3.5;
  }
  const hiss = c.createBufferSource();
  hiss.buffer = buf;
  hiss.loop = true;
  const hissGain = c.createGain();
  hissGain.gain.value = 0.012;
  const hissFilter = c.createBiquadFilter();
  hissFilter.type = 'highpass';
  hissFilter.frequency.value = 2000;
  hiss.connect(hissFilter).connect(hissGain).connect(master);
  hiss.start();
  nodes.push(hiss, hissGain, hissFilter);

  // Camera servo — periodic high-pitched whir
  const servo = c.createOscillator();
  servo.type = 'sawtooth';
  servo.frequency.value = 1800;
  const servoGain = c.createGain();
  servoGain.gain.value = 0;
  const servoFilter = c.createBiquadFilter();
  servoFilter.type = 'bandpass';
  servoFilter.frequency.value = 1800;
  servoFilter.Q.value = 12;
  servo.connect(servoFilter).connect(servoGain).connect(master);
  servo.start();
  nodes.push(servo, servoGain, servoFilter);

  // Servo bursts every 4-8s
  const servoLoop = () => {
    if (currentPhase !== 'surveillance') return;
    const now = c.currentTime;
    servoGain.gain.setValueAtTime(0, now);
    servoGain.gain.linearRampToValueAtTime(0.003, now + 0.05);
    servoGain.gain.linearRampToValueAtTime(0, now + 0.15 + Math.random() * 0.1);
    setTimeout(servoLoop, 4000 + Math.random() * 4000);
  };
  setTimeout(servoLoop, 2000);

  // Muffled breathing — low frequency modulation
  const breathOsc = c.createOscillator();
  breathOsc.type = 'sine';
  breathOsc.frequency.value = 0.22; // ~4 breaths per 18s
  const breathGain = c.createGain();
  breathGain.gain.value = 0.004;
  const breathFilter = c.createBiquadFilter();
  breathFilter.type = 'lowpass';
  breathFilter.frequency.value = 200;
  // Use noise modulated by breath oscillator
  const breathNoise = c.createBufferSource();
  breathNoise.buffer = buf;
  breathNoise.loop = true;
  const breathNoiseGain = c.createGain();
  breathNoiseGain.gain.value = 0.006;
  breathNoise.connect(breathFilter).connect(breathNoiseGain).connect(master);
  breathNoise.start();
  nodes.push(breathOsc, breathGain, breathFilter, breathNoise, breathNoiseGain);
}

// ═══════════════════════════════════════════════════════════════
// DISSECTION: Clinical buzz + heartbeat + wet crackle
// ═══════════════════════════════════════════════════════════════
function buildDissection(c: AudioContext, master: GainNode) {
  // Fluorescent buzz — 100Hz hum
  const buzz = c.createOscillator();
  buzz.type = 'sawtooth';
  buzz.frequency.value = 100;
  const buzzGain = c.createGain();
  buzzGain.gain.value = 0.004;
  const buzzFilter = c.createBiquadFilter();
  buzzFilter.type = 'bandpass';
  buzzFilter.frequency.value = 100;
  buzzFilter.Q.value = 15;
  buzz.connect(buzzFilter).connect(buzzGain).connect(master);
  buzz.start();
  nodes.push(buzz, buzzGain, buzzFilter);

  // Heartbeat monitor — periodic beep
  const beepOsc = c.createOscillator();
  beepOsc.type = 'sine';
  beepOsc.frequency.value = 880;
  const beepGain = c.createGain();
  beepGain.gain.value = 0;
  beepOsc.connect(beepGain).connect(master);
  beepOsc.start();
  nodes.push(beepOsc, beepGain);

  // Beep every ~1.1s
  const beepLoop = () => {
    if (currentPhase !== 'dissection') return;
    const now = c.currentTime;
    beepGain.gain.setValueAtTime(0, now);
    beepGain.gain.linearRampToValueAtTime(0.008, now + 0.01);
    beepGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.08);
    setTimeout(beepLoop, 1100 + Math.random() * 200);
  };
  setTimeout(beepLoop, 500);

  // Wet electrical crackle — irregular short bursts
  const bufLen = c.sampleRate;
  const buf = c.createBuffer(1, bufLen, c.sampleRate);
  const data = buf.getChannelData(0);
  for (let i = 0; i < bufLen; i++) data[i] = Math.random() * 2 - 1;
  const crackle = c.createBufferSource();
  crackle.buffer = buf;
  crackle.loop = true;
  const crackGain = c.createGain();
  crackGain.gain.value = 0;
  const crackFilter = c.createBiquadFilter();
  crackFilter.type = 'highpass';
  crackFilter.frequency.value = 4000;
  crackle.connect(crackFilter).connect(crackGain).connect(master);
  crackle.start();
  nodes.push(crackle, crackGain, crackFilter);

  const crackleLoop = () => {
    if (currentPhase !== 'dissection') return;
    const now = c.currentTime;
    crackGain.gain.setValueAtTime(0, now);
    crackGain.gain.linearRampToValueAtTime(0.006, now + 0.01);
    crackGain.gain.linearRampToValueAtTime(0, now + 0.03 + Math.random() * 0.04);
    setTimeout(crackleLoop, 2000 + Math.random() * 6000);
  };
  setTimeout(crackleLoop, 1500);
}

// ═══════════════════════════════════════════════════════════════
// THE PITCH: Hold-music drone + tinnitus ring + distant voice murmur
// ═══════════════════════════════════════════════════════════════
function buildPitch(c: AudioContext, master: GainNode) {
  // Muzak drone — detuned sine waves creating a cheap hold-music chord
  const freqs = [196, 247, 294]; // G3, B3, D4 — major triad
  for (const freq of freqs) {
    const osc = c.createOscillator();
    osc.type = 'sine';
    osc.frequency.value = freq + (Math.random() - 0.5) * 3; // slight detune
    const g = c.createGain();
    g.gain.value = 0.003;
    const f = c.createBiquadFilter();
    f.type = 'lowpass';
    f.frequency.value = 600; // muffled
    osc.connect(f).connect(g).connect(master);
    osc.start();
    nodes.push(osc, g, f);
  }

  // Tinnitus ring — very high, very quiet
  const ring = c.createOscillator();
  ring.type = 'sine';
  ring.frequency.value = 7200;
  const ringGain = c.createGain();
  ringGain.gain.value = 0.002;
  ring.connect(ringGain).connect(master);
  ring.start();
  nodes.push(ring, ringGain);

  // Pulsing modulation on the drone — like a telephone line
  const lfo = c.createOscillator();
  lfo.type = 'sine';
  lfo.frequency.value = 0.3;
  const lfoGain = c.createGain();
  lfoGain.gain.value = 0.001;
  lfo.connect(lfoGain);
  // Connect LFO to all drone gains
  lfo.start();
  nodes.push(lfo, lfoGain);

  // Distant voice murmur — filtered noise with speech-like modulation
  const bufLen = c.sampleRate * 2;
  const buf = c.createBuffer(1, bufLen, c.sampleRate);
  const data = buf.getChannelData(0);
  for (let i = 0; i < bufLen; i++) data[i] = Math.random() * 2 - 1;
  const voice = c.createBufferSource();
  voice.buffer = buf;
  voice.loop = true;
  const voiceGain = c.createGain();
  voiceGain.gain.value = 0;
  const voiceFilter = c.createBiquadFilter();
  voiceFilter.type = 'bandpass';
  voiceFilter.frequency.value = 800;
  voiceFilter.Q.value = 5;
  voice.connect(voiceFilter).connect(voiceGain).connect(master);
  voice.start();
  nodes.push(voice, voiceGain, voiceFilter);

  // Occasional murmur bursts
  const murmurLoop = () => {
    if (currentPhase !== 'pitch') return;
    const now = c.currentTime;
    voiceGain.gain.setValueAtTime(0, now);
    voiceGain.gain.linearRampToValueAtTime(0.004, now + 0.3);
    voiceGain.gain.linearRampToValueAtTime(0, now + 0.8 + Math.random() * 0.5);
    setTimeout(murmurLoop, 3000 + Math.random() * 5000);
  };
  setTimeout(murmurLoop, 1000);
}

