} from '@/lib/sound-effects';

interface Props {
  open: boolean;
  onClose: () => void;
  onExitToMenu?: () => void;
  onOpenGuide?: () => void;
  onOpenTour?: () => void;
  /** Current game day, if in-game */
  day?: number;
  /** Player name, if in-game */
  playerName?: string;
