// ══════ Section header ══════
function SectionHeader({ icon: Icon, label }: { icon: typeof Volume2; label: string }) {
  return (
    <div className="flex items-center gap-2 mb-3">
      <div className="w-1 h-3 bg-[#B87333]/50" />
      <Icon size={11} className="text-[#B87333]/60" />
      <span className="font-terminal text-[10px] tracking-[0.25em] text-[#8a8578]">{label}</span>
    </div>
  );
}

// ══════ Volume slider ══════
function VolumeSlider({ label, icon: Icon, category, disabled }: {
  label: string;
  icon: typeof Volume2;
  category: VolumeCategory;
  disabled: boolean;
}) {
  const [val, setVal] = useState(() => getVolume(category));

  useEffect(() => {
    return subscribeVolumes((v) => setVal(v[category]));
  }, [category]);

  const handleChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const newVal = parseFloat(e.target.value);
    setVolume(category, newVal);
    setVal(newVal);
  }, [category]);

  const pct = Math.round(val * 100);

  return (
    <div className={`flex items-center gap-3 ${disabled ? 'opacity-30 pointer-events-none' : ''}`}>
      <Icon size={14} className="text-[#8a8578] flex-shrink-0" />
      <span className="font-terminal text-[11px] text-[#8a8578] tracking-wider w-20 flex-shrink-0">{label}</span>
      <div className="flex-1 relative">
        <input
          type="range"
          min="0"
          max="1"
          step="0.05"
          value={val}
          onChange={handleChange}
          className="settings-slider w-full"
          aria-label={`${label} volume`}
        />
        <div
          className="absolute top-1/2 left-0 h-[3px] -translate-y-1/2 pointer-events-none rounded-sm"
          style={{
            width: `${pct}%`,
            background: 'linear-gradient(90deg, #8a9670, #B87333)',
            opacity: 0.7,
          }}
        />
      </div>
      <span className="font-terminal text-[10px] text-[#5a564e] w-8 text-right flex-shrink-0">{pct}%</span>
    </div>
  );
}

// ══════ Hotkey row ══════
function HotkeyRow({ hotkey, desc }: { hotkey: string; desc: string }) {
  return (
    <div className="flex items-center gap-3 min-h-[28px]">
      <kbd className="font-terminal text-[10px] text-[#B87333] bg-[#141410] border border-[#B87333]/25 px-2 py-0.5 min-w-[36px] text-center flex-shrink-0 rounded-sm">{hotkey}</kbd>
