import { useEffect, useRef } from 'react'

interface MachineGaugeProps {
  state: 'idle' | 'ready' | 'activating' | 'active'
  size?: number
}

export function MachineGauge({ state, size = 60 }: MachineGaugeProps) {
  const needleRef = useRef<SVGLineElement>(null)
  const arcRef = useRef<SVGCircleElement>(null)
  const r = (size - 8) / 2
  const cx = size / 2
  const cy = size / 2
  const circumference = 2 * Math.PI * r

  useEffect(() => {
    const needle = needleRef?.current
    const arc = arcRef?.current
    if (!needle || !arc) return

    if (state === 'idle') {
      needle.style.transition = 'none'
      needle.style.transform = `rotate(0deg)`
      arc.style.strokeDashoffset = String(circumference)
    } else if (state === 'ready') {
      needle.style.transition = 'transform 3s ease-in-out'
      needle.style.transform = `rotate(270deg)`
      arc.style.transition = 'stroke-dashoffset 3s ease-in-out'
      arc.style.strokeDashoffset = String(circumference * 0.25)
    } else if (state === 'activating') {
      needle.style.transition = 'transform 0.4s linear'
      needle.style.transform = `rotate(360deg)`
      arc.style.transition = 'stroke-dashoffset 0.4s linear'
      arc.style.strokeDashoffset = '0'
    } else if (state === 'active') {
      needle.style.transition = 'none'
      needle.style.transform = `rotate(0deg)`
      arc.style.strokeDashoffset = String(circumference)
    }
  }, [state, circumference])

  const tickLength = 5
  const ticks = [0, 90, 180, 270].map((angle: number) => {
    const rad = (angle * Math.PI) / 180
    const x1 = cx + (r - tickLength) * Math.cos(rad)
    const y1 = cy + (r - tickLength) * Math.sin(rad)
    const x2 = cx + r * Math.cos(rad)
    const y2 = cy + r * Math.sin(rad)
    return { x1, y1, x2, y2, angle }
  })

  return (
    <svg
      width={size}
      height={size}
      viewBox={`0 0 ${size} ${size}`}
      className="machine-gauge"
      aria-hidden="true"
    >
      {/* Outer ring */}
      <circle
        cx={cx}
        cy={cy}
        r={r}
        fill="none"
        style={{ stroke: 'var(--bv-secondary)' }}
        strokeWidth="1.5"
      />
      {/* Sweep arc */}
      <circle
        ref={arcRef}
        cx={cx}
        cy={cy}
        r={r}
        fill="none"
        strokeWidth="2"
        strokeDasharray={circumference}
        strokeDashoffset={circumference}
        strokeLinecap="butt"
        style={{ stroke: 'var(--bv-primary)', transformOrigin: `${cx}px ${cy}px`, transform: 'rotate(-90deg)' }}
      />
      {/* Tick marks */}
      {ticks?.map?.((t: any) => (
        <line
          key={t?.angle}
          x1={t?.x1}
          y1={t?.y1}
          x2={t?.x2}
          y2={t?.y2}
          style={{ stroke: 'var(--bv-secondary)' }}
          strokeWidth="1"
        />
      )) ?? null}
      {/* Needle */}
      <line
        ref={needleRef}
        x1={cx}
        y1={cy}
        x2={cx}
        y2={cy - r + 6}
        strokeWidth="1.5"
        style={{ stroke: 'var(--bv-text)', transformOrigin: `${cx}px ${cy}px` }}
      />
      {/* Center dot */}
      <circle cx={cx} cy={cy} r="2" style={{ fill: 'var(--bv-text)' }} />
    </svg>
  )
}

