import { useState, useEffect, useMemo, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import Image from 'next/image';
import { Radio, ChevronRight, Lock, Gift, Crosshair } from 'lucide-react';
import { playSniff } from '@/lib/sound-effects';
import { audioManager } from '@/app/_lib/audio-manager';
import type { GameNPC } from '@/lib/types';

interface Props {
  npcData: { name: string; portraitUrl?: string; recruitmentScene?: string; observation?: { description?: string; managerNote?: string; tells: Array<{ id?: string; text: string; key?: string }> } };
  npc: GameNPC;
  affinity: number;
  escalationLevel?: number;
  zoomPulse?: number;
  onAdvance: () => void;
}

// Affinity thresholds per tell index — spread across 0-50 range
function getTellThresholds(totalTells: number): number[] {
  if (totalTells <= 0) return [];
  if (totalTells === 1) return [0];
  return Array.from({ length: totalTells }, (_, i) =>
    i === 0 ? 0 : Math.round((i / (totalTells - 1)) * 50)
  );
}

// Annotation positions for tells on the feed — scattered like detective notes
const ANNOTATION_POSITIONS = [
  { top: '12%', left: '58%', rotate: '-2deg' },
  { top: '35%', left: '8%', rotate: '1.5deg' },
  { top: '55%', left: '62%', rotate: '-1deg' },
  { top: '22%', left: '32%', rotate: '2.5deg' },
  { top: '68%', left: '15%', rotate: '-3deg' },
  { top: '45%', left: '45%', rotate: '0.5deg' },
  { top: '78%', left: '55%', rotate: '-2.5deg' },
  { top: '8%', left: '75%', rotate: '1deg' },
];

export default function ObservationStage({ npcData, npc, affinity, escalationLevel = 0, zoomPulse = 0, onAdvance }: Props) {
  const tells = npcData?.observation?.tells ?? [];
  const thresholds = useMemo(() => getTellThresholds(tells.length), [tells.length]);

  const unlockedCount = useMemo(() => {
    let count = 0;
    for (let i = 0; i < thresholds.length; i++) {
      if (affinity >= thresholds[i]) count++;
      else break;
    }
    return count;
  }, [affinity, thresholds]);

  const requiredReveals = Math.max(1, tells.length - 1);
  const canAdvance = tells.length === 0 || unlockedCount >= requiredReveals;
  const nextThreshold = unlockedCount < thresholds.length ? thresholds[unlockedCount] : null;

  const [prevUnlocked, setPrevUnlocked] = useState(unlockedCount);
  useEffect(() => {
    if (unlockedCount > prevUnlocked) {
      playSniff();
      setPrevUnlocked(unlockedCount);
    }
  }, [unlockedCount, prevUnlocked]);

  // Tracking reticle — simulated movement across the feed
  const [reticlePos, setReticlePos] = useState({ x: 50, y: 40 });
  useEffect(() => {
    const interval = setInterval(() => {
      setReticlePos({
        x: 30 + Math.random() * 40,
        y: 25 + Math.random() * 50,
      });
    }, 2800);
    return () => clearInterval(interval);
  }, []);

  // Timestamp counter
  const [elapsed, setElapsed] = useState(0);
  useEffect(() => {
    const t = setInterval(() => setElapsed((e) => e + 1), 1000);
    return () => clearInterval(t);
  }, []);
  const ts = `${String(Math.floor(elapsed / 60)).padStart(2, '0')}:${String(elapsed % 60).padStart(2, '0')}`;

  // Pass 2: Zoom pulse animation — feed scales up briefly when vice is given
  const [feedScale, setFeedScale] = useState(1);
  const prevPulseRef = useRef(zoomPulse);
  useEffect(() => {
    if (zoomPulse !== prevPulseRef.current) {
      prevPulseRef.current = zoomPulse;
      setFeedScale(1.06);
      const t = setTimeout(() => setFeedScale(1), 350);
      return () => clearTimeout(t);
    }
  }, [zoomPulse]);

  // Pass 2: Static interference bursts — random horizontal noise bands
  const [staticBurst, setStaticBurst] = useState(false);
  useEffect(() => {
    const trigger = () => {
      setStaticBurst(true);
      const duration = 80 + Math.random() * 150;
      setTimeout(() => setStaticBurst(false), duration);
    };
    // Random interval between 3-8 seconds
    const schedule = () => {
      const delay = 3000 + Math.random() * 5000;
      return setTimeout(() => {
        trigger();
        timerId = schedule();
      }, delay);
    };
    let timerId = schedule();
    return () => clearTimeout(timerId);
  }, []);

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="p-4 sm:p-5"
    >
      {/* Header */}
      <div className="flex items-center gap-2 mb-3">
        <Radio size={13} className="text-[#9cff76]/60" />
        <h3 className="font-terminal text-xs text-[#9cff76]/60 tracking-widest">SURVEILLANCE FEED</h3>
        <span className="ml-auto font-terminal text-[9px] text-[#9cff76]/30">{ts}</span>
      </div>

      {/* ── LIVE FEED ── */}
      {npcData?.recruitmentScene && (
        <motion.div
          className="relative w-full mb-5 overflow-hidden"
          animate={{ scale: feedScale }}
          transition={{ duration: 0.35, ease: [0.22, 1, 0.36, 1] }}
          style={{
            aspectRatio: '16 / 8',
            border: '1px solid rgba(156,255,118,0.12)',
            background: '#050505',
            transformOrigin: 'center center',
          }}
        >
          {/* Scene image */}
          <Image
            src={npcData.recruitmentScene}
            alt={`Surveillance feed: ${npc?.name ?? 'subject'}`}
            fill
            priority
            className="object-cover"
            style={{ filter: `saturate(0.65) contrast(1.15) brightness(0.85)` }}
          />

          {/* Heavy scanlines — surveillance camera feel */}
          <div className="absolute inset-0 pointer-events-none" style={{
            backgroundImage: 'repeating-linear-gradient(0deg, rgba(0,0,0,0) 0px, rgba(0,0,0,0) 1px, rgba(0,0,0,0.25) 2px, rgba(0,0,0,0) 3px)',
            mixBlendMode: 'multiply',
          }} />

          {/* Vignette */}
          <div className="absolute inset-0 pointer-events-none" style={{
            background: 'radial-gradient(ellipse at center, transparent 40%, rgba(0,0,0,0.7) 100%)',
          }} />

          {/* Pass 2: Static interference burst */}
          {staticBurst && (
            <div className="absolute inset-0 pointer-events-none" style={{
              background: `repeating-linear-gradient(
                0deg,
                transparent 0px,
                transparent ${3 + Math.random() * 4}px,
                rgba(156,255,118,0.08) ${4 + Math.random() * 3}px,
                rgba(255,255,255,0.12) ${5 + Math.random() * 2}px,
                transparent ${7 + Math.random() * 3}px
              )`,
              transform: `translateY(${Math.random() * 40 - 20}%)`,
              mixBlendMode: 'screen',
            }} />
          )}

          {/* Tracking reticle */}
          <motion.div
            className="absolute pointer-events-none"
            animate={{ left: `${reticlePos.x}%`, top: `${reticlePos.y}%` }}
            transition={{ duration: 2.2, ease: 'easeInOut' }}
            style={{ transform: 'translate(-50%, -50%)' }}
          >
            <Crosshair size={28} className="text-[#9cff76]/25" />
          </motion.div>

          {/* REC indicator */}
          <div className="absolute top-2 left-2 flex items-center gap-1.5 px-1.5 py-0.5 bg-black/60">
            <motion.div
              animate={{ opacity: [1, 0.15, 1] }}
              transition={{ duration: 1.2, repeat: Infinity }}
              className="w-1.5 h-1.5 rounded-full bg-red-500"
            />
            <span className="font-terminal text-[8px] text-red-400/90 tracking-wider">REC</span>
          </div>

          {/* Camera info */}
          <div className="absolute top-2 right-2 font-terminal text-[8px] text-[#9cff76]/40 px-1.5 py-0.5 bg-black/50">
            CAM-04 · {ts} · SUBJ: {(npc?.name ?? 'UNKNOWN').toUpperCase()}
          </div>

          {/* Bottom bar */}
          <div className="absolute bottom-0 left-0 right-0 h-6 bg-gradient-to-t from-black/80 to-transparent flex items-end px-2 pb-1">
            <span className="font-terminal text-[7px] text-[#9cff76]/30 tracking-widest">EXTERNAL · PARKING LOT C · LOW-LIGHT</span>
          </div>

          {/* ── ANNOTATION OVERLAYS — tells appear as handwritten notes ON the feed ── */}
          <AnimatePresence>
            {tells.map((tell: { id?: string; text: string; key?: string }, i: number) => {
              const isRevealed = i < unlockedCount;
              if (!isRevealed) return null;
              const pos = ANNOTATION_POSITIONS[i % ANNOTATION_POSITIONS.length];
              return (
                <motion.div
                  key={tell?.id ?? i}
                  initial={{ opacity: 0, scale: 0.7 }}
                  animate={{ opacity: 1, scale: 1 }}
                  exit={{ opacity: 0 }}
                  transition={{ delay: 0.15, duration: 0.4 }}
                  className="absolute pointer-events-none px-2 py-1 max-w-[140px]"
                  style={{
                    top: pos.top,
                    left: pos.left,
                    transform: `rotate(${pos.rotate})`,
                    background: 'rgba(0,0,0,0.65)',
                    border: '1px solid rgba(156,255,118,0.25)',
                    borderLeft: '2px solid rgba(156,255,118,0.5)',
                  }}
                >
                  <span className="font-typewriter text-[9px] text-[#9cff76]/90 leading-tight block">
                    ▸ {tell?.text ?? 'Noted.'}
                  </span>
                </motion.div>
              );
            })}
          </AnimatePresence>

          {/* Escalation corruption */}
          {escalationLevel >= 5 && (
            <motion.div
              className="absolute inset-0 pointer-events-none"
              animate={{ opacity: [0, 0.15, 0] }}
              transition={{ duration: 0.3, repeat: Infinity, repeatDelay: 2 }}
              style={{ background: 'linear-gradient(90deg, transparent 30%, #b87a96 50%, transparent 70%)' }}
            />
          )}
        </motion.div>
      )}

      {/* Description */}
      <p className="font-typewriter text-sm text-[#E8E8E8]/55 leading-relaxed mb-4">
        {npcData?.observation?.description ?? 'Observe the subject carefully.'}

      {/* Manager's private margin note — why he chose this one */}
      {npcData?.observation?.managerNote && (
        <div
          className="relative pl-3 pr-2 py-2 mb-4"
          style={{
            borderLeft: '2px solid rgba(255,75,193,0.35)',
            background: 'linear-gradient(90deg, rgba(255,75,193,0.05), transparent)',
          }}
        >
          <div className="font-terminal text-[8px] tracking-[0.3em] mb-1" style={{ color: 'rgba(255,75,193,0.6)' }}>
            MANAGER&apos;S MARGIN NOTE
          </div>
          <p className="font-caveat text-base leading-snug" style={{ color: 'rgba(232,232,232,0.78)' }}>
            {npcData.observation.managerNote}
          </p>
        </div>
      )}
      </p>

      {/* Vice supply hint */}
      {tells.length > 0 && (
        <div className="p-2 mb-4 text-[10px] font-terminal tracking-wider flex items-center gap-2" style={{
          border: '1px solid rgba(255,178,95,0.15)',
          background: 'rgba(255,178,95,0.04)',
          color: 'rgba(255,178,95,0.7)',
        }}>
          <Gift size={10} className="flex-shrink-0" />
          SUPPLY VICES TO BUILD COMPLIANCE. TELLS APPEAR ON FEED AS TRUST GROWS.
        </div>
      )}

      {/* ── TELL TRACKER — list below feed ── */}
      {tells.length > 0 && (
        <div className="mb-5">
          <div className="flex items-center justify-between mb-2">
            <h4 className="font-terminal text-[9px] text-[#9cff76]/40 tracking-widest">BEHAVIORAL MARKERS ({unlockedCount}/{tells.length})</h4>
            {nextThreshold !== null && (
              <span className="font-terminal text-[8px] text-[#FFB000]/40">NEXT MARKER @ {nextThreshold}% COMPLIANCE</span>
            )}
          </div>
          <div className="space-y-1">
            {tells.map((tell: { id?: string; text: string; key?: string }, i: number) => {
              const isRevealed = i < unlockedCount;
              return (
                <motion.div
                  key={tell?.id ?? i}
                  initial={false}
                  animate={{ opacity: isRevealed ? 1 : 0.25 }}
                  transition={{ duration: 0.4 }}
                  className="flex items-center gap-2 px-2.5 py-1.5 text-[10px] font-terminal"
                  style={{
                    borderLeft: `2px solid ${isRevealed ? '#9cff76' : '#2a2a20'}`,
                    background: isRevealed ? 'rgba(156,255,118,0.04)' : 'rgba(0,0,0,0.15)',
                  }}
                >
                  {isRevealed ? (
                    <span className="text-[#E8E8E8]/80">▸ {tell?.text ?? 'Something observed.'}</span>
                  ) : (
                    <span className="flex items-center gap-1 text-[#2a2a20]">
                      <Lock size={8} className="flex-shrink-0" />
                      ████ ██████
                      <span className="text-[7px] text-[#FFB000]/30 ml-1">({thresholds[i]}%)</span>
                    </span>
                  )}
                </motion.div>
              );
            })}
          </div>
        </div>
      )}

      {tells.length === 0 && (
        <p className="text-[10px] text-[#4a4a4a] mb-5 font-terminal">Subject profile is thin. Auto-assessment available.</p>
      )}

      {/* Advance */}
      {canAdvance ? (
        <motion.button
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          onClick={() => { audioManager.playSFX('nav'); onAdvance(); }}
          className="w-full font-terminal py-3 text-sm tracking-wider transition-all cursor-pointer active:scale-[0.98]"
          style={{
            border: '1px solid #9cff76',
            color: '#9cff76',
            background: 'rgba(156,255,118,0.04)',
          }}
        >
          OPEN DISSECTION <ChevronRight size={13} className="inline ml-1" />
        </motion.button>
      ) : (
        <div className="w-full font-terminal py-3 text-sm text-center" style={{ border: '1px solid #2a2a20', color: '#4a4a3a' }}>
          <Lock size={11} className="inline mr-2 -mt-0.5" />
          TAG {requiredReveals - unlockedCount} MORE MARKER{requiredReveals - unlockedCount !== 1 ? 'S' : ''} TO ADVANCE
        </div>
      )}
    </motion.div>
  );
}

'use client';

import { Component, type ReactNode } from 'react';

interface Props {
  children: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

/**
 * Win Sweep v2 — Global error boundary for the game client.
 * Catches render-time crashes and shows a themed recovery screen
 * instead of a white-screen-of-death.
 */
export default class GameErrorBoundary extends Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, info: React.ErrorInfo) {
    console.error('[BMF3K] Unhandled render error:', error, info.componentStack);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div
          className="w-screen h-screen bg-[#080808] flex items-center justify-center p-6"
          role="alert"
          aria-live="assertive"
        >
          <div className="max-w-md text-center space-y-6">
            <div className="text-[#a8687e] font-terminal text-lg tracking-[0.2em] animate-pulse">
              SYSTEM FAULT
            </div>
            <div className="text-[#8aad7a]/60 font-typewriter text-sm leading-relaxed">
              The simulation encountered an unrecoverable error.
              <br />
              Reality buffer overflow detected.
            </div>
            <pre className="text-[#8a8578] text-xs font-mono text-left bg-[#0a0a0a] border border-[#2a2a20] p-3 overflow-auto max-h-32">
              {this.state.error?.message ?? 'Unknown error'}
            </pre>
            <button
              onClick={() => {
                this.setState({ hasError: false, error: null });
                window.location.reload();
              }}
              className="px-6 py-3 font-terminal text-sm tracking-[0.15em] text-[#8aad7a] border-2 border-[#8aad7a]/30 hover:border-[#8aad7a]/60 hover:bg-[#8aad7a]/10 transition-all"
              aria-label="Reload the game"
            >
              REBOOT SIMULATION
            </button>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

