// ── Escalation-tiered return flavour ──
const FLAVOUR_LOW = [
  'The desk is where you left it. So is everything else.',
  'The fluorescent light blinks twice. It remembers you.',
  'You sit down. The chair is still warm. That\'s concerning.',
  'The coffee ring hasn\'t moved. Time is different here.',
  'Back again. The clipboard was waiting.',
  'Nothing changed while you were gone. Nothing ever does.',
  'The receipts accumulated. They always do.',
];
const FLAVOUR_MID = [
  'The walls are thinner than you remember. You can hear them breathing.',
  'Someone moved the desk half an inch. You\'re certain of it.',
  'The fluorescent light doesn\'t blink anymore. It stares.',
  'There\'s a new stain on the ceiling. Or you just never looked up.',
  'The silence has a texture now. Like wet cardboard.',
  'Something is stuck to the underside of the desk. You don\'t check.',
];
const FLAVOUR_HIGH = [
  'They know you came back. They always know.',
  'The building groans when you walk in. Hungry.',
  'Don\'t look at the walls. DON\'T LOOK AT THE WALLS.',
  'You can feel the receipts watching. All of them.',
  'The desk didn\'t move. You moved around the desk.',
  'Everything is fine. Say it again. Everything is fine.',
];

// ── Crew status quips (one per recruited NPC) ──
const CREW_STATUS: Record<string, Record<number, string>> = {
  Dave:   { 0: 'Dave is still here. He\'s always still here.', 3: 'Dave hasn\'t blinked since you left.', 6: 'Dave is vibrating.' },
  Tamara: { 0: 'Tamara left a note: "don\'t."', 3: 'Tamara\'s handwriting is getting smaller.', 6: 'Tamara scratched something into the desk. It\'s your name.' },
  Sid:    { 0: 'Sid appears to be napping. Or praying.', 3: 'Sid has reorganised the stash. Twice.', 6: 'Sid is whispering to a cigarette.' },
  Mikey:  { 0: 'Mikey taped a motivational poster to the wall. It says "RUN."', 3: 'Mikey hasn\'t moved from the corner.', 6: 'Mikey is watching you through the keyhole from the wrong side.' },
};

function getCrewStatus(name: string, escalationLevel: number): string {
  const pool = CREW_STATUS[name];
  if (!pool) return '';
  const bracket = escalationLevel >= 6 ? 6 : escalationLevel >= 3 ? 3 : 0;
  return pool[bracket] ?? pool[0] ?? '';
}

