    playThud();
    const t = setTimeout(() => setShowBtn(true), 2000);
    return () => clearTimeout(t);
  }, []);

  const esc = escalation.level;
  const flavourPool = esc >= 6 ? FLAVOUR_HIGH : esc >= 3 ? FLAVOUR_MID : FLAVOUR_LOW;
  const flavour = flavourPool[Math.abs((game?.day ?? 0) % flavourPool.length)];

  const recruited = (game?.npcs ?? []).filter((n) => n?.recruited && n?.name);
  const recruitedCount = recruited.length;
  const resources = game?.resources ?? [];
  const getRes = (type: string) => resources.find((r) => r?.type === type)?.quantity ?? 0;
