  const crewStatusNpc = recruited.length > 0 ? recruited[Math.abs((game?.day ?? 0) % recruited.length)] : null;
  const crewStatusLine = crewStatusNpc ? getCrewStatus(crewStatusNpc.name ?? '', esc) : '';

  return (
    <div className="w-full h-full bg-[#050505] texture-receipt-bg flex items-center justify-center p-4 overflow-auto" role="region" aria-label="Welcome back">
      <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 1.5 }} className="max-w-md sm:max-w-lg w-full">
        {/* Receipt-style welcome back */}
        <div className="mx-auto relative" style={{
          background: '#e8e0c8',
          padding: '20px 16px',
          fontFamily: 'monospace',
          boxShadow: '0 4px 20px rgba(0,0,0,0.5)',
        }}>
          <div className="space-y-1 text-[#333]">
            <p className="text-center text-sm font-bold">================================</p>
            <p className="text-center text-sm font-bold">BAF3K — SESSION RESUME</p>
            <p className="text-center text-xs text-[#555]">WELCOME BACK, {game?.playerName?.toUpperCase?.() || 'MANAGER'}</p>
            <p className="text-center text-sm font-bold">================================</p>
            <div className="py-3 space-y-1.5 text-sm">
              <p>  DAY:          {game?.day ?? 1}</p>
              <p>  CREW ACTIVE:  {recruitedCount}/4</p>
              <p className={esc >= 5 ? 'text-[#8B0000]' : ''}>  HEAT LEVEL:   {(game?.heat ?? 0).toFixed(1)}</p>
              <p>  MISSIONS:     {activeMissions} active</p>
              <p className="text-center text-xs">- - - - - - - - - - - - - - - -</p>
              <div className="flex items-center justify-center gap-5 py-1">
                <span className="inline-flex items-center gap-1 text-sm"><CigaretteIcon size={14} color="#333" />{getRes('cigarettes')}</span>
