              </div>
            </div>
            <p className="text-center text-sm font-bold">================================</p>
            <p className="text-center text-xs text-[#5a5a3a] italic mt-2">&quot;{flavour}&quot;</p>

            {/* Crew status line — one recruited NPC reports in */}
