              <motion.p
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ delay: 1.2, duration: 0.8 }}
                className="text-center text-[11px] text-[#6a5a3a] italic mt-2 font-caveat"
              >
                {crewStatusLine}
              </motion.p>
            )}
          </div>

          {/* Coffee ring */}
          <div className="absolute top-6 right-6 w-10 h-10 rounded-full border-2 border-[#8B4513]/10 opacity-30" />
        </div>

        {showBtn && (
          <motion.button
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            onClick={() => { audioManager.playSFX('nav'); onContinue(); }}
            aria-label="Resume operations and continue playing"
            className="w-full mt-6 py-3 font-terminal text-base border-2 border-[#8aad7a] text-[#8aad7a] hover:bg-[#8aad7a] hover:text-[#080808] transition-all active:scale-95 cursor-pointer min-h-[48px] focus:outline-none focus-visible:ring-2 focus-visible:ring-[#8aad7a]/60"
            style={{ boxShadow: '0 0 10px rgba(216,199,163,0.12)' }}
          >
            RESUME OPERATIONS →
          </motion.button>
        )}
      </motion.div>
    </div>
  );
}

// ========================
// GAME ENGINE - Tolerance, conflict, heat calculations
// ========================

export type ToleranceCurve = 'LINEAR' | 'DOUBLE_DOWN' | 'SLOW_FADE' | 'BURN_FAST';

/**
 * Raw tolerance value — uncapped so that heavy substances (crystals)
 * can push avgTolerance high enough to trigger CRASHING/GONE in the
 * encounter system, where avgTolerance = sum-of-4 / 4.
 * ActorState output fields are clamped to 0-10 inside computeActorState.
 */
export function calculateTolerance(
  baseTolerance: number,
  useCount: number,
  escalationRate: number,
  npcModifier: number,
  curveType: ToleranceCurve
): number {
  let tolerance = baseTolerance;
  switch (curveType) {
    case 'LINEAR':
      tolerance = baseTolerance + useCount * escalationRate * npcModifier;
      break;
    case 'DOUBLE_DOWN':
      tolerance = baseTolerance + Math.pow(useCount, 1.5) * escalationRate * npcModifier;
      break;
    case 'SLOW_FADE':
      tolerance = baseTolerance + useCount * escalationRate * Math.log(useCount + 1) * npcModifier;
      break;
    case 'BURN_FAST':
      tolerance = baseTolerance + useCount * escalationRate * 2.0 * npcModifier;
      break;
  }
  return tolerance;
}

export function getToleranceStatus(tolerance: number): { label: string; color: string } {
  if (tolerance <= 3) return { label: 'Functional', color: '#8aad7a' };
  if (tolerance <= 5) return { label: 'Concerning', color: '#FFFF00' };
  if (tolerance <= 7) return { label: 'Unstable', color: '#FF8C00' };
  if (tolerance <= 9) return { label: 'CRITICAL', color: '#a8687e' };
  return { label: 'NON-FUNCTIONAL', color: '#ff3344' };
}

