.stage {
  --x: 50%;
  --y: 50%;
  --r: clamp(56px, 8vw, 110px);
  position: relative;
  width: 100%;
  cursor: crosshair;
  touch-action: pan-y;
  user-select: none;
  -webkit-user-select: none;
  -webkit-touch-callout: none;
  /* Feather the artwork's black canvas edges into the page background. */
  -webkit-mask-image: linear-gradient(to right, transparent, #000 5%, #000 95%, transparent), linear-gradient(to bottom, transparent, #000 4%, #000 96%, transparent);
  -webkit-mask-composite: source-in;
  mask-image: linear-gradient(to right, transparent, #000 5%, #000 95%, transparent), linear-gradient(to bottom, transparent, #000 4%, #000 96%, transparent);
  mask-composite: intersect;
}

.art {
  object-fit: contain;
  mix-blend-mode: screen;
  pointer-events: none;
}

/* X-ray pass: same artwork, desaturated and pushed so paint reads as bright
   bone and black stays black, tinted lime, revealed only inside the lens. */
.xray {
  position: absolute;
  inset: 0;
  isolation: isolate;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.22s ease-out;
  background: #050604;
  -webkit-mask-image: radial-gradient(circle var(--r) at var(--x) var(--y), #000 82%, transparent 100%);
  mask-image: radial-gradient(circle var(--r) at var(--x) var(--y), #000 82%, transparent 100%);
}

.xrayArt {
  object-fit: contain;
  filter: grayscale(1) brightness(1.45) contrast(2.1) blur(0.4px);
}

.tint {
  position: absolute;
  inset: 0;
  background: #b8f026;
  mix-blend-mode: multiply;
}

.lines {
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(0deg, rgba(5, 6, 4, 0.55) 0 1px, transparent 1px 3px);
}

.bar {
  position: absolute;
  left: 0;
  right: 0;
  height: 2px;
  top: var(--y);
  background: #e040b0;
  opacity: 0.85;
  animation: xrScan 1.4s linear infinite;
}

@keyframes xrScan {
  from { top: calc(var(--y) - var(--r)); }
  to { top: calc(var(--y) + var(--r)); }
}

.lens {
  position: absolute;
  left: var(--x);
  top: var(--y);
  width: calc(var(--r) * 2);
  height: calc(var(--r) * 2);
  transform: translate(-50%, -50%) scale(0.85);
  border: 1px solid rgba(184, 240, 38, 0.75);
  border-radius: 50%;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.22s ease-out, transform 0.22s ease-out;
}

.tick {
  position: absolute;
  background: #b8f026;
}
.tick[data-side='t'], .tick[data-side='b'] { left: 50%; width: 1px; height: 10px; transform: translateX(-50%); }
.tick[data-side='t'] { top: -5px; }
.tick[data-side='b'] { bottom: -5px; }
.tick[data-side='l'], .tick[data-side='r'] { top: 50%; height: 1px; width: 10px; transform: translateY(-50%); }
.tick[data-side='l'] { left: -5px; }
.tick[data-side='r'] { right: -5px; }

.label {
  position: absolute;
  top: calc(100% + 8px);
  left: 50%;
  transform: translateX(-50%);
  white-space: nowrap;
  font-size: 8px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: #b8f026;
  background: rgba(10, 10, 8, 0.85);
  padding: 2px 6px;
  font-variant-numeric: tabular-nums;
}

.stage[data-active='true'] .xray { opacity: 1; }
.stage[data-active='true'] .lens { opacity: 1; transform: translate(-50%, -50%) scale(1); }
.stage[data-active='true'] .hint { opacity: 0; }

.hint {
  position: absolute;
  right: 4%;
  bottom: 2%;
  font-size: 8px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: #b8f026;
  opacity: 0.45;
  pointer-events: none;
  transition: opacity 0.2s;
}
.hintTouch { display: none; }
@media (hover: none) {
  .hintDesk { display: none; }
  .hintTouch { display: inline; }
}

@media (prefers-reduced-motion: reduce) {
  .bar { display: none; }
  .xray, .lens { transition: none; }
}

