interface Props {
  game: GameState;
  escalation: EscalationState;
  onBack: () => void;
  onRefresh: () => Promise<void>;
  showNotification: (msg: string) => void;
}

type Phase = 'pick_location' | 'ready' | 'searching' | 'results' | 'already_done' | 'error';

interface LootEntry {
  type: string;
  gained: number;
  newTotal: number;
}

function ScroungeStation({ game, escalation, onBack, onRefresh, showNotification }: Props) {
  const [phase, setPhase] = useState<Phase>('pick_location');
  const [selectedLocation, setSelectedLocation] = useState<ScroungeLocation>(LOCATIONS[0]);
  const [loot, setLoot] = useState<LootEntry[]>([]);
  const [heatGain, setHeatGain] = useState(0);
  const [flavour, setFlavour] = useState('');
  const [assistantId, setAssistantId] = useState<string | null>(null);

  const isHighEsc = escalation.level >= 4;

  const recruitedNpcs = useMemo(
    () => (game?.npcs ?? []).filter((n) => n?.recruited),
    [game?.npcs]
  );

  const pickLocation = useCallback((loc: ScroungeLocation) => {
    audioManager.playSFX('nav');
    setSelectedLocation(loc);
    setPhase('ready');
  }, []);

  const doScrounge = useCallback(async () => {
    if (!game.sessionId) return;
    audioManager.playSFX('nav');
    setPhase('searching');
    const pool = isHighEsc ? selectedLocation.escalationFlavour : selectedLocation.searchFlavour;
    setFlavour(pool[Math.floor(Math.random() * pool.length)]);

    // Dramatic pause — let the flavour text breathe
    await new Promise(r => setTimeout(r, 1800));

    try {
      const res = await fetch('/api/game/scrounge', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ sessionId: game.sessionId, assistantNpcId: assistantId }),
      });
      const data = await res.json();

      if (!res.ok) {
        if (data.error === 'already_scrounged') {
          setFlavour(ALREADY_SCROUNGED[Math.floor(Math.random() * ALREADY_SCROUNGED.length)]);
          setPhase('already_done');
          audioManager.playSFX('error');
          return;
        }
        if (data.error === 'no_energy') {
          setFlavour('You can barely keep your eyes open. No energy left to dig through bins.');
          setPhase('already_done');
          audioManager.playSFX('error');
          return;
        }
        throw new Error(data.error || 'Scrounge failed');
      }

      setLoot(data.loot ?? []);
      setHeatGain(data.heatGain ?? 0);
      const assistantMsg = data.assistant ? ` ${data.assistant.name} helped.` : '';
      setFlavour(selectedLocation.successFlavour[Math.floor(Math.random() * selectedLocation.successFlavour.length)] + assistantMsg);
      setPhase('results');
      audioManager.playSFX('confirm');
      await onRefresh();
    } catch (err: unknown) {
      console.error('Scrounge error:', err instanceof Error ? err.message : err);
      setFlavour('Something went wrong. The alley remains unlooted.');
      setPhase('error');
      audioManager.playSFX('error');
    }
  }, [game.sessionId, onRefresh, selectedLocation, isHighEsc, assistantId]);

  const handleBack = useCallback(() => {
    audioManager.playSFX('nav');
    if (phase === 'ready') {
      setPhase('pick_location');
