// The overlay draws the borders of the hero page in real time on each arrival:
// thick corner plates snap into the four corners and short edge segments extend
// inward from them. Purely visual — no HUD / haptic wiring is touched here.
// It remounts every time the hero station is entered, so the build replays.
export function HeroFrameBuild() {
  const reduced = useReducedMotion()

  const spring = reduced
    ? { duration: 0.01 }
    : { type: 'spring' as const, stiffness: 380, damping: 18, mass: 0.9 }

  const corners = [
    { key: 'tl', pos: 'top-0 left-0', flex: 'flex-col items-start', from: { x: -40, y: -40 } },
    { key: 'tr', pos: 'top-0 right-0', flex: 'flex-col items-end', from: { x: 40, y: -40 } },
    { key: 'bl', pos: 'bottom-0 left-0', flex: 'flex-col-reverse items-start', from: { x: -40, y: 40 } },
    { key: 'br', pos: 'bottom-0 right-0', flex: 'flex-col-reverse items-end', from: { x: 40, y: 40 } },
  ] as const

  const seg = { boxShadow: '0 0 12px #B8F02688' }

  return (
    <div className="absolute inset-3 md:inset-5 pointer-events-none" aria-hidden="true">
      {/* Horizontal edge segments extending inward from each corner */}
      <motion.div className="absolute top-0 left-0 h-[3px] bg-[#B8F026]" style={seg} initial={{ width: 0, opacity: 0 }} animate={{ width: '38%', opacity: 0.5 }} transition={{ ...spring, delay: 0.15 }} />
      <motion.div className="absolute top-0 right-0 h-[3px] bg-[#B8F026]" style={seg} initial={{ width: 0, opacity: 0 }} animate={{ width: '38%', opacity: 0.5 }} transition={{ ...spring, delay: 0.2 }} />
      <motion.div className="absolute bottom-0 left-0 h-[3px] bg-[#B8F026]" style={seg} initial={{ width: 0, opacity: 0 }} animate={{ width: '38%', opacity: 0.5 }} transition={{ ...spring, delay: 0.25 }} />
      <motion.div className="absolute bottom-0 right-0 h-[3px] bg-[#B8F026]" style={seg} initial={{ width: 0, opacity: 0 }} animate={{ width: '38%', opacity: 0.5 }} transition={{ ...spring, delay: 0.3 }} />
      {/* Vertical edge segments */}
      <motion.div className="absolute top-0 left-0 w-[3px] bg-[#B8F026]" style={seg} initial={{ height: 0, opacity: 0 }} animate={{ height: '32%', opacity: 0.5 }} transition={{ ...spring, delay: 0.15 }} />
      <motion.div className="absolute top-0 right-0 w-[3px] bg-[#B8F026]" style={seg} initial={{ height: 0, opacity: 0 }} animate={{ height: '32%', opacity: 0.5 }} transition={{ ...spring, delay: 0.2 }} />
      <motion.div className="absolute bottom-0 left-0 w-[3px] bg-[#B8F026]" style={seg} initial={{ height: 0, opacity: 0 }} animate={{ height: '32%', opacity: 0.5 }} transition={{ ...spring, delay: 0.25 }} />
      <motion.div className="absolute bottom-0 right-0 w-[3px] bg-[#B8F026]" style={seg} initial={{ height: 0, opacity: 0 }} animate={{ height: '32%', opacity: 0.5 }} transition={{ ...spring, delay: 0.3 }} />

      {/* Thick corner plates snapping into place */}
      {corners.map((c, i) => (
        <motion.div
          key={c.key}
          className={`absolute ${c.pos} flex ${c.flex}`}
          initial={{ opacity: 0, ...c.from, scale: 1.4 }}
          animate={{ opacity: 0.9, x: 0, y: 0, scale: 1 }}
          transition={{ ...spring, delay: 0.05 + i * 0.06 }}
        >
          <div style={{ width: 30, height: 6, background: '#B8F026', boxShadow: '0 0 14px #B8F026' }} />
          <div style={{ width: 6, height: 30, background: '#E040B0', boxShadow: '0 0 14px #E040B0' }} />
        </motion.div>
      ))}
    </div>
  )
}

'use client'

import { ReactNode, useEffect, useState } from 'react'

/** True only after the component has mounted on the client. Use to gate browser-only values. */
export function useMounted(): boolean {
  const [mounted, setMounted] = useState(false)
  useEffect(() => setMounted(true), [])
  return mounted
}

/**
 * Renders children only after client mount, so SSR output stays deterministic.
 * Use for anything that differs between server and client (window/localStorage reads,
 * user timezone/locale values, random ids, live clocks, third-party widgets).
 * Pass a `fallback` matching the final size to avoid layout shift.
 */
export function ClientOnly({ children, fallback = null }: { children: ReactNode; fallback?: ReactNode }) {
  const mounted = useMounted()
  return <>{mounted ? children : fallback}</>
}

import bcrypt from 'bcryptjs'
import { createHash, randomBytes } from 'crypto'

/**
 * Control-room passcode. Only a bcrypt hash is stored (env ADMIN_PASSCODE_HASH_B64, base64 so the
 * `$` characters survive .env parsing). Validation is server-side only, behind a per-IP limiter
 * and a global limiter. Admin sessions carry a fingerprint of the current hash: rotating the
 * passcode instantly demotes every older admin session.
 */
export const ADMIN_PRINCIPAL_EMAIL = 'control-room@baseline.velocity'

const WINDOW_MS = 15 * 60 * 1000
const MAX_PER_IP = 5
const LOCK_MS = 15 * 60 * 1000
const MAX_GLOBAL = 40

type Entry = { fails: number[]; lockedUntil: number }
type Limiter = { ips: Map<string, Entry>; global: number[]; globalLockedUntil: number }
const g = globalThis as unknown as { __bvAdminLimiter?: Limiter }
const state: Limiter = (g.__bvAdminLimiter ??= { ips: new Map<string, Entry>(), global: [] as number[], globalLockedUntil: 0 })

function storedHash(): string | null {
  const b64 = process.env.ADMIN_PASSCODE_HASH_B64
  if (!b64) return null
  try {
    const h = Buffer.from(b64, 'base64').toString('utf8')
    return h.startsWith('$2') ? h : null
  } catch {
    return null
  }
}

export function adminFingerprint(): string | null {
  const h = storedHash()
  return h ? createHash('sha256').update(h).digest('hex').slice(0, 16) : null
}

export function clientIp(req?: Request | null): string {
  const h = req?.headers
  const fwd = h?.get('x-forwarded-for')?.split(',')[0]?.trim()
  return fwd || h?.get('x-real-ip') || 'unknown'
}

function prune(list: number[], now: number) {
  while (list.length && now - list[0] > WINDOW_MS) list.shift()
}

/** Seconds remaining on a lockout for this IP (0 = not locked). */
export function lockRemaining(ip: string): number {
  const now = Date.now()
  const e = state.ips.get(ip)
  const until = Math.max(e?.lockedUntil ?? 0, state.globalLockedUntil)
  return until > now ? Math.ceil((until - now) / 1000) : 0
}

function recordFailure(ip: string) {
  const now = Date.now()
  const e = state.ips.get(ip) ?? { fails: [], lockedUntil: 0 }
  prune(e.fails, now)
  e.fails.push(now)
  if (e.fails.length >= MAX_PER_IP) {
    e.lockedUntil = now + LOCK_MS
    e.fails = []
  }
  state.ips.set(ip, e)
  prune(state.global, now)
  state.global.push(now)
  if (state.global.length >= MAX_GLOBAL) {
    state.globalLockedUntil = now + LOCK_MS
    state.global = []
  }
}

/** One-time sign-in tickets: the passcode is checked once in /api/admin/login, the session is minted from the ticket. */
const tickets = ((globalThis as unknown as { __bvAdminTickets?: Map<string, number> }).__bvAdminTickets ??= new Map<string, number>())
const TICKET_MS = 60 * 1000

export function issueTicket(): string {
  const now = Date.now()
  for (const [t, exp] of tickets) if (exp < now) tickets.delete(t)
  const t = randomBytes(32).toString('hex')
  tickets.set(t, now + TICKET_MS)
  return t
}

export function consumeTicket(t: string): boolean {
  const exp = tickets.get(t)
  if (!exp) return false
  tickets.delete(t)
  return exp >= Date.now()
}

export type PasscodeResult = 'ok' | 'invalid' | 'locked' | 'unconfigured'

export async function verifyPasscode(given: string, ip: string): Promise<PasscodeResult> {
  if (lockRemaining(ip) > 0) return 'locked'
  const hash = storedHash()
  if (!hash) return 'unconfigured'
  const ok = given.length > 0 && given.length <= 200 && (await bcrypt.compare(given, hash))
  if (ok) {
    state.ips.delete(ip)
    return 'ok'
  }
  recordFailure(ip)
  return lockRemaining(ip) > 0 ? 'locked' : 'invalid'
}

