import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { getDumpsterByKey, type DumpsterLocation } from '@/lib/dumpster-locations';
import {
  validatePlanning,
  type CrewMember,
  type ResourceLine,
} from '@/lib/dumpster-planning';
import { type ResourceKey, MAX_ENERGY, ENERGY_COST } from '@/lib/game-data';
import { isValidId } from '@/lib/api-guards';

// ============================================================
// POST: Create / dispatch / move / collect / extract
// ============================================================
export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const { sessionId, action, expeditionId, data } = body ?? {};

    // ----- v0.5.4 DUMPSTER-DIVING DISPATCH ------------------
    // Authoritative server-side planning validation. Steps:
    //   1. Look up the location and confirm it exists.
    //   2. Pull the chosen crew's NPC rows (only recruited NPCs allowed).
    //   3. Pull the player's current resources.
    //   4. Validate: crew size band, skill requirements, resource cost.
    //   5. Atomically deduct resources and create the Expedition row.
    // Returns { expedition, validation } on success or
    // { error, validation } on planning failure.
    if (action === 'dispatch') {
      const locationKey: string | undefined = data?.locationKey;
      const crewIds: string[] = Array.isArray(data?.crewIds) ? data.crewIds : [];

      if (!isValidId(sessionId)) {
        return NextResponse.json({ error: 'Missing sessionId' }, { status: 400 });
      }
      if (!locationKey) {
        return NextResponse.json({ error: 'No dumpster location selected' }, { status: 400 });
      }

      const location: DumpsterLocation | null = getDumpsterByKey(locationKey);
      if (!location) {
        return NextResponse.json({ error: 'Unknown dumpster location' }, { status: 400 });
      }

      // Pull session + npcs + resources in parallel
      const [npcRows, resourceRows, session] = await Promise.all([
        prisma.nPC.findMany({ where: { sessionId, id: { in: crewIds } } }),
        prisma.resource.findMany({ where: { sessionId } }),
        prisma.gameSession.findUnique({ where: { id: sessionId } }),
      ]);
      if (!session) {
        return NextResponse.json({ error: 'Session not found' }, { status: 404 });
      }

      // Check energy
      const energyUsed = session.energyUsed ?? 0;
      const energyLeft = MAX_ENERGY - energyUsed;
      if (energyLeft < ENERGY_COST.expedition) {
        return NextResponse.json({
          error: 'no_energy',
          message: 'Too exhausted to dispatch. Get some sleep.',
        }, { status: 409 });
      }

      const crewMembers: CrewMember[] = npcRows.map((n: any) => ({
        id: n.id,
        name: n.name,
        recruited: n.recruited,
        status: n.status,
        muscle: n.muscle ?? 0,
        brains: n.brains ?? 0,
        unpredictability: n.unpredictability ?? 0,
        heatLevel: n.heatLevel ?? 0,
      }));

      const resourceLines: ResourceLine[] = resourceRows.map((r: any) => ({
        type: r.type,
        quantity: r.quantity,
      }));

      const validation = validatePlanning(location, crewMembers, resourceLines);
      if (!validation.ok) {
        return NextResponse.json(
          {
            error: 'Cannot dispatch: planning is invalid.',
            validation,
          },
          { status: 400 },
        );
      }

      // MOBILITY stat adds bonus move budget: +2 per point above base 2
      const mobility = Math.max(0, Math.min(10, session.mobility ?? 2));
      const mobilityBonus = Math.max(0, mobility - 2) * 2; // 0-16 range

      // Atomic dispatch: deduct cost + create expedition row + spend energy
      const cost = location.cost ?? {};
      const expedition = await prisma.$transaction(async (tx: any) => {
        for (const key of Object.keys(cost) as ResourceKey[]) {
          const amount = cost?.[key] ?? 0;
          if (amount <= 0) continue;
          await tx.resource.update({
            where: { sessionId_type: { sessionId, type: key } },
            data: { quantity: { decrement: amount } },
          });
        }
        // Spend energy
        await tx.gameSession.update({
          where: { id: sessionId },
          data: { energyUsed: { increment: ENERGY_COST.expedition } },
        });
        return tx.expedition.create({
          data: {
            sessionId,
            status: 'ACTIVE',
            crewIds: JSON.stringify(crewIds),
            locationKey,
            positionX: 0,
            positionY: 0,
            // tier-equivalent move budget scales with location difficulty + mobility bonus
            moveLimit: 25 + (location.difficulty - 1) * 5 + mobilityBonus,
          },
        });
      });

      return NextResponse.json({ expedition, validation, location });
    }

    if (action === 'create') {
      const expedition = await prisma.expedition.create({
        data: {
          sessionId,
          status: 'ACTIVE',
          crewIds: JSON.stringify(data?.crewIds ?? []),
          locationKey: data?.locationKey ?? null,
          positionX: 0,
          positionY: 0,
        },
      });
      return NextResponse.json(expedition);
    }

    if (action === 'move' && expeditionId) {
      const exp = await prisma.expedition.findUnique({ where: { id: expeditionId } });
      if (!exp) return NextResponse.json({ error: 'Not found' }, { status: 404 });
      const updated = await prisma.expedition.update({
        where: { id: expeditionId },
        data: {
          positionX: data?.x ?? exp?.positionX ?? 0,
          positionY: data?.y ?? exp?.positionY ?? 0,
          movesUsed: (exp?.movesUsed ?? 0) + (data?.cost ?? 1),
          heatGained: (exp?.heatGained ?? 0) + (data?.heat ?? 0),
        },
      });
      return NextResponse.json(updated);
    }

    if (action === 'collect' && expeditionId) {
      const exp = await prisma.expedition.findUnique({ where: { id: expeditionId } });
      if (!exp) return NextResponse.json({ error: 'Not found' }, { status: 404 });
      let collected: any[] = [];
      try { collected = JSON.parse(exp?.collected ?? '[]'); } catch { collected = []; }
      collected.push(data?.resource ?? {});
      const updated = await prisma.expedition.update({
        where: { id: expeditionId },
        data: {
          collected: JSON.stringify(collected),
          heatGained: (exp?.heatGained ?? 0) + (data?.heat ?? 0),
          movesUsed: (exp?.movesUsed ?? 0) + 1,
        },
      });
      return NextResponse.json(updated);
    }

    if (action === 'extract' && expeditionId) {
      const exp = await prisma.expedition.findUnique({ where: { id: expeditionId } });
      if (!exp) return NextResponse.json({ error: 'Not found' }, { status: 404 });
      let collected: any[] = [];
      try { collected = JSON.parse(exp?.collected ?? '[]'); } catch { collected = []; }

      // Add collected resources to session
      for (const item of collected) {
        if (item?.type && item?.quantity) {
          await prisma.resource.upsert({
            where: { sessionId_type: { sessionId: exp.sessionId, type: item.type } },
            update: { quantity: { increment: item.quantity } },
            create: { sessionId: exp.sessionId, type: item.type, quantity: item.quantity },
          });
        }
      }

      // Update session heat
      await prisma.gameSession.update({
        where: { id: exp.sessionId },
        data: { heat: { increment: exp?.heatGained ?? 0 } },
      });

      const updated = await prisma.expedition.update({
        where: { id: expeditionId },
        data: { status: 'COMPLETED' },
      });
      return NextResponse.json(updated);
    }

    return NextResponse.json({ error: 'Invalid action' }, { status: 400 });
  } catch (err: unknown) {
    console.error('Expedition error:', err);
    return NextResponse.json({ error: 'Failed' }, { status: 500 });
  }
}

