function navigate(link: string, target: string) {
  if (target === 'new_tab') {
    const w = window.open(link, '_blank', 'noopener')
    if (!w) window.location.href = link // popup blocked: still get the player to the game
  } else {
    window.location.href = link
  }
}

interface Options {
  targetRef: RefObject<HTMLElement | null>
  title: string
  launchLink: string
  linkTarget: string
  status: string
  imageUrl: string | null
  onStateChange?: (state: LaunchState) => void
}

/** The single activation sequence: standby → ready → activating → panel expands into the destination. */
export function useLaunchSequence({ targetRef, title, launchLink, linkTarget, status, imageUrl, onStateChange }: Options) {
  const [state, setState] = useState<LaunchState>('idle')
  const [flashing, setFlashing] = useState(false)
  const [overlay, setOverlay] = useState<{ rect: DOMRect; phase: LaunchPhase } | null>(null)
  const [mounted, setMounted] = useState(false)
  const busy = useRef(false)
  const reducedMotion = useRef(false)
  const timers = useRef<number[]>([])

  useEffect(() => {
    setMounted(true)
    reducedMotion.current = window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches ?? false
    const t = timers.current
    return () => t.forEach((x) => window.clearTimeout(x))
  }, [])

  const isComingSoon = status === 'coming_soon'
  const hasLink = !!launchLink && launchLink !== '#'
  const outcome: 'launch' | 'pending' | 'offline' = isComingSoon ? 'offline' : hasLink ? 'launch' : 'pending'

  const later = (fn: () => void, ms: number) => {
    timers.current.push(window.setTimeout(fn, ms))
  }

  const update = useCallback(
    (s: LaunchState) => {
      setState(s)
      onStateChange?.(s)
    },
    [onStateChange]
  )

  const arm = useCallback(() => {
    if (!busy.current) update('ready')
  }, [update])
  const disarm = useCallback(() => {
    if (!busy.current) update('idle')
  }, [update])

  const activate = useCallback(() => {
    if (busy.current) return
    busy.current = true
    haptic('press')

    if (reducedMotion.current) {
      if (outcome === 'launch') { recordLaunch(title); navigate(launchLink, linkTarget) }
      else haptic('error')
      busy.current = false
      return
    }

    haptic('activate')
    update('activating')
    setFlashing(true)
    later(() => setFlashing(false), 160)

    const el = targetRef.current
    if (el) {
      for (let i = 0; i < 2; i++) {
        const p = document.createElement('div')
        p.className = 'steam-particle'
        Object.assign(p.style, {
          position: 'absolute',
          width: `${50 + Math.random() * 30}px`,
          height: `${70 + Math.random() * 50}px`,
          background: 'rgb(var(--bv-text-rgb) / 0.12)',
          filter: 'blur(12px)',
          borderRadius: '50%',
          pointerEvents: 'none',
          zIndex: '1',
          opacity: '0',
          animation: 'steam-rise 1500ms ease-out forwards',
          ...(i === 0 ? { left: '5%', bottom: '5%' } : { right: '5%', bottom: '5%' }),
        })
        el.appendChild(p)
        later(() => p.remove(), 1500)
      }
    }

    later(() => {
      const rect = targetRef.current?.getBoundingClientRect()
      if (rect) setOverlay({ rect, phase: 'grow' })
    }, 450)

    later(() => {
      update('active')
      if (outcome === 'launch') {
        haptic('complete')
        recordLaunch(title)
        navigate(launchLink, linkTarget)
      } else {
        haptic('error')
      }
      setOverlay((o) => (o ? { ...o, phase: 'hold' } : o))
    }, 1250)

    const holdMs = outcome === 'launch' ? 700 : 1500
    later(() => {
      const rect = targetRef.current?.getBoundingClientRect()
      setOverlay((o) => (o ? { rect: rect ?? o.rect, phase: 'collapse' } : o))
    }, 1250 + holdMs)

    later(() => {
      setOverlay(null)
      update('idle')
      busy.current = false
    }, 1250 + holdMs + 650)
  }, [launchLink, linkTarget, outcome, update, targetRef, title])

  const overlayNode =
    mounted && overlay
      ? createPortal(
          <LaunchOverlay
            rect={{ top: overlay.rect.top, left: overlay.rect.left, width: overlay.rect.width, height: overlay.rect.height }}
            phase={overlay.phase}
            title={title}
            imageUrl={imageUrl}
            outcome={outcome}
          />,
          document.body
        )
      : null

  return { state, flashing, outcome, isComingSoon, hasLink, arm, disarm, activate, overlayNode }
}

