}

.rule-list li + li {
  margin-top: var(--space-2);
}

.state-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--space-3);
  margin-top: var(--space-4);
}

.empty-state,
.error-state,
.loading-state {
  display: grid;
  gap: var(--space-2);
  min-height: 9rem;
