  animation: shimmer 1.3s ease-in-out infinite;
}

.skeleton-line.short {
  width: 62%;
}

@keyframes shimmer {
  from {
    background-position: 200% 0;
  }
  to {
    background-position: -200% 0;
  }
}

.notes-dialog {
  width: min(38rem, calc(100vw - 2rem));
