  color: var(--color-text);
}

.notes-dialog::backdrop {
  background: rgba(0, 0, 0, 0.72);
  backdrop-filter: blur(0.35rem);
}

.dialog-frame {
  position: relative;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  padding: var(--space-6);
  background: var(--color-surface-solid);
  box-shadow: var(--shadow-panel);
}

.dialog-frame h2 {
  margin: var(--space-2) 0 var(--space-4);
}

.dialog-frame p + p {
  margin-top: var(--space-4);
  color: var(--color-text-muted);
}

.dialog-close {
  position: absolute;
  top: var(--space-3);
  right: var(--space-3);
  width: 2.75rem;
  height: 2.75rem;
  border: 1px solid var(--color-border);
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.04);
  color: var(--color-text);
  font-size: var(--text-lg);
}

@media (max-width: 980px) {
  .app-shell {
    grid-template-columns: 1fr;
  }

  .sidebar {
    position: relative;
    height: auto;
    padding: var(--space-4);
    gap: var(--space-3);
  }

  .brand-lockup {
    grid-template-columns: 2.4rem 1fr;
    gap: var(--space-2);
  }

  .brand-lockup .eyebrow {
    font-size: 0.68rem;
  }

  h1 {
    font-size: 1.35rem;
  }

  .nav-list {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    overflow: visible;
    padding-bottom: 0;
    gap: var(--space-2);
  }

  .nav-item {
    min-width: 0;
    min-height: 2.5rem;
    padding: var(--space-2) var(--space-3);
    gap: var(--space-2);
    font-size: 0.78rem;
  }

  .sidebar-card {
    display: none;
  }

  .mode-toggle {
    max-width: 14rem;
    min-height: 2.5rem;
    padding: var(--space-2) var(--space-3);
  }

  .stage {
    padding: var(--space-4);
  }

  .topbar {
    display: grid;
    margin-bottom: var(--space-4);
  }

  .title-layout,
  .hud-grid,
  .recruit-layout,
  .encounter-layout,
  .travel-layout,
  .sleep-layout,
  .finale-layout,
  .codex-layout,
  .kit-layout {
    grid-template-columns: 1fr;
  }

  .hero-panel,
  .portrait-card,
  .ritual-image,
  .finale-target,
  .scene-window,
  .map-panel {
    min-height: 28rem;
  }

  .swatches,
  .state-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 620px) {
  .hero-overlay {
    right: var(--space-3);
    bottom: var(--space-3);
    left: var(--space-3);
    padding: var(--space-4);
  }

  .hero-overlay h3 {
    font-size: clamp(2rem, 12vw, 3.4rem);
  }

  .status-strip,
  .button-row,
  .crew-chips {
    justify-content: flex-start;
  }

  .resource-grid,
  .verb-bar,
  .step-tabs,
  .brain-grid,
  .dose-track,
  .substance-row,
  .ritual-progress {
    grid-template-columns: 1fr;
  }

  .bin-row {
    right: var(--space-4);
    left: var(--space-4);
    grid-template-columns: 1fr;
  }

  .route-card div {
    grid-template-columns: 1fr;
    gap: var(--space-1);
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }
}

'use client';

import { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import dynamic from 'next/dynamic';
import { AnimatePresence, motion } from 'framer-motion';
import { calculateEscalation, type EscalationState } from '@/lib/escalation';
import type { GameNPC, GameResource, GameExpedition, GameMission } from '@/lib/types';
import { getDirective } from '@/lib/directives';
import { playAmbientHub, playAmbientExpedition, playAmbientScrapbook, stopAmbientLoop, stopMenuMusic, loadMutedFromStorage, loadVolumesFromStorage, toggleMuted, enableRadioMode, disableRadioMode } from '@/lib/sound-effects';
import { audioManager } from '@/app/_lib/audio-manager';
import HotkeyOverlay from './ui/hotkey-overlay';
import ResourceDeltaFloaters from './ui/resource-delta-floater';
import FullscreenEnforcer from './ui/fullscreen-enforcer';
import { StatusBar } from './ui/status-bar';
// Win-sweep v1: Lazy-load 6 UI overlays — not needed until user triggers them
const MemoReveal = dynamic(() => import('./ui/memo-reveal'), { ssr: false });
const RealityBleedOverlay = dynamic(() => import('./ui/reality-bleed-overlay'), { ssr: false });
const SettingsOverlay = dynamic(() => import('./ui/settings-overlay'), { ssr: false });
const GuideOverlay = dynamic(() => import('./ui/guide-overlay'), { ssr: false });
const OnboardingCarousel = dynamic(() => import('./ui/onboarding-carousel'), { ssr: false });
// Static imports — early flow screens + core hub (always needed quickly)
import DevIntroScreen from './screens/dev-intro-screen';
import DisclaimerScreen from './screens/disclaimer-screen';
import PipeLoadingScreen from './screens/pipe-loading-screen';
import LaunchIntroScreen from './screens/launch-intro-screen';
import MenuTransitionScreen from './screens/menu-transition-screen';
import MainMenuScreen from './screens/main-menu-screen';
import TitleSlideshowScreen from './screens/title-slideshow-screen';
import HubScreen from './screens/hub-screen';

// Dynamic imports — gameplay stations + later screens (lazy-loaded per phase)
const CharacterCreator = dynamic(() => import('./screens/character-creator'), { ssr: false });
const CharacterSequence = dynamic(() => import('./screens/character-sequence'), { ssr: false });
const ClipboardStation = dynamic(() => import('./stations/clipboard-station'), { ssr: false });
const InventoryStation = dynamic(() => import('./stations/inventory-station'), { ssr: false });
const DumpsterPlanningClipboard = dynamic(() => import('./expedition/dumpster-planning-clipboard'), { ssr: false });
const ShoeboxStation = dynamic(() => import('./stations/shoebox-station'), { ssr: false });
const DossierStation = dynamic(() => import('./stations/dossier-station'), { ssr: false });
const RecruitmentFlow = dynamic(() => import('./recruitment/recruitment-flow'), { ssr: false });
const ComicViewer = dynamic(() => import('./directives/comic-viewer'), { ssr: false });
const DirectiveHand = dynamic(() => import('./directives/directive-hand'), { ssr: false });
const NightCycleScreen = dynamic(() => import('./screens/night-cycle-screen'), { ssr: false });
const NightBlackoutScreen = dynamic(() => import('./screens/night-blackout-screen'), { ssr: false });
const RaidScreen = dynamic(() => import('./screens/raid-screen'), { ssr: false });
const GameOverScreen = dynamic(() => import('./screens/game-over-screen'), { ssr: false });
const WelcomeBackScreen = dynamic(() => import('./screens/welcome-back-screen'), { ssr: false });
const AscensionScreen = dynamic(() => import('./screens/ascension-screen'), { ssr: false });
const OperationsBoard = dynamic(() => import('./stations/operations-board'), { ssr: false });
const ScroungeStation = dynamic(() => import('./stations/scrounge-station'), { ssr: false });
const ScavengeMapStation = dynamic(() => import('./stations/scavenge-map-station'), { ssr: false });
const TacticalBoard = dynamic(() => import('./expedition/tactical-board'), { ssr: false });
// CodexStation + ScrapbookStation merged into ShoeboxStation
// DoseStation is now embedded inside InventoryStation (Substances tab)
const CoffeeStation = dynamic(() => import('./stations/coffee-station'), { ssr: false });
// DayEndScreen needs type import for ConsumptionResult
import { type ConsumptionResult } from './screens/day-end-screen';
const DayEndScreen = dynamic(() => import('./screens/day-end-screen'), { ssr: false });

export type GamePhase = 
  | 'dev_intro' | 'disclaimer' | 'pipe_loading' | 'launch_intro' | 'menu_transition' | 'menu' | 'title_slideshow'
  | 'character_creator' | 'character_sequence' | 'hub'
  | 'clipboard' | 'inventory' | 'map_table' | 'hallucination' | 'operations' | 'scrounge' | 'codex' | 'scrapbook' | 'coffee' | 'shoebox' | 'dossier' | 'sleep' | 'scavenge_map'
  | 'recruiting' | 'expedition' | 'directive_intro' | 'directive_outro'
  | 'night_cycle' | 'night_blackout' | 'day_end'
  | 'raid' | 'game_over' | 'welcome_back' | 'ascension';

export interface GameState {
  sessionId: string | null;
  phase: GamePhase;
  day: number;
  heat: number;
  npcs: GameNPC[];
  resources: GameResource[];
  expeditions: GameExpedition[];
  missions: GameMission[];
  selectedNpcId: string | null;
  activeExpeditionId: string | null;
  activeDirectiveNpcKey: string | null;
  playerName: string;
  philosophy: string;
  nerve: number;
  insight: number;
  presence: number;
  mobility: number;
  energyUsed: number;
  totalCoffees: number;
}

const initialState: GameState = {
  sessionId: null,
  phase: 'dev_intro',
  day: 1,
  heat: 0,
  npcs: [],
  resources: [],
  expeditions: [],
  missions: [],
  selectedNpcId: null,
  activeExpeditionId: null,
  activeDirectiveNpcKey: null,
  playerName: 'Manager',
  philosophy: 'shepherd',
  nerve: 2,
  insight: 2,
  presence: 2,
  mobility: 2,
  energyUsed: 0,
  totalCoffees: 0,
};

type QueuedNotification = { id: number; msg: string };

export default function GameClient() {
  const [game, setGame] = useState<GameState>(initialState);
  const [loading, setLoading] = useState(false);
  // v0.5.0: notifications are now a queue so rapid-fire events don't clobber each other
  const [notifications, setNotifications] = useState<QueuedNotification[]>([]);
  const notifIdRef = useRef(1);
  const [adminFlash, setAdminFlash] = useState(false);
  const [lastAdminNpcId, setLastAdminNpcId] = useState<string | null>(null);
  const [raidResult, setRaidResult] = useState<{ resourcesLost: { type: string; lost: number }[]; heatAfter: number; survived: boolean } | null>(null);
  const [gameOverReason, setGameOverReason] = useState<'heat' | 'raid'>('heat');
  // After the title_slideshow ends we branch to either character_creator (new) or welcome_back (load)
  const [postSlideshowPhase, setPostSlideshowPhase] = useState<GamePhase>('character_creator');
  // Night-cycle consumption result — computed server-side when entering night_cycle, displayed in day_end
  const [consumption, setConsumption] = useState<ConsumptionResult | null>(null);
  // v0.5.0 overlays
  const [hotkeyOpen, setHotkeyOpen] = useState(false);
  // Win 25: Screen reader phase announcements
  const [srAnnouncement, setSrAnnouncement] = useState('');
  // v0.9.1 overlays
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [guideOpen, setGuideOpen] = useState(false);
  const [onboardingOpen, setOnboardingOpen] = useState(false);

  // Calculate escalation from game state
  const escalation: EscalationState = useMemo(() => calculateEscalation(game), [game]);

  // Ambient sound management — switch loops based on phase
  useEffect(() => {
    const phase = game?.phase;
    // v0.5.5 — Wesley's flow: theme song carries through menu →
    // character_creator/welcome_back → bedroom hub. At the hub the song gets
    // a "playing on a radio in another room" treatment via radio-mode.
    const menuMusicPhases: GamePhase[] = [
      'menu',
      'title_slideshow',
      'character_creator',
      'welcome_back',
      'character_sequence',
      'hub',
    ];
    if (!menuMusicPhases.includes(phase)) {
      // We've left menu/hub territory — drop radio mode (idempotent), fade out.
      disableRadioMode();
      stopMenuMusic();
    }
    // Radio-mode toggle: ON only at the hub, OFF everywhere else.
    if (phase === 'hub') {
      enableRadioMode();
      // v0.9.1 — Restore room-appropriate music when returning to hub from any station
      audioManager.restoreRoomMusic();
      // v1.3 — Auto-show onboarding carousel on first hub entry
      if (typeof window !== 'undefined' && !window.localStorage.getItem('baf3k_onboarding_done')) {
        setOnboardingOpen(true);
      }
    } else {
      disableRadioMode();
    }
    if (phase === 'hub' || phase === 'clipboard' || phase === 'hallucination' || phase === 'operations' || phase === 'scrounge' || phase === 'scavenge_map' || phase === 'codex' || phase === 'shoebox' || phase === 'dossier') {
      playAmbientHub(escalation.level);
    } else if (phase === 'inventory') {
      playAmbientHub(escalation.level); // v5.0 — stash music removed, use hub ambient
    } else if (phase === 'expedition') {
      playAmbientExpedition();
    } else {
      stopAmbientLoop();
    }
    return () => { /* don't stop on unmount — let it carry across transitions */ };
  }, [game?.phase, escalation.level]);

  // v0.9.1 — Safety valve: bump pressure + SFX when cigarettes critical (per-day guard)
  const safetyValveTriggeredRef = useRef(false);
  const prevDayRef = useRef(game?.day ?? 1);

  useEffect(() => {
    const currentDay = game?.day ?? 1;
    if (currentDay !== prevDayRef.current) {
      safetyValveTriggeredRef.current = false;
      prevDayRef.current = currentDay;
    }
  }, [game?.day]);

  useEffect(() => {
    const cigs = (game?.resources ?? []).find((r) => r?.type === 'cigarettes')?.quantity ?? 0;
    if (cigs <= 1 && game?.phase === 'hub' && !safetyValveTriggeredRef.current) {
      audioManager.triggerSafetyValve();
      safetyValveTriggeredRef.current = true;
    }
  }, [game?.resources, game?.phase]);

  const showNotification = useCallback((msg: string) => {
    const id = notifIdRef.current++;
    setNotifications(prev => [...prev, { id, msg }]);
    setTimeout(() => {
      setNotifications(prev => prev.filter(n => n.id !== id));
    }, 3000);
  }, []);

  // v0.5.0: load persisted mute state at mount so muted flag is ready before
  // any synthesis fires. MuteToggle subscribes internally for its icon state.
  useEffect(() => {
    loadMutedFromStorage();
    loadVolumesFromStorage();
  }, []);

  // v0.9.1 — AudioManager init + browser autoplay unlock
  useEffect(() => {
    audioManager.init();

    const unlock = () => {
      audioManager.unlock();
      window.removeEventListener('pointerdown', unlock);
      window.removeEventListener('keydown', unlock);
    };

    window.addEventListener('pointerdown', unlock);
    window.addEventListener('keydown', unlock);

    return () => {
      window.removeEventListener('pointerdown', unlock);
      window.removeEventListener('keydown', unlock);
    };
  }, []);

  const handleToggleMute = useCallback(() => { toggleMuted(); }, []);

  const triggerAdminFlash = useCallback((npcId?: string) => {
    setAdminFlash(true);
    if (npcId) {
      setLastAdminNpcId(npcId);
      setTimeout(() => setLastAdminNpcId(null), 2000);
    }
    setTimeout(() => setAdminFlash(false), 1500);
  }, []);

  // Win 25: Human-readable phase labels for screen readers
  const PHASE_LABELS: Partial<Record<GamePhase, string>> = useMemo(() => ({
    hub: 'Hub — Operations Centre',
    clipboard: 'Crew Board',
    inventory: 'The Stash — Inventory',
    map_table: 'Expedition Planning',
    expedition: 'Tactical Expedition',
    operations: 'Operations Board',
    scavenge_map: 'Forage Map',

    hallucination: 'The Shrine',
    codex: 'The Box — Documents',
    scrapbook: 'The Shoebox — Mother\'s Scrapbook',
    shoebox: 'The Shoebox',
    dossier: 'Manager Dossier',
    scrounge: 'Scrounge — Alley Search',
    recruiting: 'Recruitment — The Intake',
    night_cycle: 'Night Cycle',
    day_end: 'Day End Report',
    menu: 'Main Menu',
    character_creator: 'Character Creation',
    game_over: 'Game Over',
  }), []);

  const setPhase = useCallback((phase: GamePhase) => {
    setGame((prev: GameState) => ({ ...prev, phase }));
    const label = PHASE_LABELS[phase];
    if (label) setSrAnnouncement(label);
  }, [PHASE_LABELS]);

  const loadGame = useCallback(async (sessionId?: string) => {
    try {
      setLoading(true);
      const url = sessionId ? `/api/game?id=${sessionId}` : '/api/game';
      const res = await fetch(url);
      if (!res?.ok) return null;
      const data = await res.json();
      if (data && !data?.error) {
        setGame((prev: GameState) => ({
          ...prev,
          sessionId: data?.id ?? null,
          day: data?.day ?? 1,
          heat: data?.heat ?? 0,
          npcs: data?.npcs ?? [],
          resources: data?.resources ?? [],
          expeditions: data?.expeditions ?? [],
          missions: data?.missions ?? [],
          playerName: data?.playerName ?? prev.playerName ?? 'Manager',
          philosophy: data?.philosophy ?? prev.philosophy ?? 'shepherd',
          nerve: data?.nerve ?? prev.nerve ?? 2,
          insight: data?.insight ?? prev.insight ?? 2,
          presence: data?.presence ?? prev.presence ?? 2,
          mobility: data?.mobility ?? prev.mobility ?? 2,
          energyUsed: data?.energyUsed ?? 0,
          totalCoffees: data?.totalCoffees ?? 0,
        }));
        return data;
      }
      return null;
    } catch (err: unknown) {
      console.error('Load game error:', err);
      return null;
    } finally {
      setLoading(false);
    }
  }, []);

  const newGame = useCallback(async () => {
    try {
      setLoading(true);
      const res = await fetch('/api/game', { method: 'POST' });
      if (!res?.ok) throw new Error('Failed to create game');
      const data = await res.json();
      setGame((prev: GameState) => ({
        ...prev,
        sessionId: data?.id ?? null,
        day: data?.day ?? 1,
        heat: data?.heat ?? 0,
        npcs: data?.npcs ?? [],
        resources: data?.resources ?? [],
        expeditions: [],
        missions: data?.missions ?? [],
        playerName: data?.playerName ?? 'Manager',
        philosophy: data?.philosophy ?? 'shepherd',
        nerve: data?.nerve ?? 2,
        insight: data?.insight ?? 2,
        presence: data?.presence ?? 2,
        mobility: data?.mobility ?? 2,
        energyUsed: 0,
        totalCoffees: 0,
        // Route through title_slideshow first; slideshow advances to character_creator.
        phase: 'title_slideshow',
      }));
      setPostSlideshowPhase('character_creator');
      if (typeof window !== 'undefined') {
        localStorage.setItem('baf_session_id', data?.id ?? '');
      }
      return data;
    } catch (err: unknown) {
      console.error('New game error:', err);
      showNotification('Failed to start new game. Try again.');
      return null;
    } finally {
      setLoading(false);
    }
  }, [showNotification]);

  const continueGame = useCallback(async () => {
    const savedId = typeof window !== 'undefined' ? localStorage.getItem('baf_session_id') : null;
    const data = await loadGame(savedId ?? undefined);
    if (data) {
      // Route through title_slideshow first; slideshow advances to welcome_back.
      setPostSlideshowPhase('welcome_back');
      setPhase('title_slideshow');
      return true;
    }
    showNotification('No saved game found. Starting new game...');
    return false;
  }, [loadGame, setPhase, showNotification]);

  const refreshGameState = useCallback(async () => {
    if (game?.sessionId) {
      await loadGame(game.sessionId);
    }
  }, [game?.sessionId, loadGame]);

  const selectNpc = useCallback((npcId: string | null) => {
    setGame((prev: GameState) => ({ ...prev, selectedNpcId: npcId }));
  }, []);

  // v0.5.0: Global keyboard shortcuts
  // M — toggle mute, ? — hotkey overlay, ESC — back to hub (station phases),
  // E — end day (hub only).
  useEffect(() => {
    const isTypingTarget = (el: EventTarget | null): boolean => {
      if (!el || !(el instanceof HTMLElement)) return false;
      const tag = el.tagName;
      return tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || el.isContentEditable;
    };
    const STATION_PHASES: GamePhase[] = ['clipboard', 'inventory', 'map_table', 'hallucination', 'operations', 'scrounge', 'scavenge_map', 'codex', 'coffee', 'shoebox', 'dossier'];
    const onKey = (e: KeyboardEvent) => {
      if (isTypingTarget(e.target)) return;
      // M — mute (not inside modal/overlay either — always respect)
      if (e.key === 'm' || e.key === 'M') {
        e.preventDefault();
        handleToggleMute();
        return;
      }
      // ? — hotkey overlay (Shift+/ on most layouts)
      if (e.key === '?' || (e.shiftKey && e.key === '/')) {
        e.preventDefault();
        setHotkeyOpen((prev) => !prev);
        return;
      }
      // ESC — close overlays first; else back-to-hub on station phases
      if (e.key === 'Escape') {
        if (settingsOpen) { setSettingsOpen(false); return; }
        if (guideOpen) { setGuideOpen(false); return; }
        if (hotkeyOpen) { setHotkeyOpen(false); return; }
        if (STATION_PHASES.includes(game.phase)) {
          e.preventDefault();
          setPhase('hub');
        }
        return;
      }
      // E — end day (hub only)
      if ((e.key === 'e' || e.key === 'E') && game.phase === 'hub') {
        e.preventDefault();
        setConsumption(null);
        setPhase('night_cycle');
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [game.phase, hotkeyOpen, settingsOpen, guideOpen, setPhase, handleToggleMute]);

  // Neon border phase — maps game phase to colour group
  const neonPhase = useMemo(() => {
    const p = game.phase;
    const preGame = ['dev_intro', 'disclaimer', 'pipe_loading', 'launch_intro', 'menu_transition', 'menu', 'title_slideshow', 'character_creator', 'character_sequence'];
    if (preGame.includes(p)) return 'none';
    if (p === 'expedition') return 'expedition';
    if (p === 'directive_intro' || p === 'directive_outro') return 'none'; // fullscreen comic — no border
    if (p === 'recruiting') return 'recruit';
    return p;
  }, [game.phase]);

  // Click particle burst handler — spawns a neon ring + radial lines at click point
  useEffect(() => {
    const handler = (e: PointerEvent) => {
      const target = e.target as HTMLElement;
      // Only fire on interactive elements (buttons, links, clickable things)
      if (!target.closest('button, a, [role="button"], [data-clickable]')) return;
      const burst = document.createElement('div');
      burst.className = 'click-burst';
      burst.style.left = `${e.clientX}px`;
      burst.style.top = `${e.clientY}px`;
      // Add 4 radial lines
      for (let i = 0; i < 4; i++) {
        const line = document.createElement('div');
        line.className = 'click-burst-line';
        line.style.transform = `rotate(${i * 90 + 45}deg)`;
        burst.appendChild(line);
      }
      document.body.appendChild(burst);
      setTimeout(() => burst.remove(), 450);
    };
    window.addEventListener('pointerdown', handler);
    return () => window.removeEventListener('pointerdown', handler);
  }, []);

  // v0.5.0: vignette intensity based on phase
  // (Stations darker than hub, disclaimer/intro cleanest.)
  const vignetteIntensity = useMemo(() => {
    const p = game.phase;
    if (['dev_intro', 'disclaimer', 'pipe_loading', 'launch_intro', 'menu_transition', 'menu', 'title_slideshow'].includes(p)) return 0.4;
    if (p === 'hub') return 0.5;
    if (['clipboard', 'inventory', 'map_table', 'operations', 'scavenge_map'].includes(p)) return 0.6;
    if (['hallucination', 'shoebox', 'dossier', 'night_cycle', 'night_blackout', 'raid', 'game_over'].includes(p)) return 0.9;
    return 0.5;
  }, [game.phase]);

  return (
    <main
      id="main-content"
      role="main"
      data-neon-phase={neonPhase}
      className={`w-screen h-screen overflow-hidden relative bg-[#080808] ${adminFlash ? 'admin-flash' : ''}`}
      style={{ '--vignette-intensity': String(vignetteIntensity) } as React.CSSProperties}
    >
      {/* Terminal corner brackets — neon colour syncs with phase */}
      <div className="terminal-corner terminal-corner--tl" aria-hidden="true" />
      <div className="terminal-corner terminal-corner--tr" aria-hidden="true" />
      <div className="terminal-corner terminal-corner--bl" aria-hidden="true" />
      <div className="terminal-corner terminal-corner--br" aria-hidden="true" />

      {/* Holographic scanline overlay — persistent CRT visor effect */}
      <div className="terminal-scanlines" aria-hidden="true" />

      {/* Atmosphere VFX — floating dust, VHS tracking, film grain */}
      <div className="atmosphere-dust" aria-hidden="true" />
      <div className="atmosphere-vhs-bar" aria-hidden="true" />
      <div className="atmosphere-grain" aria-hidden="true" />

      {/* Moving scanline bar — intensity scales with escalation */}
      <div className="fixed inset-0 pointer-events-none z-50" aria-hidden="true" style={{ opacity: 0.03 + escalation.flickerIntensity * 0.04 }}>
        <div className="w-full h-[2px] bg-[#8aad7a] animate-scanline" />
      </div>

      {/* Fluorescent buzz line — appears at escalation 2+ */}
      {escalation.level >= 2 && (
        <div className="fixed top-0 left-0 right-0 h-[1px] z-50 pointer-events-none fluorescent-buzz" aria-hidden="true" />
      )}

      {/* Grime vignette — scales with escalation AND phase intensity (v0.5.0) */}
      <div
        className="fixed inset-0 pointer-events-none z-40 vignette-layer"
        aria-hidden="true"
        style={{
          background: `radial-gradient(ellipse at center, transparent ${Math.max(30, 60 - escalation.level * 3 - (vignetteIntensity - 0.5) * 20)}%, rgba(0,0,0,${Math.min(0.55, 0.1 + escalation.level * 0.04 + (vignetteIntensity - 0.5) * 0.3)}) 100%)`,
        }}
      />

      {/* v0.5.0 Global overlays */}
      <HotkeyOverlay open={hotkeyOpen} onClose={() => setHotkeyOpen(false)} />
      <SettingsOverlay open={settingsOpen} onClose={() => setSettingsOpen(false)} onExitToMenu={() => setPhase('menu')} onOpenGuide={() => setGuideOpen(true)} onOpenTour={() => { setSettingsOpen(false); setOnboardingOpen(true); }} day={game?.day} playerName={game?.playerName} />
      <GuideOverlay open={guideOpen} onClose={() => setGuideOpen(false)} />
      {/* v1.3 — Onboarding carousel (first hub entry + Settings replay) */}
      <AnimatePresence>
        {onboardingOpen && (
          <OnboardingCarousel onComplete={() => {
            setOnboardingOpen(false);
            if (typeof window !== 'undefined') window.localStorage.setItem('baf3k_onboarding_done', '1');
          }} />
        )}
      </AnimatePresence>
      {/* v0.6.0 \u2014 Reality bleed cinematic flashes (escalation level 4+) */}
      <RealityBleedOverlay escalation={escalation} />
      {/* Resource +/-N floaters (portal-based) */}
      <ResourceDeltaFloaters />
      {/* Auto-fullscreen on first user interaction */}
      <FullscreenEnforcer />
      {/* Manager's note — a paper slip slides in per new day in hub */}
      {game.phase === 'hub' && (
        <MemoReveal triggerKey={game.day} />
      )}

      {/* Persistent top status bar — DAY • HEAT • CREW (gameplay phases only) */}
      {['hub', 'clipboard', 'inventory', 'map_table', 'recruiting', 'operations', 'scrounge', 'scavenge_map', 'expedition', 'coffee', 'dossier'].includes(game.phase) && (
        <StatusBar
          day={game.day}
          heat={game.heat}
          crewCount={game.npcs.filter((n) => n?.recruited).length}
          crewTotal={game.npcs.length}
        />
      )}

      {/* Win 25: Screen reader phase announcements */}
      <div className="sr-only" aria-live="assertive" aria-atomic="true" role="status">
        {srAnnouncement}
      </div>

      {/* Notification toast queue — stacks top-to-bottom (v0.5.0) */}
      <div className="fixed top-9 left-1/2 -translate-x-1/2 z-[200] flex flex-col gap-2 pointer-events-none" aria-live="polite">
        <AnimatePresence initial={false}>
          {notifications.map(n => (
            <motion.div
              key={n.id}
              role="alert"
              initial={{ opacity: 0, y: -20, scale: 0.95 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={{ opacity: 0, y: -12, scale: 0.95, transition: { duration: 0.2 } }}
              transition={{ type: 'spring', stiffness: 400, damping: 30 }}
              className="px-6 py-3 bg-[#1a1a1a] border border-[#8aad7a]/30 text-[#8aad7a] font-mono text-sm max-w-md text-center grimy-panel"
              style={{ boxShadow: '0 0 20px rgba(127,255,0,0.2)' }}
            >
              {n.msg}
            </motion.div>
          ))}
        </AnimatePresence>
      </div>

      {/* Loading overlay */}
      {loading && (
        <div className="fixed inset-0 z-[55] bg-black/80 flex items-center justify-center" role="status" aria-live="polite" aria-label="Loading game data">
          <div className="text-[#8aad7a] animate-pulse text-lg font-terminal">LOADING...</div>
          <span className="sr-only">Loading game data, please wait</span>
        </div>
      )}

      {/* Screens */}
      {game?.phase === 'dev_intro' && (
        <DevIntroScreen onComplete={() => setPhase('disclaimer')} />
      )}
      {game?.phase === 'disclaimer' && (
        <DisclaimerScreen onContinue={() => setPhase('launch_intro')} />
      )}
      {game?.phase === 'pipe_loading' && (
        <PipeLoadingScreen onComplete={() => setPhase('launch_intro')} />
      )}
      {game?.phase === 'launch_intro' && (
        <LaunchIntroScreen onComplete={() => setPhase('menu_transition')} />
      )}
      {game?.phase === 'menu_transition' && (
        <MenuTransitionScreen onComplete={() => setPhase('menu')} />
      )}
      {game?.phase === 'menu' && (
        <MainMenuScreen onNewGame={newGame} onContinue={continueGame} onOpenSettings={() => setSettingsOpen(true)} />
      )}
      {game?.phase === 'title_slideshow' && (
        <TitleSlideshowScreen onComplete={() => setPhase(postSlideshowPhase)} />
      )}
      {game?.phase === 'character_creator' && game?.sessionId && (
        <CharacterCreator
          sessionId={game.sessionId}
          onComplete={() => setPhase('character_sequence')}
        />
      )}
      {game?.phase === 'character_sequence' && (
        <CharacterSequence npcs={game?.npcs ?? []} onComplete={() => setPhase('hub')} />
      )}
      {game?.phase === 'hub' && (
        <HubScreen
          game={game}
          escalation={escalation}
          onOpenSettings={() => setSettingsOpen(true)}
          onOpenGuide={() => setGuideOpen(true)}
          onStation={(phase: GamePhase) => {
            // Intercept end-of-day: route through the new night cycle instead
            // of jumping straight to the summary ledger.
            if (phase === 'day_end') {
              setConsumption(null);
              setPhase('night_cycle');
              return;
            }
            setPhase(phase);
          }}
          onRefresh={refreshGameState}
          showNotification={showNotification}
        />
      )}
      {game?.phase === 'night_cycle' && (
        <NightCycleScreen
          onComplete={async () => {
            // Apply the crew consumption BEFORE the blackout so by the time
            // the day-summary ledger is shown, the DB has already been updated
            // and the UI reflects the true post-consumption state.
            if (game?.sessionId) {
              try {
                const res = await fetch('/api/game/consume', {
                  method: 'POST',
                  headers: { 'Content-Type': 'application/json' },
                  body: JSON.stringify({ sessionId: game.sessionId }),
                });
                if (res?.ok) {
                  const data = (await res.json()) as ConsumptionResult;
                  setConsumption(data);
                }
              } catch (e) {
                console.error('Consume API failed:', e);
              }
              await refreshGameState();
            }
            setPhase('night_blackout');
          }}
        />
      )}
      {game?.phase === 'night_blackout' && (
        <NightBlackoutScreen
          onComplete={() => setPhase('day_end')}
          escalationLevel={escalation.level}
        />
      )}
      {game?.phase === 'clipboard' && (
        <ClipboardStation
          game={game}
          escalation={escalation}
          onBack={() => { audioManager.restoreRoomMusic(); setPhase('hub'); }}
          onRecruit={(npcId: string) => {
            selectNpc(npcId);
            setPhase('recruiting');
          }}
          onRefresh={refreshGameState}
        />
      )}
      {game?.phase === 'inventory' && (
        <InventoryStation
          game={game}
          escalation={escalation}
          onBack={() => { audioManager.restoreRoomMusic(); setPhase('hub'); }}
          onRefresh={refreshGameState}
          showNotification={showNotification}
          triggerAdminFlash={triggerAdminFlash}
        />
      )}
      {game?.phase === 'map_table' && (
        <DumpsterPlanningClipboard
          game={game}
          escalation={escalation}
          onBack={() => { setPhase('hub'); }}
          onLaunchExpedition={(expId: string, directiveNpcKey?: string) => {
            setGame((prev: GameState) => ({
              ...prev,
              activeExpeditionId: expId,
              activeDirectiveNpcKey: directiveNpcKey ?? null,
            }));
            if (directiveNpcKey) {
              setPhase('directive_intro');
            } else {
              setPhase('expedition');
            }
          }}
          onRefresh={refreshGameState}
          showNotification={showNotification}
        />
      )}
      {(game?.phase === 'shoebox' || game?.phase === 'hallucination' || game?.phase === 'codex' || game?.phase === 'scrapbook') && (
        <ShoeboxStation onBack={() => { setPhase('hub'); }} game={game} escalation={escalation} />
      )}
      {game?.phase === 'dossier' && (
        <DossierStation onBack={() => { setPhase('hub'); }} game={game} escalation={escalation} />
      )}

      {game?.phase === 'operations' && (
        <OperationsBoard
          game={game}
          escalation={escalation}
          onBack={() => { setPhase('hub'); }}
          onRefresh={refreshGameState}
          showNotification={showNotification}
          onAscension={() => setPhase('ascension')}
        />
      )}
      {game?.phase === 'scrounge' && (
        <ScroungeStation
          game={game}
          escalation={escalation}
          onBack={() => setPhase('hub')}
          onRefresh={refreshGameState}
          showNotification={showNotification}
        />
      )}
      {game?.phase === 'scavenge_map' && (
        <ScavengeMapStation
          game={game}
          escalation={escalation}
          onBack={() => setPhase('hub')}
          onRefresh={refreshGameState}
          showNotification={showNotification}
        />
      )}
      {game?.phase === 'coffee' && (
        <CoffeeStation
          game={game}
          escalation={escalation}
          onBack={() => { audioManager.restoreRoomMusic(); setPhase('hub'); }}
          onRefresh={refreshGameState}
          showNotification={showNotification}
        />
      )}
      {game?.phase === 'recruiting' && game?.selectedNpcId && game?.sessionId && (
        <RecruitmentFlow
          npcId={game.selectedNpcId}
          npcs={game?.npcs ?? []}
          sessionId={game.sessionId}
          resources={game?.resources ?? []}
          onBack={() => { setPhase('clipboard'); refreshGameState(); }}
          onComplete={() => { setPhase('hub'); refreshGameState(); showNotification('New crew member recruited.'); }}
          showNotification={showNotification}
          refreshResources={refreshGameState}
          escalationLevel={escalation?.level ?? 0}
        />
      )}
      {game?.phase === 'directive_intro' && game.activeDirectiveNpcKey && (() => {
        const dir = getDirective(game.activeDirectiveNpcKey!);
        if (!dir) return null;
        return (
          <ComicViewer
            panels={dir.introPanels}
            sequenceLabel={`${dir.name.toUpperCase()} — ${dir.title}`}
            onComplete={() => setPhase('expedition')}
          />
        );
      })()}
      {game?.phase === 'expedition' && (
        <TacticalBoard
          recruitedNpcKeys={(game?.npcs ?? []).filter(n => n?.recruited).map(n => (n?.name ?? '').toLowerCase())}
          onBack={() => { setPhase('hub'); refreshGameState(); }}
          onComplete={async (result) => {
            // Write heat back to game state
            if (result.heat > 0 && game.sessionId) {
              try {
                await fetch('/api/game/heat', {
                  method: 'POST',
                  headers: { 'Content-Type': 'application/json' },
                  body: JSON.stringify({ sessionId: game.sessionId, change: Math.ceil(result.heat / 20) }),
                });
              } catch {}
            }
            // Write loot as random resources
            if (result.loot > 0 && game.sessionId) {
              const types = ['cigarettes', 'alcohol', 'weed', 'crystals'];
              for (let i = 0; i < result.loot; i++) {
                const resType = types[Math.floor(Math.random() * types.length)];
                try {
                  await fetch('/api/game/resources', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ sessionId: game.sessionId, type: resType, change: 1 }),
                  });
                } catch {}
              }
            }
            if (result.won) {
              showNotification(`Expedition complete. ${result.loot} supplies recovered.`);
            } else {
              showNotification('Expedition failed. Retreating to base.');
            }
            await refreshGameState();
            // Check directive flow
            if (game.activeDirectiveNpcKey) {
              const dir = getDirective(game.activeDirectiveNpcKey);
              const threshold = dir?.pressureThreshold ?? 2.5;
              if (result.won && result.heat <= threshold * 20) {
                await fetch('/api/game/directive', {
                  method: 'POST',
                  headers: { 'Content-Type': 'application/json' },
                  body: JSON.stringify({ sessionId: game.sessionId, action: 'complete', npcKey: game.activeDirectiveNpcKey }),
                }).catch(() => {});
                setPhase('directive_outro');
              } else {
                await fetch('/api/game/directive', {
                  method: 'POST',
                  headers: { 'Content-Type': 'application/json' },
                  body: JSON.stringify({ sessionId: game.sessionId, action: 'fail', npcKey: game.activeDirectiveNpcKey }),
                }).catch(() => {});
                showNotification(`Directive failed. ${dir?.name ?? 'Crew member'}'s story remains unfinished.`);
                setGame((prev: GameState) => ({ ...prev, activeDirectiveNpcKey: null }));
                setPhase('hub');
              }
            }
          }}
        />
      )}
      {game?.phase === 'directive_outro' && game.activeDirectiveNpcKey && (() => {
        const dir = getDirective(game.activeDirectiveNpcKey!);
        if (!dir) return null;
        return (
          <ComicViewer
            panels={dir.outroPanels}
            sequenceLabel={`${dir.name.toUpperCase()} — DIRECTIVE COMPLETE`}
            onComplete={() => {
              showNotification(`${dir.name}'s directive complete. They are now win-eligible.`);
              setGame((prev: GameState) => ({ ...prev, activeDirectiveNpcKey: null }));
              setPhase('hub');
              refreshGameState();
            }}
          />
        );
      })()}
      {game?.phase === 'day_end' && (
        <DayEndScreen
          game={game}
          escalation={escalation}
          consumption={consumption}
          onContinue={async () => {
            // Check for game over (heat >= 10)
            if ((game?.heat ?? 0) >= 10) {
              setGameOverReason('heat');
              setPhase('game_over');
              return;
            }
            // Check for raid event (heat >= 7, random chance)
            if ((game?.heat ?? 0) >= 7) {
              const raidChance = ((game?.heat ?? 0) - 6) * 0.15; // 15% per heat above 6
              const roll = Math.abs(((game?.day ?? 0) * 7 + 13) % 100) / 100; // deterministic "random"
              if (roll < raidChance) {
                // Trigger raid
                try {
                  const res = await fetch('/api/game/raid', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ sessionId: game?.sessionId }),
                  });
                  if (res?.ok) {
                    const data = await res.json();
                    setRaidResult({
                      resourcesLost: data?.resourcesLost ?? [],
                      heatAfter: data?.heatAfter ?? 0,
                      survived: data?.survived ?? true,
                    });
                    await refreshGameState();
                    setPhase('raid');
                    return;
                  }
                } catch {}
              }
            }
            // Heat warning notifications
            if ((game?.heat ?? 0) >= 5 && (game?.heat ?? 0) < 7) {
              showNotification('[ALERT] Heat is rising. The walls have ears.');
            } else if ((game?.heat ?? 0) >= 7) {
              showNotification('[CRITICAL] Heat maxed. Raid imminent. Lay low.');
            }
            // Normal day advance
            if (game?.sessionId) {
              try {
                await fetch('/api/game/day', {
                  method: 'POST',
                  headers: { 'Content-Type': 'application/json' },
                  body: JSON.stringify({ sessionId: game.sessionId }),
                });
              } catch {}
            }
            await refreshGameState();
            setPhase('hub');
          }}
        />
      )}
      {game?.phase === 'raid' && raidResult && (
        <RaidScreen
          game={game}
          raidResult={raidResult}
          onContinue={async () => {
            if (!raidResult.survived) {
              setGameOverReason('raid');
              setPhase('game_over');
              return;
            }
            // Survived — advance day
            if (game?.sessionId) {
              try {
                await fetch('/api/game/day', {
                  method: 'POST',
                  headers: { 'Content-Type': 'application/json' },
                  body: JSON.stringify({ sessionId: game.sessionId }),
                });
              } catch {}
            }
            await refreshGameState();
            setPhase('hub');
          }}
        />
      )}
      {game?.phase === 'game_over' && (
        <GameOverScreen
          game={game}
          reason={gameOverReason}
          onRestart={async () => {
            if (typeof window !== 'undefined') localStorage.removeItem('baf_session_id');
            setGame(initialState);
            setRaidResult(null);
          }}
        />
      )}
      {game?.phase === 'welcome_back' && (
        <WelcomeBackScreen
          game={game}
          escalation={escalation}
          onContinue={() => setPhase('hub')}
        />
      )}
      {game?.phase === 'ascension' && (
        <AscensionScreen
          game={game}
          onRestart={async () => {
            if (typeof window !== 'undefined') localStorage.removeItem('baf_session_id');
            setGame(initialState);
          }}
        />
      )}
    </main>
  );
}

'use client';

import { useState, useCallback, useEffect, memo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ArrowRight, X, RefreshCw, AlertTriangle } from 'lucide-react';
import { audioManager } from '@/app/_lib/audio-manager';
import { playHover } from '@/lib/sound-effects';
import type { GameState } from '../game-client';

interface Props {
  game: GameState;
  onRefresh: () => Promise<void>;
  showNotification: (msg: string) => void;
  onClose: () => void;
}

const RESOURCES = ['cigarettes', 'alcohol', 'weed', 'crystals'] as const;

const RESOURCE_META: Record<string, { label: string; short: string; color: string; emoji: string }> = {
  cigarettes: { label: 'CIGARETTES', short: 'CIGS', color: '#8aad7a', emoji: '\ud83d\udeac' },
  alcohol:    { label: 'ALCOHOL',    short: 'ALC',  color: '#7ab8b8', emoji: '\ud83c\udf7a' },
  weed:       { label: 'WEED',       short: 'WEED', color: '#9a86b5', emoji: '🌿' },
  crystals:   { label: 'CRYSTALS',   short: 'CRYS', color: '#a8687e', emoji: '\ud83d\udc8e' },
};

// Trade rates (must match server)
const TRADE_RATES: Record<string, Record<string, { cost: number; gain: number }>> = {
  cigarettes: { alcohol: { cost: 4, gain: 1 }, weed: { cost: 5, gain: 1 }, crystals: { cost: 7, gain: 1 } },
  alcohol:    { cigarettes: { cost: 1, gain: 2 }, weed: { cost: 2, gain: 1 }, crystals: { cost: 4, gain: 1 } },
  weed:       { cigarettes: { cost: 1, gain: 3 }, alcohol: { cost: 1, gain: 1 }, crystals: { cost: 3, gain: 1 } },
  crystals:   { cigarettes: { cost: 1, gain: 4 }, alcohol: { cost: 1, gain: 2 }, weed: { cost: 1, gain: 2 } },
};

const MAX_TRADES_PER_DAY = 3;

function TradePanel({ game, onRefresh, showNotification, onClose }: Props) {
  const [fromType, setFromType] = useState<string>('cigarettes');
  const [toType, setToType] = useState<string>('alcohol');
  const [trading, setTrading] = useState(false);
  const [tradesToday, setTradesToday] = useState(0);
  const [lastTrade, setLastTrade] = useState<{ from: string; to: string; spent: number; gained: number } | null>(null);

  const resources = game?.resources ?? [];
  const getQty = (type: string) => resources.find(r => r?.type === type)?.quantity ?? 0;

  // Load daily trade count from localStorage
  useEffect(() => {
    try {
      const key = `trades_day_${game?.sessionId}_${game?.day}`;
      const stored = localStorage.getItem(key);
      if (stored) setTradesToday(Number(stored) || 0);
    } catch {}
  }, [game?.sessionId, game?.day]);

  const rate = TRADE_RATES[fromType]?.[toType];
  const canAfford = rate && getQty(fromType) >= rate.cost;
  const tradesLeft = MAX_TRADES_PER_DAY - tradesToday;
  const disabled = trading || !rate || !canAfford || tradesLeft <= 0;

  const doTrade = useCallback(async () => {
    if (disabled || !game?.sessionId || !rate) return;
    setTrading(true);
    setLastTrade(null);
    try {
      const res = await fetch('/api/game/trade', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ sessionId: game.sessionId, from: fromType, to: toType }),
      });
      const data = await res.json();
      if (!res.ok) {
        showNotification(data?.message || data?.error || 'Trade failed.');
        audioManager.playSFX('error');
        return;
      }
      audioManager.playSFX('confirm');
      const newCount = tradesToday + 1;
      setTradesToday(newCount);
      try {
        localStorage.setItem(`trades_day_${game.sessionId}_${game.day}`, String(newCount));
      } catch {}
      setLastTrade({
        from: fromType,
        to: toType,
        spent: data.from?.spent ?? rate.cost,
        gained: data.to?.gained ?? rate.gain,
      });
      showNotification(`Traded ${rate.cost} ${RESOURCE_META[fromType]?.short} \u2192 ${rate.gain} ${RESOURCE_META[toType]?.short}`);
      await onRefresh();
    } catch {
      showNotification('Trade failed. Network error.');
      audioManager.playSFX('error');
    } finally {
      setTrading(false);
    }
  }, [disabled, game?.sessionId, game?.day, fromType, toType, rate, tradesToday, onRefresh, showNotification]);

  // Auto-fix same type selection
  useEffect(() => {
    if (fromType === toType) {
      const alt = RESOURCES.find(r => r !== fromType);
      if (alt) setToType(alt);
    }
  }, [fromType, toType]);

  return (
    <motion.div
      initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
      className="fixed inset-0 z-[60] flex items-center justify-center"
      style={{ background: 'rgba(8,8,6,0.92)', backdropFilter: 'blur(8px)' }}
    >
      <motion.div
        initial={{ scale: 0.95, opacity: 0 }} animate={{ scale: 1, opacity: 1 }}
        className="relative w-full max-w-sm mx-4 p-5"
        style={{ background: '#0e0d0b', border: '1px solid rgba(0,255,255,0.15)' }}
      >
        {/* Header */}
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-2">
            <RefreshCw size={14} className="text-[#7ab8b8]" />
            <h3 className="font-terminal text-sm tracking-[0.2em] text-[#7ab8b8]">BLACK MARKET</h3>
          </div>
          <button onClick={() => { audioManager.playSFX('nav'); onClose(); }} onMouseEnter={() => playHover()} className="p-1 text-[#8a8578] hover:text-[#7ab8b8] transition-colors" aria-label="Close trading panel">
            <X size={16} />
          </button>
        </div>

        {/* Trade meter */}
        <div className="mb-4 px-2 py-1.5" style={{ background: 'rgba(0,255,255,0.04)', border: '1px solid rgba(0,255,255,0.08)' }}>
          <div className="flex items-center justify-between mb-1">
            <span className="font-terminal text-[9px] tracking-wider text-[#7a8a6a]">DAILY TRADES</span>
            <span className="font-terminal text-[9px] tracking-wider" style={{ color: tradesLeft <= 0 ? '#ff4444' : tradesLeft === 1 ? '#FFB000' : '#7a8a6a' }}>
              {tradesToday}/{MAX_TRADES_PER_DAY}
            </span>
          </div>
          <div className="h-1 bg-[#1a1a16] overflow-hidden">
            <div className="h-full transition-all duration-300" style={{ width: `${(tradesToday / MAX_TRADES_PER_DAY) * 100}%`, background: tradesLeft <= 0 ? '#ff4444' : '#7ab8b8' }} />
          </div>
        </div>

        {/* FROM selector */}
        <div className="mb-3">
          <span className="font-terminal text-[9px] tracking-[0.15em] text-[#7a8a6a] block mb-1.5">GIVE</span>
          <div className="flex gap-1.5">
            {RESOURCES.map(r => {
              const meta = RESOURCE_META[r];
              const qty = getQty(r);
              const active = fromType === r;
              return (
                <button
                  key={r}
                  onClick={() => { audioManager.playSFX('nav'); setFromType(r); }}
                  onMouseEnter={() => playHover()}
                  className="flex-1 py-2 px-1 text-center transition-all font-terminal text-[9px] tracking-wider"
                  style={{
                    border: `1px solid ${active ? meta.color + '50' : 'rgba(255,255,255,0.06)'}`,
                    background: active ? meta.color + '12' : 'transparent',
                    color: active ? meta.color : '#5a5a5a',
                  }}
                  aria-label={`Trade from ${meta.label} (${qty} available)`}
                >
                  <div>{meta.short}</div>
                  <div className="text-[8px] mt-0.5 opacity-60">{qty}</div>
                </button>
              );
            })}
          </div>
        </div>

        {/* Arrow + rate display */}
        <div className="flex items-center justify-center gap-3 mb-3">
          <div className="h-px flex-1" style={{ background: 'rgba(0,255,255,0.1)' }} />
          <div className="flex items-center gap-2">
            {rate ? (
              <span className="font-terminal text-[10px] tracking-wider text-[#b0a890]">
                {rate.cost} {RESOURCE_META[fromType]?.short}
                <ArrowRight size={10} className="inline mx-1 text-[#7ab8b8]" />
                {rate.gain} {RESOURCE_META[toType]?.short}
              </span>
            ) : (
              <span className="font-terminal text-[9px] text-[#4a4a3a]">SELECT DIFFERENT TYPES</span>
            )}
          </div>
          <div className="h-px flex-1" style={{ background: 'rgba(0,255,255,0.1)' }} />
        </div>

        {/* TO selector */}
        <div className="mb-4">
          <span className="font-terminal text-[9px] tracking-[0.15em] text-[#7a8a6a] block mb-1.5">RECEIVE</span>
          <div className="flex gap-1.5">
            {RESOURCES.filter(r => r !== fromType).map(r => {
              const meta = RESOURCE_META[r];
              const active = toType === r;
              return (
                <button
                  key={r}
                  onClick={() => { audioManager.playSFX('nav'); setToType(r); }}
                  onMouseEnter={() => playHover()}
                  className="flex-1 py-2 px-1 text-center transition-all font-terminal text-[9px] tracking-wider"
                  style={{
                    border: `1px solid ${active ? meta.color + '50' : 'rgba(255,255,255,0.06)'}`,
                    background: active ? meta.color + '12' : 'transparent',
                    color: active ? meta.color : '#5a5a5a',
                  }}
                  aria-label={`Trade to ${meta.label}`}
                >
                  {meta.short}
                </button>
              );
            })}
          </div>
        </div>

        {/* Warnings */}
        {!canAfford && rate && (
          <div className="mb-3 flex items-center gap-1.5 px-2 py-1.5" style={{ background: 'rgba(255,68,68,0.06)', border: '1px solid rgba(255,68,68,0.1)' }}>
            <AlertTriangle size={10} className="text-[#ff4444]" />
            <span className="font-terminal text-[9px] tracking-wider text-[#ff6b6b]">
              NEED {rate.cost} {RESOURCE_META[fromType]?.short} — ONLY HAVE {getQty(fromType)}
            </span>
          </div>
        )}
        {tradesLeft <= 0 && (
          <div className="mb-3 flex items-center gap-1.5 px-2 py-1.5" style={{ background: 'rgba(255,176,0,0.06)', border: '1px solid rgba(255,176,0,0.1)' }}>
            <AlertTriangle size={10} className="text-[#FFB000]" />
            <span className="font-terminal text-[9px] tracking-wider text-[#FFB000]">
              DAILY TRADE LIMIT REACHED — COME BACK TOMORROW
            </span>
          </div>
        )}

        {/* Trade button */}
        <button
          onClick={doTrade}
          disabled={disabled}
          onMouseEnter={() => !disabled && playHover()}
          className="w-full py-2.5 font-terminal text-xs tracking-[0.2em] transition-all"
          style={{
            background: disabled ? 'rgba(255,255,255,0.02)' : 'rgba(0,255,255,0.08)',
            border: `1px solid ${disabled ? 'rgba(255,255,255,0.05)' : 'rgba(0,255,255,0.3)'}`,
            color: disabled ? '#3a3a3a' : '#7ab8b8',
            cursor: disabled ? 'not-allowed' : 'pointer',
          }}
          aria-label="Execute trade"
        >
          {trading ? 'TRADING...' : 'EXECUTE TRADE'}
        </button>

        {/* Last trade result */}
        <AnimatePresence>
          {lastTrade && (
            <motion.div
              initial={{ opacity: 0, y: 5 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }}
              className="mt-3 text-center font-terminal text-[9px] tracking-wider text-[#7a8a6a]"
            >
              ✓ Traded {lastTrade.spent} {RESOURCE_META[lastTrade.from]?.short} for {lastTrade.gained} {RESOURCE_META[lastTrade.to]?.short}
            </motion.div>
          )}
        </AnimatePresence>

        {/* Flavour */}
        <p className="mt-3 text-center font-terminal text-[7px] tracking-[0.2em] text-[#3a3a3a] italic">
          "EVERY TRADE LOSES SOMETHING. THAT'S HOW THE STREET WORKS."
        </p>
      </motion.div>
    </motion.div>
  );
}

