  game: PublicGame
  index: number
  content: SiteContentMap
  onClose: () => void
}

const FOCUSABLE = 'a[href], button:not([disabled]), [tabindex]:not([tabindex="-1"])'

export function SupporterBadge({ small, className = '' }: { small?: boolean; className?: string }) {
  return (
    <span
      className={`inline-flex items-center gap-1.5 font-ibm uppercase whitespace-nowrap ${small ? 'text-[9px] px-1.5 py-0.5' : 'text-[10px] px-2 py-1'} ${className}`}
      style={{ backgroundColor: 'rgb(var(--bv-bg-rgb) / 0.88)', border: '1px solid var(--col-steel)', color: 'var(--col-bone)', letterSpacing: '0.08em' }}
    >
      <svg width={small ? 8 : 9} height={small ? 9 : 10} viewBox="0 0 54 62" fill="none" aria-hidden="true">
