export function DossierWindow({ game, index, content, onClose }: DossierWindowProps) {
  const panelRef = useRef<HTMLDivElement>(null)
  const closeRef = useRef<HTMLButtonElement>(null)
  const unitId = `UNIT-${String(index + 1).padStart(2, '0')}`
  const isActive = game.status === 'active'
  const hasLink = !!game.launchLink && game.launchLink !== '#'
  const newTab = game.linkTarget === 'new_tab'

  const close = useCallback(() => {
    haptic('press')
    onClose()
  }, [onClose])

  useEffect(() => {
    const opener = document.activeElement as HTMLElement | null
    const prevOverflow = document.body.style.overflow
    document.body.style.overflow = 'hidden'
    closeRef.current?.focus()
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        e.preventDefault()
        close()
        return
      }
      if (e.key !== 'Tab' || !panelRef.current) return
      const items = Array.from(panelRef.current.querySelectorAll<HTMLElement>(FOCUSABLE))
      if (items.length === 0) return
      const first = items[0]
      const last = items[items.length - 1]
      if (e.shiftKey && (document.activeElement === first || !panelRef.current.contains(document.activeElement))) {
        e.preventDefault()
        last.focus()
      } else if (!e.shiftKey && document.activeElement === last) {
        e.preventDefault()
        first.focus()
      }
    }
    document.addEventListener('keydown', onKey)
    return () => {
      document.removeEventListener('keydown', onKey)
      document.body.style.overflow = prevOverflow
      opener?.focus?.()
    }
  }, [close])

  const actionBase = 'press-fx inline-flex items-center justify-center gap-3 font-oswald uppercase tracking-[0.22em] text-sm px-5 py-3 min-h-[48px] whitespace-nowrap focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--col-ivory)]'

  return createPortal(
    <div
      className="dossier-backdrop fixed inset-0 z-[120] flex items-center justify-center p-3 sm:p-6"
      style={{ backgroundColor: 'rgb(var(--bv-bg-rgb) / 0.9)' }}
      onMouseDown={(e) => { if (e.target === e.currentTarget) close() }}
      data-no-swipe
    >
      <div
        ref={panelRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby="dossier-title"
        className="dossier-panel relative w-full max-w-5xl"
        style={{ boxShadow: '0 30px 80px rgb(var(--bv-shadow-rgb) / 0.6)' }}
      >
        <div
          className="max-h-[calc(100dvh-1.5rem)] sm:max-h-[calc(100dvh-3rem)] overflow-y-auto overscroll-contain grid md:grid-cols-[1.05fr_1fr]"
          style={{ backgroundColor: 'var(--col-gunmetal)', border: '1px solid var(--col-steel)' }}
        >

        {/* Full-bleed artwork */}
        <div className="relative aspect-video md:aspect-auto md:min-h-[520px] bg-[var(--col-charcoal)] overflow-hidden">
          {game.imageUrl ? (
            <Image src={game.imageUrl} alt={`${game.title} key art`} fill unoptimized className="object-cover" sizes="(max-width: 768px) 100vw, 55vw" />
          ) : (
            <div className="absolute inset-0 dead-signal flex flex-col items-start justify-end p-6">
              <span className="font-anton uppercase leading-[0.85]" style={{ color: 'var(--col-ivory)', fontSize: 'clamp(40px, 6vw, 72px)' }}>{game.title}</span>
              <span className="mt-3 h-[3px] w-12" style={{ backgroundColor: 'var(--col-yellow)' }} />
            </div>
          )}
          <div className="absolute inset-x-0 bottom-0 h-1/3 pointer-events-none" style={{ background: 'linear-gradient(180deg, transparent, rgb(var(--bv-bg-rgb) / 0.75))' }} />
        </div>

        {/* File body */}
        <div className="relative flex flex-col p-6 md:p-8">
          <div className="flex items-start justify-between gap-4 mb-6">
            <p className="font-ibm text-[10px] uppercase tracking-[0.3em] pt-2" style={{ color: 'var(--col-bone)', opacity: 0.7 }}>
