              style={{ border: '1px solid var(--col-steel)', color: 'var(--col-ivory)', backgroundColor: 'var(--col-charcoal)' }}
            >
              <svg width="14" height="14" viewBox="0 0 14 14" aria-hidden="true"><path d="M1 1L13 13M13 1L1 13" stroke="currentColor" strokeWidth="2.2" /></svg>
            </button>
          </div>

          <h2 id="dossier-title" className="font-anton uppercase leading-[0.88] tracking-tight" style={{ color: 'var(--col-ivory)', fontSize: 'clamp(36px, 5vw, 64px)' }}>
            {game.title}
          </h2>
          {game.subtitle ? (
            <p className="font-oswald uppercase tracking-[0.2em] text-sm mt-3" style={{ color: 'var(--col-yellow)' }}>{game.subtitle}</p>
          ) : null}

          <div className="w-16 my-5 gold-rule" aria-hidden="true" />

          {game.description ? (
            <p className="font-ibm text-sm md:text-[15px] leading-relaxed" style={{ color: 'var(--col-ivory)' }}>{game.description}</p>
          ) : null}
          {game.deepDive ? (
            <div className="mt-5 pl-4" style={{ borderLeft: '1px solid var(--col-steel)' }}>
              <p className="font-oswald text-[10px] uppercase tracking-[0.3em] mb-2" style={{ color: 'var(--col-bone)', opacity: 0.7 }}>DEEP DIVE</p>
              <p className="font-ibm text-sm leading-relaxed" style={{ color: 'var(--col-bone)' }}>{game.deepDive}</p>
            </div>
          ) : null}

          <div className="mt-6 flex flex-wrap items-center gap-3">
            <span className="font-oswald text-[10px] uppercase tracking-[0.3em]" style={{ color: 'var(--col-bone)', opacity: 0.7 }}>ACCESS</span>
            {game.locked ? (
              <SupporterBadge />
            ) : (
              <span className="font-ibm text-[10px] uppercase px-2 py-1" style={{ border: '1px solid var(--col-steel)', color: 'var(--col-ivory)', letterSpacing: '0.08em' }}>
                FREE
              </span>
            )}
          </div>

          <div className="mt-auto pt-8 flex flex-col sm:flex-row sm:flex-wrap gap-3">
            {game.locked ? (
              <Link
                href="/profile"
                onClick={() => haptic('press')}
                className={`${actionBase} hover:bg-[var(--col-yellow-hot)]`}
                style={{ backgroundColor: 'var(--col-yellow)', color: 'var(--col-black)' }}
              >
                TURN THE SEAL TO UNLOCK
              </Link>
            ) : isActive && hasLink ? (
              <a
                href={game.launchLink}
                target={newTab ? '_blank' : undefined}
                rel={newTab ? 'noopener noreferrer' : undefined}
                onClick={() => haptic('complete')}
                className={`${actionBase} hover:bg-[var(--col-yellow-hot)]`}
                style={{ backgroundColor: 'var(--col-yellow)', color: 'var(--col-black)' }}
              >
                LAUNCH NOW
                <svg width="18" height="12" viewBox="0 0 20 14" fill="none" aria-hidden="true"><path d="M13 1L19 7M19 7L13 13M19 7H1" stroke="currentColor" strokeWidth="2.5" /></svg>
              </a>
            ) : (
              <span className={actionBase} style={{ border: '1px solid var(--col-steel)', color: 'var(--col-bone)', opacity: 0.7 }}>
                {isActive ? 'LINK PENDING' : 'STANDBY'}
              </span>
            )}
          </div>
        </div>
        </div>
      </div>
    </div>,
    document.body
  )
}

