import type { ResourceKey } from './game-data';

// ---- Types ------------------------------------------------

export type TravelEventType =
  | 'resource_find'    // gain resources
  | 'resource_loss'    // lose resources
  | 'combat_ambush'    // DEPRECATED: kept for data compat, resolves via encounter system
  | 'encounter'        // v1.0: encounter-system confrontation (replaces combat_ambush)
  | 'stat_buff'        // temporary stat bonus
  | 'stat_debuff'      // temporary stat penalty
  | 'heat_change'      // heat increase or decrease
  | 'crew_morale'      // morale / flavour (no mechanical effect)
  | 'shortcut'         // skip a travel step
  | 'roadblock'        // lose extra resources or turn back
  | 'npc_encounter';   // random NPC interaction

export interface TravelEventEffect {
  /** Resource changes: positive = gain, negative = loss */
  resources?: Partial<Record<ResourceKey, number>>;
  /** Heat change */
  heatDelta?: number;
  /** Skip N travel steps (shortcut) */
  skipSteps?: number;
  /** Extra resource cost to continue (roadblock toll) */
  toll?: Partial<Record<ResourceKey, number>>;
  /** Stat name temporarily buffed/debuffed and amount */
  statMod?: { stat: 'muscle' | 'brains' | 'unpredictability'; delta: number };
}

export interface TravelEvent {
  /** Unique event id */
  id: string;
  /** Event type category */
  type: TravelEventType;
  /** Display title shown on event card */
  title: string;
  /** Flavour text — [WESLEY] = placeholder for Wesley's copy */
  flavour: string;
  /** Mechanical effect */
  effect: TravelEventEffect;
  /** Base weight (higher = more likely). Route eventWeight multiplies this. */
  weight: number;
  /** Min escalation level required to appear (0 = always) */
  minEscalation?: number;
  /** Route restriction — null = any route */
  routeIds?: string[] | null;
}

