// ---- Event Resolution Helpers -----------------------------

/** Pick a travel event for a given step using seeded PRNG.
 *  routeSteps scales the event chance (more steps = more events). */
export function rollTravelEvent(
  seed: number,
  routeSteps: number,
  escalationLevel: number,
): TravelEvent | null {
  let s = (seed >>> 0) || 0xBEEF;
  const rng = () => {
    s = (s + 0x6D2B79F5) >>> 0;
    let t = s;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 0x100000000;
  };

  // ~35% base chance, scaled by route length (steps/2.5)
  const eventChance = 0.35 * (routeSteps / 2.5);
  if (rng() > eventChance) return null;

  // Filter eligible events
  const eligible = TRAVEL_EVENTS.filter(
    (e) => (e.minEscalation ?? 0) <= escalationLevel,
  );
  if (eligible.length === 0) return null;

  // Weighted random selection
  const totalWeight = eligible.reduce((sum, e) => sum + e.weight, 0);
  let roll = rng() * totalWeight;
  for (const event of eligible) {
    roll -= event.weight;
    if (roll <= 0) return event;
  }
  return eligible[eligible.length - 1];
}

/** Get all events of a specific type */
export function getEventsByType(type: TravelEventType): TravelEvent[] {
  return TRAVEL_EVENTS.filter((e) => e.type === type);
}

