import { useState, useEffect, useCallback } from 'react'
import { AnimatePresence } from 'framer-motion'
import BootSequence from './boot-sequence'
import PitchLayout from './pitch-layout'

export default function PitchApp() {
  const [booted, setBooted] = useState(false)
  const [checkingSession, setCheckingSession] = useState(true)

  useEffect(() => {
    try {
      const hasBooted = sessionStorage?.getItem?.('bmf3k-booted')
      if (hasBooted === 'true') {
        setBooted(true)
      }
    } catch (_e) {
      // sessionStorage not available
    }
    setCheckingSession(false)
  }, [])

  const handleBootComplete = useCallback(() => {
    try {
      sessionStorage?.setItem?.('bmf3k-booted', 'true')
    } catch (_e) { /* ignore */ }
    setBooted(true)
  }, [])

  if (checkingSession) {
    return <div className="fixed inset-0 bg-[#0A0A08]" />
  }

  return (
    <div className="fixed inset-0 bg-[#0A0A08] overflow-hidden">
      <AnimatePresence mode="wait">
        {!booted ? (
          <BootSequence key="boot" onComplete={handleBootComplete} />
        ) : (
          <PitchLayout key="pitch" />
        )}
      </AnimatePresence>
    </div>
  )
}

