import { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import Image from 'next/image';
import { playSniff, playCough, playTongueClick, playThud } from '@/lib/sound-effects';

interface Props {
  npcs: any[];
  onComplete: () => void;
}

type SequencePhase = 'black' | 'table' | 'blink' | 'manager' | 'sheet';

const BLINK_DURATION_MS = 260;
const MANAGER_DURATION_MS = 6200;

export default function CharacterSequence({ npcs, onComplete }: Props) {
  const [phase, setPhase] = useState<SequencePhase>('black');
  const [audioPlayed, setAudioPlayed] = useState(0);
  const [breathCount, setBreathCount] = useState(0);
  const [managerProgress, setManagerProgress] = useState(0); // 0..1, the sweat bead descent
  const [managerTextStage, setManagerTextStage] = useState(0); // 0..4 narrative beats

  const advancePhase = useCallback(() => {
    setPhase((prev: SequencePhase) => {
      if (prev === 'black') return 'table';
      if (prev === 'table') return 'blink';
      if (prev === 'blink') return 'manager';
      if (prev === 'manager') return 'sheet';
      return prev;
    });
  }, []);

  useEffect(() => {
    if (phase === 'black') {
      const timers = [
        setTimeout(() => { playSniff(); setAudioPlayed(1); }, 800),
        setTimeout(() => { setBreathCount(1); }, 1800),
        setTimeout(() => { playCough(); setAudioPlayed(2); }, 2800),
        setTimeout(() => { setBreathCount(2); }, 3800),
        setTimeout(() => { playTongueClick(); setAudioPlayed(3); }, 4600),
        setTimeout(() => advancePhase(), 5800),
      ];
      return () => timers.forEach(clearTimeout);
    }
    if (phase === 'table') {
      const t = setTimeout(() => { playThud(); advancePhase(); }, 5000);
      return () => clearTimeout(t);
    }
    if (phase === 'blink') {
      const t = setTimeout(() => { playTongueClick(); advancePhase(); }, BLINK_DURATION_MS);
      return () => clearTimeout(t);
    }
    if (phase === 'manager') {
      // Animate the sweat bead progression.
      const startTime = Date.now();
      const tickInterval = 50; // ms between progress samples
      const interval = setInterval(() => {
        const elapsed = Date.now() - startTime;
        const p = Math.min(elapsed / MANAGER_DURATION_MS, 1);
        setManagerProgress(p);
      }, tickInterval);
      // Narrative caption beats (the Manager's calculated observations)
      const captionTimers = [
        setTimeout(() => setManagerTextStage(1), 600),
        setTimeout(() => setManagerTextStage(2), 2400),
        setTimeout(() => setManagerTextStage(3), 4400),
        setTimeout(() => setManagerTextStage(4), 5600),
      ];
      const advanceTimer = setTimeout(() => advancePhase(), MANAGER_DURATION_MS);
      return () => {
        clearInterval(interval);
        captionTimers.forEach(clearTimeout);
        clearTimeout(advanceTimer);
      };
    }
  }, [phase, advancePhase]);

  // Sweat bead positions: starts at temple ~22% from top, descends to ~78% (jaw)
  const beadTop = 22 + managerProgress * 56; // percent
  const trailHeight = managerProgress * 56; // grows with progress

  return (
    <div className="w-full h-full bg-black flex items-center justify-center overflow-hidden">
      <AnimatePresence mode="wait">
        {/* Phase 1: Black screen with atmospheric SFX */}
        {phase === 'black' && (
          <motion.div
            key="black"
            initial={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            transition={{ duration: 1.5 }}
            className="text-center"
          >
            <motion.div
              animate={{ opacity: [0.15, 0.35, 0.15] }}
              transition={{ duration: 3, repeat: Infinity }}
              className="font-terminal text-[#2a2a1a] text-sm select-none"
            >
              {audioPlayed >= 1 && (
                <motion.span
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  transition={{ duration: 1.2 }}
                  className="block"
                >*sniff*</motion.span>
              )}
              {breathCount >= 1 && (
                <motion.span
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 0.3 }}
                  transition={{ duration: 1.5 }}
                  className="block mt-3 text-[10px] text-[#1a1a10]"
                >. . .</motion.span>
              )}
              {audioPlayed >= 2 && (
                <motion.span
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  transition={{ duration: 1.2 }}
                  className="block mt-3"
                >*cough*</motion.span>
              )}
              {breathCount >= 2 && (
                <motion.span
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 0.2 }}
                  transition={{ duration: 2 }}
                  className="block mt-3 text-[8px] text-[#151510]"
                >someone&apos;s there</motion.span>
              )}
              {audioPlayed >= 3 && (
                <motion.span
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  transition={{ duration: 1.2 }}
                  className="block mt-3"
