                transition={{ delay: 2.0, duration: 0.25, ease: 'easeIn' }}
                className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-64 h-80"
              >
                <div className="paper-texture coffee-stain w-full h-full p-4 flex items-center justify-center relative cig-burn fingerprint-smudge">
