            {/* Ambient grain — very subtle */}
            <div className="absolute inset-0 opacity-[0.03] pointer-events-none" style={{
              backgroundImage: 'repeating-radial-gradient(circle, rgba(200,220,150,0.1) 0px, transparent 1px, transparent 4px)',
              backgroundSize: '4px 4px',
            }} />

            {/* Faint green fluorescent flicker */}
            <motion.div
