export function TremorMeter() {
  const [held, setHeld] = useState(false)
  const hud = useHud()
  return <div className={styles.tremor} data-held={held}>
    <span>DAVE / HAND TREMOR</span><strong>75<span>%</span></strong>
    <button className={styles.meterHold} onClick={() => { setHeld(!held); hud.pulse('press') }} aria-pressed={held} aria-label={held ? 'Resume tremor display' : 'Hold tremor display'}>{held ? <Play size={12} /> : <Pause size={12} />}{held ? 'RESUME' : 'HOLD'}</button>
    <div className={styles.meterTrack} aria-label="Canon hand tremor reading: 75 percent"><span className={styles.meterFill} /><i className={styles.tremorNeedle} /></div>
  </div>
}

export function DeckImagePanel({ image, manager = false, tremor = false }: { image: DeckImage; manager?: boolean; tremor?: boolean }) {
