  const [open, setOpen] = useState(false)
  const [input, setInput] = useState('DAVE')
  const hud = useHud()
  return <div className={styles.mediaGroup}>
    {manager && <div className={styles.reportBus} aria-label="Manager household inputs">
      {['SID', 'TAMARA', 'MIKEY', 'DAVE'].map((name) => <button key={name} aria-pressed={input === name} onClick={() => { setInput(name); hud.pulse('lock'); hud.note(`MANAGER / ${name} INPUT`) }}>{name}</button>)}
    </div>}
    <div className={`${styles.mediaFrame} ${manager ? styles.managerFrame : ''}`}>
      {image.src && !failed ? <>
        <Image src={image.src} alt={image.alt} fill sizes="(max-width: 767px) 90vw, 42vw" className={styles.artwork} draggable={false} onError={() => { console.error(`Deck artwork failed to load: ${image.src}`); setFailed(true) }} />
        <button className={styles.inspectButton} data-deck-control onClick={() => { setOpen(true); hud.pulse('press') }} aria-label={`Inspect ${image.label}`}><Expand size={14} /><span>INSPECT</span></button>
      </> : <div className={styles.assetSlot}><strong>{image.label}</strong><span>{failed ? 'Artwork unavailable' : 'Member image pending'}</span></div>}
      <div className={styles.fieldTexture} aria-hidden="true" />
      <ReadoutBrackets manager={manager} />
      {manager && <div className={styles.inputReadout} aria-live="polite"><i /> INPUT / {input}</div>}
    </div>
    <div className={styles.mediaCaption}><span>{image.caption || image.label}</span><span aria-hidden="true">ART / 3K</span></div>
    {tremor && <TremorMeter />}
    {image.src && <ArtworkViewer src={image.src} alt={image.alt} title={image.label} caption={image.caption} open={open} onOpenChange={setOpen} />}
  </div>
}

const CHANNELS = ['SID', 'TAMARA', 'MIKEY', 'DAVE'] as const

/** A presentation demo, not invented household telemetry or plot progression. */
export function OverlayAssembly() {
  const reduced = useReducedMotion()
  const hud = useHud()
  const [decay, setDecay] = useState(0)
  const [selected, setSelected] = useState<string>('DAVE')
  const [entries, setEntries] = useState<string[]>([])
  const [build, setBuild] = useState(0)
  const state = !hud.power ? 'FIELD OFF' : decay > 0.85 ? 'SIGNAL LOST' : decay > 0.35 ? 'DEGRADING' : 'CONTAINED'
  const capture = () => {
    setEntries((rows) => [selected, ...rows].slice(0, 4))
    hud.pulse('lock')
    hud.note(`DEMO LEDGER / ${selected} RECORDED`)
  }
  return <div className={styles.assembly} data-overlay-slot="chassis-surface" data-decay={decay > 0.35} style={{ '--decay': decay } as CSSProperties} data-deck-control onPointerDown={(e) => e.stopPropagation()}>
    {!reduced && <div className={styles.assemblyFrame} key={build}><HeroFrameBuild /></div>}
    <ReadoutBrackets />
    <div className={styles.assemblyTitle}><span>3K / FIELD UNIT</span><span>DEMO</span></div>
    <div className={styles.assemblyPeople} aria-label="Select household input">
      {CHANNELS.map((name) => <button key={name} aria-pressed={selected === name} onClick={() => { setSelected(name); hud.pulse('press'); hud.note(`OVERLAY / ${name}`) }}>{name}</button>)}
    </div>
    <div className={styles.scopeScreen} data-off={!hud.power || decay > 0.85}>
      <div className={styles.scopeGrid} aria-hidden="true">{Array.from({ length: 24 }, (_, i) => <i key={i} style={{ opacity: ((i * 7) % 24) / 24 < decay ? 0.08 : 1 }} />)}</div>
      <span className={styles.scopeCorner}>INPUT / {selected}</span>
      <svg className={styles.scopeTrace} viewBox="0 0 300 80" preserveAspectRatio="none" aria-hidden="true"><path d="M0 46 H26 L31 43 L35 49 L40 46 H74 L80 33 L85 59 L90 41 L95 46 H135 L140 17 L146 65 L152 38 L158 46 H201 L207 40 L212 50 L218 46 H250 L255 32 L260 57 L265 46 H300" /></svg>
      <div className={styles.scopeStatus}><span>{state}</span><strong>{selected === 'DAVE' ? '75%' : selected}</strong><small>{selected === 'DAVE' ? 'HAND TREMOR / CANON' : 'HOUSEHOLD INPUT'}</small></div>
      <div className={styles.scopeBreak} aria-hidden="true" />
    </div>
    <div className={styles.assemblyInstruments}>
      <div className={styles.ledger} data-overlay-slot="ledger">
        <div className={styles.ledgerHeading}><span>LOCAL LEDGER</span><span>{String(entries.length).padStart(2, '0')}/04</span></div>
        <div className={styles.ledgerRows} aria-live="polite">{Array.from({ length: 4 }, (_, i) => <div key={`${i}-${entries[i] || 'empty'}`}><span>{String(i + 1).padStart(2, '0')}</span>{entries[i] ? <><b>{entries[i]}</b><Check size={10} /></> : <i />}</div>)}</div>
        <button onClick={capture} disabled={!hud.power || decay > 0.85}><Plus size={12} /> RECORD INPUT</button>
      </div>
      <div className={styles.decayControl}>
        <HudDial label="DECAY" value={decay} onChange={setDecay} onDetent={() => hud.pulse('tick')} onLock={() => hud.pulse('press')} size={58} valueText={`${Math.round(decay * 100)} percent visual degradation`} />
        <button onClick={() => { setDecay(0); setEntries([]); setBuild((n) => n + 1); hud.pulse('lock'); hud.note('OVERLAY / REBUILT') }}><RotateCcw size={12} /> REBUILD</button>
      </div>
    </div>
    <p className={styles.demoNote}>Select an input. Record it. Turn the decay dial.<br />Visual demonstration — not additional story events.</p>
  </div>
}

