// ── Shrine memory data (inline — small dataset) ──
const SHRINE_MEMORIES = [
  { text: 'The candles are always lit. You don\'t remember lighting them. The wax pools around the Power Rangers like amber preserving something prehistoric.', attribution: 'THE BEDSIDE' },
  { text: 'Her photo smiles the same way it always has. Patient. Waiting. The kind of smile that says she knew you\'d end up here, sitting on the floor, talking to furniture.', attribution: 'THE PORTRAIT' },
  { text: 'VHS tapes. Labeled in her handwriting. You haven\'t watched them. You won\'t. They\'re not for watching. They\'re for having.', attribution: 'THE TAPES' },
  { text: 'The Bible is open to Ecclesiastes. "Vanity of vanities; all is vanity." Someone underlined it twice. The pen ran out halfway through the second pass.', attribution: 'THE BOOK' },
  { text: 'A jar of baby teeth. Yours. She kept every single one. Twenty tiny monuments to the fact that you were once small enough to be held.', attribution: 'THE JAR' },
  { text: 'Her hairbrush still has hair in it. You\'ve never cleaned it. Cleaning it would mean admitting the hair stopped growing.', attribution: 'THE BRUSH' },
  { text: 'Lipstick. Compact mirror. The smell is fading but it\'s still there if you press your nose close enough. You do this more often than you\'d admit.', attribution: 'HER THINGS' },
  { text: 'The nightlight glows. It\'s the only thing in this room that runs on electricity. Everything else runs on grief.', attribution: 'THE LIGHT' },
];

function getDynamicMemories(game: GameState, escalation: EscalationState) {
  const memories: { text: string; attribution: string }[] = [];
  const day = game?.day ?? 1;
  const heat = game?.heat ?? 0;
  const recruited = (game?.npcs ?? []).filter((n: any) => n?.recruited);
  if (day >= 3) memories.push({ text: `Day ${day}. You\'ve been coming here every night. The candles burn shorter. The wax pools wider. The shrine grows in the way things grow when nobody\'s watching.`, attribution: 'THE ROUTINE' });
  if (heat >= 5) memories.push({ text: 'The sirens outside are getting closer. You sit with her photo and pretend they\'re for someone else. They are, for now. But "for now" has an expiry date.', attribution: 'THE SIRENS' });
  if (recruited.length >= 3) memories.push({ text: 'You\'ve built a crew. People who depend on you. She would have hated that. Or loved it. The distinction between the two was always her specialty.', attribution: 'THE WEIGHT' });
  if (escalation.level >= 4) memories.push({ text: 'The room flickers. For a moment the bedside table is a gas station counter. The candles are cigarette lighters. Her photo is a Polaroid taped to a cash register. Then it\'s back. But the smell of petrol lingers.', attribution: 'THE BLEED' });
  if (escalation.level >= 7) memories.push({ text: 'You can hear her voice in the static now. Not words. Just the shape of words. The way she used to call your name from the kitchen. Two syllables. Rising then falling. Like a wave that knows where the shore is.', attribution: 'THE FREQUENCY' });
  return memories;
}

// ── Mood tints for scrapbook pages ──
const MOOD_TINTS: Record<string, string> = {
  warm: 'rgba(255, 220, 160, 0.06)',
  bittersweet: 'rgba(200, 180, 140, 0.05)',
  worried: 'rgba(180, 160, 120, 0.04)',
  desperate: 'rgba(160, 130, 100, 0.03)',
  quiet: 'rgba(240, 230, 210, 0.07)',
};

type TabKey = 'files' | 'memories';

interface Props {
  onBack: () => void;
  game: GameState;
  escalation: EscalationState;
}

function ShoeboxStation({ onBack, game, escalation }: Props) {
  const [activeTab, setActiveTab] = useState<TabKey>('files');

  // ── FILES state ──
  const [selectedFragId, setSelectedFragId] = useState<string | null>(null);
  const unlocked = useMemo(() => CODEX_FRAGMENTS.filter(f => f.unlock(game, escalation)), [game, escalation]);
  const locked = CODEX_FRAGMENTS.length - unlocked.length;
  const selectedFrag = unlocked.find(f => f.id === selectedFragId) ?? null;
  useEffect(() => { if (activeTab === 'files' && !selectedFragId && unlocked.length > 0) setSelectedFragId(unlocked[0].id); }, [unlocked, selectedFragId, activeTab]);

  // ── MEMORIES state ──
  const [memoryIndex, setMemoryIndex] = useState(0);
  const [memDir, setMemDir] = useState(0);
  const [imgError, setImgError] = useState(false);
  const allMemories = useMemo(() => [...SHRINE_MEMORIES, ...getDynamicMemories(game, escalation)], [game, escalation]);
  const scrapbookGame: ScrapbookGameState = useMemo(() => ({
    day: game.day, heat: game.heat, npcs: game.npcs, resources: game.resources, expeditions: game.expeditions, phase: game.phase,
  }), [game.day, game.heat, game.npcs, game.resources, game.expeditions, game.phase]);
  const pageStates = useMemo(() => SCRAPBOOK_PAGES.map(p => ({ ...p, unlocked: p.unlock(scrapbookGame, escalation) })), [scrapbookGame, escalation]);
  const [memMode, setMemMode] = useState<'shrine' | 'scrapbook'>('shrine');
  const currentPage = pageStates[memoryIndex];
  const currentMemory = allMemories[memoryIndex % allMemories.length];

  // Keyboard
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if (e.key === 'Escape') { onBack(); return; }
      if (e.key === 'Tab') { e.preventDefault(); setActiveTab(t => t === 'files' ? 'memories' : 'files'); return; }
      if (activeTab === 'memories') {
        if (e.key === 'ArrowLeft' || e.key === 'a') {
          if (memMode === 'shrine') setMemoryIndex(i => (i - 1 + allMemories.length) % allMemories.length);
          else if (memoryIndex > 0) { setMemDir(-1); setImgError(false); setMemoryIndex(i => i - 1); }
        }
        if (e.key === 'ArrowRight' || e.key === 'd') {
          if (memMode === 'shrine') setMemoryIndex(i => (i + 1) % allMemories.length);
          else if (memoryIndex < SCRAPBOOK_PAGES.length - 1) { setMemDir(1); setImgError(false); setMemoryIndex(i => i + 1); }
        }
      }
    };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, [onBack, activeTab, memMode, memoryIndex, allMemories.length]);

  // Reset memory index when switching modes
  const switchMemMode = useCallback((mode: 'shrine' | 'scrapbook') => {
    setMemMode(mode);
    setMemoryIndex(0);
    setImgError(false);
    audioManager.playSFX('nav');
  }, []);

  const isCorrupted = escalation.level >= 5;

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="fixed inset-0 z-30 overflow-hidden flex flex-col"
      style={{ background: activeTab === 'memories' && memMode === 'scrapbook' ? '#f5efe0' : 'linear-gradient(180deg, #0e0d0b 0%, #080807 100%)' }}
    >
      {/* Header */}
      <div
        className="relative z-20 flex items-center gap-3 px-4 py-3 mx-2 mt-2 flex-shrink-0"
        style={{
          background: activeTab === 'memories' && memMode === 'scrapbook' ? 'rgba(90,74,54,0.08)' : 'rgba(14,13,11,0.75)',
          backdropFilter: 'blur(12px)',
          WebkitBackdropFilter: 'blur(12px)',
          border: activeTab === 'memories' && memMode === 'scrapbook' ? '1px solid rgba(120,100,70,0.2)' : '1px solid var(--bmf-border)',
          boxShadow: '0 4px 20px rgba(0,0,0,0.3)',
        }}
      >
        <button
          onClick={() => { audioManager.playSFX('nav'); onBack(); }}
          onMouseEnter={() => playHover()}
          className={`flex items-center gap-1.5 transition font-terminal text-xs tracking-wider min-w-[44px] min-h-[44px] justify-center ${
            activeTab === 'memories' && memMode === 'scrapbook'
              ? 'text-[#6b5c42] hover:text-[#4a3c2a] border border-[rgba(120,100,70,0.2)]'
              : 'text-[var(--bmf-muted)] hover:text-[var(--bmf-text)] border border-[var(--bmf-border)]'
          }`}
          aria-label="Go back"
        >
          <ArrowLeft size={14} />
          <span className="hidden sm:inline">BACK</span>
        </button>

        <div className="flex flex-col">
          <h1 className={`font-terminal text-sm tracking-[0.25em] ${
            activeTab === 'memories' && memMode === 'scrapbook' ? 'text-[#4a3c2a]' : 'text-[var(--bmf-paper)]'
          }`}>THE SHOEBOX</h1>
          <span className={`font-typewriter text-[8px] tracking-wider ml-0 ${
            activeTab === 'memories' && memMode === 'scrapbook' ? 'text-[#a0917a]' : 'text-[var(--bmf-muted)]'
          }`}>under the bed</span>
        </div>

        {/* Tab buttons */}
        <div className="ml-auto flex items-center gap-1">
          <button
            onClick={() => { setActiveTab('files'); audioManager.playSFX('nav'); }}
            onMouseEnter={() => playHover()}
            className={`flex items-center gap-1.5 px-3 py-2 font-terminal text-[10px] tracking-[0.15em] transition-all ${
              activeTab === 'files'
                ? 'text-[var(--bmf-amber)] border-b-2 border-[var(--bmf-amber)]'
                : 'text-[var(--bmf-muted)] hover:text-[var(--bmf-paper-dim)] border-b-2 border-transparent'
            }`}
          >
            <FileText size={12} />
            FILES
          </button>
          <button
            onClick={() => { setActiveTab('memories'); audioManager.playSFX('nav'); }}
            onMouseEnter={() => playHover()}
            className={`flex items-center gap-1.5 px-3 py-2 font-terminal text-[10px] tracking-[0.15em] transition-all ${
              activeTab === 'memories'
                ? memMode === 'scrapbook' ? 'text-[#6b5c42] border-b-2 border-[#8b7a5e]' : 'text-[var(--bmf-amber)] border-b-2 border-[var(--bmf-amber)]'
                : 'text-[var(--bmf-muted)] hover:text-[var(--bmf-paper-dim)] border-b-2 border-transparent'
            }`}
          >
            <Heart size={12} />
            MEMORIES
          </button>
        </div>
      </div>

      {/* Tab content */}
      <div className="flex-1 overflow-hidden">
        <AnimatePresence mode="wait">
          {activeTab === 'files' ? (
            <motion.div key="files" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="h-full flex flex-col sm:flex-row">
              {/* Sidebar */}
              <aside className="sm:w-[280px] sm:min-w-[220px] sm:max-w-[320px] border-r border-[var(--bmf-border)] overflow-y-auto p-3 space-y-1.5" style={{ background: 'rgba(0,0,0,0.15)' }}>
                {unlocked.map((frag) => (
                  <button
                    key={frag.id}
                    onClick={() => { audioManager.playSFX('nav'); setSelectedFragId(frag.id); }}
                    onMouseEnter={() => playHover()}
                    className={`w-full text-left px-3 py-2.5 rounded transition-all font-terminal text-[11px] tracking-wider leading-tight ${
                      selectedFragId === frag.id
                        ? 'bg-[var(--bmf-amber)]/10 border border-[var(--bmf-amber)]/40 text-[var(--bmf-amber)]'
                        : 'border border-transparent text-[var(--bmf-paper-dim)] hover:border-[var(--bmf-border)] hover:text-[var(--bmf-paper)]'
                    }`}
                  >
                    <span className="block text-[9px] text-[var(--bmf-muted)] mb-0.5">{frag.category}</span>
                    {frag.title.length > 36 ? frag.title.slice(0, 33) + '...' : frag.title}
                  </button>
                ))}
                {locked > 0 && (
                  <div className="mt-4 space-y-1.5">
                    {Array.from({ length: Math.min(locked, 4) }).map((_, i) => (
                      <div key={`locked-${i}`} className="flex items-center gap-2 px-3 py-2 rounded border border-[var(--bmf-border)] opacity-30">
                        <Lock size={10} className="text-[var(--bmf-muted)]" />
                        <span className="font-terminal text-[10px] text-[var(--bmf-muted)] tracking-wider">████████ · ███████</span>
                      </div>
                    ))}
                  </div>
                )}
              </aside>

              {/* Document panel */}
              <main className="flex-1 overflow-y-auto p-4 sm:p-8">
                <AnimatePresence mode="wait">
                  {selectedFrag ? (
                    <motion.article key={selectedFrag.id} initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -8 }} transition={{ duration: 0.25 }} className="max-w-2xl">
                      <p className="font-bmf-mono text-[9px] tracking-[0.3em] text-[var(--bmf-amber)] mb-3 opacity-70">{selectedFrag.eyebrow}</p>
                      <h2 className="font-typewriter text-lg sm:text-xl text-[var(--bmf-paper)] mb-6 leading-tight">{selectedFrag.title}</h2>
                      <div className="space-y-4" data-selectable>
                        {selectedFrag.body.map((para, i) => (
                          <motion.p key={i} initial={{ opacity: 0, x: -4 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: i * 0.08, duration: 0.2 }} className="font-typewriter text-sm sm:text-[15px] text-[var(--bmf-paper-dim)] leading-relaxed">
                            {para}
                          </motion.p>
                        ))}
                      </div>
                      {selectedFrag.stamp && (
                        <motion.div initial={{ opacity: 0, rotate: -4 }} animate={{ opacity: 1, rotate: -2 }} transition={{ delay: 0.3, duration: 0.3 }} className="mt-8 inline-block px-4 py-2 border-2 border-dashed font-terminal text-[10px] tracking-[0.2em] uppercase" style={{ borderColor: 'var(--bmf-danger)', color: 'var(--bmf-danger)', opacity: 0.6, transform: 'rotate(-2deg)' }}>
                          {selectedFrag.stamp}
                        </motion.div>
                      )}
                      <div className="mt-12 h-px w-full" style={{ background: 'linear-gradient(90deg, transparent, var(--bmf-border), transparent)' }} />
                    </motion.article>
                  ) : (
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex flex-col items-center justify-center h-full text-center">
                      <BookOpen size={32} className="text-[var(--bmf-muted)] mb-4 opacity-30" />
                      <p className="font-terminal text-xs tracking-wider text-[var(--bmf-muted)]">NO FRAGMENT SELECTED</p>
                      <p className="font-typewriter text-[11px] text-[var(--bmf-paper-faint)] mt-2">Check the bins after a run.</p>
                    </motion.div>
                  )}
                </AnimatePresence>
              </main>
            </motion.div>
          ) : (
            <motion.div key="memories" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="h-full flex flex-col">
              {/* Memory sub-mode switcher */}
              <div className={`flex items-center gap-2 px-4 py-2 mx-2 flex-shrink-0 ${
                memMode === 'scrapbook' ? 'border-b border-[rgba(120,100,70,0.15)]' : 'border-b border-[var(--bmf-border)]'
              }`}>
                <button
                  onClick={() => switchMemMode('shrine')}
                  className={`px-3 py-1.5 font-terminal text-[9px] tracking-[0.15em] transition-all rounded ${
                    memMode === 'shrine'
                      ? 'bg-[var(--bmf-amber)]/15 text-[var(--bmf-amber)] border border-[var(--bmf-amber)]/30'
                      : 'text-[var(--bmf-muted)] hover:text-[var(--bmf-paper-dim)] border border-transparent'
                  }`}
                >
                  THE SHRINE
                </button>
                <button
                  onClick={() => switchMemMode('scrapbook')}
                  className={`px-3 py-1.5 font-terminal text-[9px] tracking-[0.15em] transition-all rounded ${
                    memMode === 'scrapbook'
                      ? 'bg-[rgba(120,100,70,0.15)] text-[#6b5c42] border border-[rgba(120,100,70,0.3)]'
                      : memMode === 'shrine' ? 'text-[var(--bmf-muted)] hover:text-[var(--bmf-paper-dim)] border border-transparent' : 'text-[#a0917a] hover:text-[#6b5c42] border border-transparent'
                  }`}
                >
                  HER PHOTOS
                </button>
                <span className={`ml-auto font-terminal text-[9px] tracking-wider ${
                  memMode === 'scrapbook' ? 'text-[#a0917a]' : 'text-[var(--bmf-muted)]'
                }`}>
                  {memMode === 'shrine' ? `${memoryIndex + 1}/${allMemories.length}` : `${memoryIndex + 1}/${SCRAPBOOK_PAGES.length}`}
                </span>
              </div>

              {/* Memory content */}
              <div className="flex-1 overflow-hidden relative">
                {memMode === 'shrine' ? (
                  /* ── SHRINE MODE — dark, candle-lit whispers ── */
                  <div className="h-full flex flex-col relative">
                    {/* Shrine image background */}
                    <div className="absolute inset-0">
