            </motion.div>
          )}
        </AnimatePresence>
      </div>

      {/* Ambient scanlines */}
      {!(activeTab === 'memories' && memMode === 'scrapbook') && (
        <>
          <div className="fixed inset-0 pointer-events-none z-50 opacity-[0.02]" style={{ backgroundImage: 'repeating-linear-gradient(0deg, transparent 0px, rgba(255,255,255,0.3) 1px, transparent 2px)', backgroundSize: '100% 3px' }} />
          <div className="fixed inset-0 pointer-events-none z-50 opacity-[0.012]" style={{ backgroundImage: 'repeating-linear-gradient(90deg, transparent 0px, rgba(200,180,140,0.4) 1px, transparent 2px)', backgroundSize: '4px 100%' }} />
