const SPRINT1_TILE = 64;
let MAP = null;
let GAME = {
  heat: 0,
  looted: new Set(),
  player: { x: 2, y: 2, moveRange: 3, remaining: 3, vice: null, stress: 0 },
  enemies: [],
  encounters: {}
};

async function loadAndInit(mapUrl, encountersUrl) {
  MAP = await fetch(mapUrl).then(r => r.json());
  GAME.player.x = MAP.spawn.x;
  GAME.player.y = MAP.spawn.y;
  GAME.player.remaining = GAME.player.moveRange;
  const enc = await fetch(encountersUrl).then(r => r.json());
  enc.encounters.forEach(e => GAME.encounters[e.id] = e);
  spawnEnemiesFromMap(MAP);
  renderInitialMap();
  updateHeatUI();
}

function spawnEnemiesFromMap(map) {
  GAME.enemies = map.enemies.map(e => ({
    id: e.id,
    patrol: e.patrol.slice(),
    patrolIndex: 0,
    pos: { x: e.patrol[0].x, y: e.patrol[0].y },
    cone: e.cone,
    state: e.initial_state
  }));
}

function tryPlayerMove(dx, dy) {
  if (GAME.player.remaining <= 0) return false;
  const nx = GAME.player.x + dx;
  const ny = GAME.player.y + dy;
  if (!isTileInBounds(nx, ny) || isTileBlocked(nx, ny)) return false;
  if (GAME.enemies.some(en => en.pos.x === nx && en.pos.y === ny)) return false;
  GAME.player.x = nx;
  GAME.player.y = ny;
  GAME.player.remaining -= 1;
  onPlayerMovedTo({ x: nx, y: ny });
  return true;
}

function isTileInBounds(x, y) {
  return x >= 0 && y >= 0 && x < MAP.meta.width && y < MAP.meta.height;
}

function isTileBlocked(x, y) {
  const to = MAP.tile_overrides || [];
  return to.some(t => t.x === x && t.y === y && t.state === 'blocked');
}

function onPlayerMovedTo(tile) {
  const node = MAP.garbage_nodes.find(n => n.x === tile.x && n.y === tile.y && n.state === 'full');
  if (node) {
    openGarbageNode(node.id);
    GAME.player.remaining = 0;
  }
  for (const en of GAME.enemies) {
    if (isTileInCone(en, tile)) {
      triggerEncounterForEnemy(en);
      return;
    }
  }
  updatePlayerUI();
}

function isTileInCone(enemy, tile) {
  const dx = tile.x - enemy.pos.x;
  const dy = tile.y - enemy.pos.y;
  const dist = Math.hypot(dx, dy);
  if (dist > enemy.cone.range_tiles + 0.01) return false;

  let dirVec = { x: 0, y: 0 };
  switch (enemy.cone.dir) {
    case 'up': dirVec = { x: 0, y: -1 }; break;
    case 'down': dirVec = { x: 0, y: 1 }; break;
    case 'left': dirVec = { x: -1, y: 0 }; break;
    case 'right': dirVec = { x: 1, y: 0 }; break;
  }
  const dot = dx * dirVec.x + dy * dirVec.y;
  if (dot <= 0) return false;
  const cosAngle = dot / (Math.hypot(dx, dy) * Math.hypot(dirVec.x, dirVec.y) + 0.0001);
  const angle = Math.acos(Math.min(1, Math.max(-1, cosAngle))) * (180 / Math.PI);
  return angle <= (enemy.cone.angle_deg / 2);
}

function triggerEncounterForEnemy(enemy) {
  const toneMap = {
    'guard_1': 'enc_rigid_officer',
    'guard_2': 'enc_clinical_guard',
    'roamer_1': 'enc_hesitant_vendor'
  };
  const encId = toneMap[enemy.id] || 'enc_hesitant_vendor';
  const enc = GAME.encounters[encId];
  showEncounterUI(enc, enemy);
}

function openGarbageNode(nodeId) {
  const node = MAP.garbage_nodes.find(n => n.id === nodeId);
  if (!node || node.state !== 'full') return;
  node.state = 'looted';
  GAME.looted.add(nodeId);
  GAME.heat = Math.min(100, GAME.heat + 5);
  updateHeatUI();
  console.log('Node looted:', nodeId);
}

function resolveEncounter(encounterId, responseIndex, enemyId) {
  const enc = GAME.encounters[encounterId];
  const resp = enc.responses[responseIndex];
  const tone = enc.tone.toLowerCase();
  const approachTag = resp.approach.split('/')[0].toLowerCase();
  const approachMatches = approachTag === tone;
  const successChance = approachMatches ? 0.75 : 0.35;
  const success = Math.random() < successChance;
  if (success) {
    GAME.heat = Math.max(0, GAME.heat + (resp.outcome.success.heat_delta || 0));
    showMessage(resp.outcome.success.message || 'Success.');
  } else {
    GAME.player.stress += (resp.outcome.fail?.stress || 1);
    GAME.heat = Math.min(100, GAME.heat + (resp.outcome.fail?.heat_delta || 10));
    if (resp.outcome.fail?.knockout) {
      showMessage('Player knocked out!');
    } else {
      showMessage('Encounter failed.');
    }
  }
  updateHeatUI();
  closeEncounterUI();
}

function showEncounterUI(encounter, enemy) {
  const panel = document.getElementById('encounter-panel');
  if (!panel) {
    console.warn('Encounter panel not found');
    return;
  }
  panel.querySelector('.enc-text').innerText = encounter.text;
  const anchors = encounter.anchors.join(', ');
  panel.querySelector('.enc-anchors').innerText = `Anchors: ${anchors}`;
  const opts = panel.querySelector('.enc-options');
  opts.innerHTML = '';
  encounter.responses.forEach((r, i) => {
    const b = document.createElement('button');
    b.innerText = r.label;
    b.onclick = () => resolveEncounter(encounter.id, i, enemy.id);
    opts.appendChild(b);
  });
  panel.style.display = 'block';
}

function closeEncounterUI() {
  const panel = document.getElementById('encounter-panel');
  if (panel) panel.style.display = 'none';
}

function showMessage(msg) {
  const m = document.getElementById('message-box');
  if (m) {
    m.innerText = msg;
    setTimeout(() => { m.innerText = ''; }, 2800);
  } else {
    console.log(msg);
  }
}

function renderInitialMap() {
  console.log('Map loaded:', MAP.meta.name);
}

function updateHeatUI() {
  const el = document.getElementById('heat-label');
  if (el) el.innerText = `Heat: ${GAME.heat}`;
}

function updatePlayerUI() {
  const el = document.getElementById('player-status');
  if (el) el.innerText = `Player: (${GAME.player.x},${GAME.player.y}) Remain: ${GAME.player.remaining}`;
}
