import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import {
  computeActorState,
  resolveEncounterAction,
  resolveDose,
  getAvailableVerbs,
  getActorMood,
  getActorTell,
  calculateScenePressure,
  createEncounterRng,
  ENCOUNTER_TEMPLATES,
  type ActorState,
  type SceneState,
  type EncounterVerb,
  type EncounterResult,
} from '@/lib/encounter';
import { NPC_DATA, type NPCKey, type ResourceKey } from '@/lib/game-data';
import { isValidId } from '@/lib/api-guards';

// ======================================================================
// /api/game/encounter — Encounter System v1 Server-Authoritative Endpoint
//
// Actions:
//   init   — start an encounter, compute scene + actor state, return verbs
//   verb   — resolve a verb action, return outcome + updated state
//   dose   — dose an NPC during or between encounters
// ======================================================================

export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const { sessionId, action } = body ?? {};
    if (!isValidId(sessionId) || !action) {
      return NextResponse.json({ error: 'Missing sessionId or action' }, { status: 400 });
    }

    const session = await prisma.gameSession.findUnique({
      where: { id: sessionId },
      include: { npcs: true, resources: true },
    });
    if (!session) {
      return NextResponse.json({ error: 'Session not found' }, { status: 404 });
    }

    // ── INIT: Start an encounter ──────────────────────────────────────
    if (action === 'init') {
      const { trigger, npcId, seed } = body;
      // Find the encounter template
      const template = ENCOUNTER_TEMPLATES.find((t) => t.trigger === trigger)
        ?? ENCOUNTER_TEMPLATES[0];

      // Find lead NPC (use first recruited if no npcId)
      const recruitedNpcs = (session.npcs ?? []).filter((n: any) => n.recruited);
      const leadNpc = npcId
        ? recruitedNpcs.find((n: any) => n.id === npcId)
        : recruitedNpcs[0];

      if (!leadNpc) {
        return NextResponse.json({ error: 'No recruited NPC available' }, { status: 400 });
      }

      const actorState = computeActorState(leadNpc);
      const scene: SceneState = {
        pressure: template.initialPressure,
        urgency: template.urgency,
        exposure: template.exposure,
        volatileCount: recruitedNpcs.filter((n: any) => {
          const s = computeActorState(n);
          return s.volatility >= 6;
        }).length,
      };

      const hasResources = (session.resources ?? []).some((r: any) => (r.quantity ?? 0) > 0);
      const verbs = getAvailableVerbs(scene, actorState, hasResources, recruitedNpcs.length);

      return NextResponse.json({
        encounter: {
          trigger: template.trigger,
          name: template.name,
          flavour: template.flavour,
        },
        scene,
        scenePressure: calculateScenePressure(scene),
        actor: {
          id: leadNpc.id,
          name: leadNpc.name,
          mood: getActorMood(actorState),
          tell: getActorTell(actorState),
          // Qualitative bars (0-10, but UI should show as bars not numbers)
          state: actorState,
        },
        verbs,
        crewSize: recruitedNpcs.length,
      });
    }

    // ── VERB: Resolve an encounter action ─────────────────────────────
    if (action === 'verb') {
      const { verb, npcId, scene: clientScene, seed } = body as {
        verb: EncounterVerb;
        npcId: string;
        scene: SceneState;
        seed: number;
      };

      const npc = (session.npcs ?? []).find((n: any) => n.id === npcId);
      if (!npc) {
        return NextResponse.json({ error: 'NPC not found' }, { status: 404 });
      }

      const actorState = computeActorState(npc);
      const rng = createEncounterRng(seed ?? Date.now());
      const seedVal = rng();

      const result: EncounterResult = resolveEncounterAction(
        verb,
        clientScene,
        actorState,
        seedVal,
      );

      // Apply heat delta to session
      if (result.heatDelta !== 0) {
        await prisma.gameSession.update({
          where: { id: sessionId },
          data: { heat: { increment: result.heatDelta } },
        });
      }

      // Apply resource costs
      for (const [type, delta] of Object.entries(result.resourceCost)) {
        if (!delta || delta === 0) continue;
        const resource = (session.resources ?? []).find((r: any) => r.type === type);
        if (resource) {
          await prisma.resource.update({
            where: { id: resource.id },
            data: { quantity: Math.max(0, resource.quantity + delta) },
          });
        }
      }

      // Compute new scene state
      const newScene: SceneState = {
        ...clientScene,
        pressure: Math.min(10, Math.max(0, clientScene.pressure + result.pressureDelta)),
      };

      // Recompute actor state for updated verbs
      const updatedNpc = await prisma.nPC.findUnique({ where: { id: npcId } });
      const newActorState = updatedNpc ? computeActorState(updatedNpc) : actorState;
      const hasResources = (await prisma.resource.findMany({ where: { sessionId } }))
        .some((r: any) => (r.quantity ?? 0) > 0);
      const recruitedCount = (session.npcs ?? []).filter((n: any) => n.recruited).length;

      const newVerbs = result.endsEncounter
        ? []
        : getAvailableVerbs(newScene, newActorState, hasResources, recruitedCount);

      return NextResponse.json({
        result,
        scene: newScene,
        scenePressure: calculateScenePressure(newScene),
        actor: {
          id: npcId,
          name: npc.name,
          mood: getActorMood(newActorState),
          tell: getActorTell(newActorState),
          state: newActorState,
        },
        verbs: newVerbs,
        ended: result.endsEncounter,
      });
    }

    // ── DOSE: Administer substance to NPC ────────────────────────────
    if (action === 'dose') {
      const { npcId, npcKey, resourceType } = body;
      const npc = (session.npcs ?? []).find((n: any) => n.id === npcId);
      if (!npc) {
        return NextResponse.json({ error: 'NPC not found' }, { status: 404 });
      }

      const npcData = NPC_DATA[npcKey as NPCKey];
      if (!npcData?.vice) {
        return NextResponse.json({ error: 'NPC has no vice profile' }, { status: 400 });
      }

      // Check resource
      const resource = (session.resources ?? []).find((r: any) => r.type === resourceType);
      if (!resource || resource.quantity < 1) {
        return NextResponse.json({ error: 'Out of stock' }, { status: 400 });
      }

      const actorState = computeActorState(npc);
      const preference = npcData.vice.preferences[resourceType as ResourceKey] ?? 0;
      const isCraving = (npcData.vice.cravings ?? []).includes(resourceType);

      const doseResult = resolveDose(actorState, preference, isCraving);

      // Deduct resource
      await prisma.resource.update({
        where: { id: resource.id },
        data: { quantity: resource.quantity - 1 },
      });

      return NextResponse.json({
        dose: doseResult,
        remainingResource: resource.quantity - 1,
        actor: {
          mood: getActorMood({
            ...actorState,
            ...Object.fromEntries(
              Object.entries(doseResult.deltas).map(([k, v]) => [
                k,
                Math.min(10, Math.max(0, (actorState[k as keyof ActorState] ?? 0) + (v ?? 0))),
              ]),
            ),
          } as ActorState),
          tell: getActorTell(actorState),
        },
      });
    }

    return NextResponse.json({ error: 'Unknown action' }, { status: 400 });
  } catch (err: unknown) {
    console.error('Encounter API error:', err);
    return NextResponse.json({ error: 'Encounter failed' }, { status: 500 });
  }
}

/* 3K OVERLAY LOCK + VIP SHELL
   Palette: lime #B8F026 / magenta #E040B0 on near-black. Flat colour only — no
   gradients, no glow, no amber/yellow/orange. Joins the app's existing
   instrument language (same mono readouts, Space Grotesk display, hairlines). */

.station, .lock {
  --lime: #B8F026; --magenta: #E040B0; --ink: #E8E4D9;
  --ground: #0A0A08; --panel: #111210; --readout: #0d0e0b;
  --bevel-light: #20231b; --bevel-dark: #050504; --rule: #3a3f31; --dim: #8b937f;
  --mono: ui-monospace, 'SF Mono', Menlo, Consolas, monospace;
}

/* ---------- VIP shell (beneath the lock) ---------- */
.station { height: 100%; min-height: 100%; width: 100%; color: var(--ink); }
.shell { max-width: 1200px; margin: 0 auto; padding: clamp(24px, 5vh, 56px) clamp(18px, 4vw, 48px) 56px; opacity: 0; transition: opacity .4s ease; }
.shell[data-revealed] { opacity: 1; }
.shellHeader { display: flex; flex-direction: column; gap: 10px; margin-bottom: clamp(24px, 4vh, 44px); }
.shellStamp { display: none; }
.shellTitle { margin: 0; font: 500 clamp(24px, 3.5vw, 38px)/1.2 'Space Grotesk', system-ui, sans-serif; letter-spacing: -.03em; color: var(--lime); text-transform: uppercase; }
.shellSub { margin: 0; font: 400 clamp(13px, 1.4vw, 16px)/1.5 'Space Grotesk', system-ui, sans-serif; color: var(--ink); opacity: .72; }
.slots { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: clamp(14px, 2vw, 24px); }
.slot { position: relative; display: flex; flex-direction: column; min-height: 180px; background: transparent; border: 0; border-top: 1px solid var(--rule); padding: 18px 18px 14px; }
.slotBrackets { display: none; }
.slotBrackets i { position: absolute; width: 18px; height: 18px; border: 0 solid var(--lime); }
.slotBrackets [data-corner='tl'] { top: 0; left: 0; border-top-width: 2px; border-left-width: 2px; }
.slotBrackets [data-corner='tr'] { top: 0; right: 0; border-top-width: 2px; border-right-width: 2px; }
.slotBrackets [data-corner='bl'] { bottom: 0; left: 0; border-bottom-width: 2px; border-left-width: 2px; border-color: var(--magenta); }
.slotBrackets [data-corner='br'] { bottom: 0; right: 0; border-bottom-width: 2px; border-right-width: 2px; border-color: var(--magenta); }
.slotHead { display: flex; align-items: baseline; gap: 10px; padding-bottom: 12px; border-bottom: 1px solid var(--rule); }
.slotHead span { font: 9px/1 var(--mono); letter-spacing: .14em; color: var(--magenta); }
.slotHead h2 { margin: 0; font: 500 clamp(14px, 1.3vw, 17px)/1.2 'Space Grotesk', system-ui, sans-serif; letter-spacing: .06em; color: var(--lime); }
.slotBody { flex: 1; min-height: 32px; margin: 12px 0; }
.slotFoot { font: 8px/1 var(--mono); letter-spacing: .2em; color: var(--dim); }

/* ---------- The lock ---------- */
.lock { position: fixed; inset: 0; z-index: 60; display: flex; align-items: center; justify-content: center; padding: 10px; background: var(--ground); color: var(--lime); font-family: var(--mono); overflow: hidden; }
.lock[data-state='unlocking'] { pointer-events: none; animation: lockLift .5s ease 1.6s forwards; }
.lock[data-motion='reduced'][data-state='unlocking'] { animation: lockLift .45s ease forwards; }
@keyframes lockLift { to { opacity: 0; visibility: hidden; } }

/* Idle scanline drift — one subtle motion, no looping distraction. */
.scanlines { position: absolute; inset: 0; z-index: 2; pointer-events: none; background: repeating-linear-gradient(to bottom, transparent 0 3px, rgba(184, 240, 38, .015) 3px 4px); }
@keyframes scanDrift { to { background-position: 0 40px; } }
/* Dismantle — the wipe line sweeps top-to-bottom and clears the scanlines behind it. */
.wipe { position: absolute; left: 0; right: 0; top: -3px; height: 3px; background: var(--lime); opacity: 0; z-index: 3; pointer-events: none; }
.lock[data-state='unlocking'] .wipe { animation: wipeDown 1.1s .2s linear forwards; }
.lock[data-state='unlocking'] .scanlines { animation: wipeClear 1.1s .2s linear forwards; }
@keyframes wipeDown { 0% { top: -3px; opacity: 1; } 100% { top: 100%; opacity: 1; } }
@keyframes wipeClear { 0% { clip-path: inset(0 0 0 0); } 100% { clip-path: inset(100% 0 0 0); } }

.chassis { position: relative; z-index: 1; width: min(880px, 100%); max-height: 100%; overflow: auto; background: var(--panel); border: 2px solid var(--rule); box-shadow: none; padding: 14px 18px 12px; display: flex; flex-direction: column; gap: 14px; }
.corner { position: absolute; width: 16px; height: 16px; border: 2px solid var(--lime); pointer-events: none; }
.corner[data-corner='tl'] { top: 5px; left: 5px; border-right: 0; border-bottom: 0; }
.corner[data-corner='br'] { bottom: 5px; right: 5px; border-left: 0; border-top: 0; }

.statusBar { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding-bottom: 10px; border-bottom: 2px solid var(--rule); }
.stamp { font: 9px/1 var(--mono); letter-spacing: .18em; text-transform: uppercase; color: var(--lime); white-space: nowrap; }
.footer .stamp { color: var(--dim); font-size: 8px; }
.exit { min-height: 36px; padding: 0 10px; background: var(--readout); border: 1px solid var(--rule); color: var(--ink); font: 9px/1 var(--mono); letter-spacing: .14em; }
.exit:hover { border-color: var(--lime); color: var(--lime); }

/* STATUS LAMP — standby / magenta on mismatch / lime on access. */
.lamp { display: inline-flex; align-items: center; gap: 8px; min-height: 30px; padding: 0 12px; border: 1px solid var(--lime); background: var(--readout); font: 9px/1 var(--mono); letter-spacing: .2em; color: var(--lime); transition: color .15s, border-color .15s, background .15s; }
.lamp i { width: 8px; height: 8px; background: currentColor; opacity: .55; }
.lamp[data-state='reject'] { color: var(--magenta); border-color: var(--magenta); background: #1a0a14; }
.lamp[data-state='reject'] i { opacity: 1; }
.lamp[data-state='confirm'], .lamp[data-state='unlocking'] { color: #0A0A08; background: var(--lime); border-color: var(--lime); }
.lamp[data-state='confirm'] i, .lamp[data-state='unlocking'] i { opacity: 1; }

.title { margin: 0; text-align: center; font: 600 clamp(15px, 3.2vw, 22px)/1.1 'Space Grotesk', system-ui, sans-serif; letter-spacing: .2em; text-transform: uppercase; color: var(--lime); }

.cluster { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.7fr); gap: 16px; align-items: start; }

/* GREEN BAND gauge */
.gaugePanel { border: 2px solid var(--rule); background: var(--readout); padding: 12px; display: flex; flex-direction: column; gap: 10px; }
.gaugeLabel, .inputLabel, .verifyLabel { font: 8px/1 var(--mono); letter-spacing: .2em; text-transform: uppercase; color: var(--lime); }
.verifyLabel { color: var(--dim); }
.gaugeTrack { position: relative; height: 18px; border: 1px solid var(--lime); background: var(--ground); }
.gaugeBand { position: absolute; top: 0; bottom: 0; left: 36%; width: 28%; background: #1d2a0a; border-left: 1px solid #4b6414; border-right: 1px solid #4b6414; }
.gaugeFill { position: absolute; top: 0; bottom: 0; left: 0; width: 0; background: var(--lime); transition: width .5s cubic-bezier(.4, 0, .2, 1); }
.gaugeNeedle { position: absolute; top: -4px; bottom: -4px; width: 3px; left: 50%; margin-left: -1px; background: var(--lime); transition: left .45s cubic-bezier(.4, 0, .2, 1), background .15s; }
.gaugePanel[data-gauge='full'] .gaugeFill { width: 100%; }
.gaugePanel[data-gauge='full'] .gaugeNeedle { left: 100%; margin-left: -3px; }
.gaugePanel[data-gauge='out'] .gaugeNeedle { left: 9%; background: var(--magenta); transition-duration: .12s; }
.caliper { height: 7px; background: repeating-linear-gradient(to right, var(--rule) 0 1px, transparent 1px 8px); }
.gaugeReadout { font: 10px/1 var(--mono); letter-spacing: .12em; color: var(--lime); }
.gaugePanel[data-gauge='out'] .gaugeReadout { color: var(--magenta); }

/* Input panel */
.inputPanel { display: flex; flex-direction: column; gap: 12px; min-width: 0; }
.readoutFrame { position: relative; display: flex; align-items: center; min-height: 54px; padding: 10px 14px; border: 3px solid var(--lime); background: var(--readout); cursor: text; }
.readoutFrame:focus-within { outline: 2px solid var(--magenta); outline-offset: 2px; }
.input { flex: 0 1 auto; width: auto; min-width: 1ch; max-width: 100%; background: transparent; border: 0; outline: 0; color: var(--lime); font: 20px/1 var(--mono); letter-spacing: .2em; text-transform: uppercase; caret-color: transparent; }
.input:disabled { opacity: .85; }
.cursor { display: inline-block; width: .6em; height: 1.1em; font-size: 20px; background: var(--lime); flex-shrink: 0; animation: blink 1.05s steps(1) infinite; }
.readoutFrame:not(:focus-within) .cursor { opacity: .35; animation: none; }
@keyframes blink { 0%, 50% { opacity: 1; } 51%, 100% { opacity: 0; } }

.verify { display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-rows: auto auto; gap: 6px 10px; align-items: center; }
.verifyLabel { grid-column: 1 / -1; }
.verifyTrack { position: relative; height: 12px; border: 1px solid var(--lime); background: var(--ground); }
.verifyFill { position: absolute; top: 0; bottom: 0; left: 0; background: var(--lime); transition: width .08s linear; }
.lock[data-state='reject'] .verifyFill { background: var(--magenta); transition: width .2s ease; }
.verifyPct { font: 11px/1 var(--mono); letter-spacing: .08em; min-width: 3.2em; text-align: right; }

.message { display: flex; align-items: center; min-height: 40px; padding: 8px 12px; border: 1px solid var(--rule); background: var(--readout); font: 10px/1.4 var(--mono); letter-spacing: .12em; text-transform: uppercase; color: var(--lime); transition: color .15s, border-color .15s; }
.lock[data-state='reject'] .message { color: var(--magenta); border-color: var(--magenta); }
.lock[data-state='confirm'] .message, .lock[data-state='unlocking'] .message { border-color: var(--lime); }

.submit { align-self: flex-start; min-height: 40px; padding: 0 16px; border: 2px solid var(--lime); border-bottom-width: 4px; background: var(--panel); color: var(--lime); font: 10px/1 var(--mono); letter-spacing: .18em; }
.submit:hover { background: var(--lime); color: #0A0A08; }
.submit:active { border-bottom-width: 2px; transform: translateY(2px); }
.submit:disabled { opacity: .5; }

.footer { display: flex; justify-content: space-between; gap: 10px; padding-top: 10px; border-top: 2px solid var(--rule); flex-wrap: wrap; }

.exit:focus-visible, .submit:focus-visible, .input:focus-visible { outline: 2px solid var(--magenta); outline-offset: 3px; }
.input:focus-visible { outline: 0; }

/* ---------- Dismantle: chassis panels slide and rotate away like a mechanism opening ---------- */
.lock[data-state='unlocking'] .chassis { overflow: visible; border-color: transparent; box-shadow: none; background: transparent; transition: border-color .4s .9s, box-shadow .4s .9s, background .4s .9s; }
.lock[data-state='unlocking'] .corner { animation: cornerOut .6s .9s cubic-bezier(.4, 0, .2, 1) forwards; }
.lock[data-state='unlocking'] [data-panel='top'] { animation: panelTop .9s .7s cubic-bezier(.4, 0, .2, 1) forwards; }
.lock[data-state='unlocking'] [data-panel='title'] { animation: panelTitle .8s .8s cubic-bezier(.4, 0, .2, 1) forwards; }
