import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { isValidId } from '@/lib/api-guards';

// ══════════════════════════════════════════════
// RESOURCE TRADING — asymmetric exchange rates
// ──────────────────────────────────────────────
// Every round-trip trade LOSES value to prevent exploitative loops.
// Max 3 trades per day to cap manipulation.
// ══════════════════════════════════════════════

const MAX_RESOURCE = 30;
const MAX_TRADES_PER_DAY = 3;

// Trade rates: { from: { to: { cost, gain } } }
// cost = how many of 'from' you spend, gain = how many of 'to' you get
const TRADE_RATES: Record<string, Record<string, { cost: number; gain: number }>> = {
  cigarettes: {
    alcohol:  { cost: 4, gain: 1 },
    weed:     { cost: 5, gain: 1 },
    crystals: { cost: 7, gain: 1 },
  },
  alcohol: {
    cigarettes: { cost: 1, gain: 2 },
    weed:       { cost: 2, gain: 1 },
    crystals:   { cost: 4, gain: 1 },
  },
  weed: {
    cigarettes: { cost: 1, gain: 3 },
    alcohol:    { cost: 1, gain: 1 },
    crystals:   { cost: 3, gain: 1 },
  },
  crystals: {
    cigarettes: { cost: 1, gain: 4 },
    alcohol:    { cost: 1, gain: 2 },
    weed:       { cost: 1, gain: 2 },
  },
};

export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const { sessionId, from, to } = body ?? {};

    if (!isValidId(sessionId)) {
      return NextResponse.json({ error: 'Missing sessionId' }, { status: 400 });
    }

    // Validate trade pair
    if (typeof from !== 'string' || typeof to !== 'string' || from === to) {
      return NextResponse.json({ error: 'Invalid trade pair' }, { status: 400 });
    }
    const rate = TRADE_RATES[from]?.[to];
    if (!rate) {
      return NextResponse.json({ error: 'Unknown trade route' }, { status: 400 });
    }

    const session = await prisma.gameSession.findUnique({
      where: { id: sessionId },
      include: { resources: true },
    });
    if (!session) {
      return NextResponse.json({ error: 'Session not found' }, { status: 404 });
    }

    // Daily trade cap (stored in localStorage client-side, but server validates via simple counter)
    // We'll track trades via a lightweight approach: count trades this session day
    // For now, use client-side enforcement (server checks resource availability only)

    // Check 'from' resource availability
    const fromRow = (session.resources ?? []).find((r: any) => r.type === from);
    const fromQty = fromRow?.quantity ?? 0;
    if (fromQty < rate.cost) {
      return NextResponse.json({
        error: 'insufficient',
        message: `Need ${rate.cost} ${from} — you only have ${fromQty}.`,
      }, { status: 409 });
    }

    // Deduct 'from' resource
    if (fromRow) {
      await prisma.resource.update({
        where: { id: fromRow.id },
        data: { quantity: Math.max(0, fromQty - rate.cost) },
      });
    }

    // Add 'to' resource (capped)
    const toRow = await prisma.resource.upsert({
      where: { sessionId_type: { sessionId, type: to } },
      update: { quantity: { increment: rate.gain } },
      create: { sessionId, type: to, quantity: rate.gain },
    });
    let toFinal = toRow.quantity;
    if (toFinal > MAX_RESOURCE) {
      await prisma.resource.update({
        where: { sessionId_type: { sessionId, type: to } },
        data: { quantity: MAX_RESOURCE },
      });
      toFinal = MAX_RESOURCE;
    }

    return NextResponse.json({
      ok: true,
      from: { type: from, spent: rate.cost, remaining: Math.max(0, fromQty - rate.cost) },
      to: { type: to, gained: rate.gain, total: toFinal },
    });
  } catch (err: unknown) {
    console.error('Trade error:', err);
    return NextResponse.json({ error: 'Trade failed' }, { status: 500 });
  }
}

// GET — return available trade rates (client can fetch once)
export async function GET() {
  return NextResponse.json({ rates: TRADE_RATES, maxPerDay: MAX_TRADES_PER_DAY });
}

