  const s = color;
  const glitchAmount = Math.min(escalation * 0.3, 2.5);
  const glow = `drop-shadow(0 0 8px ${color}) drop-shadow(0 0 22px ${color}80) drop-shadow(0 0 44px ${color}25)`;

  // Orbiting data particles — varied sizes, staggered
