        const r = 38 + (i % 3) * 3;
        return (
          <motion.circle key={`p${i}`} cx={50 + r * Math.cos((deg * Math.PI) / 180)} cy={50 + r * Math.sin((deg * Math.PI) / 180)}
            r={0.5 + (i % 3) * 0.3} fill={`${s}90`}
            animate={{ opacity: [0.05, 0.7, 0.05], r: [0.3 + (i % 3) * 0.2, 1.0 + (i % 2) * 0.4, 0.3 + (i % 3) * 0.2] }}
