// Floating data fragment that orbits the hologram
function HologramDataOrbit({ fragments, color }: { fragments: string[]; color: string }) {
  return (
    <div className="absolute inset-0 pointer-events-none overflow-hidden">
      {fragments.slice(0, 6).map((text, i) => {
        const angle = (i / 6) * 360;
        const radius = 52 + (i % 3) * 6;
        const duration = 12 + i * 2;
        return (
          <motion.div
            key={i}
            className="absolute font-bmf-mono whitespace-nowrap"
            style={{
              fontSize: '7px',
              letterSpacing: '0.15em',
              color: `${color}${40 + (i % 3) * 15}`,
              left: '50%',
              top: '50%',
              transformOrigin: '0 0',
            }}
            animate={{
              rotate: [angle, angle + 360],
              opacity: [0.15, 0.5, 0.15],
            }}
            transition={{
              rotate: { duration, repeat: Infinity, ease: 'linear' },
              opacity: { duration: 3, repeat: Infinity, delay: i * 0.5 },
            }}
          >
            <span style={{ display: 'inline-block', transform: `translateX(${radius}px) translateY(-4px)` }}>
              {text}
            </span>
          </motion.div>
        );
      })}
    </div>
  );
}

