// STASH LASER FIELD — "Behind-The-Counter" ambient laser grid
// Thin refracted beams that drift slowly across the dark back wall.
// Restrained: low-opacity, slow, never compete with content.
// ═══════════════════════════════════════════════════════════════════════
/* v5.0 perf: LaserField — replaced 26 framer-motion elements with pure CSS animations.
   Uses CSS @keyframes via inline <style> + static SVG. Zero JS animation overhead. */
function LaserField({ escalation }: { escalation: number }) {
  const intensity = Math.min(1, 0.5 + escalation * 0.06);
  const beams = [
    { x1: 5, y1: 0, x2: 35, y2: 100, dur: 18, delay: 0, c: '#8aad7a', w: 0.6 },
    { x1: 25, y1: 0, x2: 60, y2: 100, dur: 22, delay: 2, c: '#7ab8b8', w: 0.4 },
    { x1: 55, y1: 0, x2: 80, y2: 100, dur: 20, delay: 4, c: '#9a86b5', w: 0.5 },
    { x1: 80, y1: 0, x2: 45, y2: 100, dur: 24, delay: 1, c: '#a8687e', w: 0.35 },
    { x1: 15, y1: 0, x2: 90, y2: 100, dur: 26, delay: 3, c: '#8aad7a', w: 0.3 },
  ];

  return (
    <div className="absolute inset-0 pointer-events-none overflow-hidden" style={{ opacity: 0.12 * intensity, contain: 'strict' }}>
      <style>{`
        @keyframes lf-grid{0%,100%{opacity:.1}50%{opacity:.25}}
        @keyframes lf-beam{0%,100%{opacity:.4}25%{opacity:.85}50%{opacity:.3}75%{opacity:.7}}
        @keyframes lf-spark{0%,100%{r:0.2;opacity:0}50%{r:0.8;opacity:.7}}
        .lf-gh{animation:lf-grid 5s ease-in-out infinite}
        .lf-gv{animation:lf-grid 6s ease-in-out infinite}
        .lf-beam{animation:lf-beam var(--dur) ease-in-out var(--del) infinite}
        .lf-spark{animation:lf-spark var(--dur) ease-in-out var(--del) infinite}
      `}</style>
      <svg viewBox="0 0 100 100" preserveAspectRatio="none" className="w-full h-full">
        <defs>
          {beams.map((b, i) => (
            <linearGradient key={`lg${i}`} id={`laser-grad-${i}`} x1="0%" y1="0%" x2="100%" y2="0%">
              <stop offset="0%" stopColor={b.c} stopOpacity="0" />
              <stop offset="40%" stopColor={b.c} stopOpacity="0.8" />
              <stop offset="60%" stopColor={b.c} stopOpacity="0.8" />
              <stop offset="100%" stopColor={b.c} stopOpacity="0" />
            </linearGradient>
          ))}
          <filter id="laser-glow">
            <feGaussianBlur stdDeviation="1.5" result="blur" />
            <feMerge><feMergeNode in="blur" /><feMergeNode in="SourceGraphic" /></feMerge>
          </filter>
        </defs>
        <g opacity="0.3">
          {[20, 40, 60, 80].map((y, i) => (
            <line key={`gh${i}`} x1="0" y1={y} x2="100" y2={y} stroke="#8aad7a15" strokeWidth="0.15" className="lf-gh" style={{ animationDelay: `${i * 0.6}s` }} />
          ))}
          {[20, 40, 60, 80].map((x, i) => (
            <line key={`gv${i}`} x1={x} y1="0" x2={50 + (x - 50) * 0.3} y2="100" stroke="#8aad7a10" strokeWidth="0.15" className="lf-gv" style={{ animationDelay: `${i * 0.8}s` }} />
          ))}
        </g>
        <g filter="url(#laser-glow)">
          {beams.map((b, i) => (
            <line key={`beam${i}`} x1={b.x1} y1={b.y1} x2={b.x2} y2={b.y2} stroke={`url(#laser-grad-${i})`} strokeWidth={b.w} className="lf-beam" style={{ '--dur': `${b.dur}s`, '--del': `${b.delay}s` } as React.CSSProperties} />
          ))}
        </g>
        {[
          { cx: 35, cy: 40, c: '#8aad7a', dur: 3, del: 1 },
          { cx: 60, cy: 55, c: '#7ab8b8', dur: 3.5, del: 2.5 },
          { cx: 45, cy: 30, c: '#9a86b5', dur: 4, del: 4 },
        ].map((s, i) => (
          <circle key={`spark${i}`} cx={s.cx} cy={s.cy} r="0.4" fill={s.c} className="lf-spark" style={{ '--dur': `${s.dur}s`, '--del': `${s.del}s` } as React.CSSProperties} />
        ))}
      </svg>
      <div className="absolute inset-0" style={{ background: 'radial-gradient(ellipse 80% 60% at 50% 60%, rgba(216,199,163,0.025), transparent)' }} />
    </div>
  );
}

function InventoryStation({ game, escalation, onBack, onRefresh, showNotification, triggerAdminFlash }: Props) {
  const [stashTab, setStashTab] = useState<StashTab>('stockpile');
  const [selectedRes, setSelectedRes] = useState<string | null>(null);
  const [showTargets, setShowTargets] = useState(false);
  const [administering, setAdministering] = useState(false);
  const [scanRotation, setScanRotation] = useState(0);
  const [adminReaction, setAdminReaction] = useState<{ npcName: string; substance: string } | null>(null);
  const [handoverTarget, setHandoverTarget] = useState<{ npcId: string; npcName: string; substance: string; npcKey?: string } | null>(null);
  // prepTarget removed — handover v6 is direct drag (no prep step)
  const [tradeOpen, setTradeOpen] = useState(false);
  const resources = game?.resources ?? [];

  const getQuantity = (type: string) => resources?.find?.((r) => r?.type === type)?.quantity ?? 0;
  const totalItems = resources.reduce((sum, r) => sum + (r?.quantity ?? 0), 0);

  // v5.0 — stash jingle removed per UX pass

  // Slow rotation for hologram — v5.0: 100ms interval (was 50ms)
  useEffect(() => {
    if (!selectedRes) return;
    const interval = setInterval(() => {
      setScanRotation(prev => (prev + 1) % 360);
    }, 100);
    return () => clearInterval(interval);
  }, [selectedRes]);

  const administerToNpc = async (npcId: string, substance: string) => {
    try {
      const sessionRes = resources?.find?.((r) => r?.type === substance);
      if (!sessionRes || (sessionRes?.quantity ?? 0) <= 0) {
        showNotification(`No ${substance} in stock. Go get some.`);
        return;
      }
      setAdministering(true);
      triggerAdminFlash(npcId);
      audioManager.playSFX('confirm');

      await fetch('/api/game/resources', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ sessionId: game?.sessionId, type: substance, change: -1 }),
      });
      await fetch('/api/game/tolerance', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ npcId, substance }),
      });

      // Show NPC reaction
      const npcObj = (game?.npcs ?? []).find((n) => n?.id === npcId);
      setAdminReaction({ npcName: npcObj?.name ?? 'NPC', substance });
      setTimeout(() => setAdminReaction(null), 2500);

      showNotification(`Administered ${substance}. They needed that. You tell yourself.`);
      await onRefresh();
    } catch (err: unknown) {
      console.error('Administer error:', err);
      showNotification('Something went wrong. Classic.');
    } finally {
      setAdministering(false);
    }
  };

  const recruitedNpcs = (game?.npcs ?? [])?.filter?.((n) => n?.recruited) ?? [];

  return (
    <div className="w-full h-full flex flex-col bg-[#0e0e0c]" style={{ ['--pop' as any]: 'var(--pop-stash)', ['--pop-rgb' as any]: 'var(--pop-stash-rgb)' }}>
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-3 bg-[#0e0d0b] border-b border-[#7ab8b8]/10 grimy-panel fluorescent-buzz">
        <div className="flex items-center gap-3">
          <button onClick={() => { audioManager.playSFX('nav'); onBack(); }} aria-label="Go back to hub" className="text-[#7ab8b8] hover:text-[#7ab8b8]/80 cursor-pointer active:scale-90 transition focus:outline-none min-w-[44px] min-h-[44px] flex items-center justify-center">
            <ArrowLeft size={20} />
          </button>
          <h2 className="font-terminal text-lg neon-text-cyan">THE STASH</h2>
        </div>
        <div className="flex items-center gap-3 text-[10px] font-terminal">
          {stashTab === 'stockpile' && (
            <button
              onClick={() => { audioManager.playSFX('nav'); setTradeOpen(true); }}
              className="px-2 py-1 font-terminal text-[9px] tracking-[0.15em] text-[#7ab8b8]/60 hover:text-[#7ab8b8] border border-[#7ab8b8]/15 hover:border-[#7ab8b8]/30 transition-all"
              aria-label="Open trading panel"
            >
              TRADE
            </button>
          )}
          <span className="text-[#4a4a3a]">{totalItems}/{MAX_RESOURCE}</span>
          {totalItems >= MAX_RESOURCE && <span className="text-[#a8687e] animate-pulse">FULL</span>}
        </div>
      </div>

      {/* ── STASH TAB BAR ── */}
      <div className="flex bg-[#0b0a08] border-b border-[#7ab8b8]/8">
        {([
          { key: 'stockpile' as const, label: 'STOCKPILE', icon: Package, color: '#7ab8b8' },
          { key: 'substances' as const, label: 'SUBSTANCES', icon: Pill, color: '#a8687e' },
        ] as const).map((t) => {
          const active = stashTab === t.key;
          const TIcon = t.icon;
          return (
            <button
              key={t.key}
              onClick={() => { audioManager.playSFX('nav'); setStashTab(t.key); }}
              className="flex-1 py-2 font-terminal text-[10px] tracking-widest transition-all flex items-center justify-center gap-1.5"
              style={{
                borderBottom: `2px solid ${active ? t.color : 'transparent'}`,
                color: active ? t.color : '#4a4a3a',
                background: active ? `${t.color}06` : 'transparent',
              }}
            >
              <TIcon size={11} />
              {t.label}
            </button>
          );
        })}
      </div>

      {/* ── SUBSTANCES TAB: embedded Dose Console ── */}
      {stashTab === 'substances' && (
        <DoseStation
          game={game}
          escalation={escalation}
          onRefresh={onRefresh}
          showNotification={showNotification}
          embedded
        />
      )}

      {/* ── STOCKPILE TAB: original stash content ── */}
      {stashTab === 'stockpile' && <div className="flex-1 flex flex-col lg:flex-row overflow-hidden">
        {/* Left: Shelves */}
        <div className="flex-1 overflow-auto p-4 relative" style={{
          background: 'linear-gradient(180deg, #0d0d0a 0%, #0a0908 50%, #080808 100%)',
        }}>
          {/* Laser field — behind the counter atmosphere */}
          <LaserField escalation={escalation?.level ?? 0} />

          {/* Back wall texture */}
          <div className="max-w-2xl mx-auto relative z-10">
            {/* Shelf label */}
            <div className="text-center mb-4">
              <span className="font-terminal text-[10px] text-[#4a4a3a] tracking-[0.3em]">BEHIND THE COUNTER</span>
            </div>

            {/* Shelf grid — 2x2 */}
            <div className="grid grid-cols-2 gap-3">
              {Object.entries(RESOURCE_CONFIG).map(([type, cfg]) => {
                const qty = getQuantity(type);
                const isSelected = selectedRes === type;
                const fillPct = Math.min(100, (qty / MAX_RESOURCE) * 100);

                return (
                  <motion.button
                    key={type}
                    whileTap={{ scale: 0.98 }}
                    onClick={() => {
                      audioManager.playSFX('nav');
                      setSelectedRes(isSelected ? null : type);
                      setShowTargets(false);
                    }}
                    className="relative overflow-hidden text-left transition-all"
                    style={{
                      background: '#0c0c0a',
                      border: `1px solid ${isSelected ? cfg.color : 'rgba(216,199,163,0.07)'}`,
                      boxShadow: isSelected ? `0 0 15px ${cfg.color}15, inset 0 0 20px ${cfg.color}05` : 'inset 0 2px 10px rgba(0,0,0,0.3)',
                    }}
                  >
                    {/* Shelf surface */}
                    <div className="p-4 relative">
                      {/* Fill level indicator — bottom bar like a liquid level */}
                      <div className="absolute bottom-0 left-0 right-0 h-1 bg-[#1a1a10]">
                        <motion.div
                          animate={{ width: `${fillPct}%` }}
                          className="h-full"
                          style={{ backgroundColor: `${cfg.color}40` }}
                        />
                      </div>

                      {/* Top row: icon + shelf label */}
                      <div className="flex items-start justify-between mb-3">
                        <div>
                          <div className="mb-1" style={{ color: cfg.color }}>
                            {(() => {
                              const Icon = RESOURCE_ICON_MAP[type as ResourceKey];
                              return Icon ? <Icon size={26} color={cfg.color} /> : null;
                            })()}
                          </div>
                          <div className="font-terminal text-[10px] tracking-wider" style={{ color: `${cfg.color}60` }}>
                            {cfg.shelfLabel}
                          </div>
                        </div>
                        {/* LED quantity */}
                        <div className="text-right">
                          <div className="font-terminal text-2xl led-counter" style={{ color: cfg.color }}>
                            {qty}
                          </div>
                          <div className="font-terminal text-[8px]" style={{ color: `${cfg.color}40` }}>
                            /{MAX_RESOURCE}
                          </div>
                        </div>
                      </div>

                      {/* Rarity tag */}
                      <div className="font-typewriter text-[8px]" style={{ color: `${cfg.color}30` }}>
                        {cfg.rarity} • RATE: {cfg.rate}
                      </div>

                      {/* Grime */}
                      <div className="absolute top-0 right-0 w-6 h-6 opacity-5" style={{
                        background: `radial-gradient(circle, ${cfg.color}, transparent)`,
                      }} />
                    </div>
                  </motion.button>
                );
              })}
            </div>

            {/* Crew tolerance overview — compact */}
            {recruitedNpcs.length > 0 && (
              <div className="mt-4 grimy-panel p-3">
                <h3 className="font-terminal text-[10px] text-[#8aad7a]/30 mb-2 tracking-wider">CREW TOLERANCE</h3>
                <div className="space-y-2">
                  {recruitedNpcs.map((npc) => (
                    <div key={npc?.id} className="flex items-center gap-3 text-[10px]">
                      <span className="text-[#E8E8E8]/50 font-terminal w-16 truncate">{npc?.name}</span>
                      <div className="flex gap-2 flex-1">
                        {[
                          { val: npc?.toleranceCigs ?? 0, c: '#8aad7a' },
                          { val: npc?.toleranceAlc ?? 0, c: '#7ab8b8' },
                          { val: npc?.toleranceWeed ?? 0, c: '#9a86b5' },
                          { val: npc?.toleranceCryst ?? 0, c: '#a8687e' },
                        ].map((t, i) => (
                          <span key={i} className="led-counter text-[9px]" style={{
                            color: t.val > 5 ? '#a8687e' : t.val > 3 ? '#FFFF00' : t.c,
                          }}>
                            {t.val.toFixed?.(1) ?? '0.0'}
                          </span>
                        ))}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Right: Holographic projection panel */}
        <AnimatePresence>
          {selectedRes && RESOURCE_CONFIG[selectedRes] && (
            <motion.div
              initial={{ opacity: 0, x: 50 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: 50 }}
              transition={{ type: 'spring', damping: 25, stiffness: 250 }}
              className="w-full lg:w-80 border-t lg:border-t-0 lg:border-l flex flex-col"
              style={{
                borderColor: `${RESOURCE_CONFIG[selectedRes].color}15`,
                background: 'linear-gradient(135deg, #060606 0%, #0a0a08 50%, #060606 100%)',
              }}
            >
              {/* Scan header — DELUSION PROJECTOR status bar */}
              <div className="px-4 py-3 border-b flex items-center justify-between relative overflow-hidden" style={{ borderColor: `${RESOURCE_CONFIG[selectedRes].color}12` }}>
                {/* Animated scan bar behind text */}
                <motion.div
                  className="absolute inset-0 pointer-events-none"
                  style={{ background: `linear-gradient(90deg, transparent, ${RESOURCE_CONFIG[selectedRes].color}06, transparent)` }}
                  animate={{ x: ['-100%', '100%'] }}
                  transition={{ duration: 3, repeat: Infinity, ease: 'linear' }}
                />
                <div className="flex items-center gap-2 relative z-10">
                  <motion.div
                    animate={{ opacity: [0.3, 1, 0.3], scale: [0.8, 1.2, 0.8] }}
                    transition={{ duration: 1.2, repeat: Infinity }}
                    className="w-2 h-2 rounded-full"
                    style={{ backgroundColor: RESOURCE_CONFIG[selectedRes].color, boxShadow: `0 0 6px ${RESOURCE_CONFIG[selectedRes].color}` }}
                  />
                  <span className="font-bmf-mono text-[10px] tracking-[0.25em]" style={{ color: RESOURCE_CONFIG[selectedRes].color }}>
                    HOLO-SCAN ACTIVE
                  </span>
                </div>
                <div className="flex items-center gap-3 relative z-10">
                  <motion.span
                    className="font-bmf-mono text-[8px] tracking-[0.15em]"
                    style={{ color: `${RESOURCE_CONFIG[selectedRes].color}40` }}
                    animate={{ opacity: [0.3, 0.6, 0.3] }}
                    transition={{ duration: 2, repeat: Infinity }}
                  >
                    {Math.floor(scanRotation)}°
                  </motion.span>
                  <button
                    onClick={() => { setSelectedRes(null); setShowTargets(false); }}
                    className="text-[#4a4a3a] hover:text-[#8aad7a] text-xs font-terminal transition-colors"
                  >✕</button>
                </div>
              </div>

              {/* Hologram display — v2.0 DELUSION PROJECTOR */}
              <div className="flex-1 flex flex-col items-center justify-center p-4 relative overflow-hidden">
                {/* CRT scanline sweep — dual direction */}
                <motion.div
                  animate={{ y: ['-100%', '300%'] }}
                  transition={{ duration: 3.5, repeat: Infinity, ease: 'linear' }}
                  className="absolute inset-x-0 h-[2px] z-10 pointer-events-none"
                  style={{
                    background: `linear-gradient(90deg, transparent, ${RESOURCE_CONFIG[selectedRes].color}25, transparent)`,
                  }}
                />
                <motion.div
                  animate={{ y: ['300%', '-100%'] }}
                  transition={{ duration: 5, repeat: Infinity, ease: 'linear', delay: 1.5 }}
                  className="absolute inset-x-0 h-px z-10 pointer-events-none"
                  style={{ backgroundColor: `${RESOURCE_CONFIG[selectedRes].color}10` }}
                />

                {/* CRT horizontal interference lines */}
                <div className="absolute inset-0 pointer-events-none z-10" style={{
                  backgroundImage: `repeating-linear-gradient(0deg, transparent, transparent 3px, ${RESOURCE_CONFIG[selectedRes].color}03 3px, ${RESOURCE_CONFIG[selectedRes].color}03 4px)`,
                }} />

                {/* Hologram container with data orbit */}
                <div className="relative w-48 h-48 mb-2">
                  {/* Orbiting data fragments */}
                  <HologramDataOrbit
                    fragments={HOLOGRAM_DATA_FRAGMENTS[selectedRes] ?? []}
                    color={RESOURCE_CONFIG[selectedRes].color}
                  />

                  {/* Rotating wireframe */}
                  <motion.div
                    className="w-full h-full"
                    style={{ transform: `rotateY(${scanRotation}deg)`, perspective: '600px' }}
                    whileHover={{ scale: 1.08 }}
                    transition={{ type: 'spring', stiffness: 300 }}
                  >
                    <HologramShape type={selectedRes} color={RESOURCE_CONFIG[selectedRes].color} escalation={escalation?.level ?? 0} />
                  </motion.div>
                </div>

                {/* Hologram pedestal */}
                <HologramPedestal color={RESOURCE_CONFIG[selectedRes].color} />

                {/* Item name — with flicker */}
                <motion.h3
                  className="font-terminal text-lg mb-0.5 mt-2"
                  style={{ color: RESOURCE_CONFIG[selectedRes].color }}
                  animate={escalation?.level >= 5 ? {
                    x: [0, -1, 2, -1, 0],
                    opacity: [1, 0.7, 1, 0.8, 1],
                  } : {}}
                  transition={{ duration: 0.3, repeat: Infinity, repeatDelay: 3 + Math.random() * 5 }}
                >
                  {RESOURCE_CONFIG[selectedRes].label}
                </motion.h3>

                {/* Substance classification badge */}
                <motion.div
                  className="font-bmf-mono text-[8px] tracking-[0.25em] px-3 py-1 mb-3 rounded-sm"
                  style={{
                    border: `1px solid ${RESOURCE_CONFIG[selectedRes].color}25`,
                    color: `${RESOURCE_CONFIG[selectedRes].color}60`,
                    backgroundColor: `${RESOURCE_CONFIG[selectedRes].color}06`,
                  }}
                  animate={{ opacity: [0.5, 0.8, 0.5] }}
                  transition={{ duration: 3, repeat: Infinity }}
                >
                  {RESOURCE_CONFIG[selectedRes].rarity.toUpperCase()} GRADE • RATE {RESOURCE_CONFIG[selectedRes].rate}
                </motion.div>

                {/* Stats readout — enhanced with animated bars */}
                <div className="w-full space-y-2.5 text-xs font-terminal">
                  {/* Stock meter */}
                  <div>
                    <div className="flex justify-between mb-1" style={{ color: `${RESOURCE_CONFIG[selectedRes].color}80` }}>
                      <span className="text-[9px] tracking-wider">STOCK LEVEL</span>
                      <span className="led-counter text-sm" style={{ color: RESOURCE_CONFIG[selectedRes].color }}>
                        {getQuantity(selectedRes)}
                      </span>
                    </div>
                    <div className="h-[6px] bg-[rgba(255,255,255,0.04)] rounded-sm overflow-hidden">
                      <motion.div
                        className="h-full rounded-sm"
                        animate={{ width: `${(getQuantity(selectedRes) / MAX_RESOURCE) * 100}%` }}
                        transition={{ type: 'spring', damping: 20 }}
                        style={{
                          backgroundColor: RESOURCE_CONFIG[selectedRes].color,
                          opacity: 0.7,
                          boxShadow: `0 0 8px ${RESOURCE_CONFIG[selectedRes].color}40`,
                        }}
                      />
                    </div>
                  </div>

                  {/* Tolerance rate */}
                  <div className="flex justify-between" style={{ color: `${RESOURCE_CONFIG[selectedRes].color}50` }}>
                    <span className="text-[9px] tracking-wider">ADDICTION FACTOR</span>
                    <div className="flex items-center gap-1">
                      {[...Array(5)].map((_, i) => (
                        <motion.div key={i} className="w-1.5 h-1.5 rounded-full"
                          style={{
                            backgroundColor: i < Math.ceil(RESOURCE_CONFIG[selectedRes].rate * 5)
                              ? RESOURCE_CONFIG[selectedRes].color
                              : `${RESOURCE_CONFIG[selectedRes].color}15`,
                          }}
                          animate={i < Math.ceil(RESOURCE_CONFIG[selectedRes].rate * 5) ? { opacity: [0.5, 1, 0.5] } : {}}
                          transition={{ duration: 1.5, repeat: Infinity, delay: i * 0.2 }}
                        />
                      ))}
                    </div>
                  </div>

                  {/* Heat signature */}
                  <div className="flex justify-between" style={{ color: `${RESOURCE_CONFIG[selectedRes].color}50` }}>
                    <span className="text-[9px] tracking-wider">HEAT SIGNATURE</span>
                    <span className="text-[9px]" style={{
                      color: RESOURCE_CONFIG[selectedRes].rate >= 0.5 ? '#ff5e57' : RESOURCE_CONFIG[selectedRes].rate >= 0.3 ? '#ffb25f' : '#8aad7a',
                    }}>
                      {RESOURCE_CONFIG[selectedRes].rate >= 0.5 ? 'EXTREME' : RESOURCE_CONFIG[selectedRes].rate >= 0.3 ? 'MODERATE' : 'LOW'}
                    </span>
                  </div>
                </div>

                {/* Description — typewriter style */}
                <p className="text-[9px] text-[#4a4a3a] font-typewriter mt-3 text-center leading-relaxed italic">
                  &ldquo;{RESOURCE_CONFIG[selectedRes].desc}&rdquo;
                </p>

                {/* Grid lines background — perspective grid */}
                <div className="absolute inset-0 pointer-events-none opacity-[0.03]" style={{
                  backgroundImage: `
                    linear-gradient(${RESOURCE_CONFIG[selectedRes].color}40 1px, transparent 1px),
                    linear-gradient(90deg, ${RESOURCE_CONFIG[selectedRes].color}40 1px, transparent 1px)
                  `,
                  backgroundSize: '20px 20px',
                  perspective: '500px',
                  transform: 'rotateX(30deg)',
                  transformOrigin: 'bottom center',
                }} />

                {/* Corner registration marks */}
                {['top-2 left-2', 'top-2 right-2', 'bottom-2 left-2', 'bottom-2 right-2'].map((pos, i) => (
                  <div key={i} className={`absolute ${pos} pointer-events-none`}>
                    <svg width="12" height="12" viewBox="0 0 12 12">
                      <line x1={i % 2 === 0 ? 0 : 12} y1={i < 2 ? 0 : 12} x2={i % 2 === 0 ? 6 : 6} y2={i < 2 ? 0 : 12}
                        stroke={`${RESOURCE_CONFIG[selectedRes].color}30`} strokeWidth="0.5" />
                      <line x1={i % 2 === 0 ? 0 : 12} y1={i < 2 ? 0 : 12} x2={i % 2 === 0 ? 0 : 12} y2={i < 2 ? 6 : 6}
                        stroke={`${RESOURCE_CONFIG[selectedRes].color}30`} strokeWidth="0.5" />
                    </svg>
                  </div>
                ))}
              </div>

              {/* Administer section */}
              {recruitedNpcs.length > 0 && (
                <div className="px-4 pb-4">
                  <button
                    onClick={() => setShowTargets(!showTargets)}
                    className="w-full text-[10px] px-3 py-2 border font-terminal transition-all flex items-center justify-center gap-1"
                    style={{
                      borderColor: `${RESOURCE_CONFIG[selectedRes].color}30`,
                      color: RESOURCE_CONFIG[selectedRes].color,
                    }}
                  >
                    <AlertTriangle size={10} />
                    {showTargets ? 'HIDE TARGETS' : 'ADMINISTER TO CREW'}
                  </button>

                  <AnimatePresence>
                    {showTargets && (
                      <motion.div
                        initial={{ height: 0, opacity: 0 }}
                        animate={{ height: 'auto', opacity: 1 }}
                        exit={{ height: 0, opacity: 0 }}
                        className="overflow-hidden"
                      >
                        <div className="flex gap-2 flex-wrap mt-2">
                          {recruitedNpcs.map((npc) => (
                            <button
                              key={npc?.id}
                              disabled={administering || getQuantity(selectedRes) <= 0}
                              onClick={() => {
                                audioManager.playSFX('nav');
                                // Derive NPC key for preference lookup
                                const nKey = Object.keys(NPC_DATA).find(k => NPC_DATA[k as NPCKey]?.name === npc?.name) as NPCKey | undefined;
                                // Go straight to handover drag
                                setHandoverTarget({
                                  npcId: npc?.id,
                                  npcName: npc?.name ?? 'NPC',
                                  substance: selectedRes!,
                                  npcKey: nKey,
                                });
                              }}
                              className="text-[10px] px-3 py-1.5 border border-[#8aad7a]/15 text-[#E8E8E8]/50 hover:border-[#8aad7a]/40 hover:text-[#8aad7a] transition font-terminal disabled:opacity-30 sticky-residue"
                            >
                              {npc?.name ?? 'NPC'}
                            </button>
                          ))}
                        </div>
                      </motion.div>
                    )}
                  </AnimatePresence>
                </div>
              )}
            </motion.div>
          )}
        </AnimatePresence>
      </div>}

      {/* Vice Handover overlay — atmospheric drag */}
      <ViceHandover
        substance={(handoverTarget?.substance ?? 'cigarettes') as 'cigarettes' | 'alcohol' | 'weed' | 'crystals'}
        recipientName={handoverTarget?.npcName ?? ''}
        visible={!!handoverTarget}
        mode="maintenance"
