import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { NPC_DATA, NPCKey, ResourceKey } from '@/lib/game-data';
import { isValidId, validateResourceType } from '@/lib/api-guards';

// POST: supply a vice (gift a resource) to an NPC.
// Looks up NPC vice preferences, decrements resource, updates affinity, returns response copy.
export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const { sessionId, npcId, npcKey } = body ?? {};
    const resourceType = validateResourceType(body?.resourceType);
    if (!isValidId(sessionId) || !isValidId(npcId) || !npcKey || !resourceType) {
      return NextResponse.json({ error: 'Missing params' }, { status: 400 });
    }

    // Look up NPC vice profile
    const npcData = NPC_DATA[npcKey as NPCKey];
    if (!npcData?.vice) {
      return NextResponse.json({ error: 'NPC has no vice profile' }, { status: 400 });
    }
    const preference = npcData.vice.preferences[resourceType as ResourceKey];
    if (preference === undefined) {
      return NextResponse.json({ error: 'Invalid resource type' }, { status: 400 });
    }

    // Verify NPC belongs to this session
    const npcRecord = await prisma.nPC.findUnique({ where: { id: npcId }, select: { sessionId: true } });
    if (!npcRecord || npcRecord.sessionId !== sessionId) {
      return NextResponse.json({ error: 'NPC does not belong to this session' }, { status: 403 });
    }

    // Check resource availability
    const resource = await prisma.resource.findUnique({
      where: { sessionId_type: { sessionId, type: resourceType } },
    });
    if (!resource || resource.quantity < 1) {
      return NextResponse.json({ error: 'Out of stock' }, { status: 400 });
    }

    // Map preference (-2..+2) to affinity delta
    const deltaMap: Record<number, number> = { 2: 20, 1: 10, 0: 2, [-1]: -10, [-2]: -20 };
    const affinityDelta = deltaMap[preference] ?? 0;

    // Decrement resource
    const updatedResource = await prisma.resource.update({
      where: { sessionId_type: { sessionId, type: resourceType } },
      data: { quantity: resource.quantity - 1 },
    });

    // Update NPC affinity (clamp 0..100)
    const npc = await prisma.nPC.findUnique({ where: { id: npcId } });
    const newAffinity = Math.max(0, Math.min(100, (npc?.affinity ?? 0) + affinityDelta));
    const updatedNpc = await prisma.nPC.update({
      where: { id: npcId },
      data: { affinity: newAffinity },
    });

    return NextResponse.json({
      preference,
      affinityDelta,
      newAffinity,
      giftResponse: npcData.vice.giftResponses[resourceType as ResourceKey],
      remainingResource: updatedResource.quantity,
      resourceType,
    });
  } catch (err: unknown) {
    console.error('Supply error:', err);
    return NextResponse.json({ error: 'Failed' }, { status: 500 });
  }
}

