import { deleteFile } from '@/lib/s3'

export const dynamic = 'force-dynamic'

const STR_FIELDS = ['title', 'subtitle', 'description', 'deepDive', 'launchLink'] as const

export async function PATCH(req: Request, { params }: { params: Promise<{ id: string }> }) {
  if (!(await requireAdmin())) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  const { id } = await params
  const body = await req.json().catch(() => ({}))
  const data: Record<string, unknown> = {}
  for (const f of STR_FIELDS) if (typeof body?.[f] === 'string') data[f] = body[f]
  if (typeof data.launchLink === 'string') {
    const link = (data.launchLink as string).trim() || '#'
    if (link !== '#' && !/^https?:\/\//i.test(link) && !link.startsWith('/')) {
      return NextResponse.json({ error: 'Link must start with https://, http://, / or be #' }, { status: 400 })
    }
    data.launchLink = link
  }
  if (body?.format === 'game' || body?.format === 'app') data.format = body.format
  if (body?.linkTarget === 'new_tab' || body?.linkTarget === 'same_tab') data.linkTarget = body.linkTarget
  if (body?.status === 'active' || body?.status === 'coming_soon') data.status = body.status
  if (typeof body?.featured === 'boolean') data.featured = body.featured
  if (typeof body?.visible === 'boolean') data.visible = body.visible
  if (typeof body?.locked === 'boolean') data.locked = body.locked
  if ('imagePath' in (body ?? {})) {
    data.imagePath = typeof body.imagePath === 'string' ? body.imagePath : null
    data.imageIsPublic = true
  }
  try {
    const game = await prisma.game.update({ where: { id }, data })
    return NextResponse.json({ game })
  } catch (e) {
    console.error('game update failed', e)
    return NextResponse.json({ error: 'Update failed' }, { status: 500 })
  }
}

export async function DELETE(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  if (!(await requireAdmin())) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  const { id } = await params
  try {
    const game = await prisma.game.delete({ where: { id } })
    if (game.imagePath && !game.imagePath.startsWith('/')) await deleteFile(game.imagePath).catch((e) => console.error('image delete failed', e))
    return NextResponse.json({ ok: true })
  } catch (e) {
    console.error('game delete failed', e)
    return NextResponse.json({ error: 'Delete failed' }, { status: 500 })
  }
}

