import { useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X } from 'lucide-react';
import { MEMO_POOL } from '@/lib/game-data';
import { playPaperCrinkle } from '@/lib/sound-effects';

interface Props {
  /** Incrementing key — change this to trigger a new memo. Usually the day number. */
  triggerKey: number;
  /** Name of the addressee on the slip */
  addressee?: string;
}

/**
 * MemoReveal — a paper slip flutters in at the start of each day with a
 * satirical one-liner from "HQ". Deterministic selection by triggerKey so
 * replays read the same memo for the same day.
 *
 * Triggered once per unique triggerKey value. Dismiss on click, auto-fade
 * after 7.5s.
 */
export default function MemoReveal({ triggerKey, addressee = 'YOU' }: Props) {
  const [visible, setVisible] = useState(false);
  const [memo, setMemo] = useState<string>('');
  const [lastShown, setLastShown] = useState<number | null>(null);

  useEffect(() => {
    if (triggerKey === lastShown || triggerKey < 1) return;
    // Deterministic pick
    const idx = triggerKey % MEMO_POOL.length;
    setMemo(MEMO_POOL[idx]);
    setLastShown(triggerKey);
    // Short delay so it lands AFTER the hub has mounted
    const showTimer = setTimeout(() => {
      setVisible(true);
      try { playPaperCrinkle(); } catch { /* ignore */ }
    }, 650);
    const hideTimer = setTimeout(() => setVisible(false), 7500 + 650);
    return () => {
      clearTimeout(showTimer);
      clearTimeout(hideTimer);
    };
  }, [triggerKey, lastShown]);

  const dismiss = () => setVisible(false);

  return (
    <AnimatePresence>
      {visible && memo && (
        <motion.div
          initial={{ opacity: 0, x: -400, y: -80, rotate: -25 }}
          animate={{ opacity: 1, x: 0, y: 0, rotate: -4 }}
          exit={{ opacity: 0, y: 60, rotate: 8 }}
          transition={{
            type: 'spring',
            stiffness: 55,
            damping: 14,
            duration: 1.2,
          }}
          className="fixed bottom-16 left-4 sm:left-8 z-[9998] max-w-[280px] sm:max-w-[320px]"
        >
          <button
            onClick={dismiss}
            aria-label="Dismiss memo"
            className="relative block w-full text-left cursor-pointer focus:outline-none focus-visible:ring-1 focus-visible:ring-[#8B7320]"
          >
            {/* Paper */}
            <div
              className="relative px-4 py-3 pr-7 font-typewriter text-[11px] leading-relaxed text-[#3a2e1c]"
              style={{
                background: 'linear-gradient(180deg, #d4c290 0%, #c4b58a 55%, #b5a678 100%)',
                boxShadow:
                  '0 1px 0 rgba(255,255,255,0.25) inset, 0 -1px 0 rgba(0,0,0,0.18) inset, 0 6px 16px rgba(0,0,0,0.55), 0 2px 4px rgba(0,0,0,0.35)',
                borderTop: '1px solid rgba(139,115,32,0.25)',
                borderLeft: '1px solid rgba(139,115,32,0.15)',
              }}
            >
              {/* Coffee stain */}
              <span
                className="absolute pointer-events-none rounded-full"
                style={{
                  right: 6,
                  bottom: 6,
                  width: 22,
                  height: 22,
                  background: 'radial-gradient(circle, rgba(100,60,30,0.25) 40%, rgba(100,60,30,0) 70%)',
                  transform: 'rotate(14deg)',
                }}
              />
              {/* Stamp header */}
              <div className="font-terminal text-[9px] tracking-[0.3em] text-[#8B0000] mb-1 flex items-center gap-2">
                <span>FROM THE MANAGER</span>
                <span className="text-[#3a2e1c]/40">///</span>
                <span>BAF3K</span>
              </div>
              <div className="text-[9px] text-[#3a2e1c]/65 mb-1.5">
                TO: {addressee}
              </div>
              <p className="text-[11px]">{memo}</p>
              <div className="mt-2 text-[9px] text-[#3a2e1c]/60">
                — M
              </div>
              <span className="absolute top-1 right-1 p-1 text-[#3a2e1c]/50 hover:text-[#3a2e1c] transition-colors">
                <X size={12} />
              </span>
            </div>
          </button>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

import { NextResponse } from 'next/server'
import { requireAdmin } from '@/auth'
import { generatePresignedUploadUrl } from '@/lib/s3'

export const dynamic = 'force-dynamic'

export async function POST(req: Request) {
  if (!(await requireAdmin())) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  const body = await req.json().catch(() => ({}))
  const fileName = String(body?.fileName ?? '')
  const contentType = String(body?.contentType ?? '')
  if (!fileName || !contentType.startsWith('image/')) {
    return NextResponse.json({ error: 'Image file required' }, { status: 400 })
  }
  try {
    const result = await generatePresignedUploadUrl(fileName, contentType, true)
    return NextResponse.json(result)
  } catch (e) {
    console.error('presign failed', e)
    return NextResponse.json({ error: 'Upload URL failed' }, { status: 500 })
  }
}

