const screenButtons = Array.from(document.querySelectorAll('[data-screen]'));
const screens = Array.from(document.querySelectorAll('.screen'));
const currentTitle = document.querySelector('[data-testid="text-current-screen"]');
const themeToggle = document.querySelector('[data-theme-toggle]');
const themeLabel = document.querySelector('[data-theme-label]');
const notesDialog = document.querySelector('[data-notes-dialog]');

function setScreen(screenId) {
  screenButtons.forEach((button) => {
    button.classList.toggle('is-active', button.dataset.screen === screenId);
  });

  screens.forEach((screen) => {
    const active = screen.id === `screen-${screenId}`;
    screen.classList.toggle('is-visible', active);
    if (active && currentTitle) currentTitle.textContent = screen.dataset.title;
  });

  if (window.matchMedia('(max-width: 980px)').matches) {
    document.querySelector('.stage')?.scrollIntoView({ block: 'start' });
  } else {
    window.scrollTo(0, 0);
  }
}

screenButtons.forEach((button) => {
  button.addEventListener('click', () => setScreen(button.dataset.screen));
});

let theme = window.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark';
document.documentElement.setAttribute('data-theme', theme);
if (themeLabel) themeLabel.textContent = theme === 'dark' ? 'Dark HUD' : 'Paper UI';

themeToggle?.addEventListener('click', () => {
  theme = theme === 'dark' ? 'light' : 'dark';
  document.documentElement.setAttribute('data-theme', theme);
  if (themeLabel) themeLabel.textContent = theme === 'dark' ? 'Dark HUD' : 'Paper UI';
});

document.querySelector('[data-action="begin-run"]')?.addEventListener('click', () => setScreen('hud'));
document.querySelector('[data-action="show-notes"]')?.addEventListener('click', () => notesDialog?.showModal());
document.querySelector('[data-close-notes]')?.addEventListener('click', () => notesDialog?.close());
notesDialog?.addEventListener('click', (event) => {
  if (event.target === notesDialog) notesDialog.close();
});

const recruitButtons = Array.from(document.querySelectorAll('[data-recruit-step]'));
const recruitSteps = Array.from(document.querySelectorAll('.recruit-step'));

recruitButtons.forEach((button) => {
  button.addEventListener('click', () => {
    recruitButtons.forEach((item) => item.classList.toggle('is-active', item === button));
    recruitSteps.forEach((step) => {
      step.classList.toggle('is-visible', step.id === `recruit-${button.dataset.recruitStep}`);
    });
  });
});

const doseCopy = {
  under: ['Under-dose selected.', 'Likely refusal or degraded run. Pressure rises and volatility starts leaking into the scene.'],
  functional: ['Functional band selected.', 'Task accepted. Performance holds for one short route. Dependence remains in orbit.'],
  over: ['Over-dose selected.', 'Short-term control becomes waste. Absence risk and tolerance growth increase after the window closes.'],
};

document.querySelectorAll('[data-dose]').forEach((button) => {
  button.addEventListener('click', () => {
    document.querySelectorAll('[data-dose]').forEach((item) => item.classList.toggle('is-selected', item === button));
    const [title, body] = doseCopy[button.dataset.dose];
    const result = document.querySelector('[data-testid="text-dose-result"]');
    if (result) result.innerHTML = `<strong>${title}</strong>${body}`;
  });
});

document.addEventListener('keydown', (event) => {
  if (event.key === 'Escape' && notesDialog?.open) notesDialog.close();
});

