/* ── stat metadata ─────────────────────────────────────── */
const STATS = [
  {
    key: 'nerve' as const,
    label: 'NERVE',
    icon: Zap,
    color: '#FF6B35',
    desc: 'Controls heat decay speed. High nerve = longer runway before consequences.',
