    desc: 'Boosts expedition loot and movement range. Legs over lungs.',
    effectFn: (v: number) => `x${(1.0 + Math.max(0, v - 2) * 0.1).toFixed(2)} loot bonus`,
  },
] as const;

/* ── active bonus tiers derived from stat levels ───────── */
function getActiveBonuses(game: GameState): { label: string; desc: string; color: string }[] {
  const b: { label: string; desc: string; color: string }[] = [];
  const n = game.nerve;
  const i = game.insight;
  const p = game.presence;
  const m = game.mobility;

  if (n >= 4) b.push({ label: 'COLD HANDS', desc: 'Heat decays noticeably faster overnight.', color: '#FF6B35' });
  if (n >= 7) b.push({ label: 'ICE BLOOD', desc: 'Raid threshold extended. You run dangerously cool.', color: '#FF3300' });
  if (i >= 4) b.push({ label: 'KEEN EYE', desc: 'Scrounge occasionally yields bonus weed.', color: '#C49A6C' });
  if (i >= 7) b.push({ label: 'PROFILER', desc: 'Affinity gains significantly amplified.', color: '#E8C47C' });
  if (p >= 4) b.push({ label: 'THICK SKIN', desc: 'Crew tolerance builds slower.', color: '#8B4513' });
  if (p >= 7) b.push({ label: 'IRON WILL', desc: 'Near-immunity to tolerance escalation.', color: '#A0522D' });
  if (m >= 4) b.push({ label: 'LIGHT FEET', desc: 'Expedition move budget increased.', color: '#DAA520' });
  if (m >= 7) b.push({ label: 'GHOST STEP', desc: 'Loot multiplier peaks. You strip a place clean.', color: '#FFD700' });

  // Philosophy bonus
  if (game.philosophy === 'SHEPHERD') b.push({ label: 'SHEPHERD\'S CROOK', desc: 'Crew affinity decays slower. They trust you.', color: '#8aad7a' });
  if (game.philosophy === 'WARDEN') b.push({ label: 'IRON FIST', desc: 'Compliance baseline elevated. They fear you.', color: '#FF4444' });
  if (game.philosophy === 'GHOST') b.push({ label: 'LOW PROFILE', desc: 'Base heat generation reduced on all actions.', color: '#8888FF' });

  return b;
}

/* ── journal entries derived from game state ────────────── */
function getJournalEntries(game: GameState): { text: string; color: string }[] {
  const j: { text: string; color: string }[] = [];
  j.push({ text: `Day ${game.day}. The Manager known as "${game.playerName}" persists.`, color: '#c8c4b8' });

  const recruited = game.npcs.filter(n => n?.recruited);
  if (recruited.length === 0) {
    j.push({ text: 'No crew recruited yet. The operation is a whisper.', color: '#8a8578' });
  } else {
    recruited.forEach(npc => {
      j.push({ text: `${npc.name} — recruited. On the books.`, color: '#c8dc96' });
    });
  }

  const completed = game.missions.filter(m => m?.status === 'COMPLETE');
  if (completed.length > 0) {
    j.push({ text: `${completed.length} mission${completed.length > 1 ? 's' : ''} completed.`, color: '#7ab8b8' });
  }
  const active = game.missions.filter(m => m?.status === 'ACTIVE');
  if (active.length > 0) {
    j.push({ text: `${active.length} directive${active.length > 1 ? 's' : ''} in play.`, color: '#CCAA00' });
  }

  if (game.heat >= 7) {
    j.push({ text: 'HEAT CRITICAL. Patrol raids imminent. Consider lying low.', color: '#FF4444' });
  } else if (game.heat >= 4) {
    j.push({ text: 'Heat rising. The patrols are getting curious.', color: '#FFB000' });
  }

  if (game.totalCoffees > 0) {
    j.push({ text: `${game.totalCoffees} lifetime coffee${game.totalCoffees > 1 ? 's' : ''} consumed via BREWMATIC 3000.`, color: '#8B4513' });
  }

  return j;
}

