1. Create the audio manager
Create file:

app/_lib/audio-manager.ts

Use this structure:

typescript
Copy
type SfxName =
  | 'nav'
  | 'confirm'
  | 'error'
  | 'hover'
  | 'paper'
  | 'safety_valve';

type RoomName = 'ops_centre_1' | 'ops_centre_2' | 'bedroom';
type MusicLayer = 'hub' | 'stash' | 'bedroom';

class AudioManager {
  private ctx: AudioContext | null = null;
  private master: GainNode | null = null;

  private music = {
    hub: null as HTMLAudioElement | null,
    stash: null as HTMLAudioElement | null,
    bedroom: null as HTMLAudioElement | null,
  };

  private roomAmbience = {
    ops_centre_1: null as HTMLAudioElement | null,
    ops_centre_2: null as HTMLAudioElement | null,
    bedroom: null as HTMLAudioElement | null,
  };

  private currentMusic: MusicLayer | null = null;
  private currentRoom: RoomName | null = null;

  pressure = 0.0;
  clarity = 1.0;

  init() {
    if (typeof window === 'undefined') return;
    if (this.ctx) return;

    this.ctx = new AudioContext();
    this.master = this.ctx.createGain();
    this.master.gain.value = 1;
    this.master.connect(this.ctx.destination);

    // MUSIC
    this.music.hub = this.makeLoop('/audio/menu-music.mp3', 0.65);
    this.music.stash = this.makeLoop('/audio/stash-jingle.mp3', 0.0);
    this.music.bedroom = this.makeLoop('/audio/menu-music.mp3', 0.0); // temporary reuse until dedicated bedroom loop exists

    // ROOM AMBIENCE
    this.roomAmbience.ops_centre_1 = this.makeLoop('/audio/ops1-ambience.mp3', 0.0);
    this.roomAmbience.ops_centre_2 = this.makeLoop('/audio/ops2-ambience.mp3', 0.0);
    this.roomAmbience.bedroom = this.makeLoop('/audio/bedroom-ambience.mp3', 0.0);
  }

  private makeLoop(src: string, volume: number) {
    const audio = new Audio(src);
    audio.loop = true;
    audio.preload = 'auto';
    audio.volume = volume;
    return audio;
  }

  async unlock() {
    if (!this.ctx) this.init();
    if (this.ctx?.state === 'suspended') {
      await this.ctx.resume();
    }

    const all = [
      ...Object.values(this.music),
      ...Object.values(this.roomAmbience),
    ].filter(Boolean) as HTMLAudioElement[];

    await Promise.all(
      all.map(async (a) => {
        try {
          await a.play();
          a.pause();
          a.currentTime = 0;
        } catch {}
      })
    );
  }

  private fade(audio: HTMLAudioElement | null, target: number, ms = 800) {
    if (!audio) return;
    const start = audio.volume;
    const delta = target - start;
    const steps = 20;
    const stepMs = ms / steps;
    let i = 0;

    const tick = () => {
      i += 1;
      audio.volume = Math.max(0, Math.min(1, start + (delta * i) / steps));
      if (i < steps) {
        window.setTimeout(tick, stepMs);
      } else if (target === 0) {
        audio.pause();
      }
    };

    if (target > 0 && audio.paused) {
      audio.play().catch(() => {});
    }

    tick();
  }

  setPressure(value: number) {
    this.pressure = Math.max(0, Math.min(1, value));
    this.clarity = 1 - this.pressure;
  }

  setRoom(room: RoomName) {
    if (this.currentRoom === room) return;
    this.currentRoom = room;

    const targets: Record<RoomName, number> = {
      ops_centre_1: 0.18,
      ops_centre_2: 0.16,
      bedroom: 0.14,
    };

    (Object.keys(this.roomAmbience) as RoomName[]).forEach((key) => {
      this.fade(this.roomAmbience[key], key === room ? targets[key] : 0, 800);
    });
  }

  playHubMusic() {
    this.currentMusic = 'hub';
    this.fade(this.music.hub, 0.65, 800);
    this.fade(this.music.stash, 0, 800);
    this.fade(this.music.bedroom, 0, 800);
  }

  playStashMusic() {
    this.currentMusic = 'stash';
    this.fade(this.music.hub, 0.2, 800);
    this.fade(this.music.stash, 0.55, 800);
    this.fade(this.music.bedroom, 0, 800);
  }

  playBedroomMusic() {
    this.currentMusic = 'bedroom';
    this.fade(this.music.hub, 0.15, 800);
    this.fade(this.music.stash, 0, 800);
    this.fade(this.music.bedroom, 0.35, 800);
  }

  restoreRoomMusic() {
    if (this.currentRoom === 'ops_centre_2') {
      this.playHubMusic();
      return;
    }
    if (this.currentRoom === 'bedroom') {
      this.playBedroomMusic();
      return;
    }
    this.playHubMusic();
  }

  playSfx(name: SfxName) {
    // route existing synth SFX here
    switch (name) {
      case 'nav':
      case 'hover':
        if ((window as any).playClick) (window as any).playClick();
        return;
      case 'confirm':
        if ((window as any).playSuccess) (window as any).playSuccess();
        return;
      case 'error':
        if ((window as any).playError) (window as any).playError();
        return;
      case 'paper':
        if ((window as any).playSuccess) (window as any).playSuccess();
        return;
      case 'safety_valve':
        if ((window as any).playError) (window as any).playError();
        return;
    }
  }

  triggerClipboardHover() {
    this.playSfx('hover');
  }

  triggerClipboardSelect() {
    this.playSfx('paper');
    window.setTimeout(() => this.playSfx('confirm'), 40);
  }

  triggerSafetyValve() {
    this.setPressure(Math.min(1, this.pressure + 0.2));
    this.playSfx('safety_valve');
  }

  stopAll() {
    [...Object.values(this.music), ...Object.values(this.roomAmbience)].forEach((a) => {
      if (!a) return;
      a.pause();
      a.currentTime = 0;
      a.volume = 0;
    });
    this.currentMusic = null;
    this.currentRoom = null;
  }
}

