'use client';

import { useRef, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Gift, X } from 'lucide-react';

import type { ResourceKey, ViceProfile } from '@/lib/game-data';
import { useFocusTrap } from '@/hooks/use-focus-trap';
import ViceHandover from '../ui/vice-handover';
import { audioManager } from '@/app/_lib/audio-manager';
import { CigaretteIcon, AlcoholIcon, WeedIcon, CrystalIcon } from '@/app/_components/icons/resource-icons';
import type { ReactNode } from 'react';

const RESOURCE_META: Record<ResourceKey, { label: string; icon: ReactNode; color: string }> = {
  cigarettes: { label: 'CIGS', icon: <CigaretteIcon size={18} color="#CCAA00" />, color: '#CCAA00' },
  alcohol: { label: 'BOOZE', icon: <AlcoholIcon size={18} color="#B87333" />, color: '#B87333' },
  weed: { label: 'WEED', icon: <WeedIcon size={18} color="#c8dc96" />, color: '#c8dc96' },
  crystals: { label: 'CRYSTAL', icon: <CrystalIcon size={18} color="#a4e2ff" />, color: '#a4e2ff' },
};

interface GiftResult {
  preference: number;
  affinityDelta: number;
  newAffinity: number;
  giftResponse: string;
  remainingResource: number;
  resourceType: ResourceKey;
}

interface Props {
  npcName: string;
  npcKey: string;
  npcId: string;
  vice: ViceProfile;
  sessionId: string;
  resources: any[]; // [{ type: 'cigarettes', quantity: 5 }, ...]
  hasObservedCravings: boolean; // after observation stage, show craving hint
  onGiftGiven: (result: GiftResult) => void;
  escalationLevel?: number;
}

const MAX_GIFTS = 3;

export default function GiftOfferPanel({
  npcName,
  npcKey,
  npcId,
  vice,
  sessionId,
  resources,
  hasObservedCravings,
  onGiftGiven,
  escalationLevel = 0,
}: Props) {
  const [open, setOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [lastResult, setLastResult] = useState<GiftResult | null>(null);
  const [giftsGiven, setGiftsGiven] = useState(0);
  const [handoverVice, setHandoverVice] = useState<ResourceKey | null>(null);
  const modalRef = useRef<HTMLDivElement>(null);
  // v0.5.0: trap focus while modal is open; ESC closes it
  useFocusTrap(modalRef, open, () => setOpen(false));
  const resourceTypes: ResourceKey[] = ['cigarettes', 'alcohol', 'weed', 'crystals'];

  const getStock = (type: ResourceKey): number => {
    const r = resources?.find?.((x: any) => x?.type === type);
    return r?.quantity ?? 0;
  };

  const canGift = giftsGiven < MAX_GIFTS;

  const handleOffer = async (type: ResourceKey) => {
    if (loading || !canGift) return;
    if (getStock(type) < 1) return;
    audioManager.playSFX('nav');
    setLoading(true);
    try {
      const res = await fetch('/api/game/supply', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ sessionId, npcId, npcKey, resourceType: type }),
      });
      if (!res.ok) throw new Error('Supply failed');
      const data: GiftResult = await res.json();
      setLastResult(data);
      setGiftsGiven((n) => n + 1);
      onGiftGiven(data);
    } catch (err) {
      console.error('Gift offer error:', err);
    } finally {
      setLoading(false);
    }
  };

  const cravingHint = hasObservedCravings && vice?.cravings?.[0]
    ? RESOURCE_META[vice.cravings[0]]?.label
    : null;

  return (
    <>
      {/* Floating trigger button (sticky, always visible) */}
      <button
        onClick={() => { audioManager.playSFX('nav'); setOpen(true); }}
        aria-label="Offer a gift (bum a fag)"
        className="fixed bottom-4 right-4 z-40 font-terminal bg-[#0a0806] border-2 border-[#B87333]/60 text-[#CCAA00] hover:bg-[#B87333]/10 hover:border-[#CCAA00] px-4 py-3 flex items-center gap-2 transition shadow-lg min-h-[48px] cursor-pointer active:scale-95"
        style={{ boxShadow: '0 0 12px rgba(184,115,51,0.35), 0 4px 12px rgba(0,0,0,0.6)' }}
      >
        <Gift size={18} />
        <span className="text-xs">OFFER GIFT</span>
        {giftsGiven > 0 && (
          <span className="text-[10px] text-[#8a8578]">({giftsGiven}/{MAX_GIFTS})</span>
        )}
      </button>

      {/* Modal */}
      <AnimatePresence>
        {open && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 bg-black/80 flex items-center justify-center p-4"
            onClick={() => setOpen(false)}
          >
            <motion.div
              ref={modalRef}
              role="dialog"
              aria-modal="true"
              aria-label="Offer a gift"
              initial={{ scale: 0.9, y: 20 }}
              animate={{ scale: 1, y: 0 }}
              exit={{ scale: 0.9, y: 20 }}
              className="bg-[#0a0806] border-2 border-[#B87333]/40 w-full max-w-md p-6 relative"
              onClick={(e) => e.stopPropagation()}
              style={{ boxShadow: '0 0 24px rgba(184,115,51,0.3)' }}
            >
              <button
                onClick={() => setOpen(false)}
                aria-label="Close gift panel"
                className="absolute top-2 right-2 text-[#8a8578] hover:text-[#CCAA00] transition-colors p-2"
              >
                <X size={18} />
              </button>

              <h3 className="font-terminal text-lg text-[#CCAA00] mb-1">
                BUM {npcName?.toUpperCase?.()} A FAG
              </h3>
              <p className="text-[#8a8578] text-xs mb-4 italic">
                Supply a vice. Gain trust. Or piss them off.
              </p>

              {cravingHint && !lastResult && (
                <div className="mb-4 px-3 py-2 bg-[#CCAA00]/5 border-l-2 border-[#CCAA00]/40">
                  <p className="text-[10px] text-[#8a8578] italic">
                    &raquo; Body language says they want: <span className="text-[#CCAA00]">{cravingHint}</span>
                  </p>
                </div>
              )}

              {/* Gift response panel */}
              {lastResult && (
                <motion.div
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  className="mb-4 p-3 border-l-2"
                  style={{
                    borderColor: lastResult.affinityDelta > 0 ? '#8aad7a' : lastResult.affinityDelta < 0 ? '#a8687e' : '#8a8578',
                    backgroundColor: lastResult.affinityDelta > 0 ? 'rgba(127,255,0,0.05)' : lastResult.affinityDelta < 0 ? 'rgba(255,20,147,0.05)' : 'rgba(138,133,120,0.05)',
                  }}
                >
                  <p className="text-[11px] text-[#E8E8E8]/85 leading-relaxed italic">
                    {lastResult.giftResponse}
                  </p>
                  <div className="mt-2 flex items-center gap-3 text-[10px] font-terminal">
                    <span style={{ color: lastResult.affinityDelta > 0 ? '#8aad7a' : lastResult.affinityDelta < 0 ? '#a8687e' : '#8a8578' }}>
                      AFFINITY {lastResult.affinityDelta >= 0 ? '+' : ''}{lastResult.affinityDelta}
                    </span>
                    <span className="text-[#8a8578]">&bull;</span>
                    <span className="text-[#8a8578]">NOW {lastResult.newAffinity}%</span>
                  </div>
                </motion.div>
              )}

              {/* Resource buttons */}
              <div className="grid grid-cols-2 gap-2">
                {resourceTypes.map((type) => {
                  const stock = getStock(type);
                  const meta = RESOURCE_META[type];
                  const disabled = !canGift || stock < 1 || loading;
                  return (
                    <button
                      key={type}
                      onClick={() => {
                        audioManager.playSFX('nav');
                        setHandoverVice(type);
                      }}
                      disabled={disabled}
                      aria-label={`Offer ${meta.label} (${stock} in stock)`}
                      className={`border p-3 flex flex-col items-center gap-1 transition min-h-[72px] ${
                        disabled
                          ? 'border-[#333] text-[#4a4a4a] cursor-not-allowed opacity-50'
                          : 'border-[#B87333]/40 text-[#E8E8E8] hover:border-[#CCAA00] hover:bg-[#CCAA00]/5 cursor-pointer active:scale-95'
                      }`}
                    >
                      <span className="inline-flex items-center">{meta.icon}</span>
                      <span className="font-terminal text-[10px]" style={{ color: disabled ? undefined : meta.color }}>
                        {meta.label}
                      </span>
                      <span className="font-terminal text-[9px] text-[#8a8578]">
                        STOCK: {stock}
                      </span>
                    </button>
                  );
                })}
              </div>

              {!canGift && (
                <p className="mt-4 text-[10px] text-[#a8687e] text-center">
                  &raquo; You&apos;ve offered enough. Push any further and it&apos;s begging.
                </p>
              )}
              <p className="mt-3 text-[9px] text-[#4a4a4a] text-center font-terminal">
                GIFTS REMAINING: {MAX_GIFTS - giftsGiven}
              </p>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Vice Handover overlay — recruitment mode with preference */}
      <ViceHandover
        substance={handoverVice ?? 'cigarettes'}
        recipientName={npcName}
        visible={!!handoverVice}
        mode="recruitment"
        preference={handoverVice ? (vice?.preferences?.[handoverVice] ?? 0) : 0}
        escalationLevel={escalationLevel}
        onComplete={() => {
          if (handoverVice) {
            handleOffer(handoverVice);
          }
          setHandoverVice(null);
        }}
        onCancel={() => setHandoverVice(null)}
      />
    </>
  );
}

