  const { unlocked } = paywallOn ? await getUnlockState() : { unlocked: false }
  const games = await getPublicGames(paywallOn, unlocked)
  const hero = await getHeroConfig(content, 'games')

  return (
    <main className={`bv-field min-h-[100svh] ${isOn(content.grain) ? '' : 'grain-off'}`} style={{ paddingTop: 'calc(56px + env(safe-area-inset-top))', backgroundColor: 'var(--bv-bg)' }}>
      <Nav swipe={isOn(content.swipeNav)} sections={navSections(content)} profile={{ member: unlocked }} />
      {hero.show && <PageHero hero={hero} />}
      <GamesArchive games={games} content={content} />
    </main>
  )
}

