import { motion } from 'framer-motion';

interface StatusBarProps {
  day: number;
  heat: number;
  crewCount: number;
  crewTotal: number;
}

/**
 * Persistent top status bar — DAY • HEAT • CREW.
 * Slim, always-visible pill anchored to the top-centre of the viewport.
 * Heat shifts colour as it climbs (green → amber → danger) and pulses red
 * once a raid becomes a real risk. Pulls straight from live game state
 * — no schema or API changes.
 */
export function StatusBar({ day, heat, crewCount, crewTotal }: StatusBarProps) {
  // Heat colour bands mirror the game's raid logic:
  //   <4  calm (green)   4–6 watched (amber)   7+ raid risk (danger)
  const heatColor =
    heat >= 7 ? 'var(--bmf-danger)' : heat >= 4 ? 'var(--bmf-amber)' : 'var(--bmf-green)';
  const heatDanger = heat >= 7;

  // Clamp the heat bar fill to the 0–10 game-over range.
  const heatPct = Math.max(0, Math.min(100, (heat / 10) * 100));

  const Divider = () => (
    <span className="mx-2 text-[#776b55] select-none" aria-hidden="true">
      •
    </span>
  );

  return (
    <div className="fixed top-0 left-1/2 -translate-x-1/2 z-[60] pointer-events-none">
      <motion.div
        initial={{ y: -28, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        transition={{ type: 'spring', stiffness: 320, damping: 30 }}
        className="font-bmf-mono flex items-center px-4 py-1 text-[11px] tracking-[0.18em] uppercase"
        style={{
          background: 'rgba(8,8,8,0.82)',
          border: '1px solid rgba(127,255,0,0.18)',
          borderTop: 'none',
          borderBottomLeftRadius: 6,
          borderBottomRightRadius: 6,
          color: 'var(--bmf-text)',
          backdropFilter: 'blur(4px)',
          boxShadow: '0 4px 18px rgba(0,0,0,0.55)',
        }}
        role="status"
        aria-label={`Day ${day}, heat ${heat} of 10, ${crewCount} of ${crewTotal} crew on the books`}
      >
        {/* DAY */}
        <span className="flex items-baseline gap-1.5">
          <span className="text-[#776b55]">DAY</span>
          <span style={{ color: 'var(--bmf-text)' }}>{day}</span>
        </span>

        <Divider />

        {/* HEAT — colour-coded with a thin fill track */}
        <span className="flex items-center gap-1.5">
          <span className="text-[#776b55]">HEAT</span>
          <motion.span
            style={{ color: heatColor }}
            animate={heatDanger ? { opacity: [1, 0.45, 1] } : { opacity: 1 }}
            transition={heatDanger ? { duration: 1.1, repeat: Infinity } : { duration: 0.2 }}
          >
            {heat}
          </motion.span>
          <span
            className="relative inline-block h-[5px] w-12 overflow-hidden"
            style={{ background: 'rgba(255,255,255,0.08)' }}
            aria-hidden="true"
          >
            <motion.span
              className="absolute inset-y-0 left-0"
              animate={{ width: `${heatPct}%` }}
              transition={{ type: 'spring', stiffness: 200, damping: 26 }}
              style={{ background: heatColor, boxShadow: `0 0 6px ${heatColor}` }}
            />
          </span>
        </span>

        <Divider />

        {/* CREW */}
        <span className="flex items-baseline gap-1.5">
          <span className="text-[#776b55]">CREW</span>
          <span style={{ color: 'var(--bmf-text)' }}>
            {crewCount}
            <span className="text-[#776b55]">/{crewTotal}</span>
          </span>
        </span>
      </motion.div>
    </div>
  );
}

