import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { isValidId, clampHeat } from '@/lib/api-guards';

// POST: Advance to next day + decay heat (NERVE influences decay rate) + reset energy
export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const { sessionId } = body ?? {};
    if (!isValidId(sessionId)) {
      return NextResponse.json({ error: 'Missing sessionId' }, { status: 400 });
    }

    const session = await prisma.gameSession.findUnique({ where: { id: sessionId } });
    if (!session) {
      return NextResponse.json({ error: 'Session not found' }, { status: 404 });
    }

    // NERVE stat influences heat decay: base 20% + 3% per nerve point
    // At nerve 2 (base): 26% decay. At nerve 6 (max start): 38% decay. At nerve 10 (coffee-boosted): 50% decay.
    const nerve = Math.max(0, Math.min(10, session.nerve ?? 2));
    const decayRate = 0.20 + (nerve * 0.03);
    const heatDecay = Math.max(0, (session.heat ?? 0) * (1 - decayRate));

    const updated = await prisma.gameSession.update({
      where: { id: sessionId },
      data: {
        day: { increment: 1 },
        heat: heatDecay,
        scroungedToday: false,
        energyUsed: 0,  // Reset energy for new day
      },
      include: { npcs: true, resources: true, expeditions: true },
    });

    return NextResponse.json(updated);
  } catch (err: unknown) {
    console.error('Day advance error:', err);
    return NextResponse.json({ error: 'Failed' }, { status: 500 });
  }
}

