import { NextResponse } from 'next/server'
import { getStripe } from '@/lib/stripe'
import { getSignedInUser } from '@/lib/membership'
import { getSiteContent } from '@/lib/content'
import { isOn } from '@/lib/site-defaults'

export const dynamic = 'force-dynamic'

export async function POST(req: Request) {
  const content = await getSiteContent()
  if (isOn(content.purchasesPaused)) return NextResponse.json({ error: 'PURCHASES PAUSED' }, { status: 503 })

  const stripe = getStripe()
  if (!stripe) return NextResponse.json({ error: 'CHECKOUT NOT CONFIGURED' }, { status: 503 })

  // Guests can buy: every buyer gets a single-use code on the success page and redeems it to a profile.
  const user = await getSignedInUser()
  const origin = req.headers.get('origin') || new URL(req.url).origin
  if (user?.member) return NextResponse.json({ url: `${origin}/profile` })

  const amount = Math.max(50, parseInt(content.paywallAmountCents, 10) || 500)
  const currency = content.paywallCurrency === 'aud' ? 'aud' : 'usd'

  try {
    const session = await stripe.checkout.sessions.create({
      mode: 'payment',
      submit_type: 'pay',
      allow_promotion_codes: true,
      billing_address_collection: 'auto',
      customer_creation: 'if_required',
      ...(user ? { client_reference_id: user.id, customer_email: user.email } : {}),
      metadata: { product: 'supporter-pass', ...(user ? { userId: user.id } : {}) },
      payment_intent_data: {
        description: 'Baseline Velocity Supporter Pass',
        metadata: { product: 'supporter-pass', ...(user ? { userId: user.id } : {}) },
      },
      custom_text: {
        submit: { message: 'Your single-use unlock code appears on the next screen. Redeem it to your profile — sign in anywhere to keep access.' },
      },
      line_items: [
        {
          quantity: 1,
          price_data: {
            currency,
            unit_amount: amount,
            product_data: { name: 'Baseline Velocity // Supporter Pass', description: 'One-time. Unlocks every game and app.' },
          },
        },
      ],
      success_url: `${origin}/unlock/success?session_id={CHECKOUT_SESSION_ID}`,
      cancel_url: `${origin}/unlock?checkout=cancelled`,
    })
    return NextResponse.json({ url: session.url })
  } catch (e) {
    console.error('checkout session failed', e)
    return NextResponse.json({ error: 'CHECKOUT FAILED — TRY AGAIN' }, { status: 500 })
  }
}

