// ============================================================
// COMIC VIEWER — Sequential Panel Display  (v1.0)
// ============================================================
// Auto-advancing visual panels. No text. Visual only.
// Used for directive intro/outro sequences.
// ============================================================

import { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import Image from 'next/image';
import type { DirectivePanel } from '@/lib/directives';
import { audioManager } from '@/app/_lib/audio-manager';

interface Props {
  panels: DirectivePanel[];
  /** Called when all panels have been viewed */
  onComplete: () => void;
  /** Optional label shown briefly at start */
  sequenceLabel?: string;
}

const PANEL_DURATION = 4500; // ms per panel before auto-advance
const FADE_DURATION = 0.8;   // seconds for crossfade

export default function ComicViewer({ panels, onComplete, sequenceLabel }: Props) {
  const [currentIndex, setCurrentIndex] = useState(-1); // -1 = title card
  const [autoAdvance, setAutoAdvance] = useState(true);

  // Auto-advance timer
  useEffect(() => {
    if (!autoAdvance) return;
    const timer = setTimeout(() => {
      advance();
    }, currentIndex === -1 ? 2200 : PANEL_DURATION);
    return () => clearTimeout(timer);
  }, [currentIndex, autoAdvance]);

  const advance = useCallback(() => {
    setCurrentIndex((prev) => {
      const next = prev + 1;
      if (next >= panels.length) {
        onComplete();
        return prev;
      }
      audioManager.playSFX('nav');
      return next;
    });
  }, [panels.length, onComplete]);

  // Click/tap to advance (also resumes auto)
  const handleClick = useCallback(() => {
    setAutoAdvance(true);
    advance();
  }, [advance]);

  // Keyboard: space/enter/right to advance
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if (e.key === ' ' || e.key === 'Enter' || e.key === 'ArrowRight') {
        e.preventDefault();
        handleClick();
      }
    };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, [handleClick]);

  const panel = currentIndex >= 0 && currentIndex < panels.length ? panels[currentIndex] : null;

  return (
    <div
      className="fixed inset-0 z-[9999] bg-black flex items-center justify-center cursor-pointer"
      onClick={handleClick}
      role="button"
      tabIndex={0}
      aria-label="Advance to next panel"
    >
      {/* Film grain overlay */}
      <div
        className="absolute inset-0 pointer-events-none z-30 opacity-[0.04]"
        style={{
          backgroundImage: 'url("data:image/svg+xml,%3Csvg viewBox=\'0 0 256 256\' xmlns=\'https://i.ytimg.com/vi/prHdnr2rM6c/maxresdefault.jpg id=\'noise\'%3E%3CfeTurbulence baseFrequency=\'0.9\' numOctaves=\'4\' stitchTiles=\'stitch\'/%3E%3C/filter%3E%3Crect width=\'100%25\' height=\'100%25\' filter=\'url(%23noise)\' opacity=\'1\'/%3E%3C/svg%3E")',
        }}
      />

      {/* Vignette */}
      <div
        className="absolute inset-0 pointer-events-none z-20"
        style={{ background: 'radial-gradient(ellipse at center, transparent 40%, rgba(0,0,0,0.7) 100%)' }}
      />

      <AnimatePresence mode="wait">
        {/* Title card */}
        {currentIndex === -1 && sequenceLabel && (
          <motion.div
            key="title"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            transition={{ duration: FADE_DURATION }}
            className="relative z-10 text-center"
          >
            <p className="font-terminal text-[10px] tracking-[0.5em] text-[#8a8578]/60 uppercase">
              {sequenceLabel}
            </p>
          </motion.div>
        )}

        {/* Panel */}
        {panel && (
          <motion.div
            key={`panel-${currentIndex}`}
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            transition={{ duration: FADE_DURATION }}
            className="relative z-10 w-full h-full max-w-5xl max-h-[80vh] mx-auto flex items-center justify-center p-4 sm:p-8"
          >
            <div className="relative w-full aspect-video bg-[#0a0a08] rounded-[1px] overflow-hidden shadow-2xl">
              <Image
                src={panel.image}
                alt={panel.alt}
                fill
                className="object-cover"
                priority
              />
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Progress dots */}
      {currentIndex >= 0 && (
        <div className="absolute bottom-6 left-1/2 -translate-x-1/2 z-30 flex gap-2">
          {panels.map((_, i) => (
            <div
              key={i}
              className="w-1.5 h-1.5 rounded-full transition-all duration-300"
              style={{
                background: i === currentIndex ? '#e8e4d4' : i < currentIndex ? '#8a8578' : '#3a3830',
              }}
            />
          ))}
        </div>
      )}

      {/* Skip hint */}
      <div className="absolute bottom-6 right-6 z-30">
        <p className="font-terminal text-[9px] text-[#5a5850] tracking-wider">TAP / SPACE TO ADVANCE</p>
      </div>
    </div>
  );
}

