'use client';

import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { playDenied, playThud } from '@/lib/sound-effects';
import type { GameState } from '../game-client';

interface Props {
  game: GameState;
  reason: 'heat' | 'raid';
  onRestart: () => void;
}

const ENDINGS: Record<string, { title: string; body: string }> = {
  heat: {
    title: 'SHUT DOWN',
    body: 'The heat was too much. They came with warrants, zip ties, and that look — the one that says they\'ve been watching you for weeks. Your "Grand Court Center" is now a crime scene. Your desk is evidence. Your clipboard is Exhibit A. The fluorescent lights — for once — are steady. Because someone else is paying the power bill now.',
  },
  raid: {
    title: 'RAIDED OUT',
    body: 'Two raids in quick succession. That\'s not bad luck — that\'s a pattern they\'ve been tracking. Your operation is dismantled. Your crew scattered like roaches when the light hits. The desk is empty. The receipts are in an evidence bag. Somewhere, a fluorescent light flickers one last time. Nobody notices.',
  },
};

// Epitaphs — escalation-aware last words that play after the main ending text
const EPITAPHS: Record<number, string[]> = {
  0: [
    'the desk will always be here. someone has to sit behind it.',
    'the fluorescents hum. the shift never ended.',
  ],
  3: [
    'you almost had something. the receipts know.',
    'the clipboard remembers everyone who tried.',
  ],
  5: [
    'the walls remember. the walls saw everything.',
    'somewhere in his files there\'s a version of you that got away.',
  ],
  7: [
    'the shrine is evidence now. they won\'t understand the arrangement.',
    'the lights are still on. they\'ll always be on.',
    'was any of it real? the invoice says yes.',
  ],
};

function getEpitaph(level: number, day: number): string {
  const bracket = level >= 7 ? 7 : level >= 5 ? 5 : level >= 3 ? 3 : 0;
  const pool = EPITAPHS[bracket];
  return pool[Math.abs(day) % pool.length];
}

export default function GameOverScreen({ game, reason, onRestart }: Props) {
  const [phase, setPhase] = useState<'title' | 'body' | 'stats'>('title');

  useEffect(() => {
    playDenied();
    const t1 = setTimeout(() => { playThud(); setPhase('body'); }, 2000);
    const t2 = setTimeout(() => setPhase('stats'), 5000);
    return () => { clearTimeout(t1); clearTimeout(t2); };
  }, []);

  const ending = ENDINGS[reason] ?? ENDINGS.heat;
  const recruitedCount = (game?.npcs ?? []).filter((n) => n?.recruited).length;
  const expeditionCount = game?.expeditions?.length ?? 0;
  const escalationLevel = Math.min(10, Math.floor((game?.heat ?? 0)));
  const epitaph = getEpitaph(escalationLevel, game?.day ?? 1);

  return (
    <div className="w-full h-full bg-black texture-dim-hall flex items-center justify-center p-4 overflow-auto" role="region" aria-label="Game over">
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ duration: 2 }}
        className="max-w-xl sm:max-w-2xl w-full text-center space-y-6"
      >
        {/* Static noise — pure-CSS grain */}
        <motion.div
          animate={{ opacity: [0.06, 0.12, 0.06] }}
          transition={{ duration: 3, repeat: Infinity }}
          className="fixed inset-0 pointer-events-none"
          style={{
            backgroundImage: `
              repeating-radial-gradient(circle at 12% 18%, rgba(255,255,255,0.08) 0, transparent 1.2px),
              repeating-radial-gradient(circle at 82% 43%, rgba(255,255,255,0.05) 0, transparent 0.9px),
              repeating-radial-gradient(circle at 47% 77%, rgba(255,255,255,0.07) 0, transparent 1.1px)
            `,
            backgroundSize: '120px 120px, 90px 90px, 180px 180px',
            mixBlendMode: 'screen',
          }}
        />

        <motion.h1
          initial={{ y: 20, scale: 1.1 }}
          animate={{ y: 0, scale: 1 }}
          transition={{ duration: 1.2, ease: 'easeOut' }}
          className="font-creepy text-5xl text-[#a8687e]"
          style={{ textShadow: '0 0 20px rgba(255,20,147,0.5)' }}
        >
          {ending.title}
        </motion.h1>

        <AnimatePresence>
          {(phase === 'body' || phase === 'stats') && (
            <motion.div
              initial={{ opacity: 0, y: 12 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 1 }}
            >
              <p className="font-typewriter text-sm sm:text-base text-[#E8E8E8]/50 leading-relaxed sm:leading-loose mb-2 max-w-lg mx-auto">
                {ending.body}
              </p>
            </motion.div>
          )}
        </AnimatePresence>

        <AnimatePresence>
          {phase === 'stats' && (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ duration: 1.2 }}
              className="space-y-4"
            >
              {/* Stats breakdown — receipt style */}
              <div
                className="inline-block text-left mx-auto px-6 py-4 border border-[#a8687e]/15"
                style={{ background: 'rgba(255,20,147,0.03)' }}
              >
                <div className="font-terminal text-[10px] tracking-[0.3em] text-[#a8687e]/50 mb-3">
                  POST-MORTEM
                </div>
                <div className="space-y-1.5 font-terminal text-xs">
                  <div className="flex justify-between gap-8">
                    <span className="text-[#8a8578]">DAYS SURVIVED</span>
                    <span className="text-[#E8E8E8]/60">{game?.day ?? 1}</span>
                  </div>
                  <div className="flex justify-between gap-8">
                    <span className="text-[#8a8578]">FINAL HEAT</span>
                    <span className="text-[#a8687e]/80">{(game?.heat ?? 0).toFixed(1)}</span>
                  </div>
                  <div className="flex justify-between gap-8">
                    <span className="text-[#8a8578]">CREW RECRUITED</span>
                    <span className="text-[#E8E8E8]/60">{recruitedCount}/4</span>
                  </div>
                  <div className="flex justify-between gap-8">
                    <span className="text-[#8a8578]">EXPEDITIONS</span>
                    <span className="text-[#E8E8E8]/60">{expeditionCount}</span>
                  </div>
                </div>
              </div>

              <motion.button
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ delay: 1 }}
                onClick={onRestart}
                aria-label="Restart the game"
                className="font-terminal text-base px-10 py-3 border-2 border-[#8aad7a]/30 text-[#8aad7a]/60 hover:bg-[#8aad7a] hover:text-[#080808] transition-all active:scale-95 cursor-pointer mt-4 min-h-[48px]"
              >
                TRY AGAIN
              </motion.button>

              <motion.p
                initial={{ opacity: 0 }}
                animate={{ opacity: 0.25 }}
                transition={{ delay: 2 }}
                className="text-xs text-[#5a564e] font-typewriter italic"
              >
                {epitaph}
              </motion.p>
            </motion.div>
          )}
        </AnimatePresence>
      </motion.div>
    </div>
  );
}

