/**
 * Shared API input validation & guards.
 * Red-team audit (Session 11) — centralised to avoid per-route drift.
 */

/** Valid resource type strings — anything else is rejected. */
export const VALID_RESOURCE_TYPES = ['cigarettes', 'alcohol', 'weed', 'crystals'] as const;
export type ValidResourceType = (typeof VALID_RESOURCE_TYPES)[number];

/** Returns the value if it's a known resource type, else null. */
export function validateResourceType(input: unknown): ValidResourceType | null {
  if (typeof input !== 'string') return null;
  return VALID_RESOURCE_TYPES.includes(input as ValidResourceType) ? (input as ValidResourceType) : null;
}

/** Clamp heat to 0–10 (the game's valid range). */
export function clampHeat(v: number): number {
  return Math.max(0, Math.min(10, v));
}

/** Returns a finite number or the fallback. Guards against NaN/Infinity/strings. */
export function safeNumber(input: unknown, fallback = 0): number {
  const n = Number(input);
  return Number.isFinite(n) ? n : fallback;
}

/** Validates a string looks like a cuid/uuid (not empty, reasonable length, no special chars). */
export function isValidId(input: unknown): input is string {
  if (typeof input !== 'string') return false;
  if (input.length < 10 || input.length > 60) return false;
  // Only allow alphanumeric + hyphens + underscores (covers cuid, cuid2, uuid)
  return /^[a-zA-Z0-9_-]+$/.test(input);
}

/** Valid substance strings for tolerance route. */
export const VALID_SUBSTANCES = ['cigarettes', 'alcohol', 'weed', 'crystals'] as const;

