import { NextResponse } from 'next/server'
import { requireAdmin } from '@/auth'
import { prisma } from '@/lib/db'
import { GALLERY_TYPES, getGallery, isGalleryPath } from '@/lib/gallery'
import { generatePresignedUploadUrl } from '@/lib/s3'

export const dynamic = 'force-dynamic'

export async function GET() {
  if (!(await requireAdmin())) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  return NextResponse.json({ images: await getGallery() })
}

/** action 'presign' → upload URL in public/gallery/; action 'add' → register the uploaded object at the end of the list. */
export async function POST(req: Request) {
  if (!(await requireAdmin())) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  const body = await req.json().catch(() => ({}))

  if (body?.action === 'presign') {
    const fileName = String(body?.fileName ?? '')
    const contentType = String(body?.contentType ?? '')
    if (!fileName || !(GALLERY_TYPES as readonly string[]).includes(contentType)) {
      return NextResponse.json({ error: 'JPG, PNG or WebP only' }, { status: 400 })
    }
    try {
      return NextResponse.json(await generatePresignedUploadUrl(fileName, contentType, true, 'gallery'))
    } catch (e) {
      console.error('gallery presign failed', e)
      return NextResponse.json({ error: 'Upload URL failed' }, { status: 500 })
    }
  }

  if (body?.action === 'add') {
    const path = String(body?.cloud_storage_path ?? '')
    if (!isGalleryPath(path)) return NextResponse.json({ error: 'Invalid storage path' }, { status: 400 })
    const width = Math.max(0, Math.round(Number(body?.width) || 0))
    const height = Math.max(0, Math.round(Number(body?.height) || 0))
    const last = await prisma.galleryImage.findFirst({ orderBy: { order: 'desc' }, select: { order: true } })
    const row = await prisma.galleryImage.create({
      data: { cloud_storage_path: path, isPublic: true, width, height, order: (last?.order ?? 0) + 1 },
    })
    return NextResponse.json({ id: row.id }, { status: 201 })
  }

  return NextResponse.json({ error: 'Unknown action' }, { status: 400 })
}

