import { useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ScrollText } from 'lucide-react';
import DirectiveCardComponent from './directive-card';
import {
  DIRECTIVE_CARDS,
  DIRECTIVE_NPC_KEYS,
  getDirectiveStatus,
  type DirectiveStatus,
} from '@/lib/directives';
import { computeActorState } from '@/lib/encounter';
import { getZoneFromActor, type CrewZone } from '@/lib/ui-model';
import type { GameState } from '../game-client';

interface Props {
  game: GameState;
  onActivateDirective?: (npcKey: string) => void;
  onViewDirective?: (npcKey: string) => void;
}

interface DirectiveEntry {
  npcKey: string;
  status: DirectiveStatus;
  zone?: CrewZone;
}

export default function DirectiveHand({ game, onActivateDirective, onViewDirective }: Props) {
  const entries: DirectiveEntry[] = useMemo(() => {
    return DIRECTIVE_NPC_KEYS.map((npcKey) => {
      const npc = (game?.npcs ?? []).find(
        (n) => n?.archetype === npcKey || n?.name?.toLowerCase() === npcKey,
      );
      const missionKey = `directive_${npcKey}`;
      const mission = (game?.missions ?? []).find((m: any) => m?.missionKey === missionKey);

      let zone: CrewZone | undefined;
      if (npc?.recruited) {
        try {
          const actor = computeActorState(npc as any);
          zone = getZoneFromActor(actor);
        } catch { zone = 'GREEN'; }
      }

      return {
        npcKey,
        status: getDirectiveStatus(
          npcKey,
          !!npc?.recruited,
          !!npc?.directiveDone,
          mission?.status,
        ),
        zone,
      };
    });
  }, [game?.npcs, game?.missions]);

  const completedCount = entries.filter((e) => e.status === 'COMPLETE').length;

  return (
    <div className="space-y-3">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <ScrollText size={14} className="text-[#CCAA00]" />
          <span className="font-terminal text-[10px] tracking-[0.3em] text-[#CCAA00]">
            DIRECTIVES
          </span>
        </div>
        <span className="font-terminal text-[10px] text-[#8a8578]">
          {completedCount}/4
        </span>
      </div>

      {/* Card list */}
      <div className="space-y-1.5">
        <AnimatePresence>
          {entries.map((entry, idx) => {
            const directive = DIRECTIVE_CARDS[entry.npcKey];
            if (!directive) return null;
            return (
              <motion.div
                key={entry.npcKey}
                initial={{ opacity: 0, x: -8 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: idx * 0.08 }}
              >
                <DirectiveCardComponent
                  directive={directive}
                  status={entry.status}
                  zone={entry.zone}
                  compact
                  onActivate={
                    (entry.status === 'UNLOCKED' || entry.status === 'FAILED')
                      ? () => onActivateDirective?.(entry.npcKey)
                      : undefined
                  }
                  onView={
                    entry.status !== 'LOCKED'
                      ? () => onViewDirective?.(entry.npcKey)
                      : undefined
                  }
                />
              </motion.div>
            );
          })}
        </AnimatePresence>
      </div>
    </div>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// lib/encounter.ts — Encounter System v1
//
// Replaces the dice-based combat resolver (lib/combat.ts) with a systemic
// pressure/actor-state model. No dice. No attack/defense. All outcomes are
// driven by scene pressure, actor psychology, and player verb choice.
//
// Core loop: Scene Pressure rises → Actor States shift → Player picks a Verb
// → Outcome resolves from the intersection of pressure + actor + verb.
//
// Design pillars: Recruit, Dose, Confront, Run.
// ─────────────────────────────────────────────────────────────────────────────

// ─── Actor State ──────────────────────────────────────────────────────────────
// Every NPC carries this state. It's the single source of truth for how they
// behave in encounters, expeditions, and hub interactions. The player NEVER
// sees exact numbers — only qualitative labels and behavioral tells.

export interface ActorState {
  /** How badly they need their next fix (0=satiated, 10=desperate). */
  need: number;
  /** How much substance it takes to move the needle (0=virgin, 10=burnt). */
  tolerance: number;
  /** Willingness to follow orders (0=defiant, 10=obedient). */
  compliance: number;
  /** Likelihood of unpredictable/dangerous behavior (0=stable, 10=volatile). */
  volatility: number;
  /** How close to breaking (0=resilient, 10=shattered). */
  fragility: number;
  /** Trust in the player specifically (0=hostile, 10=devoted). */
  loyalty: number;
  /** Mental clarity / usefulness (0=incoherent, 10=sharp). */
  clarity: number;
}

/** Qualitative label the UI can show without revealing numbers. */
export type ActorMood =
  | 'STABLE'       // functional, compliant
  | 'RESTLESS'     // need rising, starting to fidget
  | 'DESPERATE'    // high need, will do anything
  | 'VOLATILE'     // unpredictable, could snap
  | 'WITHDRAWN'    // low loyalty, may refuse
  | 'CRASHING'     // post-overfeed or high fragility
  | 'GONE';        // disappeared / collapsed

export function getActorMood(a: ActorState): ActorMood {
  if (a.fragility >= 9) return 'GONE';
  if (a.fragility >= 7 || (a.clarity <= 2 && a.need >= 6)) return 'CRASHING';
  if (a.volatility >= 7) return 'VOLATILE';
  if (a.need >= 7 && a.compliance >= 5) return 'DESPERATE';
  if (a.need >= 5) return 'RESTLESS';
  if (a.loyalty <= 2 && a.compliance <= 3) return 'WITHDRAWN';
  return 'STABLE';
}

/** Human-readable status line for the UI. Never exact numbers. */
export function getActorTell(a: ActorState): string {
  const mood = getActorMood(a);
  switch (mood) {
    case 'STABLE':    return 'Seems functional. Eyes forward.';
    case 'RESTLESS':  return 'Fidgeting. Keeps checking pockets.';
    case 'DESPERATE': return 'Sweating. Will say yes to anything.';
    case 'VOLATILE':  return 'Jaw clenched. Something\'s about to give.';
    case 'WITHDRAWN': return 'Won\'t look at you. Pulling away.';
    case 'CRASHING':  return 'Shaking. Barely standing. Eyes glazed.';
    case 'GONE':      return '...';
  }
}

// ─── Dosing Engine ────────────────────────────────────────────────────────────
// The core manipulation mechanic. Give or withhold substances to shift actor
// state. Thresholds are HIDDEN — the player only sees behavioral feedback.

export interface DoseResult {
  /** What changed (qualitative). */
  reaction: 'RELIEF' | 'GRATITUDE' | 'OVERFED' | 'WRONG_SUBSTANCE' | 'REFUSED' | 'NO_EFFECT';
  /** Flavor text for the UI. */
  narrative: string;
  /** Delta applied to actor state fields. */
  deltas: Partial<ActorState>;
}

/**
 * Resolve a dosing action. The player gives a substance to an NPC.
 * Returns the reaction and state deltas. Caller applies deltas to DB.
 *
 * CRITICAL: The player never sees the threshold math. They only see the
 * DoseResult.narrative text and behavioral changes on the next tick.
 */
export function resolveDose(
  actor: ActorState,
  substancePreference: number, // -2 to +2 from ViceProfile.preferences
  isCreaving: boolean,         // substance is in their cravings array
): DoseResult {
  // --- Refused: loyalty too low + substance they hate
  if (actor.loyalty <= 2 && substancePreference <= -1) {
    return {
      reaction: 'REFUSED',
      narrative: 'They push it back. Won\'t even touch it.',
      deltas: { loyalty: -1, volatility: 1 },
    };
  }

  // --- Wrong substance: negative preference
  if (substancePreference <= -1) {
    const volatilitySpike = substancePreference === -2 ? 3 : 1;
    return {
      reaction: 'WRONG_SUBSTANCE',
      narrative: substancePreference === -2
        ? 'Their face closes. You\'ve made it worse.'
        : 'They take it but something shifts. Wrong call.',
      deltas: {
        volatility: volatilitySpike,
        loyalty: substancePreference === -2 ? -2 : -1,
        compliance: -1,
      },
    };
  }

  // --- Overfed: already satiated (low need) + giving more
  if (actor.need <= 2 && actor.tolerance >= 5) {
    return {
      reaction: 'OVERFED',
      narrative: 'They take it because they can\'t say no. But they\'re already gone. You\'re losing them.',
      deltas: {
        clarity: -2,
        fragility: 2,
        compliance: 1,  // short-term obedience
        loyalty: -1,     // but they resent it
      },
    };
  }

  // --- No effect: neutral substance + low need
  if (substancePreference === 0 && actor.need <= 3) {
    return {
      reaction: 'NO_EFFECT',
      narrative: 'They pocket it without comment. Means nothing to them right now.',
      deltas: { compliance: 0 },
    };
  }

  // --- Relief / Gratitude: the good stuff
  const isRelief = actor.need >= 5;
  const needReduction = isCreaving ? -4 : substancePreference >= 1 ? -3 : -1;
  const complianceBoost = isRelief ? (isCreaving ? 3 : 2) : 1;
  const loyaltyBoost = isCreaving ? 2 : substancePreference >= 1 ? 1 : 0;

  return {
    reaction: isRelief ? 'RELIEF' : 'GRATITUDE',
    narrative: isRelief
      ? 'The tension drains out of them. Shoulders drop. They owe you and they know it.'
      : 'A nod. Respect. You read them right.',
    deltas: {
      need: needReduction,
      compliance: complianceBoost,
      loyalty: loyaltyBoost,
      volatility: isRelief ? -2 : -1,
      clarity: isCreaving && actor.tolerance >= 6 ? -1 : 0,
    },
  };
}

// ─── Withholding ──────────────────────────────────────────────────────────────
// When the player deliberately doesn't dose an NPC who needs it.
// Called once per day-tick for each recruited NPC.

export interface WithholdResult {
  narrative: string;
  deltas: Partial<ActorState>;
  disappeared: boolean;
}

export function resolveWithhold(actor: ActorState): WithholdResult {
  // Need grows each day without a fix
  const needGrowth = Math.min(2, 1 + (actor.tolerance >= 5 ? 1 : 0));

  if (actor.need >= 8 && actor.loyalty <= 3) {
    return {
      narrative: 'Gone. Didn\'t leave a note.',
      deltas: { fragility: 10 },
      disappeared: true,
    };
  }

  if (actor.need >= 7) {
    return {
      narrative: 'Pacing. Muttering. Won\'t make eye contact. Something\'s going to break.',
      deltas: {
        need: needGrowth,
        volatility: 2,
        compliance: -2,
        clarity: -1,
        fragility: 1,
      },
      disappeared: false,
    };
  }

  if (actor.need >= 4) {
    return {
      narrative: 'Restless. Keeps asking if you\'ve "got anything". Getting harder to manage.',
      deltas: {
        need: needGrowth,
        volatility: 1,
        compliance: -1,
      },
      disappeared: false,
    };
  }

  return {
    narrative: 'Holding steady. For now.',
    deltas: { need: needGrowth },
    disappeared: false,
  };
}

// ─── Scene Pressure ──────────────────────────────────────────────────────────
// Every encounter has a scene-wide pressure value that ratchets up.
// It represents urgency, exposure, and instability.

export interface SceneState {
  /** 0-10 pressure. Determines available verbs and outcome severity. */
  pressure: number;
  /** Time is running out (moves, turns, or narrative beats remaining). */
  urgency: number;
  /** Environmental exposure / heat risk. */
  exposure: number;
  /** Number of actors in the scene who are volatile. */
  volatileCount: number;
}

export function calculateScenePressure(scene: SceneState): number {
  const base = scene.pressure;
  const urgencyMod = scene.urgency <= 2 ? 2 : scene.urgency <= 4 ? 1 : 0;
  const exposureMod = Math.floor(scene.exposure / 3);
  const volatileMod = scene.volatileCount;
  return Math.min(10, Math.max(0, base + urgencyMod + exposureMod + volatileMod));
}

// ─── Encounter Verbs ─────────────────────────────────────────────────────────
// Context-sensitive actions the player can take during a confrontation.
// Each verb's viability depends on actor state + scene pressure.

export type EncounterVerb =
  | 'OBSERVE'     // Watch, assess, gather information before acting
  | 'CALM'        // De-escalate, soothe, appeal to reason
  | 'PRESSURE'    // Intimidate, threaten, leverage need
  | 'OFFER'       // Provide substance/resource to shift the dynamic
  | 'WITHHOLD'    // Deny them what they want — let need do the work
  | 'REDIRECT'    // Talk around it, stall, shift attention elsewhere
  | 'EXPLOIT'     // Use someone's weakness against them — dark, effective
  | 'WITHDRAW';   // Retreat, disengage, live to fight another day

export interface VerbOption {
  verb: EncounterVerb;
  label: string;
  available: boolean;
  risk: 'LOW' | 'MEDIUM' | 'HIGH' | 'EXTREME';
  hint: string; // qualitative hint, never exact numbers
}

/** Get available verbs for a confrontation given the scene + lead actor. */
export function getAvailableVerbs(
  scene: SceneState,
  leadActor: ActorState,
  hasResources: boolean,
  crewSize: number,
): VerbOption[] {
  const p = calculateScenePressure(scene);
  const verbs: VerbOption[] = [];

  // OBSERVE: always available first round, lets you read the situation
  verbs.push({
    verb: 'OBSERVE',
    label: 'READ THE ROOM',
    available: true,
    risk: 'LOW',
    hint: p >= 6
      ? 'Things are moving fast. You might not get another look.'
      : 'Take a breath. See what you\'re dealing with.',
  });

  // CALM: de-escalate, needs clarity + low volatility in the scene
  verbs.push({
    verb: 'CALM',
    label: 'EASY NOW',
    available: leadActor.clarity >= 3,
    risk: p >= 7 ? 'HIGH' : 'LOW',
    hint: leadActor.clarity >= 6
      ? 'Words might still work here.'
      : 'Hard to reason when you can barely think.',
  });

  // PRESSURE: lean on them, leverage their need
  verbs.push({
    verb: 'PRESSURE',
    label: 'LEAN ON THEM',
    available: leadActor.compliance >= 3 && leadActor.volatility < 8,
    risk: p >= 7 ? 'HIGH' : p >= 4 ? 'MEDIUM' : 'LOW',
    hint: leadActor.compliance >= 6
      ? 'Your people will back you up.'
      : 'Your crew\'s not sure about this one.',
  });

  // OFFER: give them something to shift the dynamic
  verbs.push({
    verb: 'OFFER',
    label: 'GIVE THEM SOMETHING',
    available: hasResources,
    risk: 'LOW',
    hint: hasResources ? 'Everyone has a price.' : 'Pockets are empty.',
  });

  // WITHHOLD: deny them what they want, let desperation build
  verbs.push({
    verb: 'WITHHOLD',
    label: 'LET THEM SWEAT',
    available: leadActor.need >= 4,
    risk: leadActor.volatility >= 6 ? 'HIGH' : 'MEDIUM',
    hint: leadActor.need >= 7
      ? 'They need it bad. Time is on your side.'
      : 'They can still walk away. Careful.',
  });

  // REDIRECT: talk around it, shift their attention
  verbs.push({
    verb: 'REDIRECT',
    label: 'CHANGE THE SUBJECT',
    available: leadActor.clarity >= 4,
    risk: p >= 6 ? 'HIGH' : 'MEDIUM',
    hint: leadActor.clarity >= 7
      ? 'Sharp enough to sell ice to penguins.'
      : 'Foggy. Might fumble the words.',
  });

  // EXPLOIT: use a weakness — dark, effective, costs trust
  verbs.push({
    verb: 'EXPLOIT',
    label: 'USE WHAT YOU KNOW',
    available: crewSize > 1 || leadActor.fragility >= 4,
    risk: 'MEDIUM',
    hint: leadActor.fragility >= 6
      ? 'They\'re already cracking. Push the right spot.'
      : 'Everyone has a wound. Find it.',
  });

  // WITHDRAW: disengage, retreat, live to try again
  verbs.push({
    verb: 'WITHDRAW',
    label: 'BACK AWAY',
    available: scene.exposure <= 5,
    risk: scene.exposure <= 2 ? 'LOW' : 'MEDIUM',
    hint: scene.exposure <= 2
      ? 'Nobody\'s watching. Slip away.'
      : 'Lot of eyes on you. Not clean.',
  });

  return verbs;
}

// ─── Encounter Resolution ────────────────────────────────────────────────────
// Replaces combat.ts resolveCombat(). No dice. Outcomes are deterministic
// given the same inputs — driven by actor state thresholds + scene pressure.

export type EncounterOutcome =
  | 'RESOLVED'        // Clean exit, minimal cost
  | 'CONCESSION'      // You gave something up but survived
  | 'ESCALATED'       // Pressure increased, encounter continues
  | 'COLLAPSE'        // Actor broke — fragility spike
  | 'DISAPPEARANCE'   // Actor fled / vanished
  | 'CONFRONTATION_WON'  // You dominated the scene
  | 'CONFRONTATION_LOST'; // You lost control

export interface EncounterResult {
  outcome: EncounterOutcome;
  narrative: string;
  /** Deltas to apply to the lead actor. */
  actorDeltas: Partial<ActorState>;
  /** Scene pressure change. */
  pressureDelta: number;
  /** Resource cost (negative = lost). */
  resourceCost: Partial<Record<string, number>>;
  /** Heat change. */
  heatDelta: number;
  /** If a crew member was sacrificed/shaken. */
  sacrificedCrewId?: string;
  /** If the encounter should end. */
  endsEncounter: boolean;
}

/**
 * Resolve one verb action in an encounter.
 * Pure function: same inputs → same output. No randomness.
 */
export function resolveEncounterAction(
  verb: EncounterVerb,
  scene: SceneState,
  actor: ActorState,
  /** Seeded value 0-1 for outcome variance (use deterministic PRNG). */
  seed: number,
): EncounterResult {
  const p = calculateScenePressure(scene);
  const mood = getActorMood(actor);

  // Threshold: actor's effectiveness at this action
  // Higher = more likely to succeed
  const effectiveness = (
    (actor.compliance * 0.25) +
    (actor.clarity * 0.25) +
    (actor.loyalty * 0.2) +
    ((10 - actor.volatility) * 0.15) +
    ((10 - actor.fragility) * 0.15)
  );

  // Difficulty: scene pressure makes everything harder
  const difficulty = p * 0.8 + (mood === 'VOLATILE' ? 2 : mood === 'CRASHING' ? 3 : 0);

  // The "roll" — deterministic from seed, weighted by effectiveness vs difficulty
  const check = effectiveness - difficulty + (seed * 4 - 2); // seed adds ±2 variance

  switch (verb) {
    case 'OBSERVE': {
      // Low-risk information gathering. Reduces pressure slightly by
      // demonstrating composure. Better results with high clarity.
      if (check >= 2) {
        return {
          outcome: 'RESOLVED',
          narrative: 'You clock the exits, the body language, the weight of it. Now you know.',
          actorDeltas: { clarity: 1 },
          pressureDelta: -1,
          resourceCost: {},
          heatDelta: 0,
          endsEncounter: false,
        };
      }
      return {
        outcome: 'ESCALATED',
        narrative: 'You hesitate. They notice you noticing. "What are you looking at?"',
        actorDeltas: { volatility: 1 },
        pressureDelta: 1,
        resourceCost: {},
        heatDelta: 0,
        endsEncounter: false,
      };
    }

    case 'CALM': {
      if (check >= 3) {
        return {
          outcome: 'RESOLVED',
          narrative: 'Your voice lands. The room exhales. Whatever was about to happen — doesn\'t.',
          actorDeltas: { volatility: -2, compliance: 1 },
          pressureDelta: -3,
          resourceCost: {},
          heatDelta: -1,
          endsEncounter: true,
        };
      }
      if (check >= 0) {
        return {
          outcome: 'CONCESSION',
          narrative: 'They stop shouting but they\'re not calm. They\'re deciding.',
          actorDeltas: { volatility: -1 },
          pressureDelta: -1,
          resourceCost: {},
          heatDelta: 0,
          endsEncounter: false,
        };
      }
      return {
        outcome: 'ESCALATED',
        narrative: '"Don\'t talk to me like I\'m stupid." Worse now.',
        actorDeltas: { volatility: 2, compliance: -1 },
        pressureDelta: 2,
        resourceCost: {},
        heatDelta: 1,
        endsEncounter: false,
      };
    }

    case 'PRESSURE': {
      if (check >= 3) {
        return {
          outcome: 'CONFRONTATION_WON',
          narrative: 'They back down. Your crew stood firm. The situation defuses.',
          actorDeltas: { compliance: 1, volatility: -1 },
          pressureDelta: -3,
          resourceCost: {},
          heatDelta: 1,
          endsEncounter: true,
        };
      }
      if (check >= 0) {
        return {
          outcome: 'ESCALATED',
          narrative: 'Standoff. Nobody moves. The pressure builds.',
          actorDeltas: { volatility: 1 },
          pressureDelta: 2,
          resourceCost: {},
          heatDelta: 1,
          endsEncounter: false,
        };
      }
      return {
        outcome: 'CONFRONTATION_LOST',
        narrative: 'Your bluff got called. They\'re not afraid of you.',
        actorDeltas: { compliance: -2, loyalty: -1, volatility: 2 },
        pressureDelta: 3,
        resourceCost: {},
        heatDelta: 2,
        endsEncounter: false,
      };
    }

    case 'OFFER': {
      // Giving them something. Always resolves, always costs.
      return {
        outcome: 'RESOLVED',
        narrative: 'You hand it over. Their eyes change. Transaction complete.',
        actorDeltas: { need: -2 },
        pressureDelta: -4,
        resourceCost: { cigarettes: -1, alcohol: -1 },
        heatDelta: 0,
        endsEncounter: true,
      };
    }

    case 'WITHHOLD': {
      // Deny them what they want. Powerful if their need is high,
      // dangerous if they're volatile enough to take it.
      if (actor.need >= 7 && check >= 1) {
        return {
          outcome: 'CONFRONTATION_WON',
          narrative: 'They\'re shaking. They need it too bad to walk away. You own this moment.',
          actorDeltas: { compliance: 2, need: 1, loyalty: -1 },
          pressureDelta: -3,
          resourceCost: {},
          heatDelta: 0,
          endsEncounter: true,
        };
      }
      if (check >= 0) {
        return {
          outcome: 'ESCALATED',
          narrative: 'They\'re getting desperate. Clock\'s ticking — for both of you.',
          actorDeltas: { need: 1, volatility: 1 },
          pressureDelta: 1,
          resourceCost: {},
          heatDelta: 0,
          endsEncounter: false,
        };
      }
      return {
        outcome: 'CONFRONTATION_LOST',
        narrative: 'They snapped. Should\'ve given them something.',
        actorDeltas: { volatility: 3, loyalty: -2 },
        pressureDelta: 3,
        resourceCost: {},
        heatDelta: 2,
        endsEncounter: false,
      };
    }

    case 'REDIRECT': {
      if (check >= 2) {
        return {
          outcome: 'RESOLVED',
          narrative: 'Talked them around the corner. They forgot what they were angry about.',
          actorDeltas: { clarity: -1 },
          pressureDelta: -2,
          resourceCost: {},
          heatDelta: 0,
          endsEncounter: true,
        };
      }
      return {
        outcome: 'ESCALATED',
        narrative: 'They see through it. "Don\'t bullshit me."',
        actorDeltas: { volatility: 1, compliance: -1 },
        pressureDelta: 2,
        resourceCost: {},
        heatDelta: 0,
        endsEncounter: false,
      };
    }

    case 'EXPLOIT': {
      // Dark verb. Uses someone's fragility / weakness against them.
      // High effectiveness but costs loyalty and trust.
      if (check >= 2) {
        return {
          outcome: 'CONFRONTATION_WON',
          narrative: 'You said the thing nobody was supposed to say. It worked. They crumbled.',
          actorDeltas: { fragility: 2, compliance: 2, loyalty: -2 },
          pressureDelta: -4,
          resourceCost: {},
          heatDelta: 1,
          endsEncounter: true,
        };
      }
      if (mood === 'VOLATILE' || mood === 'CRASHING') {
        return {
          outcome: 'COLLAPSE',
          narrative: 'You pushed the wrong button. They didn\'t fight — they broke.',
          actorDeltas: { fragility: 4, clarity: -3, volatility: -2 },
          pressureDelta: -2,
          resourceCost: {},
          heatDelta: 3,
          endsEncounter: true,
        };
      }
      return {
        outcome: 'ESCALATED',
        narrative: 'They know what you tried to do. Trust is gone.',
        actorDeltas: { loyalty: -3, volatility: 2 },
        pressureDelta: 2,
        resourceCost: {},
        heatDelta: 1,
        endsEncounter: false,
      };
    }

    case 'WITHDRAW': {
      if (scene.exposure <= 3 && check >= 0) {
        return {
          outcome: 'RESOLVED',
          narrative: 'You back away. No one follows. Live to try again.',
          actorDeltas: {},
          pressureDelta: -5,
          resourceCost: {},
          heatDelta: -1,
          endsEncounter: true,
        };
      }
      return {
        outcome: 'ESCALATED',
        narrative: 'They clock you leaving. "Where do you think you\'re going?"',
        actorDeltas: { volatility: 1 },
        pressureDelta: 3,
        resourceCost: {},
        heatDelta: 2,
        endsEncounter: false,
      };
    }
  }
}

// ─── Deterministic PRNG (same as combat.ts, preserved for seed compat) ───────
export function createEncounterRng(seed: number): () => number {
  let state = (seed >>> 0) || 0xC0FFEE;
  return () => {
    state = (state + 0x6D2B79F5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 0x100000000;
  };
}

// ─── Actor State from DB ─────────────────────────────────────────────────────
// Compute ActorState from the existing NPC database fields.
// This bridges the old schema to the new system without migration.

export function computeActorState(npc: {
  affinity: number;
  toleranceCigs: number;
  toleranceAlc: number;
  toleranceWeed: number;
  toleranceCryst: number;
  usageCigs: number;
  usageAlc: number;
  usageWeed: number;
  usageCryst: number;
  muscle: number;
  brains: number;
  unpredictability: number;
  heatLevel: number;
  decayDay: number;
}): ActorState {
  const avgTolerance = (
    npc.toleranceCigs + npc.toleranceAlc +
    npc.toleranceWeed + npc.toleranceCryst
  ) / 4;
  const totalUsage = npc.usageCigs + npc.usageAlc + npc.usageWeed + npc.usageCryst;

  // Need: inverse of recent dosing. High tolerance + low recent use = high need.
  // decayDay tracks days since last dose (0 = dosed today).
  const need = Math.min(10, Math.max(0,
    npc.decayDay * 1.5 + avgTolerance * 0.5
  ));

  // Compliance: driven by affinity + inversely by heat pressure
  const compliance = Math.min(10, Math.max(0,
    5 + npc.affinity * 0.3 - npc.heatLevel * 0.3
  ));

  // Volatility: unpredictability stat + need pressure + heat
  const volatility = Math.min(10, Math.max(0,
    npc.unpredictability * 0.4 + need * 0.3 + npc.heatLevel * 0.2
  ));

  // Fragility: tolerance wear + overuse
  const fragility = Math.min(10, Math.max(0,
    avgTolerance * 0.6 + (totalUsage > 20 ? (totalUsage - 20) * 0.15 : 0)
  ));

  // Loyalty: affinity-based
  const loyalty = Math.min(10, Math.max(0,
    5 + npc.affinity * 0.4
  ));

  // Clarity: brains - tolerance fog
  const clarity = Math.min(10, Math.max(0,
    npc.brains * 0.8 - avgTolerance * 0.3
  ));

  return {
    need: Math.round(need * 10) / 10,
    tolerance: Math.round(avgTolerance * 10) / 10,
    compliance: Math.round(compliance * 10) / 10,
    volatility: Math.round(volatility * 10) / 10,
    fragility: Math.round(fragility * 10) / 10,
    loyalty: Math.round(loyalty * 10) / 10,
    clarity: Math.round(clarity * 10) / 10,
  };
}

// ─── Travel Event Refactor ───────────────────────────────────────────────────
