'use client'

import { useEffect } from 'react'
import { useRouter, usePathname } from 'next/navigation'
import { haptic } from '@/lib/haptics'
import { WIPE_HINT_KEY } from '@/lib/wipe-direction'

const MIN_X = 70
const MAX_Y = 40
const MAX_MS = 600
const EDGE = 24 // leave the OS back/forward edge gestures alone
const SKIP = 'input, textarea, select, [contenteditable="true"], [data-no-swipe], [role="slider"]'

function scrollsSideways(el: Element | null): boolean {
  for (let n = el; n && n !== document.body; n = n.parentElement) {
    const ox = getComputedStyle(n).overflowX
    if ((ox === 'auto' || ox === 'scroll') && n.scrollWidth > n.clientWidth + 1) return true
  }
  return false
}

/** Touch-only: horizontal swipe moves to the next/previous nav page. The laser wipe follows the finger. */
export function SwipeNav({ hrefs }: { hrefs: string[] }) {
  const router = useRouter()
  const pathname = usePathname()

  useEffect(() => {
    const index = hrefs.indexOf(pathname)
    if (index < 0 || hrefs.length < 2) return
    let start: { x: number; y: number; t: number } | null = null

    const onStart = (e: TouchEvent) => {
      const t = e.touches[0]
      if (e.touches.length !== 1 || !t) { start = null; return }
      const target = e.target instanceof Element ? e.target : null
      if (t.clientX < EDGE || t.clientX > window.innerWidth - EDGE || target?.closest(SKIP) || scrollsSideways(target)) { start = null; return }
      start = { x: t.clientX, y: t.clientY, t: performance.now() }
    }
    const onEnd = (e: TouchEvent) => {
      const t = e.changedTouches[0]
      if (!start || !t) return
      const dx = t.clientX - start.x
      const dy = Math.abs(t.clientY - start.y)
      const quick = performance.now() - start.t <= MAX_MS
      start = null
      if (!quick || dy > MAX_Y || Math.abs(dx) < MIN_X) return
      const next = dx < 0 ? index + 1 : index - 1
      if (next < 0 || next >= hrefs.length) { haptic('error'); return }
      // Finger moved left → beam sweeps right-to-left (reverse); finger right → left-to-right
      try { sessionStorage.setItem(WIPE_HINT_KEY, dx < 0 ? 'reverse' : 'forward') } catch {}
      haptic('press')
      router.push(hrefs[next])
    }
    const onCancel = () => { start = null }

    window.addEventListener('touchstart', onStart, { passive: true })
    window.addEventListener('touchend', onEnd, { passive: true })
    window.addEventListener('touchcancel', onCancel, { passive: true })
    return () => {
      window.removeEventListener('touchstart', onStart)
      window.removeEventListener('touchend', onEnd)
      window.removeEventListener('touchcancel', onCancel)
    }
  }, [hrefs, pathname, router])

  return null
}

