'use client'

import { useCallback, useEffect, useRef, useState, useSyncExternalStore } from 'react'
import { createPortal } from 'react-dom'
import { useReducedMotion } from 'framer-motion'
import { useHud } from './hud-context'
import type { TabId } from './tab-navigator'
import styles from './vip-lock.module.css'

// ============================================================
// CONFIG — the VIP key phrase. Change this ONE line and nothing else.
// Comparison is trimmed and case-insensitive.
export const VIP_PASSWORD = 'BASELINE'
// ============================================================
//
// PRESENTATIONAL GATE ONLY. This is a client-side check that hides the VIP
// page from casual visitors. True confidentiality requires server-side access
// control. Never describe this lock as "secure" in user-facing copy.

const STORAGE_KEY = 'bmf3k_vip_unlocked'
const UNLOCK_EVENT = 'bmf3k:vip-unlock'

// Session persistence — unlock survives in-app navigation, nothing beyond the tab session.
function subscribe(cb: () => void) {
  window.addEventListener(UNLOCK_EVENT, cb)
  window.addEventListener('storage', cb)
  return () => {
    window.removeEventListener(UNLOCK_EVENT, cb)
    window.removeEventListener('storage', cb)
  }
}
function readUnlocked() {
  try { return sessionStorage.getItem(STORAGE_KEY) === '1' } catch { return false }
}
function persistUnlocked() {
  try { sessionStorage.setItem(STORAGE_KEY, '1') } catch { /* storage unavailable — unlock holds for this render only */ }
  window.dispatchEvent(new Event(UNLOCK_EVENT))
}

type LockState = 'standby' | 'reject' | 'confirm' | 'unlocking'

const MESSAGES: Record<LockState, string> = {
  standby: 'AWAITING INPUT',
  reject: 'MISMATCH — RE-ENTER KEY PHRASE',
  confirm: 'GREEN BAND CONFIRMED — ACCESS',
  unlocking: 'GREEN BAND CONFIRMED — ACCESS',
}
const LAMP: Record<LockState, string> = { standby: 'STANDBY', reject: 'MISMATCH', confirm: 'ACCESS', unlocking: 'ACCESS' }

// Dismantle timing (ms). Reduced motion swaps the whole sequence for a crossfade.
const HOLD_MS = 450
const DISMANTLE_MS = 2000
const CROSSFADE_MS = 450

// ---------------------------------------------------------------------------
// VIP SHELL — "PHASE: MANAGED DECLINE". Always rendered beneath the lock so the
// dismantle lifts straight onto it. Content arrives in a later handover.
// ---------------------------------------------------------------------------

const VIP_SLOTS = [
  { id: 'budget', label: 'BUDGET', index: '01' },
  { id: 'next-steps', label: 'NEXT STEPS TO SUCCESS', index: '02' },
  { id: 'dependency-economy', label: 'DEPENDENCY ECONOMY', index: '03' },
] as const

function VipShell({ revealed }: { revealed: boolean }) {
  return (
    <section className={styles.shell} data-revealed={revealed ? '' : undefined} aria-hidden={!revealed}>
      <header className={styles.shellHeader}>
        <span className={styles.shellStamp}>STATION +2 / VIP</span>
        <h1 className={styles.shellTitle}>PHASE: MANAGED DECLINE</h1>
        <p className={styles.shellSub}>Production planning — for the filmmaking team</p>
      </header>

      <div className={styles.slots}>
        {VIP_SLOTS.map((slot) => (
          /* CONTENT SLOT: {slot.label}. Empty Overlay-styled frame. Real copy lands
             in a later handover — nothing is written or invented here. */
          <article key={slot.id} className={styles.slot} data-slot={slot.id} aria-label={`${slot.label} — reserved`}>
            {/* data-overlay-slot: sprite-kit bracket set drops in here without rework */}
            <span className={styles.slotBrackets} data-overlay-slot="vip-slot-brackets" aria-hidden="true">
              <i data-corner="tl" /><i data-corner="tr" /><i data-corner="bl" /><i data-corner="br" />
            </span>
            <header className={styles.slotHead}>
              <span>{slot.index}</span>
              <h2>{slot.label}</h2>
            </header>
            <div className={styles.slotBody} />
            <footer className={styles.slotFoot}>RESERVED</footer>
          </article>
        ))}
      </div>
