}

// ---------------------------------------------------------------------------
// THE LOCK — the Manager's instrument panel. Three real instruments only:
// key phrase verification meter, Green Band gauge, status lamp.
// ---------------------------------------------------------------------------

interface LockProps {
  onUnlocked: () => void
  onExit: () => void
}

function OverlayLock({ onUnlocked, onExit }: LockProps) {
  const reducedMotion = useReducedMotion()
  const hud = useHud()
  const [value, setValue] = useState('')
  const [state, setState] = useState<LockState>('standby')
  const [pinned, setPinned] = useState(false) // meters pinned to zero during dismantle
  const inputRef = useRef<HTMLInputElement>(null)
  const rejectTimer = useRef<number | null>(null)
  const stateRef = useRef(state)
  stateRef.current = state

  // Verification meter — advances with each keystroke toward the expected length.
  const verifyPct = pinned ? 0 : Math.min(100, Math.round((value.length / VIP_PASSWORD.length) * 100))

  useEffect(() => {
    inputRef.current?.focus()
    return () => { if (rejectTimer.current) window.clearTimeout(rejectTimer.current) }
  }, [])

  const clearInput = useCallback(() => {
    setValue('')
    setState('standby')
    inputRef.current?.focus()
  }, [])

  const attempt = useCallback(() => {
    if (stateRef.current === 'unlocking' || stateRef.current === 'confirm') return
    const entered = value.trim().toUpperCase()
    if (entered === VIP_PASSWORD.trim().toUpperCase()) {
      setState('confirm')
      hud.pulse('lock')
      hud.note('GREEN BAND CONFIRMED')
      const start = window.setTimeout(() => {
        setState('unlocking')
        if (!reducedMotion) hud.triggerScan()
        if (reducedMotion) setPinned(true)
        else window.setTimeout(() => setPinned(true), 350)
        window.setTimeout(() => {
          persistUnlocked()
          onUnlocked()
        }, reducedMotion ? CROSSFADE_MS : DISMANTLE_MS)
      }, HOLD_MS)
      rejectTimer.current = start
    } else {
      setState('reject')
      setValue('')
      hud.pulse('tick')
      hud.note('MISMATCH')
      inputRef.current?.focus()
      if (rejectTimer.current) window.clearTimeout(rejectTimer.current)
      rejectTimer.current = window.setTimeout(() => {
        if (stateRef.current === 'reject') setState('standby')
      }, 1800)
    }
  }, [value, hud, reducedMotion, onUnlocked])

  const busy = state === 'confirm' || state === 'unlocking'
  const gauge = state === 'reject' ? 'out' : busy ? 'full' : 'band'

  return (
    <div
      className={styles.lock}
      data-state={state}
      data-motion={reducedMotion ? 'reduced' : 'full'}
      role="dialog"
      aria-modal="true"
      aria-labelledby="vip-lock-title"
    >
      {/* Idle scanline drift; becomes the top-to-bottom wipe during dismantle. */}
      <div className={styles.scanlines} aria-hidden="true" />
      <div className={styles.wipe} aria-hidden="true" />

      {/* Chassis — physical instrument body. data-overlay-slot marks sprite-kit drop points. */}
      <div className={styles.chassis} data-overlay-slot="lock-chassis">
        <span className={styles.corner} data-corner="tl" data-overlay-slot="lock-corner" aria-hidden="true" />
        <span className={styles.corner} data-corner="br" data-overlay-slot="lock-corner" aria-hidden="true" />

        <header className={styles.statusBar} data-panel="top">
          <span className={styles.stamp}>3K OVERLAY</span>
          <span className={styles.lamp} data-state={state} role="status" aria-live="polite">
            <i aria-hidden="true" />{LAMP[state]}
          </span>
          <button type="button" className={styles.exit} onClick={onExit} aria-label="Return to the route">
            ◀ ROUTE
          </button>
        </header>

        <h1 id="vip-lock-title" className={styles.title} data-panel="title">KEY PHRASE VERIFICATION</h1>

        <div className={styles.cluster}>
          {/* GREEN BAND gauge — steady in band; pins full on unlock; snaps out on rejection. */}
          <div className={styles.gaugePanel} data-panel="gauge" data-gauge={gauge}>
            <div className={styles.gaugeLabel}>GREEN BAND</div>
            <div className={styles.gaugeTrack} aria-hidden="true">
              <span className={styles.gaugeBand} />
              <span className={styles.gaugeFill} />
              <span className={styles.gaugeNeedle} />
            </div>
            <div className={styles.caliper} aria-hidden="true" />
            <div className={styles.gaugeReadout} aria-live="polite">
              {gauge === 'band' ? 'IN BAND' : gauge === 'full' ? 'PINNED FULL' : 'OUT OF BAND'}
            </div>
          </div>

          {/* Key phrase input + verification meter */}
          <form
            className={styles.inputPanel}
            data-panel="input"
            onSubmit={(e) => { e.preventDefault(); attempt() }}
          >
            <label htmlFor="vip-key-phrase" className={styles.inputLabel}>ENTER KEY PHRASE</label>
            <div className={styles.readoutFrame} onClick={() => inputRef.current?.focus()}>
              <input
                ref={inputRef}
                id="vip-key-phrase"
                className={styles.input}
                type="text"
                value={value}
                onChange={(e) => {
                  setValue(e.target.value)
                  if (stateRef.current === 'reject') setState('standby')
                }}
                onKeyDown={(e) => {
                  if (e.key === 'Escape') { e.preventDefault(); clearInput() }
                }}
                disabled={busy}
                autoComplete="off"
                autoCorrect="off"
                autoCapitalize="characters"
                spellCheck={false}
                maxLength={32}
                aria-describedby="vip-lock-message"
                data-hud-control
              />
              <span className={styles.cursor} aria-hidden="true" />
            </div>

            <div className={styles.verify}>
              <span className={styles.verifyLabel}>KEY PHRASE VERIFICATION</span>
              <div className={styles.verifyTrack} role="progressbar" aria-valuemin={0} aria-valuemax={100} aria-valuenow={verifyPct} aria-label="Key phrase verification">
                <span className={styles.verifyFill} style={{ width: `${verifyPct}%` }} />
              </div>
              <span className={styles.verifyPct}>{verifyPct}%</span>
            </div>

            <div id="vip-lock-message" className={styles.message} aria-live="polite">
              {MESSAGES[state]}
            </div>

            <button type="submit" className={styles.submit} disabled={busy}>
              VERIFY
            </button>
          </form>
        </div>

        <footer className={styles.footer} data-panel="bottom">
          <span className={styles.stamp}>MANAGER INSTRUMENT PANEL</span>
          <span className={styles.stamp}>STATION +2 / VIP</span>
        </footer>
      </div>
    </div>
  )
}

// ---------------------------------------------------------------------------
// STATION — the VIP pane. Lock is portalled full-screen above the app shell
// while locked; the shell beneath is already rendered so the reveal never
// flashes blank.
// ---------------------------------------------------------------------------

export function VipStation({ goTo }: { goTo: (id: TabId) => void }) {
  const unlocked = useSyncExternalStore(subscribe, readUnlocked, () => false)
  const [mounted, setMounted] = useState(false)
  const [revealed, setRevealed] = useState(false)
  useEffect(() => { setMounted(true) }, [])
  useEffect(() => { if (unlocked) setRevealed(true) }, [unlocked])

  return (
    <div className={styles.station}>
      <VipShell revealed={revealed || unlocked} />
      {mounted && !unlocked && createPortal(
        <OverlayLock onUnlocked={() => setRevealed(true)} onExit={() => goTo('hero')} />,
        document.body,
      )}
    </div>
  )
}

