  Dave: '#8aad7a', Sid: '#a8687e', Tamara: '#7ab8b8', Mikey: '#b0926a',
};

const PREF_LABELS: Record<number, { text: string; color: string }> = {
  2:  { text: 'CRAVING', color: '#a9c98a' },
  1:  { text: 'WANTS IT', color: '#8aad7a' },
  0:  { text: 'NEUTRAL', color: '#776b55' },
};
PREF_LABELS[-1] = { text: 'DISLIKES', color: '#c79a5a' };
PREF_LABELS[-2] = { text: 'HATES THIS', color: '#FF5E57' };

const ZONE_LABELS: Record<CrewZone, string> = {
  GREEN: 'FUNCTIONAL',
  YELLOW: 'UNSTABLE',
  RED: 'CRITICAL',
};

const ZONE_DESCS: Record<CrewZone, string> = {
  GREEN: 'Operational. Available for expeditions.',
  YELLOW: 'Needs attention. Drifting toward unreliable.',
  RED: 'Dangerous. Refuses expeditions. Volatile.',
};

const SHIFT_ICONS = {
  IMPROVE: TrendingUp,
  WORSEN: TrendingDown,
  STABLE: Minus,
};

const SHIFT_COLORS = {
  IMPROVE: '#8aad7a',
  WORSEN: '#FF5E57',
  STABLE: '#776b55',
};

/** Cast GameNPC to the NpcRow shape expected by ui-model. Fields are 1:1 compatible. */
function toNpcRow(npc: GameNPC) {
  return npc as unknown as Parameters<typeof previewDose>[0];
}

function DoseStation({ game, escalation, onBack, onRefresh, showNotification, embedded }: Props) {
  const [selectedNpcIdx, setSelectedNpcIdx] = useState(0);
  const [dosing, setDosing] = useState(false);
  const [hoveredSubstance, setHoveredSubstance] = useState<string | null>(null);
  const [lastResult, setLastResult] = useState<{
    reaction: string;
    narrative: string;
    zoneShift: 'IMPROVE' | 'WORSEN' | 'STABLE';
    projectedZone: CrewZone;
  } | null>(null);

  const recruitedNpcs = useMemo(
    () => (game?.npcs ?? []).filter((n) => n?.recruited),
    [game?.npcs]
  );
  const resources = game?.resources ?? [];
  const npc = recruitedNpcs[selectedNpcIdx] ?? null;
  const npcName = (npc?.name ?? '').toLowerCase() as NPCKey;
  const npcData = NPC_DATA?.[npcName];
  const npcColor = NPC_COLORS[npc?.name ?? ''] ?? '#8aad7a';

  // Build NpcRow for ui-model functions
  const npcRow = useMemo(() => npc ? toNpcRow(npc) : null, [npc]);

  // Current zone
  const currentZone = useMemo(() => {
    if (!npcRow) return 'GREEN' as CrewZone;
    return getZoneFromActor(computeActorState(npcRow));
  }, [npcRow]);

  // Current mood
  const currentMood = useMemo(() => {
    if (!npcRow) return 'STABLE';
    return getActorMood(computeActorState(npcRow));
  }, [npcRow]);

  // Live dose preview for hovered substance
  const dosePreview = useMemo((): DosePreviewType | null => {
    if (!hoveredSubstance || !npcRow || !npcData?.vice) return null;
    const pref = npcData.vice.preferences[hoveredSubstance as ResourceKey] ?? 0;
    const isCraving = npcData.vice.cravings.includes(hoveredSubstance as ResourceKey);
    try {
      return previewDose(npcRow, pref, isCraving);
    } catch {
      return null;
    }
  }, [hoveredSubstance, npcRow, npcData]);

  // Get tolerance for a substance
  const getTolerance = useCallback((type: string): number => {
    if (!npc) return 0;
    switch (type) {
      case 'cigarettes': return npc.toleranceCigs ?? 0;
      case 'alcohol': return npc.toleranceAlc ?? 0;
      case 'weed': return npc.toleranceWeed ?? 0;
      case 'crystals': return npc.toleranceCryst ?? 0;
      default: return 0;
    }
  }, [npc]);

  const doAdminister = useCallback(async (resourceType: string) => {
    if (!npc || dosing) return;
    const resource = resources.find((r) => r?.type === resourceType);
    if (!resource || resource.quantity < 1) {
      showNotification('Out of stock.');
      return;
    }

    setDosing(true);
    setLastResult(null);
    setHoveredSubstance(null);
    try {
      const res = await fetch('/api/game/encounter', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          sessionId: game?.sessionId,
          action: 'dose',
          npcId: npc.id,
          npcKey: npcName,
          resourceType,
        }),
      });
      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        showNotification(err?.error ?? 'Dose failed.');
        audioManager.playSFX('error');
      } else {
        const data = await res.json();
        const dose = data?.dose;
        const reaction = dose?.reaction ?? 'NO_EFFECT';
        const narrative = dose?.narrative ?? 'Nothing happened.';

        // Compute post-dose zone shift
        let zoneShift: 'IMPROVE' | 'WORSEN' | 'STABLE' = 'STABLE';
        let projectedZone = currentZone;
        if (npcRow && npcData?.vice) {
          const pref = npcData.vice.preferences[resourceType as ResourceKey] ?? 0;
          const isCraving = npcData.vice.cravings.includes(resourceType as ResourceKey);
          try {
            const preview = previewDose(npcRow, pref, isCraving);
            zoneShift = preview.zoneShift;
            projectedZone = preview.projectedZone;
          } catch { /* use defaults */ }
        }

        setLastResult({ reaction, narrative, zoneShift, projectedZone });

        if (reaction === 'RELIEF' || reaction === 'GRATITUDE') {
          audioManager.playSFX('confirm');
        } else if (reaction === 'WRONG_SUBSTANCE' || reaction === 'REFUSED') {
          audioManager.playSFX('error');
        } else {
          audioManager.playSFX('nav');
        }
        await onRefresh();
      }
    } catch (err: unknown) {
      console.error('Dose error:', err);
      showNotification('Dose failed. Network error.');
      audioManager.playSFX('error');
    } finally {
      setDosing(false);
    }
  }, [npc, npcName, npcRow, npcData, dosing, resources, game?.sessionId, currentZone, onRefresh, showNotification]);

  // ─── Empty State ─────────────────────────────────────────────
  if (recruitedNpcs.length === 0) {
    return (
      <div className="w-full h-full flex flex-col bg-[#080807]">
        {!embedded && (
          <div className="flex items-center gap-3 px-4 py-3 bg-[#0a0a08] border-b-2 border-[#a8687e]/10">
            <button onClick={() => { audioManager.playSFX('nav'); onBack?.(); }} aria-label="Back to hub" className="text-[#a8687e] hover:text-[#a8687e]/80 transition cursor-pointer min-w-[44px] min-h-[44px] flex items-center justify-center">
              <ArrowLeft size={20} />
            </button>
            <h2 className="font-terminal text-lg" style={{ color: '#a8687e' }}>DOSE CONSOLE</h2>
          </div>
        )}
        <div className="flex-1 flex items-center justify-center">
          <div className="text-center">
            <Pill size={32} className="mx-auto mb-3 opacity-15" style={{ color: '#a8687e' }} />
            <p className="font-terminal text-sm" style={{ color: 'rgba(255,20,147,0.3)' }}>NO CREW TO DOSE</p>
            <p className="text-[10px] text-[#4a4a3a] mt-1">Recruit someone first.</p>
          </div>
        </div>
      </div>
    );
  }

  // ─── Active preview zone (hovered or last result)
  const previewZone = dosePreview?.projectedZone ?? lastResult?.projectedZone ?? null;
  const previewShift = dosePreview?.zoneShift ?? lastResult?.zoneShift ?? null;
  const displayZone = previewZone ?? currentZone;
  const isPreviewActive = !!dosePreview;

  return (
    <div className="w-full h-full flex flex-col bg-[#080807]">
      {/* ─── Header (hidden when embedded in Stash) ─── */}
      {!embedded && (
        <div className="flex items-center gap-3 px-4 py-3 bg-[#0a0a08] border-b-2 border-[#a8687e]/15">
          <button
            onClick={() => { audioManager.playSFX('nav'); onBack?.(); }}
            aria-label="Back to hub"
            className="text-[#a8687e] hover:text-[#a8687e]/80 transition cursor-pointer active:scale-90 min-w-[44px] min-h-[44px] flex items-center justify-center"
          >
            <ArrowLeft size={20} />
          </button>
          <div className="flex-1">
            <p className="font-terminal text-[9px] tracking-[0.3em]" style={{ color: 'rgba(255,20,147,0.3)' }}>PRE-RUN CALIBRATION</p>
            <h2 className="font-terminal text-lg -mt-0.5" style={{ color: '#a8687e' }}>DOSE CONSOLE</h2>
          </div>
          {/* Crew zone summary dots */}
          <div className="flex items-center gap-1.5">
            {recruitedNpcs.map((n, i) => {
              const row = toNpcRow(n);
              const z = getZoneFromActor(computeActorState(row));
              return (
                <div
                  key={n?.id ?? i}
                  className="w-3 h-3 rounded-full border"
                  style={{
                    backgroundColor: `${ZONE_HEX[z]}20`,
                    borderColor: `${ZONE_HEX[z]}60`,
                    boxShadow: `0 0 4px ${ZONE_HEX[z]}30`,
                  }}
                  title={`${n?.name}: ${z}`}
                />
              );
            })}
          </div>
        </div>
      )}

      {/* ─── Main Layout ─── */}
      <div className="flex-1 grid grid-cols-1 md:grid-cols-[300px_1fr] overflow-hidden">
        {/* ═══ LEFT PANEL: Crew Cards ═══ */}
        <div className="bg-[#0e0c08] border-r-2 border-[#a8687e]/5 overflow-y-auto">
          {/* NPC selector tabs */}
          <div className="flex border-b border-[#a8687e]/8">
            {recruitedNpcs.map((n, idx: number) => {
              const c = NPC_COLORS[n?.name ?? ''] ?? '#8aad7a';
              const active = idx === selectedNpcIdx;
              const row = toNpcRow(n);
              const z = getZoneFromActor(computeActorState(row));
              return (
                <button
                  key={n?.id ?? idx}
                  onClick={() => { audioManager.playSFX('nav'); setSelectedNpcIdx(idx); setLastResult(null); setHoveredSubstance(null); }}
                  className={`flex-1 py-2.5 font-terminal text-[10px] tracking-wider transition-all border-b-2 relative ${
                    active ? 'bg-[#a8687e]/[0.03]' : 'hover:bg-[#a8687e]/[0.01]'
                  }`}
                  style={{
                    borderBottomColor: active ? c : 'transparent',
                    color: active ? c : '#4a4a3a',
                  }}
                >
                  {n?.name?.toUpperCase?.() ?? '???'}
                  {/* Zone dot under name */}
                  <span
                    className="absolute bottom-1 left-1/2 -translate-x-1/2 w-1.5 h-1.5 rounded-full"
                    style={{ backgroundColor: ZONE_HEX[z] }}
                  />
                </button>
              );
            })}
          </div>

          {npc && npcRow && (
            <div className="p-4 space-y-4">
              {/* Portrait */}
              <div className="relative w-full aspect-[3/4] bg-[#1a1710] overflow-hidden" style={{ borderRadius: '4px' }}>
                <Image
                  src={npc?.portraitUrl || '/images/dave-portrait-v2-crop.png'}
                  alt={npc?.name ?? 'NPC'}
                  fill
                  sizes="300px"
                  className="object-cover"
                  style={{ filter: 'saturate(0.85) contrast(1.05)' }}
                />
                <div className="absolute inset-0 bg-gradient-to-t from-[#0e0c08] via-transparent to-transparent" />
                {/* CRT scanlines */}
                <div className="absolute inset-0 pointer-events-none" style={{
                  background: 'repeating-linear-gradient(0deg, transparent, transparent 2px, rgba(0,0,0,0.08) 2px, rgba(0,0,0,0.08) 4px)',
                }} />
              </div>

              {/* Identity + Zone Badge */}
              <div className="flex justify-between items-start">
                <div>
                  <h3 className="font-terminal text-base" style={{ color: npcColor }}>{npc?.name ?? '???'}</h3>
                  <p className="text-[10px] text-[#a99775] font-typewriter">{npcData?.role ?? npc?.archetype ?? ''}</p>
                </div>
                {/* Zone badge */}
                <div
                  className="px-2.5 py-1 font-terminal text-[9px] tracking-wider flex items-center gap-1.5"
                  style={{
                    border: `1px solid ${ZONE_HEX[displayZone]}40`,
                    borderRadius: '4px',
                    backgroundColor: `${ZONE_HEX[displayZone]}08`,
                    color: ZONE_HEX[displayZone],
                    transition: 'all 0.3s ease',
                  }}
                >
                  <span
                    className="w-2 h-2 rounded-full"
                    style={{
                      backgroundColor: ZONE_HEX[displayZone],
                      boxShadow: `0 0 6px ${ZONE_HEX[displayZone]}60`,
                    }}
                  />
                  {isPreviewActive ? (
                    <span className="animate-pulse">{ZONE_LABELS[displayZone]}</span>
                  ) : (
                    ZONE_LABELS[displayZone]
                  )}
                </div>
              </div>

              {/* Zone description */}
              <p className="text-[9px] font-typewriter" style={{ color: `${ZONE_HEX[currentZone]}80` }}>
                {ZONE_DESCS[currentZone]}
              </p>

              {/* Zone shift preview (appears on hover) */}
              <AnimatePresence mode="wait">
                {dosePreview && (
                  <motion.div
                    initial={{ opacity: 0, height: 0 }}
                    animate={{ opacity: 1, height: 'auto' }}
                    exit={{ opacity: 0, height: 0 }}
                    className="overflow-hidden"
                  >
                    <div
                      className="p-3 space-y-2"
                      style={{
                        borderRadius: '6px',
                        border: `1px solid ${SHIFT_COLORS[dosePreview.zoneShift]}25`,
                        background: `${SHIFT_COLORS[dosePreview.zoneShift]}06`,
                      }}
                    >
                      <div className="flex items-center gap-2">
                        {(() => {
                          const ShiftIcon = SHIFT_ICONS[dosePreview.zoneShift];
                          return <ShiftIcon size={12} style={{ color: SHIFT_COLORS[dosePreview.zoneShift] }} />;
                        })()}
                        <span className="font-terminal text-[10px] tracking-wider" style={{ color: SHIFT_COLORS[dosePreview.zoneShift] }}>
                          PROJECTED: {dosePreview.zoneShift}
                        </span>
                      </div>
                      {/* Zone transition arrow */}
                      <div className="flex items-center gap-2 text-[10px] font-terminal">
                        <span style={{ color: ZONE_HEX[dosePreview.currentZone] }}>{dosePreview.currentZone}</span>
                        <span className="text-[#4a4a3a]">→</span>
                        <span style={{ color: ZONE_HEX[dosePreview.projectedZone] }}>{dosePreview.projectedZone}</span>
                      </div>
                      <p className="text-[9px] text-[#a99775]/70 font-typewriter italic">
                        {dosePreview.predictedNarrative}
                      </p>
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>

              {/* Tolerance bars */}
              <div className="space-y-1.5">
                <p className="font-terminal text-[9px] tracking-wider text-[#776b55] mb-1">TOLERANCE PROFILE</p>
                {(['cigarettes', 'alcohol', 'weed', 'crystals'] as const).map((type) => {
                  const tol = getTolerance(type);
                  const pref = npcData?.vice?.preferences?.[type] ?? 0;
                  const cfg = SUBSTANCE_CONFIG[type];
                  const Icon = cfg.icon;
                  const prefLabel = PREF_LABELS[pref] ?? PREF_LABELS[0];
                  const isHighTol = tol >= 6;
                  return (
                    <div key={type}>
                      <div className="flex items-center justify-between text-[9px] font-terminal mb-0.5">
                        <div className="flex items-center gap-1.5">
                          <Icon size={10} color={cfg.color} />
                          <span className="text-[#a99775]/60">{cfg.label}</span>
                        </div>
                        <span style={{ color: prefLabel.color, fontSize: '8px' }}>{prefLabel.text}</span>
                      </div>
                      <div className="h-[5px] bg-[#1a1a0a] relative" style={{ borderRadius: '2px' }}>
                        <div
                          className="absolute inset-y-0 left-0 transition-all duration-300"
                          style={{
                            width: `${Math.min(100, (tol / 10) * 100)}%`,
                            backgroundColor: isHighTol ? '#FF5E57' : cfg.color,
                            borderRadius: '2px',
                            opacity: 0.7,
                          }}
                        />
                      </div>
                    </div>
                  );
                })}
                <p className="text-[8px] text-[#4a4a3a] font-typewriter mt-1">
                  Tolerance drifts daily. Over-dosing spikes it harder.
                </p>
              </div>
            </div>
          )}
        </div>

        {/* ═══ RIGHT PANEL: Dose Console ═══ */}
        <div className="overflow-y-auto p-4 sm:p-6">
          {/* Dose band visualization */}
          <div className="mb-6">
            <h3 className="font-terminal text-sm tracking-wider mb-1" style={{ color: '#a8687e' }}>DOSE BAND</h3>
            <p className="text-[10px] text-[#776b55] font-typewriter mb-4">
              Keep crew in the green band. Under-dosing leaves them volatile. Over-dosing takes them offline.
            </p>

            {/* 3-band visual bar */}
            <div className="relative h-10 flex" style={{ borderRadius: '6px', overflow: 'hidden', border: '1px solid rgba(255,255,255,0.04)' }}>
              {/* RED band */}
              <div className="flex-1 flex items-center justify-center relative" style={{ background: 'rgba(248,113,113,0.08)' }}>
                <span className="font-terminal text-[9px] tracking-wider" style={{ color: currentZone === 'RED' && !isPreviewActive ? '#f87171' : '#f8717130' }}>
                  RED
                </span>
                {currentZone === 'RED' && !isPreviewActive && (
                  <motion.div
                    className="absolute bottom-0 left-0 right-0 h-[2px]"
                    style={{ backgroundColor: '#f87171' }}
                    layoutId="zone-indicator"
                  />
                )}
              </div>
              {/* Divider */}
              <div className="w-px bg-white/5" />
              {/* GREEN band */}
              <div className="flex-[1.5] flex items-center justify-center relative" style={{ background: 'rgba(52,211,153,0.06)' }}>
                <span className="font-terminal text-[9px] tracking-wider" style={{ color: currentZone === 'GREEN' && !isPreviewActive ? '#34d399' : '#34d39930' }}>
                  FUNCTIONAL
                </span>
                {currentZone === 'GREEN' && !isPreviewActive && (
                  <motion.div
                    className="absolute bottom-0 left-0 right-0 h-[2px]"
                    style={{ backgroundColor: '#34d399' }}
                    layoutId="zone-indicator"
                  />
                )}
              </div>
              {/* Divider */}
              <div className="w-px bg-white/5" />
              {/* YELLOW band */}
              <div className="flex-1 flex items-center justify-center relative" style={{ background: 'rgba(251,191,36,0.06)' }}>
                <span className="font-terminal text-[9px] tracking-wider" style={{ color: currentZone === 'YELLOW' && !isPreviewActive ? '#fbbf24' : '#fbbf2430' }}>
                  OVER
                </span>
                {currentZone === 'YELLOW' && !isPreviewActive && (
                  <motion.div
                    className="absolute bottom-0 left-0 right-0 h-[2px]"
                    style={{ backgroundColor: '#fbbf24' }}
                    layoutId="zone-indicator"
                  />
                )}
              </div>

              {/* Preview indicator (appears on hover) */}
              {isPreviewActive && previewZone && (
                <motion.div
                  className="absolute bottom-0 h-[2px]"
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  style={{
                    backgroundColor: ZONE_HEX[previewZone],
                    boxShadow: `0 0 8px ${ZONE_HEX[previewZone]}60`,
                    left: previewZone === 'RED' ? '0%' : previewZone === 'GREEN' ? '28.5%' : '71.5%',
                    right: previewZone === 'RED' ? '71.5%' : previewZone === 'GREEN' ? '28.5%' : '0%',
                  }}
                />
              )}
            </div>

            {/* Current position marker */}
            <div className="flex items-center gap-2 mt-2">
              <Activity size={10} style={{ color: ZONE_HEX[currentZone] }} />
              <span className="font-terminal text-[9px]" style={{ color: ZONE_HEX[currentZone] }}>
                CURRENT: {ZONE_LABELS[currentZone]} ({currentMood})
              </span>
            </div>
          </div>

          {/* Dose result feedback */}
          <AnimatePresence mode="wait">
            {lastResult && (
              <motion.div
                key={lastResult.narrative}
                initial={{ opacity: 0, y: 8 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -4 }}
                className="p-4 mb-5"
                style={{
                  borderRadius: '6px',
                  background: `${SHIFT_COLORS[lastResult.zoneShift]}06`,
                  border: `1px solid ${SHIFT_COLORS[lastResult.zoneShift]}20`,
                }}
              >
                <div className="flex items-center gap-2 mb-1.5">
                  {(() => {
                    const ShiftIcon = SHIFT_ICONS[lastResult.zoneShift];
                    return <ShiftIcon size={14} style={{ color: SHIFT_COLORS[lastResult.zoneShift] }} />;
                  })()}
                  <span className="font-terminal text-xs tracking-wider" style={{ color: SHIFT_COLORS[lastResult.zoneShift] }}>
                    {lastResult.reaction.replace('_', ' ')}
                  </span>
                </div>
                <p className="text-xs text-[#f3e8cf]/70 font-typewriter">{lastResult.narrative}</p>
              </motion.div>
            )}
          </AnimatePresence>

          {/* ─── Substance Buttons ─── */}
          <div className="mb-3">
            <p className="font-terminal text-[9px] tracking-wider text-[#776b55] mb-3">SELECT SUBSTANCE</p>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
            {(['cigarettes', 'alcohol', 'weed', 'crystals'] as const).map((type) => {
              const cfg = SUBSTANCE_CONFIG[type];
              const Icon = cfg.icon;
              const resource = resources.find((r) => r?.type === type);
              const qty = resource?.quantity ?? 0;
              const isEmpty = qty < 1;
              const preference = npcData?.vice?.preferences?.[type] ?? 0;
              const isDangerous = preference <= -1;
              const isCraving = npcData?.vice?.cravings?.includes(type) ?? false;
              const prefLabel = PREF_LABELS[preference] ?? PREF_LABELS[0];

              return (
                <button
                  key={type}
                  onClick={() => doAdminister(type)}
                  onMouseEnter={() => { playHover(); setHoveredSubstance(type); }}
                  onMouseLeave={() => setHoveredSubstance(null)}
                  disabled={isEmpty || dosing}
                  className="group relative px-4 py-3.5 font-terminal text-left transition-all"
                  style={{
                    border: `1px solid ${isDangerous ? 'rgba(255,94,87,0.25)' : `${cfg.color}15`}`,
                    borderRadius: '6px',
                    background: hoveredSubstance === type ? `${cfg.color}08` : 'rgba(255,255,255,0.015)',
                    opacity: isEmpty || dosing ? 0.25 : 1,
                    cursor: isEmpty || dosing ? 'not-allowed' : 'pointer',
                  }}
                >
                  <div className="flex items-center gap-3">
                    <div
                      className="w-9 h-9 flex items-center justify-center"
                      style={{
                        borderRadius: '4px',
                        background: `${cfg.color}0a`,
                        border: `1px solid ${cfg.color}15`,
                      }}
                    >
                      <Icon size={18} color={cfg.color} />
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <span className="text-[11px] tracking-wider" style={{ color: isDangerous ? '#FF5E57' : cfg.color }}>
                          {cfg.label}
                        </span>
                        {isCraving && (
                          <span className="text-[7px] px-1 py-px tracking-wider" style={{
                            color: '#a9c98a',
                            border: '1px solid rgba(169,201,138,0.2)',
                            borderRadius: '2px',
                          }}>CRAVES</span>
                        )}
                      </div>
                      <div className="flex items-center justify-between mt-0.5">
                        <span className="text-[9px]" style={{ color: '#776b55' }}>Stock: {qty}</span>
                        <span className="text-[8px]" style={{ color: prefLabel.color }}>{prefLabel.text}</span>
                      </div>
                    </div>
                    {isDangerous && <AlertTriangle size={13} className="flex-shrink-0" style={{ color: '#FF5E57', opacity: 0.5 }} />}
                  </div>

                  {/* Tolerance micro-bar */}
                  <div className="mt-2 h-[3px] bg-[#1a1a0a] relative" style={{ borderRadius: '2px' }}>
                    <div
                      className="absolute inset-y-0 left-0"
                      style={{
                        width: `${Math.min(100, (getTolerance(type) / 10) * 100)}%`,
