'use client'

import Image from 'next/image'
import { useEffect, useRef, useState, type PointerEvent as RPointerEvent } from 'react'
import { haptic } from '@/lib/haptics'

export type GalleryImage = { id: string; url: string; width: number; height: number }

/** Fraction of the viewer width a swipe must travel to change image. */
const SWIPE_THRESHOLD = 0.15
/** Flick speed (px/ms) that changes image regardless of distance. */
const FLICK_SPEED = 0.45

interface Props {
  images: GalleryImage[] | null
  failed: boolean
  /** false while the halves slam shut: input ignored */
  live: boolean
  onExit: () => void
}

/** Full-width swipeable hero-art viewer shown behind the split banner. */
export function HeroGallery({ images, failed, live, onExit }: Props) {
  const [index, setIndex] = useState(0)
  const [dx, setDx] = useState(0)
  const [dragging, setDragging] = useState(false)
  const drag = useRef<{ id: number; x0: number; t0: number; w: number } | null>(null)
  const exitRef = useRef<HTMLButtonElement>(null)
  const count = images?.length ?? 0

  // Keep the index valid if the list changes underneath
  useEffect(() => {
    if (index > 0 && index >= count) setIndex(Math.max(0, count - 1))
  }, [count, index])

  useEffect(() => {
    exitRef.current?.focus({ preventScroll: true })
  }, [])

  const go = (next: number) => {
    const clamped = Math.max(0, Math.min(count - 1, next))
    if (clamped !== index) haptic('press')
    setIndex(clamped)
  }

  useEffect(() => {
    if (!live) return
    const onKey = (e: KeyboardEvent) => {
      const t = e.target as HTMLElement | null
      if (t?.closest('input, textarea, select, [contenteditable="true"]')) return
      if (e.key === 'ArrowRight') { e.preventDefault(); go(index + 1) }
      else if (e.key === 'ArrowLeft') { e.preventDefault(); go(index - 1) }
      else if (e.key === 'Escape') { e.preventDefault(); onExit() }
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  })

  const onDown = (e: RPointerEvent<HTMLDivElement>) => {
    if (!live || count < 2) return
    if (e.pointerType === 'mouse' && e.button !== 0) return
    if ((e.target as HTMLElement).closest('button, a')) return
    drag.current = { id: e.pointerId, x0: e.clientX, t0: performance.now(), w: e.currentTarget.offsetWidth || 1 }
    e.currentTarget.setPointerCapture(e.pointerId)
    setDragging(true)
  }
  const onMove = (e: RPointerEvent<HTMLDivElement>) => {
    const d = drag.current
    if (!d || d.id !== e.pointerId) return
    const raw = e.clientX - d.x0
    const atEdge = (index === 0 && raw > 0) || (index === count - 1 && raw < 0)
    setDx(atEdge ? raw * 0.3 : raw)
  }
  const onUp = (e: RPointerEvent<HTMLDivElement>) => {
    const d = drag.current
    if (!d || d.id !== e.pointerId) return
    drag.current = null
    setDragging(false)
    const raw = e.clientX - d.x0
    const speed = Math.abs(raw) / Math.max(1, performance.now() - d.t0)
    setDx(0)
    if (Math.abs(raw) >= d.w * SWIPE_THRESHOLD || (speed > FLICK_SPEED && Math.abs(raw) > 24)) go(index + (raw < 0 ? 1 : -1))
  }

  const pos = count ? `${String(index + 1).padStart(2, '0')} / ${String(count).padStart(2, '0')}` : '00 / 00'

  return (
    <div className="bv-gal" role="region" aria-roledescription="carousel" aria-label="Art gallery">
      {images === null && !failed ? (
        <div className="bv-gal-empty">
          <p className="bv-gal-kicker font-ibm">◈ HANGING THE ART…</p>
        </div>
      ) : count === 0 ? (
        <div className="bv-gal-empty">
          <p className="bv-gal-kicker font-ibm">{failed ? '◈ SIGNAL LOST' : '◈ GALLERY // EMPTY'}</p>
          <p className="bv-gal-title font-anton uppercase">{failed ? 'The wall went dark' : 'The walls are bare'}</p>
          <p className="bv-gal-sub font-ibm">{failed ? 'Could not reach the gallery. Exit and try again.' : 'No art hung yet. Check back.'}</p>
        </div>
      ) : (
        <div
          className={`bv-gal-viewport ${dragging ? 'is-dragging' : ''}`}
          onPointerDown={onDown}
          onPointerMove={onMove}
          onPointerUp={onUp}
          onPointerCancel={onUp}
        >
          <div className="bv-gal-track" style={{ transform: `translate3d(calc(${-index * 100}% + ${dx}px), 0, 0)` }}>
            {images!.map((img, i) => (
              <div
                key={img.id}
                className="bv-gal-slide"
                role="group"
                aria-roledescription="slide"
                aria-label={`${i + 1} of ${count}`}
                aria-hidden={i !== index || undefined}
              >
                <Image src={img.url} alt="" aria-hidden="true" fill unoptimized sizes="100vw" className="bv-gal-backdrop" draggable={false} loading="eager" />
                <Image
                  src={img.url}
                  alt={`Gallery artwork ${i + 1} of ${count}`}
                  fill
                  unoptimized
                  sizes="100vw"
                  className="bv-gal-img"
                  draggable={false}
                  loading="eager"
                />
              </div>
            ))}
          </div>
          {count > 1 && (
            <>
              <button type="button" className="bv-gal-arrow bv-gal-arrow--prev" onClick={() => go(index - 1)} disabled={!live || index === 0} aria-label="Previous artwork">←</button>
              <button type="button" className="bv-gal-arrow bv-gal-arrow--next" onClick={() => go(index + 1)} disabled={!live || index === count - 1} aria-label="Next artwork">→</button>
            </>
          )}
        </div>
      )}

      <div className="bv-gal-hud">
        {count > 0 && (
          <div className="bv-gal-pos font-ibm" aria-live="polite">
            <span>{pos}</span>
            <span className="bv-gal-bar" aria-hidden="true">
              <i style={{ width: `${((index + 1) / count) * 100}%` }} />
            </span>
          </div>
        )}
        <button ref={exitRef} type="button" className="bv-gal-exit font-oswald" onClick={onExit} disabled={!live}>
          ✕ EXIT
        </button>
      </div>
    </div>
  )
}

