'use client';

import { useState, useMemo, memo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ArrowLeft, Lock, Zap, Target, Shield } from 'lucide-react';
import { playDenied, playMissionStart } from '@/lib/sound-effects';
import { MISSION_DEFINITIONS, DIFFICULTY_COLORS, type MissionDefinition } from '@/lib/game-data';
import { RESOURCE_ICON_MAP, type ResourceKey, BoltIcon, CrosshairIcon, LockIcon } from '../icons/resource-icons';
import PosterPinup from '../ui/poster-pinup';
import type { EscalationState } from '@/lib/escalation';
import type { GameState } from '../game-client';
import { audioManager } from '@/app/_lib/audio-manager';

interface OperationsBoardProps {
  game: GameState;
  escalation: EscalationState;
  onBack: () => void;
  onRefresh: () => Promise<void>;
  showNotification: (msg: string) => void;
  onAscension?: () => void;
}

function OperationsBoard({
  game, escalation, onBack, onRefresh, showNotification, onAscension,
}: OperationsBoardProps) {
  const [selectedMission, setSelectedMission] = useState<string | null>(null);
  const [launching, setLaunching] = useState(false);

  const missions = game?.missions ?? [];
  const resources = game?.resources ?? [];
  const recruitedCount = (game?.npcs ?? []).filter((n) => n.recruited).length;

  const mainMissions = useMemo(() =>
    Object.values(MISSION_DEFINITIONS).filter(d => d.type === 'MAIN'),
  []);

  const getMissionStatus = (key: string): string => {
    const m = missions.find((mi) => mi.missionKey === key);
    return m?.status ?? 'LOCKED';
  };

  const getNarrativePhase = (key: string): number => {
    const m = missions.find((mi) => mi.missionKey === key);
    return m?.narrativePhase ?? 0;
  };

  const getResourceQty = (type: string): number => {
    const r = resources.find((res) => res.type === type);
    return r?.quantity ?? 0;
  };

  const canAfford = (cost: Record<string, number | undefined>): boolean => {
    return Object.entries(cost).every(([type, amount]) =>
      amount === undefined || getResourceQty(type) >= amount
    );
  };

  const handleStartMission = async (missionKey: string) => {
    if (!game?.sessionId || launching) return;
    const def = MISSION_DEFINITIONS[missionKey];
    if (!def) return;

    setLaunching(true);
    try {
      const res = await fetch('/api/game/mission', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ sessionId: game.sessionId, missionKey, action: 'start' }),
      });
      const data = await res.json();
      if (!res.ok) {
        audioManager.playSFX('error');
        showNotification(data?.error ?? 'Failed to start mission');
        return;
      }
      playMissionStart();
      showNotification(`${def.title} — INITIATED`);

      // Operations Board now owns story directives only.
      // Dumpster expeditions are launched from DISPATCH in the hub.
      await onRefresh();
    } catch (err) {
      audioManager.playSFX('error');
      showNotification('Mission start failed');
    } finally {
      setLaunching(false);
    }
  };

  const handleAdvanceMission = async (missionKey: string) => {
    if (!game?.sessionId) return;
    try {
      const res = await fetch('/api/game/mission', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ sessionId: game.sessionId, missionKey, action: 'advance' }),
      });
      if (res.ok) {
        audioManager.playSFX('confirm');
        await onRefresh();
      }
    } catch {}
  };

  const handleCompleteMission = async (missionKey: string) => {
    if (!game?.sessionId) return;
    try {
      const res = await fetch('/api/game/mission', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ sessionId: game.sessionId, missionKey, action: 'complete' }),
      });
      const data = await res.json();
      if (res.ok) {
        audioManager.playSFX('confirm');
        const def = MISSION_DEFINITIONS[missionKey];
        showNotification(`${def?.title ?? 'MISSION'} — COMPLETED. ${def?.rewards?.description ?? ''}`);
        await onRefresh();
        setSelectedMission(null);
        // Trigger ascension ending if the final mission is completed
        if (missionKey === 'ascension' && onAscension) {
          setTimeout(() => onAscension(), 2000);
          return;
        }
      } else {
        audioManager.playSFX('error');
        showNotification(data?.error ?? 'Completion failed');
      }
    } catch {}
  };

  const selectedDef = selectedMission ? MISSION_DEFINITIONS[selectedMission] : null;
  const selectedStatus = selectedMission ? getMissionStatus(selectedMission) : 'LOCKED';

  const renderCostTag = (type: string, amount: number) => {
    const have = getResourceQty(type);
    const cls = have >= amount ? 'affordable' : 'locked';
    const Icon = RESOURCE_ICON_MAP[type as ResourceKey];
    return (
      <span key={type} className={`resource-cost ${cls} inline-flex items-center gap-1`}>
        {Icon ? <Icon size={11} /> : <span>?</span>}
        {amount}
      </span>
    );
  };

  const renderMissionCard = (def: MissionDefinition) => {
    const status = getMissionStatus(def.key);
    const isLocked = status === 'LOCKED';
    const isActive = status === 'ACTIVE';
    const isCompleted = status === 'COMPLETED';
    const statusClass = isLocked ? 'mission-locked' : isActive ? 'mission-active' : isCompleted ? 'mission-completed' : 'mission-available';

    return (
      <motion.button
        key={def.key}
        initial={{ opacity: 0, x: -10 }}
        animate={{ opacity: 1, x: 0 }}
        className={`mission-card ${statusClass} w-full text-left p-3 cursor-pointer`}
        onClick={() => { isLocked ? playDenied() : audioManager.playSFX('nav'); setSelectedMission(def.key); }}
        style={{ borderLeftColor: isActive ? DIFFICULTY_COLORS[def.difficulty] : undefined }}
      >
        <div className="flex items-center justify-between mb-1">
          <span className="stamped-text text-xs">{def.codename}</span>
          <span className="flex items-center gap-1">
            {isLocked && <Lock size={12} className="text-[var(--text-dim)]" />}
            {isActive && <Zap size={12} style={{ color: DIFFICULTY_COLORS[def.difficulty] }} />}
            {isCompleted && <Shield size={12} className="text-[var(--copper-patina)]" />}
          </span>
        </div>
        <div className="font-terminal text-sm" style={{ color: isLocked ? 'var(--text-dim)' : 'var(--text-primary)' }}>
          {def.title}
        </div>
        <div className="text-xs mt-1" style={{ color: 'var(--text-muted)' }}>
          {isCompleted ? '✓ COMPLETED' : isActive ? `PHASE ${getNarrativePhase(def.key)}/${def.narrativePhases}` : def.briefing.substring(0, 60) + (def.briefing.length > 60 ? '...' : '')}
        </div>
        {!isLocked && !isCompleted && (
          <div className="flex gap-1 mt-2 flex-wrap">
            {Object.entries(def.cost).map(([type, amt]) =>
              amt ? renderCostTag(type, amt) : null
            )}
          </div>
        )}
      </motion.button>
    );
  };

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      className="w-full h-full flex flex-col relative"
    >
      {/* Briefing room propaganda — wall pinup, top-right */}
      <div className="absolute hidden lg:block pointer-events-none z-[1] top-20 right-3 xl:right-6">
        <PosterPinup seed={(game?.day ?? 1) + 5} widthClass="w-24 xl:w-28" opacity={0.3} rotate={4} sepia={0.55} />
      </div>

      {/* Header */}
      <div className="brushed-steel p-3 flex items-center gap-3 relative z-10">
        <button
          onClick={() => { audioManager.playSFX('nav'); onBack(); }}
          aria-label="Go back to hub"
          className="text-[var(--copper-bright)] hover:text-[var(--cig-yellow)] transition-colors cursor-pointer active:scale-90 focus:outline-none min-w-[44px] min-h-[44px] flex items-center justify-center"
        >
          <ArrowLeft size={20} />
        </button>
        <div className="flex-1">
          <div className="stamped-text text-xs tracking-widest">OPERATIONS BOARD</div>
          <div className="font-terminal text-[10px]" style={{ color: 'var(--text-muted)' }}>
            BAF3K // MISSION CONTROL // DAY {game?.day ?? 1}
          </div>
        </div>
        <div className="flex gap-2">
          {(['cigarettes', 'alcohol', 'weed', 'crystals'] as ResourceKey[]).map((type) => {
            const Icon = RESOURCE_ICON_MAP[type];
            return (
              <span key={type} className="led-counter text-xs inline-flex items-center gap-1" style={{ color: 'var(--cig-yellow)' }}>
                <Icon size={11} />{getResourceQty(type)}
              </span>
            );
          })}
        </div>
      </div>

      {/* Directive-only strip — expeditions were moved to DISPATCH in v0.5.4/v0.6.0 */}
      <div className="border-b px-3 py-2 flex flex-col gap-1 sm:flex-row sm:items-center sm:justify-between" style={{ borderColor: 'var(--copper-dark)', background: 'rgba(184,115,51,0.04)' }}>
        <div className="font-terminal text-sm uppercase tracking-wider text-[var(--cig-yellow)] inline-flex items-center gap-2">
          <CrosshairIcon size={13} />
          CAREER DIRECTIVES
        </div>
        <div className="font-typewriter text-[10px] text-[#8a8578]">
          EXPEDITIONS tab retired — use DISPATCH on the bedroom wall map.
        </div>
      </div>

      {/* Content area */}
      <div className="flex-1 flex overflow-hidden">
        {/* Mission list */}
        <div className="w-1/2 overflow-y-auto p-3 space-y-2" style={{ borderRight: '1px solid var(--copper-dark)' }}>
          {mainMissions.map(renderMissionCard)}
        </div>

        {/* Mission detail panel */}
        <div className="w-1/2 overflow-y-auto">
          <AnimatePresence mode="wait">
            {selectedDef ? (
              <motion.div
                key={selectedDef.key}
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0 }}
                className="p-4 space-y-4"
              >
                {/* Dossier header */}
                <div className="dossier-stamp">
                  <div className="stamped-text text-xs mb-1">{selectedDef.codename}</div>
                  <div className="font-terminal text-lg" style={{ color: 'var(--text-primary)' }}>
                    {selectedDef.title}
                  </div>
                  <div
                    className="font-terminal text-xs mt-1"
                    style={{ color: DIFFICULTY_COLORS[selectedDef.difficulty] }}
                  >
                    DIFFICULTY: {selectedDef.difficulty}
                  </div>
                </div>

                {/* Briefing */}
                <div className="ops-board p-3">
                  <div className="stamped-text text-[10px] mb-2">BRIEFING</div>
                  <p className="font-typewriter text-xs leading-relaxed" style={{ color: 'var(--text-primary)' }}>
                    {selectedDef.delusionText}
                  </p>
                  {/* Reality flicker text at high escalation */}
                  {escalation.level >= 5 && (
                    <p
                      className="font-typewriter text-xs leading-relaxed mt-2 animate-flicker"
                      style={{ color: 'var(--reality-fluoro)', opacity: 0.4 + escalation.level * 0.05 }}
                    >
                      {selectedDef.realityText}
                    </p>
                  )}
                </div>

                {/* Location */}
                <div className="flex items-center gap-2 text-xs">
                  <Target size={12} style={{ color: 'var(--copper-bright)' }} />
                  <span className="font-terminal" style={{ color: 'var(--text-muted)' }}>
                    LOCATION: {selectedDef.locationName}
                  </span>
                </div>

                {/* Requirements */}
                <div className="copper-border p-3 space-y-2">
                  <div className="stamped-text text-[10px]">REQUIREMENTS</div>

                  {/* Resource costs */}
                  <div className="flex flex-wrap gap-2">
                    {Object.entries(selectedDef.cost).map(([type, amt]) =>
                      amt ? renderCostTag(type, amt) : null
                    )}
                  </div>

                  {/* Crew requirement */}
                  <div className="flex items-center gap-2 text-xs">
                    <span className="font-terminal" style={{
                      color: recruitedCount >= selectedDef.crewRequired ? 'var(--neon-green)' : 'var(--danger-red)',
                    }}>
                      CREW: {recruitedCount}/{selectedDef.crewRequired} recruited
                    </span>
                  </div>

                  {/* Prereqs */}
                  {selectedDef.prereqs.length > 0 && (
                    <div className="text-xs">
                      <span className="font-terminal" style={{ color: 'var(--text-muted)' }}>REQUIRES: </span>
                      {selectedDef.prereqs.map(pk => {
                        const pDef = MISSION_DEFINITIONS[pk];
                        const pStatus = getMissionStatus(pk);
                        return (
                          <span
                            key={pk}
                            className="font-terminal ml-1"
                            style={{ color: pStatus === 'COMPLETED' ? 'var(--neon-green)' : 'var(--danger-red)' }}
                          >
                            {pStatus === 'COMPLETED' ? '✓' : '✗'} {pDef?.title ?? pk}
                          </span>
                        );
                      })}
                    </div>
                  )}
                </div>

                {/* Rewards */}
                <div className="ops-board p-3">
                  <div className="stamped-text text-[10px] mb-2">REWARDS</div>
                  <p className="font-terminal text-xs" style={{ color: 'var(--cig-yellow)' }}>
                    {selectedDef.rewards.description}
                  </p>
                </div>

                {/* Action button */}
                {selectedStatus === 'AVAILABLE' && (
                  <button
                    onClick={() => handleStartMission(selectedDef.key)}
                    disabled={launching || !canAfford(selectedDef.cost) || recruitedCount < selectedDef.crewRequired}
                    className="w-full py-3 font-terminal text-sm uppercase tracking-wider transition-all"
                    style={{
                      background: canAfford(selectedDef.cost) && recruitedCount >= selectedDef.crewRequired
                        ? 'var(--copper-dark)'
                        : 'var(--carbon-mid)',
                      color: canAfford(selectedDef.cost) && recruitedCount >= selectedDef.crewRequired
                        ? 'var(--cig-yellow)'
                        : 'var(--text-dim)',
                      border: `1px solid ${canAfford(selectedDef.cost) ? 'var(--copper-bright)' : 'var(--copper-dark)'}`,
                      cursor: canAfford(selectedDef.cost) && recruitedCount >= selectedDef.crewRequired ? 'pointer' : 'not-allowed',
                    }}
                  >
                    {launching ? (
                      'INITIATING...'
                    ) : canAfford(selectedDef.cost) && recruitedCount >= selectedDef.crewRequired ? (
                      <span className="inline-flex items-center gap-2 justify-center">
                        <BoltIcon size={13} />
                        INITIATE {selectedDef.codename}
                      </span>
                    ) : (
                      <span className="inline-flex items-center gap-2 justify-center">
                        <LockIcon size={13} />
                        INSUFFICIENT RESOURCES
                      </span>
                    )}
                  </button>
                )}

                {selectedStatus === 'ACTIVE' && selectedDef.type === 'MAIN' && (
                  <div className="space-y-2">
                    <div className="font-terminal text-xs text-center" style={{ color: 'var(--neon-green)' }}>
                      MISSION ACTIVE — PHASE {getNarrativePhase(selectedDef.key)}/{selectedDef.narrativePhases}
                    </div>
                    <div className="w-full h-2 rounded-full overflow-hidden" style={{ background: 'var(--carbon-void)' }}>
                      <div
                        className="h-full transition-all"
                        style={{
                          width: `${(getNarrativePhase(selectedDef.key) / selectedDef.narrativePhases) * 100}%`,
                          background: DIFFICULTY_COLORS[selectedDef.difficulty],
                        }}
                      />
                    </div>
                    {getNarrativePhase(selectedDef.key) < selectedDef.narrativePhases ? (
                      <button
                        onClick={() => handleAdvanceMission(selectedDef.key)}
                        aria-label={`Advance mission to phase ${getNarrativePhase(selectedDef.key) + 1}`}
                        className="w-full py-2 font-terminal text-sm uppercase tracking-wider"
                        style={{
                          background: 'var(--copper-dark)',
                          color: 'var(--cig-yellow)',
                          border: '1px solid var(--copper-bright)',
                        }}
                      >
                        ▶ ADVANCE TO PHASE {getNarrativePhase(selectedDef.key) + 1}
                      </button>
                    ) : (
                      <button
                        onClick={() => handleCompleteMission(selectedDef.key)}
                        aria-label="Complete mission and claim rewards"
                        className="w-full py-2 font-terminal text-sm uppercase tracking-wider"
                        style={{
                          background: 'var(--copper-bright)',
                          color: 'var(--carbon-void)',
                          border: '1px solid var(--cig-yellow)',
                          textShadow: '0 1px 0 rgba(0,0,0,0.3)',
                        }}
                      >
                        ✓ COMPLETE MISSION
                      </button>
                    )}
                  </div>
                )}

                {selectedStatus === 'COMPLETED' && (
                  <div className="text-center py-3">
                    <div className="font-terminal text-sm" style={{ color: 'var(--copper-patina)' }}>
                      ✓ DIRECTIVE FULFILLED
                    </div>
                    <div className="text-xs mt-1" style={{ color: 'var(--text-muted)' }}>
                      Rewards claimed. {selectedDef.rewards.description}
                    </div>
                  </div>
                )}

                {selectedStatus === 'LOCKED' && (
                  <div className="text-center py-3">
                    <Lock size={24} className="mx-auto mb-2" style={{ color: 'var(--text-dim)' }} />
                    <div className="font-terminal text-xs" style={{ color: 'var(--text-dim)' }}>
                      CLASSIFIED — PREREQUISITES NOT MET
                    </div>
                  </div>
                )}
              </motion.div>
            ) : (
              <motion.div
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                className="h-full flex items-center justify-center p-8"
              >
                <div className="text-center">
                  <div className="stamped-text text-sm mb-2">SELECT OPERATION</div>
                  <div className="font-terminal text-xs" style={{ color: 'var(--text-muted)' }}>
                    Choose a directive from the board
                  </div>
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </div>
    </motion.div>
  );
}

export default memo(OperationsBoard);

