import { useCallback, useEffect, useMemo, useRef, useState, type CSSProperties } from 'react';

// ═══════════════════════════════════════════════════════
// BMF:3K — TACTICAL BOARD (Sprint 3)
// Integrated version of the sprint1/sprint2 prototype.
// Renders inside the main game's chrome (no own scanlines/vignette).
// ═══════════════════════════════════════════════════════

// ─── Types ────────────────────────────────────────────────
const CONE_DIR = ['up', 'down', 'left', 'right'] as const;
type ConeDir = (typeof CONE_DIR)[number];
interface Pt { x: number; y: number; }
interface Cone { dir: ConeDir; angle_deg: number; range_tiles: number; }
interface MapEnemy { id: string; type: string; patrol: Pt[]; cone: Cone; initial_state: string; }
interface GarbageNode { id: string; x: number; y: number; state: string; }
interface TileOverride { x: number; y: number; state: string; }
interface GameMap {
  meta: { name: string; tile_size: number; width: number; height: number };
  spawn: Pt;
  extraction: Pt & { type: string };
  garbage_nodes: GarbageNode[];
  enemies: MapEnemy[];
  tile_overrides: TileOverride[];
}
interface EncResponse {
  id: string; label: string; approach: string;
  outcome: {
    success: { heat_delta?: number; message?: string };
    fail: { stress?: number; heat_delta?: number; knockout?: boolean };
  };
}
interface Encounter { id: string; tone: string; text: string; anchors: string[]; responses: EncResponse[]; }

interface LiveEnemy { id: string; patrol: Pt[]; patrolIndex: number; pos: Pt; cone: Cone; }
interface BoardState {
  heat: number;
  looted: string[];
  player: { x: number; y: number; moveRange: number; remaining: number; stress: number };
  enemies: LiveEnemy[];
  turn: number;
  heatMult: number;
  mikeyBleed: boolean;
  encBonus: number;
  mainUsed: boolean;
  directiveUsed: boolean;
  heatShield: boolean;
  scavengerPrimed: boolean;
  decoderArmed: boolean;
  autoWinArmed: boolean;
  coneBlackout: number;
  cigarettes: number;
}

// ─── Operatives ──────────────────────────────────────
type OperativeId = 'tamara' | 'sid' | 'mikey' | 'dave';
interface Operative {
  id: OperativeId; name: string; role: string; color: string; glyph: string; moveRange: number;
  blurb: string;
  passive: { name: string; desc: string };
  main: { name: string; desc: string };
  directive: { name: string; desc: string };
}
const ALL_OPERATIVES: Operative[] = [
  { id: 'tamara', name: 'TAMARA', role: 'RUNNER', color: '#7ab8b8', glyph: '█', moveRange: 4, blurb: 'Never stops moving. Watches the lights.', passive: { name: 'ADRENALINE DASH', desc: '+1 move every turn (4 moves).' }, main: { name: 'DUMPSTER DETECTION', desc: 'Remotely salvage the nearest node — no walk.' }, directive: { name: 'BLIND SPOT', desc: 'Kill every vision cone for one enemy turn.' } },
  { id: 'sid', name: 'SID', role: 'ENFORCER', color: '#cc5550', glyph: '█', moveRange: 3, blurb: 'Runs hot. Loyal when managed.', passive: { name: 'PRESENCE', desc: 'Encounters start easier (+15% success).' }, main: { name: 'HEAT DEFLECTION', desc: 'Absorb the next heat spike entirely.' }, directive: { name: 'STRONG-ARM', desc: 'Force the next encounter to succeed.' } },
  { id: 'mikey', name: 'MIKEY', role: 'STREET ELDER', color: '#d4a060', glyph: '█', moveRange: 3, blurb: 'Long coat. Talks to no one.', passive: { name: 'FRUGAL CUDDLE', desc: 'Heat bleeds −1 at the start of each turn.' }, main: { name: 'MASTER SCAVENGER', desc: 'Next salvage costs no heat and no move.' }, directive: { name: 'OLD ROUTES', desc: 'Gain +3 moves right now.' } },
  { id: 'dave', name: 'DAVE', role: 'ANALYST', color: '#8aad7a', glyph: '█', moveRange: 3, blurb: 'Hugs the walls. Counts under breath.', passive: { name: 'STRUCTURAL EFFICIENCY', desc: 'All heat gain reduced 15%.' }, main: { name: 'UNIVERSAL DECODER', desc: 'Reveal the correct tone in the next encounter.' }, directive: { name: 'COLD READ', desc: 'Instantly shed 25 heat.' } },
];

const ENEMY_TONE_MAP: Record<string, string> = { guard_1: 'enc_rigid_officer', guard_2: 'enc_clinical_guard', roamer_1: 'enc_hesitant_vendor' };
const MAX_STRESS = 5;
const MAX_HEAT = 100;
const TONE_COUNTER: Record<string, string> = { rigid: 'weed', hesitant: 'alcohol', clinical: 'crystals' };

// ─── Pure helpers ────────────────────────────────────
function dirVecOf(dir: ConeDir): Pt {
  switch (dir) { case 'up': return { x: 0, y: -1 }; case 'down': return { x: 0, y: 1 }; case 'left': return { x: -1, y: 0 }; case 'right': return { x: 1, y: 0 }; }
}
function tileInCone(enemy: LiveEnemy, tx: number, ty: number): boolean {
  const dx = tx - enemy.pos.x; const dy = ty - enemy.pos.y;
  const dist = Math.hypot(dx, dy);
  if (dist < 0.01 || dist > enemy.cone.range_tiles + 0.01) return false;
  const dv = dirVecOf(enemy.cone.dir);
  const dot = dx * dv.x + dy * dv.y;
  if (dot <= 0) return false;
  const cosAngle = dot / (Math.hypot(dx, dy) * Math.hypot(dv.x, dv.y) + 0.0001);
  return Math.acos(Math.min(1, Math.max(-1, cosAngle))) * (180 / Math.PI) <= enemy.cone.angle_deg / 2;
}
function playerSpottedBy(g: BoardState): LiveEnemy | null {
  if (g.coneBlackout > 0) return null;
  for (const en of g.enemies) { if (tileInCone(en, g.player.x, g.player.y)) return en; }
  return null;
}
function clone(g: BoardState): BoardState {
  return { heat: g.heat, looted: [...g.looted], player: { ...g.player }, enemies: g.enemies.map((e) => ({ ...e, pos: { ...e.pos }, patrol: e.patrol, cone: e.cone })), turn: g.turn, heatMult: g.heatMult, mikeyBleed: g.mikeyBleed, encBonus: g.encBonus, mainUsed: g.mainUsed, directiveUsed: g.directiveUsed, heatShield: g.heatShield, scavengerPrimed: g.scavengerPrimed, decoderArmed: g.decoderArmed, autoWinArmed: g.autoWinArmed, coneBlackout: g.coneBlackout, cigarettes: g.cigarettes };
}
function gainHeat(ng: BoardState, amount: number) {
  if (amount <= 0) { ng.heat = Math.max(0, Math.min(MAX_HEAT, ng.heat + amount)); return; }
  let amt = Math.round(amount * ng.heatMult);
  if (ng.heatShield) { amt = 0; ng.heatShield = false; }
  ng.heat = Math.min(MAX_HEAT, ng.heat + amt);
}
function stepEnemies(g: BoardState): BoardState {
  const ng = clone(g);
  ng.enemies = ng.enemies.map((en) => {
    const target = en.patrol[en.patrolIndex];
    let { x, y } = en.pos; let idx = en.patrolIndex;
    if (x === target.x && y === target.y) idx = en.patrolIndex === 0 ? en.patrol.length - 1 : 0;
    const tgt = en.patrol[idx];
    if (x !== tgt.x) x += tgt.x > x ? 1 : -1;
    else if (y !== tgt.y) y += tgt.y > y ? 1 : -1;
    return { ...en, pos: { x, y }, patrolIndex: idx };
  });
  return ng;
}
const DIR_ARROW: Record<ConeDir, string> = { up: '▲', down: '▼', left: '◀', right: '▶' };

// ─── The Fog (redaction) ─────────────────────────────
// Bible §5.4: in high-heat areas the adversary's speech is blotted out.
// Cigarettes ("durries") lift the fog so the crew reads the full transmission.
function fogHash(s: string): number {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return h >>> 0;
}
interface FogToken { text: string; blot: boolean; }
function buildFog(enc: Encounter, intensity: number): FogToken[] {
  if (intensity <= 0) return enc.text.split(/(\s+)/).map((t) => ({ text: t, blot: false }));
  const anchorWords = new Set<string>();
  enc.anchors.forEach((a) => a.toLowerCase().split(/\s+/).forEach((w) => { const c = w.replace(/[^a-z0-9']/g, ''); if (c) anchorWords.add(c); }));
  return enc.text.split(/(\s+)/).map((tok, i) => {
    if (!tok.trim()) return { text: tok, blot: false };
    const core = tok.toLowerCase().replace(/[^a-z0-9']/g, '');
    if (core.length <= 2 || anchorWords.has(core)) return { text: tok, blot: false };
    return { text: tok, blot: (fogHash(`${enc.id}:${i}:${core}`) % 1000) / 1000 < intensity };
  });
}

// ─── Props ───────────────────────────────────────────
export interface TacticalBoardResult { heat: number; loot: number; won: boolean; turns: number; }
interface Props {
  onBack: () => void;
  onComplete: (result: TacticalBoardResult) => void;
  recruitedNpcKeys: string[];
}

// ═══ Component ═══════════════════════════════════
export default function TacticalBoard({ onBack, onComplete, recruitedNpcKeys }: Props) {
  const operatives = useMemo(() => {
    const avail = ALL_OPERATIVES.filter((op) => recruitedNpcKeys.includes(op.id));
    return avail.length > 0 ? avail : ALL_OPERATIVES; // fallback: show all if none recruited
  }, [recruitedNpcKeys]);

  const [map, setMap] = useState<GameMap | null>(null);
  const [encList, setEncList] = useState<Record<string, Encounter>>({});
  const [game, setGame] = useState<BoardState | null>(null);
  const [encounter, setEncounter] = useState<{ enc: Encounter; enemyId: string } | null>(null);
  const [message, setMessage] = useState('');
  const [status, setStatus] = useState<'select' | 'loading' | 'playing' | 'won' | 'lost'>('select');
  const [lastResult, setLastResult] = useState<'success' | 'fail' | null>(null);
  const [tile, setTile] = useState(48);
  const [operative, setOperative] = useState<Operative>(operatives[0]);
  const [showHelp, setShowHelp] = useState(false);
  const [fogLifted, setFogLifted] = useState(false);

  useEffect(() => {
    try { if (!localStorage.getItem('tactical_briefed')) { setShowHelp(true); localStorage.setItem('tactical_briefed', '1'); } } catch {}
  }, []);

  const mapRef = useRef<GameMap | null>(null);
  const encRef = useRef<Record<string, Encounter>>({});
  const gameRef = useRef<BoardState | null>(null);
  const encounterOpenRef = useRef(false);
  const statusRef = useRef<typeof status>('select');
  const pendingEndTurnRef = useRef(false);
  const msgTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => { mapRef.current = map; }, [map]);
  useEffect(() => { encRef.current = encList; }, [encList]);
  useEffect(() => { gameRef.current = game; }, [game]);
  useEffect(() => { encounterOpenRef.current = !!encounter; }, [encounter]);
  useEffect(() => { statusRef.current = status; }, [status]);

  useEffect(() => {
    const recalc = () => {
      const avail = Math.min(window.innerWidth - 24, 720);
      const byW = Math.floor(avail / 10);
      const byH = Math.floor((window.innerHeight - 360) / 8);
      setTile(Math.max(28, Math.min(64, byW, byH > 28 ? byH : byW)));
    };
    recalc(); window.addEventListener('resize', recalc);
    return () => window.removeEventListener('resize', recalc);
  }, []);

  const startMission = useCallback(async (op: Operative) => {
    setStatus('loading');
    try {
      const [m, e] = await Promise.all([
        fetch('/data/sprint1_map.json').then((r) => r.json()),
        fetch('/data/encounters_sprint1.json').then((r) => r.json()),
      ]);
      const encMap: Record<string, Encounter> = {};
      (e.encounters as Encounter[]).forEach((en) => { encMap[en.id] = en; });
      const g: BoardState = {
        heat: 0, looted: [],
        player: { x: m.spawn.x, y: m.spawn.y, moveRange: op.moveRange, remaining: op.moveRange, stress: 0 },
        enemies: (m.enemies as MapEnemy[]).map((en) => ({ id: en.id, patrol: en.patrol.slice(), patrolIndex: 0, pos: { x: en.patrol[0].x, y: en.patrol[0].y }, cone: en.cone })),
        turn: 1,
        heatMult: op.id === 'dave' ? 0.85 : 1, mikeyBleed: op.id === 'mikey', encBonus: op.id === 'sid' ? 0.15 : 0,
        mainUsed: false, directiveUsed: false, heatShield: false, scavengerPrimed: false, decoderArmed: false, autoWinArmed: false, coneBlackout: 0,
        cigarettes: 3,
      };
      setMap(m); setEncList(encMap); setGame(g); gameRef.current = g;
      setEncounter(null); setMessage(''); setLastResult(null); setStatus('playing');
      pendingEndTurnRef.current = false;
    } catch { setStatus('select'); setMessage('FAILED TO LOAD MISSION DATA.'); }
  }, []);

  const flash = useCallback((msg: string) => {
    setMessage(msg);
    if (msgTimer.current) clearTimeout(msgTimer.current);
    msgTimer.current = setTimeout(() => setMessage(''), 3200);
  }, []);

  const runEnemyTurn = useCallback((from: BoardState) => {
    const ng = stepEnemies(from);
    ng.player = { ...ng.player, remaining: ng.player.moveRange }; ng.turn = from.turn + 1;
    if (ng.mikeyBleed && ng.heat > 0) ng.heat = Math.max(0, ng.heat - 1);
    if (ng.coneBlackout > 0) ng.coneBlackout -= 1;
    setGame(ng); gameRef.current = ng;
    const spotter = playerSpottedBy(ng);
    if (spotter) { const enc = encRef.current[ENEMY_TONE_MAP[spotter.id] || 'enc_hesitant_vendor']; if (enc) setEncounter({ enc, enemyId: spotter.id }); }
  }, []);

  const attemptMove = useCallback((dx: number, dy: number) => {
    if (statusRef.current !== 'playing' || encounterOpenRef.current) return;
    const m = mapRef.current; const g = gameRef.current;
    if (!m || !g) return;
    if (g.player.remaining <= 0) { flash('NO MOVES LEFT — END TURN.'); return; }
    const nx = g.player.x + dx; const ny = g.player.y + dy;
    if (nx < 0 || ny < 0 || nx >= m.meta.width || ny >= m.meta.height) return;
    if (m.tile_overrides.some((t) => t.x === nx && t.y === ny && t.state === 'blocked')) return;
    if (g.enemies.some((en) => en.pos.x === nx && en.pos.y === ny)) return;
    const ng = clone(g); ng.player.x = nx; ng.player.y = ny; ng.player.remaining -= 1;
    if (nx === m.extraction.x && ny === m.extraction.y) {
      setGame(ng); gameRef.current = ng; setStatus('won');
      onComplete({ heat: ng.heat, loot: ng.looted.length, won: true, turns: ng.turn });
      return;
    }
    const node = m.garbage_nodes.find((n) => n.x === nx && n.y === ny && !ng.looted.includes(n.id));
    if (node) {
      ng.looted.push(node.id);
      if (ng.scavengerPrimed) { ng.scavengerPrimed = false; flash(`MASTER SCAVENGER — ${node.id.toUpperCase()} CLEAN GRAB`); }
      else { gainHeat(ng, 5); ng.player.remaining = 0; flash(`SALVAGED ${node.id.toUpperCase()} — HEAT +5`); }
    }
    setGame(ng); gameRef.current = ng;
    const spotter = playerSpottedBy(ng);
    if (spotter) {
      const enc = encRef.current[ENEMY_TONE_MAP[spotter.id] || 'enc_hesitant_vendor'];
      if (enc) { pendingEndTurnRef.current = ng.player.remaining === 0; setEncounter({ enc, enemyId: spotter.id }); return; }
    }
    if (ng.player.remaining === 0) runEnemyTurn(ng);
  }, [flash, runEnemyTurn, onComplete]);

  const endTurn = useCallback(() => {
    if (statusRef.current !== 'playing' || encounterOpenRef.current) return;
    const g = gameRef.current; if (!g) return; runEnemyTurn(g);
  }, [runEnemyTurn]);

  const useMainAbility = useCallback(() => {
    if (statusRef.current !== 'playing' || encounterOpenRef.current) return;
    const g = gameRef.current; const m = mapRef.current;
    if (!g || !m || g.mainUsed) return;
    const ng = clone(g); ng.mainUsed = true;
    switch (operative.id) {
      case 'tamara': {
        const remaining = m.garbage_nodes.filter((n) => !ng.looted.includes(n.id));
        if (remaining.length === 0) { flash('NO NODES LEFT TO DETECT.'); return; }
        let best = remaining[0]; let bestD = Infinity;
        for (const n of remaining) { const d = Math.abs(n.x - ng.player.x) + Math.abs(n.y - ng.player.y); if (d < bestD) { bestD = d; best = n; } }
        ng.looted.push(best.id); gainHeat(ng, 5);
        flash(`DUMPSTER DETECTION — ${best.id.toUpperCase()} PULLED REMOTELY`); break;
      }
      case 'sid': ng.heatShield = true; flash('HEAT DEFLECTION ARMED — NEXT SPIKE ABSORBED'); break;
      case 'mikey': ng.scavengerPrimed = true; flash('MASTER SCAVENGER PRIMED — NEXT GRAB IS FREE'); break;
      case 'dave': ng.decoderArmed = true; flash('UNIVERSAL DECODER ARMED — NEXT TONE REVEALED'); break;
    }
    setGame(ng); gameRef.current = ng;
  }, [operative, flash]);

  const playDirective = useCallback(() => {
    if (statusRef.current !== 'playing' || encounterOpenRef.current) return;
    const g = gameRef.current; if (!g || g.directiveUsed) return;
    const ng = clone(g); ng.directiveUsed = true;
    switch (operative.id) {
      case 'tamara': ng.coneBlackout = 2; flash('BLIND SPOT — VISION CONES DOWN'); break;
      case 'sid': ng.autoWinArmed = true; flash('STRONG-ARM READY — NEXT CONTACT FOLDS'); break;
      case 'mikey': ng.player.remaining += 3; flash('OLD ROUTES — +3 MOVES'); break;
      case 'dave': gainHeat(ng, -25); flash('COLD READ — HEAT −25'); break;
    }
    setGame(ng); gameRef.current = ng;
  }, [operative, flash]);

  const resolveEncounter = useCallback((respIndex: number) => {
    const cur = encounter; const g = gameRef.current;
    if (!cur || !g) return;
    const resp = cur.enc.responses[respIndex];
    const tone = cur.enc.tone.toLowerCase();
    const approachTag = resp.approach.split('/')[0].trim().toLowerCase();
    const isCounter = approachTag === TONE_COUNTER[tone];
    const approachMatches = approachTag === tone || isCounter;
    let successChance = (isCounter ? 0.78 : approachMatches ? 0.55 : 0.35) + g.encBonus;
    successChance = Math.min(0.97, successChance);
    const forced = g.autoWinArmed;
    const success = forced || Math.random() < successChance;
    const ng = clone(g); ng.autoWinArmed = false; ng.decoderArmed = false;
    let lost = false;
    if (success) { gainHeat(ng, resp.outcome.success.heat_delta || 0); flash(forced ? 'STRONG-ARM — THEY BACK DOWN' : (resp.outcome.success.message || 'Success.')); setLastResult('success'); }
    else {
      ng.player.stress += resp.outcome.fail.stress || 1;
      gainHeat(ng, resp.outcome.fail.heat_delta || 10); setLastResult('fail');
      if (resp.outcome.fail.knockout || ng.player.stress >= MAX_STRESS) { flash(resp.outcome.fail.knockout ? 'KNOCKED OUT. EXTRACTION FAILED.' : 'STRESS OVERLOAD. CREW DOWN.'); lost = true; }
      else flash('Encounter failed.');
    }
    if (ng.heat >= MAX_HEAT) lost = true;
    setGame(ng); gameRef.current = ng; setEncounter(null); encounterOpenRef.current = false;
    if (lost) {
      setStatus('lost');
      onComplete({ heat: ng.heat, loot: ng.looted.length, won: false, turns: ng.turn });
      return;
    }
    if (pendingEndTurnRef.current) { pendingEndTurnRef.current = false; runEnemyTurn(ng); }
  }, [encounter, flash, runEnemyTurn, onComplete]);

  useEffect(() => { setFogLifted(false); }, [encounter]);

  const liftFog = useCallback(() => {
    const g = gameRef.current; if (!g || g.cigarettes <= 0) return;
    const ng = clone(g); ng.cigarettes -= 1; setGame(ng); gameRef.current = ng;
    setFogLifted(true);
  }, []);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (statusRef.current !== 'playing') return;
      const k = e.key.toLowerCase();
      if (['arrowup', 'w'].includes(k)) { e.preventDefault(); attemptMove(0, -1); }
      else if (['arrowdown', 's'].includes(k)) { e.preventDefault(); attemptMove(0, 1); }
      else if (['arrowleft', 'a'].includes(k)) { e.preventDefault(); attemptMove(-1, 0); }
      else if (['arrowright', 'd'].includes(k)) { e.preventDefault(); attemptMove(1, 0); }
      else if (k === ' ' || k === 'enter') { e.preventDefault(); endTurn(); }
      else if (k === 'q') { e.preventDefault(); useMainAbility(); }
      else if (k === 'e') { e.preventDefault(); playDirective(); }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [attemptMove, endTurn, useMainAbility, playDirective]);

  const coneTiles = useMemo(() => {
    const set = new Set<string>();
    if (!map || !game || game.coneBlackout > 0) return set;
    for (const en of game.enemies) { for (let y = 0; y < map.meta.height; y++) { for (let x = 0; x < map.meta.width; x++) { if (tileInCone(en, x, y)) set.add(`${x},${y}`); } } }
    return set;
  }, [map, game]);

  const onTileTap = useCallback((x: number, y: number) => {
    const g = gameRef.current; if (!g) return;
    const dx = x - g.player.x; const dy = y - g.player.y;
    if (Math.abs(dx) + Math.abs(dy) !== 1) return; attemptMove(dx, dy);
  }, [attemptMove]);

  // BMF palette — aligned with the main game's muted CRT look
  const ACCENT = '#8aad7a';            // sage — primary board accent
  const INK = '#f3e8cf';               // body text
  const MUTED = '#b9aa8a';             // muted text
  const FAINT = '#776b55';             // faint text / hint
  const AMBER = '#d4a060';             // extraction / directive / warn
  const DANGER = '#cc5550';            // enemy / critical
  const TEAL = '#7ab8b8';              // special states
  const BORDER = 'rgba(216,199,163,0.18)';
  const BORDER_STRONG = 'rgba(216,199,163,0.35)';
  const PANEL = 'rgba(33,30,25,0.92)';
  const heat = game?.heat ?? 0; const hot = heat >= 70; const warm = heat >= 40;
  const opColor = operative.color;
  const panelStyle = (extra?: CSSProperties): CSSProperties => ({ background: PANEL, border: `1px solid ${BORDER}`, borderRadius: 10, boxShadow: '0 1px 2px rgba(0,0,0,0.36), 0 4px 16px rgba(0,0,0,0.24)', ...extra });

  const decoderIndex = useMemo(() => {
    if (!encounter || !game?.decoderArmed) return -1;
    const tone = encounter.enc.tone.toLowerCase();
    return encounter.enc.responses.findIndex((r) => r.approach.split('/')[0].trim().toLowerCase() === TONE_COUNTER[tone]);
  }, [encounter, game?.decoderArmed]);

  const fogIntensity = hot ? 0.6 : warm ? 0.34 : 0;
  const foggy = fogIntensity > 0;
  const fogTokens = useMemo(() => (encounter ? buildFog(encounter.enc, fogIntensity) : []), [encounter, fogIntensity]);

  const noCrewRecruited = recruitedNpcKeys.length === 0;

  // Atmospheric background image for the mission
  const BG_IMG = '/images/expedition-shopping-centre.jpg';
  const BG_IMG_2 = '/images/expedition-shopping-centre-2.jpg';

  return (
    <div className="w-full h-full flex flex-col items-center font-bmf-mono select-none overflow-y-auto relative" style={{ color: INK, minHeight: '100%', ['--pop' as any]: 'var(--pop-expedition)', ['--pop-rgb' as any]: 'var(--pop-expedition-rgb)' }}>

      {/* === ATMOSPHERIC BACKGROUND === */}
      <div className="fixed inset-0 z-0">
        <div className="absolute inset-0" style={{ backgroundImage: `url(${status !== 'select' ? BG_IMG_2 : BG_IMG})`, backgroundSize: 'cover', backgroundPosition: 'center 30%', filter: `brightness(${hot ? 0.22 : warm ? 0.18 : 0.15}) saturate(${hot ? 1.3 : 0.6}) blur(${status === 'select' ? 1.2 : 0}px)`, transition: 'filter 0.8s ease' }} />
        {/* colour wash */}
        <div className="absolute inset-0" style={{ background: hot ? 'radial-gradient(ellipse at 50% 40%, rgba(204,85,80,0.12), rgba(8,7,5,0.92) 70%)' : warm ? 'radial-gradient(ellipse at 50% 40%, rgba(212,160,96,0.08), rgba(8,7,5,0.92) 70%)' : 'radial-gradient(ellipse at 50% 40%, rgba(138,173,122,0.06), rgba(8,7,5,0.95) 70%)', transition: 'background 0.8s ease' }} />
        {/* scanlines */}
        <div className="absolute inset-0 pointer-events-none" style={{ backgroundImage: 'repeating-linear-gradient(0deg, transparent, transparent 2px, rgba(0,0,0,0.18) 2px, rgba(0,0,0,0.18) 4px)', backgroundSize: '100% 4px', opacity: 0.5 }} />
        {/* vignette */}
        <div className="absolute inset-0 pointer-events-none" style={{ background: 'radial-gradient(ellipse 85% 80% at 50% 50%, transparent 40%, rgba(0,0,0,0.7) 100%)' }} />
        {/* film grain */}
        <div className="absolute inset-0 pointer-events-none opacity-[0.04]" style={{ backgroundImage: 'repeating-radial-gradient(circle, rgba(243,232,207,0.15) 0px, transparent 1px, transparent 3px)', backgroundSize: '3px 3px' }} />
      </div>

      {/* header with back button */}
      <header className="w-full max-w-3xl px-4 pt-3 pb-2 z-10">
        <div className="flex items-center justify-between pb-2" style={{ borderBottom: `1px solid ${BORDER}` }}>
          <button onClick={onBack} className="text-[10px] tracking-widest py-1 px-2 rounded active:scale-95 transition-transform" style={{ color: MUTED }}>
            ◀ ABORT
          </button>
          <h1 className="text-sm tracking-[0.35em]" style={{ color: ACCENT, textShadow: `0 0 20px ${ACCENT}33` }}>EXPEDITION</h1>
          <span className="text-[9px] tracking-widest" style={{ color: FAINT }}>EXTRACTION PROTOCOL</span>
        </div>
      </header>

      {/* ═══ CREW SELECT ═══ */}
      {status === 'select' && (
        <div className="w-full max-w-3xl px-4 z-10 pb-10">
          {noCrewRecruited && (
            <div className="text-center my-4 px-4 py-3 rounded-lg" style={panelStyle({ borderColor: 'rgba(212,160,96,0.4)' })}>
              <div className="text-xs tracking-[0.2em]" style={{ color: AMBER }}>NO OPERATIVES RECRUITED</div>
              <div className="text-[10px] mt-1" style={{ color: MUTED }}>Recruit crew from the CREW BOARD first. Running sandbox mode.</div>
            </div>
          )}
          <div className="text-center my-5">
            <div className="text-xs tracking-[0.35em]" style={{ color: ACCENT, textShadow: `0 0 16px ${ACCENT}22` }}>SELECT OPERATIVE</div>
            <div className="text-[10px] mt-1" style={{ color: FAINT }}>One body goes in. Choose who.</div>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            {operatives.map((op) => {
              const sel = operative.id === op.id;
              return (
                <button key={op.id} onClick={() => setOperative(op)} className="text-left p-3.5 rounded-lg transition-all active:scale-[0.99]" style={panelStyle({ borderColor: sel ? op.color : BORDER, background: sel ? `${op.color}14` : PANEL, boxShadow: sel ? `0 0 0 1px ${op.color}66, 0 4px 24px rgba(0,0,0,0.4), inset 0 1px 0 rgba(255,255,255,0.03)` : '0 1px 2px rgba(0,0,0,0.36), 0 4px 16px rgba(0,0,0,0.24), inset 0 1px 0 rgba(255,255,255,0.02)' })}>
                  <div className="flex items-center justify-between">
                    <span className="text-sm tracking-widest flex items-center gap-2" style={{ color: op.color }}>
                      <span style={{ width: 10, height: 10, background: op.color, display: 'inline-block', borderRadius: 2, boxShadow: `0 0 8px ${op.color}` }} /> {op.name}
                    </span>
                    <span className="text-[9px] tracking-widest" style={{ color: FAINT }}>{op.role}</span>
                  </div>
                  <div className="text-[10px] mt-1.5 italic" style={{ color: MUTED }}>{op.blurb}</div>
                  <div className="mt-2.5 space-y-1.5 text-[10px]">
                    <div><span style={{ color: ACCENT }}>PASSIVE</span> <span style={{ color: FAINT }}>· {op.passive.name}</span><div style={{ color: MUTED }}>{op.passive.desc}</div></div>
                    <div><span style={{ color: op.color }}>MAIN</span> <span style={{ color: FAINT }}>· {op.main.name}</span><div style={{ color: MUTED }}>{op.main.desc}</div></div>
                    <div><span style={{ color: AMBER }}>DIRECTIVE</span> <span style={{ color: FAINT }}>· {op.directive.name}</span><div style={{ color: MUTED }}>{op.directive.desc}</div></div>
                  </div>
                </button>
              );
            })}
          </div>
          {message && <div className="text-center text-[11px] mt-3" style={{ color: DANGER }}>{message}</div>}
          <div className="text-center mt-6">
            <button onClick={() => startMission(operative)} className="px-8 py-3.5 text-xs tracking-[0.3em] rounded-lg active:scale-95 transition-all" style={{ border: `1px solid ${opColor}`, color: '#11100e', background: opColor, boxShadow: `0 0 28px ${opColor}55, 0 2px 8px rgba(0,0,0,0.4)` }}>
              DEPLOY {operative.name} ▶
            </button>
            <div className="mt-3">
              <button onClick={() => setShowHelp(true)} className="px-5 py-2 text-[10px] tracking-[0.25em] rounded active:scale-95" style={{ border: `1px solid ${BORDER}`, color: MUTED, background: PANEL }}>◆ HOW TO PLAY</button>
            </div>
          </div>
        </div>
      )}

      {/* ═══ HOW TO PLAY BRIEFING ═══ */}
      {showHelp && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 bmf-glass-overlay" onClick={() => setShowHelp(false)}>
          <div className="w-full max-w-md p-5 overflow-y-auto rounded-xl" style={{ maxHeight: '88vh', ...panelStyle({ borderColor: BORDER_STRONG }) }} onClick={(e) => e.stopPropagation()}>
            <div className="flex items-center justify-between mb-3 pb-2" style={{ borderBottom: `1px solid ${BORDER}` }}>
              <h2 className="text-xs tracking-[0.3em]" style={{ color: ACCENT }}>MISSION BRIEFING</h2>
              <span className="text-[9px]" style={{ color: FAINT }}>EYES ONLY</span>
            </div>
            <div className="space-y-3 text-[11px] leading-relaxed" style={{ color: INK }}>
              <div><div className="tracking-[0.2em] mb-1" style={{ color: ACCENT }}>◆ THE JOB</div><p style={{ color: MUTED }}>Slip one operative through the lot, grab the salvage, reach the <span style={{ color: AMBER }}>extraction tile ⊕</span>. Don&apos;t get pinged. Don&apos;t cook the heat.</p></div>
              <div><div className="tracking-[0.2em] mb-1" style={{ color: ACCENT }}>◆ MOVING</div><p style={{ color: MUTED }}>Tap an adjacent tile, or use <span style={{ color: INK }}>WASD / arrow keys</span>. When out of moves, <span style={{ color: ACCENT }}>END TURN</span> (Space/Enter). Guards then shuffle and cones swing.</p></div>
              <div><div className="tracking-[0.2em] mb-1" style={{ color: ACCENT }}>◆ ENCOUNTERS</div><p style={{ color: MUTED }}>Counter their tone: <span style={{ color: ACCENT }}>RIGID → weed</span>, <span style={{ color: ACCENT }}>HESITANT → booze</span>, <span style={{ color: ACCENT }}>CLINICAL → crystals</span>. Right answer slips past + sheds heat.</p></div>
              <div><div className="tracking-[0.2em] mb-1" style={{ color: ACCENT }}>◆ SALVAGE & HEAT</div><p style={{ color: MUTED }}>Walk onto salvage <span style={{ color: ACCENT }}>▣</span> = +5 heat. Heat 100 = blown. Knockout or stress max = failed.</p></div>
              <div><div className="tracking-[0.2em] mb-1" style={{ color: ACCENT }}>◆ YOUR KIT</div><p style={{ color: MUTED }}><span style={{ color: opColor }}>[Q]</span> main ability + <span style={{ color: AMBER }}>[E]</span> directive card. One shot each — use them when it counts.</p></div>
            </div>
            <button onClick={() => setShowHelp(false)} className="w-full mt-4 py-3 text-xs tracking-[0.3em] rounded active:scale-95" style={{ border: `1px solid ${ACCENT}`, color: '#11100e', background: ACCENT }}>GOT IT ▶</button>
          </div>
        </div>
      )}

      {/* ═══ MISSION HUD + GRID ═══ */}
      {status !== 'select' && (
        <>
          {/* ══ HUD panels ══ */}
          <div className="w-full max-w-3xl px-4 grid grid-cols-3 gap-2 text-[10px] z-10">
            {/* HEAT */}
            <div className="p-2.5 rounded-lg" style={panelStyle()}>
              <div className="tracking-widest flex items-center gap-1.5" style={{ color: FAINT }}>
                <span style={{ width: 6, height: 6, borderRadius: '50%', background: hot ? DANGER : warm ? AMBER : ACCENT, boxShadow: `0 0 6px ${hot ? DANGER : warm ? AMBER : ACCENT}`, display: 'inline-block' }} />
                HEAT
              </div>
              <div className="mt-1.5 h-2.5 w-full rounded-full overflow-hidden relative" style={{ background: 'rgba(0,0,0,0.45)', border: `1px solid ${BORDER}`, boxShadow: 'inset 0 1px 3px rgba(0,0,0,0.5)' }}>
                <div className={hot ? 'animate-pulse' : ''} style={{ width: `${heat}%`, height: '100%', background: hot ? `linear-gradient(90deg, ${DANGER}, #e06050)` : warm ? `linear-gradient(90deg, ${AMBER}, #e0a050)` : `linear-gradient(90deg, ${ACCENT}, #a0c890)`, transition: 'width 0.3s', borderRadius: 999, boxShadow: hot ? `0 0 10px ${DANGER}88` : warm ? `0 0 8px ${AMBER}66` : `0 0 6px ${ACCENT}44` }} />
                {/* heat tick marks */}
                {[25,50,75].map(p => <div key={p} className="absolute top-0 bottom-0 w-px" style={{ left: `${p}%`, background: 'rgba(216,199,163,0.12)' }} />)}
              </div>
              <div className="mt-1 flex items-center justify-between">
                <span style={{ color: hot ? DANGER : warm ? AMBER : ACCENT }}>{heat} / 100</span>
                {warm && <span className="text-[8px] tracking-wider" style={{ color: hot ? DANGER : AMBER }}>{game?.cigarettes ?? 0} DURRIES</span>}
              </div>
            </div>
            {/* MOVES */}
            <div className="p-2.5 rounded-lg" style={panelStyle()}>
              <div className="tracking-widest" style={{ color: FAINT }}>MOVES</div>
              <div className="mt-1 flex items-baseline gap-0.5">
                <span className="text-lg font-bold" style={{ color: INK }}>{game?.player.remaining ?? 0}</span>
                <span className="text-xs" style={{ color: FAINT }}>/{game?.player.moveRange ?? 3}</span>
              </div>
              <div className="flex items-center gap-1" style={{ color: MUTED }}>
                <span style={{ width: 5, height: 5, border: `1px solid ${MUTED}`, borderRadius: 1, display: 'inline-block' }} />
                TURN {game?.turn ?? 1}
              </div>
            </div>
            {/* STRESS + LOOT */}
            <div className="p-2.5 rounded-lg" style={panelStyle()}>
              <div className="tracking-widest" style={{ color: FAINT }}>STRESS</div>
              <div className="mt-1 flex gap-1">
                {Array.from({ length: MAX_STRESS }).map((_, i) => {
                  const filled = (game?.player.stress ?? 0) > i;
                  return <span key={i} style={{ width: 10, height: 10, borderRadius: 2, background: filled ? DANGER : 'rgba(216,199,163,0.08)', border: `1px solid ${filled ? DANGER : 'rgba(216,199,163,0.15)'}`, boxShadow: filled ? `0 0 6px ${DANGER}66` : undefined, display: 'inline-block', transition: 'all 0.3s' }} />;
                })}
              </div>
              <div className="flex items-center gap-1 mt-1" style={{ color: MUTED }}>
                <span style={{ color: ACCENT }}>▣</span> {game?.looted.length ?? 0}/{map?.garbage_nodes.length ?? 0} SALVAGE
              </div>
            </div>
          </div>

          {/* ══ Operative + Ability Bar ══ */}
          <div className="w-full max-w-3xl px-4 mt-2 z-10 flex items-stretch gap-2 text-[10px]">
            <div className="px-3 py-2 flex flex-col justify-center rounded-lg" style={panelStyle({ borderColor: `${opColor}44`, minWidth: 100, borderLeft: `3px solid ${opColor}` })}>
              <span className="flex items-center gap-1.5" style={{ color: opColor }}><span style={{ width: 8, height: 8, background: opColor, borderRadius: 2, display: 'inline-block', boxShadow: `0 0 6px ${opColor}` }} />{operative.name}</span>
              <span style={{ color: FAINT }}>{operative.role}</span>
            </div>
            <button onClick={useMainAbility} disabled={!!game?.mainUsed} className="flex-1 px-3 py-2 text-left rounded-lg active:scale-[0.98] transition-transform" style={panelStyle({ borderColor: game?.mainUsed ? BORDER : `${opColor}66`, opacity: game?.mainUsed ? 0.4 : 1 })}>
              <div className="flex items-center justify-between"><span style={{ color: game?.mainUsed ? FAINT : opColor }}>[Q] {operative.main.name}</span><span className="text-[8px] px-1.5 py-0.5 rounded" style={{ color: game?.mainUsed ? FAINT : '#11100e', background: game?.mainUsed ? 'transparent' : `${opColor}33`, border: `1px solid ${game?.mainUsed ? 'transparent' : `${opColor}44`}` }}>{game?.mainUsed ? 'SPENT' : abilityArmedLabel(operative.id, game)}</span></div>
              <div className="text-[9px] mt-0.5" style={{ color: MUTED }}>{operative.main.desc}</div>
            </button>
            <button onClick={playDirective} disabled={!!game?.directiveUsed} className="flex-1 px-3 py-2 text-left rounded-lg active:scale-[0.98] transition-transform" style={panelStyle({ borderColor: game?.directiveUsed ? BORDER : `${AMBER}66`, opacity: game?.directiveUsed ? 0.4 : 1 })}>
              <div className="flex items-center justify-between"><span style={{ color: game?.directiveUsed ? FAINT : AMBER }}>[E] {operative.directive.name}</span><span className="text-[8px] px-1.5 py-0.5 rounded" style={{ color: game?.directiveUsed ? FAINT : '#11100e', background: game?.directiveUsed ? 'transparent' : `${AMBER}33`, border: `1px solid ${game?.directiveUsed ? 'transparent' : `${AMBER}44`}` }}>{game?.directiveUsed ? 'SPENT' : directiveArmedLabel(operative.id, game)}</span></div>
              <div className="text-[9px] mt-0.5" style={{ color: MUTED }}>DIRECTIVE · {operative.directive.desc}</div>
            </button>
          </div>

          {/* ══ Flash message ══ */}
          <div className="w-full max-w-3xl px-4 h-7 mt-2 text-[11px] z-10 flex items-center" style={{ color: lastResult === 'fail' ? DANGER : ACCENT, textShadow: message ? `0 0 8px ${lastResult === 'fail' ? DANGER : ACCENT}44` : undefined }}>{message}</div>

          {/* ══ TACTICAL GRID ══ */}
          <div className="relative z-10 mt-1" style={{ filter: hot ? 'saturate(1.15)' : undefined }}>
            {map && game && (
              <div className="relative rounded-lg overflow-hidden" style={{
                width: tile * map.meta.width, height: tile * map.meta.height,
                border: `1px solid ${hot ? `${DANGER}55` : BORDER_STRONG}`,
                boxShadow: hot ? `0 0 36px rgba(204,85,80,0.4), inset 0 0 50px rgba(204,85,80,0.15), 0 8px 32px rgba(0,0,0,0.6)` : `0 8px 32px rgba(0,0,0,0.6), inset 0 0 48px rgba(0,0,0,0.5), 0 0 0 1px rgba(0,0,0,0.3)`,
                backgroundColor: '#0a0a08',
                backgroundImage: `
                  radial-gradient(ellipse 70% 55% at 50% 42%, ${hot ? 'rgba(204,85,80,0.06)' : warm ? 'rgba(212,160,96,0.05)' : 'rgba(138,173,122,0.07)'}, transparent 70%),
                  radial-gradient(ellipse 120% 120% at 50% 50%, transparent 52%, rgba(0,0,0,0.6) 100%),
                  repeating-linear-gradient(0deg, rgba(0,0,0,0.14) 0 2px, transparent 2px 4px),
                  linear-gradient(160deg, #15140f 0%, #0c0b09 55%, #100f0c 100%)
                `,
              }}>
                {/* grid overlay scanlines */}
                <div className="absolute inset-0 pointer-events-none z-[20]" style={{ backgroundImage: 'repeating-linear-gradient(0deg, transparent, transparent 3px, rgba(0,0,0,0.08) 3px, rgba(0,0,0,0.08) 4px)', mixBlendMode: 'multiply', opacity: 0.6 }} />
                {/* grid ambient glow from centre */}
                <div className="absolute inset-0 pointer-events-none z-[1]" style={{ background: 'radial-gradient(circle at 50% 50%, rgba(138,173,122,0.04), transparent 60%)' }} />

                {game.coneBlackout > 0 && <div className="absolute top-1.5 left-1.5 z-30 text-[9px] px-2 py-1 rounded-md animate-pulse" style={{ color: TEAL, background: 'rgba(8,8,7,0.9)', border: `1px solid ${TEAL}55`, boxShadow: `0 0 12px ${TEAL}33` }}>BLIND SPOT ACTIVE</div>}
                {Array.from({ length: map.meta.height }).map((_, y) =>
                  Array.from({ length: map.meta.width }).map((__, x) => {
                    const key = `${x},${y}`;
                    const blocked = map.tile_overrides.some((t) => t.x === x && t.y === y && t.state === 'blocked');
                    const inCone = coneTiles.has(key);
                    const node = map.garbage_nodes.find((n) => n.x === x && n.y === y);
                    const looted = node ? game.looted.includes(node.id) : false;
                    const isExtraction = map.extraction.x === x && map.extraction.y === y;
                    const enemy = game.enemies.find((e) => e.pos.x === x && e.pos.y === y);
                    const isPlayer = game.player.x === x && game.player.y === y;
                    const adjacent = Math.abs(x - game.player.x) + Math.abs(y - game.player.y) === 1 && !blocked && !enemy;
                    return (
                      <button key={key} onClick={() => onTileTap(x, y)} aria-label={`tile ${x},${y}`} className="absolute flex items-center justify-center transition-colors duration-200" style={{
                        left: x * tile, top: y * tile, width: tile, height: tile,
                        borderRight: `1px solid rgba(216,199,163,0.04)`, borderBottom: `1px solid rgba(216,199,163,0.04)`,
                        background: blocked ? 'repeating-linear-gradient(45deg,rgba(216,199,163,0.07),rgba(216,199,163,0.07) 4px,transparent 4px,transparent 8px)'
                          : inCone ? `radial-gradient(circle at center, rgba(204,85,80,0.34), rgba(204,85,80,0.10) 65%, transparent 92%)`
                          : adjacent ? `radial-gradient(circle at center, ${ACCENT}11, transparent 70%)`
                          : 'transparent',
                        boxShadow: adjacent ? `inset 0 0 0 1.5px ${ACCENT}55` : undefined,
                        cursor: adjacent ? 'pointer' : 'default',
                        fontSize: tile * 0.5, lineHeight: 1,
                        zIndex: isPlayer ? 12 : enemy ? 11 : 10,
                      }}>
                        {adjacent && <span className="exp-reach absolute rounded" style={{ width: tile * 0.32, height: tile * 0.32, border: `1px solid ${ACCENT}`, opacity: 0.5 }} />}
                        {isExtraction && !isPlayer && (
                          <>
                            <span className="exp-beacon absolute rounded-full" style={{ width: tile * 0.66, height: tile * 0.66, border: `1.5px solid ${AMBER}`, boxShadow: `0 0 12px ${AMBER}44` }} />
                            <span className="exp-beckon" style={{ color: AMBER, fontSize: tile * 0.58, textShadow: `0 0 16px ${AMBER}` }}>⊕</span>
                          </>
                        )}
                        {node && !looted && !isPlayer && (
                          <span className="exp-beckon relative flex items-center justify-center">
                            <span className="absolute rounded-full" style={{ width: tile * 0.55, height: tile * 0.55, background: `radial-gradient(circle, ${ACCENT}33, transparent 70%)`, boxShadow: `0 0 8px ${ACCENT}22` }} />
                            <span style={{ color: ACCENT, fontSize: tile * 0.5, textShadow: `0 0 10px ${ACCENT}` }}>▣</span>
                          </span>
                        )}
                        {node && looted && !isPlayer && <span style={{ color: FAINT, fontSize: tile * 0.45, opacity: 0.35 }}>□</span>}
                        {enemy && (
                          <span className="exp-threat relative flex items-center justify-center" style={{ width: tile * 0.78, height: tile * 0.78 }}>
                            <span className="absolute rounded-full" style={{ inset: 0, background: `radial-gradient(circle, rgba(204,85,80,0.42), transparent 68%)` }} />
                            <span className="relative flex items-center justify-center rounded-full" style={{ width: tile * 0.58, height: tile * 0.58, background: 'rgba(18,8,8,0.94)', border: `1.5px solid ${DANGER}`, color: DANGER, fontSize: tile * 0.34, boxShadow: `0 0 12px ${DANGER}aa, inset 0 0 8px rgba(204,85,80,0.4)` }}>{DIR_ARROW[enemy.cone.dir]}</span>
                          </span>
                        )}
                        {isPlayer && (
                          <span className="relative flex items-center justify-center" style={{ width: tile * 0.78, height: tile * 0.78 }}>
                            <span className="exp-halo absolute rounded-full" style={{ inset: -2, background: `radial-gradient(circle, ${opColor}66, transparent 68%)` }} />
                            <span className="relative" style={{ width: tile * 0.5, height: tile * 0.5, borderRadius: 3, background: `linear-gradient(135deg, ${opColor}, ${opColor}cc)`, boxShadow: `0 0 16px ${opColor}, inset 0 0 5px rgba(255,255,255,0.5), 0 2px 4px rgba(0,0,0,0.4)`, border: '1px solid rgba(255,255,255,0.55)' }} />
                          </span>
                        )}
                      </button>
                    );
                  })
                )}
              </div>
            )}
            {status === 'loading' && (
              <div className="p-10 text-center">
                <div className="inline-block w-8 h-8 rounded-full border-2 border-t-transparent animate-spin mb-3" style={{ borderColor: `${ACCENT} transparent ${ACCENT}44 ${ACCENT}44` }} />
                <div className="text-sm tracking-widest" style={{ color: MUTED }}>LOADING MISSION DATA...</div>
              </div>
            )}
          </div>

          {/* ══ D-pad + end turn ══ */}
          {status === 'playing' && (
            <div className="z-10 mt-4 mb-4 flex items-center gap-6">
              <div className="grid grid-cols-3 gap-1.5" style={{ width: 156 }}>
                <span /><DPad label="▲" onClick={() => attemptMove(0, -1)} /><span />
                <DPad label="◀" onClick={() => attemptMove(-1, 0)} /><DPad label="▾" onClick={() => attemptMove(0, 1)} /><DPad label="▶" onClick={() => attemptMove(1, 0)} />
              </div>
              <button onClick={endTurn} className="px-6 py-3.5 text-xs tracking-widest rounded-lg active:scale-95 transition-all" style={{ border: '1px solid var(--pop)', color: '#11100e', background: 'var(--pop)', boxShadow: '0 0 22px rgba(var(--pop-rgb),0.5), 0 2px 8px rgba(0,0,0,0.4)' }}>END TURN</button>
            </div>
          )}
          <div className="z-10 pb-4 text-[9px] flex flex-wrap gap-x-4 gap-y-1 justify-center px-4" style={{ color: FAINT }}>
            <span style={{ color: opColor }}>{operative.glyph} YOU</span>
            <span style={{ color: DANGER }}>▶ GUARD (vision)</span>
            <span style={{ color: ACCENT }}>▣ SALVAGE</span>
            <span style={{ color: AMBER }}>⊕ EXTRACTION</span>
            <span>WASD / TAP · SPACE=WAIT · Q=ABILITY · E=DIRECTIVE</span>
          </div>
        </>
      )}

      {/* ═══ ENCOUNTER MODAL ═══ */}
      {encounter && game && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bmf-glass-overlay">
          <div className="w-full max-w-md rounded-xl overflow-hidden" style={{ ...panelStyle({ borderColor: BORDER_STRONG }), boxShadow: `0 12px 40px rgba(0,0,0,0.7), 0 0 0 1px rgba(0,0,0,0.3), inset 0 1px 0 rgba(255,255,255,0.03)` }}>
