              </span>
            </div>
            <div className="p-4">
              {foggy && !fogLifted && (
                <div className="text-[9px] mb-3 px-2.5 py-1.5 rounded-md flex items-center gap-2" style={{ color: TEAL, border: `1px solid ${TEAL}33`, background: 'rgba(122,184,184,0.06)', boxShadow: `inset 0 0 12px ${TEAL}08` }}>
