              )}
              <p className="text-xs leading-relaxed mb-3" style={{ color: INK }}>
                &ldquo;{(foggy && !fogLifted ? fogTokens : [{ text: encounter.enc.text, blot: false }]).map((t, i) => (
                  t.blot
                    ? <span key={i} style={{ background: MUTED, color: 'transparent', borderRadius: 2, boxShadow: 'inset 0 0 0 1px rgba(0,0,0,0.3)', userSelect: 'none' }}>{t.text}</span>
                    : <span key={i}>{t.text}</span>
                ))}&rdquo;
              </p>
              {foggy && !fogLifted ? (
                <>
                  <p className="text-[10px] mb-2" style={{ color: FAINT }}>ANCHORS: <span style={{ background: MUTED, color: 'transparent', borderRadius: 2, userSelect: 'none' }}>signal lost in the fog</span></p>
                  <button onClick={liftFog} disabled={game.cigarettes <= 0} className="w-full mb-3 px-3 py-2.5 text-[10px] tracking-widest rounded-md active:scale-[0.98] transition-transform" style={{ border: `1px solid ${game.cigarettes > 0 ? ACCENT : BORDER}`, color: game.cigarettes > 0 ? '#11100e' : FAINT, background: game.cigarettes > 0 ? ACCENT : 'rgba(255,255,255,0.02)', boxShadow: game.cigarettes > 0 ? `0 0 16px ${ACCENT}55` : undefined }}>
                    {game.cigarettes > 0 ? `BURN A DURRY — LIFT THE FOG (${game.cigarettes} LEFT)` : 'OUT OF DURRIES — FOG HOLDS'}
