              {game.autoWinArmed && <div className="text-[9px] mb-3 px-2.5 py-1.5 rounded-md" style={{ color: DANGER, border: `1px solid ${DANGER}44`, background: 'rgba(204,85,80,0.06)' }}>STRONG-ARM ENGAGED — ANY CHOICE FOLDS THEM</div>}
              <div className="flex flex-col gap-2">
                {encounter.enc.responses.map((r, i) => {
                  const reveal = decoderIndex === i;
                  return (
                    <button key={r.id} onClick={() => resolveEncounter(i)} className="text-left px-3.5 py-2.5 text-[11px] rounded-md active:scale-[0.98] transition-all" style={{ border: `1px solid ${reveal ? ACCENT : BORDER}`, color: INK, background: reveal ? `${ACCENT}18` : 'rgba(255,255,255,0.02)', boxShadow: reveal ? `0 0 16px ${ACCENT}44, inset 0 0 8px ${ACCENT}11` : 'inset 0 1px 0 rgba(255,255,255,0.02)' }}>
