            </div>
          </div>
        </div>
      )}

      {/* ═══ WIN / LOSE OVERLAY ═══ */}
      {(status === 'won' || status === 'lost') && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 bmf-glass-overlay">
          <div className="text-center max-w-sm rounded-xl overflow-hidden" style={panelStyle({ borderColor: status === 'won' ? `${ACCENT}88` : `${DANGER}88` })}>
