              <p className="text-[10px]" style={{ color: MUTED }}>{operative.name} · TURN {game?.turn ?? 1}</p>
            </div>
            <div className="px-6 pb-5">
              {/* stats row */}
              <div className="flex justify-center gap-4 mb-4 py-3 rounded-md" style={{ background: 'rgba(0,0,0,0.25)', border: `1px solid ${BORDER}` }}>
                <div className="text-center">
                  <div className="text-lg" style={{ color: ACCENT }}>{game?.looted.length ?? 0}<span className="text-xs" style={{ color: FAINT }}>/{map?.garbage_nodes.length ?? 0}</span></div>
                  <div className="text-[8px] tracking-widest" style={{ color: FAINT }}>SALVAGE</div>
                </div>
                <div className="w-px" style={{ background: BORDER }} />
                <div className="text-center">
                  <div className="text-lg" style={{ color: hot ? DANGER : warm ? AMBER : ACCENT }}>{game?.heat ?? 0}</div>
                  <div className="text-[8px] tracking-widest" style={{ color: FAINT }}>HEAT</div>
                </div>
                <div className="w-px" style={{ background: BORDER }} />
                <div className="text-center">
                  <div className="text-lg" style={{ color: INK }}>{game?.turn ?? 1}</div>
                  <div className="text-[8px] tracking-widest" style={{ color: FAINT }}>TURNS</div>
                </div>
              </div>
              <p className="text-[10px] mb-4 max-w-xs mx-auto" style={{ color: FAINT }}>
