              <div className="flex gap-2 justify-center">
                <button onClick={() => startMission(operative)} className="px-5 py-2.5 text-xs tracking-widest rounded-md active:scale-95 transition-all" style={{ border: `1px solid ${ACCENT}`, color: '#11100e', background: ACCENT, boxShadow: `0 0 16px ${ACCENT}44` }}>NEW MISSION</button>
