}

function abilityArmedLabel(id: OperativeId, g: BoardState | null): string {
  if (!g) return 'READY';
  if (id === 'sid' && g.heatShield) return 'ARMED';
  if (id === 'mikey' && g.scavengerPrimed) return 'PRIMED';
  if (id === 'dave' && g.decoderArmed) return 'ARMED';
  return 'READY';
}
function directiveArmedLabel(id: OperativeId, g: BoardState | null): string {
  if (!g) return 'READY';
  if (id === 'tamara' && g.coneBlackout > 0) return 'ACTIVE';
  if (id === 'sid' && g.autoWinArmed) return 'ARMED';
  return 'READY';
}
function DPad({ label, onClick }: { label: string; onClick: () => void }) {
  return <button onClick={onClick} className="flex items-center justify-center py-3 text-sm rounded-md active:scale-90 transition-all" style={{ border: '1px solid rgba(216,199,163,0.22)', color: '#8aad7a', background: 'rgba(33,30,25,0.94)', boxShadow: '0 2px 4px rgba(0,0,0,0.4), inset 0 1px 0 rgba(255,255,255,0.03)', textShadow: '0 0 8px rgba(138,173,122,0.3)' }}>{label}</button>;
}

