import Stripe from 'stripe'
import { randomBytes } from 'crypto'
import { prisma } from './db'

let client: Stripe | null = null

/** null until STRIPE_SECRET_KEY is set — callers show CHECKOUT NOT CONFIGURED */
export function getStripe(): Stripe | null {
  const key = process.env.STRIPE_SECRET_KEY
  if (!key) return null
  if (!client) client = new Stripe(key)
  return client
}

export const stripeReady = () => Boolean(process.env.STRIPE_SECRET_KEY)

const ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789' // 32 chars, no 0/O/1/I — 256 % 32 = 0, so no modulo bias
function randomGroups(groups: number) {
  const bytes = randomBytes(groups * 4)
  const chars = Array.from(bytes, (b) => ALPHABET[b % ALPHABET.length])
  return Array.from({ length: groups }, (_, i) => chars.slice(i * 4, i * 4 + 4).join('')).join('-')
}

/** Legacy profile token: BV-XXXX-XXXX */
export function newUnlockToken() {
  return `BV-${randomGroups(2)}`
}

/** Single-use purchase code: BV-XXXX-XXXX-XXXX (60 bits of crypto randomness) */
export function newUnlockCode() {
  return `BV-${randomGroups(3)}`
}

const paymentIdOf = (session: Stripe.Checkout.Session) =>
  typeof session.payment_intent === 'string' ? session.payment_intent : session.payment_intent?.id ?? null

/** One unlock code per paid Checkout Session. Idempotent on stripeSessionId (webhook retries + success page). */
export async function issueUnlockCode(session: Stripe.Checkout.Session, userId: string | null) {
  const existing = await prisma.unlockCode.findUnique({ where: { stripeSessionId: session.id } })
  if (existing) return existing
  for (let attempt = 0; attempt < 5; attempt++) {
    try {
      return await prisma.unlockCode.create({
        data: {
          code: newUnlockCode(),
          stripeSessionId: session.id,
          paymentIntentId: paymentIdOf(session),
          email: session.customer_details?.email?.trim().toLowerCase() ?? null,
          userId,
          amountTotal: session.amount_total ?? null,
          currency: session.currency ?? null,
        },
      })
    } catch (e: any) {
      if (e?.code !== 'P2002') throw e
      // Unique clash: either a concurrent delivery already stored this session, or a code collision — re-check, then retry
      const raced = await prisma.unlockCode.findUnique({ where: { stripeSessionId: session.id } })
      if (raced) return raced
    }
  }
  throw new Error('could not allocate a unique unlock code')
}

/**
 * Fulfils a paid Checkout Session by issuing exactly one single-use unlock code (idempotent on the session).
 * The entitlement is granted only when that code is redeemed to a signed-in profile (/api/unlock/redeem).
 * UnlockCode.userId stays null until redemption, then holds the redeeming profile.
 */
export async function fulfilCheckout(session: Stripe.Checkout.Session): Promise<{ ok: boolean; code?: string; reason?: string }> {
  if (session.payment_status !== 'paid') return { ok: false, reason: 'unpaid' }
  const unlock = await issueUnlockCode(session, null)
  return { ok: true, code: unlock.code }
}

