export interface MapTile {
  id: number;
  name: string;
  coords: number[][];
  conflict: string;
  resources: string[];
  color: string;
}

export function getTileAt(x: number, y: number): MapTile | null {
  for (const tile of MAP_TILES) {
    for (const [cx, cy] of tile?.coords ?? []) {
      if (cx === x && cy === y) return tile;
    }
  }
  return null;
}

export function getConflictLevel(conflict: string): number {
  const map: Record<string, number> = {
    'Low': 1, 'Low-Medium': 2, 'Medium': 3, 'Medium-High': 4, 'High': 5, 'High-Risk': 6, 'Extreme': 7
  };
  return map[conflict] ?? 0;
}

export function getHeatPhase(moves: number): 'cool' | 'warm' | 'burning' {
  if (moves <= 8) return 'cool';
  if (moves <= 16) return 'warm';
  return 'burning';
}

export function getHeatColor(phase: string): string {
  if (phase === 'cool') return '#8aad7a';
  if (phase === 'warm') return '#FFFF00';
  return '#a8687e';
}

