// ========================
// STAT MODIFIERS — Philosophy & Stats affect gameplay
// ========================

export interface StatModifiers {
  heatGainMultiplier: number;      // NERVE reduces heat gain
  affinityGainMultiplier: number;  // INSIGHT boosts affinity
  toleranceDecayMultiplier: number;// PRESENCE slows tolerance
  lootBonusMultiplier: number;     // MOBILITY improves loot
  expeditionMoveBonus: number;     // extra expedition moves
  conflictBonus: number;           // conflict success bonus
}

export function calculateStatModifiers(
  nerve: number, insight: number, presence: number, mobility: number,
  philosophy: string
): StatModifiers {
  // Philosophy multipliers
  const philMods: Record<string, { pres: number; ins: number; nerv: number; mob: number }> = {
    SHEPHERD:     { pres: 1.2, ins: 1.1, nerv: 1.0, mob: 1.0 },
    ENTREPRENEUR: { pres: 1.0, ins: 1.0, nerv: 1.1, mob: 1.2 },
    PROPHET:      { pres: 1.0, ins: 1.1, nerv: 1.2, mob: 1.0 },
  };
  const pm = philMods[philosophy] ?? philMods.SHEPHERD;

  return {
    heatGainMultiplier: Math.max(0.3, 1.0 - (nerve * pm.nerv * 0.08)),
    affinityGainMultiplier: 1.0 + (insight * pm.ins * 0.06),
    toleranceDecayMultiplier: Math.max(0.4, 1.0 - (presence * pm.pres * 0.07)),
    lootBonusMultiplier: 1.0 + (mobility * pm.mob * 0.1),
    expeditionMoveBonus: Math.floor(mobility * pm.mob * 0.5),
    conflictBonus: nerve * pm.nerv * 0.03,
  };
}

