// ========================
// MANAGER'S NOTES (v2.0)
// A short note from the Manager slips in each new day. Deterministic
// selection via `day % MEMO_POOL.length`. Voice: the calculated watcher —
// quiet, certain, never raising his voice. Every line hints that he chose
// each recruit deliberately, that he has been observing far longer than
// they realise, and that he knows exactly WHY he picked them — without ever
// saying it outright. No corporate/office framing. No emojis. Short.
// ========================

export const MEMO_POOL: string[] = [
  'I picked you for a reason. You will work out what it is.',
  'I watched you a long time before you ever saw me.',
  'The cigarette is not a gift. Nothing here is a gift.',
  'You did not find this place. It found you.',
  'Dave thinks he chose to stay. Let him think that.',
  'Tamara watches the doors. I watch her watching.',
  'Sid breaks things. I decide which things.',
  'Mikey talks too much. He is usually right. Ignore him anyway.',
  'I do not collect the desperate. I collect the useful.',
  'Everyone here was chosen. None of you were asked.',
  'Heat rises. Good. I like to see who keeps still.',
  'I know what you were before. That is exactly why.',
  'Smoke when I offer. Refusing tells me more than you would like.',
  'You are not the first I have built. You may last longer.',
  'Loyalty I can measure. I am measuring now.',
  'The ones who run get remembered. Just not fondly.',
  'There is a version of you that walked away. He is not here.',
  'I never raise my voice. I have never had to.',
];

export function getMemoForDay(day: number): string {
  if (!MEMO_POOL.length) return '';
  const idx = ((day - 1) % MEMO_POOL.length + MEMO_POOL.length) % MEMO_POOL.length;
  return MEMO_POOL[idx];
}

