.mode-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-3) var(--space-4);
  color: var(--color-text-muted);
  font-family: var(--font-mono);
  font-size: var(--text-sm);
}

.toggle-dot {
  width: 1rem;
  height: 1rem;
  border-radius: 50%;
  background: var(--color-secondary);
  box-shadow: 0 0 1rem var(--color-secondary);
}

.stage {
  min-width: 0;
  padding: var(--space-6);
}

.topbar {
  display: flex;
  gap: var(--space-4);
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--space-6);
}

.status-strip {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  justify-content: flex-end;
}

.status-pill {
  display: inline-flex;
  min-height: 2rem;
  align-items: center;
  border: 1px solid var(--color-border);
  border-radius: 999px;
  padding: 0 var(--space-3);
  background: rgba(0, 0, 0, 0.18);
  color: var(--color-text-muted);
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  font-weight: 700;
}

.status-pill.good {
  color: var(--color-secondary);
}

.status-pill.warn {
  color: var(--color-warning);
}

.status-pill.bad {
  color: var(--color-danger);
}

.screen {
  display: none;
  min-height: calc(100dvh - 9rem);
}

.screen.is-visible {
  display: block;
  animation: screenIn 220ms cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes screenIn {
  from {
    opacity: 0;
    transform: translateY(0.5rem);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.title-layout,
.hud-grid,
.recruit-layout,
.encounter-layout,
.travel-layout,
.codex-layout,
.sleep-layout,
.finale-layout,
.kit-layout {
  display: grid;
  gap: var(--space-6);
}

.title-layout,
.hud-grid,
.recruit-layout,
.encounter-layout,
.travel-layout,
.sleep-layout,
.finale-layout {
  grid-template-columns: minmax(0, 1.55fr) minmax(18rem, 0.75fr);
}

.hero-panel,
.scene-window,
.portrait-card,
.actor-sheet,
.dose-console,
.map-panel,
.document-panel,
.ritual-image,
.ritual-panel,
.finale-target,
.kit-card,
.stack-panel > *,
.route-card,
.hud-panel {
