}

.stack-panel {
  display: grid;
  gap: var(--space-4);
  align-content: start;
}

.template-note,
.save-card,
.hud-panel,
.actor-sheet,
.dose-console,
.route-card,
.document-panel,
.ritual-panel,
.kit-card {
