  flex-wrap: wrap;
  gap: var(--space-2);
}

.crew-chips span {
  padding: var(--space-2) var(--space-3);
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.54);
  color: var(--color-paper);
  font-family: var(--font-mono);
  font-size: var(--text-xs);
}

.hud-panel {
  display: grid;
  gap: var(--space-5);
  align-content: start;
}

.meter-header {
