}

.node-house {
  left: 8%;
  top: 15%;
}

.node-store {
  left: 43%;
  top: 46%;
}

.node-bus {
  right: 11%;
  top: 17%;
}

.node-alley {
  right: 8%;
  bottom: 21%;
}

.node-payphone {
  left: 9%;
  bottom: 19%;
}

.node-overpass {
  right: 27%;
  top: 46%;
}

.travel-head {
