export default function DisclaimerScreen({ onContinue }: { onContinue: () => void }) {
  const [hovered, setHovered] = useState(false);
  const [glitchDone, setGlitchDone] = useState(false);
  const [showContent, setShowContent] = useState(false);
  const completedRef = useRef(false);

  // Preload assets for the next screens
  useEffect(() => {
    preloadIntroDialogue();
    preloadMenuTransitionSpeech();
    preloadMenuMusic();

    const imageKeys = [
      '/images/target-character.jpg',
      '/images/main-menu-bedroom-still.jpg',
    ];
    const links: HTMLLinkElement[] = [];
    for (const href of imageKeys) {
      try {
        const l = document.createElement('link');
        l.rel = 'preload';
        l.as = 'image';
        l.href = href;
        document.head.appendChild(l);
        links.push(l);
      } catch { /* ignore */ }
    }
    try {
      const vl = document.createElement('link');
      vl.rel = 'preload';
      vl.as = 'video';
      vl.href = '/videos/main-menu-intro.mp4';
      vl.setAttribute('type', 'video/mp4');
      document.head.appendChild(vl);
      links.push(vl);
    } catch { /* ignore */ }

    return () => {
      for (const l of links) {
        try { l.parentElement?.removeChild(l); } catch { /* ignore */ }
      }
    };
  }, []);

  // Brief glitch on entry, then reveal content
  useEffect(() => {
    const t1 = setTimeout(() => setGlitchDone(true), 500);
    const t2 = setTimeout(() => setShowContent(true), 600);
    return () => { clearTimeout(t1); clearTimeout(t2); };
  }, []);

  // Keyboard: Enter or Space to proceed
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if ((e.key === 'Enter' || e.key === ' ') && showContent) {
        e.preventDefault();
        finish();
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [showContent]);

  const finish = useCallback(() => {
    if (completedRef.current) return;
    completedRef.current = true;
    audioManager.playSFX('nav');
