          background:
            'radial-gradient(ellipse 70% 70% at 50% 50%, transparent 30%, rgba(0,0,0,0.6) 100%)',
        }}
      />

      {/* Subtle noise grain */}
      <div
        className="absolute inset-0 pointer-events-none z-10 opacity-[0.06]"
