          backgroundImage:
            'repeating-radial-gradient(circle, rgba(138,173,122,0.15) 0px, transparent 1px, transparent 3px)',
          backgroundSize: '3px 3px',
        }}
      />

      {/* Entry glitch effect */}
      {!glitchDone && (
        <motion.div
          className="absolute inset-0 z-40 pointer-events-none"
          initial={{ opacity: 1 }}
          animate={{ opacity: 0 }}
          transition={{ duration: 0.5, ease: 'easeOut' }}
        >
          {/* Horizontal glitch slices */}
          {[15, 30, 48, 62, 78].map((top, i) => (
            <motion.div
              key={i}
              className="absolute left-0 right-0"
              style={{
                top: `${top}%`,
                height: `${3 + (i % 3)}%`,
                background: `rgba(138,173,122,${0.08 + (i % 3) * 0.04})`,
                mixBlendMode: 'screen',
              }}
              initial={{ x: i % 2 === 0 ? -20 : 20, opacity: 0.8 }}
              animate={{ x: 0, opacity: 0 }}
              transition={{ duration: 0.3 + i * 0.05 }}
            />
          ))}
          {/* Brief chromatic aberration flash */}
          <motion.div
            className="absolute inset-0"
            style={{
              background: 'linear-gradient(90deg, rgba(255,0,80,0.06) 0%, transparent 30%, transparent 70%, rgba(0,255,200,0.06) 100%)',
            }}
            animate={{ opacity: [0.8, 0] }}
            transition={{ duration: 0.4 }}
          />
        </motion.div>
      )}

      {/* Content container */}
      <motion.div
        initial={{ opacity: 0, y: 10 }}
        animate={{ opacity: showContent ? 1 : 0, y: showContent ? 0 : 10 }}
        transition={{ duration: 0.6, ease: 'easeOut' }}
        className="max-w-2xl w-full relative z-10"
      >
        {/* Terminal frame */}
        <div
