import { PutObjectCommand, DeleteObjectCommand, GetObjectCommand } from '@aws-sdk/client-s3'
import { getSignedUrl } from '@aws-sdk/s3-request-presigner'
import { createS3Client, getBucketConfig } from './aws-config'

const s3 = createS3Client()

export async function generatePresignedUploadUrl(fileName: string, contentType: string, isPublic = true, folder: 'uploads' | 'gallery' = 'uploads') {
  const { bucketName, folderPrefix } = getBucketConfig()
  const safe = fileName.replace(/[^a-zA-Z0-9._-]/g, '_')
  const cloud_storage_path = isPublic
    ? `${folderPrefix}public/${folder}/${Date.now()}-${safe}`
    : `${folderPrefix}uploads/${Date.now()}-${safe}`
  const command = new PutObjectCommand({ Bucket: bucketName, Key: cloud_storage_path, ContentType: contentType })
  const uploadUrl = await getSignedUrl(s3, command, { expiresIn: 3600 })
  return { uploadUrl, cloud_storage_path }
}

export async function getFileUrl(cloud_storage_path: string, isPublic: boolean) {
  const { bucketName } = getBucketConfig()
  if (isPublic) {
    const region = process.env.AWS_REGION ?? 'us-east-1'
    const encoded = cloud_storage_path.split('/').map(encodeURIComponent).join('/')
    return `https://${bucketName}.s3.${region}.amazonaws.com/${encoded}`
  }
  const command = new GetObjectCommand({ Bucket: bucketName, Key: cloud_storage_path })
  return getSignedUrl(s3, command, { expiresIn: 3600 })
}

export async function deleteFile(cloud_storage_path: string) {
  const { bucketName } = getBucketConfig()
  await s3.send(new DeleteObjectCommand({ Bucket: bucketName, Key: cloud_storage_path }))
}

import { type ClassValue, clsx } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

export function formatDuration(seconds: number): string {
  const hours = Math.floor(seconds / 3600)
  const minutes = Math.floor((seconds % 3600) / 60)
  const remainingSeconds = seconds % 60

  return `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${remainingSeconds.toString().padStart(2, '0')}`
}

