'use client'

import { memo } from 'react'
import { useHud } from './hud-context'

interface ScanSystemProps {
  blueMode?: boolean
}

/**
 * The lens the pitch is read through.
 *  - persistent scanline texture + vignette (always on when field is powered)
 *  - a sweeping band fired every 10s by the HUD clock, or on demand via SYS CHECK
 */
function ScanSystemInner({ blueMode = false }: ScanSystemProps) {
  const { power, gain, hue, scanKey } = useHud()

  const sweepColor = blueMode ? '#3D9BE9' : '#E040B0'
  const lineColor = blueMode ? '#3D9BE9' : '#B8F026'

  // Field strength drives everything. Powered-down = bare glass.
  const strength = power ? 0.25 + gain * 0.75 : 0
  const hueShift = Math.round((hue - 0.5) * 44)

  return (
    <div
      className="absolute inset-0 pointer-events-none z-[45] overflow-hidden"
      style={{ filter: hueShift !== 0 ? `hue-rotate(${hueShift}deg)` : undefined }}
      aria-hidden="true"
    >
      {/* Persistent scanline texture */}
      <div
        className="absolute inset-0"
        style={{
          backgroundImage: `repeating-linear-gradient(to bottom, ${lineColor}0D 0px, ${lineColor}0D 1px, transparent 1px, transparent 3px)`,
          opacity: strength * 0.55,
          mixBlendMode: 'screen',
        }}
      />

      {/* Coarse interlace — slower, heavier band structure */}
      <div
        className="absolute inset-0"
        style={{
          backgroundImage: `repeating-linear-gradient(to bottom, rgba(0,0,0,0.28) 0px, rgba(0,0,0,0.28) 2px, transparent 2px, transparent 8px)`,
          opacity: strength * 0.24,
        }}
      />

      {/* Lens vignette — we are inside the housing, looking out */}
      <div
        className="absolute inset-0"
        style={{
          background: `radial-gradient(ellipse at 50% 45%, transparent 46%, rgba(0,0,0,0.30) 88%, rgba(0,0,0,0.55) 100%)`,
          opacity: 0.3 + strength * 0.4,
        }}
      />

      {/* Corner optic falloff */}
      <div
        className="absolute inset-0"
        style={{
          boxShadow: `inset 0 0 100px 12px rgba(0,0,0,0.42)`,
          opacity: 0.4 + strength * 0.3,
        }}
      />

      {/* 10-second sweep band */}
      {power && (
        <div key={scanKey} className="absolute inset-x-0 top-0 scan-sweep-band">
          <div
            style={{
              height: 120,
              background: `linear-gradient(to bottom, transparent, ${sweepColor}0A 35%, ${sweepColor}22 50%, ${sweepColor}0A 65%, transparent)`,
              opacity: strength,
            }}
          />
          <div
            style={{
              height: 1,
              background: sweepColor,
              opacity: strength * 0.55,
              boxShadow: `0 0 8px ${sweepColor}`,
            }}
          />
        </div>
      )}
    </div>
  )
}

const ScanSystem = memo(ScanSystemInner)
export default ScanSystem

'use client'

import { memo } from 'react'
import { useHud } from './hud-context'
import { signatureFor, paletteFor, MAGENTA } from './overlay-signatures'

// Fixed dropout pattern for DECAY mode. Deterministic so SSR and client agree.
const DECAY_MASK = [true, true, false, true, false, false, true, true, false, true, true, false, true, false, true, true]

interface OverlayFrameProps {
  tabId: string
  blueMode?: boolean
}

// The glaze over the reading area: measurement, registration, legends.
// The colour housing lives at viewport level in <EdgeBloom />.
function OverlayFrameInner({ tabId, blueMode = false }: OverlayFrameProps) {
  const hud = useHud()
  const power = hud.power
  const gain = hud.gain
  const hue = hud.hue
  const mode = hud.mode

  const sig = signatureFor(tabId)
  const palette = paletteFor(blueMode)

  const lineColor = palette.lime
  const accentColor = blueMode ? '#3D9BE9' : MAGENTA
  const topC = palette[sig.top]
  const bottomC = palette[sig.bottom]
  const leftC = palette[sig.left]
  const rightC = palette[sig.right]

  // Powered down still leaves the housing visible, just inert.
  const strength = power ? 0.3 + gain * 0.7 : 0.12
  const frameOpacity = 0.9 * (0.5 + strength * 0.5)
  const fieldOpacity = (sig.dense ? 0.13 : 0.09) * strength
  const accentOpacity = 0.62 * (0.4 + strength * 0.6)
  const hueShift = Math.round((hue - 0.5) * 44)

  const gridCols = mode === 'partition' ? [33.333, 66.666] : sig.dense ? [12.5, 25, 37.5, 50, 62.5, 75, 87.5] : [25, 50, 75]
  const gridRows = mode === 'partition' ? [50] : sig.dense ? [12.5, 25, 37.5, 50, 62.5, 75, 87.5] : [25, 50, 75]

  const decayGrad = `repeating-linear-gradient(to right, ${lineColor} 0 6px, transparent 6px 18px)`
  const decayGradV = `repeating-linear-gradient(to bottom, ${lineColor} 0 6px, transparent 6px 18px)`

  return (
    <div
      className="absolute inset-0 pointer-events-none z-50 overflow-hidden"
      style={hueShift !== 0 ? { filter: `hue-rotate(${hueShift}deg)` } : undefined}
      aria-hidden="true"
    >
      {/* registration rules — PARTITION nudges them inward */}
      <div
        className={mode === 'partition' ? 'absolute inset-4 md:inset-7 border' : 'absolute inset-3 md:inset-5 border'}
        style={{ borderColor: `${lineColor}2E`, opacity: frameOpacity }}
      />
      <div
        className="absolute inset-6 md:inset-9 border"
        style={{ borderColor: `${accentColor}1C`, opacity: accentOpacity }}
      />

      {/* inner corner brackets, tinted to this screen's signature */}
      <div className="absolute top-3 left-3 md:top-5 md:left-5" style={{ opacity: frameOpacity }}>
        <div className="w-7 md:w-10 h-px" style={{ background: topC }} />
        <div className="w-px h-7 md:h-10" style={{ background: leftC }} />
      </div>
      <div className="absolute top-3 right-3 md:top-5 md:right-5 flex flex-col items-end" style={{ opacity: frameOpacity }}>
        <div className="w-7 md:w-10 h-px" style={{ background: topC }} />
        <div className="w-px h-7 md:h-10 self-end" style={{ background: rightC }} />
      </div>
      <div className="absolute bottom-3 left-3 md:bottom-5 md:left-5 flex flex-col justify-end" style={{ opacity: frameOpacity }}>
        <div className="w-px h-7 md:h-10" style={{ background: leftC }} />
        <div className="w-7 md:w-10 h-px" style={{ background: bottomC }} />
      </div>
      <div className="absolute bottom-3 right-3 md:bottom-5 md:right-5 flex flex-col items-end justify-end" style={{ opacity: frameOpacity }}>
        <div className="w-px h-7 md:h-10 self-end" style={{ background: rightC }} />
        <div className="w-7 md:w-10 h-px" style={{ background: bottomC }} />
      </div>

      {/* measurement field — suppressed on the title card */}
      {!sig.bare && (
        <>
          <div style={{ opacity: fieldOpacity }}>
            {gridRows.map((p) => (
              <div
                key={`fh-${p}`}
                className="absolute left-0 right-0 h-px"
                style={{ top: `${p}%`, background: mode === 'decay' ? decayGrad : lineColor }}
              />
            ))}
            {gridCols.map((p) => (
              <div
                key={`fv-${p}`}
                className="absolute top-0 bottom-0 w-px"
                style={{ left: `${p}%`, background: mode === 'decay' ? decayGradV : lineColor }}
              />
            ))}
            {mode === 'partition' && (
              <>
                <div className="absolute top-0 bottom-0 w-px" style={{ left: 'calc(33.333% + 3px)', background: accentColor }} />
                <div className="absolute top-0 bottom-0 w-px" style={{ left: 'calc(66.666% + 3px)', background: accentColor }} />
              </>
            )}
          </div>

          {mode === 'decay' && (
            <div className="absolute inset-0 grid grid-cols-4 grid-rows-4" style={{ opacity: fieldOpacity * 1.6 }}>
              {DECAY_MASK.map((on, i) => (
                <div key={i} style={{ background: on ? `${accentColor}18` : 'transparent' }} />
              ))}
            </div>
          )}

          <div className="absolute top-3 md:top-5 left-12 md:left-16 right-12 md:right-16 flex justify-between" style={{ opacity: frameOpacity * 0.45 }}>
            {Array.from({ length: sig.ticksX }).map((_, i) => (
              <div key={i} style={{ width: 1, height: i % 4 === 0 ? 6 : 3, background: i % 4 === 0 ? topC : lineColor }} />
            ))}
          </div>
          <div className="absolute bottom-3 md:bottom-5 left-12 md:left-16 right-12 md:right-16 flex justify-between items-end" style={{ opacity: frameOpacity * 0.35 }}>
            {Array.from({ length: sig.ticksX }).map((_, i) => (
              <div key={i} style={{ width: 1, height: i % 4 === 0 ? 6 : 3, background: i % 4 === 0 ? bottomC : lineColor }} />
            ))}
          </div>
          <div className="absolute left-3 md:left-5 top-12 md:top-16 bottom-12 md:bottom-16 flex flex-col justify-between" style={{ opacity: frameOpacity * 0.35 }}>
            {Array.from({ length: sig.ticksY }).map((_, i) => (
              <div key={i} style={{ height: 1, width: i % 5 === 0 ? 6 : 3, background: i % 5 === 0 ? leftC : lineColor }} />
            ))}
          </div>
          <div className="absolute right-3 md:right-5 top-12 md:top-16 bottom-12 md:bottom-16 flex flex-col justify-between items-end" style={{ opacity: frameOpacity * 0.35 }}>
            {Array.from({ length: sig.ticksY }).map((_, i) => (
              <div key={i} style={{ height: 1, width: i % 5 === 0 ? 6 : 3, background: i % 5 === 0 ? rightC : lineColor }} />
            ))}
          </div>

          <div className="absolute" style={{ left: '50%', top: '50%', transform: 'translate(-50%, -50%)', opacity: accentOpacity * 0.55 }}>
            <div className="relative" style={{ width: 26, height: 26 }}>
              <div className="absolute" style={{ left: 0, top: '50%', width: 8, height: 1, background: accentColor }} />
              <div className="absolute" style={{ right: 0, top: '50%', width: 8, height: 1, background: accentColor }} />
              <div className="absolute" style={{ top: 0, left: '50%', height: 8, width: 1, background: accentColor }} />
              <div className="absolute" style={{ bottom: 0, left: '50%', height: 8, width: 1, background: accentColor }} />
            </div>
          </div>
        </>
      )}

      <div
        className="absolute top-3 md:top-5 left-1/2 -translate-x-1/2 -translate-y-1/2 px-2 text-[7px] uppercase tracking-wide-label whitespace-nowrap"
        style={{ background: '#0A0A08', color: topC, opacity: frameOpacity * 0.85 }}
      >
        3K OVERLAY / {sig.legend}
      </div>
      <div
        className="absolute bottom-3 md:bottom-5 left-1/2 -translate-x-1/2 translate-y-1/2 px-2 text-[7px] uppercase tracking-wide-label whitespace-nowrap"
        style={{ background: '#0A0A08', color: bottomC, opacity: accentOpacity * 0.95 }}
      >
        {power ? `FIELD ${String(Math.round(gain * 100)).padStart(3, '0')} / ${mode.toUpperCase()}` : 'FIELD SUPPRESSED'}
      </div>
    </div>
  )
}

const OverlayFrame = memo(OverlayFrameInner)
export default OverlayFrame

