];

export default function OnboardingCarousel({ onComplete }: Props) {
  const [step, setStep] = useState(0);
  const touchRef = useRef<number | null>(null);
  const total = SLIDES.length;

  const goNext = useCallback(() => {
    audioManager.playSFX('nav');
    if (step < total - 1) setStep(s => s + 1);
    else onComplete();
  }, [step, total, onComplete]);

  const goPrev = useCallback(() => {
    audioManager.playSFX('nav');
    if (step > 0) setStep(s => s - 1);
  }, [step]);

  const handleSkip = useCallback(() => {
    audioManager.playSFX('nav');
    onComplete();
  }, [onComplete]);

  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if (e.key === 'ArrowRight' || e.key === 'Enter' || e.key === ' ') { e.preventDefault(); goNext(); }
      if (e.key === 'ArrowLeft') { e.preventDefault(); goPrev(); }
      if (e.key === 'Escape') { e.preventDefault(); handleSkip(); }
    };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, [goNext, goPrev, handleSkip]);

  const slide = SLIDES[step];
  const Icon = slide.icon;

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="fixed inset-0 z-[200] flex items-center justify-center p-4"
      style={{ background: 'rgba(4,4,3,0.95)', backdropFilter: 'blur(12px)' }}
      role="dialog"
      aria-modal="true"
      aria-label="Game briefing"
    >
      {/* Skip */}
      <button
        onClick={handleSkip}
