        style={{ color: '#5a564e' }}
        onMouseEnter={(e) => { e.currentTarget.style.color = '#B87333'; }}
        onMouseLeave={(e) => { e.currentTarget.style.color = '#5a564e'; }}
        aria-label="Skip briefing"
      >
        SKIP <X size={14} />
      </button>

      <div
        className="w-full max-w-2xl"
        onTouchStart={(e) => { touchRef.current = e.touches[0].clientX; }}
        onTouchEnd={(e) => {
          if (touchRef.current === null) return;
          const dx = e.changedTouches[0].clientX - touchRef.current;
          touchRef.current = null;
          if (dx < -50) goNext();
          if (dx > 50) goPrev();
        }}
      >
        <AnimatePresence mode="wait">
          <motion.div
            key={step}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -20 }}
            transition={{ duration: 0.3, ease: 'easeOut' }}
          >
            {/* Image */}
            <div
              className="relative w-full overflow-hidden mb-0"
              style={{
                aspectRatio: '16/9',
                borderTop: `2px solid ${slide.color}40`,
                borderLeft: `2px solid ${slide.color}20`,
                borderRight: `2px solid ${slide.color}20`,
              }}
            >
              <Image
                src={slide.image}
                alt={slide.title}
                fill
                sizes="(max-width: 672px) 100vw, 672px"
                className="object-cover"
                style={{ filter: 'brightness(0.7) saturate(0.85)' }}
                priority={step === 0}
              />
              {/* Gradient overlay bottom */}
              <div className="absolute inset-0" style={{ background: 'linear-gradient(to top, rgba(4,4,3,1) 0%, rgba(4,4,3,0.6) 30%, transparent 60%)' }} />
              {/* Step counter top-left */}
              <div className="absolute top-3 left-3 z-10">
                <span className="font-terminal text-[10px] tracking-[0.3em] px-2 py-1" style={{ color: `${slide.color}90`, background: 'rgba(0,0,0,0.6)', border: `1px solid ${slide.color}25` }}>
                  BRIEFING {step + 1} / {total}
                </span>
              </div>
              {/* Title overlay bottom-left */}
              <div className="absolute bottom-4 left-4 z-10">
                <div className="flex items-center gap-2.5 mb-1">
                  <Icon size={20} style={{ color: slide.color }} />
                  <h2 className="font-terminal text-xl sm:text-2xl tracking-[0.1em] font-bold" style={{ color: slide.color }}>
                    {slide.title}
                  </h2>
                </div>
                <p className="font-typewriter text-xs sm:text-sm text-[#8a8578] ml-[30px]">
                  {slide.tagline}
                </p>
              </div>
            </div>

            {/* Content card */}
            <div
              style={{
                background: 'rgba(10,10,9,0.98)',
                borderBottom: `2px solid ${slide.color}30`,
                borderLeft: `2px solid ${slide.color}15`,
                borderRight: `2px solid ${slide.color}15`,
              }}
            >
              <div className="px-5 py-4 sm:px-6 sm:py-5">
                {/* Bullet points */}
                <ul className="space-y-2 mb-4">
                  {slide.bullets.map((b, i) => (
                    <motion.li
                      key={i}
                      initial={{ opacity: 0, x: 12 }}
                      animate={{ opacity: 1, x: 0 }}
                      transition={{ delay: 0.15 + i * 0.08 }}
                      className="flex items-start gap-2.5 font-typewriter text-[13px] sm:text-sm text-[#c8c4b8] leading-relaxed"
                    >
                      <span className="mt-1.5 w-1.5 h-1.5 rounded-full flex-shrink-0" style={{ background: slide.color, boxShadow: `0 0 6px ${slide.color}50` }} />
                      {b}
                    </motion.li>
                  ))}
                </ul>

                {/* Tip box */}
                <div
                  className="px-3 py-2.5 font-terminal text-[11px] tracking-wider leading-relaxed"
                  style={{
                    color: `${slide.color}90`,
                    background: `${slide.color}08`,
                    borderLeft: `3px solid ${slide.color}50`,
                  }}
                >
                  ▸ {slide.tip}
                </div>
              </div>

              {/* Navigation */}
              <div
                className="flex items-center justify-between px-5 py-3 sm:px-6"
                style={{ borderTop: `1px solid ${slide.color}12` }}
              >
                <button
                  onClick={goPrev}
                  disabled={step === 0}
                  aria-label="Previous"
                  className="flex items-center gap-1.5 font-terminal text-xs tracking-wider min-h-[44px] px-4 py-2 transition-all"
                  style={{
                    color: step === 0 ? '#2a2a20' : '#c8c4b8',
                    border: `1px solid ${step === 0 ? '#1a1a15' : '#5a564e'}`,
                    cursor: step === 0 ? 'not-allowed' : 'pointer',
                  }}
                >
                  <ChevronLeft size={14} /> PREV
                </button>

                {/* Progress dots */}
                <div className="flex gap-2" role="tablist">
                  {SLIDES.map((_, i) => (
                    <button
                      key={i}
                      onClick={() => { audioManager.playSFX('nav'); setStep(i); }}
                      aria-label={`Go to slide ${i + 1}`}
                      aria-selected={i === step}
                      className="transition-all"
                      style={{
                        width: i === step ? '20px' : '8px',
                        height: '8px',
                        borderRadius: '4px',
                        background: i === step ? slide.color : i < step ? `${slide.color}50` : '#2a2a20',
                        boxShadow: i === step ? `0 0 8px ${slide.color}40` : 'none',
                      }}
                    />
                  ))}
                </div>

                <button
                  onClick={goNext}
                  aria-label={step === total - 1 ? 'Start playing' : 'Next'}
                  className="flex items-center gap-1.5 font-terminal text-xs tracking-wider min-h-[44px] px-4 py-2 transition-all hover:scale-[1.02] active:scale-[0.98]"
                  style={{
                    color: step === total - 1 ? '#080808' : slide.color,
                    background: step === total - 1 ? slide.color : 'transparent',
                    border: `1px solid ${slide.color}60`,
                    fontWeight: step === total - 1 ? 700 : 400,
                  }}
                >
                  {step === total - 1 ? 'BEGIN' : 'NEXT'}
                  <ChevronRight size={14} />
                </button>
              </div>
            </div>
          </motion.div>
        </AnimatePresence>
      </div>
    </motion.div>
  );
}

