// ─── Types ────────────────────────────────────────────────
const CONE_DIR = ['up', 'down', 'left', 'right'] as const;
type ConeDir = (typeof CONE_DIR)[number];
interface Pt { x: number; y: number; }
interface Cone { dir: ConeDir; angle_deg: number; range_tiles: number; }
interface MapEnemy { id: string; type: string; patrol: Pt[]; cone: Cone; initial_state: string; }
interface GarbageNode { id: string; x: number; y: number; state: string; }
interface TileOverride { x: number; y: number; state: string; }
interface GameMap {
  meta: { name: string; tile_size: number; width: number; height: number };
  spawn: Pt;
  extraction: Pt & { type: string };
  garbage_nodes: GarbageNode[];
  enemies: MapEnemy[];
  tile_overrides: TileOverride[];
}
interface EncResponse {
  id: string; label: string; approach: string;
  outcome: {
    success: { heat_delta?: number; message?: string };
    fail: { stress?: number; heat_delta?: number; knockout?: boolean };
  };
}
interface Encounter { id: string; tone: string; text: string; anchors: string[]; responses: EncResponse[]; }

interface LiveEnemy { id: string; patrol: Pt[]; patrolIndex: number; pos: Pt; cone: Cone; }
interface GameState {
  heat: number;
  looted: string[];
  player: { x: number; y: number; moveRange: number; remaining: number; stress: number };
  enemies: LiveEnemy[];
  turn: number;
  // ── Sprint 2 ability state ──
  heatMult: number;        // Dave passive (Structural Efficiency)
  mikeyBleed: boolean;     // Mikey passive (Frugal Cuddle) — heat bleeds each turn
  encBonus: number;        // Sid passive (Presence) — encounter success bonus
  mainUsed: boolean;       // operative main ability spent
  directiveUsed: boolean;  // directive card spent
  heatShield: boolean;     // Sid main armed (Heat Deflection)
  scavengerPrimed: boolean;// Mikey main armed (Master Scavenger)
  decoderArmed: boolean;   // Dave main armed (Universal Decoder)
  autoWinArmed: boolean;   // Sid directive armed (Strong-Arm)
  coneBlackout: number;    // Tamara directive (Blind Spot) — turns cones disabled
}

// ─── Operatives (Sprint 2) ──────────────────────────────────
type OperativeId = 'tamara' | 'sid' | 'mikey' | 'dave';
interface Operative {
