const ENEMY_TONE_MAP: Record<string, string> = {
  guard_1: 'enc_rigid_officer',
  guard_2: 'enc_clinical_guard',
  roamer_1: 'enc_hesitant_vendor',
};

const MAX_STRESS = 5;
const MAX_HEAT = 100;
// tone → counter substance: Rigid→Weed, Hesitant→Alcohol, Clinical→Crystals
const TONE_COUNTER: Record<string, string> = { rigid: 'weed', hesitant: 'alcohol', clinical: 'crystals' };

// ─── Pure helpers ────────────────────────────────────
function dirVecOf(dir: ConeDir): Pt {
  switch (dir) {
    case 'up': return { x: 0, y: -1 };
    case 'down': return { x: 0, y: 1 };
    case 'left': return { x: -1, y: 0 };
    case 'right': return { x: 1, y: 0 };
  }
}

function tileInCone(enemy: LiveEnemy, tx: number, ty: number): boolean {
  const dx = tx - enemy.pos.x;
  const dy = ty - enemy.pos.y;
  const dist = Math.hypot(dx, dy);
  if (dist < 0.01) return false;
  if (dist > enemy.cone.range_tiles + 0.01) return false;
  const dv = dirVecOf(enemy.cone.dir);
  const dot = dx * dv.x + dy * dv.y;
  if (dot <= 0) return false;
  const cosAngle = dot / (Math.hypot(dx, dy) * Math.hypot(dv.x, dv.y) + 0.0001);
  const angle = Math.acos(Math.min(1, Math.max(-1, cosAngle))) * (180 / Math.PI);
  return angle <= enemy.cone.angle_deg / 2;
}

function playerSpottedBy(g: GameState): LiveEnemy | null {
  if (g.coneBlackout > 0) return null;
  for (const en of g.enemies) {
    if (tileInCone(en, g.player.x, g.player.y)) return en;
  }
  return null;
}

function clone(g: GameState): GameState {
  return {
    heat: g.heat,
    looted: [...g.looted],
    player: { ...g.player },
    enemies: g.enemies.map((e) => ({ ...e, pos: { ...e.pos }, patrol: e.patrol, cone: e.cone })),
    turn: g.turn,
    heatMult: g.heatMult,
    mikeyBleed: g.mikeyBleed,
    encBonus: g.encBonus,
    mainUsed: g.mainUsed,
    directiveUsed: g.directiveUsed,
    heatShield: g.heatShield,
    scavengerPrimed: g.scavengerPrimed,
    decoderArmed: g.decoderArmed,
    autoWinArmed: g.autoWinArmed,
    coneBlackout: g.coneBlackout,
  };
}

// Apply a heat change respecting Dave's multiplier (gains only) + Sid's shield (gains only).
function gainHeat(ng: GameState, amount: number) {
  if (amount <= 0) { ng.heat = Math.max(0, Math.min(MAX_HEAT, ng.heat + amount)); return; }
  let amt = Math.round(amount * ng.heatMult);
  if (ng.heatShield) { amt = 0; ng.heatShield = false; }
  ng.heat = Math.min(MAX_HEAT, ng.heat + amt);
}

function stepEnemies(g: GameState): GameState {
  const ng = clone(g);
  ng.enemies = ng.enemies.map((en) => {
    const target = en.patrol[en.patrolIndex];
    let { x, y } = en.pos;
    let idx = en.patrolIndex;
    if (x === target.x && y === target.y) {
      // reached waypoint — ping-pong
      idx = en.patrolIndex === 0 ? en.patrol.length - 1 : 0;
    }
    const tgt = en.patrol[idx];
    if (x !== tgt.x) x += tgt.x > x ? 1 : -1;
    else if (y !== tgt.y) y += tgt.y > y ? 1 : -1;
    return { ...en, pos: { x, y }, patrolIndex: idx };
  });
  return ng;
}

const DIR_ARROW: Record<ConeDir, string> = { up: '▲', down: '▼', left: '◀', right: '▶' };

// ═══ Component ═══════════════════════════════════
export default function Sprint1Client() {
  const [map, setMap] = useState<GameMap | null>(null);
  const [encList, setEncList] = useState<Record<string, Encounter>>({});
  const [game, setGame] = useState<GameState | null>(null);
  const [encounter, setEncounter] = useState<{ enc: Encounter; enemyId: string } | null>(null);
  const [message, setMessage] = useState('');
  const [status, setStatus] = useState<'select' | 'loading' | 'playing' | 'won' | 'lost'>('select');
  const [lastResult, setLastResult] = useState<'success' | 'fail' | null>(null);
  const [tile, setTile] = useState(48);
  const [operative, setOperative] = useState<Operative>(OPERATIVES[3]); // default Dave
  const [showHelp, setShowHelp] = useState(false);

  // Auto-show the briefing the first time a player lands here
  useEffect(() => {
    try {
      if (!localStorage.getItem('sprint1_briefed')) {
        setShowHelp(true);
        localStorage.setItem('sprint1_briefed', '1');
      }
    } catch { /* localStorage blocked */ }
  }, []);

  // refs for event handlers (avoid stale closures)
  const mapRef = useRef<GameMap | null>(null);
  const encRef = useRef<Record<string, Encounter>>({});
  const gameRef = useRef<GameState | null>(null);
  const encounterOpenRef = useRef(false);
  const statusRef = useRef<typeof status>('select');
  const pendingEndTurnRef = useRef(false);
  const msgTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => { mapRef.current = map; }, [map]);
  useEffect(() => { encRef.current = encList; }, [encList]);
  useEffect(() => { gameRef.current = game; }, [game]);
  useEffect(() => { encounterOpenRef.current = !!encounter; }, [encounter]);
  useEffect(() => { statusRef.current = status; }, [status]);

  // ─── Responsive tile size ───
  useEffect(() => {
    const recalc = () => {
      const avail = Math.min(window.innerWidth - 24, 720);
      const byW = Math.floor(avail / 10);
      const byH = Math.floor((window.innerHeight - 360) / 8);
      setTile(Math.max(28, Math.min(64, byW, byH > 28 ? byH : byW)));
    };
    recalc();
    window.addEventListener('resize', recalc);
    return () => window.removeEventListener('resize', recalc);
  }, []);

  // ─── Load data + start mission with chosen operative ───
  const startMission = useCallback(async (op: Operative) => {
    setStatus('loading');
    try {
      const [m, e] = await Promise.all([
        fetch('/data/sprint1_map.json').then((r) => r.json()),
        fetch('/data/encounters_sprint1.json').then((r) => r.json()),
      ]);
      const encMap: Record<string, Encounter> = {};
      (e.encounters as Encounter[]).forEach((en) => { encMap[en.id] = en; });
      const g: GameState = {
        heat: 0,
        looted: [],
        player: { x: m.spawn.x, y: m.spawn.y, moveRange: op.moveRange, remaining: op.moveRange, stress: 0 },
        enemies: (m.enemies as MapEnemy[]).map((en) => ({
          id: en.id,
          patrol: en.patrol.slice(),
          patrolIndex: 0,
          pos: { x: en.patrol[0].x, y: en.patrol[0].y },
          cone: en.cone,
        })),
        turn: 1,
        heatMult: op.id === 'dave' ? 0.85 : 1,
        mikeyBleed: op.id === 'mikey',
        encBonus: op.id === 'sid' ? 0.15 : 0,
        mainUsed: false,
        directiveUsed: false,
        heatShield: false,
        scavengerPrimed: false,
        decoderArmed: false,
        autoWinArmed: false,
        coneBlackout: 0,
      };
      setMap(m);
      setEncList(encMap);
      setGame(g);
      gameRef.current = g;
      setEncounter(null);
      setMessage('');
      setLastResult(null);
      setStatus('playing');
      pendingEndTurnRef.current = false;
    } catch {
      setStatus('select');
      setMessage('FAILED TO LOAD MISSION DATA.');
    }
  }, []);

  const flash = useCallback((msg: string) => {
    setMessage(msg);
    if (msgTimer.current) clearTimeout(msgTimer.current);
    msgTimer.current = setTimeout(() => setMessage(''), 3200);
  }, []);

  // ─── Turn resolution ───
  const runEnemyTurn = useCallback((from: GameState) => {
    const ng = stepEnemies(from);
    ng.player = { ...ng.player, remaining: ng.player.moveRange };
    ng.turn = from.turn + 1;
    // Mikey passive: heat bleed at the start of each new turn
    if (ng.mikeyBleed && ng.heat > 0) ng.heat = Math.max(0, ng.heat - 1);
    // Tamara directive: decrement cone blackout
    if (ng.coneBlackout > 0) ng.coneBlackout -= 1;
    setGame(ng);
    gameRef.current = ng;
    // re-check: enemy may have walked into seeing the player
    const spotter = playerSpottedBy(ng);
    if (spotter) {
      const encId = ENEMY_TONE_MAP[spotter.id] || 'enc_hesitant_vendor';
      const enc = encRef.current[encId];
      if (enc) { setEncounter({ enc, enemyId: spotter.id }); }
    }
  }, []);

  // ─── Movement ───
  const attemptMove = useCallback((dx: number, dy: number) => {
    if (statusRef.current !== 'playing' || encounterOpenRef.current) return;
    const m = mapRef.current;
    const g = gameRef.current;
    if (!m || !g) return;
    if (g.player.remaining <= 0) { flash('NO MOVES LEFT — END TURN.'); return; }
    const nx = g.player.x + dx;
    const ny = g.player.y + dy;
    if (nx < 0 || ny < 0 || nx >= m.meta.width || ny >= m.meta.height) return;
    if (m.tile_overrides.some((t) => t.x === nx && t.y === ny && t.state === 'blocked')) return;
    if (g.enemies.some((en) => en.pos.x === nx && en.pos.y === ny)) return;

    const ng = clone(g);
    ng.player.x = nx;
    ng.player.y = ny;
    ng.player.remaining -= 1;

    // extraction = win
    if (nx === m.extraction.x && ny === m.extraction.y) {
      setGame(ng);
      gameRef.current = ng;
      setStatus('won');
      return;
    }

    // loot node
    const node = m.garbage_nodes.find((n) => n.x === nx && n.y === ny && !ng.looted.includes(n.id));
    if (node) {
      ng.looted.push(node.id);
      if (ng.scavengerPrimed) {
        ng.scavengerPrimed = false; // Mikey: clean grab — no heat, keep moving
        flash(`MASTER SCAVENGER — ${node.id.toUpperCase()} CLEAN GRAB`);
      } else {
        gainHeat(ng, 5);
        ng.player.remaining = 0;
        flash(`SALVAGED ${node.id.toUpperCase()} — HEAT +5`);
      }
    }

    setGame(ng);
    gameRef.current = ng;

    // spotted on entering a cone?
    const spotter = playerSpottedBy(ng);
    if (spotter) {
      const encId = ENEMY_TONE_MAP[spotter.id] || 'enc_hesitant_vendor';
      const enc = encRef.current[encId];
      if (enc) {
        pendingEndTurnRef.current = ng.player.remaining === 0;
        setEncounter({ enc, enemyId: spotter.id });
        return;
      }
    }

    if (ng.player.remaining === 0) runEnemyTurn(ng);
  }, [flash, runEnemyTurn]);

  const endTurn = useCallback(() => {
    if (statusRef.current !== 'playing' || encounterOpenRef.current) return;
    const g = gameRef.current;
    if (!g) return;
    runEnemyTurn(g);
  }, [runEnemyTurn]);

  // ─── Main ability (1 use) ───
  const useMainAbility = useCallback(() => {
    if (statusRef.current !== 'playing' || encounterOpenRef.current) return;
    const g = gameRef.current;
    const m = mapRef.current;
    if (!g || !m || g.mainUsed) return;
    const ng = clone(g);
    ng.mainUsed = true;
    switch (operative.id) {
      case 'tamara': {
        // Dumpster Detection: remote-salvage nearest unlooted node
        const remaining = m.garbage_nodes.filter((n) => !ng.looted.includes(n.id));
        if (remaining.length === 0) { flash('NO NODES LEFT TO DETECT.'); return; }
        let best = remaining[0];
        let bestD = Infinity;
        for (const n of remaining) {
          const d = Math.abs(n.x - ng.player.x) + Math.abs(n.y - ng.player.y);
          if (d < bestD) { bestD = d; best = n; }
        }
        ng.looted.push(best.id);
        gainHeat(ng, 5);
        flash(`DUMPSTER DETECTION — ${best.id.toUpperCase()} PULLED REMOTELY`);
        break;
      }
      case 'sid':
        ng.heatShield = true;
        flash('HEAT DEFLECTION ARMED — NEXT SPIKE ABSORBED');
        break;
      case 'mikey':
        ng.scavengerPrimed = true;
        flash('MASTER SCAVENGER PRIMED — NEXT GRAB IS FREE');
        break;
      case 'dave':
        ng.decoderArmed = true;
        flash('UNIVERSAL DECODER ARMED — NEXT TONE REVEALED');
        break;
    }
    setGame(ng);
    gameRef.current = ng;
  }, [operative, flash]);

  // ─── Directive card (1 use) ───
  const playDirective = useCallback(() => {
    if (statusRef.current !== 'playing' || encounterOpenRef.current) return;
    const g = gameRef.current;
    if (!g || g.directiveUsed) return;
    const ng = clone(g);
    ng.directiveUsed = true;
    switch (operative.id) {
      case 'tamara':
        ng.coneBlackout = 2; // covers this turn + the next enemy step
        flash('BLIND SPOT — VISION CONES DOWN');
        break;
      case 'sid':
        ng.autoWinArmed = true;
        flash('STRONG-ARM READY — NEXT CONTACT FOLDS');
        break;
      case 'mikey':
        ng.player.remaining += 3;
        flash('OLD ROUTES — +3 MOVES');
        break;
      case 'dave':
        gainHeat(ng, -25);
        flash('COLD READ — HEAT −25');
        break;
    }
    setGame(ng);
    gameRef.current = ng;
  }, [operative, flash]);

  // ─── Encounter resolution ───
  const resolveEncounter = useCallback((respIndex: number) => {
    const cur = encounter;
    const g = gameRef.current;
    if (!cur || !g) return;
    const resp = cur.enc.responses[respIndex];
    const tone = cur.enc.tone.toLowerCase();
    const approachTag = resp.approach.split('/')[0].trim().toLowerCase();
    const approachMatches = approachTag === tone
      || (tone === 'rigid' && approachTag === 'weed')
      || (tone === 'hesitant' && approachTag === 'alcohol')
      || (tone === 'clinical' && approachTag === 'crystals');
    const isCounter = approachTag === TONE_COUNTER[tone];
    let successChance = (isCounter ? 0.78 : approachMatches ? 0.55 : 0.35) + g.encBonus;
    successChance = Math.min(0.97, successChance);
    // Sid directive: auto-succeed
    const forced = g.autoWinArmed;
    const success = forced || Math.random() < successChance;

    const ng = clone(g);
    ng.autoWinArmed = false;
    ng.decoderArmed = false; // consume reveal when an encounter resolves
    let lost = false;
    if (success) {
      gainHeat(ng, resp.outcome.success.heat_delta || 0);
      flash(forced ? 'STRONG-ARM — THEY BACK DOWN' : (resp.outcome.success.message || 'Success.'));
      setLastResult('success');
    } else {
      ng.player.stress += resp.outcome.fail.stress || 1;
      gainHeat(ng, resp.outcome.fail.heat_delta || 10);
      setLastResult('fail');
      if (resp.outcome.fail.knockout || ng.player.stress >= MAX_STRESS) {
        flash(resp.outcome.fail.knockout ? 'KNOCKED OUT. EXTRACTION FAILED.' : 'STRESS OVERLOAD. CREW DOWN.');
        lost = true;
      } else {
        flash('Encounter failed.');
      }
    }
    if (ng.heat >= MAX_HEAT) lost = true;

    setGame(ng);
    gameRef.current = ng;
    setEncounter(null);
    encounterOpenRef.current = false;

    if (lost) { setStatus('lost'); return; }

    if (pendingEndTurnRef.current) {
      pendingEndTurnRef.current = false;
      runEnemyTurn(ng);
    }
  }, [encounter, flash, runEnemyTurn]);

  // ─── Keyboard ───
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (statusRef.current !== 'playing') return;
      const k = e.key.toLowerCase();
      if (['arrowup', 'w'].includes(k)) { e.preventDefault(); attemptMove(0, -1); }
      else if (['arrowdown', 's'].includes(k)) { e.preventDefault(); attemptMove(0, 1); }
      else if (['arrowleft', 'a'].includes(k)) { e.preventDefault(); attemptMove(-1, 0); }
      else if (['arrowright', 'd'].includes(k)) { e.preventDefault(); attemptMove(1, 0); }
      else if (k === ' ' || k === 'enter') { e.preventDefault(); endTurn(); }
      else if (k === 'q') { e.preventDefault(); useMainAbility(); }
      else if (k === 'e') { e.preventDefault(); playDirective(); }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [attemptMove, endTurn, useMainAbility, playDirective]);

  // ─── Cone tiles (for tint) ───
  const coneTiles = useMemo(() => {
    const set = new Set<string>();
    if (!map || !game || game.coneBlackout > 0) return set;
    for (const en of game.enemies) {
      for (let y = 0; y < map.meta.height; y++) {
        for (let x = 0; x < map.meta.width; x++) {
          if (tileInCone(en, x, y)) set.add(`${x},${y}`);
        }
      }
    }
    return set;
  }, [map, game]);

  // ─── Tap-to-move (orthogonal adjacent) ───
  const onTileTap = useCallback((x: number, y: number) => {
    const g = gameRef.current;
    if (!g) return;
    const dx = x - g.player.x;
    const dy = y - g.player.y;
    if (Math.abs(dx) + Math.abs(dy) !== 1) return; // only adjacent
    attemptMove(dx, dy);
  }, [attemptMove]);

  // ═══ Render ═══════════════════════════════════════
  const GREEN = '#86f0a8';
  const DIM = '#3f6e52';
  const heat = game?.heat ?? 0;
  const hot = heat >= 70;
  const opColor = operative.color;

  // decoder: which response is the correct counter?
  const decoderIndex = useMemo(() => {
    if (!encounter || !game?.decoderArmed) return -1;
    const tone = encounter.enc.tone.toLowerCase();
    return encounter.enc.responses.findIndex(
      (r) => r.approach.split('/')[0].trim().toLowerCase() === TONE_COUNTER[tone],
    );
  }, [encounter, game?.decoderArmed]);

  return (
    <div
      className="min-h-[100dvh] w-full flex flex-col items-center font-bmf-mono select-none"
      style={{ background: '#060a07', color: GREEN }}
    >
      {/* scanline overlay */}
      <div
        aria-hidden
        className="pointer-events-none fixed inset-0 z-50"
        style={{
          background: 'repeating-linear-gradient(0deg, rgba(0,0,0,0.18) 0px, rgba(0,0,0,0.18) 1px, transparent 2px, transparent 4px)',
          mixBlendMode: 'multiply',
        }}
      />
      {/* vignette */}
      <div aria-hidden className="pointer-events-none fixed inset-0 z-40" style={{ boxShadow: 'inset 0 0 160px rgba(0,0,0,0.85)' }} />

      {/* header */}
      <header className="w-full max-w-3xl px-4 pt-4 pb-2 z-10">
        <div className="flex items-center justify-between" style={{ borderBottom: `1px solid ${DIM}` }}>
          <h1 className="text-sm tracking-[0.3em]" style={{ textShadow: `0 0 8px ${GREEN}80` }}>BMF:3K // SPRINT_2</h1>
          <span className="text-[10px]" style={{ color: DIM }}>EXTRACTION PROTOCOL</span>
        </div>
      </header>

      {/* ═══ CREW SELECT ═══ */}
      {status === 'select' && (
        <div className="w-full max-w-3xl px-4 z-10 pb-10">
          <div className="text-center my-4">
            <div className="text-xs tracking-[0.3em]" style={{ color: GREEN }}>SELECT OPERATIVE</div>
            <div className="text-[10px] mt-1" style={{ color: DIM }}>One body goes in. Choose who.</div>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            {OPERATIVES.map((op) => {
              const sel = operative.id === op.id;
              return (
                <button
                  key={op.id}
                  onClick={() => setOperative(op)}
                  className="text-left p-3 transition-all active:scale-[0.99]"
                  style={{
                    border: `1px solid ${sel ? op.color : DIM}`,
                    background: sel ? `${op.color}10` : 'rgba(134,240,168,0.02)',
                    boxShadow: sel ? `0 0 18px ${op.color}33` : undefined,
                  }}
                >
                  <div className="flex items-center justify-between">
                    <span className="text-sm tracking-widest" style={{ color: op.color, textShadow: `0 0 8px ${op.color}66` }}>
                      {op.glyph} {op.name}
                    </span>
                    <span className="text-[9px]" style={{ color: DIM }}>{op.role}</span>
                  </div>
                  <div className="text-[10px] mt-1 italic" style={{ color: DIM }}>{op.blurb}</div>
                  <div className="mt-2 space-y-1 text-[10px]">
                    <div><span style={{ color: GREEN }}>PASSIVE</span> <span style={{ color: DIM }}>· {op.passive.name}</span><div style={{ color: DIM }}>{op.passive.desc}</div></div>
                    <div><span style={{ color: op.color }}>MAIN</span> <span style={{ color: DIM }}>· {op.main.name}</span><div style={{ color: DIM }}>{op.main.desc}</div></div>
                    <div><span style={{ color: '#d4a060' }}>DIRECTIVE</span> <span style={{ color: DIM }}>· {op.directive.name}</span><div style={{ color: DIM }}>{op.directive.desc}</div></div>
                  </div>
                </button>
              );
            })}
          </div>
          {message && <div className="text-center text-[11px] mt-3" style={{ color: '#cc5550' }}>{message}</div>}
          <div className="text-center mt-5">
            <button
              onClick={() => startMission(operative)}
              className="px-8 py-3 text-xs tracking-[0.3em] active:scale-95"
              style={{ border: `1px solid ${opColor}`, color: opColor, background: `${opColor}10`, boxShadow: `0 0 20px ${opColor}33` }}
            >
              DEPLOY {operative.name} ▶
            </button>
            <div className="mt-3">
              <button
                onClick={() => setShowHelp(true)}
                className="px-5 py-2 text-[10px] tracking-[0.25em] active:scale-95"
                style={{ border: `1px solid ${DIM}`, color: DIM }}
              >
                ◆ HOW TO PLAY
              </button>
            </div>
          </div>
        </div>
      )}

      {/* ═══ HOW TO PLAY BRIEFING ═══ */}
      {showHelp && (
        <div
          className="fixed inset-0 z-[70] flex items-center justify-center p-4"
          style={{ background: 'rgba(2,6,3,0.92)' }}
          onClick={() => setShowHelp(false)}
        >
          <div
            className="w-full max-w-md p-5 overflow-y-auto"
            style={{ maxHeight: '88vh', border: `1px solid ${GREEN}`, background: '#070d09', boxShadow: `0 0 30px ${GREEN}33` }}
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex items-center justify-between mb-3" style={{ borderBottom: `1px solid ${DIM}` }}>
              <h2 className="text-xs tracking-[0.3em] pb-2" style={{ color: GREEN, textShadow: `0 0 8px ${GREEN}80` }}>MISSION BRIEFING</h2>
              <span className="text-[9px] pb-2" style={{ color: DIM }}>EYES ONLY</span>
            </div>
            <div className="space-y-3 text-[11px] leading-relaxed" style={{ color: '#bfe8cd' }}>
              <div>
                <div className="tracking-[0.2em] mb-1" style={{ color: GREEN }}>◆ THE JOB</div>
                <p style={{ color: DIM }}>Slip one operative through the lot, grab the salvage, reach the <span style={{ color: GREEN }}>extraction tile ⊕</span> in the corner. Don&apos;t get pinged. Don&apos;t cook the heat.</p>
              </div>
              <div>
                <div className="tracking-[0.2em] mb-1" style={{ color: GREEN }}>◆ MOVING</div>
                <p style={{ color: DIM }}>You get a set number of moves per turn (shown as MOVES). Tap an adjacent tile, or use <span style={{ color: GREEN }}>WASD / arrow keys</span>, or the on-screen D-pad. When you&apos;re out of moves, <span style={{ color: GREEN }}>END TURN</span> (Space/Enter).</p>
              </div>
              <div>
                <div className="tracking-[0.2em] mb-1" style={{ color: GREEN }}>◆ THE ENEMIES</div>
                <p style={{ color: DIM }}>Red <span style={{ color: '#cc5550' }}>vision cones</span> are bad news. Step into one — or let a guard&apos;s cone swing onto you — and you trigger a <span style={{ color: GREEN }}>contact encounter</span>. After each of your turns the guards shuffle and their cones swing around, so plan ahead.</p>
              </div>
              <div>
                <div className="tracking-[0.2em] mb-1" style={{ color: GREEN }}>◆ ENCOUNTERS</div>
                <p style={{ color: DIM }}>Pick the response that counters their tone: <span style={{ color: GREEN }}>RIGID → weed</span>, <span style={{ color: GREEN }}>HESITANT → booze</span>, <span style={{ color: GREEN }}>CLINICAL → crystals</span>. Right answer and you slip past and shed heat. Wrong answer spikes it.</p>
              </div>
              <div>
                <div className="tracking-[0.2em] mb-1" style={{ color: GREEN }}>◆ SALVAGE & HEAT</div>
                <p style={{ color: DIM }}>Walk onto a salvage node <span style={{ color: GREEN }}>▣</span> to loot it (+5 heat each). Heat over 100 = mission blown. So does getting knocked out or maxing stress.</p>
              </div>
              <div>
                <div className="tracking-[0.2em] mb-1" style={{ color: GREEN }}>◆ YOUR KIT</div>
                <p style={{ color: DIM }}>Each operative has an always-on passive, plus two one-shot powers: <span style={{ color: GREEN }}>[Q]</span> main ability and <span style={{ color: GREEN }}>[E]</span> directive card. Use them when it counts — you only get one of each.</p>
              </div>
            </div>
            <button
              onClick={() => setShowHelp(false)}
              className="w-full mt-4 py-3 text-xs tracking-[0.3em] active:scale-95"
              style={{ border: `1px solid ${GREEN}`, color: GREEN, background: `${GREEN}10` }}
            >
              GOT IT ▶
            </button>
          </div>
        </div>
      )}

      {/* ═══ MISSION HUD + GRID ═══ */}
      {status !== 'select' && (
        <>
          {/* HUD */}
          <div className="w-full max-w-3xl px-4 grid grid-cols-3 gap-2 text-[10px] z-10">
            <div className="p-2" style={{ border: `1px solid ${DIM}` }}>
              <div style={{ color: DIM }}>HEAT</div>
              <div className="mt-1 h-2 w-full" style={{ background: '#0c140d', border: `1px solid ${DIM}` }}>
                <div
                  className={hot ? 'animate-pulse' : ''}
                  style={{
                    width: `${heat}%`, height: '100%',
                    background: hot ? '#cc5550' : heat >= 40 ? '#d4a060' : GREEN,
                    transition: 'width 0.3s',
                  }}
                />
              </div>
              <div id="heat-label" className="mt-1" style={{ color: hot ? '#cc5550' : GREEN }}>{heat} / 100</div>
            </div>
            <div className="p-2" style={{ border: `1px solid ${DIM}` }}>
              <div style={{ color: DIM }}>MOVES</div>
              <div className="mt-1 text-base">{game?.player.remaining ?? 0}<span style={{ color: DIM }}>/{game?.player.moveRange ?? 3}</span></div>
              <div style={{ color: DIM }}>TURN {game?.turn ?? 1}</div>
            </div>
            <div className="p-2" style={{ border: `1px solid ${DIM}` }}>
              <div style={{ color: DIM }}>STRESS</div>
              <div className="mt-1 flex gap-1">
                {Array.from({ length: MAX_STRESS }).map((_, i) => (
                  <span key={i} style={{ color: (game?.player.stress ?? 0) > i ? '#cc5550' : DIM }}>◆</span>
                ))}
              </div>
              <div id="player-status" style={{ color: DIM }}>
                LOOT {game?.looted.length ?? 0}/{map?.garbage_nodes.length ?? 0}
              </div>
            </div>
          </div>

          {/* operative + ability bar */}
          <div className="w-full max-w-3xl px-4 mt-2 z-10 flex items-stretch gap-2 text-[10px]">
            <div className="px-2 py-2 flex flex-col justify-center" style={{ border: `1px solid ${opColor}55`, minWidth: 96 }}>
              <span style={{ color: opColor }}>{operative.glyph} {operative.name}</span>
              <span style={{ color: DIM }}>{operative.role}</span>
            </div>
            <button
              onClick={useMainAbility}
              disabled={!!game?.mainUsed}
              className="flex-1 px-2 py-2 text-left active:scale-[0.98] transition-transform"
              style={{
                border: `1px solid ${game?.mainUsed ? DIM : opColor}`,
                color: game?.mainUsed ? DIM : opColor,
                background: game?.mainUsed ? 'transparent' : `${opColor}0d`,
                opacity: game?.mainUsed ? 0.5 : 1,
              }}
            >
              <div className="flex items-center justify-between">
                <span>[Q] {operative.main.name}</span>
                <span style={{ color: DIM }}>{game?.mainUsed ? 'SPENT' : abilityArmedLabel(operative.id, game)}</span>
              </div>
              <div className="text-[9px]" style={{ color: DIM }}>{operative.main.desc}</div>
            </button>
            <button
              onClick={playDirective}
              disabled={!!game?.directiveUsed}
              className="flex-1 px-2 py-2 text-left active:scale-[0.98] transition-transform"
              style={{
                border: `1px solid ${game?.directiveUsed ? DIM : '#d4a060'}`,
                color: game?.directiveUsed ? DIM : '#d4a060',
                background: game?.directiveUsed ? 'transparent' : 'rgba(212,160,96,0.06)',
                opacity: game?.directiveUsed ? 0.5 : 1,
              }}
            >
              <div className="flex items-center justify-between">
                <span>[E] {operative.directive.name}</span>
                <span style={{ color: DIM }}>{game?.directiveUsed ? 'SPENT' : directiveArmedLabel(operative.id, game)}</span>
              </div>
              <div className="text-[9px]" style={{ color: DIM }}>DIRECTIVE · {operative.directive.desc}</div>
            </button>
          </div>

          {/* message box */}
          <div id="message-box" className="w-full max-w-3xl px-4 h-6 mt-2 text-[11px] z-10 flex items-center"
            style={{ color: lastResult === 'fail' ? '#cc5550' : GREEN }}>
            {message}
          </div>

          {/* grid */}
          <div className="relative z-10 mt-1" style={{ filter: hot ? 'saturate(1.2)' : undefined }}>
            {map && game && (
              <div
                className="relative"
                style={{
                  width: tile * map.meta.width,
                  height: tile * map.meta.height,
                  border: `2px solid ${DIM}`,
                  boxShadow: `0 0 24px ${hot ? 'rgba(204,85,80,0.4)' : 'rgba(134,240,168,0.15)'}`,
                }}
              >
                {game.coneBlackout > 0 && (
                  <div className="absolute top-1 left-1 z-20 text-[9px] px-1 animate-pulse" style={{ color: '#7ab8b8', background: '#060a07cc' }}>BLIND SPOT ACTIVE</div>
                )}
                {Array.from({ length: map.meta.height }).map((_, y) =>
                  Array.from({ length: map.meta.width }).map((__, x) => {
                    const key = `${x},${y}`;
                    const blocked = map.tile_overrides.some((t) => t.x === x && t.y === y && t.state === 'blocked');
                    const inCone = coneTiles.has(key);
                    const node = map.garbage_nodes.find((n) => n.x === x && n.y === y);
                    const looted = node ? game.looted.includes(node.id) : false;
                    const isExtraction = map.extraction.x === x && map.extraction.y === y;
                    const enemy = game.enemies.find((e) => e.pos.x === x && e.pos.y === y);
                    const isPlayer = game.player.x === x && game.player.y === y;
                    const adjacent = Math.abs(x - game.player.x) + Math.abs(y - game.player.y) === 1 && !blocked && !enemy;
                    return (
                      <button
                        key={key}
                        onClick={() => onTileTap(x, y)}
                        aria-label={`tile ${x},${y}`}
                        className="absolute flex items-center justify-center"
                        style={{
                          left: x * tile, top: y * tile, width: tile, height: tile,
                          borderRight: `1px solid ${DIM}22`,
                          borderBottom: `1px solid ${DIM}22`,
                          background: blocked
                            ? 'repeating-linear-gradient(45deg,#10160f,#10160f 4px,#0a0e0a 4px,#0a0e0a 8px)'
                            : inCone ? 'rgba(204,85,80,0.18)' : 'transparent',
                          boxShadow: adjacent ? `inset 0 0 0 1px ${GREEN}55` : undefined,
                          cursor: adjacent ? 'pointer' : 'default',
                          fontSize: tile * 0.5,
                          lineHeight: 1,
                        }}
                      >
                        {isExtraction && !isPlayer && (
                          <span style={{ color: '#d4a060', fontSize: tile * 0.55, textShadow: '0 0 8px #d4a06088' }}>⊕</span>
                        )}
                        {node && !looted && !isPlayer && (
                          <span style={{ color: GREEN, fontSize: tile * 0.5, textShadow: `0 0 6px ${GREEN}88` }}>▣</span>
                        )}
                        {node && looted && !isPlayer && (
                          <span style={{ color: DIM, fontSize: tile * 0.45 }}>□</span>
                        )}
                        {enemy && (
                          <span style={{ color: '#cc5550', fontSize: tile * 0.55, textShadow: '0 0 8px #cc555088' }}>
                            {DIR_ARROW[enemy.cone.dir]}
                          </span>
                        )}
                        {isPlayer && (
                          <span style={{ color: opColor, fontSize: tile * 0.62, textShadow: `0 0 10px ${opColor}` }}>{operative.glyph}</span>
                        )}
                      </button>
                    );
                  })
                )}
              </div>
            )}
            {status === 'loading' && (
              <div className="p-10 text-center text-sm" style={{ color: DIM }}>LOADING MISSION DATA...</div>
            )}
          </div>

          {/* D-pad + end turn (mobile touch) */}
          {status === 'playing' && (
            <div className="z-10 mt-4 mb-4 flex items-center gap-6">
              <div className="grid grid-cols-3 gap-1" style={{ width: 150 }}>
                <span />
                <DPad label="▲" onClick={() => attemptMove(0, -1)} />
                <span />
                <DPad label="◀" onClick={() => attemptMove(-1, 0)} />
                <DPad label="▾" onClick={() => attemptMove(0, 1)} />
                <DPad label="▶" onClick={() => attemptMove(1, 0)} />
              </div>
              <button
                onClick={endTurn}
                className="px-4 py-3 text-xs tracking-widest active:scale-95"
                style={{ border: `1px solid ${GREEN}`, color: GREEN, background: 'rgba(134,240,168,0.06)' }}
              >
                END TURN
              </button>
            </div>
          )}

          {/* legend */}
          <div className="z-10 pb-8 text-[9px] flex flex-wrap gap-x-4 gap-y-1 justify-center px-4" style={{ color: DIM }}>
            <span style={{ color: opColor }}>{operative.glyph} YOU</span>
            <span style={{ color: '#cc5550' }}>▶ GUARD (vision)</span>
            <span style={{ color: GREEN }}>▣ SALVAGE</span>
            <span style={{ color: '#d4a060' }}>⊕ EXTRACTION</span>
            <span>WASD / TAP · SPACE=WAIT · Q=ABILITY · E=DIRECTIVE</span>
          </div>
        </>
      )}

      {/* encounter modal */}
      {encounter && game && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4" style={{ background: 'rgba(2,5,3,0.9)' }}>
          <div className="w-full max-w-md p-4" style={{ border: `1px solid ${GREEN}`, background: '#070d09', boxShadow: `0 0 30px ${GREEN}33` }}>
            <div className="flex items-center justify-between text-[10px] mb-2" style={{ color: DIM }}>
              <span>&gt; CONTACT // {encounter.enc.tone.toUpperCase()} TONE</span>
              <span className="animate-pulse" style={{ color: '#cc5550' }}>● REC</span>
            </div>
            <p className="enc-text text-xs leading-relaxed mb-2" style={{ color: GREEN }}>“{encounter.enc.text}”</p>
            <p className="enc-anchors text-[10px] mb-3" style={{ color: '#d4a060' }}>
              ANCHORS: {encounter.enc.anchors.join(' · ')}
            </p>
            {game.autoWinArmed && (
              <div className="text-[9px] mb-2 px-2 py-1" style={{ color: '#cc5550', border: '1px solid #cc555055' }}>STRONG-ARM ENGAGED — ANY CHOICE FOLDS THEM</div>
            )}
            <div className="enc-options flex flex-col gap-2">
              {encounter.enc.responses.map((r, i) => {
                const reveal = decoderIndex === i;
                return (
                  <button
                    key={r.id}
                    onClick={() => resolveEncounter(i)}
                    className="text-left px-3 py-2 text-[11px] active:scale-[0.98] transition-transform"
                    style={{
                      border: `1px solid ${reveal ? GREEN : DIM}`,
                      color: GREEN,
                      background: reveal ? 'rgba(134,240,168,0.14)' : 'rgba(134,240,168,0.04)',
                      boxShadow: reveal ? `0 0 12px ${GREEN}55` : undefined,
                    }}
                  >
                    <div>{r.label}{reveal && <span className="ml-2" style={{ color: GREEN }}>◀ DECODED</span>}</div>
                    <div className="text-[9px] mt-0.5" style={{ color: DIM }}>{r.approach.toUpperCase()}</div>
                  </button>
                );
              })}
            </div>
            <div className="text-[9px] mt-3" style={{ color: DIM }}>
              MATCH THE TONE: Rigid→Weed · Hesitant→Alcohol · Clinical→Crystals
            </div>
          </div>
        </div>
      )}

      {/* win / lose overlay */}
      {(status === 'won' || status === 'lost') && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center p-4" style={{ background: 'rgba(2,5,3,0.94)' }}>
          <div className="text-center p-6" style={{ border: `1px solid ${status === 'won' ? GREEN : '#cc5550'}`, background: '#070d09' }}>
            <h2 className="text-lg tracking-[0.3em] mb-2" style={{ color: status === 'won' ? GREEN : '#cc5550', textShadow: `0 0 12px ${status === 'won' ? GREEN : '#cc5550'}` }}>
              {status === 'won' ? 'EXTRACTION COMPLETE' : 'MISSION FAILED'}
            </h2>
            <p className="text-[11px] mb-1" style={{ color: DIM }}>
              {operative.name} · SALVAGE {game?.looted.length ?? 0}/{map?.garbage_nodes.length ?? 0} · HEAT {game?.heat ?? 0} · TURN {game?.turn ?? 1}
            </p>
            <p className="text-[10px] mb-4 max-w-xs" style={{ color: DIM }}>
              {status === 'won'
                ? `${operative.name} made the extraction point. Swap operatives and run it cleaner.`
                : 'Heat spiked or the crew broke. Pick a different operative and try a quieter route.'}
            </p>
            <div className="flex gap-2 justify-center">
              <button
                onClick={() => startMission(operative)}
                className="px-5 py-2 text-xs tracking-widest active:scale-95"
                style={{ border: `1px solid ${GREEN}`, color: GREEN, background: 'rgba(134,240,168,0.06)' }}
              >
                RUN AGAIN
              </button>
              <button
                onClick={() => { setStatus('select'); setMessage(''); }}
                className="px-5 py-2 text-xs tracking-widest active:scale-95"
                style={{ border: `1px solid ${DIM}`, color: DIM, background: 'transparent' }}
              >
                SWAP CREW
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// armed-state labels for the ability buttons
function abilityArmedLabel(id: OperativeId, g: GameState | null): string {
  if (!g) return 'READY';
  if (id === 'sid' && g.heatShield) return 'ARMED';
  if (id === 'mikey' && g.scavengerPrimed) return 'PRIMED';
  if (id === 'dave' && g.decoderArmed) return 'ARMED';
  return 'READY';
}
function directiveArmedLabel(id: OperativeId, g: GameState | null): string {
  if (!g) return 'READY';
  if (id === 'tamara' && g.coneBlackout > 0) return 'ACTIVE';
  if (id === 'sid' && g.autoWinArmed) return 'ARMED';
  return 'READY';
}

function DPad({ label, onClick }: { label: string; onClick: () => void }) {
  return (
    <button
      onClick={onClick}
      className="flex items-center justify-center py-3 text-sm active:scale-90 transition-transform"
      style={{ border: '1px solid #3f6e52', color: '#86f0a8', background: 'rgba(134,240,168,0.05)' }}
    >
      {label}
    </button>
  );
}

