                      className="relative font-terminal text-sm sm:text-base tracking-[0.2em] py-3 px-6 sm:px-8 rounded-md cursor-pointer transition-all duration-200 active:scale-[0.97] focus:outline-none focus-visible:ring-2 focus-visible:ring-[#b87a96]/60 overflow-hidden group"
