                        backgroundColor: hoveredBtn === btn.id
                          ? (btn.primary ? 'var(--pop)' : 'rgba(216,199,163,0.12)')
                          : 'transparent',
                        border: `1px solid ${hoveredBtn === btn.id
                          ? (btn.primary ? 'transparent' : 'rgba(216,199,163,0.5)')
                          : btn.primary ? 'rgba(var(--pop-rgb),0.5)' : 'rgba(216,199,163,0.25)'}`,
                        boxShadow: hoveredBtn === btn.id && btn.primary
                          ? '0 0 24px rgba(var(--pop-rgb),0.5)'
                          : 'none',
                      }}
                    >
                      <span className="absolute inset-0 bg-gradient-to-r from-transparent via-white/[0.06] to-transparent translate-x-[-100%] group-hover:translate-x-[100%] transition-transform duration-700" />
                      <span className="relative z-10">
                        <span className="text-[#b9aa8a]/60 mr-2 text-xs">[{btn.hotkey}]</span>
                        {btn.label}
                      </span>
                    </motion.button>
                  ))}
                </motion.div>
              )}
            </motion.div>
          </motion.article>

          {/* ── STACK PANEL ── */}
          <motion.aside
            initial={{ opacity: 0, y: 16 }}
            animate={{ opacity: showContent ? 1 : 0, y: showContent ? 0 : 16 }}
            transition={{ duration: 0.8, delay: 0.4 }}
            className="hidden lg:grid gap-4 content-start"
          >
            {/* Lore teaser card */}
            <div className="p-5 rounded-xl border border-[rgba(216,199,163,0.18)] bg-[rgba(33,30,25,0.88)]" style={{ boxShadow: '0 24px 80px rgba(0,0,0,0.45)' }}>
              <p className="font-terminal text-[10px] tracking-[0.35em] text-[#b87a96]/60 mb-2 uppercase">
                SUPPLY HUB · YEAR 3000
              </p>
              <h4 className="font-terminal text-base sm:text-lg tracking-[0.06em] text-[#f3e8cf] mb-3">
                The Selection
              </h4>
              <p className="font-terminal text-[11px] sm:text-xs leading-relaxed text-[#b9aa8a]">
