              </p>
            </div>

            {/* Save ritual card */}
            <div className="p-5 rounded-xl border border-[rgba(216,199,163,0.18)] bg-[rgba(33,30,25,0.88)] grid grid-cols-[3.5rem_1fr] gap-4 items-center" style={{ boxShadow: '0 24px 80px rgba(0,0,0,0.45)' }}>
