              <div
                className="h-12 rounded-sm border-2 border-[#d8c7a3]/40 relative"
                style={{
                  background:
                    'radial-gradient(circle at 32% 68%, transparent 0 5px, #d8c7a3 5.5px 7px, transparent 7.5px), radial-gradient(circle at 68% 68%, transparent 0 5px, #d8c7a3 5.5px 7px, transparent 7.5px)',
                }}
              />
              <div>
                <p className="font-terminal text-[10px] tracking-[0.35em] text-[#ffb25f]/60 mb-1 uppercase">
