// Web Audio Synth Engine
class AudioEngine {
  constructor() {
    this.ctx = null;
    this.heartbeatInterval = null;
    this.droneOsc = null;
    this.droneGain = null;
  }

  init() {
    if (!this.ctx) {
      const AudioContext = window.AudioContext || window.webkitAudioContext;
      this.ctx = new AudioContext();
    }
    if (this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
  }

  playClick() {
    if (!this.ctx) return;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.frequency.setValueAtTime(800, this.ctx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(100, this.ctx.currentTime + 0.08);
    gain.gain.setValueAtTime(0.05, this.ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + 0.08);
    osc.connect(gain);
    gain.connect(this.ctx.destination);
    osc.start();
    osc.stop(this.ctx.currentTime + 0.08);
  }

  startDrone() {
    if (!this.ctx) return;
    try {
      this.droneOsc = this.ctx.createOscillator();
      this.droneGain = this.ctx.createGain();
      this.droneOsc.type = 'sawtooth';
      this.droneOsc.frequency.setValueAtTime(45, this.ctx.currentTime);

      const filter = this.ctx.createBiquadFilter();
      filter.type = 'lowpass';
      filter.frequency.setValueAtTime(90, this.ctx.currentTime);

      this.droneGain.gain.setValueAtTime(0.02, this.ctx.currentTime);

      this.droneOsc.connect(filter);
      filter.connect(this.droneGain);
      this.droneGain.connect(this.ctx.destination);
      this.droneOsc.start();
    } catch (e) {}
  }

  stopDrone() {
    try {
      if (this.droneOsc) {
        this.droneOsc.stop();
        this.droneOsc.disconnect();
        this.droneOsc = null;
      }
    } catch(e) {}
  }

  playPulseClick(isOpen) {
    if (!this.ctx) return;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = 'triangle';
    osc.frequency.setValueAtTime(isOpen ? 350 : 250, this.ctx.currentTime);
    gain.gain.setValueAtTime(0.02, this.ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + 0.04);
    osc.connect(gain);
    gain.connect(this.ctx.destination);
    osc.start();
    osc.stop(this.ctx.currentTime + 0.04);
  }

  playHeartbeat(rateMs) {
    if (!this.ctx) return;
    this.stopHeartbeat();
    this.heartbeatInterval = setInterval(() => {
      if (!this.ctx) return;
      // Double thump
      const t = this.ctx.currentTime;
      this.thump(t, 60, 0.15);
      this.thump(t + 0.15, 50, 0.12);
    }, rateMs);
  }

  stopHeartbeat() {
    if (this.heartbeatInterval) {
      clearInterval(this.heartbeatInterval);
      this.heartbeatInterval = null;
    }
  }

  thump(time, freq, volume) {
    try {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(freq, time);
      osc.frequency.exponentialRampToValueAtTime(10, time + 0.12);
      gain.gain.setValueAtTime(volume, time);
      gain.gain.exponentialRampToValueAtTime(0.001, time + 0.12);
      osc.connect(gain);
      gain.connect(this.ctx.destination);
      osc.start(time);
      osc.stop(time + 0.15);
    } catch(e) {}
  }

  playTransferOutcome(success) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    if (success) {
      const osc1 = this.ctx.createOscillator();
      const osc2 = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc1.frequency.setValueAtTime(220, t);
      osc1.frequency.exponentialRampToValueAtTime(440, t + 0.3);
      osc2.frequency.setValueAtTime(330, t);
      osc2.frequency.exponentialRampToValueAtTime(660, t + 0.3);
      gain.gain.setValueAtTime(0.08, t);
      gain.gain.exponentialRampToValueAtTime(0.001, t + 0.35);
      osc1.connect(gain);
      osc2.connect(gain);
      gain.connect(this.ctx.destination);
      osc1.start();
      osc2.start();
      osc1.stop(t + 0.35);
      osc2.stop(t + 0.35);
    } else {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(110, t);
      osc.frequency.linearRampToValueAtTime(55, t + 0.4);
      gain.gain.setValueAtTime(0.12, t);
      gain.gain.exponentialRampToValueAtTime(0.001, t + 0.4);
      osc.connect(gain);
      gain.connect(this.ctx.destination);
      osc.start();
      osc.stop(t + 0.4);
    }
  }
}

const audio = new AudioEngine();

export default function App() {
  const [soundEnabled, setSoundEnabled] = useState(true);
  const [crtEnabled, setCrtEnabled] = useState(true);

  // Substances list
  const substances = {
    cigs: { name: 'Cigarettes Pack', icon: '🚬', label: 'Cigs', rhythm: 800, weightReq: 40 },
    weed: { name: 'Wrapped Weed', icon: '🌿', label: 'Weed', rhythm: 1200, weightReq: 60 },
    booze: { name: 'Flask of Alcohol', icon: '🍺', label: 'Flask', rhythm: 1800, weightReq: 50 },
    crystals: { name: 'Shard Foil', icon: '💎', label: 'Crystals', rhythm: 2500, weightReq: 80 }
  };

  const [activeSubstance, setActiveSubstance] = useState('cigs');

  // Dave's preference profiles
  const [daveStance, setDaveStance] = useState('craving'); // 'craving' | 'neutral' | 'reluctant'

  // Handover state machine
  // States: 'READY' (waiting for placement) | 'PLACED' (placed on table) | 'HOLDING' (moral hold active) | 'RESOLVED'
  const [gameState, setGameState] = useState('READY');
  const [placement, setPlacement] = useState({ x: 50, y: 50 }); // percentages
  const [moralWeight, setMoralWeight] = useState(0); // 0 to 100
  const [handOpen, setHandOpen] = useState(false); // Evolving hand rhythm state
  const [resolution, setResolution] = useState(null); // 'SUCCESS' | 'FUMBLE' | 'REFUSED'
  const [escalation, setEscalation] = useState('low'); // 'low' | 'high' | 'critical'

  // Logging & compliance metrics for feedback
  const [compliance, setCompliance] = useState(35);
  const [gameLogs, setGameLogs] = useState([
    'SYSTEM READY: Double-click or tap concrete surface to place the substance.'
  ]);

  // Audio Context lock release helper
  const enableAudio = () => {
    if (soundEnabled) {
      audio.init();
      audio.playClick();
    }
  };

  // Pulse Timer loop
  useEffect(() => {
    let interval;
    const rate = substances[activeSubstance].rhythm * (daveStance === 'craving' ? 0.7 : daveStance === 'reluctant' ? 1.4 : 1);

    interval = setInterval(() => {
      setHandOpen(prev => {
        const nextState = !prev;
        if (soundEnabled && gameState !== 'RESOLVED') {
          audio.playPulseClick(nextState);
        }
        return nextState;
      });
    }, rate);

    return () => clearInterval(interval);
  }, [activeSubstance, daveStance, soundEnabled, gameState]);

  // Hold Timer logic
  const holdTimer = useRef(null);
  useEffect(() => {
    if (gameState === 'HOLDING') {
      if (soundEnabled) {
        audio.init();
        audio.playHeartbeat(450 - (moralWeight * 3));
      }
      holdTimer.current = setInterval(() => {
        setMoralWeight(prev => {
          if (prev >= 100) {
            clearInterval(holdTimer.current);
            return 100;
          }
          return prev + 2.5;
        });
      }, 50);
    } else {
      if (soundEnabled) {
        audio.stopHeartbeat();
      }
      clearInterval(holdTimer.current);
    }
    return () => clearInterval(holdTimer.current);
  }, [gameState, moralWeight, soundEnabled]);

  // Placement validation & dynamic territory calculation
  const getPlacementTerritory = (y) => {
    if (y < 35) return { label: 'Desperate Offering (Close to Crew)', affinityBonus: -15, risk: 'low', desc: 'Dave grabs fast. You look fragile and desperate. Barely shifts compliance.' };
    if (y > 65) return { label: 'Power Play (Close to Manager)', affinityBonus: 25, risk: 'high', desc: 'Making him reach for it. High risk: if Dave is reluctant, he may refuse outright. High compliance reward.' };
    return { label: 'Neutral Transaction (Dead Centre)', affinityBonus: 5, risk: 'medium', desc: 'Balanced handoff. Standard compliance gain.' };
  };

  const territory = getPlacementTerritory(placement.y);

  // Handle table top-down click/placement
  const handleTableClick = (e) => {
    if (gameState !== 'READY') return;
    enableAudio();

    const rect = e.currentTarget.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width) * 100;
    const y = ((e.clientY - rect.top) / rect.height) * 100;

    setPlacement({ x, y });
    setGameState('PLACED');
    setGameLogs(prev => [
      `SUBSTANCE POSITIONED: ${substances[activeSubstance].name} placed on concrete. Territory: ${getPlacementTerritory(y).label}.`,
      ...prev
    ]);
  };

  // Hold down interaction handlers
  const handleHoldStart = () => {
    if (gameState !== 'PLACED') return;
    enableAudio();
    if (soundEnabled) audio.startDrone();
    setGameState('HOLDING');
  };

  const handleHoldEnd = () => {
    if (gameState !== 'HOLDING') return;
    if (soundEnabled) audio.stopDrone();

    const requiredWeight = substances[activeSubstance].weightReq;

    // Check if the holding weight target met
    if (moralWeight < requiredWeight) {
      setGameState('PLACED');
      setMoralWeight(0);
      setGameLogs(prev => ['HESTTATION: You withdrew your hand too early. Moral gravity not resolved.', ...prev]);
      if (soundEnabled) audio.playTransferOutcome(false);
      return;
    }

    // Determine timing outcome (Rhythm check)
