'use client'

import { useEffect, useRef, useCallback } from 'react'

// Global counter shared across all windows
let globalSteamCount = 0
const MAX_STEAM = 2

interface SteamSystemProps {
  containerRef: React.RefObject<HTMLDivElement | null>
  paused?: boolean
}

export function useSteamSystem({ containerRef, paused }: SteamSystemProps) {
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const visibleRef = useRef(false)
  const reducedMotion = useRef(false)

  useEffect(() => {
    if (typeof window !== 'undefined') {
      reducedMotion.current = window?.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches ?? false
    }
  }, [])

  const spawnParticle = useCallback(() => {
    if (reducedMotion?.current) return
    if (globalSteamCount >= MAX_STEAM) return
    if (visibleRef?.current) return
    const container = containerRef?.current
    if (!container) return

    globalSteamCount++
    visibleRef.current = true

    const particle = document.createElement('div')
    particle.className = 'steam-particle'
    const w = 40 + Math.random() * 40
    const h = 60 + Math.random() * 60
    const duration = 2000 + Math.random() * 2000

    // Pick a random corner
    const corners = [
      { left: '5%', bottom: '5%' },
      { right: '5%', bottom: '5%' },
      { left: '5%', top: '60%' },
      { right: '5%', top: '60%' },
    ]
    const corner = corners[Math.floor(Math.random() * corners?.length)] ?? corners?.[0] ?? {}

    Object.assign(particle.style, {
      position: 'absolute',
      width: `${w}px`,
      height: `${h}px`,
      background: 'rgb(var(--bv-text-rgb) / 0.08)',
      filter: 'blur(12px)',
      borderRadius: '50%',
      pointerEvents: 'none',
      zIndex: '1',
      opacity: '0',
      animation: `steam-rise ${duration}ms ease-out forwards`,
      ...(corner ?? {}),
    })

    container?.appendChild?.(particle)

    setTimeout(() => {
      particle?.remove?.()
      globalSteamCount = Math.max(0, globalSteamCount - 1)
      visibleRef.current = false
    }, duration)
  }, [containerRef])

  const scheduleNext = useCallback(() => {
    const delay = 6000 + Math.random() * 12000
    timerRef.current = setTimeout(() => {
      if (!paused) {
        spawnParticle()
      }
      scheduleNext()
    }, delay)
  }, [paused, spawnParticle])

  useEffect(() => {
    scheduleNext()
    return () => {
      if (timerRef?.current) clearTimeout(timerRef.current)
    }
  }, [scheduleNext])

  // Pause on tab hidden
  useEffect(() => {
    const handler = () => {
      if (document?.visibilityState === 'hidden' && timerRef?.current) {
        clearTimeout(timerRef.current)
      } else if (document?.visibilityState === 'visible') {
        scheduleNext()
      }
    }
    document?.addEventListener?.('visibilitychange', handler)
    return () => document?.removeEventListener?.('visibilitychange', handler)
  }, [scheduleNext])
}
